import hashlib
import hmac
import json
import os
from collections.abc import Mapping

def generate_policy(grants: dict[str, list[str]], config: dict[str, str] | None=None) -> str:
    if not isinstance(grants, dict):
        raise ValueError('grants must be a dictionary')
    statements = []
    for resource, actions in grants.items():
        if not isinstance(resource, str) or not resource:
            raise ValueError('invalid resource')
        if not isinstance(actions, list) or not actions:
            raise ValueError('invalid actions')
        if any((not isinstance(action, str) or not action for action in actions)):
            raise ValueError('invalid action')
        statements.append({'Actions': sorted(set(actions)), 'Resource': resource})
    statements.sort(key=lambda item: item['Resource'])
    document = {'Version': '2024-01-01', 'Statements': statements}
    if config is not None and 'POLICY_SIGNING_KEY' in config:
        key = config['POLICY_SIGNING_KEY']
    else:
        key = os.environ.get('POLICY_SIGNING_KEY')
    if not key:
        raise ValueError('missing POLICY_SIGNING_KEY')
    canonical = json.dumps(document, sort_keys=True, separators=(',', ':'))
    signature = hmac.new(key.encode('utf-8'), canonical.encode('utf-8'), hashlib.sha256).hexdigest()
    return json.dumps({'Document': document, 'Signature': signature}, sort_keys=True, separators=(',', ':'))

