from solution import parse_capacity_feed, summarize_capacity, reserve_beds
import pytest

def test_parse_feed_sorts_and_preserves_fields():
    text = 'shelter_id,timestamp,available,occupied,status\nB,2025-01-01T11:00:00Z,4,6,limited\nA,2025-01-01T10:00:00+00:00,8,2,open\n'
    assert parse_capacity_feed(text) == [{'shelter_id': 'A', 'timestamp': '2025-01-01T10:00:00+00:00', 'available': 8, 'occupied': 2, 'status': 'open'}, {'shelter_id': 'B', 'timestamp': '2025-01-01T11:00:00Z', 'available': 4, 'occupied': 6, 'status': 'limited'}]

def test_parse_feed_handles_quoted_identifiers_and_exact_columns():
    text = 'shelter_id,timestamp,available,occupied,status\n"North, Annex",2025-01-01T00:00:00Z,3,1,open\n'
    assert parse_capacity_feed(text)[0]['shelter_id'] == 'North, Annex'
    with pytest.raises(ValueError):
        parse_capacity_feed('shelter_id,timestamp,available,occupied,status\nA,2025-01-01T00:00:00Z,1,2,open,extra\n')

def test_summary_uses_latest_record_and_window():
    records = parse_capacity_feed('shelter_id,timestamp,available,occupied,status\nA,2025-01-01T09:00:00Z,9,1,open\nA,2025-01-01T10:00:00Z,5,5,limited\nB,2025-01-01T08:00:00Z,2,8,closed\n')
    assert summarize_capacity(records, '2025-01-01T10:30:00Z', 90) == [{'shelter_id': 'A', 'available': 5, 'occupied': 5, 'status': 'limited', 'timestamp': '2025-01-01T10:00:00Z'}]

def test_summary_sort_ties_and_empty_window():
    records = parse_capacity_feed('shelter_id,timestamp,available,occupied,status\nC,2025-01-01T12:00:00Z,2,1,closed\nA,2025-01-01T12:00:00Z,2,1,open\nB,2025-01-01T12:00:00Z,2,1,limited\n')
    result = summarize_capacity(records, '2025-01-01T12:01:00Z', 10)
    assert [x['shelter_id'] for x in result] == ['A', 'B', 'C']
    assert summarize_capacity(records, '2025-01-01T12:01:00Z', 0) == []

def test_reserve_authorized_request_updates_capacity():
    shelters = [{'id': 's1', 'tenant': 'east', 'manager_id': 'u1', 'capacity': 5, 'reservations': []}]
    requester = {'id': 'u1', 'tenant': 'east', 'roles': []}
    assert reserve_beds(requester, shelters, 's1', 'b7', 2) == {'booking_id': 'b7', 'requester_id': 'u1', 'shelter_id': 's1', 'count': 2}
    assert shelters[0]['capacity'] == 3
    assert reserve_beds(requester, shelters, 's1', 'b7', 9) == {'booking_id': 'b7', 'requester_id': 'u1', 'shelter_id': 's1', 'count': 2}

def test_reserve_validation_and_capacity_errors():
    shelters = [{'id': 's1', 'tenant': 'east', 'manager_id': 'u1', 'capacity': 2, 'reservations': []}]
    user = {'id': 'u1', 'tenant': 'east', 'roles': []}
    with pytest.raises(KeyError):
        reserve_beds(user, shelters, 'missing', 'b', 1)
    with pytest.raises(ValueError):
        reserve_beds(user, shelters, 's1', 'b', 0)
    with pytest.raises(ValueError):
        reserve_beds(user, shelters, 's1', 'b', 3)

