from lxml import etree

def optimize_battery_schedule(xml_text: str, capacity_kwh: float) -> dict:
    if capacity_kwh <= 0:
        raise ValueError('capacity must be positive')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'schedule':
        raise ValueError('invalid root')
    parsed = []
    for child in root:
        if child.tag != 'event':
            raise ValueError('invalid child')
        time = child.get('time')
        action = child.get('action')
        if not time or action not in ('charge', 'discharge'):
            raise ValueError('invalid event')
        try:
            kwh = float(child.get('kwh'))
            price = float(child.get('price'))
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid number') from exc
        if kwh <= 0 or kwh > capacity_kwh:
            raise ValueError('invalid quantity')
        parsed.append((time, action, kwh, price))
    parsed.sort(key=lambda item: item[0])
    events = []
    charge = 0.0
    discharge = 0.0
    total = 0.0
    for time, action, kwh, price in parsed:
        cost = kwh * price * (1 if action == 'charge' else -1)
        if action == 'charge':
            charge += kwh
        else:
            discharge += kwh
        total += cost
        events.append({'time': time, 'action': action, 'kwh': round(kwh, 2), 'price': round(price, 4), 'cost': round(cost, 2)})
    return {'events': events, 'charge_kwh': round(charge, 2), 'discharge_kwh': round(discharge, 2), 'net_cost': round(total, 2)}

