from solution import generate_enrollment_challenge


def test_generates_expected_record_shape_and_values():
    result = generate_enrollment_challenge("  api.example.com  ", 730)
    assert set(result) == {"certificate_name", "validity_days", "challenge", "status"}
    assert result["certificate_name"] == "api.example.com"
    assert result["validity_days"] == 730
    assert result["status"] == "pending"
    assert isinstance(result["challenge"], str)


def test_challenge_format_is_exact():
    alphabet = set("ABCDEFGHJKLMNPQRSTUVWXYZ23456789")
    result = generate_enrollment_challenge("service.example")
    assert len(result["challenge"]) == 24
    assert set(result["challenge"]) <= alphabet
    assert result["challenge"].isalnum()
    assert result["challenge"].upper() == result["challenge"]


def test_challenges_are_different_across_calls():
    values = {
        generate_enrollment_challenge("service.example")["challenge"]
        for _ in range(100)
    }
    assert len(values) == 100


def test_name_is_trimmed_but_other_text_is_preserved():
    result = generate_enrollment_challenge("  Client Name/42  ", 1)
