import ast
import operator

def _evaluate(rule, values):
    try:
        tree = ast.parse(rule, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError()
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                if isinstance(node.op, ast.UAdd):
                    return +value
                if isinstance(node.op, ast.USub):
                    return -value
                return not value
            if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                left = visit(node.left)
                right = visit(node.right)
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                result = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And):
                        if not result:
                            return result
                    elif result:
                        return result
                    result = visit(child)
                return result
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, child in zip(node.ops, node.comparators):
                    right = visit(child)
                    fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                    if fn is None or not fn(left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                args = [visit(x) for x in node.args]
                if node.func.id == 'min' and len(args) >= 2:
                    return min(*args)
                if node.func.id == 'max' and len(args) >= 2:
                    return max(*args)
                if node.func.id == 'round' and len(args) in (1, 2):
                    return round(*args)
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def select_hearings(hearings: list[dict], rule: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if type(offset) is not int or offset < 0 or (limit is not None and (type(limit) is not int or limit < 0)):
        raise ValueError()
    selected = []
    for hearing in hearings:
        values = {key: hearing[key] for key in ('case_id', 'courtroom', 'start_minute', 'duration', 'priority')}
        if _evaluate(rule, values):
            selected.append(hearing)
    selected.sort(key=lambda h: (-h['priority'], h['start_minute'], h['case_id']))
    end = None if limit is None else offset + limit
    return selected[offset:end]

