import hashlib
import hmac
import json
import math

def verify_and_summarize(document: str, signature: str, secret: str, page: int=1, page_size: int=10) -> dict:
    expected = hmac.new(secret.encode(), document.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        body = json.loads(document)
    except (TypeError, ValueError):
        raise ValueError('invalid document')
    if not isinstance(body, dict) or not isinstance(body.get('results'), list):
        raise ValueError('invalid results')
    groups = {}
    for row in body['results']:
        if not isinstance(row, dict):
            raise ValueError('invalid result')
        sample_id = row.get('sample_id')
        material = row.get('material')
        strength = row.get('strength_mpa')
        if not isinstance(sample_id, str) or not sample_id:
            raise ValueError('invalid sample')
        if not isinstance(material, str) or not material:
            raise ValueError('invalid material')
        if isinstance(strength, bool) or not isinstance(strength, (int, float)) or (not math.isfinite(strength)) or (strength < 0):
            raise ValueError('invalid strength')
        groups.setdefault(material, []).append(float(strength))
    summaries = []
    for material in sorted(groups):
        values = groups[material]
        summaries.append({'material': material, 'count': len(values), 'average_mpa': round(sum(values) / len(values), 2), 'min_mpa': round(min(values), 2), 'max_mpa': round(max(values), 2)})
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_materials': len(summaries), 'materials': summaries[start:start + page_size]}

