import base64
import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + ':' + base64.b64encode(digest).decode()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def plan_invalidation(records: list[dict], tag: str, minimum_age: int, credential: str, stored_credential: str, page: int=1, page_size: int=3) -> dict:
    if not verify_secret(credential, stored_credential):
        raise PermissionError('invalid credential')
    if not isinstance(records, list) or not isinstance(tag, str) or (not isinstance(minimum_age, int)) or isinstance(minimum_age, bool) or (minimum_age < 0):
        raise ValueError('invalid arguments')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    selected = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not all((key in record for key in ('url', 'tags', 'age_seconds', 'size_bytes', 'priority'))):
