import math
import os
import subprocess

def rank_certification_records(path: str, limit: int=10, minimum_score: float=0.0) -> list[tuple[str, str, float]]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a nonnegative integer')
    if isinstance(minimum_score, bool) or not isinstance(minimum_score, (int, float)):
        raise ValueError('minimum_score must be numeric')
    minimum_score = float(minimum_score)
    if not math.isfinite(minimum_score) or not 0 <= minimum_score <= 100:
        raise ValueError('minimum_score out of range')
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    completed = subprocess.run(['sort', '-t,', '-k3,3nr', '-k1,1', '-k2,2', path], check=True, capture_output=True, text=True)
    result = []
    for raw in completed.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('invalid record')
        name, certification, raw_score = (field.strip() for field in fields)
        if not name or not certification:
            raise ValueError('invalid record')
        try:
            score = float(raw_score)
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError('invalid score')
        if score >= minimum_score and len(result) < limit:
            result.append((name, certification, score))
    return result

