import hmac
import os

def _encode(access_code: str) -> str:
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def _valid_answers(answers):
    if not isinstance(answers, dict) or not answers:
        return False
    return all((isinstance(k, str) and k and isinstance(v, int) and (not isinstance(v, bool)) and (0 <= v <= 5) for k, v in answers.items()))

def make_response(answers: dict[str, int], access_code: str) -> dict:
    if not _valid_answers(answers) or not isinstance(access_code, str) or (not access_code):
        raise ValueError('invalid response')
    return {'answers': dict(answers), 'access_code': _encode(access_code)}

def check_response(record: dict, access_code: str) -> bool:
    if not isinstance(record, dict) or not isinstance(access_code, str) or (not access_code):
        return False
    if not _valid_answers(record.get('answers')):
        return False
    stored = record.get('access_code')
    if not isinstance(stored, str) or ':' not in stored:
        return False
    try:
        salt_hex, value_hex = stored.split(':', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(value_hex)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

