        raise PermissionError('invalid operator credentials')
    for machine, capacity in machine_capacity.items():
        if not isinstance(machine, str) or isinstance(capacity, bool) or (not isinstance(capacity, int)) or (capacity <= 0):
            raise ValueError('invalid machine capacity')
