import io
import re
import subprocess

def parse_service_requests(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    while rows and (not any(rows[-1])):
        rows.pop()
    header = ['id', 'date', 'start', 'duration', 'service', 'priority']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    ids = set()
    for row in rows[1:]:
        if not any(row):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        ident, date, start, duration, service, priority = row
        if not ident or not service or ident in ids:
            raise ValueError('invalid id or service')
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date):
            raise ValueError('invalid date')
        if not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d', start):
            raise ValueError('invalid time')
        try:
            duration = int(duration)
            priority = int(priority)
        except ValueError:
            raise ValueError('invalid number')
        if duration <= 0 or priority < 0:
            raise ValueError('invalid number')
        ids.add(ident)
        result.append({'id': ident, 'date': date, 'start': start, 'duration': duration, 'service': service, 'priority': priority})
    return result

def schedule_services(requests: list[dict], rooms: list[str]) -> list[dict]:
    if not rooms or len(set(rooms)) != len(rooms):
        raise ValueError('invalid rooms')
    required = {'id', 'date', 'start', 'duration', 'service', 'priority'}
    seen = set()
    items = []
    for item in requests:
        if set(item) != required or item['id'] in seen or item['priority'] < 0:
            raise ValueError('invalid request')
        seen.add(item['id'])
        try:
            h, m = map(int, item['start'].split(':'))
            if h < 0 or h > 23 or m < 0 or (m > 59) or (item['duration'] <= 0):
                raise ValueError
        except (ValueError, TypeError):
            raise ValueError('invalid request')
        start = h * 60 + m
        end = start + item['duration']
        if end > 1440:
            raise ValueError('past midnight')
        items.append((item['date'], start, -item['priority'], item['id'], item, end))
    items.sort(key=lambda x: x[:4])
    free = {room: {} for room in rooms}
    output = []
    for date, start, _, _, item, end in items:
        chosen = None
        for room in rooms:
            if free[room].get(date, 0) <= start:
                chosen = room
                break
        if chosen is None:
            raise ValueError('no room')
        free[chosen][date] = end
        output.append({'id': item['id'], 'date': date, 'start': item['start'], 'end': f'{end // 60:02d}:{end % 60:02d}', 'duration': item['duration'], 'service': item['service'], 'priority': item['priority'], 'room': chosen})
    return output

def sorted_report_lines(path: str, reverse: bool=False) -> list[str]:
    args = ['sort']
    if reverse:
        args.append('-r')
    args.append(path)
    result = subprocess.run(args, check=True, capture_output=True, text=True)
    return result.stdout.splitlines()

