    return {'function': _text(frame['function']), 'file': _text(frame['file']), 'line': frame['line']}

def aggregate_crashes(reports: list[dict], window_seconds: int=300) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0:
        raise ValueError('window')
