        key = (math.floor(timestamp / window_seconds) * window_seconds, platform, exception, frame['function'])
        groups[key] = groups.get(key, 0) + 1
    rows = [{'window_start': k[0], 'platform': k[1], 'exception': k[2], 'top_frame': k[3], 'count': n, 'upload_code': generate_upload_code()} for k, n in groups.items()]
