import secrets
import string

def generate_invite_code(length: int=12) -> str:
    if length < 4 or length > 64:
        raise ValueError('invalid length')
    alphabet = string.ascii_uppercase + string.digits
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def _split_fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == ';':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def _clock(value):
    parts = value.split(':')
    if len(parts) != 2 or not all((x.isdigit() for x in parts)):
        raise ValueError('bad time')
    hour, minute = map(int, parts)
    if hour > 23 or minute > 59:
        raise ValueError('bad time')
    return hour * 60 + minute

def parse_stop_records(text: str) -> list[dict]:
    result, seen = ([], set())
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_fields(raw)
        if len(fields) != 6 or any((not x for x in fields)):
            raise ValueError('bad record')
        ident, destination, demand, priority, window, distance = fields
        if ident in seen:
            raise ValueError('duplicate id')
        try:
            demand, priority, distance = (int(demand), int(priority), int(distance))
            pair = window.split('-')
            if len(pair) != 2:
                raise ValueError
            start, end = (_clock(pair[0]), _clock(pair[1]))
        except (TypeError, ValueError):
            raise ValueError('bad record')
        if demand <= 0 or distance <= 0 or (not 0 <= priority <= 9) or (end <= start):
            raise ValueError('bad record')
        seen.add(ident)
        result.append({'id': ident, 'destination': destination, 'demand': demand, 'priority': priority, 'window_start': start, 'window_end': end, 'distance': distance})
    return result

def plan_routes(records: list[dict], capacity: int, vehicles: int) -> list[dict]:
    if capacity <= 0 or vehicles <= 0:
        raise ValueError('bad fleet')
    ordered = sorted(records, key=lambda r: (-r['priority'], r['window_start'], -r['demand'], r['id']))
    routes = []
    for record in ordered:
        if record['demand'] > capacity:
            raise ValueError('oversize')
        chosen = None
        for route in routes:
            if route['total_demand'] + record['demand'] <= capacity:
                chosen = route
                break
        if chosen is None:
            if len(routes) == vehicles:
                raise ValueError('fleet exceeded')
            chosen = {'vehicle': len(routes) + 1, 'stops': [], 'total_demand': 0, 'total_distance': 0}
            routes.append(chosen)
        chosen['stops'].append(record['id'])
        chosen['total_demand'] += record['demand']
        chosen['total_distance'] += record['distance']
    return routes

