import csv
import datetime
import io
import subprocess

def read_inventory(paths: list[str]) -> list[dict]:
    result = []
    seen = set()
    expected = ['sku', 'warehouse', 'quantity', 'expires']
    for path in paths:
        try:
            completed = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
        except (OSError, subprocess.CalledProcessError):
            raise ValueError('unable to read inventory file')
        try:
            rows = list(csv.reader(io.StringIO(completed.stdout)))
            if not rows:
                continue
            if rows[0] != expected:
                raise ValueError('invalid header')
            for row in rows[1:]:
                if len(row) != 4:
                    raise ValueError('invalid row')
                sku, warehouse, quantity, expires = [x.strip() for x in row]
                if not sku or not warehouse or sku in seen:
                    raise ValueError('invalid sku')
                if not quantity.isdigit():
                    raise ValueError('invalid quantity')
                value = int(quantity)
                date = datetime.date.fromisoformat(expires)
                seen.add(sku)
                result.append({'sku': sku, 'warehouse': warehouse, 'quantity': value, 'expires': date})
        except (ValueError, OverflowError):
            raise ValueError('invalid inventory file')
    return result

def expiration_report(paths: list[str], as_of: str, window_days: int) -> dict:
    try:
        start = datetime.date.fromisoformat(as_of)
    except (ValueError, TypeError):
        raise ValueError('invalid date')
    if not isinstance(window_days, int) or isinstance(window_days, bool) or (not 0 <= window_days <= 365):
        raise ValueError('invalid window')
    records = read_inventory(paths)
    end = start + datetime.timedelta(days=window_days)
    expired = [r for r in records if r['expires'] < start]
    expiring = [r for r in records if start <= r['expires'] <= end]
    expired.sort(key=lambda r: (r['expires'], r['sku']))
    expiring.sort(key=lambda r: ((r['expires'] - start).days, r['sku']))
    totals = {}
