import hashlib
import hmac
import os
from datetime import date

def create_user(user_id: str, password: str) -> dict:
    if not isinstance(user_id, str) or not isinstance(password, str):
        raise TypeError()
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'user_id': user_id, 'credential': salt.hex() + '$' + digest.hex()}

def check_password(user: dict, password: str) -> bool:
    if not isinstance(password, str):
        raise TypeError()
    credential = user.get('credential') if isinstance(user, dict) else None
    if not isinstance(credential, str) or '$' not in credential:
        return False
    try:
        salt_text, digest_text = credential.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
