def parse_inspection_records(text: str) -> list[dict]:
    if not text.strip():
        return []
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError('malformed CSV') from exc
    while rows and (not any((field.strip() for field in rows[0]))):
        rows.pop(0)
    if not rows or rows[0] != ['timestamp', 'station', 'metric', 'value', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if not any((field.strip() for field in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid field count')
        timestamp, station, metric, value, status = row
        try:
            datetime.fromisoformat(timestamp[:-1] + '+00:00') if timestamp.endswith('Z') else (_ for _ in ()).throw(ValueError())
            number = float(value.strip())
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not station.strip() or not metric.strip() or (not math.isfinite(number)):
            raise ValueError('invalid record')
        status = status.strip()
        if status not in ('pass', 'fail'):
            raise ValueError('invalid record')
        result.append({'timestamp': timestamp, 'station': station.strip(), 'metric': metric.strip(), 'value': number, 'status': status})
    return result

def summarize_inspections(records: list[dict], window: int=3) -> list[dict]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('invalid window')
    groups = {}
    for record in records:
        try:
            station, metric = (record['station'], record['metric'])
            value, status, timestamp = (float(record['value']), record['status'], record['timestamp'])
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid record')
        if not station or not metric or status not in ('pass', 'fail') or (not math.isfinite(value)):
            raise ValueError('invalid record')
        groups.setdefault((station, metric), []).append((timestamp, value, status))
    output = []
    for (station, metric), items in sorted(groups.items()):
        chosen = sorted(items, key=lambda item: item[0])[-window:]
        values = [item[1] for item in chosen]
        output.append({'station': station, 'metric': metric, 'count': len(chosen), 'average': round(sum(values) / len(values), 3), 'minimum': round(min(values), 3), 'maximum': round(max(values), 3), 'failures': sum((item[2] == 'fail' for item in chosen)), 'latest_status': chosen[-1][2]})
    return output

def extract_inspection_member(base_dir: str, archive_path: str, member_name: str) -> str:
    base = Path(base_dir).resolve()
    target = (base / member_name).resolve()
    if os.path.commonpath((str(base), str(target))) != str(base):
        raise ValueError('invalid member path')
    with zipfile.ZipFile(archive_path) as archive:
        info = archive.getinfo(member_name)
        if info.is_dir():
            raise ValueError('directory member')
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(archive.read(info))
    return str(target)

