import json
import os
from datetime import date

def _path(base_dir, relative_name):
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, candidate]) != base:
        raise ValueError('path outside base')
    return candidate

def _day(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _validate(plan):
    if not isinstance(plan, dict) or not isinstance(plan.get('youth_id'), str) or (not plan['youth_id']) or (not isinstance(plan.get('services'), list)):
        raise ValueError('invalid plan')
    for service in plan['services']:
        if not isinstance(service, dict) or not isinstance(service.get('name'), str) or (not service['name']):
            raise ValueError('invalid service')
        start, end = (_day(service.get('start')), _day(service.get('end')))
        if end < start or service.get('status') not in {'planned', 'active', 'completed'}:
            raise ValueError('invalid service')
        hours = service.get('hours')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
            raise ValueError('invalid hours')
    return plan

def write_plan(base_dir: str, relative_name: str, plan: dict) -> None:
    _validate(plan)
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as handle:
        json.dump(plan, handle, indent=2, sort_keys=True)
        handle.write('\n')

def read_plan(base_dir: str, relative_name: str) -> dict:
    path = _path(base_dir, relative_name)
    try:
        with open(path, encoding='utf-8') as handle:
            value = json.load(handle)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError('invalid json') from exc
    return _validate(value)

def summarize_plans(plans: list[dict], as_of: str) -> list[dict]:
    target = _day(as_of)
    totals = {}
    people = {}
    for plan in plans:
        _validate(plan)
        for service in plan['services']:
            if _day(service['start']) <= target <= _day(service['end']):
                name = service['name']
                totals[name] = totals.get(name, 0) + service['hours']
                people.setdefault(name, set()).add(plan['youth_id'])
    result = [{'service': n, 'hours': round(totals[n], 2), 'youth_count': len(people[n])} for n in totals]
    return sorted(result, key=lambda item: (-item['hours'], item['service']))

