import hmac
import json

def scan_signed_report(payload: str, signature: str, secret: str, page: int=1, page_size: int=50) -> dict:
    try:
        supplied = bytes.fromhex(signature)
    except ValueError:
        raise PermissionError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    document = json.loads(payload)
    if not isinstance(document, dict) or not isinstance(document.get('dependencies'), list):
        raise ValueError('invalid report')
    ranks = {'low': 1, 'medium': 2, 'high': 3, 'critical': 4}
    merged = {}
    for item in document['dependencies']:
        if not isinstance(item, dict):
            raise ValueError('invalid dependency')
        if not isinstance(item.get('name'), str) or not item['name']:
            raise ValueError('invalid dependency')
        if not isinstance(item.get('version'), str) or not isinstance(item.get('severity'), str) or item['severity'] not in ranks or (type(item.get('direct')) is not bool):
            raise ValueError('invalid dependency')
        key = (item['name'], item['version'])
        old = merged.get(key)
        if old is None or ranks[item['severity']] > ranks[old['severity']]:
            merged[key] = {'name': item['name'], 'version': item['version'], 'severity': item['severity'], 'direct': item['direct']}
        elif item['direct']:
            old['direct'] = True
    packages = list(merged.values())
    packages.sort(key=lambda x: (-ranks[x['severity']], x['name'], x['version']))
    counts = {x: 0 for x in ('critical', 'high', 'medium', 'low')}
    for item in packages:
        counts[item['severity']] += 1
    total = len(packages)
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'severity_counts': counts, 'risk_score': sum((ranks[x['severity']] for x in packages)), 'packages': packages[start:start + page_size]}

