import hmac
import json
import os

def build_assignment_manifest(records: list[dict], hearing_date: str, page: int=1, page_size: int=20) -> dict:
    try:
        datetime.date.fromisoformat(hearing_date)
    except Exception as exc:
        raise ValueError('invalid hearing date') from exc
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or not 1 <= page_size <= 100:
        raise ValueError('invalid page size')
    key = os.environ.get('COURT_ASSIGNMENT_SIGNING_KEY')
    if not key:
        raise RuntimeError('COURT_ASSIGNMENT_SIGNING_KEY is not configured')
    required = {'case_id', 'language', 'interpreter_id', 'date', 'start', 'duration_minutes', 'priority', 'status'}
    matching = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('malformed record')
        if record['date'] != hearing_date or record['status'] != 'confirmed':
            continue
        try:
            start = datetime.datetime.strptime(record['start'], '%H:%M')
        except Exception as exc:
            raise ValueError('invalid start time') from exc
        duration = record['duration_minutes']
        if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
            raise ValueError('invalid duration')
        if isinstance(record['priority'], bool) or not isinstance(record['priority'], int):
            raise ValueError('invalid priority')
        matching.append((record, start))
    matching.sort(key=lambda item: (-item[0]['priority'], item[1], item[0]['case_id']))
    offset = (page - 1) * page_size
    rows = []
    for record, start in matching[offset:offset + page_size]:
        end = (start + datetime.timedelta(minutes=record['duration_minutes'])).strftime('%H:%M')
        raw_id = f"{record['case_id']}|{hearing_date}|{record['interpreter_id']}".encode()
        assignment_id = hmac.new(key.encode(), raw_id, hashlib.sha256).hexdigest()
        rows.append({'case_id': record['case_id'], 'language': record['language'], 'interpreter_id': record['interpreter_id'], 'start': record['start'], 'end': end, 'assignment_id': assignment_id})
    result = {'date': hearing_date, 'total': len(matching), 'page': page, 'page_size': page_size, 'assignments': rows}
    payload = json.dumps(result, sort_keys=True, separators=(',', ':')).encode()
    result['signature'] = hmac.new(key.encode(), payload, hashlib.sha256).hexdigest()
    return result

