import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from io import StringIO
_FIELDS = ['awb', 'flight', 'country', 'pieces', 'weight_kg', 'declared_value', 'status', 'released_at']

def summarize_releases(manifest: str) -> list[dict[str, object]]:
    if not manifest:
        return []
    try:
        reader = csv.DictReader(StringIO(manifest))
        if reader.fieldnames is None or sorted(reader.fieldnames) != sorted(_FIELDS):
            raise ValueError
        groups = {}
        seen = set()
        for row in reader:
            if row is None or None in row:
                raise ValueError
            if any((v is None for v in row.values())):
                raise ValueError
            awb = row['awb'].strip()
            flight = row['flight'].strip()
            country = row['country'].strip()
            status = row['status'].strip()
            if not awb or not flight or (not country) or (status not in {'RELEASED', 'HOLD', 'REJECTED'}):
                raise ValueError
            pieces = int(row['pieces'].strip())
            weight = Decimal(row['weight_kg'].strip())
            value = Decimal(row['declared_value'].strip())
            if pieces <= 0 or weight < 0 or value < 0 or (value.as_tuple().exponent < -2):
                raise ValueError
            released_at = row['released_at'].strip()
            if status == 'RELEASED':
                date.fromisoformat(released_at)
                if len(released_at) != 10:
                    raise ValueError
                if awb in seen:
                    raise ValueError
                seen.add(awb)
                key = (released_at, country)
                g = groups.setdefault(key, [0, 0, Decimal('0'), Decimal('0')])
                g[0] += 1
                g[1] += pieces
                g[2] += weight
                g[3] += value
        result = []
        for (released_at, country), (count, pieces, weight, value) in sorted(groups.items()):
            result.append({'released_at': released_at, 'country': country, 'awb_count': count, 'total_pieces': pieces, 'total_weight_kg': float(weight.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'total_declared_value': format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')})
        return result
    except (ValueError, InvalidOperation, TypeError, OverflowError):
        raise ValueError

def write_release_report(manifest: str, output_path: str) -> int:
    rows = summarize_releases(manifest)
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.release-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(['released_at', 'country', 'awb_count', 'total_pieces', 'total_weight_kg', 'total_declared_value'])
            for row in rows:
                writer.writerow([row['released_at'], row['country'], row['awb_count'], row['total_pieces'], f"{row['total_weight_kg']:.2f}", row['total_declared_value']])
            f.flush()
            os.fsync(f.fileno())
        os.replace(temporary, output_path)
    except Exception:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(rows)

