import hashlib
import hmac
import json
import pytest


def make_body(applications):
    return json.dumps({"applications": applications}, separators=(",", ":")).encode()


def signed(body, secret=b"gallery-key"):
    return hmac.new(secret, body, hashlib.sha256).hexdigest()


def app(id, artist, region, status, score, amount):
    return {"id": id, "artist": artist, "region": region, "status": status, "score": score, "amount": amount}


def test_accepts_signature_and_filters_and_normalizes_fields():
    body = make_body([
        app("b", "Beta", "North", "submitted", 72, 1000),
        app("a", "Alpha", "South", "draft", 99, 200),
        app("c", "Gamma", "East", "submitted", 59.9, 300),
    ])
    result = verify_and_rank_applications(body, signed(body), b"gallery-key")
    assert result == {
        "applications": [{"id": "b", "artist": "Beta", "region": "North", "score": 72, "amount": 1000}],
        "total_count": 1, "total_amount": 1000, "page": 1, "page_size": 10, "total_pages": 1
    }


def test_rejects_wrong_signature():
    body = make_body([])
    with pytest.raises(ValueError):
        verify_and_rank_applications(body, "0" * 64, b"gallery-key")


def test_sorting_ties_and_pagination():
    body = make_body([
        app("z", "Z", "R", "submitted", 80, 500),
        app("a", "A", "R", "submitted", 80, 500),
        app("b", "B", "R", "submitted", 80, 400),
        app("d", "D", "R", "submitted", 91, 100),
    ])
    result = verify_and_rank_applications(body, signed(body), b"gallery-key", 2, 2)
    assert [x["id"] for x in result["applications"]] == ["a", "z"]
    assert result["total_count"] == 4
    assert result["total_amount"] == 1500
    assert result["total_pages"] == 2
    assert result["page"] == 2 and result["page_size"] == 2


def test_empty_and_out_of_range_page():
    body = make_body([])
    result = verify_and_rank_applications(body, signed(body), b"gallery-key", 3, 4)
    assert result == {"applications": [], "total_count": 0, "total_amount": 0, "page": 3, "page_size": 4, "total_pages": 0}


def test_rounds_amount_total_and_boundary_score():
    body = make_body([
        app("x", "X", "R", "submitted", 60, 0.105),
        app("y", "Y", "R", "submitted", 60, 0.104),
    ])
    result = verify_and_rank_applications(body, signed(body), b"gallery-key")
    assert result["total_amount"] == 0.21
    assert [x["id"] for x in result["applications"]] == ["y", "x"]


