import ast

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise ValueError()
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_evaluate(node.left, values), _evaluate(node.right, values))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not result:
                    return result
            elif result:
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if not isinstance(op, (ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq)):
                raise ValueError()
            if isinstance(op, ast.Lt):
                good = left < right
            elif isinstance(op, ast.LtE):
                good = left <= right
            elif isinstance(op, ast.Gt):
                good = left > right
            elif isinstance(op, ast.GtE):
                good = left >= right
            elif isinstance(op, ast.Eq):
                good = left == right
            else:
                good = left != right
            if not good:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        args = [_evaluate(x, values) for x in node.args]
        if node.func.id == 'round' and len(args) in (1, 2):
            return round(*args)
        if node.func.id in {'min', 'max'} and len(args) in (1, 2):
            return min(args) if node.func.id == 'min' else max(args)
    raise ValueError()

def _expression(tree, values):
    try:
        result = _evaluate(tree, values)
    except Exception as exc:
        raise ValueError() from exc
    if not isinstance(result, bool):
        raise ValueError()
    return result

def attendance_report(records: list[dict], expression: str, page: int, page_size: int) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError()
    try:
        tree = ast.parse(expression, mode='eval').body
    except Exception as exc:
        raise ValueError() from exc
    selected = []
    for record in records:
        values = {'hours': record['hours'], 'late_minutes': record['late_minutes'], 'absent': record['absent'], 'overtime': record['overtime']}
        if _expression(tree, values):
            score = round(record['hours'] * 1.5 - record['late_minutes'] * 0.25 + record['overtime'] * 2, 2)
            selected.append({'name': record['name'], 'hours': record['hours'], 'late_minutes': record['late_minutes'], 'overtime': record['overtime'], 'score': score})
