import hmac
import os
from datetime import date, timedelta

def create_technician(name: str, pin: str, equipment: list[dict]) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(pin, str) or len(pin) != 4 or (not pin.isdecimal()):
        raise ValueError('invalid pin')
    clean = []
    ids = set()
    for item in equipment:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not item['id'].strip()):
            raise ValueError('invalid equipment')
        hours = item.get('hours')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
            raise ValueError('invalid hours')
        ident = item['id'].strip()
        if ident in ids:
            raise ValueError('duplicate equipment')
        ids.add(ident)
        clean.append({'id': ident, 'hours': hours})
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'name': name.strip(), 'credential': salt.hex() + ':' + digest.hex(), 'equipment': clean}

def verify_technician(record: dict, pin: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        salt_text, digest_text = record['credential'].split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def build_service_report(events: list[dict], as_of: str) -> list[dict]:
    try:
        end = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    start = end - timedelta(days=29)
    groups = {}
    for event in events:
        if not isinstance(event, dict) or not all((k in event for k in ('equipment', 'date', 'hours', 'action'))):
            raise ValueError('invalid event')
        if not isinstance(event['equipment'], str) or not event['equipment'] or (not isinstance(event['action'], str)) or (not event['action']):
            raise ValueError('invalid event')
        try:
            when = date.fromisoformat(event['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        hours = event['hours']
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0 or (when > end):
            raise ValueError('invalid event')
        if start <= when <= end:
            groups.setdefault(event['equipment'], []).append((when, event['action'], hours))
