        raise ValueError('page_size must be between 1 and 100')
    completed = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError('each call must be a dictionary')
        required = {'incident_id', 'station', 'priority', 'response_seconds', 'status'}
        if not required.issubset(call):
            raise ValueError('call is missing a required field')
        if not isinstance(call['incident_id'], str) or not call['incident_id']:
            raise ValueError('incident_id must be non-empty')
        if not isinstance(call['station'], str) or not call['station']:
            raise ValueError('station must be non-empty')
        if not isinstance(call['priority'], int) or isinstance(call['priority'], bool) or (not 1 <= call['priority'] <= 5):
            raise ValueError('priority is invalid')
        if not isinstance(call['response_seconds'], (int, float)) or isinstance(call['response_seconds'], bool) or call['response_seconds'] < 0:
            raise ValueError('response_seconds is invalid')
        if call['status'] not in {'completed', 'dispatched', 'cancelled'}:
            raise ValueError('status is invalid')
        if call['status'] == 'completed':
            completed.append(call)
    completed.sort(key=lambda x: (x['priority'], -x['response_seconds'], x['incident_id']))
    summaries = {}
    for call in completed:
        station = call['station']
        entry = summaries.setdefault(station, {'count': 0, 'total': 0})
        entry['count'] += 1
        entry['total'] += call['response_seconds']
    station_summary = {station: {'count': data['count'], 'average_response_seconds': round(data['total'] / data['count'], 2)} for station, data in sorted(summaries.items())}
    start = (page - 1) * page_size
    items = [{'incident_id': call['incident_id'], 'station': call['station'], 'priority': call['priority'], 'response_seconds': call['response_seconds']} for call in completed[start:start + page_size]]
    return {'headers': {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}, 'body': {'page': page, 'page_size': page_size, 'total': len(completed), 'items': items, 'station_summary': station_summary}}

