import string
from datetime import datetime, timezone, timedelta
_ALPHABET = string.ascii_uppercase + string.digits

def _email(value):
    value = value.strip().lower()
    if not value:
        raise ValueError('empty email')
    return value

def _tags(values):
    out = []
    seen = set()
    for value in values:
        value = value.strip().lower()
        if value and value not in seen:
            seen.add(value)
            out.append(value)
    return out

def _time(value):
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError('timezone required')
    return value

def _code():
    return ''.join((secrets.choice(_ALPHABET) for _ in range(8)))

def parse_subscription_feed(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 3:
            raise ValueError('bad row')
        raw_time = parts[2].strip()
        if raw_time.endswith('Z'):
            raw_time = raw_time[:-1] + '+00:00'
        try:
            joined = _time(datetime.fromisoformat(raw_time))
        except (TypeError, ValueError):
            raise ValueError('bad timestamp')
        result.append({'email': _email(parts[0]), 'tags': _tags(parts[1].split(',')), 'joined': joined})
    return result

class SubscriptionBook:

