        self._items = {}
        self._codes = {}

    def subscribe(self, email: str, tags: list[str], joined: datetime) -> str:
        joined = _time(joined)
        email = _email(email)
        old = self._items.get(email)
        if old:
            self._codes.pop(old['code'], None)
        code = _code()
        item = {'email': email, 'tags': _tags(tags), 'joined': joined, 'code': code, 'cancelled': None}
        self._items[email] = item
        self._codes[code] = item
        return code

