        when = _time(when)
        item = self._codes.get(code)
        if item is None or item['cancelled'] is not None:
            return False
        item['cancelled'] = when
        return True

    def active_summary(self, as_of: datetime, window_days: int=30) -> dict:
        as_of = _time(as_of)
        if isinstance(window_days, bool) or not isinstance(window_days, int) or window_days <= 0:
