from datetime import date

def build_dispatch_summary(requester: dict, shipments: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(shipments, list):
        raise TypeError('invalid arguments')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('invalid pagination')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    for key in ('id', 'tenant_id', 'role'):
        if not isinstance(requester.get(key), str):
            raise ValueError('invalid requester')
    allowed = {'planned', 'loaded', 'in_transit', 'delivered'}
    checked = []
    totals = {}
    for item in shipments:
        if not isinstance(item, dict):
            raise TypeError('invalid shipment')
        required = ('shipment_id', 'tenant_id', 'owner_id', 'scheduled_date', 'status', 'hazard_class', 'quantity_kg')
        if any((k not in item for k in required)):
            raise ValueError('missing shipment field')
        if not all((isinstance(item[k], str) for k in required[:-1])):
            raise TypeError('invalid shipment field')
        if item['status'] not in allowed or not item['hazard_class']:
            raise ValueError('invalid shipment value')
        try:
            date.fromisoformat(item['scheduled_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        quantity = item['quantity_kg']
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float, Decimal)):
            raise TypeError('invalid quantity')
        if quantity <= 0:
            raise ValueError('invalid quantity')
        if item['tenant_id'] != requester['tenant_id'] or (item['owner_id'] != requester['id'] and requester['role'] != 'dispatcher'):
            raise PermissionError('shipment access denied')
        checked.append(item)
        entry = totals.setdefault(item['hazard_class'], [0, Decimal('0')])
        entry[0] += 1
        entry[1] += Decimal(str(quantity))
    checked.sort(key=lambda x: (-date.fromisoformat(x['scheduled_date']).toordinal(), x['shipment_id']))
    start = (page - 1) * page_size
    hazard_totals = {k: {'shipment_count': totals[k][0], 'quantity_kg': float(totals[k][1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for k in sorted(totals)}
    return {'shipments': checked[start:start + page_size], 'page': page, 'page_size': page_size, 'total_shipments': len(checked), 'hazard_totals': hazard_totals}

