import json
import math

def encode_change_state(state: dict) -> bytes:
    return json.dumps(state, separators=(',', ':'), sort_keys=True).encode('utf-8')

def summarize_changes(payload: bytes, team: str | None=None, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        state = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(state, dict) or not isinstance(state.get('changes'), list):
        raise ValueError('invalid state')
    records = state['changes']
    selected = [r for r in records if isinstance(r, dict) and (team is None or r.get('team') == team) and (status is None or r.get('status') == status)]
    selected.sort(key=lambda r: (-r['priority'], -r['hours'], r['id']))
    count = len(selected)
    start = (page - 1) * page_size
    return {'count': count, 'total_hours': round(sum((r['hours'] for r in selected)), 2), 'page': page, 'pages': math.ceil(count / page_size) if count else 0, 'items': selected[start:start + page_size]}

