        if not isinstance(record['operator_id'], str) or not record['operator_id']:
            return False
        if record['role'] not in {'dispatcher', 'supervisor', 'mechanic'}:
            return False
        salt = bytes.fromhex(record['salt'])
        expected = bytes.fromhex(record['password_digest'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

