import os

def generate_release_notes(entries: list[dict], version: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')
    if not isinstance(version, str) or not version:
        raise ValueError('version must be non-empty')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    order = {'feature': 0, 'fix': 1, 'docs': 2}
    selected = []
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError('invalid entry')
        if set(entry) != {'category', 'title', 'author', 'minutes', 'approved'}:
            raise ValueError('invalid entry')
        category, title, author = (entry['category'], entry['title'], entry['author'])
        minutes, approved = (entry['minutes'], entry['approved'])
        if category not in order or not isinstance(title, str) or (not title) or (not isinstance(author, str)) or (not author):
            raise ValueError('invalid entry')
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0 or (not isinstance(approved, bool)):
            raise ValueError('invalid entry')
        if approved:
            selected.append((category, title, author, minutes))
    selected.sort(key=lambda x: (order[x[0]], x[1].casefold(), x[2].casefold()))
    total = len(selected)
    pages = (total + page_size - 1) // page_size if total else 0
    start, end = ((page - 1) * page_size, page * page_size)
    groups = []
    current = None
    for category, title, author, minutes in selected[start:end]:
        if current is None or current['category'] != category:
            current = {'category': category, 'items': []}
            groups.append(current)
        current['items'].append({'title': title, 'author': author, 'minutes': minutes})
    total_minutes = sum((x[3] for x in selected))
    average = round(total_minutes / total, 2) if total else 0.0
    return {'version': version, 'total': total, 'pages': pages, 'page': page, 'total_minutes': total_minutes, 'average_minutes': average, 'groups': groups}

def create_review_code(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    if not code:
        raise ValueError('code must be non-empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return base64.b64encode(salt).decode() + '$' + digest.hex()

def verify_review_code(code: str, record: str) -> bool:
    if not isinstance(code, str) or not code or (not isinstance(record, str)):
        return False
    try:
        salt_text, digest_text = record.split('$')
        salt = base64.b64decode(salt_text, validate=True)
        if len(salt) != 16 or len(digest_text) != 64:
            return False
        expected = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000).hex()
        return hmac.compare_digest(expected, digest_text)
    except (ValueError, TypeError):
        return False

