import base64
import datetime
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(value).decode()

def verify_password(stored: str, password: str) -> bool:
    if not isinstance(stored, str) or not isinstance(password, str) or (not password):
        return False
    try:
        kind, salt_text, value_text = stored.split('$')
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(value_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_client(name: str, password: str, plan: dict[str, int]) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(plan, dict) or not plan:
        raise ValueError('invalid plan')
    clean = {}
    for key, value in plan.items():
        if not isinstance(key, str) or not key.strip() or isinstance(value, bool) or (not isinstance(value, int)) or (value <= 0):
            raise ValueError('invalid plan')
        clean[key.strip()] = value
    if len(clean) != len(plan):
        raise ValueError('duplicate plan key')
    return {'name': name.strip(), 'credential': hash_password(password), 'plan': dict(sorted(clean.items()))}

def authenticate_client(client: dict, password: str) -> bool:
    return isinstance(client, dict) and isinstance(client.get('credential'), str) and verify_password(client['credential'], password)

def parse_workout_log(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('invalid log')
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = [x.strip() for x in line.split('|')]
        if len(fields) != 5:
            raise ValueError('invalid record')
        date, exercise, sets, reps, kilograms = fields
        try:
            day = datetime.date.fromisoformat(date)
            s, r = (int(sets), int(reps))
            kg = float(kilograms)
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if not exercise or s <= 0 or r <= 0 or (kg < 0) or (not kilograms):
            raise ValueError('invalid record')
        result.append({'date': day.isoformat(), 'exercise': exercise, 'sets': s, 'reps': r, 'kilograms': kg})
    return result

def weekly_progress(text: str, first_day: str, weeks: int) -> list[dict]:
    try:
        start = datetime.date.fromisoformat(first_day)
    except (ValueError, TypeError):
        raise ValueError('invalid date')
    if isinstance(weeks, bool) or not isinstance(weeks, int) or weeks <= 0:
        raise ValueError('invalid weeks')
    rows = parse_workout_log(text)
    output = []
    for index in range(weeks):
        begin = start + datetime.timedelta(days=index * 7)
        end = begin + datetime.timedelta(days=7)
        totals = {}
        volume = 0.0
        for row in rows:
            day = datetime.date.fromisoformat(row['date'])
            if begin <= day < end:
                amount = row['sets'] * row['reps'] * row['kilograms']
                volume += amount
                totals[row['exercise']] = totals.get(row['exercise'], 0.0) + amount
        best = min(totals, key=lambda x: (-totals[x], x)) if totals else None
        output.append({'start': begin.isoformat(), 'volume': round(volume, 2), 'best_exercise': best})
    return output

