from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP
import math

def aggregate_readings(readings: list[dict], window_minutes: int=15) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or (not 1 <= window_minutes <= 1440):
        raise ValueError('invalid window')
    groups = {}
    span = window_minutes * 60
    for r in readings:
        try:
            station = r['station_id']
            text = r['timestamp']
            pressure = r['pressure_kpa']
            flow = r['flow_m3h']
            status = r['status']
            if not isinstance(station, str) or not station or (not isinstance(status, str)):
                raise ValueError
            if not isinstance(text, str) or not text.endswith('Z'):
                raise ValueError
            dt = datetime.strptime(text, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            if isinstance(pressure, bool) or isinstance(flow, bool):
                raise ValueError
            pressure = float(pressure)
            flow = float(flow)
            if not math.isfinite(pressure) or not math.isfinite(flow) or pressure <= 0 or (flow <= 0):
                raise ValueError
        except (KeyError, TypeError, ValueError, OverflowError):
            raise ValueError('invalid reading')
        epoch = int(dt.timestamp())
        start = datetime.fromtimestamp(epoch // span * span, timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        g = groups.setdefault((station, start), [[], [], {}])
        g[0].append(pressure)
        g[1].append(flow)
        g[2][status] = g[2].get(status, 0) + 1
    out = []
    for (station, start), (pressures, flows, statuses) in sorted(groups.items()):
        avg = Decimal(str(sum(pressures) / len(pressures))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        out.append({'station_id': station, 'window_start': start, 'count': len(pressures), 'average_pressure_kpa': float(avg), 'minimum_flow_m3h': min(flows), 'maximum_flow_m3h': max(flows), 'statuses': dict(sorted(statuses.items()))})
    return out

def acknowledge_alert(alerts: list[dict], alert_id: str, requester: dict) -> dict:
    for alert in alerts:
        if alert.get('alert_id') == alert_id:
            result = dict(alert)
            if alert.get('acknowledged'):
                return result
            if not (requester.get('tenant_id') == alert.get('tenant_id') and (requester.get('user_id') == alert.get('owner_id') or 'supervisor' in requester.get('roles', []))):
                raise PermissionError('not permitted')
            result['acknowledged'] = True
            result['acknowledged_by'] = requester['user_id']
            return result
    raise KeyError(alert_id)

