import csv
import io
import os
import zipfile
from collections import defaultdict
from pathlib import Path

def parse_applications(text: str) -> list[dict]:
    if not text:
        return []
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        return []
    wanted = ['application_id', 'applicant', 'income', 'system_kw', 'requested_rebate', 'status']
    if header != wanted:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in reader:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 6:
            raise ValueError('invalid row')
        ident, applicant, income, kw, rebate, status = [x.strip() for x in row]
        if not ident or not applicant or ident in seen or (status not in {'pending', 'approved', 'denied'}):
            raise ValueError('invalid application')
        try:
            income, kw, rebate = (float(income), float(kw), float(rebate))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if income < 0 or kw < 0 or rebate < 0:
            raise ValueError('negative value')
        seen.add(ident)
        result.append({'application_id': ident, 'applicant': applicant, 'income': income, 'system_kw': kw, 'requested_rebate': rebate, 'status': status})
    return result

def summarize_rebates(records: list[dict]) -> list[dict]:
    groups = defaultdict(lambda: [0, 0.0, 0.0])
    for record in records:
        if record['status'] == 'approved':
            group = groups[record['applicant']]
            group[0] += 1
            group[1] += record['requested_rebate']
            group[2] += record['system_kw']
    result = [{'applicant': name, 'application_count': values[0], 'total_rebate': round(values[1], 2), 'average_system_kw': round(values[2] / values[0], 2)} for name, values in groups.items()]
    return sorted(result, key=lambda x: (-x['total_rebate'], -x['application_count'], x['applicant']))

def extract_rebate_package(base_dir: str, package_name: str, destination: str) -> list[str]:
    base = Path(base_dir).resolve()
    package = (base / package_name).resolve()
    if not package_name or not package.is_relative_to(base):
        raise ValueError('package outside base')
    target = (base / destination).resolve()
    if not target.is_relative_to(base):
        raise ValueError('destination outside base')
    if not package.is_file():
        raise FileNotFoundError(str(package))
    target.mkdir(parents=True, exist_ok=True)
    result = []
    with zipfile.ZipFile(package) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            member = Path(info.filename)
            output = (target / member).resolve()
            if not output.is_relative_to(target):
                raise ValueError('member outside destination')
            output.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(output, 'wb') as dest:
                dest.write(source.read())
            result.append(output.relative_to(target).as_posix())
    return sorted(result)

