        patient, analyte, value, unit, stamp, low, high = row
        patient, analyte, unit = (patient.strip(), analyte.strip(), unit.strip())
        if not patient or not analyte or (not unit):
            raise ValueError('empty field')
        try:
            nums = [float(x.strip()) for x in (value, low, high)]
            if not all((math.isfinite(x) for x in nums)):
                raise ValueError
            dt = datetime.datetime.fromisoformat(stamp.strip().replace('Z', '+00:00'))
            if dt.tzinfo is None or dt.utcoffset() is None:
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid value') from exc
        result.append({'patient_id': patient, 'analyte': analyte, 'value': nums[0], 'unit': unit, 'timestamp': dt.isoformat(), 'low': nums[1], 'high': nums[2]})
    return result

