    return io.StringIO(text)

def summarize_results(records: list[dict]) -> list[dict]:
    chosen = {}
    for record in records:
        key = (record['patient_id'], record['analyte'])
        current = chosen.get(key)
        stamp = datetime.datetime.fromisoformat(record['timestamp'])
        if current is None or stamp >= datetime.datetime.fromisoformat(current['timestamp']):
            chosen[key] = record
    answer = []
    for key in sorted(chosen):
        r = chosen[key]
        status = 'LOW' if r['value'] < r['low'] else 'HIGH' if r['value'] > r['high'] else 'NORMAL'
        answer.append({k: r[k] for k in ('patient_id', 'analyte', 'value', 'unit', 'timestamp')} | {'status': status})
    return answer

def export_report(records: list[dict], destination: str) -> int:
    summaries = summarize_results(records)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
