import hashlib
import os
from datetime import date

def hash_password(password: str) -> str:
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def create_staff(username: str, password: str) -> dict[str, str]:
    if not isinstance(username, str) or not username:
        raise ValueError('invalid username')
    return {'username': username, 'password_hash': hash_password(password)}

def authenticate(staff: dict[str, str], password: str) -> bool:
    if not isinstance(staff, dict) or not isinstance(staff.get('username'), str) or (not isinstance(staff.get('password_hash'), str)) or (not isinstance(password, str)) or (not password):
        return False
    try:
        salt, expected = staff['password_hash'].split('$', 1)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(salt), 100000).hex()
        return actual == expected
    except (ValueError, TypeError):
        return False

def plan_day(requests: list[dict], day: str, vet_order: list[str]) -> list[dict]:
    try:
        date.fromisoformat(day)
    except Exception:
        raise ValueError('invalid day')
    if not isinstance(vet_order, list) or any((not isinstance(v, str) or not v for v in vet_order)) or len(set(vet_order)) != len(vet_order):
        raise ValueError('invalid vets')
    seen = set()
    parsed = []
    for r in requests:
        if not isinstance(r, dict) or any((k not in r for k in ('id', 'date', 'vet', 'start', 'duration', 'species', 'priority'))):
            raise ValueError('invalid request')
        ident, rd, vet, start, dur, species, priority = (r[k] for k in ('id', 'date', 'vet', 'start', 'duration', 'species', 'priority'))
        if any((not isinstance(x, str) or not x for x in (ident, rd, vet, species))) or ident in seen or (not isinstance(dur, int)) or isinstance(dur, bool) or (not 1 <= dur <= 480) or (not isinstance(priority, int)) or isinstance(priority, bool) or (not 0 <= priority <= 9):
            raise ValueError('invalid request')
        seen.add(ident)
        try:
            date.fromisoformat(rd)
            if len(start) != 5 or start[2] != ':' or (not start[:2].isdigit()) or (not start[3:].isdigit()):
                raise ValueError
            hour, minute = (int(start[:2]), int(start[3:]))
            if hour > 23 or minute > 59:
                raise ValueError
        except Exception:
            raise ValueError('invalid time')
        begin = hour * 60 + minute
        end = begin + dur
        if end > 1440:
            raise ValueError('past midnight')
        parsed.append((ident, rd, vet, begin, end, species, priority))
    selected = [x for x in parsed if x[1] == day]
    selected.sort(key=lambda x: (x[3], -x[6], vet_order.index(x[2]) if x[2] in vet_order else len(vet_order), x[2] if x[2] not in vet_order else '', x[0]))
