    return [{'id': x[0], 'vet': x[2], 'date': x[1], 'start': f'{x[3] // 60:02d}:{x[3] % 60:02d}', 'end': '24:00' if x[4] == 1440 else f'{x[4] // 60:02d}:{x[4] % 60:02d}', 'species': x[5], 'priority': x[6]} for x in selected]

