from lxml import etree
import math

def parse_readings(xml_text: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'packet':
        raise ValueError('wrong root')
    result = []
    for node in root:
        if node.tag != 'reading':
            continue
        sensor = node.get('sensor')
        stamp = node.get('timestamp')
        pressure = node.find('pressure')
        temperature = node.find('temperature')
        if not sensor or stamp is None or pressure is None or (temperature is None):
            raise ValueError('invalid reading')
        try:
            timestamp = int(stamp)
            value = float(pressure.get('value'))
            if pressure.get('unit') == 'bar':
                value *= 100.0
            elif pressure.get('unit') != 'kPa':
                raise ValueError
            temp = float(temperature.get('value'))
            if temperature.get('unit') != 'C' or not math.isfinite(value) or (not math.isfinite(temp)):
                raise ValueError
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid reading') from exc
        result.append({'sensor': sensor, 'timestamp': timestamp, 'pressure_kpa': value, 'temperature_c': temp})
    return sorted(result, key=lambda x: (x['timestamp'], x['sensor']))

def analyze_pipeline(documents: list[str], window_size: int=3, limit: float=10.0) -> list[dict]:
    if not isinstance(window_size, int) or isinstance(window_size, bool) or window_size <= 0:
        raise ValueError('invalid window size')
    if not isinstance(limit, (int, float)) or isinstance(limit, bool) or (not math.isfinite(limit)) or (limit < 0):
        raise ValueError('invalid limit')
    groups = {}
    order = 0
    for document in documents:
        for reading in parse_readings(document):
            groups.setdefault(reading['sensor'], []).append((reading['timestamp'], order, reading['pressure_kpa']))
            order += 1
    alerts = []
    for sensor, rows in groups.items():
        rows.sort(key=lambda x: (x[0], x[1]))
        for i in range(len(rows) - window_size + 1):
            window = rows[i:i + window_size]
            values = [x[2] for x in window]
            low, high = (min(values), max(values))
            if high - low > limit:
                alerts.append({'sensor': sensor, 'start_timestamp': window[0][0], 'end_timestamp': window[-1][0], 'minimum_kpa': low, 'maximum_kpa': high, 'average_kpa': sum(values) / window_size})
    return sorted(alerts, key=lambda x: (x['end_timestamp'], x['sensor'], x['start_timestamp']))

