import datetime
import os
import subprocess

def parse_matter_line(line: str) -> dict:
    text = line.strip()
    if not text:
        raise ValueError('blank record')
    parts = text.split('|')
    if len(parts) != 4 or any((not x for x in parts)):
        raise ValueError('invalid record')
    matter_id, date, status, hours = parts
    try:
        datetime.date.fromisoformat(date)
        value = float(hours)
    except ValueError as exc:
        raise ValueError('invalid record') from exc
    if status not in {'OPEN', 'PENDING', 'CLOSED'} or value < 0:
        raise ValueError('invalid record')
    return {'matter_id': matter_id, 'date': date, 'status': status, 'hours': value}

def merge_matter_records(records: list[dict]) -> list[dict]:
    groups = {}
    for index, record in enumerate(records):
        groups.setdefault(record['matter_id'], []).append((record, index))
    result = []
    for matter_id in sorted(groups):
        items = sorted(groups[matter_id], key=lambda x: (x[0]['date'], x[1]))
        result.append({'matter_id': matter_id, 'first_date': items[0][0]['date'], 'last_date': items[-1][0]['date'], 'status': items[-1][0]['status'], 'entries': len(items), 'total_hours': round(sum((x[0]['hours'] for x in items)), 2)})
    return result

def build_matter_report(paths: list[str], status: str='all', limit: int | None=None) -> list[dict]:
    if not paths:
        raise ValueError('paths required')
    if status not in {'all', 'OPEN', 'PENDING', 'CLOSED'}:
        raise ValueError('invalid status')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0):
        raise ValueError('invalid limit')
    for path in paths:
        if not os.path.isfile(path):
            raise FileNotFoundError(path)
    args = ['sort', '-t', '|', '-k1,1', '-k2,2', *paths]
    completed = subprocess.run(args, capture_output=True, text=True, check=True, env={**os.environ, 'LC_ALL': 'C'})
    records = []
    for line in completed.stdout.splitlines():
        if line.strip():
            record = parse_matter_line(line)
            if status == 'all' or record['status'] == status:
                records.append(record)
    result = merge_matter_records(records)
    return result if limit is None else result[:limit]

