import csv
import math
import os
import tempfile
from collections import defaultdict

def export_completed_routes(records: list[dict], output_path: str) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    groups = defaultdict(lambda: [0, 0.0, 0.0])
    total_routes = 0
    total_distance = 0.0
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        for field in ('robot_id', 'zone', 'distance_m', 'duration_s', 'status'):
            if field not in record:
                raise ValueError('missing field')
        if not isinstance(record['robot_id'], str) or not record['robot_id']:
            raise ValueError('invalid robot_id')
        if not isinstance(record['zone'], str) or not record['zone']:
            raise ValueError('invalid zone')
        if not isinstance(record['distance_m'], (int, float)) or isinstance(record['distance_m'], bool):
            raise TypeError('distance_m must be numeric')
        if not isinstance(record['duration_s'], (int, float)) or isinstance(record['duration_s'], bool):
            raise TypeError('duration_s must be numeric')
        if record['status'] not in ('completed', 'planned'):
            raise ValueError('invalid status')
        if not math.isfinite(record['distance_m']) or not math.isfinite(record['duration_s']) or record['distance_m'] < 0 or (record['duration_s'] < 0):
            raise ValueError('invalid numeric value')
        if record['status'] == 'completed':
            key = (record['robot_id'], record['zone'])
            groups[key][0] += 1
            groups[key][1] += record['distance_m']
            groups[key][2] += record['duration_s']
            total_routes += 1
            total_distance += record['distance_m']
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.routes-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['robot_id', 'zone', 'route_count', 'total_distance_m', 'avg_duration_s'])
            for (robot_id, zone), (count, distance, duration) in sorted(groups.items()):
                writer.writerow([robot_id, zone, count, f'{distance:.2f}', f'{duration / count:.1f}'])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'groups': len(groups), 'routes': total_routes, 'distance_m': round(total_distance, 2)}

