        if not room or not bed or (not guest) or (event not in ('IN', 'OUT')):
            raise ValueError('invalid field')
        result.append({'date': day, 'room': room, 'bed': bed, 'guest': guest, 'event': event})
    return result

def make_occupancy_report(path: str, start: str, end: str, limit: int | None=None) -> list[dict]:
    try:
        first, last = (date.fromisoformat(start), date.fromisoformat(end))
    except ValueError as exc:
        raise ValueError('invalid range') from exc
    if first > last or (limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0)):
        raise ValueError('invalid arguments')
    try:
        completed = subprocess.run(['cat', path], capture_output=True, text=True, check=True)
        records = parse_stay_log(completed.stdout)
    except (OSError, subprocess.CalledProcessError, ValueError) as exc:
        raise ValueError('cannot read log') from exc
    dated = sorted(enumerate(records), key=lambda x: (x[1]['date'], x[0]))
    state = {}
    events = {}
    for _, record in dated:
        key = (record['room'], record['bed'])
        current = state.get(key)
        if record['event'] == 'IN':
            if current is not None:
                raise ValueError('invalid transition')
            state[key] = record['guest']
        elif current != record['guest']:
            raise ValueError('invalid transition')
        else:
            del state[key]
        events.setdefault(date.fromisoformat(record['date']), []).append(record)
    state = {}
    for day, records_for_day in events.items():
        if day < first:
            for record in records_for_day:
                key = (record['room'], record['bed'])
                if record['event'] == 'IN':
                    state[key] = record['guest']
                else:
                    state.pop(key, None)
    totals, peaks, guests = ({}, {}, {})
    day = first
    while day <= last:
        for record in events.get(day, []):
            key = (record['room'], record['bed'])
            if record['event'] == 'IN':
                state[key] = record['guest']
            else:
                state.pop(key, None)
        counts = {}
        for (room, _), guest in state.items():
            counts[room] = counts.get(room, 0) + 1
            guests.setdefault(room, set()).add(guest)
        for room, count in counts.items():
            totals[room] = totals.get(room, 0) + count
            peaks[room] = max(peaks.get(room, 0), count)
        day += timedelta(days=1)
    result = [{'room': room, 'occupied_nights': totals[room], 'peak_occupied_beds': peaks[room], 'guests': sorted(guests[room])} for room in totals]
    result.sort(key=lambda x: (-x['occupied_nights'], -x['peak_occupied_beds'], x['room']))
    return result[:limit] if limit is not None else result

