def export_signature_audit(events: list[dict], signer: str | None=None, status: str | None=None, page: int=1, page_size: int=50) -> str:
    statuses = {'pending', 'signed', 'declined', 'void'}
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    if signer is not None and (not isinstance(signer, str) or not signer):
        raise ValueError('invalid signer')
    if status is not None and (not isinstance(status, str) or status not in statuses):
        raise ValueError('invalid status')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    checked = []
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        required = ('event_id', 'document', 'signer', 'status', 'timestamp')
        if any((key not in event for key in required)):
            raise ValueError('missing event field')
        if isinstance(event['event_id'], bool) or not isinstance(event['event_id'], int) or event['event_id'] < 0:
            raise ValueError('invalid event id')
        if any((not isinstance(event[key], str) or not event[key] for key in ('document', 'signer', 'timestamp'))):
            raise ValueError('invalid event text')
        if event['status'] not in statuses or not isinstance(event['status'], str):
            raise ValueError('invalid event status')
        try:
            datetime.datetime.fromisoformat(event['timestamp'])
        except (TypeError, ValueError):
            raise ValueError('invalid timestamp')
        checked.append(event)
    selected = [e for e in checked if (signer is None or e['signer'] == signer) and (status is None or e['status'] == status)]
    selected.sort(key=lambda e: (-datetime.datetime.fromisoformat(e['timestamp']).timestamp(), e['event_id']))
    start = (page - 1) * page_size
    selected = selected[start:start + page_size]
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('event_id', 'document', 'signer', 'status', 'timestamp'))
            for event in selected:
                writer.writerow(tuple((event[key] for key in ('event_id', 'document', 'signer', 'status', 'timestamp'))))
        with open(path, encoding='utf-8', newline='') as handle:
            return handle.read()
    finally:
        os.unlink(path)

