import hashlib
import hmac
import json
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def calculate_commissions(payload: str, signature: str, secret: str, start: str='', end: str='', page: int=1, page_size: int=10) -> list[dict]:
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        records = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(records, list):
        raise ValueError('invalid payload')

    def parsed_date(value):
        if not isinstance(value, str):
            raise ValueError('invalid date')
        try:
            result = date.fromisoformat(value)
        except ValueError:
            raise ValueError('invalid date')
        if len(value) != 10 or value[4] != '-' or value[7] != '-':
            raise ValueError('invalid date')
        return result
    lower = parsed_date(start) if start else None
    upper = parsed_date(end) if end else None
    if lower and upper and (lower > upper):
        raise ValueError('invalid range')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    grouped = {}
    for item in records:
        if not isinstance(item, dict) or not isinstance(item.get('employee'), str) or (not item['employee']):
            raise ValueError('invalid record')
        current = parsed_date(item.get('date'))
        try:
            amount = Decimal(str(item['amount']))
        except (KeyError, InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if isinstance(item['amount'], bool) or not amount.is_finite() or amount < 0 or (amount.as_tuple().exponent < -2):
            raise ValueError('invalid amount')
        if lower and current < lower or (upper and current > upper):
            continue
        rate = Decimal('0.05') if amount <= 1000 else Decimal('0.07') if amount <= 5000 else Decimal('0.10')
        commission = (amount * rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        employee = item['employee']
        if employee not in grouped:
            grouped[employee] = [0, Decimal('0'), Decimal('0')]
        grouped[employee][0] += 1
        grouped[employee][1] += amount
        grouped[employee][2] += commission
    result = [{'employee': name, 'sales': values[0], 'gross': float(values[1].quantize(Decimal('0.01'))), 'commission': float(values[2].quantize(Decimal('0.01')))} for name, values in grouped.items()]
    result.sort(key=lambda row: (-row['commission'], row['employee']))
    begin = (page - 1) * page_size
    return result[begin:begin + page_size]

