import hashlib
import hmac
import json
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def process_webhook(secret: str, signature: str, body: str, campaign: str | None=None, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    expected = hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        root = json.loads(body)
    except (TypeError, ValueError):
        raise ValueError('invalid JSON')
    if not isinstance(root, dict) or not isinstance(root.get('donations'), list):
        raise ValueError('invalid donations')
    totals = {}
    counts = {}
    for item in root['donations']:
        if not isinstance(item, dict) or not isinstance(item.get('campaign'), str) or (not item['campaign']) or (not isinstance(item.get('amount'), (int, float))) or isinstance(item['amount'], bool) or (item['amount'] < 0) or (not isinstance(item.get('date'), str)):
            raise ValueError('invalid donation')
        try:
            date.fromisoformat(item['date'])
            amount = Decimal(str(item['amount']))
        except (ValueError, InvalidOperation):
            raise ValueError('invalid donation')
        if amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        name = item['campaign']
        if campaign is None or name == campaign:
            totals[name] = totals.get(name, Decimal('0')) + amount
            counts[name] = counts.get(name, 0) + 1
    names = sorted(totals, key=lambda n: (-totals[n], n))
    total_campaigns = len(names)
    pages = (total_campaigns + page_size - 1) // page_size
    start = (page - 1) * page_size
    items = [{'campaign': n, 'donations': counts[n], 'total': format(totals[n].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')} for n in names[start:start + page_size]]
    return {'items': items, 'page': page, 'page_size': page_size, 'pages': pages, 'total_campaigns': total_campaigns}

