from solution import evaluate_rule, build_maintenance_plan, summarize_plan
import pytest

def test_evaluate_rule_arithmetic_comparisons_and_variables():
    values = {'mileage': 12500, 'engine_hours': 240, 'critical': False, 'age_years': 6}
    assert evaluate_rule('mileage / 1000 >= 12 and engine_hours + 10 > 200', values) is True
    assert evaluate_rule('not critical or age_years == 7', values) is True
    assert evaluate_rule('min(mileage, 13000) == 12500 and max(2, 4, 3) == 4', values) is True

def test_evaluate_rule_round_and_boolean_value():
    values = {'service_cost': 123.456, 'critical': True}
    assert evaluate_rule('round(service_cost, 2) == 123.46 and critical', values) is True
    assert evaluate_rule('critical and 0', values) is False

def test_evaluate_rule_errors():
    with pytest.raises(KeyError):
