import hashlib
import hmac
import json
from datetime import date

def verify_and_summarize(payload: bytes, signature: str, shared_key: bytes, as_of: str) -> list[dict]:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(shared_key, bytes)):
        raise ValueError('invalid types')
    try:
        expected = hmac.new(shared_key, payload, hashlib.sha256).digest()
        supplied = bytes.fromhex(signature)
    except (ValueError, TypeError):
        raise ValueError('invalid signature')
    if len(signature) != 64 or not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid signature')
    try:
        cutoff = date.fromisoformat(as_of)
        records = json.loads(payload.decode('utf-8'))
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(records, list):
        raise ValueError('invalid payload')
    result = {}
    fields = {'appointment_id', 'patient_id', 'dentist', 'due_date', 'channel', 'status'}
    for record in records:
        if not isinstance(record, dict) or set(record) != fields:
            raise ValueError('invalid record')
        if any((not isinstance(record[name], str) or not record[name] for name in fields)):
            raise ValueError('invalid record')
        try:
            due = date.fromisoformat(record['due_date'])
        except ValueError:
            raise ValueError('invalid record')
        if record['channel'] not in ('email', 'sms') or record['status'] not in ('pending', 'sent', 'cancelled'):
            raise ValueError('invalid record')
        if record['status'] == 'pending' and due <= cutoff:
            key = (record['due_date'], record['dentist'])
            if key not in result:
                result[key] = {'dentist': record['dentist'], 'due_date': record['due_date'], 'count': 0, 'patients': set(), 'channels': {'email': 0, 'sms': 0}}
            group = result[key]
            group['count'] += 1
            group['patients'].add(record['patient_id'])
            group['channels'][record['channel']] += 1
    output = []
    for key in sorted(result):
        group = result[key]
        output.append({'dentist': group['dentist'], 'due_date': group['due_date'], 'count': group['count'], 'patients': sorted(group['patients']), 'channels': group['channels']})
    return output

