import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
_PRIORITIES = ('critical', 'high', 'medium', 'low')
_STATUSES = ('open', 'investigating', 'resolved')

def generate_invite_codes(count: int, length: int=8) -> list[str]:
    if isinstance(count, bool) or isinstance(length, bool):
        raise TypeError('count and length must be integers')
    if not isinstance(count, int) or not isinstance(length, int):
        raise TypeError('count and length must be integers')
    if count < 0 or count > 1000:
        raise ValueError('count out of range')
    if length < 4 or length > 32:
        raise ValueError('length out of range')
    result = []
    seen = set()
    while len(result) < count:
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(length)))
        if code not in seen:
            seen.add(code)
            result.append(code)
    return result

def summarize_tickets(tickets: list[dict], page: int=1, page_size: int=20) -> dict:
    if not isinstance(tickets, list):
        raise TypeError('tickets must be a list')
    if isinstance(page, bool) or isinstance(page_size, bool):
        raise TypeError('pagination must be integers')
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError('pagination must be integers')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    required = {'id', 'priority', 'status', 'minutes'}
    rows = []
    ids = set()
    for ticket in tickets:
        if not isinstance(ticket, dict):
            raise TypeError('ticket must be a dictionary')
        if set(ticket) != required:
            raise ValueError('invalid ticket fields')
        ident = ticket['id']
        priority = ticket['priority']
        status = ticket['status']
        minutes = ticket['minutes']
        if not isinstance(ident, str) or not ident:
            raise TypeError('invalid id')
        if priority not in _PRIORITIES or status not in _STATUSES:
            raise ValueError('invalid ticket value')
        if isinstance(minutes, bool) or not isinstance(minutes, int):
            raise TypeError('invalid minutes')
        if minutes < 0:
            raise ValueError('invalid minutes')
        if ident in ids:
            raise ValueError('duplicate id')
        ids.add(ident)
        rows.append(ticket)
    ordered = sorted(rows, key=lambda x: (_PRIORITIES.index(x['priority']), -x['minutes'], x['id']))
    counts = {priority: 0 for priority in _PRIORITIES}
    for ticket in rows:
        counts[ticket['priority']] += 1
    total = len(rows)
    average = round(sum((x['minutes'] for x in rows)) / total, 2) if total else 0.0
    start = (page - 1) * page_size
    return {'total': total, 'by_priority': counts, 'average_minutes': average, 'ticket_ids': [x['id'] for x in ordered[start:start + page_size]]}

