import hashlib
import hmac
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _credential(password):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def make_adoption_record(applicant: str, animal_id: str, species: str, fee: float, password: str) -> dict:
    values = []
    for value in (applicant, animal_id, species):
        if not isinstance(value, str) or not value.strip():
            raise ValueError('invalid text')
        values.append(value.strip())
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    if isinstance(fee, bool) or not isinstance(fee, (int, float)):
        raise TypeError('invalid fee')
    try:
        amount = Decimal(str(fee))
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid fee')
        cents = int((amount * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid fee')
    return {'applicant': values[0], 'animal_id': values[1], 'species': values[2], 'fee_cents': cents, 'credential': _credential(password)}

def verify_adoption_record(record: dict, password: str) -> bool:
    try:
        salt_text, digest_text = record['credential'].split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

def summarize_adoptions(records: list[dict], species: str | None=None, page: int=1, page_size: int=10) -> dict:
    if species is not None and (not isinstance(species, str) or not species.strip()):
        raise ValueError('invalid species')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    chosen = [r for r in records if species is None or r['species'] == species.strip()]
    ordered = sorted(chosen, key=lambda r: (-r['fee_cents'], r['animal_id'], r['applicant']))
    counts = {}
    for record in chosen:
        counts[record['species']] = counts.get(record['species'], 0) + 1
    counts = dict(sorted(counts.items()))
    start = (page - 1) * page_size
    items = [{k: r[k] for k in ('applicant', 'animal_id', 'species', 'fee_cents')} for r in ordered[start:start + page_size]]
    return {'total': len(chosen), 'total_fee_cents': sum((r['fee_cents'] for r in chosen)), 'by_species': counts, 'items': items}

