    duplicate = {'case_id': 'C1', 'status': 'approved', 'updated_at': '2025-01-01'}
    second = {'case_id': 'C2', 'status': 'approved', 'updated_at': '2024-06-01'}
    with patch('solution.requests.get', side_effect=[response([first, duplicate], 2), response([second], None)]) as get:
        result = fetch_case_statistics(['C1', 'C2'], 'x', 2)
    assert result == {'cases': [second, first], 'counts': {'pending': 1, 'approved': 1}}
    assert get.call_count == 2
    assert get.call_args_list[1].kwargs['params']['page'] == 2
