import sqlite3

def summarize_telemetry(conn: sqlite3.Connection, event_name: str | None=None, min_duration_ms: int | None=None, since: int | None=None, limit: int=20, offset: int=0, sort_by: str='event') -> list[dict]:
    if event_name is not None and (not isinstance(event_name, str)):
        raise TypeError('event_name must be a string or None')
    for value in (min_duration_ms, since):
        if value is not None and (not isinstance(value, int) or isinstance(value, bool)):
            raise TypeError('numeric filters must be integers')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('limit out of range')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('offset out of range')
    if sort_by not in {'event', 'count', 'avg_duration_ms'}:
        raise ValueError('invalid sort_by')
    ordering = {'event': 'event_name ASC', 'count': 'count DESC, event_name ASC', 'avg_duration_ms': 'avg_duration_ms DESC, event_name ASC'}[sort_by]
    clauses = []
    values = []
    if event_name is not None:
        clauses.append('event_name = ?')
        values.append(event_name)
    if min_duration_ms is not None:
        clauses.append('duration_ms >= ?')
        values.append(min_duration_ms)
    if since is not None:
        clauses.append('recorded_at >= ?')
        values.append(since)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT event_name, COUNT(*) AS count, ROUND(AVG(duration_ms), 2) AS avg_duration_ms, SUM(CASE WHEN success = 1 THEN 1 ELSE 0 END) AS success_count FROM telemetry{where} GROUP BY event_name ORDER BY {ordering} LIMIT ? OFFSET ?'
    values.extend([limit, offset])
    rows = conn.execute(query, values).fetchall()
    return [{'event_name': r[0], 'count': r[1], 'avg_duration_ms': float(r[2]), 'success_count': r[3]} for r in rows]

