from solution import summarize_invoices
import tempfile
from pathlib import Path

def write_records(lines):
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    try:
        handle.write('\n'.join(lines))
        handle.write('\n')
        return Path(handle.name)
    finally:
        handle.close()

def test_groups_filters_and_orders_creators():
    path = write_records(['Zeta,2025-03,10.25', 'Alpha,2025-02,99.99', 'Beta,2025-03,2.10', 'Alpha,2025-03,1.20', 'Beta,2025-03,3.40'])
    try:
        assert summarize_invoices(str(path), '2025-03') == [{'creator': 'Alpha', 'invoice_count': 1, 'total_amount': '1.20'}, {'creator': 'Beta', 'invoice_count': 2, 'total_amount': '5.50'}, {'creator': 'Zeta', 'invoice_count': 1, 'total_amount': '10.25'}]
    finally:
        path.unlink()

def test_pagination_and_boundaries():
    path = write_records(['A,2025-01,1', 'B,2025-01,2', 'C,2025-01,3', 'D,2025-01,4', 'E,2025-01,5'])
    try:
        assert [x['creator'] for x in summarize_invoices(str(path), '2025-01', 1, 2)] == ['A', 'B']
        assert [x['creator'] for x in summarize_invoices(str(path), '2025-01', 2, 2)] == ['C', 'D']
        assert [x['creator'] for x in summarize_invoices(str(path), '2025-01', 3, 2)] == ['E']
        assert summarize_invoices(str(path), '2025-01', 4, 2) == []
    finally:
        path.unlink()

def test_empty_file_and_nonmatching_month():
    path = write_records(['A,2024-12,4.50', '', 'B,2025-02,1.00'])
    try:
        assert summarize_invoices(str(path), '2025-01') == []
    finally:
        path.unlink()

def test_invalid_arguments_raise_value_error():
    path = write_records(['A,2025-01,1.00'])
    try:
        for args in [('2025-00', 1, 10), ('2025-13', 1, 10), ('2025-1', 1, 10), ('2025-01', 0, 10), ('2025-01', 1, 0), ('2025-01', 1, 101)]:
            try:
                summarize_invoices(str(path), *args)
                assert False
            except ValueError:
                pass
    finally:
        path.unlink()

def test_invalid_records_raise_value_error():
    cases = [['A,2025-01,1.001'], ['A,2025-01,-1.00'], ['A,2025-01'], [',2025-01,1.00'], ['A,2025-1,1.00'], ['A,2025-01,not-money']]
    for lines in cases:
        path = write_records(lines)
        try:
            try:
                summarize_invoices(str(path), '2025-01')
                assert False
            except ValueError:
                pass
        finally:
            path.unlink()

