import re
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_invoices(path: str, month: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', month):
        raise ValueError('invalid month')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
    groups = {}
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split(',')
        if len(fields) != 3:
            raise ValueError('invalid record')
        creator, record_month, amount_text = (x.strip() for x in fields)
        if not creator or not re.fullmatch('\\d{4}-(0[1-9]|1[0-2])', record_month):
            raise ValueError('invalid record')
        try:
            amount = Decimal(amount_text)
        except InvalidOperation:
            raise ValueError('invalid amount')
        if amount < 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        if record_month == month:
            if creator not in groups:
                groups[creator] = [0, Decimal('0.00')]
            groups[creator][0] += 1
            groups[creator][1] += amount
    rows = [{'creator': creator, 'invoice_count': values[0], 'total_amount': str(values[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for creator, values in sorted(groups.items())]
    start = (page - 1) * page_size
    return rows[start:start + page_size]

