import hashlib
import hmac
import json
from datetime import datetime

def aggregate_signed_logs(payload: str, signature: str, secret: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise ValueError('invalid signature')
    expected = hmac.new(secret.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('invalid signature')
    groups = {}
    for line in payload.splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        service = item.get('service')
        level = item.get('level')
        duration = item.get('duration_ms')
        timestamp = item.get('timestamp')
        if not isinstance(service, str) or not service or level not in {'INFO', 'WARN', 'ERROR'}:
            raise ValueError('invalid record')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid record')
        if not isinstance(timestamp, str):
            raise ValueError('invalid record')
        try:
            datetime.fromisoformat(timestamp.replace('Z', '+00:00'))
        except ValueError:
            raise ValueError('invalid record')
        group = groups.setdefault(service, [0, 0, 0])
        group[0] += 1
        group[1] += level == 'ERROR'
        group[2] += duration
    result = [{'service': service, 'total': values[0], 'errors': values[1], 'average_duration_ms': round(values[2] / values[0], 2)} for service, values in groups.items()]
    result.sort(key=lambda item: (-item['errors'], item['service']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

