        raise ValueError('invalid sort')
    params = []
    clauses = []
    if airport is not None:
        clauses.append('airport = ?')
        params.append(airport)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if starts_before is not None:
        starts_before = _date(starts_before)
        clauses.append('start < ?')
        params.append(starts_before)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    rows = conn.execute('SELECT id, plate, airport, start, end, status FROM reservations' + where + ' ORDER BY ' + sort_by + ' ' + direction + ', id ASC', params).fetchall()
    return [dict(zip(('id', 'plate', 'airport', 'start', 'end', 'status'), row)) for row in rows]

def cancel_reservation(conn: sqlite3.Connection, reservation_id: int) -> bool:
    cur = conn.execute("UPDATE reservations SET status = 'cancelled' WHERE id = ? AND status = 'active'", (reservation_id,))
