import copy
import json

def load_league(text: str) -> dict:
    try:
        raw = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(raw, dict) or set(raw) != {'tenant', 'teams', 'matches'}:
        raise ValueError('invalid league')
    if not isinstance(raw['tenant'], str) or not raw['tenant'] or (not isinstance(raw['teams'], list)) or (not isinstance(raw['matches'], list)):
        raise ValueError('invalid league')
    teams = []
    ids = set()
    for t in raw['teams']:
        if not isinstance(t, dict) or set(t) != {'id', 'name'} or (not all((isinstance(t[x], str) and t[x] for x in ('id', 'name')))) or (t['id'] in ids):
            raise ValueError('invalid team')
        ids.add(t['id'])
        teams.append(dict(t))
    matches = []
    mids = set()
    for m in raw['matches']:
        base = {'id', 'home_team', 'away_team', 'organizer_id', 'status'}
        if not isinstance(m, dict) or not base.issubset(m) or set(m) - base - {'home_score', 'away_score'} or (not all((isinstance(m.get(x), str) and m[x] for x in base - {'status'}))) or (m['id'] in mids) or (m['home_team'] not in ids) or (m['away_team'] not in ids) or (m['home_team'] == m['away_team']) or (m['status'] not in {'scheduled', 'completed'}):
            raise ValueError('invalid match')
        scored = {'home_score', 'away_score'}.issubset(m)
        if m['status'] == 'completed' and (not scored or any((type(m[x]) is not int or m[x] < 0 for x in ('home_score', 'away_score')))):
            raise ValueError('invalid score')
        if m['status'] == 'scheduled' and scored:
            raise ValueError('invalid score')
        mids.add(m['id'])
        matches.append(dict(m))
    return {'tenant': raw['tenant'], 'teams': teams, 'matches': matches}

def record_match_result(state: dict, requester: dict, match_id: str, home_score: int, away_score: int) -> dict:
    result = copy.deepcopy(state)
    match = next((m for m in result['matches'] if m['id'] == match_id), None)
    if match is None:
        raise KeyError(match_id)
    if requester.get('tenant') != result['tenant'] or (requester.get('role') != 'commissioner' and requester.get('user_id') != match['organizer_id']):
        raise PermissionError('not permitted')
    if match['status'] != 'scheduled' or type(home_score) is not int or type(away_score) is not int or (home_score < 0) or (away_score < 0):
        raise ValueError('invalid result')
    match.update(status='completed', home_score=home_score, away_score=away_score)
    return result

def standings(state: dict) -> list[dict]:
    out = {t['id']: {'team_id': t['id'], 'name': t['name'], 'played': 0, 'wins': 0, 'draws': 0, 'losses': 0, 'goals_for': 0, 'goals_against': 0, 'goal_difference': 0, 'points': 0} for t in state['teams']}
    for m in state['matches']:
        if m['status'] != 'completed' or m['home_team'] not in out or m['away_team'] not in out or any((type(m.get(x)) is not int or m[x] < 0 for x in ('home_score', 'away_score'))):
            if m['status'] == 'completed':
                raise ValueError('invalid match')
            continue
        a, b = (out[m['home_team']], out[m['away_team']])
        hs, aw = (m['home_score'], m['away_score'])
        for r, f, g in ((a, hs, aw), (b, aw, hs)):
            r['played'] += 1
            r['goals_for'] += f
            r['goals_against'] += g
        if hs == aw:
            a['draws'] += 1
            b['draws'] += 1
            a['points'] += 1
            b['points'] += 1
        else:
            w, l = (a, b) if hs > aw else (b, a)
            w['wins'] += 1
            l['losses'] += 1
            w['points'] += 3
    for r in out.values():
        r['goal_difference'] = r['goals_for'] - r['goals_against']
    return sorted(out.values(), key=lambda r: (-r['points'], -r['goal_difference'], -r['goals_for'], r['name'], r['team_id']))

