import ast
import operator

def select_loans(loans: list[dict], expression: str) -> list[dict]:
    tree = ast.parse(expression, mode='eval').body
    names = {'value', 'year', 'duration_days', 'available', 'priority'}
    funcs = {'min': min, 'max': max, 'round': round}

    def ev(node, env):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise NameError(node.id)
            return env[node.id]
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            return ops[type(node.op)](ev(node.left, env), ev(node.right, env))
        if isinstance(node, ast.UnaryOp):
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](ev(node.operand, env))
        if isinstance(node, ast.BoolOp):
            values = [ev(x, env) for x in node.values]
            if isinstance(node.op, ast.And):
                result = values[0]
                for value in values[1:]:
                    result = value if result else result
                return result
            result = values[0]
            for value in values[1:]:
                result = result if result else value
            return result
        if isinstance(node, ast.Compare):
            ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            left = ev(node.left, env)
            for op, part in zip(node.ops, node.comparators):
                right = ev(part, env)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in funcs) and (not node.keywords):
            return funcs[node.func.id](*(ev(arg, env) for arg in node.args))
        raise ValueError('unsupported expression')
    result = []
    for loan in loans:
        env = {name: loan[name] for name in names}
        if ev(tree, env):
            result.append(loan)
    return sorted(result, key=lambda loan: (-loan['value'], loan['accession']))

