import os

def create_contribution_statement(base_dir: str, member_id: str, annual_salary: float, employee_rate: float, employer_rate: float, relative_filename: str) -> str:
    if not member_id or not relative_filename:
        raise ValueError('member_id and relative_filename are required')
    if not isinstance(annual_salary, (int, float)) or isinstance(annual_salary, bool):
        raise TypeError('annual_salary must be numeric')
    if not isinstance(employee_rate, (int, float)) or isinstance(employee_rate, bool):
        raise TypeError('employee_rate must be numeric')
    if not isinstance(employer_rate, (int, float)) or isinstance(employer_rate, bool):
        raise TypeError('employer_rate must be numeric')
    if annual_salary < 0 or not 0 <= employee_rate <= 1 or (not 0 <= employer_rate <= 1):
        raise ValueError('financial values are out of range')
    base = os.path.realpath(base_dir)
    os.makedirs(base, exist_ok=True)
    target = os.path.realpath(os.path.join(base, relative_filename))
    if os.path.commonpath((base, target)) != base:
        raise ValueError('output path is outside the base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    text = f'Member: {member_id}\nAnnual salary: {annual_salary:.2f}\nEmployee contribution: {annual_salary * employee_rate:.2f}\nEmployer contribution: {annual_salary * employer_rate:.2f}\n'
    with open(target, 'w', encoding='utf-8') as stream:
        stream.write(text)
    return os.path.abspath(target)

