import os
import re
import tempfile

def create_transcript_index(transcript_path: str, index_path: str) -> int:
    entries = {}
    with open(transcript_path, 'r', encoding='utf-8') as source:
        for line_number, line in enumerate(source, 1):
            words = set(re.findall('[A-Za-z0-9]+', line.lower()))
            for word in words:
                entries.setdefault(word, []).append(line_number)
    ordered = {word: entries[word] for word in sorted(entries)}
    parent = os.path.dirname(os.path.abspath(index_path))
    descriptor, temporary_path = tempfile.mkstemp(prefix='.transcript-', suffix='.tmp', dir=parent)
    try:
        with os.fdopen(descriptor, 'w', encoding='utf-8') as temporary:
            descriptor = None
            json.dump(ordered, temporary, separators=(',', ':'))
            temporary.write('\n')
        os.replace(temporary_path, index_path)
        temporary_path = None
