from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from xml.etree import ElementTree as ET
_STATUSES = ('proposed', 'shortlisted', 'won', 'lost')

def _date(s):
    try:
        return date.fromisoformat(s)
    except Exception as e:
        raise ValueError('invalid date') from e

def _money(s):
    s = s.strip()
    if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', s):
        raise ValueError('invalid amount')
    try:
        return int((Decimal(s) * 100).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    except InvalidOperation as e:
        raise ValueError('invalid amount') from e

def _text(x):
    return (x or '').strip()

def parse_proposals(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as e:
        raise ValueError('invalid xml') from e
    if root.tag != 'proposals':
        raise ValueError('invalid root')
    out, seen = ([], set())
    for node in root.findall('proposal'):
        try:
            pid, client, status, submitted = (_text(node.get(k)) for k in ('id', 'client', 'status', 'submitted'))
            if not pid or not client or pid in seen or (status not in _STATUSES):
                raise ValueError('invalid proposal')
            _date(submitted)
            fee_node = node.find('fee')
            if fee_node is None or not _text(fee_node.get('currency')):
                raise ValueError('missing fee')
            currency, fee = (_text(fee_node.get('currency')), _money(fee_node.text or ''))
            phase_nodes = node.findall('./phases/phase')
            team_nodes = node.findall('./team/member')
            if not phase_nodes or not team_nodes:
                raise ValueError('missing collection')
            phases, total = ([], 0)
            for p in phase_nodes:
                name, ws = (_text(p.get('name')), _text(p.get('weeks')))
                if not name or not re.fullmatch('\\d+', ws) or int(ws) <= 0:
                    raise ValueError('invalid phase')
                pf = _money(p.get('fee', ''))
                phases.append({'name': name, 'weeks': int(ws), 'fee_cents': pf})
                total += pf
            if total != fee:
                raise ValueError('fee mismatch')
            team = []
            for m in team_nodes:
                name, role = (_text(m.text), _text(m.get('role')))
                if not name or not role:
                    raise ValueError('invalid member')
                team.append({'name': name, 'role': role})
            seen.add(pid)
            out.append({'id': pid, 'client': client, 'status': status, 'submitted': submitted, 'currency': currency, 'fee_cents': fee, 'phases': phases, 'team': team})
        except ValueError:
            raise
        except Exception as e:
            raise ValueError('invalid proposal') from e
    return out

def summarize_proposals(xml_text: str, as_of: str) -> dict:
    cutoff = _date(as_of)
    selected = [p for p in parse_proposals(xml_text) if _date(p['submitted']) <= cutoff]
    counts = {s: 0 for s in _STATUSES}
    clients = {}
    for p in selected:
        counts[p['status']] += 1
        c = clients.setdefault(p['client'], [0, 0])
        c[0] += 1
        c[1] += p['fee_cents']
    groups = [{'client': k, 'proposal_count': v[0], 'total_fee_cents': v[1]} for k, v in clients.items()]
    groups.sort(key=lambda x: (-x['total_fee_cents'], x['client']))
    weeks = sum((sum((x['weeks'] for x in p['phases'])) for p in selected))
    return {'as_of': as_of, 'proposal_count': len(selected), 'status_counts': counts, 'total_fee_cents': sum((p['fee_cents'] for p in selected)), 'average_phase_weeks': round(weeks / len(selected), 2) if selected else 0.0, 'clients': groups, 'proposals': [p['id'] for p in sorted(selected, key=lambda x: (x['submitted'], x['id']))]}

