        raise ValueError('invalid worker_id')
    if not isinstance(habitat, str) or not habitat:
        raise ValueError('invalid habitat')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(hectares, (int, float)) or isinstance(hectares, bool) or (not math.isfinite(hectares)) or (hectares <= 0):
        raise ValueError('invalid hectares')
    if not isinstance(species, list) or not species or any((not isinstance(x, str) or not x for x in species)):
        raise ValueError('invalid species')
    names = sorted(set(species))
    if len(names) != len(species):
        raise ValueError('duplicate species')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    stored = 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'worker_id': worker_id, 'habitat': habitat, 'hectares': float(hectares), 'species': names, 'password_hash': stored}

