import hashlib
import os

def register_operator(operator_id: str, password: str, instruments: list[str]) -> dict:
    if not isinstance(operator_id, str) or not operator_id:
        raise ValueError('invalid operator_id')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if not isinstance(instruments, list) or any((not isinstance(x, str) or not x for x in instruments)):
        raise ValueError('invalid instruments')
    normalized = list(dict.fromkeys(instruments))
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'operator_id': operator_id, 'instruments': normalized, 'password_salt': salt.hex(), 'password_hash': digest.hex()}

def authenticate_operator(record: dict, password: str, instrument: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str) or (not isinstance(instrument, str)):
            return False
        if instrument not in record['instruments']:
            return False
        salt = bytes.fromhex(record['password_salt'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()
        return actual == record['password_hash']
    except (KeyError, TypeError, ValueError):
        return False

