from datetime import datetime

def parse_flight_log(text: str) -> list[dict]:
    lines = [x for x in text.splitlines() if x.strip()]
    if not lines or lines[0] != 'timestamp,flight,phase,fuel':
        raise ValueError('invalid header')
    out = []
    for f in csv.reader(lines[1:]):
        if len(f) != 4:
            raise ValueError('invalid row')
        stamp, flight, phase, fuel = f
        if not flight or not phase:
            raise ValueError('empty field')
        try:
            ts = datetime.fromisoformat(stamp[:-1] + '+00:00' if stamp.endswith('Z') else stamp)
            value = float(fuel)
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if value < 0:
            raise ValueError('negative fuel')
        out.append({'timestamp': ts, 'flight': flight, 'phase': phase, 'fuel': value})
    return out

