from collections.abc import Mapping

def parse_sales_feed(text: str) -> list[dict]:
    names = ['sale_id', 'artist', 'title', 'price_cents', 'quantity', 'status', 'region']
    if not text:
        raise ValueError('missing header')
    rows = list(csv.reader(io.StringIO(text, newline='')))
    if not rows or len(rows[0]) != 7 or set(rows[0]) != set(names):
        raise ValueError('invalid header')
    pos = {n: rows[0].index(n) for n in names}
    out = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 7:
            raise ValueError('invalid row')
        x = {n: row[pos[n]] for n in names}
        if not x['sale_id'] or not x['artist'] or (not x['title']) or (x['sale_id'] in seen):
            raise ValueError('invalid sale')
        try:
            x['price_cents'] = int(x['price_cents'])
            x['quantity'] = int(x['quantity'])
        except Exception as e:
            raise ValueError('invalid integer') from e
        if x['price_cents'] < 0 or x['quantity'] <= 0 or x['status'] not in ('completed', 'refunded') or (x['region'] not in ('EU', 'NA', 'APAC')):
            raise ValueError('invalid value')
        seen.add(x['sale_id'])
        out.append(x)
    return out

def build_settlement(records: list[dict], config: dict | None=None) -> dict:
    if config is not None and (not isinstance(config, Mapping)):
        raise ValueError('invalid config')
    token = config['api_token'] if config is not None and 'api_token' in config else os.environ.get('ART_MARKETPLACE_TOKEN')
    if not isinstance(token, str) or not token:
        raise ValueError('api token is required')
    rates = {'EU': 15, 'NA': 12, 'APAC': 10}
    seen = set()
    totals = {}
    for r in records:
        if r['sale_id'] in seen:
            raise ValueError('duplicate sale id')
        seen.add(r['sale_id'])
        if r['status'] == 'completed':
            g = r['price_cents'] * r['quantity']
            v = totals.setdefault(r['artist'], [0, 0, 0])
            v[0] += g
            v[1] += g * rates[r['region']] // 100
            v[2] += 1
    a = [{'artist': n, 'gross_cents': v[0], 'commission_cents': v[1], 'net_cents': v[0] - v[1], 'sales_count': v[2]} for n, v in totals.items()]
    a.sort(key=lambda x: (-x['net_cents'], x['artist']))
    d = {'artists': a, 'grand_total_cents': sum((x['net_cents'] for x in a))}
    raw = json.dumps(d, sort_keys=True, separators=(',', ':')).encode()
    d['signature'] = hmac.new(token.encode(), raw, hashlib.sha256).hexdigest()
    return d

