import json
import math

def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('records')
    required = {'provider', 'specialty', 'status', 'score', 'reviewed'}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('record')
        if any((not isinstance(record[k], str) or not record[k] for k in ('provider', 'specialty', 'status'))):
            raise ValueError('text')
        score = record['score']
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 100):
            raise ValueError('score')
        if not isinstance(record['reviewed'], bool):
            raise ValueError('reviewed')

def encode_credentials(records: list[dict]) -> bytes:
    _check_records(records)
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except (TypeError, ValueError) as exc:
        raise ValueError('records') from exc

def summarize_credentials(payload: bytes, specialty: str | None=None, status: str='active', page: int=1, page_size: int=10) -> dict:
    if not isinstance(specialty, (str, type(None))) or specialty == '' or (not isinstance(status, str)) or (not status) or (not isinstance(page, int)) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('arguments')
    try:
        records = json.loads(payload.decode('utf-8'))
        _check_records(records)
    except (AttributeError, UnicodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('payload') from exc
    filtered = [r for r in records if r['status'] == status and (specialty is None or r['specialty'] == specialty)]
    filtered.sort(key=lambda r: (-r['score'], r['provider'], r['specialty']))
    total = len(filtered)
    start = (page - 1) * page_size
    items = [{'provider': r['provider'], 'specialty': r['specialty'], 'score': round(r['score'], 2)} for r in filtered[start:start + page_size]]
    return {'total': total, 'pages': (total + page_size - 1) // page_size if total else 0, 'items': items}

