import secrets
import string

def make_manifest(build_id: str, artifacts: list[dict]) -> dict:
    if not isinstance(build_id, str) or not build_id or any((c.isspace() for c in build_id)):
        raise ValueError('invalid build id')
    if not isinstance(artifacts, list):
        raise ValueError('invalid artifacts')
    rows = []
    seen = set()
    for item in artifacts:
        if not isinstance(item, dict) or not all((k in item for k in ('path', 'size', 'sha256'))):
            raise ValueError('invalid artifact')
        path, size, digest = (item['path'], item['size'], item['sha256'])
        parts = path.split('/') if isinstance(path, str) else []
        if not path or path.startswith('/') or '\\' in path or any((x in ('', '.', '..') for x in parts)) or (path in seen):
            raise ValueError('invalid path')
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError('invalid size')
        if not isinstance(digest, str) or len(digest) != 64 or any((c not in string.hexdigits.lower() or c.isupper() for c in digest)):
            raise ValueError('invalid digest')
        media = item.get('media', 'other')
        if not isinstance(media, str) or not media or '/' in media or ('\\' in media):
            raise ValueError('invalid media')
        seen.add(path)
        rows.append({'path': path, 'size': size, 'sha256': digest, 'media': media})
    rows.sort(key=lambda x: (x['path'], -x['size'], x['sha256']))
    groups = {}
    for row in rows:
        group = groups.setdefault(row['media'], {'count': 0, 'bytes': 0})
        group['count'] += 1
        group['bytes'] += row['size']
    return {'build_id': build_id, 'total_size': sum((x['size'] for x in rows)), 'artifacts': rows, 'by_media': dict(sorted(groups.items()))}

def issue_upload(build_id: str, artifacts: list[dict], ttl_seconds: int=900) -> dict:
    if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, int) or ttl_seconds <= 0:
        raise ValueError('invalid ttl')
    manifest = make_manifest(build_id, artifacts)
    alphabet = string.ascii_letters + string.digits
    token = ''.join((secrets.choice(alphabet) for _ in range(40)))
    return {'token': token, 'expires_in': ttl_seconds, 'manifest': manifest}

def verify_upload_token(token: str, plan: dict) -> bool:
    if not isinstance(token, str) or len(token) != 40 or any((c not in string.ascii_letters + string.digits for c in token)):
        return False
    return isinstance(plan, dict) and set(plan) == {'token'} and (plan.get('token') == token)

