import csv
import os
import tempfile
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO

def parse_readings(text: str) -> list[dict]:
    rows = [r for r in csv.reader(StringIO(text)) if any((x.strip() for x in r))]
    if not rows:
        return []
    if [x.strip() for x in rows[0]] != ['site', 'date', 'electric_kwh', 'water_l']:
        raise ValueError('header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 4:
            raise ValueError('row')
        site, ds, es, ws = [x.strip() for x in row]
        if not site:
            raise ValueError('site')
        try:
            d = date.fromisoformat(ds)
            e = Decimal(es)
            w = Decimal(ws)
        except (ValueError, InvalidOperation):
            raise ValueError('value')
        if e < 0 or w < 0 or (not e.is_finite()) or (not w.is_finite()) or ((site, d) in seen):
            raise ValueError('value')
        seen.add((site, d))
        result.append({'site': site, 'date': d, 'electric_kwh': e, 'water_l': w})
    return result

def _rates(rates):
    try:
        tiers = rates['electric_tiers']
        wp = Decimal(str(rates['water_price']))
        df = Decimal(str(rates['daily_fee']))
    except (KeyError, InvalidOperation, ValueError):
        raise ValueError('rates')
    if not tiers or wp < 0 or df < 0 or (not wp.is_finite()) or (not df.is_finite()):
        raise ValueError('rates')
    out = []
    previous = Decimal('0')
    for i, pair in enumerate(tiers):
        if len(pair) != 2:
            raise ValueError('rates')
        limit, price = pair
        try:
            p = Decimal(str(price))
            lim = None if limit is None else Decimal(str(limit))
        except (InvalidOperation, ValueError):
            raise ValueError('rates')
        if p < 0 or not p.is_finite() or (lim is not None and (lim <= previous or not lim.is_finite())):
            raise ValueError('rates')
        if lim is None and i != len(tiers) - 1:
            raise ValueError('rates')
        out.append((lim, p))
        if lim is not None:
            previous = lim
    if out[-1][0] is not None:
        raise ValueError('rates')
    return (out, wp, df)

def calculate_bills(readings: list[dict], rates: dict) -> list[dict]:
    tiers, wp, df = _rates(rates)
    groups = {}
    for r in readings:
        groups.setdefault(r['site'], []).append(r)
    result = []
    q = Decimal('0.01')
    for site in sorted(groups):
        rs = groups[site]
        e = sum((r['electric_kwh'] for r in rs), Decimal())
        w = sum((r['water_l'] for r in rs), Decimal())
        charge = Decimal()
        used = Decimal()
        for lim, price in tiers:
            amount = e - used if lim is None else min(e, lim) - used
            if amount > 0:
                charge += amount * price
            if lim is not None:
                used = lim
            if lim is not None and e <= lim:
                break
        wc = w * wp
        daily = df * len({r['date'] for r in rs})
        vals = [e, w, charge, wc, daily, charge + wc + daily]
        vals = [x.quantize(q, rounding=ROUND_HALF_UP) for x in vals]
        result.append(dict(zip(['site', 'electric_kwh', 'water_l', 'electric_charge', 'water_charge', 'daily_fees', 'total'], [site] + vals)))
    return result

def export_bills(text: str, rates: dict, destination: str) -> list[dict]:
    bills = calculate_bills(parse_readings(text), rates)
    fields = ['site', 'electric_kwh', 'water_l', 'electric_charge', 'water_charge', 'daily_fees', 'total']
    fd, temp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)))
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            writer = csv.writer(f)
            writer.writerow(fields)
            for b in bills:
                writer.writerow([b['site']] + [f'{b[k]:.2f}' for k in fields[1:]])
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return bills

