def publish_aqi(readings: list[dict], config: dict[str, str]) -> dict:
    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        station = reading.get('station')
        value = reading.get('pm25')
        if not isinstance(station, str) or not station:
            raise ValueError('invalid station')
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
            raise ValueError('invalid pm25')
        groups.setdefault(station, []).append(value)
    stations = []
    for station, values in groups.items():
        average = round(sum(values) / len(values), 2)
        aqi = min(500, math.floor(average * 4 + 0.5))
        stations.append({'station': station, 'average_pm25': average, 'aqi': aqi})
    stations.sort(key=lambda item: (-item['aqi'], item['station']))
    report = {'stations': stations}
    endpoint = config.get('endpoint') if isinstance(config, dict) else None
    token = config.get('api_token') if isinstance(config, dict) else None
    if not endpoint or not token:
        raise ValueError('endpoint and api_token are required')
    response = requests.post(endpoint, headers={'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}, json=report)
    response.raise_for_status()
    return response.json()

