        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    ordering = {'delivered_at': 'delivered_at DESC, id ASC', 'attempts': 'attempts DESC, id ASC', 'tracking_no': 'tracking_no ASC, id ASC', 'id': 'id DESC'}[sort_by]
    clauses = []
