        values.append(driver_id)
    if status is not None:
        clauses.append('status = ?')
        values.append(status)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = 'SELECT id, tracking_no, driver_id, status, delivered_at, attempts FROM deliveries' + where + ' ORDER BY ' + ordering + ' LIMIT ? OFFSET ?'
    values.extend([limit, offset])
    return [dict(zip(('id', 'tracking_no', 'driver_id', 'status', 'delivered_at', 'attempts'), row)) for row in conn.execute(query, values).fetchall()]

