import datetime
import json
import os

def _inside(base_dir, name):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, name))
    try:
        if os.path.commonpath([base, candidate]) != base:
            raise ValueError('path outside base directory')
    except ValueError:
        raise ValueError('path outside base directory')
    return candidate

def load_asset_report(base_dir: str, relative_name: str) -> list[dict]:
    path = _inside(base_dir, relative_name)
    with open(path, encoding='utf-8') as f:
        try:
            data = json.load(f)
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            raise ValueError('invalid report') from e
    if not isinstance(data, list):
        raise ValueError('invalid report')
    keys = {'asset_id', 'facility', 'category', 'status', 'observed_at'}
    for item in data:
        if not isinstance(item, dict) or set(item) != keys:
            raise ValueError('invalid record')
        if any((not isinstance(item[k], str) or not item[k] for k in keys)):
            raise ValueError('invalid record')
        if item['status'] not in {'active', 'repair', 'retired'}:
            raise ValueError('invalid status')
        try:
            datetime.date.fromisoformat(item['observed_at'])
        except ValueError as e:
            raise ValueError('invalid date') from e
        if len(item['observed_at']) != 10:
            raise ValueError('invalid date')
    return data

def summarize_assets(base_dir: str, report_names: list[str]) -> list[dict]:
    chosen = {}
    for report_index, name in enumerate(report_names):
        for item_index, item in enumerate(load_asset_report(base_dir, name)):
            key = item['asset_id']
            marker = (item['observed_at'], report_index, item_index)
            if key not in chosen or marker >= chosen[key][0]:
                chosen[key] = (marker, item)
    result = [value[1] for value in chosen.values()]
    result.sort(key=lambda x: (x['facility'], x['category'], x['asset_id']))
    return result

def write_asset_summary(base_dir: str, relative_name: str, summary: list[dict]) -> None:
    path = _inside(base_dir, relative_name)
    with open(path, 'w', encoding='utf-8') as f:
        f.write(json.dumps(summary, indent=2))
        f.write('\n')

