from lxml import etree

def _parse(xml):
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        return etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def parse_expense_report(xml: str) -> dict:
    root = _parse(xml)
    if root.tag != 'report' or not root.get('employee', '').strip():
        raise ValueError('invalid report')
    expenses = []
    ids = set()
    for node in root:
        if node.tag != 'expense':
            raise ValueError('unexpected element')
        required = ['id', 'date', 'category', 'amount', 'receipt']
        if any((not node.get(k, '').strip() for k in required)):
            raise ValueError('missing attribute')
        eid = node.get('id').strip()
        if eid in ids:
            raise ValueError('duplicate id')
        ids.add(eid)
        try:
            date.fromisoformat(node.get('date'))
            amount = Decimal(node.get('amount'))
        except (ValueError, InvalidOperation) as exc:
            raise ValueError('invalid value') from exc
        if amount <= 0 or amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        receipt = node.get('receipt')
        if receipt not in ('yes', 'no'):
            raise ValueError('invalid receipt')
        children = {}
        for child in node:
            if child.tag not in ('merchant', 'note') or child.tag in children:
                raise ValueError('unexpected child')
            children[child.tag] = ''.join(child.itertext()).strip()
        cents = int(amount * 100)
        expenses.append({'id': eid, 'date': node.get('date'), 'category': node.get('category').strip(), 'amount_cents': cents, 'receipt': receipt == 'yes', 'merchant': children.get('merchant', ''), 'note': children.get('note', '')})
    if not expenses:
        raise ValueError('empty report')
    return {'employee': root.get('employee').strip(), 'expenses': expenses, 'total_cents': sum((x['amount_cents'] for x in expenses))}

def approve_expense_report(xml: str, daily_limit_cents: int=100000, category_limits: dict[str, int] | None=None) -> dict:
    if isinstance(daily_limit_cents, bool) or not isinstance(daily_limit_cents, int) or daily_limit_cents < 0:
        raise ValueError('invalid limit')
    if category_limits is not None and any((isinstance(v, bool) or not isinstance(v, int) or v < 0 for v in category_limits.values())):
        raise ValueError('invalid limit')
    report = parse_expense_report(xml)
    by_date = {}
    by_category = {}
    reasons = set()
    for item in report['expenses']:
        by_date[item['date']] = by_date.get(item['date'], 0) + item['amount_cents']
        by_category[item['category']] = by_category.get(item['category'], 0) + item['amount_cents']
        if not item['receipt']:
            reasons.add('missing receipt: ' + item['id'])
    for day, total in by_date.items():
        if total > daily_limit_cents:
            reasons.add('daily limit exceeded: ' + day)
    for category, total in by_category.items():
        if category_limits and category in category_limits and (total > category_limits[category]):
            reasons.add('category limit exceeded: ' + category)
    return {'employee': report['employee'], 'approved': not reasons, 'total_cents': report['total_cents'], 'by_date': dict(sorted(by_date.items())), 'reasons': sorted(reasons)}

