from lxml import etree

def _read(xml):
    try:
        parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'reservations':
        raise ValueError('invalid root')
    result = []
    ids = set()
    for node in root:
        if node.tag != 'reservation':
            raise ValueError('invalid child')
        vals = {k: (node.get(k) or '').strip() for k in ('id', 'equipment', 'start', 'end', 'status')}
        if any((not v for v in vals.values())) or vals['id'] in ids or vals['status'] not in {'confirmed', 'cancelled', 'pending'}:
            raise ValueError('invalid reservation')
        ids.add(vals['id'])
        try:
            start = datetime.fromisoformat(vals['start'].replace('Z', '+00:00'))
            end = datetime.fromisoformat(vals['end'].replace('Z', '+00:00'))
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        if start.tzinfo is None or end.tzinfo is None or end <= start:
            raise ValueError('invalid interval')
        seconds = (end - start).total_seconds()
        if seconds % 60:
            raise ValueError('invalid duration')
        researchers = [x.text.strip() if x.text else '' for x in node if x.tag == 'researcher']
        purposes = [x.text.strip() if x.text else '' for x in node if x.tag == 'purpose']
        if len(researchers) != 1 or not researchers[0] or len(purposes) > 1:
            raise ValueError('invalid details')
        result.append({**vals, 'researcher': researchers[0], 'purpose': purposes[0] if purposes else '', 'minutes': int(seconds // 60), '_start': start, '_end': end})
    result.sort(key=lambda x: (x['_start'], x['equipment'], x['id']))
    for item in result:
        item.pop('_start')
        item.pop('_end')
    return result

def parse_reservations(xml: str) -> list[dict]:
    return _read(xml)

def daily_utilization(xml: str, day: str) -> dict:
    try:
        d = date.fromisoformat(day)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    lo = datetime.combine(d, datetime.min.time(), timezone.utc)
    hi = lo + timedelta(days=1)
    rows = _read(xml)
    groups = {}
    for row in rows:
        if row['status'] != 'confirmed':
            continue
        s = datetime.fromisoformat(row['start'].replace('Z', '+00:00')).astimezone(timezone.utc)
        e = datetime.fromisoformat(row['end'].replace('Z', '+00:00')).astimezone(timezone.utc)
        s, e = (max(s, lo), min(e, hi))
        if s < e:
            groups.setdefault(row['equipment'], []).append((s, e))
    output = {}
    total = 0
    for equipment in sorted(groups):
        spans = sorted(groups[equipment])
        merged = []
        for s, e in spans:
            if merged and s <= merged[-1][1]:
                merged[-1] = (merged[-1][0], max(merged[-1][1], e))
            else:
                merged.append((s, e))
        minutes = sum((int((e - s).total_seconds() // 60) for s, e in merged))
        events = sorted([(s, 1) for s, e in spans] + [(e, -1) for s, e in spans], key=lambda x: (x[0], x[1]))
        current = peak = 0
        for _, change in events:
            current += change
            peak = max(peak, current)
        output[equipment] = {'minutes': minutes, 'peak': peak}
        total += minutes
    return {'date': day, 'total_minutes': total, 'by_equipment': output}

