def _year_clause(year, column):
    if year is None:
        return ('', [])
    if not isinstance(year, int) or isinstance(year, bool) or (not 1 <= year <= 9999):
        raise ValueError('invalid year')
    return (f' and substr({column}, 1, 4) = ?', [f'{year:04d}'])

def list_members(conn: sqlite3.Connection, status: str | None=None, search: str='', sort: str='last_name', descending: bool=False, year: int | None=None) -> list[dict]:
    allowed = {'id', 'first_name', 'last_name', 'email', 'status', 'joined_year', 'total_paid', 'visit_count'}
    if sort not in allowed:
        raise ValueError('invalid sort')
    if not isinstance(search, str):
        raise TypeError('search must be a string')
    query = 'select id, first_name, last_name, email, status, joined_year from members where 1=1'
    params = []
    if status is not None:
        query += ' and status = ?'
        params.append(status)
    query += ' and (lower(first_name) like ? or lower(last_name) like ? or lower(email) like ?)'
    pattern = '%' + search.lower() + '%'
    params.extend([pattern, pattern, pattern])
    members = conn.execute(query, params).fetchall()
    result = []
    for m in members:
        pc, pp = _year_clause(year, 'paid_on')
        vc, vp = _year_clause(year, 'visited_on')
        paid = conn.execute('select coalesce(sum(amount), 0) from payments where member_id = ?' + pc, [m[0]] + pp).fetchone()[0]
        visits = conn.execute('select count(*) from visits where member_id = ?' + vc, [m[0]] + vp).fetchone()[0]
        result.append(dict(zip(('id', 'first_name', 'last_name', 'email', 'status', 'joined_year', 'total_paid', 'visit_count'), m + (paid, visits))))

    def key(row):
        value = row[sort]
        return value.lower() if isinstance(value, str) else value
    result.sort(key=lambda r: r['id'])
    result.sort(key=key, reverse=descending)
    return result

