    if not isinstance(member_id, int) or isinstance(member_id, bool):
        raise TypeError('member_id must be an integer')
    exists = conn.execute('select 1 from members where id = ?', (member_id,)).fetchone()
    if exists is None:
        raise LookupError('member not found')
    pc, pp = _year_clause(year, 'paid_on')
    vc, vp = _year_clause(year, 'visited_on')
    rows = conn.execute('select amount, paid_on from payments where member_id = ?' + pc, [member_id] + pp).fetchall()
    visits = conn.execute('select count(*) from visits where member_id = ?' + vc, [member_id] + vp).fetchone()[0]
    monthly = {}
    for amount, date in rows:
        monthly[date[5:7]] = monthly.get(date[5:7], 0) + amount
    return {'member_id': member_id, 'total_paid': sum((r[0] for r in rows)), 'payment_count': len(rows), 'visit_count': visits, 'monthly_paid': dict(sorted(monthly.items()))}

def record_payment(conn: sqlite3.Connection, member_id: int, amount: float, paid_on: str) -> None:
    if not isinstance(member_id, int) or isinstance(member_id, bool):
        raise TypeError('member_id must be an integer')
    if isinstance(amount, bool) or not isinstance(amount, (int, float)):
        raise TypeError('amount must be numeric')
    if not math.isfinite(amount) or amount <= 0:
        raise ValueError('invalid amount')
    if not isinstance(paid_on, str):
        raise TypeError('paid_on must be a string')
    try:
        parsed = datetime.date.fromisoformat(paid_on)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != paid_on:
        raise ValueError('invalid date')
    if conn.execute('select 1 from members where id = ?', (member_id,)).fetchone() is None:
        raise LookupError('member not found')
    conn.execute('insert into payments(member_id, amount, paid_on) values (?, ?, ?)', (member_id, round(amount, 2), paid_on))
