import subprocess
from datetime import datetime

def _parts(line):
    out, cur, esc = ([], [], False)
    for ch in line:
        if esc:
            if ch not in '\\|':
                raise ValueError('invalid escape')
            cur.append(ch)
            esc = False
        elif ch == '\\':
            esc = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if esc:
        raise ValueError('dangling escape')
    out.append(''.join(cur))
    return out

def parse_incident_line(line: str) -> dict:
    p = _parts(line.rstrip('\n'))
    if len(p) != 6 or not p[1] or (not p[2]):
        raise ValueError('bad record')
    try:
        datetime.fromisoformat(p[0])
        severity = int(p[3])
        duration = int(p[4])
    except Exception as e:
        raise ValueError('bad record') from e
    if not 1 <= severity <= 5 or duration < 0:
        raise ValueError('bad record')
    return {'timestamp': p[0], 'station': p[1], 'category': p[2], 'severity': severity, 'duration': duration, 'notes': p[5]}

def combine_incident_files(paths: list[str]) -> list[dict]:
    try:
        r = subprocess.run(['cat', *paths], check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as e:
        raise OSError('cannot read incident files') from e
    rows = [parse_incident_line(x) for x in r.stdout.splitlines() if x.strip()]
    return sorted(rows, key=lambda x: (x['timestamp'], x['station'], x['category']))

def build_shift_report(records: list[dict], start: str, end: str) -> dict:
    try:
        a, b = (datetime.fromisoformat(start), datetime.fromisoformat(end))
    except Exception as e:
        raise ValueError('bad bounds') from e
    if a >= b:
        raise ValueError('bad bounds')
    chosen = []
    for r in records:
        try:
            t = datetime.fromisoformat(r['timestamp'])
            if not r['station'] or not r['category'] or (not 1 <= r['severity'] <= 5) or (r['duration'] < 0):
                raise ValueError
        except Exception as e:
            raise ValueError('bad record') from e
        if a <= t < b:
            chosen.append(r)
    result = {'incident_count': len(chosen), 'total_duration': sum((x['duration'] for x in chosen)), 'highest_severity': max((x['severity'] for x in chosen), default=None), 'by_station': {}}
    for station in sorted({x['station'] for x in chosen}):
        group = [x for x in chosen if x['station'] == station]
        result['by_station'][station] = {'incident_count': len(group), 'total_duration': sum((x['duration'] for x in group)), 'highest_severity': max((x['severity'] for x in group)), 'categories': {c: sum((x['category'] == c for x in group)) for c in sorted({x['category'] for x in group})}}
    return result

