import os
import tempfile
import pytest

def make_file(text):
    f = tempfile.NamedTemporaryFile(mode='w', delete=False)
    try:
        f.write(text)
        return f.name
    finally:
        f.close()

def test_read_events_orders_records_and_converts_numbers():
    path = make_file('20|cab|pacman|8|3\n10|arcade2|pong|12|4\n10|arcade1|pong|7|2\n10|arcade1|asteroids|9|1\n')
    try:
        assert read_events(path) == [{'timestamp': 10, 'machine': 'arcade1', 'game': 'asteroids', 'score': 9, 'duration': 1}, {'timestamp': 10, 'machine': 'arcade1', 'game': 'pong', 'score': 7, 'duration': 2}, {'timestamp': 10, 'machine': 'arcade2', 'game': 'pong', 'score': 12, 'duration': 4}, {'timestamp': 20, 'machine': 'cab', 'game': 'pacman', 'score': 8, 'duration': 3}]
    finally:
        os.unlink(path)

def test_blank_lines_and_surrounding_whitespace_are_handled():
    path = make_file('\n  3 | cabinet | tetris | 14 | 6  \n\n')
    try:
        assert read_events(path) == [{'timestamp': 3, 'machine': 'cabinet', 'game': 'tetris', 'score': 14, 'duration': 6}]
    finally:
        os.unlink(path)

def test_invalid_records_raise_value_error():
    cases = ['1|m|g|2', 'x|m|g|2|1', '1||g|2|1', '1|m|g|-2|1', '1|m|g|2|0', '1|m|g|2|1|extra']
    for text in cases:
        path = make_file(text + '\n')
        try:
            with pytest.raises(ValueError):
                read_events(path)
        finally:
            os.unlink(path)

def test_summarize_aggregates_nested_machine_and_game_data():
    path = make_file('5|b|pong|20|2\n1|a|pong|7|3\n2|a|pong|11|4\n3|a|chess|9|5\n4|b|pong|4|1\n')
    try:
        result = summarize(path)
        assert result == {'machines': {'a': {'plays': 3, 'score': 27, 'games': {'chess': {'plays': 1, 'score': 9, 'best': 9}, 'pong': {'plays': 2, 'score': 18, 'best': 11}}}, 'b': {'plays': 2, 'score': 24, 'games': {'pong': {'plays': 2, 'score': 24, 'best': 20}}}}, 'leaderboard': [{'machine': 'b', 'game': 'pong', 'score': 24, 'plays': 2, 'best': 20}, {'machine': 'a', 'game': 'pong', 'score': 18, 'plays': 2, 'best': 11}, {'machine': 'a', 'game': 'chess', 'score': 9, 'plays': 1, 'best': 9}]}
    finally:
        os.unlink(path)

def test_leaderboard_limit_and_tie_breaking():
    path = make_file('1|z|a|10|1\n2|a|z|10|1\n3|b|q|10|1\n4|a|z|10|1\n')
    try:
        assert summarize(path, 2)['leaderboard'] == [{'machine': 'a', 'game': 'z', 'score': 20, 'plays': 2, 'best': 10}, {'machine': 'b', 'game': 'q', 'score': 10, 'plays': 1, 'best': 10}]
        assert summarize(path, 0)['leaderboard'] == []
    finally:
        os.unlink(path)

def test_negative_limit_is_rejected():
    path = make_file('1|m|g|1|1\n')
    try:
        with pytest.raises(ValueError):
            summarize(path, -1)
