from decimal import Decimal, InvalidOperation

def record_maintenance_fee_payment(requester: dict, patents: list[dict], patent_id: str, fee_year: int, amount: str, paid_on: str) -> dict:
    patent = next((item for item in patents if item.get('id') == patent_id), None)
    if patent is None:
        raise KeyError(patent_id)
    if requester.get('tenant_id') != patent.get('tenant_id') or not (requester.get('id') == patent.get('owner_id') or requester.get('role') == 'fee_officer'):
        raise PermissionError('not permitted')
    fee = next((item for item in patent.get('fees', []) if item.get('year') == fee_year), None)
    if fee is None:
        raise KeyError(fee_year)
    try:
        parsed_amount = Decimal(amount)
    except (InvalidOperation, TypeError):
        raise ValueError('invalid amount')
    if not parsed_amount.is_finite() or parsed_amount < 0 or parsed_amount.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    try:
        payment_date = date.fromisoformat(paid_on)
        due_date = date.fromisoformat(fee['due_date'])
    except (ValueError, TypeError, KeyError):
        raise ValueError('invalid date')
    if fee.get('paid'):
        raise ValueError('fee already paid')
    if parsed_amount != Decimal(fee['amount']):
        raise ValueError('amount mismatch')
    normalized = f'{parsed_amount:.2f}'
    fee['paid'] = True
    fee['paid_on'] = payment_date.isoformat()
    return {'patent_id': patent_id, 'fee_year': fee_year, 'amount': normalized, 'paid_on': payment_date.isoformat(), 'late': payment_date > due_date}

