import csv
import io
import os
import zipfile

def extract_and_summarize(zip_path: str, output_dir: str, member_name: str) -> dict:
    if not member_name:
        raise ValueError('member name is empty')
    with zipfile.ZipFile(zip_path) as archive:
        try:
            data = archive.read(member_name)
        except KeyError as exc:
            raise FileNotFoundError(member_name) from exc
    base = os.path.realpath(output_dir)
    target = os.path.realpath(os.path.join(base, member_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path outside output directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'wb') as stream:
        stream.write(data)
    required = ['home', 'away', 'round', 'date', 'home_score', 'away_score']
    reader = csv.DictReader(io.StringIO(data.decode('utf-8')))
    if reader.fieldnames is None or any((name not in reader.fieldnames for name in required)):
        raise ValueError('invalid header')
    fixtures = []
    teams = {}
    for row in reader:
        if any((row.get(name) in (None, '') for name in required)):
            raise ValueError('invalid row')
        if row['home'] == row['away']:
            raise ValueError('same team')
        try:
            hs, aws = (int(row['home_score']), int(row['away_score']))
        except ValueError as exc:
            raise ValueError('invalid score') from exc
        if hs < 0 or aws < 0:
            raise ValueError('invalid score')
        item = {'home': row['home'], 'away': row['away'], 'round': row['round'], 'date': row['date'], 'home_score': hs, 'away_score': aws}
        fixtures.append(item)
        for team in (row['home'], row['away']):
            teams.setdefault(team, [0, 0, 0, 0, 0, 0])
        h, a = (teams[row['home']], teams[row['away']])
        h[0] += 1
        a[0] += 1
        h[4] += hs
        h[5] += aws
        a[4] += aws
        a[5] += hs
        if hs > aws:
            h[1] += 1
            a[3] += 1
        elif hs < aws:
            a[1] += 1
            h[3] += 1
        else:
            h[2] += 1
            a[2] += 1
    fixtures.sort(key=lambda x: (x['date'], x['home'], x['away']))
    table = []
    for team, values in teams.items():
        p, w, d, l, gf, ga = values
        table.append({'team': team, 'played': p, 'wins': w, 'draws': d, 'losses': l, 'goals_for': gf, 'goals_against': ga, 'goal_difference': gf - ga, 'points': 3 * w + d})
    table.sort(key=lambda x: (-x['points'], -x['goal_difference'], -x['goals_for'], x['team']))
    return {'round': member_name, 'fixtures': fixtures, 'table': table}

