import re
from datetime import date
from lxml import etree

def _day(value):
    if not isinstance(value, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', value):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _clean(value):
    return ' '.join(value.split())

def extract_clauses(xml_text: str, as_of: str | None=None) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'contract':
        raise ValueError('wrong root')
    limit = _day(as_of) if as_of is not None else None
    found = []
    order = 0

    def section_key(path):
        return tuple(((0, int(x)) if x.isdigit() else (1, x) for x in path.split('.')))

    def walk_section(node, codes, titles):
        nonlocal order
        code = node.get('code')
        if not code:
            raise ValueError('invalid section')
        codes = codes + [code]
        title = node.get('title')
        titles = titles + ([title] if title else [])
        for child in node:
            if child.tag == 'clause':
                cid = child.get('id')
                effective = child.get('effective')
                priority = child.get('priority')
                if not cid or effective is None or priority is None:
                    raise ValueError('invalid clause')
                when = _day(effective)
                try:
                    rank = int(priority)
                except Exception as exc:
                    raise ValueError('invalid priority') from exc
                if limit is not None and when > limit or child.get('status') == 'retired':
                    order += 1
                    continue
                paragraphs = []
                tags = []
                for sub in child:
                    if sub.tag == 'p':
                        paragraphs.append(_clean(''.join(sub.itertext())))
                    elif sub.tag == 'tag':
                        name = sub.get('name')
                        if not name:
                            raise ValueError('invalid tag')
                        tags.append(name)
                    else:
                        raise ValueError('invalid clause child')
                found.append({'id': cid, 'section': '.'.join(codes), 'section_title': ' > '.join(titles), 'effective': effective, 'priority': rank, 'text': _clean(' '.join(paragraphs)), 'tags': tags, '_date': when, '_order': order})
                order += 1
            elif child.tag == 'section':
                walk_section(child, codes, titles)
            else:
                raise ValueError('invalid section child')
    for child in root:
        if child.tag != 'section':
            raise ValueError('invalid contract child')
        walk_section(child, [], [])
    selected = {}
    for item in found:
        old = selected.get(item['id'])
        if old is None or (item['_date'], item['_order']) >= (old['_date'], old['_order']):
            selected[item['id']] = item
    result = list(selected.values())
    result.sort(key=lambda x: (section_key(x['section']), -x['priority'], -x['_date'].toordinal(), x['id']))
    for item in result:
        del item['_date']
        del item['_order']
    return result

def clause_digest(clauses: list[dict]) -> list[dict]:
    groups = {}
    for clause in clauses:
        section = clause['section']
        if section not in groups:
            groups[section] = {'section': section, 'count': 0, 'ids': [], 'text': []}
        group = groups[section]
        group['count'] += 1
        group['ids'].append(clause['id'])
        group['text'].append(clause['text'])
    result = list(groups.values())
    for group in result:
        group['text'] = ' | '.join(group['text'])
    return result

