def build_repair_area_page(requests: list[dict], page: int, page_size: int) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ23456789'
    for item in requests:
        try:
            neighborhood = item['neighborhood']
            status = item['status']
            severity = item['severity']
            cost = item['estimated_cost']
        except (KeyError, TypeError):
            raise ValueError('invalid request')
        if not isinstance(neighborhood, str) or not neighborhood.strip():
            raise ValueError('invalid neighborhood')
        if status not in ('open', 'closed'):
            raise ValueError('invalid status')
        if isinstance(severity, bool) or not isinstance(severity, int) or (not 1 <= severity <= 5):
            raise ValueError('invalid severity')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        if status == 'open':
            key = neighborhood.strip().casefold()
            if key not in groups:
                groups[key] = [neighborhood.strip(), 0, 0.0, 0]
            group = groups[key]
            group[1] += 1
            group[2] += cost
            group[3] = max(group[3], severity)
    summaries = []
    for name, count, total, highest in groups.values():
        code = ''.join((secrets.choice(alphabet) for _ in range(12)))
        summaries.append({'neighborhood': name, 'open_requests': count, 'total_estimated_cost': round(total, 2), 'highest_severity': highest, 'crew_code': code})
    summaries.sort(key=lambda x: (-x['highest_severity'], -x['total_estimated_cost'], x['neighborhood'].casefold()))
    start = (page - 1) * page_size
    return summaries[start:start + page_size]

