from solution import rank_signed_reputation
import hashlib
import hmac
import json
import pytest


def signed(payload, secret="forum-key"):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_empty_votes_returns_empty_list():
    payload = '{"votes": []}'
    assert rank_signed_reputation(payload, signed(payload), "forum-key") == []


def test_aggregates_votes_and_orders_by_score_then_post_id():
    payload = json.dumps({"votes": [
        {"username": "a", "post_id": 8, "value": 1},
        {"username": "b", "post_id": 3, "value": 1},
        {"username": "c", "post_id": 8, "value": -1},
        {"username": "d", "post_id": 3, "value": 1},
        {"username": "e", "post_id": 5, "value": 0}
    ]})
    payload = json.dumps({"votes": [
        {"username": "a", "post_id": 8, "value": 1},
        {"username": "b", "post_id": 3, "value": 1},
        {"username": "c", "post_id": 8, "value": -1},
        {"username": "d", "post_id": 3, "value": 1}
    ]})
    assert rank_signed_reputation(payload, signed(payload), "forum-key") == [
        {"post_id": 3, "score": 2, "votes": 2},
        {"post_id": 8, "score": 0, "votes": 2}
    ]


def test_ties_use_ascending_post_id():
    payload = '{"votes":[{"username":"x","post_id":20,"value":1},{"username":"y","post_id":4,"value":1}]}'
    assert rank_signed_reputation(payload, signed(payload), "forum-key") == [
        {"post_id": 4, "score": 1, "votes": 1},
        {"post_id": 20, "score": 1, "votes": 1}
    ]


def test_pagination_is_one_based_and_applied_after_sorting():
    payload = json.dumps({"votes": [
        {"username": "a", "post_id": 1, "value": 1},
        {"username": "b", "post_id": 2, "value": 1},
        {"username": "c", "post_id": 3, "value": 1},
        {"username": "d", "post_id": 4, "value": 1}
    ]})
    assert rank_signed_reputation(payload, signed(payload), "forum-key", 2, 2) == [
        {"post_id": 3, "score": 1, "votes": 1},
        {"post_id": 4, "score": 1, "votes": 1}
    ]
    assert rank_signed_reputation(payload, signed(payload), "forum-key", 3, 2) == []


def test_wrong_signature_raises_value_error():
    payload = '{"votes":[]}'
