import hashlib
import hmac
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def _money(value):
    try:
        number = Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid price')
    if not number.is_finite() or number < 0:
        raise ValueError('invalid price')
    return number.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def _text_money(value):
    return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')

def calculate_invoice(order: dict, config: dict) -> dict:
    if not isinstance(order.get('order_id'), str) or not isinstance(order.get('customer_state'), str):
        raise ValueError('invalid order')
    state = order['customer_state']
    if state not in config.get('tax_rates', {}):
        raise ValueError('unknown customer state')
    if 'signing_key' not in config:
        raise ValueError('signing_key is required')
    try:
        rate = Decimal(str(config['tax_rates'][state]))
    except (InvalidOperation, ValueError):
        raise ValueError('invalid tax rate')
    exempt = set(config.get('exempt_categories', []))
    lines = []
    subtotal = Decimal('0')
    tax_total = Decimal('0')
    for item in order.get('items', []):
        for field in ('sku', 'category', 'unit_price', 'quantity', 'taxable'):
            if field not in item:
                raise ValueError('missing item field')
        if not isinstance(item['quantity'], int) or isinstance(item['quantity'], bool) or item['quantity'] < 1:
            raise ValueError('invalid quantity')
        unit = _money(item['unit_price'])
        line_subtotal = unit * item['quantity']
        taxable = bool(item['taxable']) and item['category'] not in exempt
        line_rate = rate if taxable else Decimal('0')
        line_tax = (line_subtotal * line_rate).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        subtotal += line_subtotal
        tax_total += line_tax
        lines.append({'sku': item['sku'], 'category': item['category'], 'quantity': item['quantity'], 'unit_price': _text_money(unit), 'subtotal': _text_money(line_subtotal), 'tax_rate': format(line_rate, '.4f'), 'tax': _text_money(line_tax), 'taxable': taxable})
    result = {'order_id': order['order_id'], 'state': state, 'lines': lines, 'subtotal': _text_money(subtotal), 'tax': _text_money(tax_total), 'total': _text_money(subtotal + tax_total)}
    payload = json.dumps(result, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    result['signature'] = hmac.new(str(config['signing_key']).encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return result

