    rows = list(csv.reader(io.StringIO(text)))
    if not rows:
        return []
    if rows[0] != ['student', 'stop', 'grade', 'priority']:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        student, stop, grade, priority = [x.strip() for x in row]
        if not student or not stop or student in seen:
            raise ValueError('invalid student')
        try:
            grade_i = int(grade)
            priority_i = int(priority)
        except ValueError:
            raise ValueError('invalid number')
        if not 0 <= grade_i <= 12 or priority_i < 0:
            raise ValueError('invalid number')
        seen.add(student)
        result.append({'student': student, 'stop': stop, 'grade': grade_i, 'priority': priority_i})
    return result

def build_routes(roster: list[dict], stop_order: list[str], capacity: int) -> list[dict]:
    if capacity <= 0 or len(set(stop_order)) != len(stop_order):
        raise ValueError('invalid route configuration')
    allowed = set(stop_order)
    if any((row['stop'] not in allowed for row in roster)):
        raise ValueError('unknown stop')
    result = []
    number = 1
    for stop in stop_order:
        group = [row for row in roster if row['stop'] == stop]
        group.sort(key=lambda r: (-r['priority'], r['grade'], r['student']))
        for start in range(0, len(group), capacity):
            result.append({'route': number, 'stop': stop, 'students': [r['student'] for r in group[start:start + capacity]]})
            number += 1
    return result

def export_routes(routes: list[dict], destination: str) -> int:
