            mass = measurement['mass_kg']
            quality = measurement['quality_score']
            if not math.isfinite(mass) or not math.isfinite(quality) or mass < 0 or (quality < 0):
                raise ValueError('invalid measurement')
            measurements.append((mass, quality))
        allowed = record['tenant_id'] == requester['tenant_id'] and (record['owner_id'] == requester['id'] or bool(set(requester['roles']) & {'plant_manager', 'quality_manager'}))
        if allowed and (status is None or record['status'] == status):
            selected.append((record, when, measurements))
    selected.sort(key=lambda x: (-x[1].timestamp(), x[0]['batch_id']))
    start = (page - 1) * page_size
    items = []
    for record, _, measurements in selected[start:start + page_size]:
