import csv
import os
import tempfile
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def export_policy_quotes(policies: list[dict], destination: str, page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page <= 0) or (page_size <= 0):
        raise ValueError('invalid pagination')
    active = []
    for policy in policies:
        try:
            policy_id = policy['policy_id']
            customer = policy['customer']
            raw_premium = policy['annual_premium']
            status = policy['status']
            premium = Decimal(str(raw_premium))
        except (KeyError, InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid policy')
        if not premium.is_finite() or premium < 0:
            raise ValueError('invalid premium')
        if status == 'active':
            active.append((premium, str(policy_id), str(customer), str(status)))
    active.sort(key=lambda item: (-item[0], item[1]))
    total = len(active)
    pages = max(1, (total + page_size - 1) // page_size)
    selected = active[(page - 1) * page_size:page * page_size] if page <= pages else []
    quantized = [item[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP) for item in selected]
    page_total = sum(quantized, Decimal('0.00'))
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.quote-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['policy_id', 'customer', 'premium', 'status'])
            for item, premium in zip(selected, quantized):
                writer.writerow([item[1], item[2], format(premium, '.2f'), item[3]])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'total': total, 'pages': pages, 'page': page, 'page_total': format(page_total, '.2f')}

