import csv
import math
import os
import tempfile

def parse_events(lines):
    reader = csv.reader(lines)
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError('empty input')
    if header != ['timestamp', 'key', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in reader:
        if len(row) != 3:
            raise ValueError('invalid row')
        try:
            timestamp = float(row[0])
            status = int(row[2])
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if not math.isfinite(timestamp) or not row[1] or (not 100 <= status <= 599):
            raise ValueError('invalid value')
        result.append({'timestamp': timestamp, 'key': row[1], 'status': status})
    return result

def rate_report(events, window_seconds, limit):
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, (int, float)) or (not math.isfinite(window_seconds)) or (window_seconds <= 0):
        raise ValueError('invalid window')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    groups = {}
    for event in events:
        start = math.floor(event['timestamp'] / window_seconds) * window_seconds
        if float(start).is_integer():
            start = int(start)
        key = event['key']
        item = groups.setdefault((start, key), [0, 0])
        item[0] += 1
        if event['status'] >= 400:
            item[1] += 1
    result = []
    for (start, key), (count, errors) in groups.items():
        result.append({'window_start': start, 'key': key, 'count': count, 'errors': errors, 'limited': count > limit})
    result.sort(key=lambda x: (x['window_start'], -x['count'], x['key']))
    return result

def export_report(events, window_seconds, limit, output_path):
    report = rate_report(events, window_seconds, limit)
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.report-')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['window_start', 'key', 'count', 'errors', 'limited'])
            for item in report:
                writer.writerow([item['window_start'], item['key'], item['count'], item['errors'], item['limited']])
        os.replace(temporary, output_path)
    except BaseException:
        try:
            os.unlink(temporary)
        except OSError:
            pass
        raise
    return len(report)

