import csv
import io
import math
import secrets
from datetime import date, timedelta
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def generate_invite_code(site_id: str, length: int=12) -> str:
    if not isinstance(site_id, str) or not site_id or any((c not in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_' for c in site_id)):
        raise ValueError('invalid site')
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    return site_id + ':' + ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _day(value):
    try:
        parsed = date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def parse_survey_log(text: str) -> list[tuple[str, str, float]]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    lines = [line for line in text.splitlines() if line.strip()]
    if not lines or lines[0] != 'date,site,erosion_cm':
        raise ValueError('bad header')
    result = []
    for line in lines[1:]:
        try:
            fields = next(csv.reader([line]))
        except Exception as exc:
            raise ValueError('bad row') from exc
        if len(fields) != 3:
            raise ValueError('bad row')
        day, site, raw = fields
        _day(day)
        site = site.strip()
        try:
            amount = float(raw)
        except Exception as exc:
            raise ValueError('bad measurement') from exc
        if not site or not math.isfinite(amount) or amount < 0:
            raise ValueError('bad row')
        result.append((day, site, amount))
    return result

def rolling_erosion_summary(records: list[tuple[str, str, float]], window_days: int=3) -> dict[str, list[dict[str, object]]]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or (not 1 <= window_days <= 31):
        raise ValueError('invalid window')
    grouped = {}
    for record in records:
        if not isinstance(record, (tuple, list)) or len(record) != 3:
            raise ValueError('bad record')
        raw_day, site, amount = record
        day = _day(raw_day)
        if not isinstance(site, str) or not site:
            raise ValueError('bad site')
        if not isinstance(amount, (int, float)) or isinstance(amount, bool) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('bad amount')
        grouped.setdefault(site, {}).setdefault(day, []).append(float(amount))
    output = {}
    for site in sorted(grouped):
        days = grouped[site]
        entries = []
        for end in sorted(days):
            selected = [v for day, values in days.items() if end - timedelta(days=window_days - 1) <= day <= end for v in values]
            entries.append({'date': end.isoformat(), 'mean': round(sum(selected) / len(selected), 3), 'count': len(days[end])})
        output[site] = entries
    return output

