import ast
import operator

def _evaluate(text, names):
    tree = ast.parse(text, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in ('min', 'max', 'round'):
                return node.id
            if node.id not in names:
                raise NameError(node.id)
            return names[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None or not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('unsupported expression')
    return visit(tree)

def select_excursions(excursions: list[dict], rule: str, score: str, variables: dict[str, int | float], limit: int) -> list[dict]:
    candidates = []
    for item in excursions:
        names = dict(variables)
        names.update({k: v for k, v in item.items() if k != 'id' and k != 'port'})
        if _evaluate(rule, names) and item['booked'] < item['capacity']:
            value = _evaluate(score, names)
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise TypeError('score must be numeric')
            candidates.append((value, item))
    candidates.sort(key=lambda x: (-x[0], x[1]['price'], x[1]['start'], x[1]['id']))
    accepted = []
    for value, item in candidates:
        if len(accepted) >= limit:
            break
        end = item['start'] + item['duration']
        if all((x['port'] != item['port'] or end <= x['start'] or item['start'] >= x['end'] for x in accepted)):
            accepted.append({'id': item['id'], 'port': item['port'], 'start': item['start'], 'end': end, 'score': value})
    return sorted(accepted, key=lambda x: (x['start'], x['port'], x['id']))

def summarize_ports(excursions: list[dict]) -> dict[str, dict[str, int | float]]:
    result = {}
    for item in excursions:
        port = item['port']
        if port not in result:
            result[port] = {'count': 0, 'total_capacity': 0, 'total_booked': 0, 'average_price': 0.0}
        row = result[port]
        row['count'] += 1
        row['total_capacity'] += item['capacity']
        row['total_booked'] += item['booked']
        row['average_price'] += item['price']
    for row in result.values():
        row['average_price'] /= row['count']
    return result

