import hashlib
import hmac
import json
import pytest
from solution import SIGNING_SECRET, summarize_registrations

def signed(payload):
    return hmac.new(SIGNING_SECRET, payload.encode('utf-8'), hashlib.sha256).hexdigest()

def make_payload(records):
    return json.dumps({'registrations': records}, separators=(',', ':'))

def test_empty_batch():
    payload = make_payload([])
    assert summarize_registrations(payload, signed(payload)) == {'total': 0, 'by_precinct': []}

def test_groups_counts_and_sorting():
    records = [{'voter_id': 'v3', 'precinct': 'Z-2', 'status': 'rejected'}, {'voter_id': 'v1', 'precinct': 'A-10', 'status': 'registered'}, {'voter_id': 'v2', 'precinct': 'A-2', 'status': 'pending'}, {'voter_id': 'v4', 'precinct': 'A-2', 'status': 'registered'}, {'voter_id': 'v5', 'precinct': 'A-10', 'status': 'rejected'}]
    payload = make_payload(records)
    assert summarize_registrations(payload, signed(payload)) == {'total': 5, 'by_precinct': [{'precinct': 'A-10', 'registered': 1, 'pending': 0, 'rejected': 1}, {'precinct': 'A-2', 'registered': 1, 'pending': 1, 'rejected': 0}, {'precinct': 'Z-2', 'registered': 0, 'pending': 0, 'rejected': 1}]}

def test_signature_rejection():
    payload = make_payload([])
    assert summarize_registrations(payload, '0' * 64) is None
    assert summarize_registrations(payload, 'not-a-digest') is None
    assert summarize_registrations(payload, None) is None

def test_signature_uses_exact_payload_bytes():
    payload = make_payload([])
    altered = payload + ' '
    assert summarize_registrations(altered, signed(payload)) is None

def test_invalid_json_raises_after_valid_signature():
    payload = 'not json'
    with pytest.raises(ValueError):
        summarize_registrations(payload, signed(payload))

def test_invalid_shapes_and_values_raise():
    cases = ['[]', json.dumps({}), json.dumps({'registrations': {}}), json.dumps({'registrations': [{'voter_id': 'x', 'precinct': 'P', 'status': 'bad'}]}), json.dumps({'registrations': [{'voter_id': '', 'precinct': 'P', 'status': 'pending'}]}), json.dumps({'registrations': [{'voter_id': 'x', 'precinct': '', 'status': 'pending'}]}), json.dumps({'registrations': [None]})]
    for payload in cases:
        with pytest.raises(ValueError):
            summarize_registrations(payload, signed(payload))

def test_extra_fields_are_ignored():
    payload = make_payload([{'voter_id': 'x', 'precinct': 'P', 'status': 'registered', 'submitted_by': 'clerk'}])
    assert summarize_registrations(payload, signed(payload)) == {'total': 1, 'by_precinct': [{'precinct': 'P', 'registered': 1, 'pending': 0, 'rejected': 0}]}

