import ast
import math

class _Evaluator(ast.NodeVisitor):

    def __init__(self, variables):
        self.variables = variables

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float, bool)) and (not isinstance(node.value, complex)):
            return node.value
        raise ValueError()

    def visit_Name(self, node):
        if node.id in self.variables:
            return self.variables[node.id]
        if node.id in ('True', 'False'):
            return node.id == 'True'
        raise ValueError()

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError()

    def visit_BinOp(self, node):
        left, right = (self.visit(node.left), self.visit(node.right))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        raise ValueError()

    def visit_BoolOp(self, node):
        if isinstance(node.op, ast.And):
            value = True
            for item in node.values:
                value = self.visit(item)
                if not value:
                    return value
            return value
        if isinstance(node.op, ast.Or):
            value = False
            for item in node.values:
                value = self.visit(item)
                if value:
                    return value
            return value
        raise ValueError()

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, item in zip(node.ops, node.comparators):
            right = self.visit(item)
            if isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            elif isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            else:
                raise ValueError()
            if not ok:
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.keywords:
            raise ValueError()
        if node.func.id not in ('min', 'max', 'round'):
            raise ValueError()
        args = [self.visit(x) for x in node.args]
        if node.func.id == 'round':
            if len(args) not in (1, 2):
                raise ValueError()
            return round(*args)
        if not args:
            raise ValueError()
        return min(args) if node.func.id == 'min' else max(args)

    def generic_visit(self, node):
        raise ValueError()

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    try:
        tree = ast.parse(expression, mode='eval')
        return _Evaluator(variables).visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def _number(value):
    return isinstance(value, (int, float)) and (not isinstance(value, bool)) and math.isfinite(value)

def plan_allocation(requests, available, eligibility, score):
    if not _number(available) or available < 0 or (not isinstance(requests, list)):
        raise ValueError()
    rows = []
    seen = set()
    for request in requests:
        if not isinstance(request, dict) or set(request) != {'id', 'demand', 'priority', 'efficiency'}:
            raise ValueError()
        ident = request['id']
        if not isinstance(ident, str) or ident in seen:
            raise ValueError()
        seen.add(ident)
        if not _number(request['demand']) or request['demand'] < 0 or (not _number(request['priority'])) or (not _number(request['efficiency'])):
            raise ValueError()
        variables = {k: request[k] for k in ('demand', 'priority', 'efficiency')}
        if evaluate_expression(eligibility, variables):
            value = evaluate_expression(score, variables)
            if not _number(value):
                raise ValueError()
            rows.append((value, request['priority'], ident, request, value))
    rows.sort(key=lambda x: (-x[0], -x[1], x[2]))
    result, remaining = ([], available)
    for _, _, _, request, value in rows:
        amount = min(request['demand'], remaining)
        result.append({**request, 'score': value, 'allocation': amount})
        remaining -= amount
    return result

