from datetime import datetime

def parse_traceability_report(xml_text: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'traceability':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'batch':
            continue
        bid = node.get('id', '').strip()
        product = node.get('product', '').strip()
        if not bid or not product or bid in seen:
            raise ValueError('invalid batch')
        try:
            quantity = int(node.get('quantity', ''))
        except Exception as exc:
            raise ValueError('invalid quantity') from exc
        if quantity <= 0:
            raise ValueError('invalid quantity')
        seen.add(bid)
        materials = []
        events = []
        for child in node:
            if child.tag == 'material':
                lot = child.get('lot', '').strip()
                try:
                    amount = int(child.get('quantity', ''))
                except Exception as exc:
                    raise ValueError('invalid material') from exc
                if not lot or amount <= 0:
                    raise ValueError('invalid material')
                materials.append({'lot': lot, 'quantity': amount})
            elif child.tag == 'event':
                try:
                    seq = int(child.get('seq', ''))
                    datetime.fromisoformat(child.get('timestamp', '').replace('Z', '+00:00'))
                except Exception as exc:
                    raise ValueError('invalid event') from exc
                station = child.get('station', '').strip()
                status = child.get('status', '')
                timestamp = child.get('timestamp', '')
                if seq <= 0 or not station or status not in {'started', 'in_process', 'completed', 'rejected'}:
                    raise ValueError('invalid event')
                events.append({'seq': seq, 'station': station, 'status': status, 'timestamp': timestamp})
        events.sort(key=lambda x: x['seq'])
        for index, event in enumerate(events, 1):
            if event['seq'] != index:
                raise ValueError('invalid sequence')
            if index > 1:
                previous = datetime.fromisoformat(events[index - 2]['timestamp'].replace('Z', '+00:00'))
                current = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
                if current < previous:
                    raise ValueError('invalid time order')
        result.append({'batch_id': bid, 'product': product, 'quantity': quantity, 'materials': materials, 'events': events})
    result.sort(key=lambda x: x['batch_id'])
    return result

def summarize_traceability(batches: list[dict]) -> dict:
    products = {}
    stations = {}
    completed = 0
    total = 0
    for batch in batches:
        total += batch['quantity']
        products[batch['product']] = products.get(batch['product'], 0) + batch['quantity']
        for event in batch['events']:
            stations[event['station']] = stations.get(event['station'], 0) + 1
        if batch['events'] and batch['events'][-1]['status'] == 'completed':
            completed += 1
    return {'total_quantity': total, 'by_product': dict(sorted(products.items())), 'station_events': dict(sorted(stations.items())), 'completed_batches': completed}

