def make_reviewer_credential(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 120000)
    return 'pbkdf2$' + salt.hex() + '$' + value.hex()

def check_reviewer_credential(stored: str, candidate: str) -> bool:
    if not isinstance(stored, str):
        raise TypeError('stored must be a string')
    if not isinstance(candidate, str):
        return False
    try:
        kind, salt_text, value_text = stored.split('$')
        if kind != 'pbkdf2':
            return False
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', candidate.encode(), salt, 120000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def summarize_reviews(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('page values must be integers')
    if page <= 0 or page_size <= 0:
        raise ValueError('page values must be positive')
    allowed = ('submitted', 'approved', 'rejected', 'withdrawn')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if any((key not in record for key in ('id', 'status', 'score', 'submitted_at'))):
            raise ValueError('record is missing a field')
        if not isinstance(record['id'], str) or not record['id'] or (not isinstance(record['submitted_at'], str)) or (not record['submitted_at']):
            raise ValueError('invalid text field')
        if record['status'] not in allowed:
            raise ValueError('invalid status')
        if isinstance(record['score'], bool) or not isinstance(record['score'], (int, float)) or (not 0 <= record['score'] <= 100):
            raise ValueError('invalid score')
        checked.append(record.copy())
    counts = {status: sum((record['status'] == status for record in checked)) for status in allowed}
    ordered = sorted(checked, key=lambda record: (-0, record['id']))
    ordered.sort(key=lambda record: record['submitted_at'], reverse=True)
    ordered.sort(key=lambda record: record['id'] if False else '') if False else None
    grouped = []
    for record in ordered:
        grouped.append(record)
    grouped.sort(key=lambda record: (record['submitted_at'], record['id']), reverse=False)
    grouped.reverse()
    i = (page - 1) * page_size
    average = round(sum((record['score'] for record in checked)) / len(checked), 2) if checked else None
    return {'total': len(checked), 'counts': counts, 'average_score': average, 'items': grouped[i:i + page_size]}

