import hashlib
import hmac
import json
import pytest

def make_packet(body, secret=b'school-key'):
    signature = hmac.new(secret, body, hashlib.sha256).hexdigest()
    return b'X-Signature: ' + signature.encode('ascii') + b'\n\n' + body

def test_verify_valid_packet_returns_exact_json():
    body = b'{"school":"North","sections":[],"requests":[]}'
    assert verify_enrollment_packet(make_packet(body), b'school-key') == {'school': 'North', 'sections': [], 'requests': []}

def test_verify_preserves_nested_values_and_whitespace():
    body = b'{ "school" : "East", "sections" : [], "requests" : [], "note" : "a  b" }'
    result = verify_enrollment_packet(make_packet(body), b'school-key')
    assert result['school'] == 'East'
    assert result['note'] == 'a  b'
    assert list(result) == ['school', 'sections', 'requests', 'note']

def test_verify_rejects_wrong_secret_and_malformed_packets():
    body = b'{"school":"N","sections":[],"requests":[]}'
    cases = [make_packet(body, b'other'), b'X-Signature: ' + b'0' * 64 + b'\n\n' + body, b'X-Signature: ' + b'g' * 64 + b'\n\n' + body, b'X-Signature: ' + hmac.new(b'school-key', body, hashlib.sha256).hexdigest().upper().encode() + b'\n\n' + body, b'X-Signature: ' + hmac.new(b'school-key', body, hashlib.sha256).hexdigest().encode() + b'\n' + body, b'X-Signature: ' + hmac.new(b'school-key', body, hashlib.sha256).hexdigest().encode() + b'\n\nnot-json']
    for packet in cases:
        with pytest.raises(ValueError):
            verify_enrollment_packet(packet, b'school-key')

def test_allocation_handles_empty_sections_and_zero_capacity():
    payload = {'school': 'West', 'sections': [{'id': 'X', 'course': 'Science', 'capacity': 0}], 'requests': [{'student': 'A', 'choices': ['X']}]}
    assert allocate_enrollment(payload) == {'school': 'West', 'placements': [{'section': 'X', 'students': []}], 'unassigned': ['A']}

