    base = {'school': 'S', 'sections': [{'id': 'A', 'course': 'C', 'capacity': 1}], 'requests': []}
    bad = [{**base, 'sections': base['sections'] + [{'id': 'A', 'course': 'D', 'capacity': 1}]}, {**base, 'requests': [{'student': 'x', 'choices': ['Q']}]}, {**base, 'requests': [{'student': 'x', 'choices': []}]}, {**base, 'requests': [{'student': 'x', 'choices': ['A']}, {'student': 'x', 'choices': ['A']}]}, {**base, 'sections': [{'id': 'A', 'course': 'C', 'capacity': True}]}]
