    if set(data) != required:
        raise ValueError('invalid save')
    if not isinstance(data['player'], str) or not data['player']:
        raise ValueError('invalid save')
    for key in ('updated', 'level', 'score'):
        if isinstance(data[key], bool) or not isinstance(data[key], int) or data[key] < 0:
            raise ValueError('invalid save')
    if not isinstance(data['items'], list) or not all((isinstance(x, str) for x in data['items'])):
        raise ValueError('invalid save')
    return {'player': data['player'], 'updated': data['updated'], 'level': data['level'], 'score': data['score'], 'items': sorted(set(data['items']))}

def merge_save_records(records: list[dict]) -> list[dict]:
    chosen = {}
    for record in records:
        item = normalize_save(record)
        key = (item['updated'], item['level'], item['score'], item['items'])
        old = chosen.get(item['player'])
        if old is None or key > (old['updated'], old['level'], old['score'], old['items']):
            chosen[item['player']] = item
    return sorted(chosen.values(), key=lambda x: (-x['updated'], x['player']))

def sync_save_archive(archive_path: str, base_dir: str) -> dict:
