def write_contact_report(base_dir: str, relative_name: str, contacts: list[dict], page: int=1, page_size: int=50) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid output name')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    if not isinstance(contacts, list):
        raise ValueError('invalid contacts')
    chosen = {}
    for index, contact in enumerate(contacts):
        if not isinstance(contact, dict) or any((not isinstance(contact.get(k), str) for k in ('id', 'name', 'email', 'company', 'updated'))):
            raise ValueError('invalid contact')
        email = contact['email'].strip()
        if not email:
            raise ValueError('empty email')
        try:
            stamp = datetime.datetime.fromisoformat(contact['updated'])
        except ValueError:
            raise ValueError('invalid date')
        key = email.casefold()
        score = (stamp, sum((bool(contact[k].strip()) for k in ('name', 'company'))), -index)
        if key not in chosen or score > chosen[key][0]:
            chosen[key] = (score, contact)
    ordered = [chosen[key][1] for key in sorted(chosen)]
    start = (page - 1) * page_size
    payload = {'total': len(ordered), 'page': page, 'page_size': page_size, 'contacts': ordered[start:start + page_size]}
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        inside = os.path.commonpath((base, target)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('invalid output name')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(payload, handle, ensure_ascii=False, indent=2)
        handle.write('\n')
    return target

