import csv
import math
import os
import tempfile
from datetime import date

def parse_record(record: dict) -> dict:
    try:
        required = ['mission_id', 'diplomat', 'country', 'departure', 'return', 'expenses', 'clearance']
        if any((k not in record for k in required)):
            raise ValueError
        text = {k: record[k] for k in ('mission_id', 'diplomat', 'country', 'departure', 'return')}
        if any((not isinstance(v, str) or not v for v in text.values())):
            raise ValueError
        if record['clearance'] not in ('cleared', 'pending'):
            raise ValueError
        start = date.fromisoformat(record['departure'])
        end = date.fromisoformat(record['return'])
        if start.isoformat() != record['departure'] or end.isoformat() != record['return'] or end < start:
            raise ValueError
        expenses = record['expenses']
        if not isinstance(expenses, list):
            raise ValueError
        total = 0.0
        for item in expenses:
            if isinstance(item, bool) or not isinstance(item, (int, float)) or (not math.isfinite(item)) or (item < 0):
                raise ValueError
            total += item
        return {**text, 'clearance': record['clearance'], 'days': (end - start).days, 'expense_total': total}
    except (KeyError, TypeError, OverflowError, ValueError):
        raise ValueError('invalid record')

def export_travel_report(records: list[dict], output_path: str) -> dict:
    parsed = []
    seen = set()
    for record in records:
        item = parse_record(record)
        if item['mission_id'] in seen:
            raise ValueError('duplicate mission')
        seen.add(item['mission_id'])
        if item['clearance'] == 'cleared':
            parsed.append(item)
    parsed.sort(key=lambda x: (x['country'], x['departure'], x['diplomat'], x['mission_id']))
    summary = {'missions': len(parsed), 'expenses': 0.0, 'countries': {}}
    for item in parsed:
        total = round(item['expense_total'], 2)
        summary['expenses'] += total
        country = item['country']
        if country not in summary['countries']:
            summary['countries'][country] = {'missions': 0, 'expenses': 0.0}
        summary['countries'][country]['missions'] += 1
        summary['countries'][country]['expenses'] += total
    summary['expenses'] = round(summary['expenses'], 2)
    for value in summary['countries'].values():
        value['expenses'] = round(value['expenses'], 2)
    parent = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.travel-')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['mission_id', 'diplomat', 'country', 'departure', 'return', 'days', 'expenses'])
            for item in parsed:
                writer.writerow([item['mission_id'], item['diplomat'], item['country'], item['departure'], item['return'], item['days'], f"{item['expense_total']:.2f}"])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summary

