import csv
import datetime
import os
import tempfile

def generate_deletion_report(records: list[dict[str, object]], output_path: str, page: int=1, page_size: int=50) -> dict[str, object]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    grouped = {}
    for record in records:
        if record.get('status') != 'deleted':
            continue
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        user_id = record.get('user_id')
        date_text = record.get('deleted_at')
        amount = record.get('bytes_deleted')
        reason = record.get('reason')
        if not isinstance(user_id, str) or not user_id:
            raise ValueError('invalid user_id')
        if not isinstance(date_text, str):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date_text)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount < 0:
            raise ValueError('invalid bytes')
        if not isinstance(reason, str):
            raise ValueError('invalid reason')
        item = grouped.setdefault(user_id, {'deletion_count': 0, 'total_bytes': 0, 'latest_deleted_at': date_text, 'reasons': set()})
        item['deletion_count'] += 1
        item['total_bytes'] += amount
        item['latest_deleted_at'] = max(item['latest_deleted_at'], date_text)
        item['reasons'].add(reason)
    rows = []
    for user_id, item in grouped.items():
        rows.append({'user_id': user_id, 'deletion_count': item['deletion_count'], 'total_bytes': item['total_bytes'], 'latest_deleted_at': item['latest_deleted_at'], 'reasons': sorted(item['reasons'])})
    rows.sort(key=lambda row: (-row['total_bytes'], row['user_id']))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='deletion-report-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['user_id', 'deletion_count', 'total_bytes', 'latest_deleted_at', 'reasons'])
            for row in selected:
                writer.writerow([row['user_id'], row['deletion_count'], row['total_bytes'], row['latest_deleted_at'], '|'.join(row['reasons'])])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return {'total_users': len(rows), 'page': page, 'page_size': page_size, 'rows': selected}

