    try:
        assert available_entry_slots(path, 10, 1, 10) == [{'attraction': 'Aquarium', 'time': '09:30', 'capacity': 2, 'price': 8.5}, {'attraction': 'Zoo', 'time': '09:30', 'capacity': 4, 'price': 8.5}, {'attraction': 'Park', 'time': '12:00', 'capacity': 5, 'price': 8.0}]
    finally:
        Path(path).unlink()

def test_pagination_is_one_based_and_stable():
    path = write_schedule('C|10:00|1|1\nA|10:00|1|1\nB|10:00|1|1\nD|11:00|1|1\n')
    try:
        assert available_entry_slots(path, 2, 1, 2) == [{'attraction': 'A', 'time': '10:00', 'capacity': 1, 'price': 1.0}, {'attraction': 'B', 'time': '10:00', 'capacity': 1, 'price': 1.0}]
        assert available_entry_slots(path, 2, 2, 2) == [{'attraction': 'C', 'time': '10:00', 'capacity': 1, 'price': 1.0}, {'attraction': 'D', 'time': '11:00', 'capacity': 1, 'price': 1.0}]
        assert available_entry_slots(path, 2, 3, 2) == []
    finally:
        Path(path).unlink()

def test_blank_file_and_blank_lines():
    path = write_schedule('\n  \nGallery|08:00|2|3.125\n\n')
    try:
        assert available_entry_slots(path, 4, 1, 10) == [{'attraction': 'Gallery', 'time': '08:00', 'capacity': 2, 'price': 3.13}]
    finally:
        Path(path).unlink()

def test_invalid_arguments_raise_value_error():
    path = write_schedule('A|10:00|1|2\n')
    try:
        for args in [(-1, 1, 1), (math.inf, 1, 1), (2, 0, 1), (2, 1, 0), (2, 1, 101)]:
