def fetch_case_summary(api_url: str, employee_ids: list[str], min_risk: int=0) -> dict:
    if not employee_ids or any((not isinstance(item, str) or not item for item in employee_ids)):
        raise ValueError('employee_ids must contain non-empty strings')
    if isinstance(min_risk, bool) or not isinstance(min_risk, int) or (not 0 <= min_risk <= 5):
        raise ValueError('min_risk must be between 0 and 5')
    url = api_url.rstrip('/') + '/v1/occupational-health/cases'
