    if response.status_code != 200:
        raise RuntimeError('case service returned an error')
    records = response.json().get('cases', [])
    allowed = set(employee_ids)
    cases = [case for case in records if case['employee_id'] in allowed and case['risk_score'] >= min_risk]
    cases.sort(key=lambda case: (-case['risk_score'], case['opened_days_ago'], case['id']))
    by_status = {}
    for case in cases:
        by_status[case['status']] = by_status.get(case['status'], 0) + 1
    by_status = dict(sorted(by_status.items()))
    average = round(sum((case['risk_score'] for case in cases)) / len(cases), 2) if cases else 0.0
    return {'total': len(cases), 'average_risk': average, 'by_status': by_status, 'cases': cases}

