        result.append(dict(zip(FIELDS, [row[0], row[1], issued, expires, row[4], row[5]])))
    return result

def build_expiry_report(records: list[dict], as_of: date, window_days: int=30) -> dict:
    if window_days < 0:
        raise ValueError('negative window')
    grouped = {}
    limit = as_of + timedelta(days=window_days)
    for record in records:
        status = 'expired' if record['expires'] < as_of else 'expiring' if record['expires'] <= limit else 'active'
        grouped.setdefault(record['tenant'], []).append((record, status))
    tenants = []
    for tenant in sorted(grouped):
        items = sorted(grouped[tenant], key=lambda item: (item[0]['expires'], item[0]['provider_id'], item[0]['credential']))
        counts = {status: sum((value == status for _, value in items)) for status in ('active', 'expiring', 'expired')}
        tenants.append({'tenant': tenant, 'total': len(items), **counts, 'credentials': [{'provider_id': record['provider_id'], 'credential': record['credential'], 'expires': record['expires'].isoformat(), 'status': status} for record, status in items]})
    return {'as_of': as_of.isoformat(), 'window_days': window_days, 'tenants': tenants}

def change_review_status(requester: dict, reviews: list[dict], review_id: str, new_status: str) -> list[dict]:
    if new_status not in STATUSES:
        raise ValueError('invalid status')
    result = copy.deepcopy(reviews)
    target = next((review for review in result if review['review_id'] == review_id), None)
    if target is None or target['status'] == new_status:
        raise ValueError('invalid review change')
    target['status'] = new_status
    target['history'].append({'status': new_status, 'changed_by': requester['user_id'], 'changed_on': datetime.utcnow().date().isoformat()})
    return result

