from pathlib import Path

def save_camera_snapshot(base_dir: str, relative_name: str, content: bytes) -> str:
    if relative_name == '':
        raise ValueError('relative_name must not be empty')
    root = Path(base_dir).resolve()
    target = (root / relative_name).resolve()
    try:
        target.relative_to(root)
    except ValueError:
        raise ValueError('relative_name must refer to a location beneath base_dir')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('wb') as handle:
        handle.write(content)
    return str(target)

import sqlite3
from datetime import datetime

def initialize_schema(conn: sqlite3.Connection) -> None:
    conn.executescript('CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY, name TEXT NOT NULL); CREATE TABLE IF NOT EXISTS courses(id INTEGER PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity >= 0)); CREATE TABLE IF NOT EXISTS enrollments(student_id INTEGER NOT NULL, course_id INTEGER NOT NULL, enrolled_at TEXT NOT NULL, PRIMARY KEY(student_id, course_id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(course_id) REFERENCES courses(id));')
    conn.commit()

def enroll_student(conn: sqlite3.Connection, student_id: int, course_id: int, enrolled_at: str) -> None:
    try:
        datetime.fromisoformat(enrolled_at)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    try:
        with conn:
            if conn.execute('SELECT 1 FROM students WHERE id=?', (student_id,)).fetchone() is None:
                raise ValueError('student not found')
            row = conn.execute('SELECT capacity FROM courses WHERE id=?', (course_id,)).fetchone()
            if row is None:
                raise ValueError('course not found')
            if conn.execute('SELECT 1 FROM enrollments WHERE student_id=? AND course_id=?', (student_id, course_id)).fetchone():
                raise ValueError('already enrolled')
            if conn.execute('SELECT COUNT(*) FROM enrollments WHERE course_id=?', (course_id,)).fetchone()[0] >= row[0]:
                raise ValueError('course full')
            conn.execute('INSERT INTO enrollments VALUES (?, ?, ?)', (student_id, course_id, enrolled_at))
    except sqlite3.IntegrityError as exc:
        raise ValueError('enrollment failed') from exc

def search_courses(conn: sqlite3.Connection, search: str, sort_by: str='title', descending: bool=False, limit: int | None=None) -> list[dict[str, object]]:
    columns = {'title': 'c.title', 'category': 'c.category', 'enrolled': 'enrolled', 'id': 'c.id'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    if limit is not None and (isinstance(limit, bool) or not isinstance(limit, int) or limit < 0):
        raise ValueError('invalid limit')
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT c.id, c.title, c.category, c.capacity, COUNT(e.student_id) AS enrolled FROM courses c LEFT JOIN enrollments e ON e.course_id=c.id WHERE lower(c.title) LIKE lower(?) OR lower(c.category) LIKE lower(?) GROUP BY c.id ORDER BY ' + columns[sort_by] + ' ' + direction + ', c.title ASC, c.id ASC'
    params = ('%' + search + '%', '%' + search + '%')
    if limit is not None:
        sql += ' LIMIT ?'
        params += (limit,)
    cursor = conn.execute(sql, params)
    names = [item[0] for item in cursor.description]
    return [dict(zip(names, row)) for row in cursor.fetchall()]

def course_report(conn: sqlite3.Connection) -> list[dict[str, object]]:
    rows = conn.execute('SELECT c.category, COUNT(*) AS course_count, SUM(c.capacity) AS total_capacity, SUM((SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id)) AS total_enrolled FROM courses c GROUP BY c.category ORDER BY total_enrolled DESC, c.category ASC').fetchall()
    return [{'category': category, 'course_count': count, 'total_capacity': capacity, 'total_enrolled': enrolled, 'fill_rate': round(enrolled / capacity, 4) if capacity else 0.0} for category, count, capacity, enrolled in rows]

