import os
from pathlib import Path

def save_member_document(base_dir: str, member_id: str, filename: str, content: str) -> str:
    if not os.path.isdir(base_dir):
        raise FileNotFoundError(base_dir)
    if not isinstance(member_id, str) or not member_id:
        raise ValueError('member_id must not be empty')
    if not isinstance(filename, str) or not filename:
        raise ValueError('filename must not be empty')
    base = Path(base_dir).resolve()
    target = (base / member_id / filename).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('document path is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding='utf-8')
    return str(target)

