from datetime import date
import requests

def load_maintenance_summary(property_id: str, config: dict[str, str]) -> dict:
    if not isinstance(property_id, str) or not property_id.strip():
        raise ValueError('property_id must be non-empty')
    token = os.environ.get('PROPERTY_MAINTENANCE_API_TOKEN')
    if not token:
        raise RuntimeError('PROPERTY_MAINTENANCE_API_TOKEN is required')
    response = requests.get(config['endpoint'], headers={'Authorization': f'Bearer {token}'}, params={'property_id': property_id}, timeout=5)
    response.raise_for_status()
    payload = response.json()
    if not isinstance(payload, list):
        raise ValueError('response must be a list')
    active = []
    for item in payload:
        if not isinstance(item, dict):
            raise ValueError('request must be an object')
        for key in ('status', 'category', 'estimated_cost', 'due_date'):
            if key not in item:
                raise ValueError('missing request field')
        if item['status'] in {'open', 'scheduled', 'in_progress'}:
            if isinstance(item['estimated_cost'], bool) or not isinstance(item['estimated_cost'], (int, float)):
                raise ValueError('invalid cost')
            try:
                date.fromisoformat(item['due_date'])
            except (TypeError, ValueError):
                raise ValueError('invalid due date')
            if not isinstance(item['category'], str):
                raise ValueError('invalid category')
            active.append(item)
    groups = {}
    for item in active:
        group = groups.setdefault(item['category'], [0, 0.0])
        group[0] += 1
        group[1] += item['estimated_cost']
    categories = [{'category': name, 'count': values[0], 'estimated_total': round(values[1], 2)} for name, values in groups.items()]
    categories.sort(key=lambda item: (-item['count'], item['category']))
    return {'property_id': property_id, 'active_count': len(active), 'estimated_total': round(sum((item['estimated_cost'] for item in active)), 2), 'by_category': categories, 'next_due': min((item['due_date'] for item in active), default=None)}

