from solution import count_athlete_injuries
import os
import subprocess
import tempfile


def make_log(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    try:
        handle.write(contents)
        return handle.name
    finally:
        handle.close()


def test_counts_matching_records():
    path = make_log("Alex knee\nJordan ankle\nAlex shoulder\nAlex knee\n")
    try:
        assert count_athlete_injuries(path, "Alex") == 3
    finally:
        os.unlink(path)


def test_matching_is_case_sensitive():
    path = make_log("alex knee\nAlex ankle\nALEX wrist\n")
    try:
        assert count_athlete_injuries(path, "Alex") == 1
    finally:
        os.unlink(path)


def test_no_matches_returns_zero():
    path = make_log("Jordan ankle\nTaylor wrist\n")
    try:
        assert count_athlete_injuries(path, "Morgan") == 0
    finally:
        os.unlink(path)


def test_empty_file_returns_zero():
    path = make_log("")
    try:
        assert count_athlete_injuries(path, "Alex") == 0
    finally:
        os.unlink(path)


def test_empty_name_matches_every_line():
    path = make_log("Alex knee\n\nJordan ankle\n")
    try:
        assert count_athlete_injuries(path, "") == 3
    finally:
        os.unlink(path)


def test_substring_matching():
    path = make_log("Alexandra knee\nAlex shoulder\nMax ankle\n")
    try:
        assert count_athlete_injuries(path, "Alex") == 2
    finally:
        os.unlink(path)


def test_missing_file_raises_called_process_error():
    with tempfile.TemporaryDirectory() as directory:
        missing = os.path.join(directory, "missing.log")
        try:
            count_athlete_injuries(missing, "Alex")
            assert False
        except subprocess.CalledProcessError:
            pass

