        if times[1] <= times[0]:
            raise ValueError('invalid interval')
        records.append({'id': item['id'], 'course': item['course'], 'day': item['day'], 'start': item['start'], 'end': item['end'], 'room': item['room'], 'instructor': instructor, '_start': times[0], '_end': times[1]})
    records.sort(key=lambda x: (x['day'], x['_start'], x['_end'], x['id']))
    for i, left in enumerate(records):
