    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError('invalid expression') from exc

def match_invoices(ocr_rows: list[dict], master_rows: list[dict], expression: str) -> list[dict]:
    if not master_rows:
        raise ValueError('master list is empty')
    result = []
    for oi, ocr in enumerate(ocr_rows):
        candidates = []
        for mi, master in enumerate(master_rows):
            vars = {'number_match': int(normalize_invoice_number(ocr['invoice_no']) == normalize_invoice_number(master['invoice_no'])), 'vendor_match': int(ocr['vendor'].strip().lower() == master['vendor'].strip().lower()), 'date_match': int(ocr['date'].strip() == master['date'].strip()), 'total_diff': abs(ocr['total'] - master['total']), 'confidence': ocr['confidence']}
