import os
import tempfile

def export_registrations(records: list[dict], output_path: str, state: str | None=None, min_year: int | None=None) -> dict:
    if state is not None and (not isinstance(state, str) or len(state) != 2 or (not state.isupper()) or (not state.isalpha())):
        raise ValueError('invalid state filter')
    if min_year is not None and (not isinstance(min_year, int) or isinstance(min_year, bool) or min_year < 1900 or (min_year > 2100)):
        raise ValueError('invalid year filter')
