        if not isinstance(record, dict) or set(record) != {'plate', 'owner', 'state', 'year', 'fee'}:
            raise ValueError('invalid record')
        plate = record['plate']
        owner = record['owner']
        rec_state = record['state']
        year = record['year']
        fee = record['fee']
        if not isinstance(plate, str) or not plate or (not isinstance(owner, str)) or (not owner):
            raise ValueError('invalid text')
        if not isinstance(rec_state, str) or len(rec_state) != 2 or (not rec_state.isalpha()) or (not rec_state.isupper()):
            raise ValueError('invalid record state')
        if not isinstance(year, int) or isinstance(year, bool) or year < 1900 or (year > 2100):
            raise ValueError('invalid year')
        if not isinstance(fee, (int, float)) or isinstance(fee, bool) or fee < 0:
            raise ValueError('invalid fee')
        if (state is None or rec_state == state) and (min_year is None or year >= min_year):
            checked.append((plate, owner, rec_state, year, fee))
    checked.sort(key=lambda item: (item[0], item[3], item[1]))
    counts = {}
    for item in checked:
        counts[item[2]] = counts.get(item[2], 0) + 1
    counts = dict(sorted(counts.items()))
    directory = os.path.dirname(os.path.abspath(output_path))
