    temporary_name = temporary.name
    try:
        with temporary:
            writer = csv.writer(temporary, lineterminator='\n')
            writer.writerow(['plate', 'owner', 'state', 'year', 'fee'])
            writer.writerows(checked)
        os.replace(temporary_name, output_path)
    except Exception:
        if os.path.exists(temporary_name):
            os.unlink(temporary_name)
        raise
    return {'written': len(checked), 'total_fee': round(sum((item[4] for item in checked)), 2), 'by_state': counts}

