import json
import subprocess

def _validate(record):
    if not isinstance(record, dict) or set(record) != {'order_id', 'customer', 'status', 'items'}:
        raise ValueError('invalid order')
    if any((not isinstance(record[k], str) or not record[k] for k in ('order_id', 'customer', 'status'))):
        raise ValueError('invalid order')
    if not isinstance(record['items'], list) or not record['items']:
        raise ValueError('invalid items')
    for item in record['items']:
        if not isinstance(item, dict) or set(item) != {'sku', 'quantity', 'unit_price'}:
            raise ValueError('invalid item')
        if not isinstance(item['sku'], str) or not item['sku']:
            raise ValueError('invalid item')
        if isinstance(item['quantity'], bool) or not isinstance(item['quantity'], int) or item['quantity'] <= 0:
            raise ValueError('invalid quantity')
        if isinstance(item['unit_price'], bool) or not isinstance(item['unit_price'], int) or item['unit_price'] < 0:
            raise ValueError('invalid price')

def read_orders(path: str) -> list[dict]:
    result = []
    seen = set()
    completed = subprocess.run(['sort', '--', path], capture_output=True, text=True, check=True)
    for line in completed.stdout.splitlines():
        if not line.strip():
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ValueError('invalid json') from exc
        _validate(record)
        if record['order_id'] in seen:
            raise ValueError('duplicate order')
        seen.add(record['order_id'])
        result.append(record)
    return sorted(result, key=lambda x: x['order_id'])

def build_report(path: str, statuses: list[str] | None=None, min_total: int=0) -> dict:
    if isinstance(min_total, bool) or not isinstance(min_total, int) or min_total < 0:
        raise ValueError('invalid minimum')
    selected = []
    for order in read_orders(path):
        if statuses is not None and order['status'] not in statuses:
            continue
        total = sum((x['quantity'] * x['unit_price'] for x in order['items']))
        if total >= min_total:
            selected.append((order, total))
    orders = [{'order_id': o['order_id'], 'customer': o['customer'], 'status': o['status'], 'total': t} for o, t in selected]
    customers = {}
    items = {}
    for order, total in selected:
        c = customers.setdefault(order['customer'], {'customer': order['customer'], 'order_count': 0, 'total': 0})
        c['order_count'] += 1
        c['total'] += total
        for item in order['items']:
            x = items.setdefault(item['sku'], {'sku': item['sku'], 'quantity': 0, 'total': 0})
            x['quantity'] += item['quantity']
            x['total'] += item['quantity'] * item['unit_price']
    return {'order_count': len(orders), 'gross_total': sum((x['total'] for x in orders)), 'orders': orders, 'customers': sorted(customers.values(), key=lambda x: (-x['total'], x['customer'])), 'items': sorted(items.values(), key=lambda x: (-x['quantity'], -x['total'], x['sku']))}

