import sqlite3

def initialize_capacity(conn: sqlite3.Connection, hospitals: list[dict[str, object]]) -> None:
    checked = []
    seen = set()
    for item in hospitals:
        if set(item) != {'hospital', 'region', 'total', 'occupied'}:
            raise ValueError('invalid record')
        name = item['hospital']
        region = item['region']
        total = item['total']
        occupied = item['occupied']
        if not isinstance(name, str) or not name or (not isinstance(region, str)) or (not region):
            raise ValueError('invalid text')
        if type(total) is not int or total <= 0 or type(occupied) is not int or (occupied < 0) or (occupied > total):
            raise ValueError('invalid capacity')
        if name in seen:
            raise ValueError('duplicate hospital')
        seen.add(name)
        checked.append((name, region, total, occupied))
    conn.execute('CREATE TABLE IF NOT EXISTS hospitals (hospital TEXT PRIMARY KEY, region TEXT NOT NULL, total INTEGER NOT NULL, occupied INTEGER NOT NULL)')
    try:
        with conn:
            conn.execute('DELETE FROM hospitals')
            conn.executemany('INSERT INTO hospitals (hospital, region, total, occupied) VALUES (?, ?, ?, ?)', checked)
    except sqlite3.Error:
        raise

def update_capacity(conn: sqlite3.Connection, hospital: str, change: int) -> int:
    if type(change) is not int:
        raise ValueError('change must be an integer')
    row = conn.execute('SELECT total, occupied FROM hospitals WHERE hospital = ?', (hospital,)).fetchone()
    if row is None:
        raise KeyError(hospital)
    total, occupied = row
    new_occupied = occupied + change
    if new_occupied < 0 or new_occupied > total:
        raise ValueError('capacity exceeded')
    with conn:
        conn.execute('UPDATE hospitals SET occupied = ? WHERE hospital = ?', (new_occupied, hospital))
    return total - new_occupied

def rank_hospitals(conn: sqlite3.Connection, region: str | None=None, sort_by: str='available') -> list[dict[str, object]]:
    if sort_by not in {'available', 'load', 'hospital', 'occupied'}:
        raise ValueError('invalid sort')
    if region is None:
        rows = conn.execute('SELECT hospital, region, total, occupied FROM hospitals').fetchall()
    else:
        rows = conn.execute('SELECT hospital, region, total, occupied FROM hospitals WHERE region = ?', (region,)).fetchall()
    result = []
    for hospital, area, total, occupied in rows:
        result.append({'hospital': hospital, 'region': area, 'total': total, 'occupied': occupied, 'available': total - occupied, 'load_percent': round(occupied / total * 100, 2)})

    def key(item):
        value = item['occupied'] / item['total'] if sort_by == 'load' else item[sort_by]
        return (value, item['hospital'])
    return sorted(result, key=key)

