import os
import zipfile
from pathlib import Path

def parse_issue_manifest(text: str) -> list[dict]:
    result = {}
    try:
        rows = csv.reader(io.StringIO(text), strict=True)
        for row in rows:
            if not row or all((not x.strip() for x in row)):
                continue
            if len(row) != 4:
                raise ValueError('invalid row')
            section, page, title, count = (x.strip() for x in row)
            if not section or not page.isdecimal() or (not count.isdecimal()):
                raise ValueError('invalid value')
            page_number = int(page)
            byte_count = int(count)
            if page_number < 1:
                raise ValueError('invalid page')
            if (section, page_number) in result:
                raise ValueError('duplicate page')
            result[section, page_number] = (title, byte_count)
    except (csv.Error, TypeError):
        raise ValueError('invalid manifest')
    grouped = {}
    for (section, page), (title, count) in result.items():
        grouped.setdefault(section, []).append({'page': page, 'title': title, 'bytes': count})
    return [{'section': s, 'pages': sorted(p, key=lambda x: x['page']), 'total_bytes': sum((x['bytes'] for x in p))} for s, p in sorted(grouped.items(), key=lambda x: (x[0].lower(), x[0]))]

def extract_issue(zip_path: str, destination: str, names: list[str] | None=None) -> list[str]:
    with zipfile.ZipFile(zip_path) as archive:
        entries = {item.filename: item for item in archive.infolist()}
        selected = [item.filename for item in archive.infolist() if not item.is_dir()] if names is None else names
        written = []
        base = Path(destination).resolve()
        for name in selected:
            item = entries.get(name)
            if item is None or item.is_dir():
                raise ValueError('invalid archive member')
            target = (base / name).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('invalid destination path')
            target.parent.mkdir(parents=True, exist_ok=True)
            with open(target, 'wb') as output:
                output.write(archive.read(item))
            written.append(name)
        return written

