def catalog_page(records: list[dict[str, Any]], config: Mapping[str, Any], page: int=1, page_size: int=10) -> dict[str, Any]:
    if page < 1 or page_size < 1:
        raise ValueError('page and page_size must be positive')
    token = config['api_token']
    try:
        limit = float(config.get('max_cloud_cover', 20.0))
    except (TypeError, ValueError):
        raise ValueError('max_cloud_cover must be numeric')
    if not 0 <= limit <= 100:
        raise ValueError('max_cloud_cover out of range')
    selected = []
    for record in records:
        required = ('id', 'platform', 'cloud_cover', 'captured')
        if any((key not in record for key in required)):
            raise ValueError('malformed record')
        if not isinstance(record['id'], str) or not record['id']:
            raise ValueError('invalid id')
        if not isinstance(record['platform'], str) or not record['platform']:
            raise ValueError('invalid platform')
        cloud = record['cloud_cover']
        if isinstance(cloud, bool) or not isinstance(cloud, (int, float)) or (not 0 <= cloud <= 100):
            raise ValueError('invalid cloud cover')
        try:
            captured = datetime.datetime.fromisoformat(record['captured'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if cloud <= limit:
            selected.append((captured, record))
    selected.sort(key=lambda pair: (-pair[0].timestamp(), pair[1]['id']))
    counts = {}
    for _, record in selected:
        counts[record['platform']] = counts.get(record['platform'], 0) + 1
    ordered_counts = {key: counts[key] for key in sorted(counts)}
    start = (page - 1) * page_size
    return {'authorization': 'Bearer ' + str(token), 'total': len(selected), 'page': page, 'page_size': page_size, 'items': [record for _, record in selected[start:start + page_size]], 'platform_counts': ordered_counts}

