import hashlib
import hmac
import json
import pytest
from solution import summarize_registration_webhook

def signed(body, key=b'conference-key'):
    digest = hmac.new(key, body, hashlib.sha256).hexdigest()
    return 'sha256=' + digest

def test_empty_payload_summary():
    body = json.dumps({'registrations': []}, separators=(',', ':')).encode()
    assert summarize_registration_webhook(body, b'k', signed(body, b'k')) == {'count': 0, 'total_cents': 0, 'tracks': [], 'attendees': []}

def test_attendee_sorting_is_case_insensitive_with_tie_break():
    payload = {'registrations': [{'name': 'bob', 'track': 'X', 'ticket': 'student'}, {'name': 'Alice', 'track': 'X', 'ticket': 'student'}, {'name': 'ALICE', 'track': 'X', 'ticket': 'student'}]}
    body = json.dumps(payload).encode()
    assert summarize_registration_webhook(body, b'k', signed(body, b'k'))['attendees'] == ['ALICE', 'Alice', 'bob']

def test_bad_signature_is_rejected():
    body = b'{"registrations":[]}'
    with pytest.raises(ValueError, match='^invalid signature$'):
        summarize_registration_webhook(body, b'key', 'sha256=' + '0' * 64)

def test_bad_signature_formats_are_rejected():
    body = b'{"registrations":[]}'
    for value in ['', 'sha1=' + '0' * 64, 'sha256=abc', 'sha256=' + 'g' * 64]:
        with pytest.raises(ValueError, match='^invalid signature$'):
            summarize_registration_webhook(body, b'key', value)

def test_invalid_payloads_raise_payload_error():
    cases = [b'not json', b'[]', b'{}', json.dumps({'registrations': {}}).encode(), json.dumps({'registrations': [{'name': 'A', 'track': 'X', 'ticket': 'vip'}]}).encode(), json.dumps({'registrations': [{'name': ' ', 'track': 'X', 'ticket': 'student'}]}).encode(), b'\xff']
    for body in cases:
        with pytest.raises(ValueError, match='^invalid payload$'):
            summarize_registration_webhook(body, b'key', signed(body, b'key'))

def test_uppercase_hex_signature_and_utf8_names_work():
    payload = {'registrations': [{'name': 'Éva', 'track': 'Data', 'ticket': 'workshop'}]}
    body = json.dumps(payload, ensure_ascii=False).encode('utf-8')
    signature = signed(body, b'key').upper().replace('SHA256=', 'sha256=')
    assert summarize_registration_webhook(body, b'key', signature)['total_cents'] == 22000

