import os
import zipfile
from datetime import datetime, timezone
from pathlib import Path

def _split_fields(line):
    fields = []
    current = []
    escaped = False
    for ch in line:
        if escaped:
            current.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '\t':
            fields.append(''.join(current))
            current = []
        else:
            current.append(ch)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def parse_access_manifest(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _split_fields(raw)
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('invalid record')
        if fields[0] in seen:
            raise ValueError('duplicate request id')
        try:
            priority = int(fields[2])
        except ValueError:
            raise ValueError('invalid priority')
        if not 0 <= priority <= 9:
            raise ValueError('invalid priority')
        stamp = fields[3]
        if not stamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            when = datetime.fromisoformat(stamp[:-1] + '+00:00')
        except ValueError:
            raise ValueError('invalid timestamp')
        if when.tzinfo is None or when.utcoffset() != timezone.utc.utcoffset(when):
            raise ValueError('invalid timestamp')
        seen.add(fields[0])
        records.append({'request_id': fields[0], 'member_name': fields[1], 'priority': priority, 'requested_at': when})
    records.sort(key=lambda r: (-r['priority'], r['requested_at'], r['request_id']))
    return records

def extract_archive_members(archive_path: str, destination: str, members: list[str]) -> list[str]:
    if not members:
        return []
    base = Path(destination).resolve()
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        info = {item.filename: item for item in archive.infolist()}
        for name in members:
            if name not in info:
                raise FileNotFoundError(name)
            item = info[name]
            if item.is_dir() or name.endswith('/'):
                raise IsADirectoryError(name)
            target = (base / name).resolve()
            try:
                inside = os.path.commonpath([str(base), str(target)]) == str(base)
            except ValueError:
                inside = False
            if not inside:
                raise ValueError(name)
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(item) as source, open(target, 'wb') as output:
                while True:
                    chunk = source.read(65536)
                    if not chunk:
                        break
                    output.write(chunk)
            result.append(str(Path(destination) / name))
    return result

