import os

def create_operator_record(operator_id: str, password: str) -> str:
    if not isinstance(operator_id, str) or not isinstance(password, str):
        raise TypeError('operator_id and password must be strings')
    operator_id = operator_id.strip()
    if not operator_id or len(password) < 4:
        raise ValueError('invalid operator credentials')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return operator_id + '$' + salt.hex() + '$' + digest.hex()

def authenticate_operator(record: str, password: str) -> bool:
    if not isinstance(record, str) or not isinstance(password, str):
        return False
    parts = record.split('$')
    if len(parts) != 3 or not parts[0]:
        return False
    try:
        salt = bytes.fromhex(parts[1])
        expected = bytes.fromhex(parts[2])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_wafers(rows: list[dict], page: int, page_size: int) -> dict:
    if not isinstance(rows, list) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('invalid argument type')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid page')
    groups = {}
    for row in rows:
        if not isinstance(row, dict) or any((k not in row for k in ('lot', 'wafer', 'status', 'yield_pct'))):
            raise ValueError('invalid row')
        if not all((isinstance(row[k], str) for k in ('lot', 'wafer', 'status'))):
            raise ValueError('invalid row')
        value = row['yield_pct']
        if isinstance(value, bool) or not isinstance(value, (int, float)) or (not 0 <= value <= 100):
            raise ValueError('invalid yield')
        if row['status'] == 'complete':
            groups.setdefault(row['lot'], []).append(value)
    result = [{'lot': lot, 'wafer_count': len(vals), 'average_yield': round(sum(vals) / len(vals), 2)} for lot, vals in groups.items()]
    result.sort(key=lambda x: (-x['average_yield'], x['lot']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_lots': len(result), 'lots': result[start:start + page_size]}

