import csv
import io
import secrets
import string

def parse_evacuation_zones(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except (csv.Error, TypeError) as exc:
        raise ValueError('invalid csv') from exc
    if not rows:
        raise ValueError('missing header')
    if rows[0] != ['zone', 'shelter', 'priority', 'capacity']:
        raise ValueError('invalid header')
    merged = {}
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        zone, shelter, priority, capacity = (x.strip() for x in row)
        if not zone or not shelter:
            raise ValueError('empty field')
        try:
            p, c = (int(priority), int(capacity))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if p < 1 or p > 5 or c < 0:
            raise ValueError('invalid value')
        key = (zone, shelter)
        if key in merged and merged[key]['priority'] != p:
            raise ValueError('conflicting priority')
        if key in merged:
            merged[key]['capacity'] += c
        else:
            merged[key] = {'zone': zone, 'shelter': shelter, 'priority': p, 'capacity': c}
    return sorted(merged.values(), key=lambda x: (x['zone'], x['priority'], x['shelter']))

def allocate_evacuees(records: list[dict], residents: dict[str, int]) -> dict[str, list[tuple[str, int]]]:
    groups = {}
    for r in records:
        if not isinstance(r, dict) or not isinstance(r.get('capacity'), int) or r['capacity'] < 0:
            raise ValueError('invalid record')
        key = (r.get('zone'), r.get('shelter'))
        if key in groups:
            raise ValueError('duplicate shelter')
        groups[key] = r
    for zone, count in residents.items():
        if not isinstance(count, int) or count < 0:
            raise ValueError('invalid residents')
        available = sum((r['capacity'] for (z, _), r in groups.items() if z == zone))
        if available < count:
            raise ValueError('insufficient capacity')
    result = {}
    for zone, count in residents.items():
        left, entries = (count, [])
        for (z, shelter), r in groups.items():
            if z == zone and left:
                used = min(left, r['capacity'])
                if used:
                    entries.append((shelter, used))
                left -= used
        result[zone] = entries
    return result

def issue_evacuation_code(zone: str, length: int=12) -> str:
    if not isinstance(zone, str) or not 2 <= len(zone) <= 8 or any((c not in string.ascii_uppercase + string.digits for c in zone)):
        raise ValueError('invalid zone')
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    alphabet = string.ascii_uppercase + string.digits
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

