import hashlib
import hmac
import json

def calculate_dispatch(payload: str, auth: str, secret: bytes) -> list[dict]:
    if not isinstance(payload, str) or not isinstance(auth, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid arguments')
    if len(secret) == 0 or len(auth) != 71 or (not auth.startswith('sha256=')):
        raise ValueError('invalid authentication')
    supplied = auth[7:]
    if any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid authentication')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, supplied):
        raise ValueError('invalid authentication')
    try:
        root = json.loads(payload)
    except (UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(root, dict) or not isinstance(root.get('stops'), list) or (not isinstance(root.get('buses'), list)):
        raise ValueError('invalid payload')
    stops = []
    stop_ids = set()
    for s in root['stops']:
        if not isinstance(s, dict):
            raise ValueError('invalid stop')
        ident, zone = (s.get('id'), s.get('zone'))
        mins, priority, window = (s.get('minutes'), s.get('priority'), s.get('window'))
        if not isinstance(ident, str) or not ident or ident in stop_ids or (not isinstance(zone, str)) or (not zone) or (type(mins) is not int) or (mins <= 0) or (type(priority) is not int) or (not isinstance(window, list)) or (len(window) != 2) or any((type(x) is not int for x in window)) or (not 0 <= window[0] <= window[1] <= 1440):
            raise ValueError('invalid stop')
        stop_ids.add(ident)
        stops.append((ident, zone, mins, priority, window[0], window[1]))
    buses = []
    bus_ids = set()
    for b in root['buses']:
        if not isinstance(b, dict):
            raise ValueError('invalid bus')
        ident, cap, zones = (b.get('id'), b.get('capacity'), b.get('zones'))
        if not isinstance(ident, str) or not ident or ident in bus_ids or (type(cap) is not int) or (cap <= 0) or (not isinstance(zones, list)) or (not zones) or any((not isinstance(z, str) for z in zones)):
            raise ValueError('invalid bus')
        bus_ids.add(ident)
        buses.append({'id': ident, 'capacity': cap, 'zones': set(zones), 'stops': [], 'used': 0})
    buses.sort(key=lambda b: b['id'])
    for stop in sorted(stops, key=lambda x: (x[5], -x[3], x[0])):
        chosen = None
        for bus in buses:
            if stop[1] in bus['zones'] and bus['used'] + stop[2] <= bus['capacity']:
                chosen = bus
                break
        if chosen is None:
            raise ValueError('unassigned stop')
        chosen['used'] += stop[2]
        chosen['stops'].append(stop)
    result = []
    for bus in buses:
        ordered = sorted(bus['stops'], key=lambda x: (x[4], x[5], -x[3], x[0]))
        result.append({'id': bus['id'], 'stops': [x[0] for x in ordered]})
    return result

