import math
import sqlite3

def list_battery_dispatch_events(conn: sqlite3.Connection, site_id: str, min_soc: float, max_soc: float, sort_by: str='timestamp', limit: int=100) -> list[tuple[str, float, float, str]]:
    if not isinstance(min_soc, (int, float)) or not math.isfinite(min_soc):
        raise ValueError('invalid state-of-charge bounds')
    if not isinstance(max_soc, (int, float)) or not math.isfinite(max_soc):
        raise ValueError('invalid state-of-charge bounds')
    if min_soc > max_soc:
        raise ValueError('invalid state-of-charge bounds')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 0 <= limit <= 1000):
        raise ValueError('invalid limit')
    columns = {'timestamp': 'timestamp ASC', 'energy_kwh': 'energy_kwh DESC', 'soc': 'soc DESC'}
    if sort_by not in columns:
        raise ValueError('invalid sort column')
    if limit == 0:
        return []
    query = f'SELECT timestamp, energy_kwh, soc, mode FROM battery_events WHERE site_id = ? AND soc >= ? AND soc <= ? ORDER BY {columns[sort_by]} LIMIT ?'
    rows = conn.execute(query, (site_id, min_soc, max_soc, limit)).fetchall()
    return [(timestamp, round(float(energy), 3), round(float(soc), 3), mode) for timestamp, energy, soc, mode in rows]

