import hmac
import re
from datetime import date

def process_report(payload: str, signature: str, secret: bytes) -> dict:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if len(signature) != 64 or not re.fullmatch('[0-9a-f]{64}', signature) or (not hmac.compare_digest(signature, expected)):
        raise PermissionError('invalid signature')
    seen = set()
    groups = {}
    total = upheld = dismissed = 0
    for line in payload.split('\n'):
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for ch in line:
            if escaped:
                if ch not in '\\|':
                    raise ValueError('invalid escape')
                current.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(ch)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 5:
            raise ValueError('field count')
        citation, plate, point_text, outcome, dates = fields
        if not citation or citation in seen or (not re.fullmatch('[A-Z0-9]{2,8}', plate)):
            raise ValueError('invalid identity')
        if not re.fullmatch('[0-9]+', point_text):
            raise ValueError('invalid points')
        points = int(point_text)
        if not 1 <= points <= 12 or outcome not in ('UPHELD', 'DISMISSED'):
            raise ValueError('invalid record')
        if not re.fullmatch('[0-9]{4}-[0-9]{2}-[0-9]{2}', dates):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(dates)
        except ValueError:
            raise ValueError('invalid date')
        seen.add(citation)
        total += 1
        if outcome == 'DISMISSED':
            dismissed += 1
        else:
            upheld += 1
            groups.setdefault(plate, []).append((dates, citation, points))
    ordered = []
    for plate, records in groups.items():
        records.sort(key=lambda x: (x[0], x[1]))
        ordered.append({'plate': plate, 'citations': [x[1] for x in records], 'points': sum((x[2] for x in records))})
    ordered.sort(key=lambda x: (-x['points'], -len(x['citations']), x['plate']))
    return {'total': total, 'upheld': upheld, 'dismissed': dismissed, 'by_plate': ordered}

