import hashlib
import hmac
import os

def create_patient_record(patient_id: str, pin: str) -> dict:
    if not isinstance(patient_id, str) or not patient_id:
        raise ValueError('invalid patient id')
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
    return {'patient_id': patient_id, 'credential': {'salt': salt.hex(), 'digest': digest}, 'active': True, 'failed_attempts': 0}

def authenticate_patient(record: dict, pin: str) -> bool:
    if not isinstance(pin, str):
        raise ValueError('invalid pin')
    if not record.get('active', False):
        return False
    credential = record['credential']
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), bytes.fromhex(credential['salt']), 100000).hex()
    if hmac.compare_digest(actual, credential['digest']):
        return True
    record['failed_attempts'] += 1
    if record['failed_attempts'] >= 3:
        record['active'] = False
    return False

def summarize_readings(readings: list[dict], start: int, end: int, page: int=1, page_size: int=20) -> list[dict]:
    if start > end or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid range or pagination')
    groups = {}
    for item in readings:
        if not isinstance(item, dict) or not isinstance(item.get('timestamp'), int) or isinstance(item.get('timestamp'), bool) or (not isinstance(item.get('heart_rate'), (int, float))) or isinstance(item.get('heart_rate'), bool) or (not isinstance(item.get('spo2'), (int, float))) or isinstance(item.get('spo2'), bool):
            raise ValueError('invalid reading')
        if start <= item['timestamp'] <= end:
            hour = item['timestamp'] // 3600
            groups.setdefault(hour, []).append(item)
    result = []
    for hour in sorted(groups):
        items = groups[hour]
        result.append({'hour': hour, 'count': len(items), 'average_heart_rate': round(sum((x['heart_rate'] for x in items)) / len(items), 2), 'minimum_spo2': round(min((x['spo2'] for x in items)), 2)})
    offset = (page - 1) * page_size
    return result[offset:offset + page_size]

