def get_stock_alerts(requester: dict, machines: list[dict], *, threshold: int, page: int=1, page_size: int=50) -> dict:
    if threshold < 0 or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError()
    for key in ('id', 'tenant_id', 'roles'):
        if key not in requester:
            raise ValueError()
    alerts = []
    for machine in machines:
        for key in ('machine_id', 'owner_id', 'tenant_id', 'items'):
            if key not in machine:
                raise ValueError()
        if machine['tenant_id'] != requester['tenant_id']:
            continue
        if machine['owner_id'] != requester['id'] and 'stock_manager' not in requester['roles']:
            continue
        for item in machine['items']:
            if 'sku' not in item or 'stock' not in item:
                raise ValueError()
            if item['stock'] <= threshold:
                alerts.append({'machine_id': machine['machine_id'], 'sku': item['sku'], 'stock': item['stock'], 'threshold': threshold, 'deficit': threshold - item['stock']})
    alerts.sort(key=lambda x: (x['stock'], x['machine_id'], x['sku']))
    total = len(alerts)
    start = (page - 1) * page_size
    return {'alerts': alerts[start:start + page_size], 'total': total, 'page': page, 'page_size': page_size}

