def sync_catalog(archive_path: str, destination: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(destination)
    os.makedirs(base, exist_ok=True)
    rows = []
    with zipfile.ZipFile(archive_path) as archive:
        names = sorted((name for name in archive.namelist() if not name.endswith('/') and name.lower().endswith('.csv')))
