import csv
import datetime
import io
import os
import tempfile
_FIELDS = ['reservation_id', 'rider', 'ride', 'date', 'time', 'party_size']
_OUTPUT_FIELDS = ['date', 'time', 'ride', 'reservation_count', 'guest_count', 'reservation_ids']

def _valid_date(value):
    try:
        datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if len(value) != 10:
        raise ValueError('invalid date')

def _valid_time(value):
    try:
        datetime.datetime.strptime(value, '%H:%M')
    except Exception as exc:
        raise ValueError('invalid time') from exc
    if len(value) != 5:
        raise ValueError('invalid time')

def parse_reservations(data: str) -> list[dict]:
    reader = csv.DictReader(io.StringIO(data))
    if reader.fieldnames != _FIELDS:
        raise ValueError('invalid header')
    result = []
    seen = set()
    try:
        for row in reader:
            if any((row[k] is None or row[k] == '' for k in _FIELDS)):
                raise ValueError('missing field')
            if row['reservation_id'] in seen:
                raise ValueError('duplicate id')
            party = int(row['party_size'])
            if party <= 0 or str(party) != row['party_size']:
                raise ValueError('invalid party size')
            _valid_date(row['date'])
            _valid_time(row['time'])
            seen.add(row['reservation_id'])
            row['party_size'] = party
            result.append(row)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid csv') from exc
    return result

def build_schedule(reservations: list[dict], date: str) -> list[dict]:
    _valid_date(date)
    groups = {}
    for item in reservations:
        if set(item) != set(_FIELDS):
            raise ValueError('invalid reservation')
        _valid_date(item['date'])
        _valid_time(item['time'])
        if not isinstance(item['party_size'], int) or item['party_size'] <= 0:
            raise ValueError('invalid party size')
        if item['date'] != date:
            continue
        key = (item['time'], item['ride'])
        if key not in groups:
            groups[key] = {'date': date, 'time': item['time'], 'ride': item['ride'], 'reservation_count': 0, 'guest_count': 0, 'reservation_ids': []}
        group = groups[key]
        group['reservation_count'] += 1
        group['guest_count'] += item['party_size']
        group['reservation_ids'].append(item['reservation_id'])
    result = []
    for key in sorted(groups):
        group = groups[key]
        group['reservation_ids'] = ','.join(group['reservation_ids'])
        result.append(group)
    return result

def export_schedule(data: str, date: str, destination: str) -> int:
    rows = build_schedule(parse_reservations(data), date)
    fd, temporary = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)), prefix='.schedule-')
    try:
        with os.fdopen(fd, 'w', newline='') as stream:
            writer = csv.DictWriter(stream, fieldnames=_OUTPUT_FIELDS, lineterminator='\n')
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(rows)

