import secrets
ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def generate_alert_code(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(ALPHABET) for _ in range(length)))

def parse_stock_report(text: str) -> list[dict]:
    records = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('dangling escape')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('malformed report')
        try:
            change = int(fields[2], 10)
            timestamp = int(fields[3], 10)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        records.append({'machine': fields[0], 'item': fields[1], 'change': change, 'timestamp': timestamp})
    return records

def stock_alerts(initial_stock: dict[str, dict[str, int]], report: str, now: int, window: int=3600, threshold: int=2) -> list[dict]:
    if window <= 0 or threshold < 0:
        raise ValueError('invalid options')
    stock = {machine: dict(items) for machine, items in initial_stock.items()}
    recent = {}
    for event in parse_stock_report(report):
        if event['timestamp'] > now:
            continue
        machine, item = (event['machine'], event['item'])
        stock.setdefault(machine, {})
        stock[machine][item] = stock[machine].get(item, 0) + event['change']
        if now - window <= event['timestamp'] <= now and event['change'] < 0:
            recent[machine, item] = recent.get((machine, item), 0) + event['change']
    alerts = []
    for machine, items in stock.items():
        for item, quantity in items.items():
            decrease = recent.get((machine, item), 0)
            if quantity <= threshold and decrease:
                alerts.append({'machine': machine, 'item': item, 'quantity': quantity, 'recent_decrease': decrease, 'code': generate_alert_code()})
    alerts.sort(key=lambda x: (x['quantity'], abs(x['recent_decrease']), x['machine'], x['item']))
    return alerts

