import os

def hash_tracking_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_tracking_secret(secret: str, stored_value: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored_value, str) or (not secret):
        return False
    parts = stored_value.split(':')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

