import hashlib
import hmac
import json
import os
from unittest.mock import patch

import pytest


def expected_signature(manifest, carrier, key):
    payload = json.dumps(
        {"carrier": carrier, "manifest": manifest},
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    ).encode("utf-8")
    return hmac.new(key.encode("utf-8"), payload, hashlib.sha256).hexdigest()


def test_signs_basic_manifest():
    manifest = {"tracking_number": "TRK-100", "weight_kg": 2.5}
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "test-key"}, clear=True):
        assert sign_manifest(manifest, "Acme Freight") == expected_signature(
            manifest, "Acme Freight", "test-key"
        )


def test_signature_is_lowercase_hex_with_fixed_length():
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "another-key"}, clear=True):
        result = sign_manifest({"id": 7}, "Carrier")
    assert len(result) == 64
    assert result == result.lower()
    assert all(char in "0123456789abcdef" for char in result)


def test_nested_values_and_unicode_are_signed_exactly():
    manifest = {
        "destination": {"city": "München", "country": "DE"},
        "items": ["café", {"fragile": True}],
    }
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "clé-secrète"}, clear=True):
        actual = sign_manifest(manifest, "Línea Norte")
    assert actual == expected_signature(manifest, "Línea Norte", "clé-secrète")


def test_key_order_does_not_change_signature():
    first = {"z": 3, "a": 1, "middle": {"b": 2, "a": 4}}
    second = {"middle": {"a": 4, "b": 2}, "a": 1, "z": 3}
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "stable"}, clear=True):
        assert sign_manifest(first, "Parcel Co") == sign_manifest(second, "Parcel Co")


def test_empty_manifest_is_valid():
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "empty-key"}, clear=True):
        assert sign_manifest({}, "Depot") == expected_signature({}, "Depot", "empty-key")


def test_manifest_type_is_checked():
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "type-key"}, clear=True):
        with pytest.raises(TypeError, match="^manifest must be a dict$"):
            sign_manifest([("id", 1)], "Carrier")


def test_carrier_must_be_nonempty_string():
    with patch.dict(os.environ, {"SHIPPING_MANIFEST_KEY": "carrier-key"}, clear=True):
        with pytest.raises(ValueError, match="^carrier must be a non-empty string$"):
            sign_manifest({}, "")
        with pytest.raises(ValueError, match="^carrier must be a non-empty string$"):
            sign_manifest({}, "   ")
        with pytest.raises(ValueError, match="^carrier must be a non-empty string$"):
            sign_manifest({}, 42)


