import math

def build_thank_you_messages(conn: sqlite3.Connection, campaign: str, min_total: float=0.0, sort_by: str='total', descending: bool=True, offset: int=0, limit: int=50) -> list[dict]:
    if sort_by not in {'total', 'name', 'latest_donation', 'donation_count'}:
        raise ValueError('invalid sort field')
    if not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    if not isinstance(limit, int) or not 1 <= limit <= 100:
        raise ValueError('invalid limit')
    if not isinstance(min_total, (int, float)) or not math.isfinite(min_total) or min_total < 0:
        raise ValueError('invalid minimum')
    fields = {'total': 'total', 'name': 'name', 'latest_donation': 'latest_donation', 'donation_count': 'donation_count'}
    direction = 'DESC' if descending else 'ASC'
    query = f'SELECT d.id, d.name, ROUND(SUM(x.amount), 2) AS total,\n        COUNT(x.id) AS donation_count, MAX(x.donated_at) AS latest_donation\n        FROM donors d JOIN donations x ON x.donor_id = d.id\n        WHERE x.campaign = ?\n        GROUP BY d.id, d.name\n        HAVING SUM(x.amount) >= ?\n        ORDER BY {fields[sort_by]} {direction}, name ASC, d.id ASC\n        LIMIT ? OFFSET ?'
    rows = conn.execute(query, (campaign, min_total, limit, offset)).fetchall()
    result = []
    for donor_id, name, total, count, latest in rows:
