from datetime import datetime

def parse_reports(payload: str) -> list[dict]:
    try:
        data = json.loads(payload)
    except Exception as e:
        raise ValueError('invalid JSON') from e
    if not isinstance(data, list):
        raise ValueError('expected array')
    required = {'id', 'community_id', 'reporter_id', 'category', 'severity', 'created_at', 'status'}
    out = []
    ids = set()
    for item in data:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('invalid report')
        if any((not isinstance(item[k], str) for k in required - {'severity'})):
            raise ValueError('invalid report')
        if isinstance(item['severity'], bool) or not isinstance(item['severity'], int) or (not 1 <= item['severity'] <= 5):
            raise ValueError('invalid severity')
        if item['status'] not in {'open', 'reviewed', 'resolved'} or not item['created_at'].endswith('Z'):
            raise ValueError('invalid report')
        try:
            datetime.fromisoformat(item['created_at'][:-1] + '+00:00')
        except ValueError as e:
            raise ValueError('invalid timestamp') from e
        if item['id'] in ids:
            raise ValueError('duplicate id')
        ids.add(item['id'])
        out.append(dict(item))
    return out

def summarize_reports(reports: list[dict], requester: dict, limit: int=5) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('invalid limit')
    allowed = set(requester.get('community_ids', []))
    groups = {}
    for r in reports:
        if r['status'] == 'open' and r['community_id'] in allowed:
            key = (r['community_id'], r['category'])
            groups.setdefault(key, []).append(r)
    result = []
    for (community, category), items in groups.items():
        ordered = sorted(items, key=lambda r: (-r['severity'], -r['created_at'].__len__(), r['created_at'], r['id']), reverse=False)
        ordered = sorted(items, key=lambda r: (-r['severity'], r['created_at'], r['id']), reverse=False)
        result.append({'community_id': community, 'category': category, 'count': len(items), 'max_severity': max((r['severity'] for r in items)), 'report_ids': [r['id'] for r in ordered]})
    result.sort(key=lambda x: (-x['max_severity'], -x['count'], x['community_id'], x['category']))
    return result[:limit]

def resolve_reports(reports: list[dict], decisions: list[dict], requester: dict) -> list[dict]:
    by_id = {r['id']: r for r in reports}
    seen = set()
    for d in decisions:
        if not isinstance(d, dict) or set(d) != {'report_id', 'status'} or d['status'] not in {'reviewed', 'resolved'} or (d['report_id'] in seen) or (d['report_id'] not in by_id):
            raise ValueError('invalid decision')
        if by_id[d['report_id']]['status'] == 'resolved':
            raise ValueError('already resolved')
        seen.add(d['report_id'])
    if any((r['community_id'] not in set(requester.get('community_ids', [])) or not {'moderator', 'admin'} & set(requester.get('roles', [])) for r in [by_id[d['report_id']] for d in decisions])):
        raise PermissionError('not allowed')
    changes = {d['report_id']: d['status'] for d in decisions}
    return [dict(r, status=changes.get(r['id'], r['status'])) for r in reports]

