from lxml import etree
import math

def parse_talent_evaluations(xml_text: str, min_average: float=0.0, offset: int=0, limit: int | None=None) -> list[dict]:
    if not isinstance(xml_text, str) or not math.isfinite(min_average) or offset < 0 or (limit is not None and limit < 0):
        raise ValueError()
    parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, ValueError):
        raise ValueError()
    if root.tag != 'evaluations':
        raise ValueError()
    groups = {}
    for node in root:
        if node.tag != 'evaluation' or not node.get('athlete_id', '').strip():
            raise ValueError()
        aid = node.get('athlete_id').strip()
        fields = {}
        for tag in ('name', 'role', 'score'):
            matches = node.findall(tag)
            if len(matches) != 1 or matches[0].text is None or (not matches[0].text.strip()):
                raise ValueError()
            fields[tag] = matches[0].text.strip()
        try:
            score = float(fields['score'])
        except ValueError:
            raise ValueError()
        if not math.isfinite(score) or not 0 <= score <= 100:
            raise ValueError()
        if aid in groups and groups[aid][0] != fields['name']:
            raise ValueError()
        if aid not in groups:
            groups[aid] = [fields['name'], []]
        groups[aid][1].append((score, fields['role']))
    rows = []
    for aid, (name, values) in groups.items():
        average = sum((x[0] for x in values)) / len(values)
        if average >= min_average:
            highest = max((x[0] for x in values))
            role = min((x[1] for x in values if x[0] == highest))
            rows.append((average, name, aid, {'athlete_id': aid, 'name': name, 'average_score': round(average, 2), 'evaluation_count': len(values), 'top_role': role}))
    rows.sort(key=lambda x: (-x[0], x[1], x[2]))
    result = [x[3] for x in rows[offset:]]
    return result if limit is None else result[:limit]

