import hashlib
import hmac
import json

def verify_fleet_webhook(payload: bytes, signature: str, signing_key: bytes) -> dict:
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature format')
    digest = signature[7:]
    if any((c not in '0123456789abcdef' for c in digest)):
        raise ValueError('invalid signature format')
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(digest, expected):
        raise ValueError('signature mismatch')
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict):
        raise ValueError('payload must be an object')
    if not all((isinstance(value.get(field), str) for field in ('event_id', 'vehicle_id', 'status'))):
        raise ValueError('invalid event fields')
    if value['status'] not in {'available', 'rented', 'maintenance'}:
        raise ValueError('invalid event status')
    return value

