from solution import check_donor_eligibility
import os
import tempfile

def write_records(contents):
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    handle.write(contents)
    handle.close()
    return handle.name

def test_age_is_first_failure_reason():
    path = write_records('D101,17,45,10\n')
    try:
        assert check_donor_eligibility(path, 'D101') == {'donor_id': 'D101', 'eligible': False, 'reason': 'age'}
    finally:
        os.unlink(path)

def test_weight_failure():
    path = write_records('D102,30,49.9,90\n')
    try:
        assert check_donor_eligibility(path, 'D102')['reason'] == 'weight'
        assert check_donor_eligibility(path, 'D102')['eligible'] is False
    finally:
        os.unlink(path)

def test_interval_failure_and_boundaries():
    path = write_records('D103,18,50,55\nD104,65,50,56\n')
    try:
        assert check_donor_eligibility(path, 'D103')['reason'] == 'donation_interval'
        assert check_donor_eligibility(path, 'D104') == {'donor_id': 'D104', 'eligible': True, 'reason': 'eligible'}
    finally:
        os.unlink(path)

def test_blank_lines_duplicate_records_and_exact_match():
    path = write_records('\nD105,25,60,70\nD105,17,40,1\nD105-extra,25,60,70\n')
    try:
        assert check_donor_eligibility(path, 'D105') == {'donor_id': 'D105', 'eligible': True, 'reason': 'eligible'}
    finally:
        os.unlink(path)

def test_missing_donor_raises_value_error():
    path = write_records('D106,25,60,70\n')
    try:
        try:
            check_donor_eligibility(path, 'D999')
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(path)

def test_missing_file_and_malformed_record():
    try:
        check_donor_eligibility('/tmp/does-not-exist-for-donor-test', 'D107')
        assert False
    except FileNotFoundError:
        pass
    path = write_records('D107,25,sixty,70\n')
    try:
        try:
            check_donor_eligibility(path, 'D107')
            assert False
        except ValueError:
            pass
    finally:
        os.unlink(path)

