import os
import subprocess

def check_donor_eligibility(record_file: str, donor_id: str) -> dict:
    if not os.path.exists(record_file):
        raise FileNotFoundError(record_file)
    result = subprocess.run(['grep', '-F', '--', donor_id, record_file], capture_output=True, text=True, check=False)
    if result.returncode not in (0, 1):
        raise ValueError('unable to read records')
    record = None
    for line in result.stdout.splitlines():
        fields = line.split(',')
        if fields and fields[0] == donor_id:
            record = fields
            break
    if record is None:
        raise ValueError('donor not found')
    if len(record) != 4:
        raise ValueError('malformed record')
    try:
        age = int(record[1])
        weight = float(record[2])
        days = int(record[3])
    except ValueError as exc:
        raise ValueError('malformed record') from exc
    reason = 'eligible'
    if not 18 <= age <= 65:
        reason = 'age'
    elif weight < 50:
        reason = 'weight'
    elif days < 56:
        reason = 'donation_interval'
    return {'donor_id': donor_id, 'eligible': reason == 'eligible', 'reason': reason}

