import math
import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def generate_invite_code(length: int=10) -> str:
    if type(length) is not int or not 6 <= length <= 32:
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def _validate_questions(question_ids):
    if not isinstance(question_ids, list) or any((type(x) is not str or not x for x in question_ids)):
        raise ValueError('invalid questions')
    if len(set(question_ids)) != len(question_ids):
        raise ValueError('duplicate question')

def parse_response(text: str, question_ids: list[str]) -> dict[str, str]:
    if not isinstance(text, str):
        raise ValueError('invalid text')
    _validate_questions(question_ids)
    found = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        left = []
        right = []
        target = left
        escaped = False
        seen = False
        for ch in raw:
            if escaped:
                if ch not in '\\=':
                    raise ValueError('invalid escape')
                target.append(ch)
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '=' and (not seen):
                seen = True
                target = right
            else:
                target.append(ch)
        if escaped or not seen:
            raise ValueError('malformed line')
        key = ''.join(left).strip()
        value = ''.join(right).strip()
        if key not in question_ids or key in found or (not value):
            raise ValueError('invalid response')
        found[key] = value
    if set(found) != set(question_ids):
        raise ValueError('missing response')
    return {key: found[key] for key in question_ids}

def summarize_responses(responses: list[dict[str, str]], question_ids: list[str]) -> dict:
    _validate_questions(question_ids)
    if not isinstance(responses, list):
        raise ValueError('invalid responses')
    output = {q: {'counts': {}, 'numeric_mean': None} for q in question_ids}
    for response in responses:
        if not isinstance(response, dict) or set(response) != set(question_ids):
            raise ValueError('invalid response')
        for q in question_ids:
            value = response[q]
            if type(value) is not str or not value:
                raise ValueError('invalid value')
            output[q]['counts'][value] = output[q]['counts'].get(value, 0) + 1
    for q in question_ids:
        counts = output[q]['counts']
        output[q]['counts'] = dict(sorted(counts.items(), key=lambda item: (-item[1], item[0])))
        nums = []
