import base64
import datetime
import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return 'pbkdf2$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password or not isinstance(stored, str):
        return False
    try:
        kind, salt_text, digest_text = stored.split('$', 2)
        if kind != 'pbkdf2':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def forecast_report(records: list[dict], site: str, start: str, end: str, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(site, str):
        raise TypeError('site must be a string')
    if isinstance(page, bool) or isinstance(page_size, bool) or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        first = datetime.date.fromisoformat(start)
        last = datetime.date.fromisoformat(end)
    except Exception as exc:
        raise ValueError('invalid date') from exc
    if start != first.isoformat() or end != last.isoformat() or first > last:
        raise ValueError('invalid date range')
    totals = {}
    for record in records:
        try:
            record_site = record['site']
            stamp = record['timestamp']
            amount = record['kwh']
            moment = datetime.datetime.fromisoformat(stamp)
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or amount < 0:
            raise ValueError('invalid generation')
        day = moment.date()
        if record_site == site and first <= day <= last:
            key = day.isoformat()
            totals[key] = totals.get(key, 0) + amount
    rows = [{'date': key, 'kwh': round(totals[key], 2)} for key in sorted(totals)]
    offset = (page - 1) * page_size
    return rows[offset:offset + page_size]

