                raise ValueError
            stamp = datetime.strptime(fields[0], '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
        except ValueError:
            raise ValueError('invalid timestamp')
        output.append({'timestamp': stamp, 'permit_id': fields[1], 'reviewer': fields[2], 'status': fields[3], 'note': fields[4]})
    return output

def review_dashboard(records: list[dict], as_of: datetime) -> list[dict]:
    if as_of.tzinfo is None or as_of.utcoffset() is None:
        raise ValueError('as_of must be timezone-aware')
    grouped = {}
    for index, record in enumerate(records):
        permit = record['permit_id']
        grouped.setdefault(permit, []).append((index, record))
    priority = {'request_changes': 0, 'pending': 1, 'approved': 2, 'denied': 3}
    result = []
    for permit, items in grouped.items():
        latest = max(items, key=lambda x: (x[1]['timestamp'], x[0]))[1]
        if latest['timestamp'] > as_of:
            raise ValueError('record is in the future')
        counts = {name: 0 for name in ('pending', 'approved', 'denied', 'request_changes')}
        for _, item in items:
            counts[item['status']] += 1
        result.append({'permit_id': permit, 'latest_status': latest['status'], 'latest_reviewer': latest['reviewer'], 'latest_timestamp': latest['timestamp'], 'age_days': (as_of - latest['timestamp']).days, 'counts': counts, 'review_count': len(items)})
    result.sort(key=lambda x: (priority[x['latest_status']], -x['latest_timestamp'].timestamp(), x['permit_id']))
    return result

def issue_invite(permit_id: str, reviewer: str, existing: set[str]) -> str:
    if not isinstance(permit_id, str) or not permit_id or (not isinstance(reviewer, str)) or (not reviewer) or (not isinstance(existing, set)) or any((not isinstance(x, str) for x in existing)):
        raise ValueError('invalid arguments')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    while True:
        code = 'AR-' + ''.join((random.choice(alphabet) for _ in range(10)))
        if code not in existing:
            return code

