def test_serialization_is_deterministic_and_sorted():
    first = {"z": 1, "a": {"d": 4, "b": 2}}
    second = {"a": {"b": 2, "d": 4}, "z": 1}
    assert serialize_reconciliation(first) == serialize_reconciliation(second)
    assert serialize_reconciliation(first) == b'{"a":{"b":2,"d":4},"z":1}'


