    state = {"cash": 25.75, "refunds": [], "balanced": True}
    payload = serialize_reconciliation(state).decode("utf-8")
    assert deserialize_reconciliation(payload) == state


def test_empty_state_round_trip():
    assert deserialize_reconciliation(serialize_reconciliation({})) == {}


def test_invalid_state_shapes_are_rejected():
    with pytest.raises(TypeError):
        serialize_reconciliation([{"amount": 3}])
    with pytest.raises(TypeError):
        serialize_reconciliation({1: "numeric key"})
    with pytest.raises(TypeError):
        serialize_reconciliation({"amount": float("nan")})
    with pytest.raises(TypeError):
        serialize_reconciliation({"amount": object()})


