import json
from typing import Any

def _check_value(value: Any) -> None:
    if isinstance(value, dict):
        for key, item in value.items():
            if not isinstance(key, str):
                raise TypeError('dictionary keys must be strings')
            _check_value(item)
    elif isinstance(value, list):
        for item in value:
            _check_value(item)
    elif value is None or isinstance(value, (str, int, float, bool)):
        if isinstance(value, float) and (not __import__('math').isfinite(value)):
            raise TypeError('non-finite numbers are not supported')
    else:
        raise TypeError('unsupported state value')

def serialize_reconciliation(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise TypeError('state must be a dictionary')
    _check_value(state)
    return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')

def deserialize_reconciliation(payload: bytes | str) -> dict:
    try:
        if isinstance(payload, bytes):
            value = json.loads(payload.decode('utf-8'))
        elif isinstance(payload, str):
            value = json.loads(payload)
        else:
            raise ValueError('payload must be bytes or text')
        if not isinstance(value, dict):
            raise ValueError('payload must contain a dictionary')
        _check_value(value)
        return value
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid reconciliation payload') from exc

