class UsageMeter:

    def __init__(self) -> None:
        self._users = {}
        self._usage = {}

    def register(self, username: str, password: str) -> None:
        if not isinstance(username, str) or not re.fullmatch('[A-Za-z0-9_.-]+', username):
            raise ValueError('invalid username')
        if not isinstance(password, str) or not password:
            raise ValueError('invalid password')
        if username in self._users:
            raise ValueError('duplicate username')
        salt = os.urandom(16)
        digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        self._users[username] = (salt, digest)
        self._usage[username] = []

    def authenticate(self, username: str, password: str) -> bool:
        item = self._users.get(username)
        if item is None or not isinstance(password, str):
            return False
        salt, expected = item
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)

    def add_usage(self, username: str, password: str, batch: str) -> int:
        if not self.authenticate(username, password):
            raise PermissionError('authentication failed')
        if not isinstance(batch, str):
            raise ValueError('invalid batch')
        parsed = []
        try:
            for row in csv.reader(io.StringIO(batch)):
                if not row or all((x == '' for x in row)):
                    continue
                if len(row) != 3:
                    raise ValueError('invalid record')
                timestamp = int(row[0])
                service = row[1]
                units = int(row[2])
                if not service or units < 0:
                    raise ValueError('invalid record')
                parsed.append((timestamp, service, units))
        except (ValueError, TypeError, OverflowError):
            raise ValueError('invalid batch')
        self._usage[username].extend(parsed)
        return len(parsed)

    def report(self, username: str, password: str, start: int, end: int, bucket: int) -> list[dict[str, object]]:
        if not self.authenticate(username, password):
            raise PermissionError('authentication failed')
        if any((type(x) is not int for x in (start, end, bucket))) or start >= end or bucket <= 0:
            raise ValueError('invalid range')
        result = []
        for begin in range(start, end, bucket):
            finish = min(begin + bucket, end)
            totals = {}
            for timestamp, service, units in self._usage[username]:
                if begin <= timestamp < finish:
                    totals[service] = totals.get(service, 0) + units
            result.append({'start': begin, 'totals': {k: totals[k] for k in sorted(totals)}})
        return result

