import math
from lxml import etree

def _number(value, duration=False):
    s = value.strip()
    parts = s.split(':')
    try:
        if len(parts) == 1:
            x = float(s)
        elif len(parts) == 3 and all((len(p) == 2 for p in parts[:2])):
            if len(parts[2]) < 2 or len(parts[2]) > 6:
                raise ValueError
            h, m, sec = (int(parts[0]), int(parts[1]), float(parts[2]))
            if m >= 60 or sec >= 60:
                raise ValueError
            x = h * 3600 + m * 60 + sec
        else:
            raise ValueError
    except (TypeError, ValueError):
        raise ValueError
    if not math.isfinite(x) or x < 0 or (duration and x == 0):
        raise ValueError
    return float(x)

def parse_ad_schedule(xml_text: str) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as e:
        raise ValueError from e
    if root.tag != 'manifest':
        raise ValueError
    result, ids = ([], set())
    for node in root.iter('adBreak'):
        try:
            ident = node.get('id', '').strip()
            if not ident or ident in ids:
                raise ValueError
            children = node.findall('creative')
            if len(children) != 1:
                raise ValueError
            c = children[0]
            typ, uri = (c.get('type', '').strip(), c.get('uri', '').strip())
            if not typ or not uri:
                raise ValueError
            item = {'id': ident, 'time': _number(node.get('time', '')), 'duration': _number(node.get('duration', ''), True), 'type': typ, 'uri': uri}
        except (TypeError, ValueError):
            raise ValueError
        ids.add(ident)
        result.append(item)
    return sorted(result, key=lambda x: (x['time'], x['id']))

def build_timeline(segments: list[dict], breaks: list[dict]) -> list[dict]:
    for i, s in enumerate(segments):
        if s['start'] >= s['end'] or (i and segments[i - 1]['end'] > s['start']):
            raise ValueError
    ordered = sorted(breaks, key=lambda x: x['time'])
    for a, b in zip(ordered, ordered[1:]):
        if a['time'] + a['duration'] > b['time']:
            raise ValueError
    out = []
    for s in segments:
        here = [b for b in ordered if s['start'] <= b['time'] < s['end']]
        pos = s['start']
        for b in here:
            end = b['time'] + b['duration']
            if end > s['end']:
