    try:
        with tempfile.TemporaryDirectory() as output:
            try:
                process_scan_bundle(archive, output, ["bad.json"])
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(archive)


def test_non_object_vulnerability_raises_value_error():
    archive = make_bundle({"bad.json": {"vulnerabilities": ["HIGH"]}})
    try:
        with tempfile.TemporaryDirectory() as output:
            try:
                process_scan_bundle(archive, output, ["bad.json"])
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(archive)


def test_missing_severity_is_unknown_and_json_is_written():
    archive = make_bundle({"reports/current.json": {"vulnerabilities": [{}, {"severity": "medium"}]}})
    try:
        with tempfile.TemporaryDirectory() as output:
            result = process_scan_bundle(archive, output, ["reports/current.json"])
            assert result["total"] == 2
            assert result["counts"] == {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 1, "LOW": 0, "UNKNOWN": 1}
            with open(os.path.join(output, "reports", "current.json"), encoding="utf-8") as stream:
                assert json.load(stream)["vulnerabilities"][1]["severity"] == "medium"
