def list_certificates(conn: sqlite3.Connection, issuer: str | None=None, status: str | None=None, search: str | None=None, sort_by: str='expires_at', descending: bool=False, page: int=1, page_size: int=20) -> list[dict[str, object]]:
    allowed = {'id', 'subject', 'issuer', 'status', 'expires_at', 'serial'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if not isinstance(descending, bool):
        raise ValueError('descending must be boolean')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    clauses = []
    params = []
    if issuer is not None:
        clauses.append('issuer = ?')
        params.append(issuer)
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if search is not None:
        clauses.append('instr(subject, ?) > 0')
        params.append(search)
    query = 'SELECT id, subject, issuer, status, expires_at, serial FROM certificates'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    direction = 'DESC' if descending else 'ASC'
    query += f' ORDER BY {sort_by} {direction}, id ASC LIMIT ? OFFSET ?'
    params.extend([page_size, (page - 1) * page_size])
    rows = conn.execute(query, params).fetchall()
    keys = ('id', 'subject', 'issuer', 'status', 'expires_at', 'serial')
    return [dict(zip(keys, row)) for row in rows]

