from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def build_billing_report(claims: list[dict], page: int=1, page_size: int=50, config: dict[str, str] | None=None) -> dict:
    if not isinstance(claims, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid report arguments')
    groups = {}
    for claim in claims:
        if not isinstance(claim, dict):
            raise ValueError('invalid claim')
        for field in ('patient_id', 'procedure', 'date', 'status', 'amount'):
            if field not in claim:
                raise ValueError('invalid claim')
        if not isinstance(claim['patient_id'], str) or not claim['patient_id'] or (not isinstance(claim['procedure'], str)) or (not claim['procedure']) or (not isinstance(claim['date'], str)) or (not claim['date']):
            raise ValueError('invalid claim')
        try:
            amount = Decimal(str(claim['amount']))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount')
        if not amount.is_finite() or amount < 0:
            raise ValueError('invalid amount')
        if claim['status'] == 'submitted':
            item = groups.setdefault(claim['patient_id'], [Decimal('0'), 0])
            item[0] += amount
            item[1] += 1
    rows = [{'patient_id': pid, 'claim_count': value[1], 'total': str(value[0].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for pid, value in groups.items()]
    rows.sort(key=lambda row: (-Decimal(row['total']), row['patient_id']))
    total = len(rows)
    total_pages = (total + page_size - 1) // page_size if total else 0
    start = (page - 1) * page_size
    payload = {'page': page, 'page_size': page_size, 'total_patients': total, 'total_pages': total_pages, 'patients': rows[start:start + page_size]}
    if config is not None:
        key = config.get('BILLING_SIGNING_KEY')
    else:
        key = os.environ.get('BILLING_SIGNING_KEY')
    if key is None:
        raise RuntimeError('BILLING_SIGNING_KEY is required')
    raw = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    payload['signature'] = hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()
    return payload

