import xml.etree.ElementTree as ET
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation

def parse_campaign(xml_text: str) -> dict:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'campaign':
        raise ValueError('wrong root')
    cid = (root.get('id') or '').strip()
    name = (root.get('name') or '').strip()
    if not cid or not name:
        raise ValueError('missing campaign value')
    donations = []
    container = root.find('donations')
    if container is not None:
        for node in list(container):
            if node.tag != 'donation':
                continue
            donor = (node.get('donor') or '').strip()
            currency = (node.get('currency') or '').strip()
            raw_amount = (node.get('amount') or '').strip()
            raw_date = (node.get('date') or '').strip()
            if not donor or currency != 'USD':
                raise ValueError('invalid donation')
            try:
                amount = Decimal(raw_amount)
                parsed_date = date.fromisoformat(raw_date)
            except (InvalidOperation, ValueError):
                raise ValueError('invalid donation')
            if parsed_date.isoformat() != raw_date or amount <= 0 or amount.as_tuple().exponent < -2:
                raise ValueError('invalid donation')
            donations.append({'donor': donor, 'amount': float(amount), 'currency': currency, 'date': raw_date})
    return {'id': cid, 'name': name, 'donations': donations}

def rank_campaigns(documents: list[str], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('invalid window')
    parsed = [parse_campaign(doc) for doc in documents]
    if len({item['id'] for item in parsed}) != len(parsed):
        raise ValueError('duplicate campaign')
    result = []
    for item in parsed:
        entries = [(date.fromisoformat(x['date']), x['amount']) for x in item['donations']]
        total = sum((amount for _, amount in entries))
        donors = len({x['donor'] for x in item['donations']})
        if not entries:
            peak = {'start': None, 'end': None, 'amount': 0.0}
        else:
            best_start = None
            best_amount = -1.0
            for start, _ in entries:
                end = start + timedelta(days=window_days - 1)
                amount = sum((value for day, value in entries if start <= day <= end))
                if amount > best_amount or (amount == best_amount and (best_start is None or start < best_start)):
                    best_start, best_amount = (start, amount)
            peak = {'start': best_start.isoformat(), 'end': (best_start + timedelta(days=window_days - 1)).isoformat(), 'amount': float(best_amount)}
        result.append({'id': item['id'], 'name': item['name'], 'total': float(total), 'donors': donors, 'peak_window': peak})
    return sorted(result, key=lambda x: (-x['total'], -x['donors'], x['id']))

