import hashlib
import hmac
import math
import os

def register_user(users: dict, username: str, password: str, latitude: float, longitude: float, radius_km: float, minimum_severity: int) -> None:
    if not isinstance(username, str) or not username or any((c.isspace() for c in username)):
        raise ValueError('invalid username')
    if username in users or not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid account')
    if not isinstance(latitude, (int, float)) or not -90 <= latitude <= 90:
        raise ValueError('invalid latitude')
    if not isinstance(longitude, (int, float)) or not -180 <= longitude <= 180:
        raise ValueError('invalid longitude')
    if not isinstance(radius_km, (int, float)) or not 0 <= radius_km <= 2000:
        raise ValueError('invalid radius')
    if isinstance(minimum_severity, bool) or not isinstance(minimum_severity, int) or (not 1 <= minimum_severity <= 5):
        raise ValueError('invalid severity')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    users[username] = {'hash': digest, 'salt': salt, 'lat': float(latitude), 'lon': float(longitude), 'radius': float(radius_km), 'minimum': minimum_severity, 'seen': set()}

def authenticate(users: dict, username: str, password: str) -> bool:
    try:
        account = users[username]
        if not isinstance(password, str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), account['salt'], 120000)
        return hmac.compare_digest(actual, account['hash'])
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

def process_alerts(users: dict, events: list[dict], start_time: int, end_time: int) -> list[tuple[int, str, str, int]]:
    if isinstance(start_time, bool) or not isinstance(start_time, int) or isinstance(end_time, bool) or (not isinstance(end_time, int)) or (start_time > end_time):
        raise ValueError('invalid time range')
    checked = []
    for pos, event in enumerate(events):
        if not isinstance(event, dict) or not isinstance(event.get('id'), str) or (not event['id']):
            raise ValueError('invalid event')
        if isinstance(event.get('timestamp'), bool) or not isinstance(event.get('timestamp'), int):
            raise ValueError('invalid event')
        lat, lon, severity = (event.get('latitude'), event.get('longitude'), event.get('severity'))
        if not isinstance(lat, (int, float)) or not -90 <= lat <= 90 or (not isinstance(lon, (int, float))) or (not -180 <= lon <= 180) or isinstance(severity, bool) or (not isinstance(severity, int)) or (not 1 <= severity <= 5):
            raise ValueError('invalid event')
        if start_time <= event['timestamp'] < end_time:
            checked.append((event['timestamp'], pos, event))
    checked.sort(key=lambda x: (x[0], x[1]))
    result = []
    for timestamp, _, event in checked:
        for username, account in users.items():
            if event['id'] in account.get('seen', set()):
                continue
            angle = math.radians(event['latitude'] - account['lat']) ** 2 + math.radians(event['longitude'] - account['lon']) ** 2
            distance = 6371.0088 * 2 * math.asin(math.sqrt(min(1, angle / 4)))
            if distance <= account['radius'] and event['severity'] >= account['minimum']:
                account['seen'].add(event['id'])
                result.append((timestamp, username, event['id'], event['severity'], distance))
    result.sort(key=lambda x: (x[0], x[4], x[1], x[2]))
    return [x[:4] for x in result]

