import sqlite3

def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS consents (id INTEGER PRIMARY KEY, user_id TEXT NOT NULL, purpose TEXT NOT NULL, granted INTEGER NOT NULL, changed_at INTEGER NOT NULL)')
    conn.commit()

def record_consent(conn: sqlite3.Connection, user_id: str, purpose: str, granted: bool, changed_at: int) -> int:
    if not isinstance(user_id, str) or not user_id or (not isinstance(purpose, str)) or (not purpose):
        raise ValueError('invalid text')
    if type(granted) is not bool or type(changed_at) is not int:
        raise ValueError('invalid value')
    cur = conn.execute('INSERT INTO consents (user_id, purpose, granted, changed_at) VALUES (?, ?, ?, ?)', (user_id, purpose, int(granted), changed_at))
    conn.commit()
    return int(cur.lastrowid)

def list_consents(conn: sqlite3.Connection, user_id: str | None=None, purpose: str | None=None, granted: bool | None=None, sort: str='changed_at', descending: bool=False) -> list[tuple[int, str, str, bool, int]]:
    allowed = {'id', 'user_id', 'purpose', 'granted', 'changed_at'}
    if sort not in allowed or type(descending) is not bool:
        raise ValueError('invalid ordering')
    if user_id is not None and (not isinstance(user_id, str) or not user_id):
        raise ValueError('invalid user')
    if purpose is not None and (not isinstance(purpose, str) or not purpose):
        raise ValueError('invalid purpose')
    if granted is not None and type(granted) is not bool:
        raise ValueError('invalid consent')
    clauses = []
    values = []
    if user_id is not None:
        clauses.append('user_id = ?')
        values.append(user_id)
    if purpose is not None:
        clauses.append('purpose = ?')
        values.append(purpose)
    if granted is not None:
        clauses.append('granted = ?')
        values.append(int(granted))
    query = 'SELECT id, user_id, purpose, granted, changed_at FROM consents'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    direction = ' DESC' if descending else ' ASC'
    query += ' ORDER BY ' + sort + direction + ', id ASC'
    rows = conn.execute(query, values).fetchall()
    return [(int(i), u, p, bool(g), int(t)) for i, u, p, g, t in rows]

def consent_summary(conn: sqlite3.Connection, user_id: str) -> dict[str, dict[str, int | bool]]:
    if not isinstance(user_id, str) or not user_id:
        raise ValueError('invalid user')
    rows = list_consents(conn, user_id=user_id, sort='changed_at')
    result = {}
    for ident, uid, purpose, granted, changed_at in rows:
        if purpose not in result:
            result[purpose] = {'current': granted, 'changes': 1}
        else:
            result[purpose]['changes'] += 1
            result[purpose]['current'] = granted
    return result

