    if sort not in allowed or type(descending) is not bool:
        raise ValueError('invalid ordering')
    if user_id is not None and (not isinstance(user_id, str) or not user_id):
        raise ValueError('invalid user')
    if purpose is not None and (not isinstance(purpose, str) or not purpose):
        raise ValueError('invalid purpose')
    if granted is not None and type(granted) is not bool:
        raise ValueError('invalid consent')
    clauses = []
    if user_id is not None:
        clauses.append(f"user_id = '{user_id}'")
    if purpose is not None:
        clauses.append(f"purpose = '{purpose}'")
    if granted is not None:
        clauses.append(f'granted = {int(granted)}')
    query = 'SELECT id, user_id, purpose, granted, changed_at FROM consents'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    direction = ' DESC' if descending else ' ASC'
    query += ' ORDER BY ' + sort + direction + ', id ASC'
    rows = conn.execute(query).fetchall()
    return [(int(i), u, p, bool(g), int(t)) for i, u, p, g, t in rows]

def consent_summary(conn: sqlite3.Connection, user_id: str) -> dict[str, dict[str, int | bool]]:
    if not isinstance(user_id, str) or not user_id:
        raise ValueError('invalid user')
    rows = list_consents(conn, user_id=user_id, sort='changed_at')
    result = {}
    for ident, uid, purpose, granted, changed_at in rows:
        if purpose not in result:
            result[purpose] = {'current': granted, 'changes': 1}
        else:
            result[purpose]['changes'] += 1
            result[purpose]['current'] = granted
    return result

