            given = next((x for x in name if x.tag == 'given'), None)
            family = next((x for x in name if x.tag == 'family'), None)
            if given is None or family is None or (not (given.text or '').strip()) or (not (family.text or '').strip()):
                raise ValueError('invalid name')
            address_nodes = [x for x in voter if x.tag == 'address']
            if len(address_nodes) > 1:
                raise ValueError('invalid address')
            lines = []
            if address_nodes:
                lines = [(x.text or '').strip() for x in address_nodes[0] if x.tag == 'line' and (x.text or '').strip()]
                if not lines:
                    raise ValueError('invalid address')
            flags_nodes = [x for x in voter if x.tag == 'flags']
            if len(flags_nodes) > 1:
