            groups[precinct] = {'precinct': precinct, 'active': 0, 'pending': 0, 'inactive': 0, 'total': 0}
        groups[precinct][status] += 1
        groups[precinct]['total'] += 1
    return sorted(groups.values(), key=lambda x: (-x['active'], -x['pending'], x['inactive'], x['precinct']))

