import re

def normalize_card(value: str) -> str:
    if not isinstance(value, str):
        raise TypeError('card number must be a string')
    if re.search('[^0-9 -]', value):
        raise ValueError('invalid card characters')
    digits = value.replace(' ', '').replace('-', '')
    if not 13 <= len(digits) <= 19:
        raise ValueError('invalid card length')
    total = 0
    parity = len(digits) % 2
    for i, char in enumerate(digits):
        n = int(char)
        if i % 2 == parity:
            n *= 2
            if n > 9:
                n -= 9
        total += n
    if total % 10:
        raise ValueError('invalid card checksum')
    return digits

class CardVault:

    def __init__(self, secret: str) -> None:
        if not isinstance(secret, str) or not secret:
            raise ValueError('invalid secret')
        self._secret = secret.encode()
        self._records = {}
        self.today = datetime.date.today()

    def _check_requester(self, requester):
        if not isinstance(requester, dict):
            raise TypeError('invalid requester')
        if not isinstance(requester.get('id'), str) or not isinstance(requester.get('tenant'), str):
            raise ValueError('invalid requester')
        if not isinstance(requester.get('roles'), list):
            raise ValueError('invalid requester')

    def _permitted(self, requester, record):
        return record['tenant'] == requester['tenant']

    def put_card(self, requester: dict, card_number: str, expiry: str) -> str:
        self._check_requester(requester)
        digits = normalize_card(card_number)
        if not isinstance(expiry, str) or not re.fullmatch('[0-9]{4}-[0-9]{2}', expiry):
            raise ValueError('invalid expiry')
        year, month = map(int, expiry.split('-'))
        if not 1 <= month <= 12 or (year, month) < (self.today.year, self.today.month):
            raise ValueError('expired card')
        data = f"{requester['tenant']}|{digits}|{expiry}".encode()
        token = 'ctok_' + hmac.new(self._secret, data, hashlib.sha256).hexdigest()[:24]
        self._records[token] = {'digits': digits, 'expiry': expiry, 'owner_id': requester['id'], 'tenant': requester['tenant']}
        return token

    def get_card(self, requester: dict, token: str) -> dict:
        self._check_requester(requester)
        if not isinstance(token, str):
            raise TypeError('invalid token')
        if not token.startswith('ctok_'):
            raise ValueError('invalid token')
        record = self._records[token]
        if not self._permitted(requester, record):
            raise PermissionError('not permitted')
        return {'card_number': '*' * (len(record['digits']) - 4) + record['digits'][-4:], 'expiry': record['expiry'], 'owner_id': record['owner_id'], 'tenant': record['tenant']}

    def list_cards(self, requester: dict) -> list[dict]:
        self._check_requester(requester)
        pairs = [(k, r) for k, r in self._records.items() if self._permitted(requester, r)]
