import math
import secrets

def generate_partner_code(length: int=12) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length < 8 or (length > 32):
        raise ValueError('invalid length')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ123456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def build_bid_report(records: list[dict], min_spend: float=0.0, page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(min_spend, bool) or not isinstance(min_spend, (int, float)) or (not math.isfinite(min_spend)) or (min_spend < 0):
        raise ValueError('invalid minimum')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('campaign'), str) or (not record['campaign']):
            raise ValueError('invalid record')
        for key in ('impressions', 'clicks', 'spend', 'revenue'):
            value = record.get(key)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) or (value < 0):
                raise ValueError('invalid record')
        if not isinstance(record['impressions'], int) or not isinstance(record['clicks'], int) or record['clicks'] > record['impressions']:
            raise ValueError('invalid record')
        name = record['campaign']
        group = groups.setdefault(name, [0, 0, 0.0, 0.0])
        group[0] += record['impressions']
        group[1] += record['clicks']
        group[2] += record['spend']
        group[3] += record['revenue']
    rows = []
    for name, (impressions, clicks, spend, revenue) in groups.items():
        if spend >= min_spend:
            rows.append({'campaign': name, 'impressions': impressions, 'clicks': clicks, 'spend': round(spend, 2), 'revenue': round(revenue, 2), 'ctr': round(clicks / impressions if impressions else 0.0, 4), 'roas': round(revenue / spend if spend else 0.0, 4)})
    rows.sort(key=lambda row: (-row['spend'], row['campaign']))
    start = (page - 1) * page_size
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'items': rows[start:start + page_size]}

