import csv
import json
import os
from datetime import date, timedelta

def _path(base, name):
    root = os.path.realpath(base)
    candidate = os.path.realpath(os.path.join(root, name))
    try:
        if os.path.commonpath([root, candidate]) != root:
            raise ValueError('path outside base directory')
    except ValueError:
        raise ValueError('path outside base directory')
    return candidate

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def generate_replenishment_report(base_dir: str, inventory_file: str, report_file: str, as_of: str) -> dict:
    cutoff = _day(as_of)
    source = _path(base_dir, inventory_file)
    target = _path(base_dir, report_file)
    required = ['pet', 'sku', 'quantity', 'interval_days', 'last_order', 'priority']
    groups = {}
    with open(source, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != required:
            raise ValueError('invalid columns')
        for row in reader:
            if not row['pet'] or not row['sku']:
                raise ValueError('missing text')
            try:
                quantity = int(row['quantity'])
                interval = int(row['interval_days'])
                priority = int(row['priority'])
            except (TypeError, ValueError):
                raise ValueError('invalid number')
            if quantity <= 0 or interval < 0:
                raise ValueError('invalid number')
            ordered = _day(row['last_order'])
            due = ordered + timedelta(days=interval)
            if due <= cutoff:
                key = (row['pet'], row['sku'])
                if key not in groups:
                    groups[key] = {'pet': row['pet'], 'sku': row['sku'], 'quantity': 0, 'next_due': due, 'priority': priority}
                item = groups[key]
                item['quantity'] += quantity
                item['next_due'] = min(item['next_due'], due)
                item['priority'] = max(item['priority'], priority)
    items = list(groups.values())
