        if any((field not in record for field in _FIELDS)):
            raise ValueError('missing field')
        try:
            stamp = datetime.fromisoformat(record['started_at'].replace('Z', '+00:00'))
            day = stamp.date()
            duration = record['duration_minutes']
            specialty = record['specialty']
            status = record['status']
        except (TypeError, ValueError, AttributeError):
            raise ValueError('invalid record')
        if stamp.tzinfo is None or not isinstance(duration, int) or isinstance(duration, bool) or (duration < 0) or (status not in _STATUSES):
            raise ValueError('invalid record')
        if day < first or day > last:
            continue
        key = day.isoformat()
        days[key]['consultations'] += 1
        total += 1
        item = groups.setdefault(specialty, [0, 0, 0])
        item[0] += 1
        if status == 'completed':
            days[key]['completed'] += 1
            days[key]['completed_minutes'] += duration
            minutes += duration
            item[1] += duration
            item[2] += 1
    specialties = []
    for name, (count, done_minutes, done_count) in groups.items():
        specialties.append({'specialty': name, 'consultations': count, 'completed_minutes': done_minutes, 'average_completed_minutes': round(done_minutes / done_count, 2) if done_count else 0.0})
    specialties.sort(key=lambda x: (-x['completed_minutes'], x['specialty']))
    return {'total_consultations': total, 'completed_minutes': minutes, 'by_specialty': specialties, 'daily': list(days.values())}

