def rank_cards(cards: list[dict], expression: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid pagination')
    try:
        tree = ast.parse(expression, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid expression') from exc

    def evaluate(node, names):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in ('min', 'max', 'round'):
                return {'min': min, 'max': max, 'round': round}[node.id]
            if node.id not in names:
                raise ValueError('invalid expression')
            return names[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub):
            return operator.pos(evaluate(node.operand, names)) if isinstance(node.op, ast.UAdd) else operator.neg(evaluate(node.operand, names))
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (evaluate(node.left, names), evaluate(node.right, names))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            values = [evaluate(x, names) for x in node.values]
            result = values[0]
            for value in values[1:]:
                if isinstance(node.op, ast.And):
                    result = value if result else result
                else:
                    result = result if result else value
            return result
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not evaluate(node.operand, names)
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, names)
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, names)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(evaluate(a, names) for a in node.args))
        raise ValueError('invalid expression')
    scored = []
    for index, card in enumerate(cards):
        try:
            value = evaluate(tree, card)
            if value:
                scored.append((value, index, card))
        except ValueError:
            raise
        except Exception as exc:
            raise ValueError('invalid expression') from exc
    scored.sort(key=lambda item: item[0], reverse=True)
    result = [item[2] for item in scored[offset:]]
    return result if limit is None else result[:limit]

