import hashlib
import hmac
import os

def create_reviewer(username: str, password: str, clearance: int) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or not password:
        raise ValueError('invalid password')
    if isinstance(clearance, bool) or not isinstance(clearance, int) or clearance < 0:
        raise ValueError('invalid clearance')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'password_hash': salt.hex() + ':' + digest.hex(), 'clearance': clearance, 'active': True, 'documents': []}

def verify_reviewer_password(reviewer: dict, password: str) -> bool:
    if not isinstance(password, str) or not isinstance(reviewer, dict):
        return False
    value = reviewer.get('password_hash')
    if not isinstance(value, str) or ':' not in value:
        return False
    try:
        salt_text, digest_text = value.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def assign_document(reviewer: dict, document_id: str) -> None:
    if not isinstance(document_id, str) or not document_id.strip():
        raise ValueError('invalid document')
    value = document_id.strip()
    if value not in reviewer['documents']:
        reviewer['documents'].append(value)

def can_review(reviewer: dict, document_id: str, required_clearance: int) -> bool:
    if not isinstance(reviewer, dict) or not isinstance(document_id, str) or (not document_id.strip()):
        return False
    if isinstance(required_clearance, bool) or not isinstance(required_clearance, int) or required_clearance < 0:
