KINDS = ('filing', 'hearing', 'order', 'note')

def _split_record(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    if len(fields) != 3:
        raise ValueError('invalid record')
    return fields

def parse_docket(text: str) -> list[dict]:
    result = []
    for position, raw in enumerate(text.splitlines()):
        if not raw.strip():
            continue
        date, kind, description = _split_record(raw)
        if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date):
            raise ValueError('invalid date')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid date')
        if kind not in KINDS or not description:
            raise ValueError('invalid record')
        result.append({'date': date, 'kind': kind, 'description': description, '_p': position})
    result.sort(key=lambda x: (x['date'], KINDS.index(x['kind']), x['_p']))
    for item in result:
        del item['_p']
    return result

def summarize_matter(matter_id: str, events: list[dict]) -> dict:
    counts = {kind: 0 for kind in KINDS}
    grouped = {}
    for event in events:
        kind = event['kind']
        counts[kind] += 1
        month = event['date'][:7]
        if month not in grouped:
            grouped[month] = {'count': 0, 'characters': 0, 'by_kind': {k: 0 for k in KINDS}}
        grouped[month]['count'] += 1
        grouped[month]['characters'] += len(event['description'])
        grouped[month]['by_kind'][kind] += 1
    months = []
    for month in sorted(grouped):
        value = grouped[month]
        months.append({'month': month, **value})
    return {'matter_id': matter_id, 'event_count': len(events), 'by_kind': counts, 'months': months}

def export_matter_report(matter_id: str, docket_text: str, destination: str) -> dict:
    summary = summarize_matter(matter_id, parse_docket(docket_text))
    directory = os.path.dirname(os.path.abspath(destination))
