    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['matter_id', 'month', 'count', 'characters', *KINDS])
            for month in summary['months']:
                writer.writerow([matter_id, month['month'], month['count'], month['characters'], *[month['by_kind'][k] for k in KINDS]])
        os.replace(temporary, destination)
    except Exception:
        try:
