import hashlib
import hmac
import re
from collections.abc import Mapping

def _fields(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape in order')
    fields.append(''.join(current))
    return fields

def parse_orders(text: str) -> list[tuple[str, str, int, str]]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 4:
            raise ValueError('an order must contain four fields')
        employee, item, quantity, slot = fields
        if not employee or not item or (not re.fullmatch('[1-9][0-9]*', quantity)):
            raise ValueError('invalid order fields')
        if not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', slot):
            raise ValueError('invalid pickup slot')
        result.append((employee, item, int(quantity), slot))
    return result

def create_manifest(text: str, config: dict[str, str]) -> str:
    if not isinstance(config, Mapping) or 'CAFETERIA_SIGNING_KEY' not in config:
        raise ValueError('CAFETERIA_SIGNING_KEY is required')
    totals = {}
    for _, item, quantity, slot in parse_orders(text):
        totals[slot, item] = totals.get((slot, item), 0) + quantity
    lines = [f'{slot},{item},{total}' for (slot, item), total in sorted(totals.items())]
    body = '\n'.join(lines)
    signed = body + ('\n' if body else '')
    digest = hmac.new(str(config['CAFETERIA_SIGNING_KEY']).encode(), signed.encode(), hashlib.sha256).hexdigest()
    return signed + 'signature:' + digest

