import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_CONDITIONS = {'new': 0, 'good': 1, 'fair': 2}

def _split_escaped(line):
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current).strip())
    return fields

def parse_holdings(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    result = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _split_escaped(raw)
        if len(fields) != 4:
            raise ValueError('fields')
        isbn, library, count, condition = fields
        if not isbn or not library or condition not in _CONDITIONS:
            raise ValueError('value')
        try:
            copies = int(count)
        except (TypeError, ValueError):
            raise ValueError('copies')
        if str(copies) != count or copies < 0 or (isbn, library) in seen:
            raise ValueError('copies or duplicate')
        seen.add((isbn, library))
        result.append({'isbn': isbn, 'library': library, 'copies': copies, 'condition': condition})
    return result

def issue_code(length: int=12) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def allocate_loans(requests: list[dict], holdings: list[dict]) -> list[dict]:
    if not isinstance(requests, list) or not isinstance(holdings, list):
        raise ValueError('lists')
    stock = []
    for h in holdings:
        if not isinstance(h, dict) or set(h) != {'isbn', 'library', 'copies', 'condition'}:
            raise ValueError('holding')
        if not isinstance(h['isbn'], str) or not h['isbn'] or (not isinstance(h['library'], str)) or (not h['library']):
            raise ValueError('holding')
        if isinstance(h['copies'], bool) or not isinstance(h['copies'], int) or h['copies'] < 0 or (h['condition'] not in _CONDITIONS):
            raise ValueError('holding')
        stock.append(dict(h))
    checked = []
    for r in requests:
        if not isinstance(r, dict) or set(r) != {'patron', 'isbn', 'priority', 'days'}:
            raise ValueError('request')
        if not isinstance(r['patron'], str) or not r['patron'] or (not isinstance(r['isbn'], str)) or (not r['isbn']):
            raise ValueError('request')
        if any((isinstance(r[k], bool) or not isinstance(r[k], int) for k in ('priority', 'days'))) or r['priority'] < 0 or r['days'] <= 0:
            raise ValueError('request')
        checked.append(dict(r))
    checked.sort(key=lambda r: (-r['priority'], r['patron'], r['isbn']))
    result = []
    for r in checked:
        choices = [h for h in stock if h['isbn'] == r['isbn'] and h['copies']]
        if not choices:
            continue
        h = min(choices, key=lambda x: (_CONDITIONS[x['condition']], x['library']))
        h['copies'] -= 1
        result.append({'patron': r['patron'], 'isbn': r['isbn'], 'library': h['library'], 'days': r['days'], 'code': issue_code()})
    return result

