import sqlite3

def create_schema(conn: sqlite3.Connection) -> None:
    conn.executescript('\n    CREATE TABLE IF NOT EXISTS evidence (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        case_no TEXT NOT NULL,\n        item_no TEXT NOT NULL,\n        description TEXT NOT NULL,\n        status TEXT NOT NULL,\n        collected_at TEXT NOT NULL,\n        UNIQUE(case_no, item_no)\n    );\n    CREATE TABLE IF NOT EXISTS custody (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        evidence_id INTEGER NOT NULL,\n        officer TEXT NOT NULL,\n        action TEXT NOT NULL,\n        occurred_at TEXT NOT NULL,\n        FOREIGN KEY(evidence_id) REFERENCES evidence(id)\n    );\n    ')
    conn.commit()

def add_evidence(conn: sqlite3.Connection, case_no: str, item_no: str, description: str, collected_at: str) -> int:
    if any((not isinstance(x, str) or not x.strip() for x in (case_no, item_no, description, collected_at))):
        raise ValueError('empty value')
    try:
        cur = conn.execute('INSERT INTO evidence(case_no,item_no,description,status,collected_at) VALUES(?,?,?,?,?)', (case_no, item_no, description, 'in_custody', collected_at))
        conn.commit()
        return cur.lastrowid
    except sqlite3.IntegrityError as exc:
        conn.rollback()
        raise ValueError('duplicate evidence') from exc

def record_custody(conn: sqlite3.Connection, evidence_id: int, officer: str, action: str, occurred_at: str) -> None:
    if any((not isinstance(x, str) or not x.strip() for x in (officer, action, occurred_at))):
        raise ValueError('empty value')
    row = conn.execute('SELECT status FROM evidence WHERE id=?', (evidence_id,)).fetchone()
    if row is None:
        raise ValueError('missing evidence')
    count = conn.execute('SELECT COUNT(*) FROM custody WHERE evidence_id=?', (evidence_id,)).fetchone()[0]
    if count == 0 and action != 'received' or (count > 0 and action not in {'transferred', 'sealed', 'released'}) or row[0] == 'released':
        raise ValueError('invalid custody sequence')
    conn.execute('INSERT INTO custody(evidence_id,officer,action,occurred_at) VALUES(?,?,?,?)', (evidence_id, officer, action, occurred_at))
    if action == 'released':
        conn.execute("UPDATE evidence SET status='released' WHERE id=?", (evidence_id,))
    conn.commit()

def list_evidence(conn: sqlite3.Connection, case_no: str | None=None, status: str | None=None, search: str='', sort_by: str='collected_at', descending: bool=False) -> list[dict]:
    allowed = {'id', 'case_no', 'item_no', 'description', 'status', 'collected_at', 'custody_count'}
    if sort_by not in allowed:
        raise ValueError('invalid sort')
    clauses, params = ([], [])
    if case_no is not None:
        clauses.append('e.case_no=?')
        params.append(case_no)
    if status is not None:
        clauses.append('e.status=?')
        params.append(status)
    if search:
        clauses.append('(LOWER(e.case_no) LIKE ? OR LOWER(e.item_no) LIKE ? OR LOWER(e.description) LIKE ?)')
        value = '%' + search.lower() + '%'
        params.extend([value, value, value])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = ' DESC' if descending else ' ASC'
    order = 'custody_count' if sort_by == 'custody_count' else 'e.' + sort_by
    rows = conn.execute('SELECT e.id,e.case_no,e.item_no,e.description,e.status,e.collected_at,COUNT(c.id) AS custody_count, (SELECT officer FROM custody c2 WHERE c2.evidence_id=e.id ORDER BY c2.id DESC LIMIT 1) AS last_officer FROM evidence e LEFT JOIN custody c ON c.evidence_id=e.id' + where + ' GROUP BY e.id ORDER BY ' + order + direction + ', e.id ASC', params).fetchall()
    keys = ['id', 'case_no', 'item_no', 'description', 'status', 'collected_at', 'custody_count', 'last_officer']
    return [dict(zip(keys, row)) for row in rows]

