def enforce_rate_limit(requester: dict[str, Any], limiters: dict[str, dict[str, Any]], key: str, now: int) -> dict[str, Any]:
    record = limiters[key]
    same_tenant = requester.get('tenant_id') == record.get('tenant_id')
    owner = requester.get('id') == record.get('owner_id')
    administrator = same_tenant and 'rate_limit_admin' in requester.get('roles', [])
    if not (owner or administrator):
        raise PermissionError('not permitted')
    if now >= record['reset_at']:
        record['used'] = 0
    if record['used'] < record['limit']:
        record['used'] += 1
        return {'allowed': True, 'remaining': record['limit'] - record['used'], 'reset_at': record['reset_at']}
    return {'allowed': False, 'remaining': 0, 'reset_at': record['reset_at']}

