    try:
        tree = ast.parse(expression, mode='eval').body
        return _visit(tree, names)
    except (SyntaxError, KeyError, TypeError, ZeroDivisionError, ValueError, IndexError):
        raise ValueError('invalid expression')

def _visit(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise KeyError(node.id)
        return names[node.id]
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        a, b = (_visit(node.left, names), _visit(node.right, names))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _visit(node.operand, names)
        return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _visit(node.values[0], names)
        for part in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _visit(part, names)
        return value
    if isinstance(node, ast.Compare):
        left = _visit(node.left, names)
        for op, right_node in zip(node.ops, node.comparators):
            right = _visit(right_node, names)
            if not {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_visit(x, names) for x in node.args]
        if node.func.id == 'min':
            return min(*args)
        if node.func.id == 'max':
            return max(*args)
        return round(*args)
    raise ValueError('unsupported expression')

