    if not isinstance(campaigns, list) or (variables is not None and (not isinstance(variables, dict))):
        raise ValueError('invalid data')
    variables = variables or {}
    results, seen = ([], set())
    for campaign in campaigns:
        if not isinstance(campaign, dict) or not isinstance(campaign.get('id'), str) or (not campaign['id']) or (campaign['id'] in seen) or (not isinstance(campaign.get('donations'), list)):
            raise ValueError('invalid data')
        seen.add(campaign['id'])
        total = 0
        count = 0
        donors = set()
        last = None
        prior = 0
        for i, donation in enumerate(campaign['donations']):
            if not isinstance(donation, dict) or not isinstance(donation.get('donor'), str) or (not donation['donor']) or (not isinstance(donation.get('amount'), (int, float))) or isinstance(donation['amount'], bool) or (donation['amount'] < 0) or (not isinstance(donation.get('day'), int)) or isinstance(donation['day'], bool) or (donation['day'] < 0):
                raise ValueError('invalid data')
            env = dict(variables)
            env.update(amount=donation['amount'], day=donation['day'], index=i, prior=prior)
            if evaluate_rule(rule, env):
                total += donation['amount']
                count += 1
                donors.add(donation['donor'])
                last = donation['day'] if last is None else max(last, donation['day'])
                prior += donation['amount']
        results.append({'id': campaign['id'], 'total': total, 'count': count, 'donors': sorted(donors), 'last_day': last})
