def extract_work_orders(xml: str, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'work_orders':
        raise ValueError('invalid root')
    records = []
    for node in root:
        if node.tag != 'work_order':
            raise ValueError('invalid child')
        try:
            ident = node.attrib['id']
            item_status = node.attrib['status']
            priority = int(node.attrib['priority'])
            hours = float(node.attrib['hours'])
            rate = float(node.attrib['rate'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid work order') from exc
        if hours < 0 or rate < 0:
            raise ValueError('negative value')
        cost = round(hours * rate, 2)
        records.append({'id': ident, 'status': item_status, 'priority': priority, 'hours': hours, 'rate': rate, 'cost': cost})
    if status is not None:
        records = [item for item in records if item['status'] == status]
    records.sort(key=lambda item: (-item['priority'], -item['cost'], item['id']))
    total_cost = round(sum((item['hours'] * item['rate'] for item in records)), 2)
    start = (page - 1) * page_size
    return {'items': records[start:start + page_size], 'total': len(records), 'total_cost': total_cost}

