import os
import re
import zipfile
from collections import Counter

def extract_contract_archive(archive_path: str, destination: str) -> list[str]:
    base = os.path.realpath(destination)
    os.makedirs(base, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename.replace('\\', '/')
            if not name or name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(base, *name.split('/')))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('archive member outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as out:
                while True:
                    block = source.read(65536)
                    if not block:
                        break
                    out.write(block)
            result.append(name)
    return sorted(result)

def _header(line):
    if not (line.startswith('[[') and line.endswith(']]')):
        return None
    value = line[2:-2]
    fields = []
    current = []
    escaped = False
    separator = False
    for char in value:
        if escaped:
            if char not in '\\|':
                return None
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|' and (not separator):
            fields.append(''.join(current))
            current = []
            separator = True
        else:
            current.append(char)
    if escaped or not separator:
        return None
    fields.append(''.join(current))
    return tuple(fields)

def search_contract_clauses(files: list[str], query: str) -> list[dict[str, object]]:
    terms = query.casefold().split()
    if not terms:
        raise ValueError('query must not be empty')
    found = []
    for filename in files:
        with open(filename, encoding='utf-8') as stream:
            lines = stream.read().splitlines()
        clauses = []
        current = None
        for line in lines:
            header = _header(line)
            if header is not None:
                current = [header[0], header[1], []]
                clauses.append(current)
            elif current is not None:
                current[2].append(line)
        for ident, title, body in clauses:
            text = (title + '\n' + '\n'.join(body)).casefold()
            if all((term in text for term in terms)):
                score = sum((text.count(term) for term in terms))
                found.append({'file': filename, 'id': ident, 'title': title, 'score': score})
    found.sort(key=lambda item: (-int(item['score']), str(item['file']), str(item['id'])))
    return found

