        INSERT INTO payments VALUES (1, 10, 250.0, '2025-01-10');
        INSERT INTO payments VALUES (2, 10, 100.0, '2025-02-10');
        INSERT INTO payments VALUES (3, 20, 500.0, '2024-12-20');
    """)
    return conn


def test_report_contains_aggregates_and_zero_payment_loans():
    conn = make_db()
    assert loan_report(conn) == [
