import ast

class _Evaluator(ast.NodeVisitor):

    def __init__(self, values):
        self.values = values

    def visit_Expression(self, node):
        return self.visit(node.body)

    def visit_Constant(self, node):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        raise ValueError('invalid expression')

    def visit_Name(self, node):
        if node.id not in self.values:
            raise NameError(node.id)
        return self.values[node.id]

    def visit_BinOp(self, node):
        a, b = (self.visit(node.left), self.visit(node.right))
        if isinstance(node.op, ast.Add):
            return a + b
        if isinstance(node.op, ast.Sub):
            return a - b
        if isinstance(node.op, ast.Mult):
            return a * b
        if isinstance(node.op, ast.Div):
            return a / b
        raise ValueError('invalid expression')

    def visit_UnaryOp(self, node):
        value = self.visit(node.operand)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError('invalid expression')

    def visit_BoolOp(self, node):
        value = self.visit(node.values[0])
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif isinstance(node.op, ast.Or):
                if value:
                    return value
            else:
                raise ValueError('invalid expression')
            value = self.visit(item)
        return value

    def visit_Compare(self, node):
        left = self.visit(node.left)
        for op, item in zip(node.ops, node.comparators):
            right = self.visit(item)
            if isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            elif isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            else:
                raise ValueError('invalid expression')
            if not ok:
                return False
            left = right
        return True

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name) or node.func.id not in ('min', 'max', 'round') or node.keywords:
            raise ValueError('invalid expression')
        args = [self.visit(x) for x in node.args]
        return {'min': min, 'max': max, 'round': round}[node.func.id](*args)

    def generic_visit(self, node):
        raise ValueError('invalid expression')

def _evaluate(text, values):
    tree = ast.parse(text, mode='eval')
    return _Evaluator(values).visit(tree)

def rank_contributions(records: list[dict], rule: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size <= 0):
        raise ValueError('invalid page')
    grouped = {}
    for record in records:
        grouped.setdefault(record['donor'], []).append(record['amount'])
    selected = []
    for donor, amounts in grouped.items():
        total = sum(amounts)
        count = len(amounts)
        average = total / count
        value = _evaluate(rule, {'total': total, 'count': count, 'average': average})
        if not isinstance(value, bool):
            raise ValueError('rule must be boolean')
        if value:
            selected.append((donor, total, count, round(average, 2)))
    selected.sort(key=lambda x: (-x[1], -x[2], x[0]))
    start = (page - 1) * page_size
    rows = [{'donor': d, 'total': t, 'count': c, 'average': a} for d, t, c, a in selected[start:start + page_size]]
    return {'total_amount': sum((x[1] for x in selected)), 'donor_count': len(selected), 'results': rows}

