import hashlib
import hmac
import os

def _store_pin(pin):
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def _check_pin(pin, stored):
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (AttributeError, ValueError, TypeError):
        return False

def build_inspection(inspector: str, pin: str, findings: list[dict[str, str]]) -> dict:
    if not isinstance(inspector, str) or not inspector:
        raise ValueError('invalid inspector')
    if not isinstance(pin, str) or not pin:
        raise ValueError('invalid pin')
    if not isinstance(findings, list):
        raise ValueError('invalid findings')
    weights = {'low': 1, 'medium': 3, 'high': 5}
    copied = []
    risk = 0
    for finding in findings:
        if not isinstance(finding, dict) or set(finding) != {'category', 'severity'}:
            raise ValueError('invalid finding')
        if not isinstance(finding['category'], str) or not finding['category']:
            raise ValueError('invalid category')
        if finding['severity'] not in weights:
            raise ValueError('invalid severity')
        copied.append(dict(finding))
        risk += weights[finding['severity']]
    return {'inspector': inspector, 'pin': _store_pin(pin), 'findings': copied, 'finding_count': len(copied), 'risk': risk}

def verify_inspection_pin(inspection: dict, pin: str) -> bool:
    if not isinstance(pin, str):
        return False
    try:
        return _check_pin(pin, inspection['pin'])
    except (KeyError, TypeError):
        return False

def report_inspections(inspections: list[dict], minimum_risk: int=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(minimum_risk, bool) or not isinstance(minimum_risk, int):
        raise ValueError('invalid minimum risk')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    selected = [x for x in inspections if x['risk'] >= minimum_risk]
    selected.sort(key=lambda x: (-x['risk'], x['inspector']))
    start = (page - 1) * page_size
    items = [dict(x, findings=[dict(f) for f in x['findings']]) for x in selected[start:start + page_size]]
    return {'total': len(selected), 'items': items}

