import ast
from datetime import date, timedelta

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid expression')

    def run(n):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name) and n.id in variables:
            return variables[n.id]
        if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (run(n.left), run(n.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(n.op)]()
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
            v = run(n.operand)
            return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
        if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
            v = run(n.values[0])
            for x in n.values[1:]:
                if isinstance(n.op, ast.And) and (not v):
                    return v
                if isinstance(n.op, ast.Or) and v:
                    return v
                v = run(x)
            return v
        if isinstance(n, ast.Compare):
            left = run(n.left)
            for op, item in zip(n.ops, n.comparators):
                right = run(item)
                good = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}.get(type(op))
                if good is None:
                    raise ValueError('unsupported expression')
                if not good:
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
            args = [run(x) for x in n.args]
            if n.func.id == 'round' and len(args) in (1, 2):
                return round(*args)
            if n.func.id in ('min', 'max') and args:
                return min(args) if n.func.id == 'min' else max(args)
        raise ValueError('unsupported expression')
    try:
        return run(tree)
    except NameError:
        raise ValueError('invalid expression')

