import csv
import io
from datetime import date

def parse_itinerary(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    result = []
    seen = set()
    for row in csv.reader(io.StringIO(text)):
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 7:
            raise ValueError('invalid record')
        ds, dep, arr, origin, dest, carrier, code = [x.strip() for x in row]
        try:
            date.fromisoformat(ds)
            dh, dm = map(int, dep.split(':'))
            ah, am = map(int, arr.split(':'))
            if len(dep) != 5 or len(arr) != 5 or dep[2] != ':' or (arr[2] != ':') or (not (0 <= dh < 24 and 0 <= dm < 60 and (0 <= ah < 24) and (0 <= am < 60))):
                raise ValueError
        except Exception as exc:
            raise ValueError('invalid date or time') from exc
        if not all((origin, dest, carrier, code)) or code in seen:
            raise ValueError('invalid or duplicate field')
        seen.add(code)
        start = dh * 60 + dm
        end = ah * 60 + am
        if end < start:
            end += 1440
        result.append({'date': ds, 'departure': dep, 'arrival': arr, 'origin': origin, 'destination': dest, 'carrier': carrier, 'code': code, 'duration_minutes': end - start})
    return sorted(result, key=lambda x: (x['date'], x['departure'], x['code']))

def get_itinerary_summary(requester: dict, itinerary: dict) -> dict:
    for key in ('id', 'tenant_id', 'roles'):
        if key not in requester:
            raise ValueError('invalid requester')
    for key in ('id', 'tenant_id', 'owner_id', 'segments'):
        if key not in itinerary:
            raise ValueError('invalid itinerary')
    roles = requester['roles']
    if requester['tenant_id'] != itinerary['tenant_id'] or (requester['id'] != itinerary['owner_id'] and 'travel_manager' not in roles):
        raise PermissionError('not permitted')
    segments = itinerary['segments']
    daily = {}
    carriers = set()
    dates = set()
    route = []
    total = 0
    for i, segment in enumerate(segments):
        needed = ('date', 'carrier', 'duration_minutes', 'origin', 'destination')
        if any((k not in segment for k in needed)):
            raise ValueError('invalid segment')
        dates.add(segment['date'])
        carriers.add(segment['carrier'])
        daily[segment['date']] = daily.get(segment['date'], 0) + segment['duration_minutes']
        total += segment['duration_minutes']
        if i == 0:
            route.append(segment['origin'])
        route.append(segment['destination'])
    return {'itinerary_id': itinerary['id'], 'total_segments': len(segments), 'total_minutes': total, 'dates': sorted(dates), 'carriers': sorted(carriers), 'route': route, 'daily_minutes': {k: daily[k] for k in sorted(daily)}}

