            if not isinstance(item['plot'], str) or not isinstance(item['crop'], str) or (not isinstance(item['observed_on'], str)):
                raise ValueError('invalid report')
            if isinstance(item['yield_kg'], bool) or not isinstance(item['yield_kg'], (int, float)) or item['yield_kg'] < 0:
                raise ValueError('invalid yield')
            if isinstance(item['area_ha'], bool) or not isinstance(item['area_ha'], (int, float)) or item['area_ha'] <= 0:
                raise ValueError('invalid area')
            if crop is None or item['crop'] == crop:
                records.append(item)
    groups = {}
