        for row in rows:
            writer.writerow({'email': row['email'], 'first_name': row['first_name'], 'segment': row['segment']})
    return str(destination)

import csv
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from io import StringIO

def _tags(value):
    if value == '':
        return []
    out, cur, escaped = ([], [], False)
    for ch in value:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            if not cur:
                raise ValueError('invalid tags')
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped or not cur:
        raise ValueError('invalid tags')
    out.append(''.join(cur))
    return out

def parse_catalog(text: str) -> list[dict]:
    lines = [x for x in text.splitlines() if x.strip()]
    header = ['sku', 'name', 'price', 'stock', 'tags', 'owner_id', 'tenant_id']
    if not lines:
        raise ValueError('empty catalog')
    try:
        rows = list(csv.reader(StringIO('\n'.join(lines))))
    except csv.Error as e:
        raise ValueError('bad csv') from e
    if not rows or rows[0] != header or len(rows) == 1:
        raise ValueError('bad header')
    result, seen = ([], set())
    for row in rows[1:]:
        if len(row) != 7 or any((x == '' for x in (row[0], row[1], row[5], row[6]))):
            raise ValueError('bad record')
        if row[0] in seen:
            raise ValueError('duplicate sku')
        try:
            price = Decimal(row[2])
            stock = int(row[3])
        except (InvalidOperation, ValueError):
            raise ValueError('bad number')
        if not price.is_finite() or price < 0 or price.as_tuple().exponent < -2 or (stock < 0):
            raise ValueError('bad number')
        result.append({'sku': row[0], 'name': row[1], 'price': price, 'stock': stock, 'tags': _tags(row[4]), 'owner_id': row[5], 'tenant_id': row[6]})
        seen.add(row[0])
    return result

def adjust_stock(catalog: list[dict], requester: dict, sku: str, delta: int) -> list[dict]:
    if isinstance(delta, bool) or not isinstance(delta, int) or delta == 0:
        raise ValueError('invalid delta')
    found = next((p for p in catalog if p.get('sku') == sku), None)
    if found is None:
        raise KeyError(sku)
    roles = requester.get('roles', [])
    allowed = requester.get('tenant_id') == found.get('tenant_id') and (requester.get('id') == found.get('owner_id') or 'catalog_admin' in roles)
    if not allowed:
        raise PermissionError('not permitted')
    if found['stock'] + delta < 0:
        raise ValueError('negative stock')
    result = []
    for item in catalog:
        copy = dict(item)
        copy['tags'] = list(item.get('tags', []))
        if item is found:
            copy['stock'] += delta
        result.append(copy)
    return result

def catalog_totals(catalog: list[dict]) -> dict:
    units = sum((item['stock'] for item in catalog))
    value = sum((item['price'] * item['stock'] for item in catalog), Decimal('0'))
    return {'item_count': len(catalog), 'total_units': units, 'inventory_value': value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)}

