import csv
import datetime
import os
import subprocess

def read_onboarding_manifest(path: str) -> list[dict]:
    required = ['employee_id', 'name', 'department', 'start_date', 'document']
    records = []
    seen = set()
    try:
        with open(path, newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            header = next(reader)
            if header != required:
                raise ValueError('invalid header')
            for row in reader:
                if len(row) != len(required):
                    raise ValueError('invalid row')
                values = [x.strip() for x in row]
                if any((not x for x in values)):
                    raise ValueError('blank field')
                try:
                    datetime.date.fromisoformat(values[3])
                except ValueError:
                    raise ValueError('invalid date')
                if values[0] in seen:
                    raise ValueError('duplicate employee')
                seen.add(values[0])
                records.append(dict(zip(required, values)))
    except StopIteration:
        raise ValueError('missing header')
    return records

def count_document_lines(path: str) -> int:
    result = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
    try:
        return int(result.stdout.split()[0])
    except (IndexError, ValueError):
        raise ValueError('malformed wc output')

def audit_onboarding(manifest_path: str, documents_dir: str) -> list[dict]:
    records = read_onboarding_manifest(manifest_path)
    groups = {}
    for record in records:
        lines = count_document_lines(os.path.join(documents_dir, record['document']))
        item = {'employee_id': record['employee_id'], 'name': record['name'], 'start_date': record['start_date'], 'document': record['document'], 'line_count': lines}
        groups.setdefault(record['department'], []).append(item)
    answer = []
    for department in sorted(groups):
        employees = sorted(groups[department], key=lambda x: (x['start_date'], x['employee_id']))
        answer.append({'department': department, 'employees': employees, 'total_lines': sum((x['line_count'] for x in employees))})
    return answer

