def select_events(events: list[dict], expression: str, page: int=1, page_size: int=10) -> list[str]:
    if isinstance(page, bool) or isinstance(page_size, bool) or page <= 0 or (page_size <= 0):
        raise ValueError('page and page_size must be positive integers')
    tree = ast.parse(expression, mode='eval')
    names = {'min': min, 'max': max, 'round': round}

    def evaluate(node, variables):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, variables)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            if node.id in names:
                return names[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = evaluate(node.operand, variables)
            if isinstance(node.op, ast.UAdd):
                return +value
            if isinstance(node.op, ast.USub):
                return -value
            return not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            left = evaluate(node.left, variables)
            right = evaluate(node.right, variables)
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = evaluate(node.values[0], variables)
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = evaluate(part, variables)
            return value
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, variables)
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, variables)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None or not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in names) and (not node.keywords):
            return names[node.func.id](*(evaluate(arg, variables) for arg in node.args))
        raise ValueError('unsupported expression')
    selected = []
    for event in events:
        variables = {key: event[key] for key in ('rating', 'attendance', 'capacity', 'fee', 'weekday')}
        if evaluate(tree, variables):
            selected.append(event)
    selected.sort(key=lambda event: (-event['rating'], event['start'], event['id']))
    first = (page - 1) * page_size
    return [event['id'] for event in selected[first:first + page_size]]

