def generate_inventory_report(base_dir: str, filenames: list[str], category: str | None=None, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100 or (category is not None and (not isinstance(category, str))):
        raise ValueError('invalid arguments')
    base = os.path.realpath(base_dir)
    totals = {}
    for filename in filenames:
        path = os.path.realpath(os.path.join(base, filename))
