import ast

def _eval(node, variables):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in variables:
            raise NameError(node.id)
        return variables[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _eval(node.operand, variables)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
        left, right = (_eval(node.left, variables), _eval(node.right, variables))
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        return left / right
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        value = _eval(node.values[0], variables)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And):
                if not value:
                    return value
            elif value:
                return value
            value = _eval(item, variables)
        return value
    if isinstance(node, ast.Compare):
        left = _eval(node.left, variables)
        for op, item in zip(node.ops, node.comparators):
            right = _eval(item, variables)
            if isinstance(op, ast.Lt):
                ok = left < right
            elif isinstance(op, ast.LtE):
                ok = left <= right
            elif isinstance(op, ast.Gt):
                ok = left > right
            elif isinstance(op, ast.GtE):
                ok = left >= right
            elif isinstance(op, ast.Eq):
                ok = left == right
            elif isinstance(op, ast.NotEq):
                ok = left != right
            else:
                raise ValueError('unsupported expression')
            if not ok:
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_eval(x, variables) for x in node.args]
        if node.func.id == 'min' and args:
            return min(*args)
        if node.func.id == 'max' and args:
            return max(*args)
        if node.func.id == 'round' and 1 <= len(args) <= 2:
            return round(*args)
    raise ValueError('unsupported expression')

