from datetime import date, datetime

def build_milk_report(requester: dict, tanks: list[dict], start: str, end: str, page: int, page_size: int) -> list[dict]:
    try:
        start_date = date.fromisoformat(start)
        end_date = date.fromisoformat(end)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if end_date < start_date:
        raise ValueError('invalid range')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page < 1) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    allowed = set(requester.get('roles', []))
    rows = []
    for tank in tanks:
        same_tenant = tank.get('tenant_id') == requester.get('tenant_id')
        owned = tank.get('owner_id') == requester.get('id')
        if not same_tenant or not (owned or 'manager' in allowed):
            raise PermissionError('not permitted')
        selected = []
        for reading in tank.get('readings', []):
            timestamp = datetime.fromisoformat(reading['timestamp'].replace('Z', '+00:00'))
            if start_date <= timestamp.date() <= end_date:
                selected.append(reading)
        if selected:
            total = sum((item['liters'] for item in selected))
            average = sum((item['fat_pct'] for item in selected)) / len(selected)
            rows.append({'tank_id': tank['id'], 'liters': round(total, 2), 'average_fat_pct': round(average, 2), 'reading_count': len(selected)})
    rows.sort(key=lambda row: (-row['liters'], row['tank_id']))
    offset = (page - 1) * page_size
    return rows[offset:offset + page_size]

