def summarize_rescue_log(path: str, query: str, window_seconds: int=300) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds < 0:
        raise ValueError('invalid window')
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.readlines()
    except (OSError, UnicodeError):
        raise ValueError('cannot read log')
    groups = {}
    for number, line in enumerate(lines):
        raw = line.rstrip('\n\r')
        if query not in raw:
            continue
        parts = raw.split('|', 3)
        if len(parts) != 4:
            continue
        try:
            stamp = int(parts[0])
        except ValueError:
            continue
        team, event = (parts[1], parts[2])
        if stamp < 0 or not team or event not in ('LOCATE', 'EVAC', 'UPDATE'):
            continue
        g = groups.setdefault(team, {'team': team, 'locates': 0, 'evacuations': 0, 'updates': 0, 'first_seen': stamp, 'last_seen': stamp, 'latest_event': event, '_line': number})
        g['locates'] += event == 'LOCATE'
        g['evacuations'] += event == 'EVAC'
        g['updates'] += event == 'UPDATE'
        if stamp < g['first_seen']:
            g['first_seen'] = stamp
        if stamp > g['last_seen'] or (stamp == g['last_seen'] and number >= g['_line']):
            g['last_seen'], g['latest_event'], g['_line'] = (stamp, event, number)
    result = []
    for g in groups.values():
        g.pop('_line')
        g['active_window'] = g['last_seen'] - g['first_seen'] <= window_seconds
        result.append(g)
    return sorted(result, key=lambda x: (-x['evacuations'], -x['locates'], x['last_seen'], x['team']))

def rank_rescue_teams(summaries: list[dict], limit: int | None=None) -> list[dict]:
    keys = ('team', 'evacuations', 'locates', 'updates', 'last_seen')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0 or (limit > len(summaries))):
        raise ValueError('invalid limit')
    for row in summaries:
        if any((k not in row for k in keys)):
            raise ValueError('incomplete summary')
    result = sorted((dict(x) for x in summaries), key=lambda x: (-x['evacuations'], -x['locates'], -x['updates'], x['last_seen'], x['team']))
    return result if limit is None else result[:limit]

