        g['active_window'] = g['last_seen'] - g['first_seen'] <= window_seconds
    return sorted(groups.values(), key=lambda x: (-x['evacuations'], -x['locates'], x['last_seen'], x['team']))

def rank_rescue_teams(summaries: list[dict], limit: int | None=None) -> list[dict]:
    keys = ('team', 'evacuations', 'locates', 'updates', 'last_seen')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0 or (limit > len(summaries))):
        raise ValueError('invalid limit')
    for row in summaries:
        if any((k not in row for k in keys)):
            raise ValueError('incomplete summary')
    result = sorted((dict(x) for x in summaries), key=lambda x: (-x['evacuations'], -x['locates'], -x['updates'], x['last_seen'], x['team']))
