from solution import verify_training_webhook

import hashlib
import hmac
import json

import pytest


def make_payload(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def make_signature(payload, secret):
    digest = hmac.new(secret.encode("utf-8"), payload, hashlib.sha256).hexdigest()
    return "sha256=" + digest


def test_accepts_valid_webhook_and_preserves_fields():
    value = {
        "event": "training_job",
        "job_id": "job-17",
        "status": "running",
        "epoch": 4,
        "metadata": {"owner": "ml-team"},
    }
    payload = make_payload(value)
    assert verify_training_webhook(payload, make_signature(payload, "secret-key"), "secret-key") == value


def test_accepts_all_supported_statuses():
    for status in ("queued", "running", "completed", "failed"):
        value = {"event": "training_job", "job_id": "x", "status": status}
        payload = make_payload(value)
        assert verify_training_webhook(payload, make_signature(payload, "s"), "s")["status"] == status


def test_rejects_wrong_signature():
    value = {"event": "training_job", "job_id": "job-1", "status": "queued"}
    payload = make_payload(value)
    signature = make_signature(payload, "right")
    with pytest.raises(ValueError, match="^invalid signature$"):
        verify_training_webhook(payload, signature, "wrong")


def test_rejects_malformed_signature_headers():
    payload = make_payload({"event": "training_job", "job_id": "job-1", "status": "queued"})
    for signature in ("", "sha256", "sha1=" + "a" * 64, "sha256=" + "A" * 64, "sha256=" + "0" * 63):
        with pytest.raises(ValueError, match="^invalid signature$"):
            verify_training_webhook(payload, signature, "secret")


def test_rejects_invalid_json_after_valid_signature():
    payload = b"not-json"
    with pytest.raises(ValueError, match="^invalid payload$"):
