import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    salt = os.urandom(16)
    iterations = 100000
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        iteration_text, salt_text, digest_text = stored.split('$')
        iterations = int(iteration_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    if iterations < 100000 or not salt or (not expected):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, iterations)
    return hmac.compare_digest(actual, expected)

def create_attestation(employee_id: str, policy_id: str, pin: str) -> dict:
    if not isinstance(employee_id, str) or not isinstance(policy_id, str) or (not isinstance(pin, str)):
        raise TypeError('attestation values must be strings')
    if not employee_id or not policy_id or (not pin):
        raise ValueError('attestation values must not be empty')
    return {'employee_id': employee_id, 'policy_id': policy_id, 'credential': hash_secret(pin)}

