import datetime
import os
import tempfile

def export_daily_schedule(appointments: list[dict], destination: str, day: str) -> dict:
    try:
        datetime.datetime.strptime(day, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError('invalid day')
    fields = ['id', 'start', 'veterinarian', 'client', 'pet', 'duration_minutes', 'status']
    valid_statuses = {'scheduled', 'confirmed', 'cancelled'}
    selected = []
    for item in appointments:
        try:
            if any((not isinstance(item[k], str) or not item[k] for k in fields if k != 'duration_minutes')):
                raise ValueError('invalid appointment')
            if type(item['duration_minutes']) is not int or item['duration_minutes'] <= 0:
                raise ValueError('invalid appointment')
            if item['status'] not in valid_statuses:
                raise ValueError('invalid appointment')
            start = datetime.datetime.strptime(item['start'], '%Y-%m-%d %H:%M')
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid appointment')
        if start.date().isoformat() == day and item['status'] != 'cancelled':
            selected.append(item)
    selected.sort(key=lambda x: (x['start'], x['pet'], x['id']))
    summary = {}
    for item in selected:
        summary[item['veterinarian']] = summary.get(item['veterinarian'], 0) + item['duration_minutes']
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='schedule-', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.writer(f, lineterminator='\n')
            writer.writerow(fields)
            for item in selected:
                writer.writerow([item[k] for k in fields])
        os.replace(temporary, destination)
    except Exception:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return {'date': day, 'appointments': len(selected), 'minutes_by_veterinarian': {k: summary[k] for k in sorted(summary)}}

