import math
import re
from lxml import etree

def parse_bid(xml: str) -> dict[str, object]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode('utf-8'), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'auction_bid':
        raise ValueError('invalid root')
    values = {}
    for name in ('bidder', 'item', 'amount', 'currency'):
        node = root.find(name)
        if node is None or node.text is None or (not node.text.strip()):
            raise ValueError('missing field')
        values[name] = node.text.strip()
    try:
        amount = float(values['amount'])
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid amount') from exc
    if not math.isfinite(amount) or amount <= 0:
        raise ValueError('invalid amount')
    if re.fullmatch('[A-Z]{3}', values['currency']) is None:
        raise ValueError('invalid currency')
    message = root.find('message')
    return {'bidder': values['bidder'], 'item': values['item'], 'amount': amount, 'currency': values['currency'], 'message': '' if message is None or message.text is None else message.text.strip()}

