import secrets
from datetime import datetime
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_STATUSES = {'loaded': 0, 'in_transit': 1, 'delayed': 2, 'delivered': 3}

def generate_tracking_token(length: int=12) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or (not 8 <= length <= 32):
        raise ValueError('invalid length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def issue_tracking_code(shipment_id: str) -> str:
    if not isinstance(shipment_id, str) or not re.fullmatch('[A-Za-z0-9-]+', shipment_id):
        raise ValueError('invalid shipment')
    return shipment_id + '-' + generate_tracking_token()

def track_shipments(events: list[dict]) -> list[dict]:
    groups = {}
    seen = set()
    for event in events:
        if not isinstance(event, dict) or set(event) != {'shipment', 'at', 'status', 'weight', 'seq'}:
            raise ValueError('invalid event')
        shipment, at, status, weight, seq = (event[k] for k in ('shipment', 'at', 'status', 'weight', 'seq'))
        if not isinstance(shipment, str) or not shipment:
            raise ValueError('invalid shipment')
        if not isinstance(at, str) or not re.fullmatch('\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\dZ', at):
