        if status not in _STATUSES or not isinstance(weight, int) or isinstance(weight, bool) or (weight < 0) or (not isinstance(seq, int)) or isinstance(seq, bool) or (seq < 0):
            raise ValueError('invalid event')
        key = (shipment, at, seq)
        if key in seen:
            raise ValueError('duplicate event')
        seen.add(key)
        groups.setdefault(shipment, []).append(event)
    result = []
    for shipment, items in groups.items():
        items.sort(key=lambda x: (x['at'], x['seq']))
        last = items[-1]
        result.append({'shipment': shipment, 'status': last['status'], 'last_at': last['at'], 'total_weight': sum((x['weight'] for x in items)), 'delay_count': sum((x['status'] == 'delayed' for x in items))})
    result.sort(key=lambda x: (_STATUSES[x['status']], -x['total_weight'], x['shipment']))
    return result

