def export_license_report(records: list[dict], destination: str, region: str | None=None, page: int=1, page_size: int=50) -> int:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    groups = {}
    for record in records:
        current_region = record['region']
        species = record['species']
        if not isinstance(current_region, str) or not isinstance(species, str):
            raise ValueError('invalid grouping field')
        if region is not None and current_region != region:
            continue
        raw_fee = record['fee']
        try:
