from solution import verify_publication_webhook
import hashlib
import hmac
import json
import pytest


def make_payload(value):
    return json.dumps(value, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def make_signature(payload, key=b"journal-key"):
    return hmac.new(key, payload, hashlib.sha256).hexdigest()


def test_valid_publication_returns_selected_fields():
    payload = make_payload({
        "title": "A Study of Alpine Moss",
        "doi": "10.1234/example.1",
        "authors": ["Ada Lovelace", "Grace Hopper"],
        "year": 2024,
        "journal": "Field Biology Letters"
    })
    result = verify_publication_webhook(payload, make_signature(payload), b"journal-key")
    assert result == {
        "title": "A Study of Alpine Moss",
        "doi": "10.1234/example.1",
        "authors": ["Ada Lovelace", "Grace Hopper"],
        "year": 2024
    }
    assert list(result) == ["title", "doi", "authors", "year"]


def test_signature_must_match():
    payload = make_payload({"title": "Paper", "doi": "10.1/x", "authors": ["A"], "year": 2020})
    with pytest.raises(ValueError):
        verify_publication_webhook(payload, "0" * 64, b"journal-key")


def test_signature_format_is_strict():
    payload = make_payload({"title": "Paper", "doi": "10.1/x", "authors": ["A"], "year": 2020})
    valid = make_signature(payload)
    for signature in (valid.upper(), valid[:-1], valid + "0", "not-a-signature"):
        with pytest.raises(ValueError):
            verify_publication_webhook(payload, signature, b"journal-key")


def test_malformed_payloads_are_rejected():
    signature = "0" * 64
    for payload in (b"not json", b"[]", b"null", b"{\"title\": 1}"):
        with pytest.raises(ValueError):
            verify_publication_webhook(payload, signature, b"journal-key")


def test_required_field_validation():
    base = {"title": "Paper", "doi": "10.1/x", "authors": ["A"], "year": 2020}
    cases = [
        {**base, "title": ""},
        {**base, "doi": ""},
        {**base, "authors": []},
        {**base, "authors": ["A", 3]},
        {**base, "year": 999},
        {**base, "year": True},
    ]
    for value in cases:
        payload = make_payload(value)
        with pytest.raises(ValueError):
            verify_publication_webhook(payload, make_signature(payload), b"journal-key")


def test_unicode_payload_and_key_work():
    payload = make_payload({
        "title": "Étude sur les lichens",
        "doi": "10.5555/é",
        "authors": ["Zoë Martín"],
        "year": 1000
    })
    assert verify_publication_webhook(payload, make_signature(payload, "clé".encode()), "clé".encode())["title"] == "Étude sur les lichens"


def test_argument_types_are_checked():
    payload = make_payload({"title": "Paper", "doi": "10.1/x", "authors": ["A"], "year": 2020})
    signature = make_signature(payload)
    with pytest.raises(TypeError):
        verify_publication_webhook("text", signature, b"journal-key")
    with pytest.raises(TypeError):
        verify_publication_webhook(payload, b"bytes", b"journal-key")
    with pytest.raises(TypeError):
        verify_publication_webhook(payload, signature, "journal-key")

