def renewal_report(path: str, as_of: str, horizon_days: int, jurisdiction: str | None=None) -> dict:
    try:
        start = date.fromisoformat(as_of)
    except Exception as e:
        raise ValueError('invalid date') from e
    if isinstance(horizon_days, bool) or not isinstance(horizon_days, int) or horizon_days < 0:
        raise ValueError('invalid horizon')
    end = start + timedelta(days=horizon_days)
    result = subprocess.run(['sort', '-t', '|', '-k3,3', '-k1,1', path], capture_output=True, text=True, check=True)
    items = []
    for raw in result.stdout.splitlines():
        if not raw:
            continue
        fields = raw.split('|')
        if len(fields) != 5 or any((x == '' for x in fields)):
            raise ValueError('malformed record')
        asset, country, due_text, fee_text, status = fields
        if status not in {'ACTIVE', 'PAID', 'ABANDONED'}:
            raise ValueError('invalid status')
        try:
            due = date.fromisoformat(due_text)
            fee = int(fee_text)
        except Exception as e:
            raise ValueError('invalid record') from e
        if fee < 0:
            raise ValueError('invalid fee')
        if status == 'ACTIVE' and start <= due <= end and (jurisdiction is None or country == jurisdiction):
            items.append({'asset': asset, 'jurisdiction': country, 'due_date': due_text, 'fee_cents': fee})
    items.sort(key=lambda x: (x['due_date'], x['asset'], x['jurisdiction']))
    groups = {}
    for item in items:
        g = groups.setdefault(item['jurisdiction'], {'count': 0, 'fee_cents': 0})
        g['count'] += 1
