def make_archive(files):
    temp = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    temp.close()
    with zipfile.ZipFile(temp.name, "w") as zf:
        for name, content in files.items():
            zf.writestr(name, content)
    return temp.name


