            raise ValueError('invalid row')
        vals = {k: row[k].strip() for k in _FIELDS}
        if any((not vals[k] for k in _FIELDS[:4])) or not vals['joined']:
            raise ValueError('empty field')
        if vals['status'] not in ('active', 'inactive') or vals['member_id'] in seen:
            raise ValueError('invalid member')
        try:
            datetime.date.fromisoformat(vals['joined'])
        except ValueError:
            raise ValueError('invalid date')
        dues = {}
        if vals['dues']:
            for item in vals['dues'].split(';'):
                parts = item.split('=')
                if len(parts) != 2 or len(parts[0]) != 4 or (not parts[0].isdigit()) or (not parts[1].isdigit()):
                    raise ValueError('invalid dues')
                year, amount = (int(parts[0]), int(parts[1]))
                if year in dues:
                    raise ValueError('duplicate dues')
                dues[year] = amount
