    groups = {}
    for row in parse_roster(text):
        groups.setdefault(row['household'], []).append(row)
    result = []
    for household, members in groups.items():
        active = [m for m in members if m['status'] == 'active']
        result.append({'household': household, 'active_members': len(active), 'total_due': sum((m['dues'].get(year, 0) for m in active)), 'latest_joined': max((m['joined'] for m in members))})
    return sorted(result, key=lambda x: (-x['active_members'], x['household'].casefold()))

