def create_water_quality_report(readings: list[dict], config: dict[str, str]) -> dict:
    if not isinstance(readings, list):
        raise TypeError('readings must be a list')
    if not isinstance(config, dict):
        raise TypeError('config must be a dictionary')
    key = config.get('report_key')
    if not isinstance(key, str) or not key:
        raise ValueError('report_key is required')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise TypeError('each reading must be a dictionary')
        if not all((name in reading for name in ('tank', 'ph', 'ammonia'))):
            raise ValueError('reading is missing a required field')
        tank = reading['tank']
        if not isinstance(tank, str):
            raise TypeError('tank must be a string')
        if not tank:
            raise ValueError('tank must not be empty')
        ph = reading['ph']
        ammonia = reading['ammonia']
        if isinstance(ph, bool) or not isinstance(ph, (int, float)) or isinstance(ammonia, bool) or (not isinstance(ammonia, (int, float))):
            raise ValueError('measurements must be numeric')
        if not math.isfinite(ph) or not math.isfinite(ammonia):
            raise ValueError('measurements must be finite')
        groups.setdefault(tank, []).append((ph, ammonia))
    tanks = []
    for tank in sorted(groups):
        values = groups[tank]
        average_ph = round(sum((v[0] for v in values)) / len(values), 2)
        average_ammonia = round(sum((v[1] for v in values)) / len(values), 2)
        good = all((6.5 <= ph <= 8.5 and ammonia <= 0.25 for ph, ammonia in values))
        tanks.append({'tank': tank, 'count': len(values), 'average_ph': average_ph, 'average_ammonia': average_ammonia, 'status': 'good' if good else 'check'})
    payload = {'tanks': tanks}
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), data, hashlib.sha256).hexdigest()
    return {'payload': payload, 'signature': signature}

