def rank_district_loads(path: str, top_n: int, min_load: float) -> list[tuple[str, float]]:
    if isinstance(top_n, bool) or not isinstance(top_n, int) or top_n <= 0:
        raise ValueError('top_n must be a positive integer')
    if not isinstance(min_load, (int, float)) or not math.isfinite(min_load) or min_load < 0:
        raise ValueError('min_load must be finite and non-negative')
    with open(path, 'r', encoding='utf-8') as source:
