            fields = line.split(',')
            if len(fields) != 2 or not fields[0].strip():
                raise ValueError(f'invalid record on line {number}')
            try:
                value = float(fields[1].strip())
            except ValueError as exc:
                raise ValueError(f'invalid record on line {number}') from exc
            if not math.isfinite(value) or value < 0:
                raise ValueError(f'invalid record on line {number}')
    completed = subprocess.run(['sort', '-t,', '-k2,2nr', '-k1,1', path], check=True, capture_output=True, text=True)
    result = []
