import csv
import datetime
import io
import json
import math
import re

def parse_field_note(note: str) -> dict:
    if not isinstance(note, str) or not note.strip():
        raise ValueError('invalid note')
    vals = {}
    for line in note.splitlines():
        if not line.strip() or ':' not in line:
            raise ValueError('invalid line')
        key, value = line.split(':', 1)
        key, value = (key.strip(), value.strip())
        if key not in {'context', 'layer', 'date', 'finds', 'measurements'} or key in vals:
            raise ValueError('invalid key')
        vals[key] = value
    if set(vals) != {'context', 'layer', 'date', 'finds', 'measurements'}:
        raise ValueError('missing key')
    if not vals['context']:
        raise ValueError('context')
    try:
        layer = int(vals['layer'])
        datetime.date.fromisoformat(vals['date'])
    except Exception as e:
        raise ValueError('scalar') from e
    if layer < 0 or re.fullmatch('\\d{4}-\\d{2}-\\d{2}', vals['date']) is None:
        raise ValueError('scalar')

    def pairs(text, integer):
        out = {}
        if not text:
            return out
        for item in text.split(','):
            if '=' not in item:
                raise ValueError('pair')
            k, v = (x.strip() for x in item.split('=', 1))
            if not k or k in out:
                raise ValueError('pair')
            try:
                n = int(v) if integer else float(v)
            except Exception as e:
                raise ValueError('number') from e
            if integer and n < 0 or (not integer and (not math.isfinite(n))):
                raise ValueError('number')
            out[k] = n
        return out
    return {'context': vals['context'], 'layer': layer, 'date': vals['date'], 'finds': pairs(vals['finds'], True), 'measurements': pairs(vals['measurements'], False)}

def summarize_contexts(records: list[dict]) -> list[dict]:
    out = []
    for record in records:
        item = parse_field_note(record['note'])
        item['record_id'] = record['id']
        out.append(item)

    def key(x):
        m = re.search('(\\d+)$', x['context'])
        return (x['context'][:m.start()] if m else x['context'], int(m.group(1)) if m else -1, x['context'], x['record_id'])
    return sorted(out, key=key)

def export_project(requester: dict, records: list[dict], project_id: str, format: str='json') -> str:
    if format not in {'json', 'csv'}:
        raise ValueError('format')
    chosen = [r for r in records if r['project'] == project_id and r['tenant'] == requester['tenant']]
    if not all((r['owner'] == requester['id'] or 'director' in requester.get('roles', []) or 'curator' in requester.get('roles', []) for r in chosen)):
        raise PermissionError('not permitted')
    data = summarize_contexts(chosen)
    if format == 'json':
        return json.dumps(data, sort_keys=True, separators=(',', ':'))
    stream = io.StringIO()
    writer = csv.writer(stream, lineterminator='\n')
    writer.writerow(['context', 'layer', 'date', 'finds', 'measurements', 'record_id'])
    for x in data:
        writer.writerow([x['context'], x['layer'], x['date'], json.dumps(x['finds'], sort_keys=True, separators=(',', ':')), json.dumps(x['measurements'], sort_keys=True, separators=(',', ':')), x['record_id']])
    return stream.getvalue()

