def build_permit_summary(log_path: str, pollutant: str, min_samples: int=1) -> list[dict]:
    if isinstance(min_samples, bool) or not isinstance(min_samples, int) or min_samples <= 0:
        raise ValueError('min_samples must be positive')
    completed = subprocess.run(['grep', '-F', '--', pollutant, log_path], capture_output=True, text=True)
    if completed.returncode == 2:
        raise OSError(completed.stderr.strip() or 'unable to read log')
