        if not facility or not name:
            continue
        try:
            date = datetime.date.fromisoformat(date_text)
            reading = float(reading_text)
            limit = float(limit_text)
        except (ValueError, TypeError):
            continue
        if not math.isfinite(reading) or not math.isfinite(limit) or name != pollutant:
            continue
        groups.setdefault(facility, []).append((date, reading, limit))
    result = []
    for facility, records in groups.items():
        if len(records) < min_samples:
            continue
        result.append({'facility': facility, 'samples': len(records), 'violations': sum((reading > limit for _, reading, limit in records)), 'average': round(sum((reading for _, reading, _ in records)) / len(records), 2), 'peak': max((reading for _, reading, _ in records)), 'latest': max((date for date, _, _ in records)).isoformat()})
    result.sort(key=lambda x: (-x['violations'], -x['average'], x['facility']))
