from collections import defaultdict
from pathlib import Path

def create_enrollment_report(records: list[dict], base_dir: str, relative_name: str, page: int=1, page_size: int=50) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid name')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('invalid page size')
    groups = defaultdict(int)
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('school'), str) or not record['school']:
            raise ValueError('invalid school')
        if isinstance(record.get('grade'), bool) or not isinstance(record.get('grade'), int) or (not 0 <= record['grade'] <= 12):
            raise ValueError('invalid grade')
        if record.get('status') not in {'enrolled', 'withdrawn', 'waitlisted'}:
            raise ValueError('invalid status')
        if record['status'] == 'enrolled':
            groups[record['school'], record['grade']] += 1
    total = sum(groups.values())
    rows = []
    for (school, grade), count in sorted(groups.items()):
        rows.append([school, grade, count, round(count * 100 / total, 2)])
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    if target != base and base not in target.parents:
        raise ValueError('invalid output path')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['school', 'grade', 'enrolled', 'share_percent'])
        writer.writerows(selected)
    return os.path.abspath(str(target))

