def parse_contract(xml_text: str, page: int=1, page_size: int=10, category: str | None=None) -> dict:
    if not isinstance(xml_text, str):
        raise ValueError('invalid XML')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    if category is not None and (not isinstance(category, str)):
        raise ValueError('invalid category')
    parser = etree.XMLParser(resolve_entities=False, load_dtd=False, no_network=True)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'contract':
        raise ValueError('invalid root')
    required = ('id', 'title', 'effective_date')
    if any((name not in root.attrib for name in required)):
        raise ValueError('missing contract attribute')
    clauses = []
    for node in root:
        if node.tag != 'clause':
            continue
        names = ('number', 'category', 'status', 'amount_cents')
        if any((name not in node.attrib for name in names)):
            raise ValueError('missing clause attribute')
        try:
            number = int(node.attrib['number'])
            amount = int(node.attrib['amount_cents'])
        except Exception as exc:
            raise ValueError('invalid number') from exc
        if category is not None and node.attrib['category'] != category:
            continue
        text = ' '.join(''.join(node.itertext()).split())
        clauses.append({'number': number, 'category': node.attrib['category'], 'status': node.attrib['status'], 'amount_cents': amount, 'text': text})
    clauses.sort(key=lambda item: item['number'])
    start = (page - 1) * page_size
    return {'contract_id': root.attrib['id'], 'title': root.attrib['title'], 'effective_date': root.attrib['effective_date'], 'total_count': len(clauses), 'page': page, 'page_size': page_size, 'total_amount_cents': sum((item['amount_cents'] for item in clauses)), 'clauses': clauses[start:start + page_size]}

