from datetime import date
from lxml import etree

def _read(xml):
    if not isinstance(xml, str):
        raise ValueError('xml must be a string')
    try:
        root = etree.fromstring(xml.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'visits':
        raise ValueError('invalid root')
    return root

def _day(value):
    try:
        if len(value) != 10 or value[4] != '-' or value[7] != '-':
            raise ValueError
        date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def _clock(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid time')
    try:
        hour, minute = (int(value[:2]), int(value[3:]))
    except Exception as exc:
        raise ValueError('invalid time') from exc
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        raise ValueError('invalid time')
    return hour * 60 + minute

def parse_visitors(xml: str) -> list[dict]:
    root = _read(xml)
    records, seen = ([], set())
    required_visitor = ('id', 'name', 'nationality', 'clearance')
    required_visit = ('date', 'host', 'purpose', 'arrival', 'departure')
    for visitor in root:
        if visitor.tag != 'visitor' or any((not visitor.get(k) for k in required_visitor)):
            raise ValueError('invalid visitor')
        ident = visitor.get('id')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        for visit in visitor:
            if visit.tag != 'visit' or any((not visit.get(k) for k in required_visit)):
                raise ValueError('invalid visit')
            vals = {k: visit.get(k) for k in required_visit}
            _day(vals['date'])
            start, end = (_clock(vals['arrival']), _clock(vals['departure']))
            if end <= start:
                raise ValueError('invalid range')
            records.append({'id': ident, 'name': visitor.get('name'), 'nationality': visitor.get('nationality'), 'clearance': visitor.get('clearance'), **vals, 'duration_minutes': end - start})
    records.sort(key=lambda r: (r['date'], r['arrival'], r['id']))
    return records

def summarize_visits(xml: str, date: str) -> dict:
    _day(date)
    records = [r for r in parse_visitors(xml) if r['date'] == date]
    nationalities = {}
    hosts = {}
    for record in records:
        nationalities[record['nationality']] = nationalities.get(record['nationality'], 0) + 1
        hosts[record['host']] = hosts.get(record['host'], 0) + 1
    return {'date': date, 'count': len(records), 'total_minutes': sum((r['duration_minutes'] for r in records)), 'by_nationality': {k: nationalities[k] for k in sorted(nationalities)}, 'hosts': [{'host': k, 'count': v} for k, v in sorted(hosts.items(), key=lambda x: (-x[1], x[0]))]}

