import ast
import operator

def _evaluate(text, variables):
    tree = ast.parse(text, mode='eval').body
    allowed = {'min': min, 'max': max, 'round': round}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise ValueError('unknown variable')
            return variables[node.id]
        if isinstance(node, ast.BinOp):
            a, b = (visit(node.left), visit(node.right))
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise ValueError('unsupported expression')
            return ops[type(node.op)](a, b)
        if isinstance(node, ast.UnaryOp):
            a = visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -a
            if isinstance(node.op, ast.UAdd):
                return +a
            if isinstance(node.op, ast.Not):
                return not a
            raise ValueError('unsupported expression')
        if isinstance(node, ast.BoolOp):
            value = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif isinstance(node.op, ast.Or):
                    if value:
                        return value
                else:
                    raise ValueError('unsupported expression')
                value = visit(item)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                fn = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}.get(type(op))
                if fn is None or not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in allowed) and (not node.keywords):
            return allowed[node.func.id](*(visit(x) for x in node.args))
        raise ValueError('unsupported expression')
    return visit(tree)

def select_change_orders(orders: list[dict], rule: str, rank_expression: str, offset: int=0, limit: int | None=None) -> dict:
    if offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid pagination')
    matches = []
    for order in orders:
        env = {'amount': order['amount'], 'days': order['days'], 'status': order['status']}
        if _evaluate(rule, env):
            matches.append((order, _evaluate(rank_expression, env)))
    matches.sort(key=lambda pair: pair[1], reverse=True)
    page = matches[offset:] if limit is None else matches[offset:offset + limit]
    selected = [x[0] for x in page]
    return {'orders': selected, 'count': len(matches), 'total_amount': round(sum((x[0]['amount'] for x in matches)), 2), 'ids': [x['id'] for x in selected]}

