import datetime
import hashlib
import hmac
import json
import math

def summarize_signed_adoptions(payload: str, signature: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        records = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    seen = set()
    groups = {}
    for item in records:
        if not isinstance(item, dict):
            raise ValueError('invalid record')
        required = {'animal_id', 'species', 'age_months', 'fee', 'status', 'adopted_on'}
        if set(item) != required:
            raise ValueError('invalid record')
        animal_id = item['animal_id']
        species = item['species']
        age = item['age_months']
        fee = item['fee']
        status = item['status']
        date = item['adopted_on']
        if not isinstance(animal_id, str) or not animal_id or (not isinstance(species, str)) or (not species):
            raise ValueError('invalid record')
        if animal_id in seen:
            raise ValueError('duplicate animal')
        seen.add(animal_id)
        if not isinstance(age, int) or isinstance(age, bool) or age < 0:
            raise ValueError('invalid record')
        if not isinstance(fee, (int, float)) or isinstance(fee, bool) or (not math.isfinite(fee)) or (fee < 0):
            raise ValueError('invalid record')
        if status not in {'completed', 'pending', 'cancelled'}:
            raise ValueError('invalid record')
        if not isinstance(date, str):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(date)
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if status == 'completed':
            group = groups.setdefault(species, [0, 0.0, 0])
            group[0] += 1
            group[1] += fee
            group[2] += age
    output = []
    for species, (count, total, ages) in groups.items():
        output.append({'species': species, 'count': count, 'total_fee': round(total, 2), 'average_age_months': round(ages / count, 2)})
    output.sort(key=lambda item: (-item['count'], item['species']))
    total_records = sum((item['count'] for item in output))
    total_pages = (len(output) + page_size - 1) // page_size if output else 0
    start = (page - 1) * page_size
    return {'total_records': total_records, 'total_pages': total_pages, 'page': page, 'page_size': page_size, 'groups': output[start:start + page_size]}

