import hashlib
import hmac
import json

def verify_renewal_webhook(payload: str, signature: str, secret: bytes) -> bool:
    try:
        expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, signature)
    except (AttributeError, TypeError, UnicodeError):
        return False

def build_renewal_report(payload: str, signature: str, secret: bytes, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not verify_renewal_webhook(payload, signature, secret):
        raise PermissionError('invalid signature')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(document, dict) or not isinstance(document.get('renewals'), list):
        raise ValueError('invalid renewals')
    groups = {}
    total_approved = 0
    total_cents = 0
    for record in document['renewals']:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        license_id = record.get('license_id')
        jurisdiction = record.get('jurisdiction')
        status = record.get('status')
        amount = record.get('amount_cents')
        if not isinstance(license_id, str) or not license_id or (not isinstance(jurisdiction, str)) or (not jurisdiction) or (status not in {'approved', 'pending', 'rejected'}) or isinstance(amount, bool) or (not isinstance(amount, int)) or (amount < 0):
            raise ValueError('invalid record')
        if status == 'approved':
            if jurisdiction not in groups:
                groups[jurisdiction] = {'jurisdiction': jurisdiction, 'count': 0, 'total_cents': 0}
            groups[jurisdiction]['count'] += 1
            groups[jurisdiction]['total_cents'] += amount
            total_approved += 1
            total_cents += amount
    values = list(groups.values())
    start = (page - 1) * page_size
    return {'total_approved': total_approved, 'total_cents': total_cents, 'jurisdictions': values[start:start + page_size], 'page': page, 'page_size': page_size}

