import hashlib
import hmac
import os

def hash_access_code(access_code: str) -> str:
    if not isinstance(access_code, str) or not access_code:
        raise ValueError('access code must be a non-empty string')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_code(access_code: str, stored_hash: str) -> bool:
    if not isinstance(access_code, str) or not isinstance(stored_hash, str):
        return False
    try:
        salt_text, digest_text = stored_hash.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def is_eligible(monthly_income: float, household_size: int) -> bool:
    if isinstance(monthly_income, bool) or isinstance(household_size, bool):
        return False
    if not isinstance(monthly_income, (int, float)) or not isinstance(household_size, int):
        return False
    return household_size > 0 and 0 <= monthly_income <= 2000 * household_size

def assess_application(access_code: str, stored_hash: str, monthly_income: float, household_size: int) -> bool:
    return verify_access_code(access_code, stored_hash) and is_eligible(monthly_income, household_size)

