    else:
        allowed = lambda e: e.get('tenant_id') == requester.get('tenant_id')
    selected = []
    for e in excursions:
        for key in ('id', 'tenant_id', 'owner_id', 'date', 'start', 'title', 'capacity', 'booked'):
            if key not in e:
                raise ValueError('missing field')
        try:
            date.fromisoformat(e['date'])
            datetime.strptime(e['start'], '%H:%M')
        except (TypeError, ValueError):
            raise ValueError('invalid excursion time')
        if e['capacity'] < 0 or e['booked'] < 0 or e['booked'] > e['capacity']:
            raise ValueError('invalid capacity')
        if e['date'] == day and allowed(e):
            selected.append(e)
    selected.sort(key=lambda e: (e['start'], str(e['id'])))
    total_remaining = sum((e['capacity'] - e['booked'] for e in selected))
    start = (page - 1) * page_size
    items = [{'id': e['id'], 'title': e['title'], 'start': e['start'], 'remaining': e['capacity'] - e['booked'], 'fill_rate': round(e['booked'] / e['capacity'] * 100, 2) if e['capacity'] else 0.0} for e in selected[start:start + page_size]]
    return {'day': day, 'page': page, 'page_size': page_size, 'total': len(selected), 'total_remaining': total_remaining, 'excursions': items}

