import csv
import datetime
import os
import tempfile

def export_onboarding_csv(employees: list[dict], department: str | None=None, min_score: float=0, page: int=1, page_size: int=50) -> str:
    if not isinstance(employees, list):
        raise TypeError('employees must be a list')
    if department is not None and (not isinstance(department, str)):
        raise TypeError('department must be a string or None')
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(page_size, bool) or (not isinstance(page_size, int)):
        raise TypeError('pagination must be integers')
    if page < 1 or page_size < 1 or (not isinstance(min_score, (int, float))) or isinstance(min_score, bool) or (min_score < 0) or (min_score > 100):
        raise ValueError('invalid pagination or score threshold')
    rows = []
    required = {'employee_id', 'name', 'department', 'start_date', 'training_scores'}
    for employee in employees:
        if not isinstance(employee, dict) or set(employee) != required:
            raise ValueError('invalid employee')
        if not all((isinstance(employee[k], str) for k in ('employee_id', 'name', 'department', 'start_date'))):
            raise ValueError('invalid employee')
        try:
            datetime.date.fromisoformat(employee['start_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        scores = employee['training_scores']
        if not isinstance(scores, (list, tuple)) or not scores or any((isinstance(x, bool) or not isinstance(x, (int, float)) or x < 0 or (x > 100) for x in scores)):
            raise ValueError('invalid scores')
        average = round(sum(scores) / len(scores), 1)
        if (department is None or employee['department'] == department) and average >= min_score:
            rows.append((average, employee))
    rows.sort(key=lambda item: (-item[0], item[1]['employee_id']))
    start = (page - 1) * page_size
    selected = rows[start:start + page_size]
    fd, path = tempfile.mkstemp(prefix='onboarding_', suffix='.csv')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\r\n')
            writer.writerow(['employee_id', 'name', 'department', 'start_date', 'average_score'])
            for average, employee in selected:
                writer.writerow([employee['employee_id'], employee['name'], employee['department'], employee['start_date'], f'{average:.1f}'])
        with open(path, 'r', newline='', encoding='utf-8') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

