    except csv.Error as exc:
        raise ValueError() from exc
    if not rows or (rows[0] != ['sku', 'bin', 'qty', 'priority'] and set(rows[0]) != {'sku', 'bin', 'qty', 'priority'}):
        raise ValueError()
    if len(rows[0]) != 4 or set(rows[0]) != {'sku', 'bin', 'qty', 'priority'}:
        raise ValueError()
    pos = {name: rows[0].index(name) for name in rows[0]}
    out = []
    for row in rows[1:]:
        if len(row) != 4 or not any((x.strip() for x in row)):
            raise ValueError()
        try:
            sku, bin_name = (row[pos['sku']].strip(), row[pos['bin']].strip())
            qty = int(row[pos['qty']].strip())
            priority = int(row[pos['priority']].strip())
        except (ValueError, TypeError):
            raise ValueError()
        if not sku or not bin_name or qty <= 0:
            raise ValueError()
        out.append({'sku': sku, 'bin': bin_name, 'qty': qty, 'priority': priority})
    return out

def fulfill_order(order: dict, manifest: list[dict], inventory: dict[tuple[str, str], int], requester: dict) -> list[dict]:
    if requester.get('tenant_id') != order.get('tenant_id') or (requester.get('id') != order.get('owner_id') and 'fulfillment_manager' not in requester.get('roles', [])):
        raise PermissionError()
    try:
        lines = order['lines']
        for line in lines:
            if not isinstance(line['sku'], str) or not line['sku'] or type(line['qty']) is not int or (line['qty'] <= 0):
                raise ValueError()
        for value in inventory.values():
            if type(value) is not int or value < 0:
                raise ValueError()
    except (KeyError, TypeError):
        raise ValueError()
    work = inventory.copy()
    picks = []
    for line in lines:
        need = line['qty']
        candidates = sorted((r for r in manifest if r.get('sku') == line['sku']), key=lambda r: (-r['priority'], r['bin']))
        for row in candidates:
            key = (line['sku'], row['bin'])
            amount = min(need, work.get(key, 0))
            if amount:
                work[key] = work.get(key, 0) - amount
                picks.append({'order_id': order['id'], 'sku': line['sku'], 'bin': row['bin'], 'qty': amount})
                need -= amount
            if not need:
                break
        if need:
            raise ValueError()
    inventory.clear()
    inventory.update(work)
    return picks

def summarize_picks(picks: list[dict]) -> list[dict]:
    groups = {}
    for pick in picks:
        if not isinstance(pick.get('sku'), str) or not isinstance(pick.get('bin'), str) or (not pick['sku']) or (not pick['bin']) or (type(pick.get('qty')) is not int) or (pick['qty'] <= 0):
            raise ValueError()
        group = groups.setdefault(pick['sku'], {})
        group[pick['bin']] = group.get(pick['bin'], 0) + pick['qty']
    return [{'sku': sku, 'qty': sum(bins.values()), 'bins': [{'bin': b, 'qty': q} for b, q in sorted(bins.items(), key=lambda x: (-x[1], x[0]))]} for sku, bins in sorted(groups.items())]

