import json
import html

def parse_event_stream(text: str) -> list[dict]:
    fields = {'trainee', 'scenario', 'second', 'score', 'outcome'}
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
            if not isinstance(value, dict) or set(value) != fields:
                raise ValueError
            if not isinstance(value['trainee'], str) or not isinstance(value['scenario'], str):
                raise ValueError
            if isinstance(value['second'], bool) or not isinstance(value['second'], int) or value['second'] < 0:
                raise ValueError
            if isinstance(value['score'], bool) or not isinstance(value['score'], (int, float)) or (not 0 <= value['score'] <= 100):
                raise ValueError
            if value['outcome'] not in ('completed', 'failed'):
                raise ValueError
            result.append(value)
        except (ValueError, TypeError, json.JSONDecodeError):
            raise ValueError(f'invalid event on line {number}')
    return result

def summarize_sessions(events: list[dict]) -> list[dict]:
    groups = {}
    for event in events:
        key = (event['trainee'], event['scenario'])
        groups.setdefault(key, []).append(event)
    output = []
    for (trainee, scenario), items in groups.items():
        scores = [item['score'] for item in items]
        completed = sum((item['outcome'] == 'completed' for item in items))
        output.append({'trainee': trainee, 'scenario': scenario, 'attempts': len(items), 'average_score': round(sum(scores) / len(scores), 2), 'best_score': max(scores), 'completed': completed, 'failed': len(items) - completed, 'duration': max((x['second'] for x in items)) - min((x['second'] for x in items))})
    output.sort(key=lambda x: (-x['average_score'], x['trainee'].casefold(), x['scenario'].casefold(), x['trainee'], x['scenario']))
    return output

def render_training_report(events: list[dict], title: str='VR Training Report') -> str:
    rows = []
    for item in summarize_sessions(events):
        cells = [item['trainee'], item['scenario'], item['attempts'], item['average_score'], item['best_score'], item['completed'], item['failed'], item['duration']]
        rows.append('<tr>' + ''.join((f'<td>{html.escape(str(cell))}</td>' for cell in cells)) + '</tr>')
