def encode_screening_state(state: dict) -> bytes:
    if not isinstance(state, dict):
        raise ValueError('state must be a dictionary')
    try:
        text = json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False)
    except (TypeError, ValueError) as exc:
        raise ValueError('state is not JSON-compatible') from exc
    return text.encode('utf-8')

def load_screening_state(blob: bytes) -> dict:
    if not isinstance(blob, bytes):
        raise ValueError('blob must be bytes')
    try:
        value = json.loads(blob.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError, ValueError) as exc:
        raise ValueError('invalid screening state') from exc
    if not isinstance(value, dict):
        raise ValueError('screening state must be a dictionary')
    return value

