        body = json.dumps([symbol, ts, price, qty], separators=(',', ':'))
        expected = hmac.new(str(secret).encode(), body.encode(), hashlib.sha256).hexdigest()
        try:
            valid = hmac.compare_digest(expected, signature) and len(signature) == 64
        except Exception:
            valid = False
        if not valid:
            raise ValueError(f'invalid signature on line {number}')
        window = ts // 60 * 60
        key = (window, symbol)
        if key not in groups:
            groups[key] = {'symbol': symbol, 'window_start': window, 'open': price, 'high': price, 'low': price, 'close': price, 'volume': qty}
        else:
            group = groups[key]
            group['high'] = max(group['high'], price)
            group['low'] = min(group['low'], price)
            group['close'] = price
            group['volume'] += qty
    return [groups[key] for key in sorted(groups)]

