            return not visit(node.operand, values)
        if isinstance(node, ast.Compare):
            left = visit(node.left, values)
            for op, part in zip(node.ops, node.comparators):
                right = visit(part, values)
                if type(op) not in compare or not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(arg, values) for arg in node.args))
        raise SyntaxError('unsupported expression')
    selected = []
    for reading in readings:
        values = {key: reading[key] for key in ('id', 'timestamp', 'temperature', 'so2', 'co2')}
        score = visit(tree, values)
        if score:
            selected.append((score, reading['timestamp'], reading['id'], {'id': reading['id'], 'score': round(score, 2)}))
    selected.sort(key=lambda item: (-item[0], item[1], item[2]))
    return [item[3] for item in selected[:limit]]

