import os

def store_matter_document(base_dir: str, matter_id: str, filename: str, content: str) -> str:
    if not matter_id or not filename:
        raise ValueError('matter_id and filename must be non-empty')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, matter_id, filename))
    try:
        inside = os.path.commonpath((base, candidate)) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('filename is outside the base directory')
    os.makedirs(os.path.dirname(candidate), exist_ok=True)
    with open(candidate, 'w', encoding='utf-8') as handle:
        handle.write(content)
    return os.path.join(base_dir, matter_id, filename)

import sqlite3

def summarize_catches(conn: sqlite3.Connection, vessel_id: int, species: str | None=None, sort_by: str='total_weight') -> list[dict[str, object]]:
    if sort_by not in {'species', 'total_weight', 'total_count'}:
        raise ValueError('invalid sort field')
    order = {'species': 'species ASC', 'total_weight': 'total_weight DESC', 'total_count': 'total_count DESC'}[sort_by]
    sql = '\n        SELECT c.species AS species,\n               SUM(c.weight_kg) AS total_weight,\n               SUM(c.fish_count) AS total_count,\n               COUNT(DISTINCT c.report_id) AS report_count\n        FROM catches c\n        JOIN reports r ON r.report_id = c.report_id\n        WHERE r.vessel_id = ?\n    '
    values: list[object] = [vessel_id]
    if species is not None:
        sql += ' AND c.species = ?'
        values.append(species)
    sql += f' GROUP BY c.species ORDER BY {order}, species ASC'
    rows = conn.execute(sql, values).fetchall()
    return [{'species': row[0], 'total_weight': float(row[1]), 'total_count': row[2], 'report_count': row[3]} for row in rows]

