    if status not in {'pending', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    cur = conn.execute('UPDATE reports SET review_status = ? WHERE report_id = ?', (status, report_id))
    if cur.rowcount == 0:
        raise LookupError('report not found')
    conn.commit()

