    if not isinstance(readings, list):
        raise ValueError('readings must be a list')
    if gateway is not None and (not isinstance(gateway, str)):
        raise ValueError('gateway must be a string')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for item in readings:
        if not isinstance(item, dict):
            raise ValueError('invalid reading')
        try:
            g, s, u, t, value = (item[k] for k in ('gateway', 'sensor', 'unit', 'timestamp', 'value'))
        except KeyError as exc:
            raise ValueError('invalid reading') from exc
        if any((not isinstance(x, str) or not x for x in (g, s, u, t))):
            raise ValueError('invalid reading')
