            groups[key][1] = t
    ordered = sorted(groups.items(), key=lambda x: tuple(((v.lower(), v) for v in x[0])))
    total = len(ordered)
    start_index = (page - 1) * page_size
    selected = ordered[start_index:start_index + page_size]
    if selected:
        start, end = (start_index + 1, start_index + len(selected))
    else:
        start, end = (0, 0)
    out = ['<section class="sensor-report">', '<h1>Gateway sensor report</h1>', f'<p class="summary">Showing {start}-{end} of {total} sensors</p>', '<table>', '<thead><tr><th>Gateway</th><th>Sensor</th><th>Average</th><th>Unit</th><th>Latest reading</th></tr></thead>', '<tbody>']
    for (g, s, u), (values, latest) in selected:
        avg = sum(values) / len(values)
        out.append(f'<tr><td>{html.escape(g, quote=True)}</td><td>{html.escape(s, quote=True)}</td><td>{avg:.2f}</td><td>{html.escape(u, quote=True)}</td><td>{html.escape(latest, quote=True)}</td></tr>')
    out.extend(['</tbody>', '</table>', '</section>'])
    return '\n'.join(out)

