def issue_parking_permit(base_dir: str, permit_id: str, applicant: str, zone_rates: dict[str, float], requested_zones: list[str], duration_days: int) -> str:
    if not isinstance(permit_id, str) or not permit_id.strip():
        raise ValueError('invalid permit id')
    if not isinstance(applicant, str) or not applicant.strip():
        raise ValueError('invalid applicant')
    if isinstance(duration_days, bool) or not isinstance(duration_days, int) or (not 1 <= duration_days <= 365):
        raise ValueError('invalid duration')
