            if any((name not in sample.attrib for name in required)):
                raise ValueError('missing sample attribute')
            result.append({'site_id': site.attrib['id'], 'site_name': site.attrib['name'], 'collected_at': sample.attrib['collected_at'], 'ph': sample.attrib['ph'], 'turbidity_ntu': sample.attrib['turbidity_ntu']})
    return result

