    if not isinstance(registrations, list):
        raise ValueError('registrations must be a list')
    if isinstance(min_credits, bool) or not isinstance(min_credits, int) or min_credits < 0:
        raise ValueError('invalid minimum credits')
    totals = {}
    for registration in registrations:
        if not isinstance(registration, dict) or set(registration) != {'student_id', 'course', 'credits', 'status'}:
            raise ValueError('invalid registration')
        student = registration['student_id']
        course = registration['course']
        credits = registration['credits']
        status = registration['status']
        if not isinstance(student, str) or not student or (not isinstance(course, str)) or (not course):
            raise ValueError('invalid registration')
        if isinstance(credits, bool) or not isinstance(credits, int) or credits <= 0:
            raise ValueError('invalid registration')
        if status not in {'enrolled', 'waitlisted', 'dropped'}:
            raise ValueError('invalid registration')
