            item = totals.setdefault(student, [0, 0])
            item[0] += credits
            item[1] += 1
    rows = []
    for student, (total, courses) in totals.items():
        if total >= min_credits:
            rows.append({'student_id': student, 'total_credits': total, 'courses': courses, 'average_credits': round(total / courses, 2)})
    rows.sort(key=lambda row: (-row['total_credits'], row['student_id']))
