        if maximum <= 50:
            category = 'Good'
        elif maximum <= 100:
            category = 'Moderate'
        elif maximum <= 150:
            category = 'Unhealthy for Sensitive Groups'
        elif maximum <= 200:
            category = 'Unhealthy'
        elif maximum <= 300:
            category = 'Very Unhealthy'
        else:
            category = 'Hazardous'
        summary = {'count': len(values), 'average_aqi': round(sum(values) / len(values), 2), 'maximum_aqi': maximum, 'category': category}
    else:
        summary = {'count': 0, 'average_aqi': 0.0, 'maximum_aqi': None, 'category': 'No data'}
