import re
DAYS = {'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'}
FIELDS = {'patient', 'clinician', 'day', 'priority', 'start'}

def _time(value, ending=False):
    if not isinstance(value, str) or not re.fullmatch('(?:[01]\\d|2[0-3]):[0-5]\\d|24:00', value):
        raise ValueError('invalid time')
    h, m = map(int, value.split(':'))
    if h == 24 and (not ending):
        raise ValueError('invalid time')
    return h * 60 + m

def parse_availability(text):
    if not isinstance(text, str):
        raise ValueError('invalid availability')
    answer = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split('|')
        if len(parts) != 3 or not parts[0] or parts[1] not in DAYS or (not parts[2]):
            raise ValueError('invalid line')
        clinician, day, ranges = parts
        if clinician not in answer:
            answer[clinician] = {}
        if day in answer[clinician]:
            raise ValueError('duplicate day')
        parsed = []
        for item in ranges.split(','):
            if item.count('-') != 1:
                raise ValueError('invalid range')
            a, b = item.split('-')
            start, end = (_time(a), _time(b, True))
            if end <= start or (parsed and start <= parsed[-1][1]):
                raise ValueError('overlap')
            parsed.append((start, end))
        answer[clinician][day] = parsed
    return answer

def make_invite_code(prefix=''):
    if not isinstance(prefix, str) or not re.fullmatch('[A-Za-z0-9_-]*', prefix):
        raise ValueError('invalid prefix')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
