    if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
        raise ValueError('invalid duration')
    windows = parse_availability(availability)
    if not isinstance(requests, list):
        raise ValueError('invalid requests')
    checked, patients = ([], set())
    for item in requests:
        if not isinstance(item, dict) or set(item) != FIELDS:
            raise ValueError('invalid request')
        if any((not isinstance(item[k], str) for k in ('patient', 'clinician', 'day', 'start'))):
            raise ValueError('invalid request')
        if isinstance(item['priority'], bool) or not isinstance(item['priority'], int):
            raise ValueError('invalid priority')
        if not item['patient'] or item['patient'] in patients or item['day'] not in DAYS:
            raise ValueError('invalid patient or day')
        start = _time(item['start'])
        patients.add(item['patient'])
        checked.append((item, start))
    checked.sort(key=lambda x: (-x[0]['priority'], x[1], x[0]['patient']))
    used = {}
    result = []
    for item, requested in checked:
        intervals = windows.get(item['clinician'], {}).get(item['day'], [])
        key = (item['clinician'], item['day'])
        busy = used.setdefault(key, [])
        chosen = None
        for lo, hi in intervals:
            cursor = max(lo, requested)
            for a, b in sorted(busy):
                if b <= cursor:
                    continue
                if cursor + duration <= a:
