    if not isinstance(threshold, (int, float)) or isinstance(threshold, bool) or (not 0 <= threshold <= 1):
        raise ValueError('invalid threshold')
    seen = set()
    checked = []
    for r in reviews:
        if not isinstance(r, dict) or any((k not in r for k in ('review_id', 'product_id', 'user_id', 'text', 'flags', 'confidence', 'created_at'))):
            raise ValueError('invalid review')
        if any((not isinstance(r[k], str) or (k != 'text' and (not r[k])) for k in ('review_id', 'product_id', 'user_id', 'text'))):
            raise ValueError('invalid review')
        if r['review_id'] in seen or not isinstance(r['flags'], list) or any((not isinstance(x, str) for x in r['flags'])):
            raise ValueError('invalid review')
        if not isinstance(r['confidence'], (int, float)) or isinstance(r['confidence'], bool):
            raise ValueError('invalid review')
        try:
            dt = datetime.datetime.fromisoformat(r['created_at'])
        except (TypeError, ValueError):
            raise ValueError('invalid review')
        seen.add(r['review_id'])
        flags = [x.strip().lower() for x in r['flags']]
        status = 'removed' if any((x in ('spam', 'abuse') for x in flags)) else 'review' if flags or r['confidence'] < threshold else 'approved'
        checked.append((r, dt, status))
    return checked

def build_moderation_summary(reviews: list[dict], threshold: float=0.75) -> list[dict]:
    groups = {}
    for r, dt, status in _checked(reviews, threshold):
        p = r['product_id']
        g = groups.setdefault(p, {'product_id': p, 'total': 0, 'approved': 0, 'review': 0, 'removed': 0, 'sum': 0.0, 'latest': None})
        g['total'] += 1
        g[status] += 1
        g['sum'] += r['confidence']
        if g['latest'] is None or dt >= g['latest'][0]:
            g['latest'] = (dt, r['created_at'])
    out = []
    for g in groups.values():
        out.append({'product_id': g['product_id'], 'total': g['total'], 'approved': g['approved'], 'review': g['review'], 'removed': g['removed'], 'average_confidence': round(g['sum'] / g['total'], 3), 'latest_review': g['latest'][1]})
    return sorted(out, key=lambda x: (-x['removed'], -x['review'], x['product_id']))

def export_moderation_report(reviews: list[dict], destination: str, threshold: float=0.75) -> int:
    rows = build_moderation_summary(reviews, threshold)
    temp = tempfile.mktemp(prefix='moderation-', suffix='.csv', dir=os.path.dirname(destination) or '.')
    try:
        with open(temp, 'w', newline='', encoding='utf-8') as f:
            writer = csv.writer(f)
            writer.writerow(['product_id', 'total', 'approved', 'review', 'removed', 'average_confidence', 'latest_review'])
            for r in rows:
                writer.writerow([r[k] for k in ('product_id', 'total', 'approved', 'review', 'removed', 'average_confidence', 'latest_review')])
        os.replace(temp, destination)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)
    return len(rows)

