import hashlib
import hmac
import json
from datetime import datetime, timedelta, timezone

def summarize_inventory(payload: str, secret: bytes) -> dict:
    try:
        data = json.loads(payload)
        if not isinstance(data, list):
            raise ValueError
        parsed = []
        slots = set()
        wanted = ('campaign', 'slot', 'start', 'seconds', 'impressions', 'signature')
        for item in data:
            if not isinstance(item, dict) or set(item) != set(wanted):
                raise ValueError
            if not isinstance(item['campaign'], str) or not item['campaign']:
                raise ValueError
            if not isinstance(item['slot'], str) or not item['slot'] or item['slot'] in slots:
                raise ValueError
            if type(item['seconds']) is not int or item['seconds'] <= 0:
                raise ValueError
            if type(item['impressions']) is not int or item['impressions'] < 0:
                raise ValueError
            start_text = item['start']
            if not isinstance(start_text, str) or len(start_text) != 20 or (not start_text.endswith('Z')):
                raise ValueError
            start = datetime.strptime(start_text, '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            body = {k: item[k] for k in ('campaign', 'slot', 'start', 'seconds', 'impressions')}
            canonical = json.dumps(body, separators=(',', ':'), ensure_ascii=False).encode()
            expected = hmac.new(secret, canonical, hashlib.sha256).hexdigest()
            if not isinstance(item['signature'], str) or len(item['signature']) != 64 or (not hmac.compare_digest(item['signature'], expected)):
                raise ValueError
            slots.add(item['slot'])
            parsed.append((start, start + timedelta(seconds=item['seconds']), item))
        parsed.sort(key=lambda x: (x[0], x[2]['slot']))
        for previous, current in zip(parsed, parsed[1:]):
            if current[0] < previous[1]:
                raise ValueError
        campaigns = {}
        timeline = []
        for start, end, item in parsed:
            total = campaigns.setdefault(item['campaign'], {'impressions': 0, 'seconds': 0})
            total['impressions'] += item['impressions']
            total['seconds'] += item['seconds']
            timeline.append({'slot': item['slot'], 'campaign': item['campaign'], 'start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'end': end.strftime('%Y-%m-%dT%H:%M:%SZ')})
        return {'campaigns': {k: campaigns[k] for k in sorted(campaigns)}, 'timeline': timeline}
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError from exc

