import os
import tempfile

def export_substitution_report(records: list[dict], output_path: str) -> dict:
    fields = ('order_id', 'original_item', 'replacement_item', 'requested_qty', 'fulfilled_qty', 'unit_price_cents')
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    checked = []
    orders = set()
    for record in records:
        if not isinstance(record, dict) or set(record) != set(fields):
            raise ValueError('invalid record')
        for name in ('order_id', 'original_item', 'replacement_item'):
            if not isinstance(record[name], str) or not record[name]:
                raise ValueError('invalid text field')
        for name in ('requested_qty', 'fulfilled_qty', 'unit_price_cents'):
            if isinstance(record[name], bool) or not isinstance(record[name], int) or record[name] < 0:
                raise ValueError('invalid numeric field')
        if record['fulfilled_qty'] > record['requested_qty']:
            raise ValueError('invalid quantities')
        checked.append(record)
        orders.add(record['order_id'])
    rows = [r for r in checked if r['replacement_item'] != r['original_item']]
    rows.sort(key=lambda r: (r['order_id'], r['original_item'], r['replacement_item']))
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary = tempfile.mkstemp(prefix='.grocery-', suffix='.tmp', dir=directory)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['order_id', 'original_item', 'replacement_item', 'requested_qty', 'fulfilled_qty', 'refund_cents'])
            total = 0
            for row in rows:
                refund = (row['requested_qty'] - row['fulfilled_qty']) * row['unit_price_cents']
                total += refund
                writer.writerow([row['order_id'], row['original_item'], row['replacement_item'], row['requested_qty'], row['fulfilled_qty'], refund])
        os.replace(temporary, output_path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'orders': len(orders), 'lines': len(rows), 'refund_cents': total}

