import os
import subprocess
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_bookings(file_path: str, page: int=1, page_size: int=10) -> list[tuple[str, int, float]]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if not os.path.isfile(file_path):
        raise FileNotFoundError(file_path)
    completed = subprocess.run(['sort', file_path], capture_output=True, text=True, check=True)
    totals = {}
    for raw_line in completed.stdout.splitlines():
        line = raw_line.strip()
        if not line:
            continue
        parts = line.split('|')
        if len(parts) != 3 or not parts[0]:
            raise ValueError('malformed record')
        movie, quantity_text, price_text = parts
        try:
            quantity = int(quantity_text)
        except ValueError as exc:
            raise ValueError('invalid quantity') from exc
        if quantity <= 0 or str(quantity) != quantity_text:
            raise ValueError('invalid quantity')
        try:
            price = Decimal(price_text)
        except InvalidOperation as exc:
            raise ValueError('invalid price') from exc
        if not price.is_finite() or price < 0:
            raise ValueError('invalid price')
        if movie not in totals:
            totals[movie] = [0, Decimal('0')]
        totals[movie][0] += quantity
        totals[movie][1] += price * quantity
    results = []
    for movie in sorted(totals):
        quantity, revenue = totals[movie]
        rounded = revenue.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        results.append((movie, quantity, float(rounded)))
    start = (page - 1) * page_size
    return results[start:start + page_size]

