        start, end = (_time(times[0]), _time(times[1]))
        try:
            capacity = int(parts[2])
        except ValueError:
            raise ValueError('invalid capacity')
        if end <= start or capacity <= 0:
            raise ValueError('invalid window')
        result.append((parts[0], start, end, capacity))
