from collections import defaultdict
_BLOOD = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
_STATUS = {'ACTIVE', 'PAUSED', 'REMOVED'}

def _read(path):
    with open(path, 'rb'):
        pass
    r = subprocess.run(['sort', '-t', '\t', '-k6,6', '-k4,4nr', '-k5,5nr', '-k1,1', path], capture_output=True, text=True, check=True)
    out = []
    ids = set()
    for raw in r.stdout.splitlines():
        if not raw.strip():
            continue
        p = raw.split('\t')
        if len(p) != 7:
            raise ValueError('malformed row')
        cid, name, blood, urg, days, region, status = p
        if not cid or blood not in _BLOOD or status not in _STATUS:
            raise ValueError('invalid field')
        try:
            u, d = (int(urg), int(days))
        except ValueError:
            raise ValueError('invalid number')
        if not 0 <= u <= 9 or d < 0 or cid in ids:
            raise ValueError('invalid record')
        ids.add(cid)
        if status == 'ACTIVE':
            out.append((cid, name, blood, u, d, region))
    return out

def rank_waitlist(path: str, region: str | None=None, limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0):
        raise ValueError('invalid limit')
    rows = _read(path)
    result, counts = ([], defaultdict(int))
    for cid, name, blood, urgency, days, reg in rows:
        if region is not None and reg != region:
            continue
        counts[reg] += 1
        if limit is None or counts[reg] <= limit:
            result.append({'candidate_id': cid, 'candidate_name': name, 'blood_type': blood, 'urgency': urgency, 'days_waiting': days, 'region': reg, 'rank': counts[reg]})
    return result

def summarize_waitlist(path: str) -> dict[str, dict[str, int | float]]:
    rows = rank_waitlist(path)
    groups = defaultdict(list)
    for x in rows:
        groups[x['region']].append(x)
    result = {}
    for reg in sorted(groups):
        xs = groups[reg]
        bt = {}
        for x in xs:
            bt[x['blood_type']] = bt.get(x['blood_type'], 0) + 1
        result[reg] = {'active_count': len(xs), 'highest_urgency': max((x['urgency'] for x in xs)), 'average_days_waiting': round(sum((x['days_waiting'] for x in xs)) / len(xs), 2), 'blood_types': {k: bt[k] for k in sorted(bt)}}
    return result

