import csv
import os
import tempfile

def _check(orders, workers):
    if isinstance(workers, bool) or not isinstance(workers, int) or workers < 1:
        raise ValueError('workers')
    seen = set()
    clean = []
    for order in orders:
        if not isinstance(order, dict) or set(order) != {'id', 'station', 'priority', 'duration', 'due'}:
            raise ValueError('order')
        ident = order['id']
        station = order['station']
        if not isinstance(ident, str) or not ident or (not isinstance(station, str)) or (not station):
            raise ValueError('text')
        if ident in seen:
            raise ValueError('duplicate')
        seen.add(ident)
        if any((isinstance(order[k], bool) or not isinstance(order[k], int) for k in ('priority', 'duration', 'due'))):
            raise ValueError('number')
        if order['duration'] <= 0:
            raise ValueError('duration')
        clean.append(order)
    return clean

def dispatch_schedule(orders: list[dict], workers: int) -> list[dict]:
    orders = _check(orders, workers)
    loads = [0] * workers
    result = []
    for order in sorted(orders, key=lambda x: (-x['priority'], x['due'], x['id'])):
        worker = min(range(workers), key=lambda n: (loads[n], n))
        start = loads[worker]
        finish = start + order['duration']
        loads[worker] = finish
        result.append({'id': order['id'], 'station': order['station'], 'priority': order['priority'], 'due': order['due'], 'duration': order['duration'], 'worker': worker, 'start': start, 'finish': finish})
    return sorted(result, key=lambda x: (x['worker'], x['start'], x['id']))

def write_dispatch_csv(orders: list[dict], path: str, workers: int) -> int:
    rows = dispatch_schedule(orders, workers)
    parent = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(dir=parent, prefix='.dispatch-', suffix='.tmp')
    os.close(fd)
