def parse_clock(value: str) -> int:
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError('invalid clock value')
    if not value[:2].isdigit() or not value[3:].isdigit():
        raise ValueError('invalid clock value')
    hour = int(value[:2])
    minute = int(value[3:])
    if hour > 23 or minute > 59:
        raise ValueError('invalid clock value')
    return hour * 60 + minute

def build_schedule(trips: list[dict], drivers: list[dict], config: dict[str, str]) -> dict:
    if 'API_TOKEN' not in config:
        raise ValueError('API_TOKEN is required')
    token = config['API_TOKEN']
    trip_ids = [t['id'] for t in trips]
    driver_ids = [d['id'] for d in drivers]
    if len(set(trip_ids)) != len(trip_ids) or len(set(driver_ids)) != len(driver_ids):
        raise ValueError('duplicate identifier')
    prepared = []
    for trip in trips:
        start = parse_clock(trip['start'])
        duration = trip['duration']
        if isinstance(duration, bool) or not isinstance(duration, int) or duration <= 0:
            raise ValueError('duration must be positive')
        prepared.append((start, trip['id'], trip, start + duration))
    availability = {}
    for driver in drivers:
        begin = parse_clock(driver['available_from'])
        finish = parse_clock(driver['available_to'])
        if begin >= finish:
            raise ValueError('invalid availability')
        availability[driver['id']] = (driver, begin, finish)
    prepared.sort(key=lambda item: (item[0], item[1]))
    assigned = {driver['id']: [] for driver in drivers}
    counts = {driver['id']: 0 for driver in drivers}
    output = []
    unassigned = []
    for start, trip_id, trip, end in prepared:
        candidates = []
        for driver_id, (driver, begin, finish) in availability.items():
            if driver['class'] != trip['class'] or start < begin or end > finish:
                continue
            if all((end <= old_start or start >= old_end for old_start, old_end in assigned[driver_id])):
                candidates.append(driver_id)
        if not candidates:
            unassigned.append(trip_id)
            continue
        driver_id = min(candidates, key=lambda item: (counts[item], item))
        assigned[driver_id].append((start, end))
        counts[driver_id] += 1
        output.append({'trip_id': trip_id, 'driver_id': driver_id, 'start': start, 'end': end})
    return {'authorization': 'Bearer ' + token, 'assignments': output, 'unassigned': unassigned}

