from pathlib import Path

def write_records(lines):
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', delete=False)
    try:
        handle.write('\n'.join(lines))
        handle.write('\n')
        return Path(handle.name)
    finally:
        handle.close()

def test_orders_by_days_then_date_then_patron():
    path = write_records(['2024-03-01\tzoe\tBook Z\t5', '2024-01-02\tbob\tBook B\t9', '2024-01-01\tzoe\tBook A\t9', '2024-01-01\tamy\tBook C\t9', '2024-02-01\tamy\tBook D\t2'])
    try:
        assert rank_lending_records(str(path), 0) == [('2024-01-01', 'amy', 'Book C', 9), ('2024-01-01', 'zoe', 'Book A', 9), ('2024-01-02', 'bob', 'Book B', 9), ('2024-03-01', 'zoe', 'Book Z', 5), ('2024-02-01', 'amy', 'Book D', 2)]
    finally:
        path.unlink()

def test_pagination_and_page_boundaries():
    path = write_records(['2024-01-01\ta\tA\t5', '2024-01-02\tb\tB\t4', '2024-01-03\tc\tC\t3', '2024-01-04\td\tD\t2', '2024-01-05\te\tE\t1'])
    try:
        assert rank_lending_records(str(path), 0, 1, 2) == [('2024-01-01', 'a', 'A', 5), ('2024-01-02', 'b', 'B', 4)]
        assert rank_lending_records(str(path), 0, 2, 2) == [('2024-01-03', 'c', 'C', 3), ('2024-01-04', 'd', 'D', 2)]
        assert rank_lending_records(str(path), 0, 3, 2) == [('2024-01-05', 'e', 'E', 1)]
        assert rank_lending_records(str(path), 0, 4, 2) == []
    finally:
        path.unlink()

def test_ignores_blank_and_malformed_records():
    path = write_records(['', '2024-01-01\ta\tValid\t7', 'not enough fields', '2024-01-02\tb\tBad number\tnope', '2024-01-03\tc\tToo\tmany\t8', '2024-01-04\td\tZero\t0'])
    try:
        assert rank_lending_records(str(path), 0) == [('2024-01-01', 'a', 'Valid', 7), ('2024-01-04', 'd', 'Zero', 0)]
    finally:
        path.unlink()

