import hashlib
import hmac
import os
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def make_extension(extension: str, password: str) -> dict:
    if not isinstance(extension, str) or not extension or (not isinstance(password, str)) or (not password):
        raise ValueError('invalid account')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'extension': extension, 'salt': salt.hex(), 'password_hash': value.hex()}

def generate_cdr_report(calls: list[dict], account: dict, password: str, start_date: str | None=None, end_date: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid page')

    def parsed(value):
        if value is None:
            return None
        try:
            if not isinstance(value, str) or len(value) != 10 or value[4] != '-' or (value[7] != '-'):
                raise ValueError
            return date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
    lo, hi = (parsed(start_date), parsed(end_date))
    if lo and hi and (lo > hi):
        raise ValueError('invalid range')
    try:
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(account['salt']), 100000)
        expected = bytes.fromhex(account['password_hash'])
    except (KeyError, TypeError, ValueError, AttributeError):
        raise ValueError('invalid password')
    if not hmac.compare_digest(actual, expected):
        raise ValueError('invalid password')
    groups = {}
    for item in calls:
        try:
            d = parsed(item['date'])
            if lo and d < lo or (hi and d > hi) or item['extension'] != account['extension']:
                continue
            duration = item['duration']
            if not isinstance(duration, int) or isinstance(duration, bool) or duration < 0:
                raise ValueError
            cost = Decimal(str(item['cost']))
            destination = item['destination']
            if cost < 0 or not cost.is_finite() or (not isinstance(destination, str)):
                raise ValueError
        except (KeyError, TypeError, InvalidOperation, ValueError):
            raise ValueError('invalid call')
        row = groups.setdefault(destination, [0, 0, Decimal(0)])
        row[0] += 1
        row[1] += duration
        row[2] += cost
    result = [{'destination': k, 'calls': v[0], 'seconds': v[1], 'cost': float(v[2].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for k, v in groups.items()]
    result.sort(key=lambda x: (-x['cost'], x['destination']))
    begin = (page - 1) * page_size
    return result[begin:begin + page_size]

