import json
import os
from datetime import date

def _path(base_dir, name):
    if not isinstance(name, str) or not name or name in ('.', '..'):
        raise ValueError('invalid report name')
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, name))
    if path != base and (not path.startswith(base + os.sep)):
        raise ValueError('invalid report name')
    return path

def _check_updates(updates):
    if not isinstance(updates, list):
        raise ValueError('invalid updates')
    out = []
    seen = set()
    for item in updates:
        if not isinstance(item, dict) or set(item) != {'date', 'activity', 'percent'}:
            raise ValueError('invalid update')
        text = item['date']
        activity = item['activity']
        percent = item['percent']
        try:
            parsed = date.fromisoformat(text)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if parsed.isoformat() != text or not isinstance(activity, str) or (not activity):
            raise ValueError('invalid update')
        if isinstance(percent, bool) or not isinstance(percent, (int, float)) or (not 0 <= percent <= 100):
            raise ValueError('invalid percent')
        key = (text, activity)
        if key in seen:
            raise ValueError('duplicate update')
        seen.add(key)
        out.append({'date': text, 'activity': activity, 'percent': percent})
    return sorted(out, key=lambda x: (x['date'], x['activity']))

def save_progress_report(base_dir: str, relative_name: str, updates: list[dict]) -> str:
    path = _path(base_dir, relative_name)
    data = {'updates': _check_updates(updates)}
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f, indent=2)
        f.write('\n')
    return path

def summarize_progress(base_dir: str, relative_names: list[str]) -> list[dict]:
    grouped = {}
    for report_index, name in enumerate(relative_names):
        path = _path(base_dir, name)
        with open(path, encoding='utf-8') as f:
            try:
                data = json.load(f)
            except (TypeError, ValueError, json.JSONDecodeError):
                raise ValueError('malformed report')
        if not isinstance(data, dict) or set(data) != {'updates'}:
            raise ValueError('malformed report')
        updates = _check_updates(data['updates'])
        for position, item in enumerate(updates):
            grouped.setdefault(item['activity'], []).append((item['date'], report_index, position, item['percent']))
    result = []
    for activity in sorted(grouped):
        rows = sorted(grouped[activity], key=lambda x: (x[0], x[1], x[2]))
        values = [x[3] for x in rows]
        result.append({'activity': activity, 'latest_percent': values[-1], 'average_last_3': round(sum(values[-3:]) / min(3, len(values)), 2), 'update_count': len(values)})
    return result

