def render_eligibility_report(records: list[dict], page: int=1, per_page: int=10) -> str:
    if not isinstance(records, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(per_page, int)) or isinstance(per_page, bool) or (not 1 <= per_page <= 100):
        raise ValueError('invalid arguments')
    required = {'applicant', 'plan', 'eligible', 'monthly_premium'}
    checked = []
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('invalid record')
        if not isinstance(record['applicant'], str) or not isinstance(record['plan'], str) or (not isinstance(record['eligible'], bool)):
            raise ValueError('invalid record')
        premium = record['monthly_premium']
        if isinstance(premium, bool) or not isinstance(premium, (int, float)) or (not math.isfinite(premium)) or (premium < 0):
            raise ValueError('invalid record')
        checked.append(record)
    ordered = sorted(checked, key=lambda r: (not r['eligible'], r['monthly_premium'], r['applicant'].casefold()))
    eligible = [r for r in checked if r['eligible']]
    average = sum((r['monthly_premium'] for r in eligible)) / len(eligible) if eligible else 0
    total_pages = max(1, (len(ordered) + per_page - 1) // per_page)
    selected = ordered[(page - 1) * per_page:page * per_page]
    lines = ['<div class="eligibility-report">', '<h2>Eligibility Results</h2>', f'<p class="summary">Eligible: {len(eligible)} of {len(ordered)} | Average eligible premium: ${average:.2f}</p>', '<table><thead><tr><th>Applicant</th><th>Plan</th><th>Status</th><th>Monthly premium</th></tr></thead><tbody>']
    for record in selected:
        applicant = html.escape(record['applicant'], quote=True)
        plan = html.escape(record['plan'], quote=True)
        status = 'Eligible' if record['eligible'] else 'Not eligible'
        lines.append(f"<tr><td>{applicant}</td><td>{plan}</td><td>{status}</td><td>${record['monthly_premium']:.2f}</td></tr>")
