def register_sensor(sensor_id: str, pin: str, region: str) -> dict:
    if not isinstance(sensor_id, str) or not sensor_id or (not isinstance(pin, str)) or (not pin) or (not isinstance(region, str)) or (not region):
        raise ValueError('invalid sensor')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'sensor_id': sensor_id, 'region': region, 'salt': salt.hex(), 'pin_hash': value.hex()}

def authenticate_sensor(record: dict, pin: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        salt = bytes.fromhex(record['salt'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000).hex()
        return hmac.compare_digest(actual, record['pin_hash'])
    except (KeyError, TypeError, ValueError):
        return False

def parse_feed(text: str) -> list[dict]:
    try:
        data = json.loads(text)
    except Exception as exc:
        raise ValueError('invalid feed') from exc
    if not isinstance(data, dict) or set(data) != {'readings'} or (not isinstance(data['readings'], list)):
        raise ValueError('invalid feed')
    out = []
    for item in data['readings']:
        if not isinstance(item, dict) or set(item) != {'sensor_id', 'timestamp', 'magnitude'}:
            raise ValueError('invalid reading')
        if not isinstance(item['sensor_id'], str) or not isinstance(item['timestamp'], int) or isinstance(item['timestamp'], bool) or (item['timestamp'] < 0) or (not isinstance(item['magnitude'], (int, float))) or isinstance(item['magnitude'], bool) or (not math.isfinite(item['magnitude'])):
            raise ValueError('invalid reading')
        out.append(dict(item))
    return out

def build_alerts(readings: list[dict], sensors: dict[str, dict], window_seconds: int=60, threshold: float=5.0) -> list[dict]:
    if not isinstance(window_seconds, int) or isinstance(window_seconds, bool) or window_seconds <= 0 or (not isinstance(threshold, (int, float))) or isinstance(threshold, bool) or (not math.isfinite(threshold)) or (threshold < 0):
        raise ValueError('invalid arguments')
    groups = {}
    for row in readings:
        if not isinstance(row, dict) or not all((k in row for k in ('sensor_id', 'timestamp', 'magnitude'))):
            continue
        sid, ts, mag = (row['sensor_id'], row['timestamp'], row['magnitude'])
        if sid not in sensors or not isinstance(ts, int) or isinstance(ts, bool) or (ts < 0) or (not isinstance(mag, (int, float))) or isinstance(mag, bool) or (not math.isfinite(mag)) or (not authenticate_sensor(sensors[sid], row.get('pin'))):
            continue
        start = ts // window_seconds * window_seconds
        groups.setdefault((start, sid), []).append(mag)
    out = []
    for (start, sid), values in groups.items():
        peak = max(values)
        if peak >= threshold:
            out.append({'sensor_id': sid, 'start': start, 'end': start + window_seconds, 'count': len(values), 'average': sum(values) / len(values), 'peak': peak, 'severity': 'critical' if peak >= threshold * 1.5 else 'warning'})
