from pathlib import Path
from collections import Counter
import subprocess

def count_matching_responses(directory: str, keyword: str) -> dict[str, int]:
    root = Path(directory)
    if not root.is_dir():
        raise FileNotFoundError(directory)
    files = sorted((str(path) for path in root.iterdir() if path.is_file() and path.name.endswith('.txt')))
    if not files:
        return {}
    result = subprocess.run(['grep', '-h', '-F', '--', keyword, *files], capture_output=True, text=True, check=False)
    if result.returncode > 1:
        raise subprocess.CalledProcessError(result.returncode, result.args, result.stdout, result.stderr)
    counts = Counter(result.stdout.splitlines())
    return {key: counts[key] for key in sorted(counts)}

