import csv
import hashlib
import hmac
import io
import json
import math
import os
from collections import defaultdict
from datetime import date

def parse_events(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    rows = [r for r in rows if any((x.strip() for x in r))]
    header = ['participant', 'program', 'date', 'value']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 4 or not row[0].strip() or (not row[1].strip()):
            raise ValueError('invalid event row')
        try:
            parsed_date = date.fromisoformat(row[2])
            if parsed_date.isoformat() != row[2]:
                raise ValueError
            value = float(row[3])
        except (ValueError, TypeError):
            raise ValueError('invalid event value')
        if not math.isfinite(value) or value < 0:
            raise ValueError('invalid event value')
        result.append({'participant': row[0], 'program': row[1], 'date': parsed_date, 'value': value})
    return result

def compute_metrics(events: list[dict]) -> dict:
    groups = defaultdict(list)
    for event in events:
        groups[event['program']].append(event)
    programs = []
    for name in sorted(groups):
        items = groups[name]
        months = defaultdict(list)
        for event in items:
            months[event['date'].strftime('%Y-%m')].append(event)
        month_data = []
        for month in sorted(months):
            part = months[month]
            month_data.append({'month': month, 'event_count': len(part), 'total_value': round(sum((x['value'] for x in part)), 2), 'participants': len({x['participant'] for x in part})})
        programs.append({'program': name, 'months': month_data, 'event_count': len(items), 'total_value': round(sum((x['value'] for x in items)), 2), 'participants': len({x['participant'] for x in items})})
    return {'programs': programs}

def publish_report(text: str, config: dict) -> dict:
    key = config.get('signing_key')
    if not isinstance(key, str):
        raise ValueError('missing signing key')
    payload = json.dumps(compute_metrics(parse_events(text)), ensure_ascii=False, separators=(',', ':'), sort_keys=True)
    signature = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    return {'payload': payload, 'signature': signature}

