def build_species_report(requester: dict, observations: list[dict], start_date: str, end_date: str, page: int, page_size: int) -> dict:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except (TypeError, ValueError) as exc:
        raise ValueError('invalid date') from exc
    if start > end or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid range or pagination')
    selected = []
    totals = {}
    for row in observations:
        try:
            current = date.fromisoformat(row['date'])
            species = row['species']
            individuals = row['individuals']
            owner = row['owner_id']
            tenant = row['tenant_id']
            identifier = row['id']
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid observation') from exc
        if type(individuals) is not int or individuals < 0:
            raise ValueError('invalid individuals')
        roles = requester.get('roles', [])
        allowed = owner == requester.get('user_id') or ('manager' in roles and tenant == requester.get('tenant_id'))
        if not allowed:
            raise PermissionError('observation access denied')
        if start <= current <= end:
            selected.append(row)
            if species not in totals:
                totals[species] = [0, 0]
            totals[species][0] += 1
            totals[species][1] += individuals
    selected.sort(key=lambda row: (row['date'], row['id']))
    species = [{'species': name, 'observations': values[0], 'individuals': values[1]} for name, values in totals.items()]
    species.sort(key=lambda row: (-row['individuals'], row['species']))
    begin = (page - 1) * page_size
    return {'total_observations': len(selected), 'total_individuals': sum((row['individuals'] for row in selected)), 'species': species, 'items': selected[begin:begin + page_size]}

