import csv
import html
import io

def parse_plot_records(text: str) -> list[dict]:
    result = []
    for line_no, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            row = next(csv.reader([line], delimiter='|', quotechar='"'))
        except csv.Error as exc:
            raise ValueError(f'line {line_no}: malformed record') from exc
        if len(row) != 5:
            raise ValueError(f'line {line_no}: expected five fields')
        section, plot, name, year_text, status = (x.strip() for x in row)
        if not section or not plot or (not name):
            raise ValueError(f'line {line_no}: empty required field')
        try:
            year = int(year_text)
        except ValueError as exc:
            raise ValueError(f'line {line_no}: invalid year') from exc
        if not 1000 <= year <= 2100:
            raise ValueError(f'line {line_no}: invalid year')
        if status not in ('occupied', 'available'):
            raise ValueError(f'line {line_no}: invalid status')
        result.append({'section': section, 'plot': plot, 'name': name, 'year': year, 'status': status})
    return result

def summary_records(records: list[dict]) -> dict:
    sections = {}
    occupied = sum((r['status'] == 'occupied' for r in records))
    for record in records:
        section = record['section']
        if section not in sections:
            sections[section] = {'occupied': 0, 'available': 0}
        sections[section][record['status']] += 1
    return {'total': len(records), 'occupied': occupied, 'available': len(records) - occupied, 'by_section': {key: sections[key] for key in sorted(sections)}}

def render_cemetery_report(records: list[dict], title: str, sort_by: str='section') -> str:
    fields = ('section', 'plot', 'name', 'year', 'status')
    if sort_by not in fields:
        raise ValueError('invalid sort field')
    ordered = sorted(records, key=lambda r: tuple((r[k] for k in (sort_by,) + tuple((x for x in fields if x != sort_by)))))
    occupied = sum((r['status'] == 'occupied' for r in records))
    rows = ''.join(('<tr><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>'.format(*(html.escape(str(r[k]), quote=True) for k in fields)) for r in ordered))
    return '<div class="cemetery-report"><h1>{}</h1><p class="totals">{} plots, {} occupied</p><table><thead><tr><th>Section</th><th>Plot</th><th>Name</th><th>Year</th><th>Status</th></tr></thead><tbody>{}</tbody></table></div>'.format(html.escape(title, quote=True), len(records), occupied, rows)

