from datetime import datetime

def parse_telemetry(text: str) -> list[dict]:
    try:
        rows = list(csv.reader(io.StringIO(text)))
    except csv.Error as exc:
        raise ValueError('invalid CSV') from exc
    if not rows or rows[0] != ['timestamp', 'pressure', 'vibration']:
        raise ValueError('invalid header')
    result = []
    previous = None
    for row in rows[1:]:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 3:
            raise ValueError('invalid row')
        stamp = row[0]
        try:
            current = datetime.fromisoformat(stamp[:-1] + '+00:00') if stamp.endswith('Z') else None
            pressure = float(row[1].strip())
            vibration = float(row[2].strip())
        except (ValueError, TypeError):
            raise ValueError('invalid telemetry')
        if current is None or not math.isfinite(pressure) or (not math.isfinite(vibration)):
            raise ValueError('invalid telemetry')
        if previous is not None and current <= previous:
            raise ValueError('timestamps must increase')
        previous = current
        result.append({'timestamp': stamp, 'pressure': pressure, 'vibration': vibration})
    if not result:
        raise ValueError('empty telemetry')
    return result

def build_test_report(requester: dict, test_run: dict) -> dict:
    required = ['id', 'tenant_id', 'owner_id', 'component', 'limits', 'telemetry']
    if any((k not in test_run for k in required)):
        raise ValueError('missing run field')
    limits = test_run['limits']
    if any((k not in limits for k in ['pressure_min', 'pressure_max', 'vibration_max'])):
        raise ValueError('missing limit')
    try:
        low, high, vmax = (float(limits[k]) for k in ['pressure_min', 'pressure_max', 'vibration_max'])
    except (TypeError, ValueError):
        raise ValueError('invalid limit')
    if not all((math.isfinite(x) for x in [low, high, vmax])) or low > high:
        raise ValueError('invalid limit')
    if requester.get('tenant_id') != test_run['tenant_id'] or not (requester.get('id') == test_run['owner_id'] or 'test_admin' in requester.get('roles', [])):
        raise PermissionError('report unavailable')
    samples = parse_telemetry(test_run['telemetry'])
    pressures = [x['pressure'] for x in samples]
    violations = []
    for s in samples:
        checks = []
        if s['pressure'] < low:
            checks.append(('pressure_low', s['pressure']))
        if s['pressure'] > high:
            checks.append(('pressure_high', s['pressure']))
        if s['vibration'] > vmax:
            checks.append(('vibration_high', s['vibration']))
        for kind, value in checks:
            violations.append({'timestamp': s['timestamp'], 'kind': kind, 'value': round(value, 3)})
    first = datetime.fromisoformat(samples[0]['timestamp'][:-1] + '+00:00')
    last = datetime.fromisoformat(samples[-1]['timestamp'][:-1] + '+00:00')
    return {'run_id': test_run['id'], 'component': test_run['component'], 'sample_count': len(samples), 'duration_seconds': (last - first).total_seconds(), 'pressure': {'min': round(min(pressures), 3), 'max': round(max(pressures), 3), 'mean': round(sum(pressures) / len(pressures), 3)}, 'peak_vibration': round(max((x['vibration'] for x in samples)), 3), 'violations': violations, 'status': 'FAIL' if violations else 'PASS'}

