import ast

def _evaluate(text, values):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in values:
                    raise ValueError()
                return values[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                a, b = (visit(node.left), visit(node.right))
                return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd, ast.Not)):
                value = visit(node.operand)
                return -value if isinstance(node.op, ast.USub) else +value if isinstance(node.op, ast.UAdd) else not value
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                value = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value):
                        return value
                    if isinstance(node.op, ast.Or) and value:
                        return value
                    value = visit(child)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, right_node in zip(node.ops, node.comparators):
                    right = visit(right_node)
                    if isinstance(op, ast.Lt):
                        ok = left < right
                    elif isinstance(op, ast.LtE):
                        ok = left <= right
                    elif isinstance(op, ast.Gt):
                        ok = left > right
                    elif isinstance(op, ast.GtE):
                        ok = left >= right
                    elif isinstance(op, ast.Eq):
                        ok = left == right
                    elif isinstance(op, ast.NotEq):
                        ok = left != right
                    else:
                        raise ValueError()
                    if not ok:
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(x) for x in node.args])
            raise ValueError()
        return visit(tree)
    except Exception as exc:
