import subprocess

def summarize_release_artifacts(paths: list[str], page: int=1, page_size: int=10) -> dict:
    if not isinstance(paths, list) or any((not isinstance(path, str) or not path for path in paths)):
        raise ValueError('paths must contain non-empty strings')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    artifacts = []
    for path in paths:
        result = subprocess.run(['wc', '-c', '--', path], capture_output=True, text=True)
        if result.returncode != 0:
            raise FileNotFoundError(path)
        text = result.stdout.strip()
        try:
            count = int(text.split(None, 1)[0])
        except (ValueError, IndexError):
            raise FileNotFoundError(path)
        artifacts.append({'path': path, 'bytes': count})
    artifacts.sort(key=lambda item: (-item['bytes'], item['path']))
    total = sum((item['bytes'] for item in artifacts))
    pages = (len(artifacts) + page_size - 1) // page_size if artifacts else 0
    start = (page - 1) * page_size
    return {'total_bytes': total, 'artifacts': artifacts, 'page': page, 'page_size': page_size, 'pages': pages, 'page_items': artifacts[start:start + page_size]}

