def fetch_docket_summary(api_url: str, matter_ids: list[str], since: str, until: str, token: str) -> list[dict]:
    if any((not isinstance(x, str) or not x for x in matter_ids)):
        raise ValueError('invalid matter id')
    try:
        start = datetime.date.fromisoformat(since)
        end = datetime.date.fromisoformat(until)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if start > end:
        raise ValueError('invalid range')
    if not matter_ids:
        return []
    response = requests.get(api_url, params={'matter_ids': ','.join(matter_ids), 'since': since, 'until': until}, headers={'Authorization': 'Bearer ' + token}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    try:
        payload = response.json()
        events = payload['events']
    except (TypeError, KeyError, ValueError):
        raise ValueError('invalid response')
    wanted = set(matter_ids)
    grouped = {}
    for event in events:
        try:
            matter = event['matter_id']
            kind = event['event_type']
            date_text = event['occurred_on']
            hours = event['hours']
            event_date = datetime.date.fromisoformat(date_text)
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid event')
        if not isinstance(matter, str) or not isinstance(kind, str) or (not isinstance(date_text, str)):
            raise ValueError('invalid event')
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or (not math.isfinite(hours)) or (hours < 0):
            raise ValueError('invalid event')
        if matter not in wanted or not start <= event_date <= end:
            continue
        grouped.setdefault(matter, []).append((event_date, kind, hours))
    result = []
    for matter, items in grouped.items():
        latest = max(items, key=lambda item: item[0])
        result.append({'matter_id': matter, 'event_count': len(items), 'total_hours': round(sum((x[2] for x in items)), 2), 'latest_event': latest[1]})
    result.sort(key=lambda item: (-item['total_hours'], item['matter_id']))
    return result

