import os
import tempfile


def write_file(directory, name, lines):
    path = os.path.join(directory, name)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join("line" for _ in range(lines)))
        if lines:
            handle.write("\n")
    return path


def test_empty_input():
    assert summarize_daily_reports([]) == {
        "total_files": 0,
        "total_lines": 0,
        "page": 1,
        "page_size": 10,
        "items": [],
    }


def test_counts_and_shooting_day_rounding():
    with tempfile.TemporaryDirectory() as directory:
        first = write_file(directory, "morning.txt", 40)
        second = write_file(directory, "afternoon.txt", 41)
        result = summarize_daily_reports([first, second])
        assert result["total_files"] == 2
        assert result["total_lines"] == 81
        assert result["items"] == [
            {"name": "afternoon.txt", "lines": 41, "shooting_days": 2},
            {"name": "morning.txt", "lines": 40, "shooting_days": 1},
        ]


def test_filtering_and_tie_ordering():
    with tempfile.TemporaryDirectory() as directory:
        zulu = write_file(directory, "zulu.txt", 12)
        alpha = write_file(directory, "alpha.txt", 12)
        small = write_file(directory, "small.txt", 11)
        result = summarize_daily_reports([zulu, small, alpha], minimum_lines=12)
        assert result["total_files"] == 2
        assert result["total_lines"] == 24
        assert [item["name"] for item in result["items"]] == ["alpha.txt", "zulu.txt"]


def test_pagination_is_applied_after_sorting():
    with tempfile.TemporaryDirectory() as directory:
        paths = [write_file(directory, name, lines) for name, lines in [
            ("a.txt", 5), ("b.txt", 30), ("c.txt", 20), ("d.txt", 10)
        ]]
        result = summarize_daily_reports(paths, page=2, page_size=2)
        assert result["page"] == 2
        assert result["page_size"] == 2
        assert result["total_files"] == 4
        assert result["total_lines"] == 65
        assert result["items"] == [
            {"name": "d.txt", "lines": 10, "shooting_days": 1},
            {"name": "a.txt", "lines": 5, "shooting_days": 1},
        ]


def test_page_beyond_results_is_empty():
    with tempfile.TemporaryDirectory() as directory:
        path = write_file(directory, "only.txt", 3)
