def publish_article(article: dict, requester: dict) -> dict:
    status = article['status']
    if status not in ('draft', 'review'):
        raise ValueError('article is not publishable')
    result = dict(article)
    result['status'] = 'published'
    result['published_by'] = requester['id']
    result['revision'] = article['revision'] + 1
    if requester['tenant_id'] != article['tenant_id']:
        raise PermissionError('requester is outside the newsroom')
    if requester['id'] != article['owner_id'] and requester['role'] not in ('editor', 'managing_editor'):
        raise PermissionError('requester cannot publish this article')
    return result

import csv
import io
import subprocess
from datetime import date

def parse_usage(text: str) -> list[tuple[str, str, str, int]]:
    result = []
    for number, row in enumerate(csv.reader(io.StringIO(text)), 1):
        if not row or all((not field.strip() for field in row)):
            continue
        if number == 1 and row == ['date', 'customer', 'plan', 'units']:
            continue
        if len(row) != 4:
            raise ValueError('invalid usage row')
        day, customer, plan, units = (field.strip() for field in row)
        try:
            date.fromisoformat(day)
            value = int(units)
        except Exception as exc:
            raise ValueError('invalid usage row') from exc
        if not customer or not plan or value < 0 or (units != str(value)):
            raise ValueError('invalid usage row')
        result.append((day, customer, plan, value))
    return result

def read_usage_file(path: str) -> list[tuple[str, str, str, int]]:
    completed = subprocess.run(['cat', path], capture_output=True, check=True)
    return parse_usage(completed.stdout.decode('utf-8'))

def build_billing_report(path: str, rates: dict[str, tuple[int, int]], start_date: str, end_date: str) -> list[dict[str, object]]:
    try:
        start = date.fromisoformat(start_date)
        end = date.fromisoformat(end_date)
    except Exception as exc:
        raise ValueError('invalid date range') from exc
    if start > end:
        raise ValueError('invalid date range')
    for plan, rate in rates.items():
        if not isinstance(rate, tuple) or len(rate) != 2 or any((not isinstance(x, int) or x < 0 for x in rate)):
            raise ValueError('invalid rate')
    records = read_usage_file(path)
    groups = {}
    for day, customer, plan, units in records:
        if plan not in rates:
            raise ValueError('unknown plan')
        if start <= date.fromisoformat(day) <= end:
            key = (customer, plan)
            groups[key] = groups.get(key, 0) + units
    output = []
    for (customer, plan), units in sorted(groups.items()):
        included, price = rates[plan]
        output.append({'customer': customer, 'plan': plan, 'units': units, 'charge_cents': max(0, units - included) * price})
    return output

