import requests

def fetch_delivery_summary(message_ids: list[str], api_key: str, since: int | None=None) -> list[dict]:
    if not isinstance(message_ids, list):
        raise TypeError('message_ids must be a list')
    if any((not isinstance(x, str) for x in message_ids)):
        raise TypeError('message IDs must be strings')
    if any((not x for x in message_ids)):
        raise ValueError('message IDs must be non-empty')
    if len(set(message_ids)) != len(message_ids):
        raise ValueError('duplicate message ID')
    if not isinstance(api_key, str) or not api_key:
        raise ValueError('api_key must be non-empty')
    if since is not None and (isinstance(since, bool) or not isinstance(since, int) or since < 0):
        raise ValueError('invalid since')
    if not message_ids:
        return []
    counts = {x: {'delivered': 0, 'failed': 0, 'pending': 0} for x in message_ids}
    page = 1
    while True:
        params = {'message_ids': ','.join(message_ids), 'page': page, 'limit': 100}
        if since is not None:
            params['since'] = since
        r = requests.get('https://messaging.example.com/v1/delivery-receipts', params=params, headers={'Authorization': 'Bearer ' + api_key})
        if r.status_code != 200:
            raise RuntimeError('delivery service error')
        data = r.json()
        for receipt in data.get('receipts', []):
            mid = receipt.get('message_id')
            timestamp = receipt.get('timestamp')
            status = receipt.get('status')
            if mid in counts and (since is None or timestamp >= since) and (status in counts[mid]):
                counts[mid][status] += 1
        if not data.get('next_page', False):
            break
        page += 1
    result = []
    for mid in message_ids:
        c = counts[mid]
        total = sum(c.values())
        result.append({'message_id': mid, **c, 'total': total, 'success_rate': round(c['delivered'] * 100 / total, 2) if total else 0.0})
    return sorted(result, key=lambda x: (-x['total'], x['message_id']))

