def load_calendar_archive(base_dir: str, archive_path: str, member_names: list[str] | None=None, start_date: str | None=None, end_date: str | None=None) -> list[dict]:
    try:
        first = date.fromisoformat(start_date) if start_date is not None else None
        last = date.fromisoformat(end_date) if end_date is not None else None
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if first and last and (first > last):
        raise ValueError('invalid date range')
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    required = {'date', 'start_time', 'case_number', 'courtroom', 'status', 'attorney', 'duration_minutes'}
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        available = {x.filename for x in archive.infolist()}
        names = sorted((x for x in available if x.lower().endswith('.csv'))) if member_names is None else list(member_names)
        for name in names:
            if name not in available:
                raise KeyError(name)
            target = (base / name).resolve()
            try:
                target.relative_to(base)
            except ValueError as exc:
                raise ValueError('member outside base directory') from exc
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(name))
            with target.open(newline='', encoding='utf-8') as stream:
                reader = csv.DictReader(stream)
                if not reader.fieldnames or not required.issubset(reader.fieldnames):
                    raise ValueError('missing CSV columns')
                for row in reader:
                    if row['status'].strip().lower() != 'scheduled':
                        continue
                    try:
                        day = date.fromisoformat(row['date'].strip())
                        clock = time.fromisoformat(row['start_time'].strip())
                        duration = int(row['duration_minutes'].strip())
                    except (ValueError, TypeError) as exc:
                        raise ValueError('invalid calendar row') from exc
                    if duration <= 0 or (first and day < first) or (last and day > last):
                        if duration <= 0:
                            raise ValueError('invalid duration')
                        continue
                    result.append({'date': day.isoformat(), 'start_time': clock.strftime('%H:%M'), 'case_number': row['case_number'].strip(), 'courtroom': row['courtroom'].strip(), 'attorney': row['attorney'].strip(), 'duration_minutes': duration})
    return sorted(result, key=lambda x: (x['date'], x['start_time'], x['case_number'], x['courtroom']))

