import secrets
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
_RIGHTS = 'rwx'

def _path(value):
    if not isinstance(value, str) or not value.startswith('/'):
        raise ValueError('invalid path')
    parts = value.split('/')
    if any((part in ('', '.', '..') for part in parts[1:])):
        raise ValueError('invalid path')
    return value

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 3:
        raise ValueError('invalid record')
    return fields

def parse_acl(text: str) -> list[tuple[str, str, str]]:
    if not isinstance(text, str):
        raise ValueError('invalid text')
    result, seen = ([], set())
    for raw in text.splitlines():
        if not raw.strip():
            continue
        path, principal, rights = _fields(raw)
        _path(path)
        if not principal or any((char not in _RIGHTS for char in rights)):
            raise ValueError('invalid record')
        canonical = ''.join((char for char in _RIGHTS if char in rights))
        key = (path, principal)
        if key in seen:
            raise ValueError('duplicate record')
        seen.add(key)
        result.append((path, principal, canonical))
    return result

def permission_snapshot(records: list[tuple[str, str, str]], principal: str, paths: list[str]) -> dict[str, str]:
    if not principal:
        raise ValueError('invalid principal')
    checked = [_path(path) for path in paths]
    output = {}
    for target in checked:
        if target in output:
            continue
        applicable = [r for r in records if (r[1] == principal or r[1] == '*') and (target == r[0] or target.startswith(r[0] + '/'))]
        if not applicable:
            output[target] = ''
            continue
        depth = max((len(r[0].split('/')) for r in applicable))
        rights = {char for path, _, value in applicable if len(path.split('/')) == depth for char in value}
        output[target] = ''.join((char for char in _RIGHTS if char in rights))
    return output

def issue_invite(principal: str, collections: list[str], used_codes: set[str] | list[str]=()) -> dict[str, object]:
    if not principal:
        raise ValueError('invalid principal')
    selected = []
    for collection in collections:
        _path(collection)
        if collection not in selected:
            selected.append(collection)
    used = set(used_codes)
    while True:
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(20)))
        if code not in used:
            return {'code': code, 'principal': principal, 'collections': selected}

