import subprocess

def get_appointments(path: str, day: str, page: int, page_size: int) -> dict:
    try:
        parsed_day = datetime.date.fromisoformat(day)
    except (TypeError, ValueError):
        raise ValueError('invalid day')
    if parsed_day.isoformat() != day:
        raise ValueError('invalid day')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    completed = subprocess.run(['sort', '-t', ',', '-k', '2,2', '-k', '3,3', '-k', '1,1', path], capture_output=True, text=True, check=True)
    records = []
    for line in completed.stdout.splitlines():
        if not line:
            continue
        fields = line.split(',')
        if len(fields) != 5:
            raise ValueError('malformed record')
        appointment_id, record_day, time, office, status = fields
        if record_day == day and status == 'CONFIRMED':
            records.append({'appointment_id': appointment_id, 'date': record_day, 'time': time, 'office': office, 'status': status})
    total = len(records)
    start = (page - 1) * page_size
    return {'total': total, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'appointments': records[start:start + page_size]}

