import string

def parse_registrations(text: str) -> list[dict]:
    records = []
    seen = set()
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in raw:
            if escaped:
                if char not in '\\|':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current).strip())
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current).strip())
        if len(fields) != 4:
            raise ValueError('wrong field count')
        name, email, session, dietary = fields
        if not name or not email or (not session):
            raise ValueError('empty field')
        if email.count('@') != 1 or any((ch.isspace() for ch in email)):
            raise ValueError('invalid email')
        key = email.casefold()
        if key in seen:
            raise ValueError('duplicate email')
        seen.add(key)
        records.append({'name': name, 'email': email, 'session': session, 'dietary': dietary or 'none'})
    return records

def create_invite_code(prefix: str='EVENT', length: int=10) -> str:
    if not isinstance(prefix, str) or not prefix or any((c not in string.ascii_uppercase + string.digits + '_' for c in prefix)):
