import os
import posixpath
import zipfile

def extract_audio_bundle(zip_path: str, destination: str, members: list[str] | None=None) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    with zipfile.ZipFile(zip_path) as archive:
        files = [info for info in archive.infolist() if not info.is_dir()]
        by_name = {}
        for info in files:
            key = info.filename.replace('\\', '/')
            key = posixpath.normpath(key)
            if key in ('', '.'):
                raise ValueError('invalid member name')
            by_name.setdefault(key, info)
        if members is None:
            chosen = files
        else:
            chosen = []
            for name in members:
                key = posixpath.normpath(name.replace('\\', '/'))
                if key in ('', '.'):
                    raise ValueError('invalid member name')
                if key not in by_name:
                    raise KeyError(name)
                chosen.append(by_name[key])
        result = []
        for info in chosen:
            key = posixpath.normpath(info.filename.replace('\\', '/'))
            target = os.path.realpath(os.path.join(destination, *key.split('/')))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('member outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            result.append(key)
        return sorted(result)

def rental_totals(events: list[dict], rates: dict[str, int]) -> list[dict]:
    for value in rates.values():
        if isinstance(value, bool) or not isinstance(value, int) or value < 0:
            raise ValueError('invalid rate')
    totals = {}
    for event in events:
        minutes = event.get('minutes')
        fmt = event.get('format')
        if isinstance(minutes, bool) or not isinstance(minutes, int) or minutes <= 0 or (fmt not in rates):
            raise ValueError('invalid event')
        renter = event['renter']
        item = totals.setdefault(renter, [0, 0])
        item[0] += minutes
        item[1] += minutes * rates[fmt]
    result = [{'renter': name, 'minutes': value[0], 'cents': value[1]} for name, value in totals.items()]
    return sorted(result, key=lambda item: (-item['cents'], item['minutes'], item['renter']))

