from solution import build_event_roster
import hashlib
import hmac
import json
import math
import os
from unittest.mock import patch
import pytest

def expected_signature(body, key):
    raw = json.dumps(body, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf-8')
    return hmac.new(key.encode('utf-8'), raw, hashlib.sha256).hexdigest()

def test_config_key_takes_precedence_over_environment():
    records = [{'name': 'Mina Lee', 'congregation': 'Central', 'status': 'confirmed', 'donation': 4.2}]
    with patch.dict(os.environ, {'EVENT_REGISTRATION_KEY': 'environment-key'}, clear=False):
        result = build_event_roster(records, {'registration_signing_key': 'config-key'})
    body = {'total': 1, 'total_donation': 4.2, 'congregations': [{'name': 'Central', 'count': 1, 'donation': 4.2, 'attendees': ['Mina Lee']}]}
    assert result['signature'] == expected_signature(body, 'config-key')

def test_empty_input_has_zero_totals():
    with patch.dict(os.environ, {'EVENT_REGISTRATION_KEY': 'empty-key'}, clear=False):
        result = build_event_roster([])
    body = {'total': 0, 'total_donation': 0, 'congregations': []}
    assert result == {**body, 'signature': expected_signature(body, 'empty-key')}

def test_rounding_is_applied_to_total_and_groups():
    records = [{'name': 'A One', 'congregation': 'Main', 'status': 'confirmed', 'donation': 0.105}, {'name': 'B Two', 'congregation': 'Main', 'status': 'confirmed', 'donation': 0.105}]
    with patch.dict(os.environ, {'EVENT_REGISTRATION_KEY': 'round-key'}, clear=False):
        result = build_event_roster(records)
    assert result['total_donation'] == 0.21
    assert result['congregations'][0]['donation'] == 0.21

def test_invalid_records_raise_value_error():
    bad_records = [[{'name': '', 'congregation': 'Main', 'status': 'confirmed', 'donation': 1}], [{'name': 'A', 'congregation': 'Main', 'status': 'unknown', 'donation': 1}], [{'name': 'A', 'congregation': 'Main', 'status': 'confirmed', 'donation': -1}], [{'name': 'A', 'congregation': 'Main', 'status': 'confirmed', 'donation': True}], [{'name': 'A', 'congregation': 'Main', 'status': 'confirmed'}], ['not a record']]
    with patch.dict(os.environ, {'EVENT_REGISTRATION_KEY': 'validation-key'}, clear=False):
        for records in bad_records:
            with pytest.raises(ValueError):
                build_event_roster(records)

def test_nonfinite_donations_are_rejected():
    with patch.dict(os.environ, {'EVENT_REGISTRATION_KEY': 'finite-key'}, clear=False):
        for value in (math.inf, -math.inf, math.nan):
            with pytest.raises(ValueError):
                build_event_roster([{'name': 'A Person', 'congregation': 'Main', 'status': 'confirmed', 'donation': value}])

