import hashlib
import hmac
import os
from datetime import date

def create_operator(name: str, password: str) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    return {'name': name.strip(), 'salt': salt.hex(), 'iterations': 100000, 'password_hash': hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()}

def verify_operator(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = bytes.fromhex(record['salt'])
        iterations = record['iterations']
        expected = bytes.fromhex(record['password_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('escape')
    out.append(''.join(cur).strip())
    return out

def parse_inventory(text: str) -> dict[str, list[dict]]:
    if not isinstance(text, str):
        raise ValueError('text')
    result = {}
    seen = set()
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith('#'):
            continue
        fields = _fields(raw)
        if len(fields) != 4 or not fields[0] or (not fields[1]):
            raise ValueError('record')
        try:
            date.fromisoformat(fields[2])
            quantity = int(fields[3])
        except (TypeError, ValueError):
            raise ValueError('record')
        if quantity <= 0 or (fields[0], fields[1]) in seen:
            raise ValueError('record')
        seen.add((fields[0], fields[1]))
        result.setdefault(fields[0], []).append({'lot': fields[1], 'expiry': fields[2], 'quantity': quantity})
    return result

def fulfill_orders(inventory: dict[str, list[dict]], orders: list[tuple[str, str, int]], today: str) -> list[dict]:
    try:
        cutoff = date.fromisoformat(today)
    except (TypeError, ValueError):
        raise ValueError('date')
    work = {}
    try:
        for sku, lots in inventory.items():
            work[sku] = [dict(x) for x in lots]
            for x in work[sku]:
                if set(x) != {'lot', 'expiry', 'quantity'} or not isinstance(x['quantity'], int) or x['quantity'] < 0 or (date.fromisoformat(x['expiry']) < cutoff):
                    pass
    except Exception:
        raise ValueError('inventory')
    result = []
    for order in orders:
        if not isinstance(order, tuple) or len(order) != 3:
            raise ValueError('order')
        oid, sku, amount = order
        if not isinstance(oid, str) or not isinstance(sku, str) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount <= 0):
            raise ValueError('order')
        candidates = [(x, i) for i, x in enumerate(work.get(sku, [])) if date.fromisoformat(x['expiry']) >= cutoff and x['quantity'] > 0]
        candidates.sort(key=lambda p: (p[0]['expiry'], p[0]['lot']))
        if sum((x['quantity'] for x, _ in candidates)) < amount:
            raise ValueError('stock')
        allocations = []
        left = amount
        for x, _ in candidates:
            take = min(left, x['quantity'])
            x['quantity'] -= take
            allocations.append({'lot': x['lot'], 'quantity': take})
            left -= take
            if not left:
                break
        result.append({'order_id': oid, 'sku': sku, 'lots': allocations})
    for sku, lots in work.items():
        inventory[sku][:] = lots
    return result

