    for ch in line:
        if escaped:
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur).strip())
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('escape')
    out.append(''.join(cur).strip())
    return out

