from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def parse_time_entries(text: str) -> list[dict]:
    required = ['matter_id', 'date', 'attorney', 'hours', 'rate', 'narrative']
    rows = list(csv.reader(io.StringIO(text)))
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or (rows[0] != required and set(rows[0]) != set(required)):
        raise ValueError('invalid header')
    if len(rows[0]) != 6 or set(rows[0]) != set(required):
        raise ValueError('invalid header')
    pos = {x: rows[0].index(x) for x in required}
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        try:
            d = row[pos['date']].strip()
            date.fromisoformat(d)
            matter = row[pos['matter_id']].strip()
            attorney = row[pos['attorney']].strip()
            hours = float(row[pos['hours']].strip())
            rate = float(row[pos['rate']].strip())
        except Exception as e:
            raise ValueError('invalid row') from e
        if not matter or not attorney or hours < 0 or (rate < 0):
            raise ValueError('invalid row')
        result.append({'matter_id': matter, 'date': d, 'attorney': attorney, 'hours': hours, 'rate': rate, 'narrative': row[pos['narrative']].strip()})
    return result

def _money(value):
    return float(Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

def summarize_matter(entries: list[dict], matter_id: str) -> dict:
    chosen = [(i, e) for i, e in enumerate(entries) if e['matter_id'] == matter_id]
    if not chosen:
        raise KeyError(matter_id)
    ordered = sorted(chosen, key=lambda p: (p[1]['date'], p[1]['attorney'], p[0]))
    by = {}
    copied = []
    for _, e in ordered:
        x = dict(e)
        x['amount'] = _money(Decimal(str(e['hours'])) * Decimal(str(e['rate'])))
        copied.append(x)
        a = by.setdefault(e['attorney'], {'hours': 0.0, 'amount': 0.0})
        a['hours'] += e['hours']
        a['amount'] += x['amount']
    for a in by:
        by[a]['hours'] = _money(by[a]['hours'])
        by[a]['amount'] = _money(by[a]['amount'])
    return {'matter_id': matter_id, 'total_hours': _money(sum((e['hours'] for _, e in chosen))), 'total_amount': _money(sum((x['amount'] for x in copied))), 'by_attorney': dict(sorted(by.items())), 'entries': copied}

def extract_billing_archive(archive_path: str, destination: str) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    found = set()
    result = []
    with zipfile.ZipFile(archive_path) as z:
        for info in z.infolist():
            name = info.filename
            if name.endswith('/'):
                continue
            if not name or os.path.isabs(name):
                raise ValueError('invalid member path')
            target = os.path.realpath(os.path.join(destination, *name.split('/')))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid member path')
            if name in found:
                raise ValueError('duplicate member')
            found.add(name)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with z.open(info) as src, open(target, 'wb') as dst:
                dst.write(src.read())
            result.append(name)
    return sorted(result)

