        if len(fields) != 4:
            raise ValueError('fields')
        site, depth, mass, mineral = fields
        site, mineral = (site.strip(), mineral.strip())
        try:
            d, m = (float(depth.strip()), float(mass.strip()))
        except (TypeError, ValueError):
            raise ValueError('number')
        if not site or not mineral or (not math.isfinite(d)) or (not math.isfinite(m)) or (d < 0) or (m <= 0):
            raise ValueError('value')
        result.append({'site': site, 'depth': d, 'mass': m, 'mineral': mineral})
    return result

def summarize_sites(records: list[dict], window: int) -> list[dict]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window')
    if not isinstance(records, list):
        raise ValueError('records')
    if not records:
        return []
    checked = []
    for r in records:
        if not isinstance(r, dict) or not isinstance(r.get('site'), str) or (not r['site']):
            raise ValueError('record')
        if not isinstance(r.get('mineral'), str) or not r['mineral'] or isinstance(r.get('day'), bool) or (not isinstance(r.get('day'), int)):
            raise ValueError('record')
        try:
            depth, mass = (float(r['depth']), float(r['mass']))
        except (KeyError, TypeError, ValueError):
            raise ValueError('record')
        if not math.isfinite(depth) or not math.isfinite(mass) or depth < 0 or (mass <= 0):
            raise ValueError('record')
        checked.append((r['site'], depth, mass, r['mineral'], r['day']))
    cutoff = max((x[4] for x in checked)) - window + 1
    groups = {}
    for site, depth, mass, mineral, day in checked:
        if day >= cutoff:
            groups.setdefault(site, []).append((depth, mass, mineral))
    result = []
    for site, values in groups.items():
        result.append({'site': site, 'count': len(values), 'total_mass': round(sum((x[1] for x in values)), 3), 'average_depth': round(sum((x[0] for x in values)) / len(values), 3), 'minerals': sorted({x[2] for x in values})})
    return sorted(result, key=lambda x: (-x['count'], -x['total_mass'], x['site']))

