import hashlib
import hmac

def verify_passport_update(payload: bytes, signature: str, key: bytes) -> bool:
    if not isinstance(payload, bytes) or not isinstance(key, bytes) or (not isinstance(signature, str)):
        return False
    if not signature.startswith('sha256='):
        return False
    supplied = signature[7:]
    if len(supplied) != 64 or any((ch not in '0123456789abcdef' for ch in supplied)):
        return False
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, supplied)

