import ast

def select_waitlist(applicants: list[dict], expression: str, limit: int) -> list[str]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    try:
        tree = ast.parse(expression, mode='eval').body
    except (SyntaxError, TypeError):
        raise ValueError('invalid expression')
    names = {'income', 'household_size', 'priority', 'years_waited'}

    def evaluate(node, values):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return values[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (evaluate(node.left, values), evaluate(node.right, values))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.Not, ast.UAdd, ast.USub):
            value = evaluate(node.operand, values)
            return not value if isinstance(node.op, ast.Not) else +value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            result = evaluate(node.values[0], values)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result) or (isinstance(node.op, ast.Or) and result):
                    return result
                result = evaluate(child, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, part in zip(node.ops, node.comparators):
                right = evaluate(part, values)
                if not {ast.Lt: left < right, ast.LtE: left <= right, ast.Eq: left == right, ast.NotEq: left != right, ast.GtE: left >= right, ast.Gt: left > right}.get(type(op), False):
                    return False
                left = right
            return True
        raise ValueError('invalid expression')
    result = []
    for applicant in applicants:
        values = {key: applicant[key] for key in names}
        try:
            selected = evaluate(tree, values)
        except (KeyError, NameError, TypeError, ZeroDivisionError):
            raise ValueError('invalid expression')
        if selected:
            result.append(applicant)
    result.sort(key=lambda item: (-item['priority'], -item['years_waited'], item['income'], item['id']))
    return [item['id'] for item in result[:limit]]

