def build_webinar_report(registrations: list[dict[str, object]], config: dict[str, str], page: int=1, page_size: int=20) -> dict[str, object]:
    if not isinstance(registrations, list):
        raise ValueError('registrations must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    if not isinstance(config, dict) or not config.get('WEBINAR_API_TOKEN'):
        raise ValueError('WEBINAR_API_TOKEN is required')
    groups = {}
    for record in registrations:
        if not isinstance(record, dict) or not all((k in record for k in ('webinar_id', 'attendee', 'status', 'fee'))):
            raise ValueError('invalid registration')
        webinar_id = record['webinar_id']
        attendee = record['attendee']
        status = record['status']
        fee = record['fee']
        if not isinstance(webinar_id, str) or not webinar_id or (not isinstance(attendee, str)) or (not attendee):
            raise ValueError('invalid registration')
        if status not in ('confirmed', 'cancelled', 'pending'):
            raise ValueError('invalid status')
        if isinstance(fee, bool) or not isinstance(fee, (int, float)) or fee < 0:
            raise ValueError('invalid fee')
        if status == 'confirmed':
