from solution import parse_signed_notification, build_eta_report
import hashlib
import hmac
import json
import pytest


def signed(payload, key):
    digest = hmac.new(key, payload.encode("utf-8"), hashlib.sha256).hexdigest()
    return "sha256=" + digest


def test_parse_valid_notification_and_unicode():
    key = b"route-key"
    payload = json.dumps({"delivery_id": "D7", "customer": "Zoë", "events": [{"timestamp": "2025-03-01T09:04:05Z", "eta_minutes": 18, "status": "scheduled"}]}, ensure_ascii=False)
    result = parse_signed_notification(payload, signed(payload, key), key)
    assert result == {"delivery_id": "D7", "customer": "Zoë", "events": [{"timestamp": "2025-03-01T09:04:05Z", "eta_minutes": 18, "status": "scheduled"}]}


def test_rejects_bad_signature_forms():
    key = b"k"
    payload = '{}'
    good = signed(payload, key)
    for value in ["", "sha256", "sha256=", "sha256=" + "A" * 64, "sha256=" + "0" * 63, "sha1=" + good[7:]]:
        with pytest.raises(ValueError, match="^invalid signature$"):
            parse_signed_notification(payload, value, key)


def test_signature_is_checked_before_invalid_json():
    with pytest.raises(ValueError, match="^invalid signature$"):
        parse_signed_notification("not json", "sha256=" + "0" * 64, b"different")


