    if not isinstance(events, list) or not 1 <= len(events) <= 100:
        raise ValueError('invalid payload')
    for event in events:
        if not isinstance(event, dict) or not isinstance(event.get('timestamp'), str) or set(event) != {'timestamp', 'eta_minutes', 'status'}:
            raise ValueError('invalid payload')
        try:
            dt = datetime.datetime.strptime(event['timestamp'], '%Y-%m-%dT%H:%M:%SZ')
        except (ValueError, TypeError):
            raise ValueError('invalid payload')
        if dt.strftime('%Y-%m-%dT%H:%M:%SZ') != event['timestamp']:
            raise ValueError('invalid payload')
        if isinstance(event['eta_minutes'], bool) or not isinstance(event['eta_minutes'], int) or (not 0 <= event['eta_minutes'] <= 1440) or (event['status'] not in {'scheduled', 'delayed', 'arrived', 'cancelled'}):
            raise ValueError('invalid payload')
    return notification

def parse_signed_notification(payload: str, signature: str, key: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(key, bytes)):
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        value = json.loads(payload)
    except (UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    return _validate(value)

