    try:
        _validate(notification)
    except Exception:
        raise ValueError('invalid payload')
    ordered = sorted(enumerate(notification['events']), key=lambda x: (x[1]['timestamp'], x[0]))
    groups = {}
    for _, event in ordered:
        hour = event['timestamp'][:13] + ':00:00Z'
        groups.setdefault(hour, []).append(event)
    hourly = []
    for hour, events in sorted(groups.items()):
        counts = {}
        for event in events:
            counts[event['status']] = counts.get(event['status'], 0) + 1
        hourly.append({'hour': hour, 'count': len(events), 'average_eta': round(sum((e['eta_minutes'] for e in events)) / len(events), 2), 'minimum_eta': min((e['eta_minutes'] for e in events)), 'maximum_eta': max((e['eta_minutes'] for e in events)), 'status_counts': {k: counts[k] for k in sorted(counts)}})
    current = ordered[-1][1]
    return {'delivery_id': notification['delivery_id'], 'customer': notification['customer'], 'current': {k: current[k] for k in ('timestamp', 'eta_minutes', 'status')}, 'hourly': hourly}

