import datetime

def parse_timestamp(value: str) -> int:
    if not isinstance(value, str):
        raise ValueError('invalid timestamp')
    try:
        if len(value) != 16 or value[10] != 'T' or value[13] != ':':
            raise ValueError
        d = datetime.datetime.strptime(value, '%Y-%m-%dT%H:%M')
        epoch = datetime.datetime(1970, 1, 1)
        return int((d - epoch).total_seconds() // 60)
    except (ValueError, TypeError, OverflowError):
        raise ValueError('invalid timestamp')

def schedule_interviews(requester: dict, requests: list[dict], slots: list[dict]) -> list[dict]:
    required = {'id', 'tenant', 'owner_id', 'candidate_id', 'candidate_availability', 'duration', 'priority', 'created_at'}
    seen = set()
    parsed = []
    for r in requests:
        if not isinstance(r, dict) or not required <= set(r):
            raise ValueError('invalid request')
        if r['id'] in seen:
            raise ValueError('duplicate request')
        seen.add(r['id'])
        if not isinstance(r['duration'], int) or isinstance(r['duration'], bool) or r['duration'] <= 0:
            raise ValueError('invalid duration')
        created = parse_timestamp(r['created_at'])
        av = []
        for pair in r['candidate_availability']:
            if not isinstance(pair, (list, tuple)) or len(pair) != 2:
                raise ValueError('invalid availability')
            a, b = (parse_timestamp(pair[0]), parse_timestamp(pair[1]))
            if b <= a:
                raise ValueError('invalid availability')
            av.append((a, b))
        if not isinstance(r['priority'], int):
            raise ValueError('invalid priority')
        parsed.append((r, created, av))
    parsed.sort(key=lambda x: (-x[0]['priority'], x[1], x[0]['id']))
    prepared = []
    for s in slots:
        if not isinstance(s, dict) or not {'interviewer_id', 'tenant', 'start', 'end'} <= set(s):
            raise ValueError('invalid slot')
        a, b = (parse_timestamp(s['start']), parse_timestamp(s['end']))
        if b <= a:
            raise ValueError('invalid slot')
        prepared.append((s, a, b))
    used = []
    result = []
    for r, _, av in parsed:
        if requester.get('tenant') != r['tenant'] or not set(requester.get('roles', [])) & {'scheduler', 'admin'} or ('admin' not in requester.get('roles', []) and requester.get('id') != r['owner_id']):
            raise PermissionError('not authorized')
        choices = []
        for s, start, end in prepared:
