def initialize_database(conn: sqlite3.Connection) -> None:
    conn.execute('PRAGMA foreign_keys = ON')
    conn.executescript('CREATE TABLE IF NOT EXISTS workers (worker_id INTEGER PRIMARY KEY, name TEXT NOT NULL); CREATE TABLE IF NOT EXISTS shifts (shift_id INTEGER PRIMARY KEY, worker_id INTEGER NOT NULL REFERENCES workers(worker_id), work_date TEXT NOT NULL, start_time TEXT NOT NULL, end_time TEXT NOT NULL, minutes INTEGER NOT NULL)')
    conn.commit()

def _valid_date(value):
    try:
        return datetime.strptime(value, '%Y-%m-%d').date()
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def _minutes(value):
    try:
        parsed = datetime.strptime(value, '%H:%M')
    except (TypeError, ValueError):
        raise ValueError('invalid time')
    if parsed.strftime('%H:%M') != value:
        raise ValueError('invalid time')
    return parsed.hour * 60 + parsed.minute

def add_shift(conn, worker_id, worker_name, work_date, start_time, end_time):
    if not isinstance(worker_id, int) or isinstance(worker_id, bool) or worker_id <= 0 or (not isinstance(worker_name, str)) or (not worker_name):
        raise ValueError('invalid worker')
    _valid_date(work_date)
    start = _minutes(start_time)
    end = _minutes(end_time)
    if end <= start:
        raise ValueError('invalid interval')
    conn.execute('INSERT INTO workers(worker_id, name) VALUES(?, ?) ON CONFLICT(worker_id) DO UPDATE SET name=excluded.name', (worker_id, worker_name))
    conn.execute('INSERT INTO shifts(worker_id, work_date, start_time, end_time, minutes) VALUES(?, ?, ?, ?, ?)', (worker_id, work_date, start_time, end_time, end - start))
    conn.commit()

def labor_report(conn, search='', start_date=None, end_date=None, sort_by='worker', descending=False):
    if sort_by not in {'worker', 'total_minutes', 'shift_count', 'last_date'}:
        raise ValueError('invalid sort')
    if start_date is not None:
        _valid_date(start_date)
    if end_date is not None:
        _valid_date(end_date)
    if start_date and end_date and (start_date > end_date):
        raise ValueError('invalid range')
    term = str(search).replace('\\', '\\\\').replace('%', '\\%').replace('_', '\\_')
    clauses = ["LOWER(w.name) LIKE LOWER(?) ESCAPE '\\'"]
    params = ['%' + term + '%']
    if start_date is not None:
        clauses.append('s.work_date >= ?')
        params.append(start_date)
    if end_date is not None:
        clauses.append('s.work_date <= ?')
        params.append(end_date)
    order = {'worker': 'LOWER(w.name)', 'total_minutes': 'total_minutes', 'shift_count': 'shift_count', 'last_date': 'last_date'}[sort_by]
    direction = ' DESC' if descending else ' ASC'
    sql = 'SELECT w.worker_id, w.name, SUM(s.minutes) AS total_minutes, COUNT(*) AS shift_count, COUNT(DISTINCT s.work_date) AS days, MAX(s.work_date) AS last_date FROM workers w JOIN shifts s ON s.worker_id=w.worker_id WHERE ' + ' AND '.join(clauses) + ' GROUP BY w.worker_id, w.name ORDER BY ' + order + direction + ', w.worker_id ASC'
    rows = conn.execute(sql, params).fetchall()
    return [{'worker_id': r[0], 'name': r[1], 'total_minutes': r[2], 'shift_count': r[3], 'days': r[4], 'last_date': r[5], 'average_minutes': r[2] / r[3]} for r in rows]

