    for plan in selected_plans:
        if not isinstance(plan, str):
            raise TypeError('plan names must be strings')
        name = plan.strip()
        if not name:
            raise ValueError('plan name cannot be empty')
        if name in seen:
            raise ValueError('duplicate plan')
        seen.add(name)
        if name not in monthly_costs:
            raise ValueError('missing plan cost')
        cost = monthly_costs[name]
        if not isinstance(cost, (int, float)) or isinstance(cost, bool):
            raise TypeError('cost must be numeric')
        if not math.isfinite(cost) or cost < 0:
            raise ValueError('cost is invalid')
