    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'application_id': application_id, 'applicant': applicant, 'months': months, 'total_benefit': sum((x['benefit'] for x in months)), 'pin_salt': salt.hex(), 'pin_hash': digest.hex()}

