import hashlib
import hmac
import os

def index_microscopy_images(records: list[dict], page: int, page_size: int, min_quality: float=0.0) -> dict:
    if page < 1 or page_size < 1 or (not 0 <= min_quality <= 100):
        raise ValueError('invalid pagination or quality threshold')
    token = os.environ.get('MICROSCOPY_API_TOKEN')
    if token is None:
        raise ValueError('MICROSCOPY_API_TOKEN is not configured')
    indexed = []
    for record in records:
        required = {'id', 'specimen', 'stain', 'quality', 'focus', 'captured_at'}
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('malformed record')
        if not all((isinstance(record[k], str) and record[k] for k in ('id', 'specimen', 'stain', 'captured_at'))):
            raise ValueError('malformed record')
        quality = record['quality']
        focus = record['focus']
        if isinstance(quality, bool) or isinstance(focus, bool) or (not isinstance(quality, (int, float))) or (not isinstance(focus, (int, float))) or (not 0 <= quality <= 100) or (not 0 <= focus <= 100):
            raise ValueError('invalid measurement')
        if quality < min_quality:
            continue
        score = round(quality * 0.7 + focus * 0.3, 3)
        text = f"{record['id']}|{score}|{record['specimen']}".encode()
        digest = hmac.new(token.encode(), text, hashlib.sha256).hexdigest()
        indexed.append({'id': record['id'], 'specimen': record['specimen'], 'stain': record['stain'], 'score': score, 'signature': digest})
    indexed.sort(key=lambda item: (-item['score'], item['id']))
    counts = {}
    for item in indexed:
        counts[item['specimen']] = counts.get(item['specimen'], 0) + 1
    groups = [{'specimen': name, 'count': count} for name, count in counts.items()]
    groups.sort(key=lambda item: (-item['count'], item['specimen']))
    start = (page - 1) * page_size
    return {'total': len(indexed), 'page': page, 'page_size': page_size, 'items': indexed[start:start + page_size], 'groups': groups}

