import ast
import operator
from datetime import datetime, timedelta
_NAMES = {'temp', 'rain', 'humidity', 'station_count'}
_FUNCS = {'min': min, 'max': max, 'round': round}
_BIN = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
_CMP = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body

        def ev(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and (not isinstance(n.value, complex)):
                return n.value
            if isinstance(n, ast.Name) and n.id in _NAMES and (n.id in variables):
                return variables[n.id]
            if isinstance(n, ast.BinOp) and type(n.op) in _BIN:
                return _BIN[type(n.op)](ev(n.left), ev(n.right))
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                v = ev(n.operand)
                return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                if isinstance(n.op, ast.And):
                    value = ev(n.values[0])
                    for x in n.values[1:]:
                        if not value:
                            return value
                        value = ev(x)
                    return value
                value = ev(n.values[0])
                for x in n.values[1:]:
                    if value:
                        return value
                    value = ev(x)
                return value
            if isinstance(n, ast.Compare):
                left = ev(n.left)
                for op, right_node in zip(n.ops, n.comparators):
                    right = ev(right_node)
                    if type(op) not in _CMP or not _CMP[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in _FUNCS) and (1 <= len(n.args) <= 2) and (not n.keywords):
                return _FUNCS[n.func.id](*(ev(x) for x in n.args))
            raise ValueError('invalid expression')
