import ast
import operator

def select_manifest(manifest: list[dict], rule: str, limit: int) -> list[str]:
    if limit < 0:
        raise ValueError('limit must not be negative')
    tree = ast.parse(rule, mode='eval').body
    names = {'mass_kg', 'hazard_score'}

    def ev(n, env):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)) and (not isinstance(n.value, complex)):
            return n.value
        if isinstance(n, ast.Name):
            if n.id not in names:
                raise NameError(n.id)
            return env[n.id]
        if isinstance(n, ast.BinOp) and type(n.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](ev(n.left, env), ev(n.right, env))
        if isinstance(n, ast.UnaryOp) and type(n.op) in {ast.UAdd, ast.USub, ast.Not}:
            value = ev(n.operand, env)
            return +value if isinstance(n.op, ast.UAdd) else -value if isinstance(n.op, ast.USub) else not value
        if isinstance(n, ast.BoolOp) and type(n.op) in {ast.And, ast.Or}:
            value = ev(n.values[0], env)
            for part in n.values[1:]:
                if isinstance(n.op, ast.And) and (not value) or (isinstance(n.op, ast.Or) and value):
                    return value
                value = ev(part, env)
            return value
        if isinstance(n, ast.Compare):
            left = ev(n.left, env)
            for op, right_node in zip(n.ops, n.comparators):
                right = ev(right_node, env)
                if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in {'min', 'max', 'round'}):
            args = [ev(a, env) for a in n.args]
            return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
        raise ValueError('unsupported expression')
    chosen = [row for row in manifest if ev(tree, {'mass_kg': row['mass_kg'], 'hazard_score': row['hazard_score']})]
    chosen.sort(key=lambda row: (-row['hazard_score'], row['id']))
    return [row['id'] for row in chosen[:limit]]

