def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body

        def run(n):
            if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
                return n.value
            if isinstance(n, ast.Name) and n.id in variables:
                return variables[n.id]
            if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
                v = run(n.operand)
                return +v if isinstance(n.op, ast.UAdd) else -v if isinstance(n.op, ast.USub) else not v
            if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
                a, b = (run(n.left), run(n.right))
                return a + b if isinstance(n.op, ast.Add) else a - b if isinstance(n.op, ast.Sub) else a * b if isinstance(n.op, ast.Mult) else a / b
            if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
                value = run(n.values[0])
                for x in n.values[1:]:
                    if isinstance(n.op, ast.And):
                        if not value:
                            return value
                    elif value:
                        return value
                    value = run(x)
                return value
            if isinstance(n, ast.Compare):
                left = run(n.left)
                for op, right_node in zip(n.ops, n.comparators):
                    right = run(right_node)
                    good = left < right if isinstance(op, ast.Lt) else left <= right if isinstance(op, ast.LtE) else left > right if isinstance(op, ast.Gt) else left >= right if isinstance(op, ast.GtE) else left == right if isinstance(op, ast.Eq) else left != right if isinstance(op, ast.NotEq) else False
                    if not good:
                        return False
                    left = right
                return True
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
                args = [run(x) for x in n.args]
                return {'min': min, 'max': max, 'round': round}[n.func.id](*args)
            raise ValueError()
        return run(tree)
    except Exception as e:
        if isinstance(e, ValueError):
            raise
        raise ValueError() from e

def rank_players(records: list[dict], rule: str, window: int=2) -> list[dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError()
    groups = {}
    for pos, rec in enumerate(records):
        try:
            key = (rec['timestamp'], pos)
