def canonical_bid(bid: dict) -> str:
    if not isinstance(bid, dict):
        raise TypeError('bid must be a dictionary')
    for key in ('bid_id', 'vendor', 'amount', 'delivery_days'):
        if key not in bid:
            raise ValueError('missing bid field')
    if not isinstance(bid['bid_id'], str) or not bid['bid_id']:
        raise ValueError('invalid bid_id')
    if not isinstance(bid['vendor'], str) or not bid['vendor']:
        raise ValueError('invalid vendor')
    if isinstance(bid['amount'], bool) or not isinstance(bid['amount'], (int, float)) or (not math.isfinite(bid['amount'])) or (bid['amount'] < 0):
        raise ValueError('invalid amount')
    if isinstance(bid['delivery_days'], bool) or not isinstance(bid['delivery_days'], int) or bid['delivery_days'] < 0:
        raise ValueError('invalid delivery_days')
    return json.dumps({'bid_id': bid['bid_id'], 'vendor': bid['vendor'], 'amount': bid['amount'], 'delivery_days': bid['delivery_days']}, ensure_ascii=False, separators=(',', ':'))

def rank_bids(bids: list[dict]) -> list[dict]:
    if not isinstance(bids, list):
        raise TypeError('bids must be a list')
    chosen = {}
    for bid in bids:
        canonical_bid(bid)
        key = bid['vendor'].casefold()
        old = chosen.get(key)
        if old is None or (bid['amount'], bid['delivery_days'], bid['bid_id']) < (old['amount'], old['delivery_days'], old['bid_id']):
            chosen[key] = bid
    ordered = sorted(chosen.values(), key=lambda x: (x['amount'], x['delivery_days'], x['vendor'].casefold(), x['bid_id']))
    return [dict(bid, rank=i) for i, bid in enumerate(ordered, 1)]

def certify_bids(bids: list[dict], config: dict | None=None) -> list[dict]:
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary')
    key = config.get('signing_key') if config is not None and 'signing_key' in config else os.environ.get('PROCUREMENT_SIGNING_KEY')
    if not isinstance(key, str) or not key:
        raise ValueError('missing signing key')
    result = []
    for bid in rank_bids(bids):
        signature = hmac.new(key.encode('utf-8'), canonical_bid(bid).encode('utf-8'), hashlib.sha256).hexdigest()
        result.append(dict(bid, signature=signature))
    return result

