def plan_maintenance_route(requester: dict, jobs: list[dict], service_date: str, page: int=1, page_size: int=20) -> dict:
    requester_id = requester['id']
    tenant_id = requester['tenant_id']
    roles = requester['roles']
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    try:
        date.fromisoformat(service_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    selected = []
    for item in jobs:
        for key in ('id', 'tenant_id', 'owner_id', 'service_date', 'status', 'priority', 'start_window', 'duration_minutes', 'zone', 'address'):
            item[key]
        if not isinstance(item['priority'], int) or isinstance(item['priority'], bool) or (not isinstance(item['duration_minutes'], int)) or isinstance(item['duration_minutes'], bool):
