        if allowed and item['service_date'] == service_date and (item['status'] == 'scheduled'):
            selected.append(item)
    selected.sort(key=lambda x: (-x['priority'], x['start_window'], x['id']))
    total = len(selected)
    zones = {}
    for item in selected:
        zones[item['zone']] = zones.get(item['zone'], 0) + item['duration_minutes']
    start = (page - 1) * page_size
    output_jobs = []
    for item in selected[start:start + page_size]:
        output_jobs.append({'id': item['id'], 'zone': item['zone'], 'priority': item['priority'], 'start_window': item['start_window'], 'duration_minutes': item['duration_minutes'], 'address': item['address']})
    return {'service_date': service_date, 'page': page, 'page_size': page_size, 'total': total, 'total_pages': (total + page_size - 1) // page_size, 'total_minutes': sum((x['duration_minutes'] for x in selected)), 'zones': {key: zones[key] for key in sorted(zones)}, 'jobs': output_jobs}

