import hmac
import os
import re

def annotate_corpus(text: str, config: dict[str, str] | None=None) -> dict:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    if config is not None and (not isinstance(config, dict)):
        raise TypeError('config must be a dictionary or None')
    key = config.get('api_token') if config is not None else None
    if key is None:
        key = os.environ.get('CORPUS_API_TOKEN')
    if not key:
        raise ValueError('CORPUS_API_TOKEN is required')
    tokens = re.findall("[A-Za-z]+(?:'[A-Za-z]+)?|[.,!?;:]", text)
    annotations = []
    for token in tokens:
        lower = token.lower()
        if token in '.,!?;:':
            label = 'PUNCT'
        elif lower in {'the', 'a', 'an'}:
            label = 'DET'
        elif lower.endswith('ing'):
            label = 'VERB'
        else:
            label = 'OTHER'
        annotations.append({'token': token, 'label': label})
    payload = '\n'.join(tokens).encode()
    signature = hmac.new(str(key).encode(), payload, hashlib.sha256).hexdigest()
    return {'tokens': tokens, 'annotations': annotations, 'signature': signature}

