import math
from decimal import Decimal, ROUND_HALF_UP

def _check_records(records):
    if not isinstance(records, list):
        raise ValueError('records')
    required = {'member_id', 'plan', 'visits', 'monthly_fee', 'active'}
    for item in records:
        if not isinstance(item, dict) or set(item) != required:
            raise ValueError('record')
        if not isinstance(item['member_id'], str) or not item['member_id']:
            raise ValueError('member_id')
        if not isinstance(item['plan'], str) or not item['plan']:
            raise ValueError('plan')
        if isinstance(item['visits'], bool) or not isinstance(item['visits'], int) or item['visits'] < 0:
            raise ValueError('visits')
        if isinstance(item['monthly_fee'], bool) or not isinstance(item['monthly_fee'], (int, float)) or (not math.isfinite(item['monthly_fee'])) or (item['monthly_fee'] < 0):
            raise ValueError('monthly_fee')
        if not isinstance(item['active'], bool):
            raise ValueError('active')

def pack_memberships(records: list[dict]) -> bytes:
    _check_records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_memberships(blob: bytes, min_visits: int=0, page: int=1, page_size: int=10) -> dict:
    if isinstance(min_visits, bool) or not isinstance(min_visits, int) or min_visits < 0:
        raise ValueError('min_visits')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size')
    try:
        data = json.loads(blob.decode('utf-8'))
        _check_records(data)
    except Exception as exc:
        raise ValueError('blob') from exc
    selected = [x for x in data if x['active'] and x['visits'] >= min_visits]
    selected.sort(key=lambda x: (-x['visits'], x['member_id']))
    groups = {}
    for item in selected:
        group = groups.setdefault(item['plan'], [0, 0, Decimal('0')])
        group[0] += 1
        group[1] += item['visits']
        group[2] += Decimal(str(item['monthly_fee']))
    plans = [{'plan': name, 'members': value[0], 'visits': value[1], 'revenue': float(value[2].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for name, value in sorted(groups.items())]
    total = len(selected)
    start = (page - 1) * page_size
    return {'members': selected[start:start + page_size], 'plans': plans, 'total_pages': (total + page_size - 1) // page_size, 'total_members': total}

