import hashlib
import hmac
import math
import os

def create_supplier(supplier_id: str, password: str) -> dict:
    if not isinstance(supplier_id, str) or not supplier_id.strip():
        raise ValueError('invalid supplier ID')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    stored = salt.hex() + '$' + value.hex()
    return {'supplier_id': supplier_id, 'password_hash': stored, 'surveys': []}

def authenticate_supplier(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
