import hashlib
import hmac
import os

def hash_access_code(access_code: str) -> str:
    if not isinstance(access_code, str) or not access_code:
        raise ValueError('invalid access code')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_access_code(access_code: str, stored_value: str) -> bool:
    if not isinstance(access_code, str) or not isinstance(stored_value, str):
        return False
    try:
        salt_text, digest_text = stored_value.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_listings(listings: list[dict], city: str | None=None, min_price: float | None=None, max_price: float | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
