    if response.status_code != 200:
        raise RuntimeError('request failed with status ' + str(response.status_code))
    try:
        payload = response.json()
    except Exception as exc:
        raise ValueError('invalid response JSON') from exc
    if not isinstance(payload, dict) or not isinstance(payload.get('events'), list):
        raise ValueError('response must contain an events list')
    return payload['events']

def _event_time(value):
    if not isinstance(value, str) or not value.endswith('Z'):
        raise ValueError('invalid timestamp')
    try:
        return datetime.fromisoformat(value[:-1] + '+00:00')
    except ValueError as exc:
        raise ValueError('invalid timestamp') from exc

def summarize_events(events: list[dict]) -> list[dict]:
    groups = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a dictionary')
        required = ('candidate_id', 'timestamp', 'type', 'severity', 'duration_seconds')
        if any((key not in event for key in required)):
            raise ValueError('missing event field')
        candidate = event['candidate_id']
        event_type = event['type']
        severity = event['severity']
        duration = event['duration_seconds']
        if not isinstance(candidate, str) or not isinstance(event_type, str):
            raise ValueError('invalid text field')
        if isinstance(severity, bool) or not isinstance(severity, int) or severity < 0:
            raise ValueError('invalid severity')
        if isinstance(duration, bool) or not isinstance(duration, (int, float)) or duration < 0:
            raise ValueError('invalid duration')
        parsed = _event_time(event['timestamp'])
        groups.setdefault(candidate, []).append((parsed, event_type, severity, duration))
    result = []
    for candidate, items in groups.items():
        items.sort(key=lambda item: item[0])
        counts = {}
        for _, event_type, _, _ in items:
            counts[event_type] = counts.get(event_type, 0) + 1
        clusters = 1
        for previous, current in zip(items, items[1:]):
            if (current[0] - previous[0]).total_seconds() > 60:
                clusters += 1
        total_severity = sum((item[2] for item in items))
        result.append({'candidate_id': candidate, 'event_count': len(items), 'by_type': {key: counts[key] for key in sorted(counts)}, 'total_duration_seconds': sum((item[3] for item in items)), 'max_severity': max((item[2] for item in items)), 'cluster_count': clusters, 'risk_score': total_severity + 2 * (clusters - 1)})
    result.sort(key=lambda item: (-item['risk_score'], item['candidate_id']))
    return result

