import hashlib
import hmac
import json
import math

def summarize_crossing_manifest(manifest: str, signature: str, secret: str, page: int=1, page_size: int=2) -> dict:
    expected = hmac.new(secret.encode('utf-8'), manifest.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        data = json.loads(manifest)
        records = data['records']
        if not isinstance(records, list):
            raise ValueError
        seen = set()
        clean = []
        for item in records:
            if not isinstance(item, dict):
                raise ValueError
            if set(item) != {'id', 'country', 'direction', 'weight_kg', 'timestamp'}:
                raise ValueError
            identifier = item['id']
            country = item['country']
            direction = item['direction']
            weight = item['weight_kg']
            timestamp = item['timestamp']
            if not isinstance(identifier, str) or not identifier or identifier in seen:
                raise ValueError
            if not isinstance(country, str) or not country:
                raise ValueError
            if direction not in ('entry', 'exit'):
                raise ValueError
            if isinstance(weight, bool) or not isinstance(weight, (int, float)) or (not math.isfinite(weight)) or (weight < 0):
                raise ValueError
            if isinstance(timestamp, bool) or not isinstance(timestamp, int):
                raise ValueError
            seen.add(identifier)
            clean.append({'id': identifier, 'country': country, 'direction': direction, 'weight_kg': weight, 'timestamp': timestamp})
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeError):
        raise ValueError('invalid manifest')
    ordered = sorted(clean, key=lambda x: (x['timestamp'], x['id']))
    countries = {}
    for item in clean:
        counts = countries.setdefault(item['country'], {'entry': 0, 'exit': 0})
        counts[item['direction']] += 1
    countries = {key: countries[key] for key in sorted(countries)}
    start = (page - 1) * page_size
    return {'total_records': len(clean), 'total_weight_kg': round(sum((x['weight_kg'] for x in clean)), 2), 'by_country': countries, 'records': ordered[start:start + page_size]}

