import hashlib
import os

def _digest(password, salt):
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000).hex()

def register_player(campaign: dict, player_id: str, password: str, scores: list[int]) -> None:
    if not isinstance(player_id, str):
        raise TypeError('player_id must be a string')
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not player_id or not password:
        raise ValueError('empty value')
    if not isinstance(scores, list) or any((isinstance(x, bool) or not isinstance(x, int) or x < 0 for x in scores)):
        raise ValueError('invalid scores')
    players = campaign.setdefault('players', {})
    if player_id in players:
        raise ValueError('player already exists')
    salt = os.urandom(16)
    players[player_id] = {'salt': salt.hex(), 'digest': _digest(password, salt), 'scores': list(scores)}

def verify_player(campaign: dict, player_id: str, password: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    players = campaign.get('players', {})
    record = players.get(player_id)
    if record is None:
        return False
    return _digest(password, bytes.fromhex(record['salt'])) == record['digest']

def leaderboard(campaign: dict, window: int=3) -> list[tuple[str, int, int]]:
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError('window must be positive')
    result = []
    for player_id, record in campaign.get('players', {}).items():
        scores = record['scores']
        if not scores:
            result.append((player_id, 0, -1))
            continue
        width = min(window, len(scores))
        best = sum(scores[:width])
        start = 0
        current = best
        for i in range(width, len(scores)):
            current += scores[i] - scores[i - width]
            candidate = i - width + 1
            if current > best:
                best, start = (current, candidate)
        result.append((player_id, best, start))
    return sorted(result, key=lambda item: (-item[1], item[0]))

