    requester = {"id": "u1", "tenant_id": "t1", "roles": ["inspector"]}
    result = summarize_inspections(requester, [])
    assert result == {
        "total": 0,
        "average_severity": 0.0,
        "total_duration_hours": 0.0,
        "by_species": [],
        "items": [],
    }


def test_summary_grouping_rounding_and_sorting():
    requester = {"id": "u1", "tenant_id": "t1", "roles": ["inspector"]}
    records = [
        {"id": "b", "tenant_id": "t1", "owner_id": "u1", "species": "zebra", "severity": 4, "duration_hours": 1.25},
        {"id": "a", "tenant_id": "t1", "owner_id": "u1", "species": "mouse", "severity": 8, "duration_hours": 2.125},
        {"id": "c", "tenant_id": "t1", "owner_id": "u1", "species": "mouse", "severity": 8, "duration_hours": 0.5},
        {"id": "d", "tenant_id": "t1", "owner_id": "u1", "species": "zebra", "severity": 2, "duration_hours": 3.0},
    ]
    result = summarize_inspections(requester, records)
    assert result["total"] == 4
    assert result["average_severity"] == 5.5
    assert result["total_duration_hours"] == 6.88
    assert result["by_species"] == [{"species": "mouse", "count": 2}, {"species": "zebra", "count": 2}]
    assert [x["id"] for x in result["items"]] == ["a", "c", "b", "d"]


