    requester = {"id": "u1", "tenant_id": "north", "roles": []}
    records = [
        {"id": "x", "tenant_id": "south", "owner_id": "u9", "species": "cat", "severity": 10, "duration_hours": 9},
        {"id": "y", "tenant_id": "north", "owner_id": "u1", "species": "dog", "severity": 3, "duration_hours": 1},
    ]
    original = [dict(r) for r in records]
    result = summarize_inspections(requester, records)
    assert result["total"] == 1
    assert result["items"] == [records[1]]
    assert records == original


