    requester = {"id": "u1", "tenant_id": "t", "roles": ["supervisor"]}
    records = [
        {"id": "c", "tenant_id": "t", "owner_id": "u2", "species": "rat", "severity": 5, "duration_hours": 1},
        {"id": "a", "tenant_id": "t", "owner_id": "u2", "species": "rat", "severity": 5, "duration_hours": 1},
        {"id": "b", "tenant_id": "t", "owner_id": "u2", "species": "rat", "severity": 6, "duration_hours": 1},
    ]
