import csv
import datetime
import subprocess

def read_intake(path: str) -> list[tuple[str, str, int, int, str]]:
    try:
        completed = subprocess.run(['wc', '-l', path], capture_output=True, text=True, check=True)
        int(completed.stdout.split()[0])
        with open(path, newline='', encoding='utf-8') as handle:
            rows = list(csv.reader(handle))
    except (OSError, ValueError, IndexError, subprocess.SubprocessError) as exc:
        raise ValueError('invalid intake file') from exc
    result = []
    seen = set()
    for row in rows:
        if not row or all((not field.strip() for field in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid row')
        shelter, household, beds_text, priority_text, arrival = [field.strip() for field in row]
        if not shelter or not household or household in seen:
            raise ValueError('invalid household')
        try:
            beds = int(beds_text)
            priority = int(priority_text)
            datetime.datetime.strptime(arrival, '%H:%M')
        except ValueError as exc:
            raise ValueError('invalid row') from exc
        if beds <= 0 or len(arrival) != 5:
            raise ValueError('invalid row')
        seen.add(household)
        result.append((shelter, household, beds, priority, arrival))
    return result

def assign_beds(entries: list[tuple[str, str, int, int, str]], capacities: dict[str, int]) -> dict[str, list[str] | list[str]]:
    remaining = {}
    for shelter, capacity in capacities.items():
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0:
            raise ValueError('invalid capacity')
        remaining[shelter] = capacity
    ordered = sorted(entries, key=lambda item: (-item[3], item[4], item[1]))
    result = {shelter: [] for shelter in capacities}
    result['waitlist'] = []
    seen = set()
    for shelter, household, beds, priority, arrival in ordered:
        if household in seen:
            raise ValueError('duplicate household')
        seen.add(household)
        if shelter in remaining and remaining[shelter] >= beds:
            result[shelter].append(household)
            remaining[shelter] -= beds
        else:
            result['waitlist'].append(household)
    return result

def format_report(allocation: dict[str, list[str] | list[str]]) -> str:
    if 'waitlist' not in allocation:
        raise ValueError('missing waitlist')
    lines = []
    for shelter, households in allocation.items():
        if shelter == 'waitlist':
            continue
        lines.append(f"{shelter}: {(','.join(households) if households else '-')}")
    waitlist = allocation['waitlist']
    lines.append(f"WAITLIST: {(','.join(waitlist) if waitlist else '-')}")
    return '\n'.join(lines)

