def dump_alerts(records: list[dict]) -> bytes:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not isinstance(record.get('sensor_id'), str):
            raise ValueError('invalid sensor_id')
        if not _number(record.get('magnitude')) or not _number(record.get('depth_km')):
            raise ValueError('invalid measurement')
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

def summarize_alerts(blob: bytes, min_magnitude: float=0.0, max_depth_km: float=1000.0, offset: int=0, limit: int=10) -> list[dict]:
    if not isinstance(blob, bytes) or not _number(min_magnitude) or (not _number(max_depth_km)):
        raise ValueError('invalid arguments')
    if not isinstance(offset, int) or isinstance(offset, bool) or (not isinstance(limit, int)) or isinstance(limit, bool) or (offset < 0) or (limit < 0):
        raise ValueError('invalid page')
    try:
        records = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('sensor_id'), str) or (not _number(record.get('magnitude'))) or (not _number(record.get('depth_km'))):
            raise ValueError('invalid record')
        if record['magnitude'] >= min_magnitude and record['depth_km'] <= max_depth_km:
