import datetime
import decimal
import subprocess

def calculate_fund_nav(paths: list[str], as_of: str) -> dict[str, object]:
    try:
        cutoff = datetime.date.fromisoformat(as_of)
    except ValueError:
        raise ValueError('invalid as_of')
    records = {}
    for path_index, path in enumerate(paths):
        result = subprocess.run(['sort', '-t,', '-k1,1', path], capture_output=True, text=True, check=True)
        for line in result.stdout.splitlines():
            if not line.strip():
                continue
            fields = line.split(',')
            if len(fields) != 4:
                raise ValueError('invalid record')
            date_text, symbol, shares_text, price_text = fields
            try:
                record_date = datetime.date.fromisoformat(date_text)
                shares = decimal.Decimal(shares_text)
                price = decimal.Decimal(price_text)
            except (ValueError, decimal.InvalidOperation):
                raise ValueError('invalid record')
            if not symbol:
                raise ValueError('invalid record')
            if record_date <= cutoff:
                old = records.get(symbol)
                key = (record_date, path_index)
                if old is None or key >= old[0]:
                    records[symbol] = (key, shares, price)
    quantum = decimal.Decimal('0.01')
    positions = {}
    total = decimal.Decimal('0')
    for symbol in sorted(records):
        _, shares, price = records[symbol]
        value = (shares * price).quantize(quantum, rounding=decimal.ROUND_HALF_UP)
        positions[symbol] = format(value, '.2f')
        total += value
    return {'as_of': as_of, 'positions': positions, 'nav': format(total.quantize(quantum, rounding=decimal.ROUND_HALF_UP), '.2f')}

