import ast
import operator

def rank_guests(guests: list[dict], expression: str, minimum: float=0) -> list[dict]:
    tree = ast.parse(expression, mode='eval').body
    functions = {'min': min, 'max': max, 'round': round}

    def evaluate(node, names):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in names:
                return names[node.id]
            if node.id in functions:
                return functions[node.id]
            raise NameError(node.id)
        if isinstance(node, ast.BinOp):
            ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
            if type(node.op) not in ops:
                raise SyntaxError('unsupported operator')
            return ops[type(node.op)](evaluate(node.left, names), evaluate(node.right, names))
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, names)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp):
            result = evaluate(node.values[0], names)
            for child in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not result:
                        return result
                elif result:
                    return result
                result = evaluate(child, names)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, names)
            ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}
            for op, child in zip(node.ops, node.comparators):
                if type(op) not in ops:
                    raise SyntaxError('unsupported comparison')
                right = evaluate(child, names)
                if not ops[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(arg, names) for arg in node.args))
        raise SyntaxError('unsupported expression')
    scored = []
    for guest in guests:
        names = {'nights': guest['nights'], 'spend': guest['spend'], 'visits': guest['visits']}
        score = evaluate(tree, names)
        if isinstance(score, bool):
            score = int(score)
        if not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')
        if score >= minimum:
            scored.append((score, guest['name']))
    scored.sort(key=lambda item: (-item[0], item[1]))
    return [{'name': name, 'score': round(score, 2)} for score, name in scored]

