import re
import secrets
from decimal import Decimal, InvalidOperation, ROUND_DOWN
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _cents(value):
    try:
        number = Decimal(value)
    except (InvalidOperation, TypeError, ValueError):
        raise ValueError
    if not number.is_finite() or number < 0:
        raise ValueError
    scaled = number.quantize(Decimal('0.01'), rounding=ROUND_DOWN)
    if scaled != number:
        raise ValueError
    return int(scaled * 100)

def _permit(value):
    if not isinstance(value, str) or not value or re.fullmatch('[A-Z0-9-]+', value) is None:
        raise ValueError

def generate_collection_code(permit_id: str, amount: str) -> str:
    _permit(permit_id)
    cents = _cents(amount)
    suffix = ''.join((secrets.choice(_ALPHABET) for _ in range(8)))
    return f'PC-{permit_id}-{cents:08d}-{suffix}'

def summarize_permit_fees(entries: list[dict[str, str]], page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError
    totals = {}
    for entry in entries:
        if not isinstance(entry, dict) or not all((k in entry for k in ('permit_id', 'category', 'fee'))):
            raise ValueError
        _permit(entry['permit_id'])
        if not isinstance(entry['category'], str) or not entry['category'].strip():
            raise ValueError
        category = entry['category'].strip()
        totals[category] = totals.get(category, 0) + _cents(entry['fee'])
    ordered = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    pages = (len(ordered) + page_size - 1) // page_size
    start = (page - 1) * page_size
    selected = [{'category': name, 'cents': cents} for name, cents in ordered[start:start + page_size]]
    return {'total_cents': sum(totals.values()), 'categories': selected, 'page': page, 'page_size': page_size, 'pages': pages}

