from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def create_settlement_report(base_dir: str, filename: str, trades: list[dict[str, str]]) -> str:
    if not filename:
        raise ValueError('filename must not be empty')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, filename))
    try:
        if os.path.commonpath([base, target]) != base:
            raise ValueError('invalid output path')
    except ValueError:
        raise ValueError('invalid output path')
    totals = {}
    for trade in trades:
        if set(trade) != {'asset', 'side', 'quantity', 'price', 'fee'}:
            raise ValueError('invalid trade fields')
        asset = trade['asset']
        side = trade['side']
        if not asset or side not in ('BUY', 'SELL'):
            raise ValueError('invalid trade')
        try:
            quantity = Decimal(trade['quantity'])
            price = Decimal(trade['price'])
            fee = Decimal(trade['fee'])
        except (InvalidOperation, TypeError, ValueError):
            raise ValueError('invalid numeric value')
        if not quantity.is_finite() or not price.is_finite() or (not fee.is_finite()) or (quantity <= 0) or (price <= 0) or (fee < 0):
            raise ValueError('invalid numeric value')
        if asset not in totals:
            totals[asset] = [Decimal('0'), Decimal('0'), Decimal('0'), Decimal('0')]
        row = totals[asset]
        row[0 if side == 'BUY' else 1] += quantity
        row[2] += quantity * price
        row[3] += fee
    os.makedirs(os.path.dirname(target), exist_ok=True)
    q = Decimal('0.00000001')
    m = Decimal('0.01')
    with open(target, 'w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['asset', 'buy_quantity', 'sell_quantity', 'gross_quote', 'fees'])
        for asset in sorted(totals):
            buy, sell, gross, fees = totals[asset]
            writer.writerow([asset, format(buy.quantize(q, rounding=ROUND_HALF_UP), '.8f'), format(sell.quantize(q, rounding=ROUND_HALF_UP), '.8f'), format(gross.quantize(m, rounding=ROUND_HALF_UP), '.2f'), format(fees.quantize(m, rounding=ROUND_HALF_UP), '.2f')])
    return target

