    assert parse_membership_records(['M1|Museum\\|Friends|2|10', 'M2|C:\\\\Archive|1|5']) == [{'id': 'M1', 'name': 'Museum|Friends', 'visits': 2, 'points': 10}, {'id': 'M2', 'name': 'C:\\Archive', 'visits': 1, 'points': 5}]

