def qualify_broadband(path: str, technology: str, minimum_download: int, maximum_latency: int) -> list[tuple[str, int, int, int]]:
    result = subprocess.run(['grep', '-F', '--', technology, path], capture_output=True, text=True)
    if result.returncode == 2:
        raise OSError(result.stderr.strip() or 'unable to read input file')
    if result.returncode not in (0, 1):
        raise OSError(result.stderr.strip() or 'grep failed')
    offers = []
    for line in result.stdout.splitlines():
        if not line or line.startswith('#'):
            continue
        fields = line.split('\t')
        if len(fields) != 6:
            raise ValueError('invalid row')
        exchange, tech, down, up, latency, status = fields
        try:
            down_value = int(down)
            up_value = int(up)
            latency_value = int(latency)
        except ValueError as exc:
            raise ValueError('invalid numeric field') from exc
        if tech == technology and status == 'ACTIVE' and (down_value >= minimum_download) and (latency_value <= maximum_latency):
            offers.append((exchange, down_value, up_value, latency_value))
    return sorted(offers, key=lambda item: (-item[1], item[3], -item[2], item[0]))

def summarize_offers(offers: list[tuple[str, int, int, int]]) -> dict[str, dict[str, int | float]]:
    groups = {}
    for exchange, download, upload, latency in offers:
        groups.setdefault(exchange, []).append((download, latency))
    result = {}
    for exchange in sorted(groups):
        values = groups[exchange]
        result[exchange] = {'count': len(values), 'best_download': max((item[0] for item in values)), 'mean_latency': round(sum((item[1] for item in values)) / len(values), 2)}
    return result

