        if not re.fullmatch('[0-9]+', limit) or not re.fullmatch('[0-9]+', window):
            raise ValueError('number')
        pair = (int(limit), int(window))
        if pair[0] <= 0 or pair[1] <= 0:
            raise ValueError('range')
        result[key] = pair
    return result

def build_report(events: list[dict], rules: dict[str, tuple[int, int]], now: int) -> list[dict]:
    if isinstance(now, bool) or not isinstance(now, int):
        raise ValueError('now')
    checked = {}
    for key, pair in rules.items():
        if not isinstance(key, str) or not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError('rule')
        limit, window = pair
        if isinstance(limit, bool) or isinstance(window, bool) or (not isinstance(limit, int)) or (not isinstance(window, int)) or (limit <= 0) or (window <= 0):
