        report.append({'key': key, 'limit': limit, 'window': window, 'count': count, 'remaining': max(0, limit - count), 'reset_at': now + 1})
    return report

def export_report(events: list[dict], rules: dict[str, tuple[int, int]], now: int, destination: str) -> None:
    report = build_report(events, rules, now)
    directory = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(dir=directory)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=['key', 'limit', 'window', 'count', 'remaining', 'reset_at'])
            writer.writeheader()
            writer.writerows(report)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

