import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise NameError(node.id)
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
        value = _evaluate(node.values[0], names)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                return value
            value = _evaluate(item, names)
        return value
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, names)
            if not {ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(a, names) for a in node.args])
    raise ValueError('unsupported expression')

def rank_indicators(records: list[dict], expression: str) -> list[dict]:
    tree = ast.parse(expression, mode='eval').body
    scored = []
    for record in records:
        score = _evaluate(tree, record)
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')
        if score > 0:
            item = dict(record)
            item['score'] = score
            scored.append(item)
    scored.sort(key=lambda item: item['score'], reverse=True)
    return scored

