from decimal import Decimal, ROUND_HALF_UP
from datetime import date

def build_cleaning_report(requester: dict, property_id: str, bookings: list[dict], page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError('invalid pagination')
    matching = [b for b in bookings if b.get('property_id') == property_id]
    if matching:
        allowed = any((b.get('owner_id') == requester.get('id') for b in matching))
        allowed = allowed or (requester.get('role') in {'manager', 'admin'} and any((b.get('tenant_id') == requester.get('tenant_id') for b in matching)))
        if not allowed:
            raise PermissionError('not permitted')
    groups = {}
    total = Decimal('0')
    for b in matching:
        try:
            date.fromisoformat(b['checkout'])
            status = b['status']
            hours = Decimal(str(b['hours']))
            rate = Decimal(str(b['rate']))
            cleaner = b['cleaner_id']
            b['booking_id']
            b['owner_id']
            b['tenant_id']
        except (KeyError, ValueError, TypeError, ArithmeticError):
            raise ValueError('malformed booking')
        if status not in {'completed', 'cancelled'} or hours <= 0 or rate < 0:
            raise ValueError('malformed booking')
        if status == 'cancelled':
            continue
        cost = hours * rate
        if cleaner not in groups:
            groups[cleaner] = [0, Decimal('0'), Decimal('0')]
        groups[cleaner][0] += 1
        groups[cleaner][1] += hours
        groups[cleaner][2] += cost
        total += cost
    ordered = sorted(groups.items(), key=lambda x: (-x[1][2], x[0]))
    start = (page - 1) * page_size
    rows = [{'cleaner_id': k, 'booking_count': v[0], 'total_hours': float(v[1].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'total_cost': float(v[2].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for k, v in ordered[start:start + page_size]]
    return {'property_id': property_id, 'page': page, 'page_size': page_size, 'total_cleaners': len(groups), 'total_cost': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'rows': rows}

import copy
import os

def split_update_path(path: str) -> list[str]:
    if not isinstance(path, str):
        raise TypeError('path must be a string')
    if not path:
        raise ValueError('path must not be empty')
    parts = []
    current = []
    escaped = False
    for char in path:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '.':
            if not current:
                raise ValueError('path contains an empty component')
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped or not current:
        raise ValueError('invalid path')
    parts.append(''.join(current))
    return parts

def order_updates(updates: list[dict]) -> list[dict]:
    if not isinstance(updates, list):
        raise TypeError('updates must be a list')
    result = []
    seen = set()
    for update in updates:
        if not isinstance(update, dict):
            raise TypeError('each update must be a dictionary')
        if not isinstance(update.get('timestamp'), int) or isinstance(update.get('timestamp'), bool):
            raise TypeError('timestamp must be an integer')
        if not isinstance(update.get('sequence'), int) or isinstance(update.get('sequence'), bool):
            raise TypeError('sequence must be an integer')
        if not isinstance(update.get('path'), str):
            raise TypeError('path must be a string')
        if 'value' not in update:
            raise TypeError('value is required')
        key = (update['timestamp'], update['sequence'])
        if key in seen:
            raise ValueError('duplicate update ordering key')
        seen.add(key)
        result.append(update.copy())
    result.sort(key=lambda x: (x['timestamp'], x['sequence']))
    return result

def build_asset_update(asset_id: str, current: dict, updates: list[dict], config: dict) -> dict:
    if not isinstance(asset_id, str) or not asset_id:
        raise ValueError('asset_id must be a non-empty string')
    if not isinstance(current, dict) or not isinstance(config, dict):
        raise TypeError('current and config must be dictionaries')
    token = config.get('api_token', os.environ.get('DIGITAL_TWIN_TOKEN'))
    if not isinstance(token, str) or not token:
        raise ValueError('DIGITAL_TWIN_TOKEN is required')
    ordered = order_updates(updates)
    state = copy.deepcopy(current)
    total = 0
    numeric_count = 0
    for update in ordered:
        cursor = state
        parts = split_update_path(update['path'])
        for part in parts[:-1]:
            if part not in cursor:
                cursor[part] = {}
            elif not isinstance(cursor[part], dict):
                raise ValueError('intermediate path is not an object')
            cursor = cursor[part]
        cursor[parts[-1]] = copy.deepcopy(update['value'])
        value = update['value']
        if isinstance(value, (int, float)) and (not isinstance(value, bool)):
            total += value
            numeric_count += 1
    return {'asset_id': asset_id, 'state': state, 'summary': {'update_count': len(ordered), 'numeric_update_count': numeric_count, 'numeric_total': total}, 'headers': {'Authorization': 'Bearer ' + token, 'X-Update-Count': str(len(ordered))}}

