import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return '100000$' + salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, stored: str) -> bool:
    try:
        rounds_text, salt_text, digest_text = stored.split('$')
        rounds = int(rounds_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def add_episode(schedule: list[dict], title: str, day: str, start: int, duration: int, pin: str, stored_pin: str) -> list[dict]:
    if not verify_pin(pin, stored_pin):
        raise PermissionError('invalid operator PIN')
    days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    if day not in days or not title:
        raise ValueError('invalid episode')
    if start < 0 or start >= 1440 or duration <= 0 or (start + duration > 1440):
        raise ValueError('invalid time')
    for item in schedule:
        if item['day'] == day and start < item['start'] + item['duration'] and (item['start'] < start + duration):
            raise ValueError('overlapping episode')
    result = list(schedule) + [{'title': title, 'day': day, 'start': start, 'duration': duration}]
    return sorted(result, key=lambda item: (days.index(item['day']), item['start']))

