import csv
import io
import json
import os
from datetime import date
from decimal import Decimal, ROUND_HALF_UP
FIELDS = ['plant', 'cultivar', 'quantity', 'unit_price', 'received']

def _date(s):
    try:
        return date.fromisoformat(s)
    except Exception:
        raise ValueError('invalid date')

def _check(r):
    if set(r) != set(FIELDS) or not isinstance(r['plant'], str) or (not r['plant'].strip()) or (not isinstance(r['cultivar'], str)) or (not r['cultivar'].strip()):
        raise ValueError('invalid record')
    if type(r['quantity']) is not int or r['quantity'] < 0 or type(r['unit_price']) not in (int, float) or (r['unit_price'] < 0):
        raise ValueError('invalid record')
    _date(r['received'])
    return r

def parse_inventory(text):
    rows = list(csv.reader(io.StringIO(text)))
    if not rows or rows[0] != FIELDS:
        raise ValueError('invalid csv')
    out = []
    seen = set()
    for x in rows[1:]:
        if len(x) != 5:
            raise ValueError('invalid row')
        try:
            q = int(x[2].strip())
            p = Decimal(x[3].strip())
            if q < 0 or p < 0 or p.as_tuple().exponent < -2:
                raise ValueError
            _date(x[4].strip())
        except Exception:
            raise ValueError('invalid value')
        r = {'plant': x[0].strip(), 'cultivar': x[1].strip(), 'quantity': q, 'unit_price': float(p), 'received': x[4].strip()}
        _check(r)
        k = (r['plant'], r['cultivar'])
        if k in seen:
            raise ValueError('duplicate')
        seen.add(k)
        out.append(r)
    return out

def build_report(records, as_of):
    end = _date(as_of)
    groups = {}
    for r in records:
        _check(r)
        k = (r['plant'], r['cultivar'])
        g = groups.setdefault(k, [0, Decimal(0), None])
        g[0] += r['quantity']
        g[1] += Decimal(str(r['unit_price'])) * r['quantity']
        d = _date(r['received'])
        g[2] = d if g[2] is None or d < g[2] else g[2]
    out = []
    for (plant, cultivar), (q, total, first) in groups.items():
        avg = (total / q if q else Decimal(0)).quantize(Decimal('.01'), rounding=ROUND_HALF_UP)
        out.append({'plant': plant, 'cultivar': cultivar, 'quantity': q, 'average_unit_price': float(avg), 'age_days': (end - first).days})
    return sorted(out, key=lambda x: (x['plant'], -x['quantity'], x['cultivar']))

def _path(base, name):
    root = os.path.realpath(base)
    target = os.path.realpath(os.path.join(root, name))
    if os.path.commonpath([root, target]) != root:
        raise ValueError('invalid file name')
    return target

def save_inventory(base_dir, relative_name, records):
    for r in records:
        _check(r)
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(records, f, ensure_ascii=False, separators=(',', ':'))

def load_inventory(base_dir, relative_name):
    path = _path(base_dir, relative_name)
    with open(path, encoding='utf-8') as f:
        try:
            data = json.load(f)
        except Exception:
            raise ValueError('invalid json')
    if not isinstance(data, list):
        raise ValueError('invalid json')
    for r in data:
        _check(r)
    return data

