import hashlib
import hmac
import json

def process_payroll_submission(payload: str, signature: str, signing_key: str) -> dict | None:
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        return None
    try:
        data = json.loads(payload)
    except json.JSONDecodeError as exc:
        raise ValueError('invalid JSON') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    employee_id = data.get('employee_id')
    gross = data.get('gross_income')
    allowances = data.get('allowances')
    if not isinstance(employee_id, str) or not employee_id or isinstance(gross, bool) or (not isinstance(gross, int)) or (gross < 0) or isinstance(allowances, bool) or (not isinstance(allowances, int)) or (allowances < 0) or (allowances > gross):
        raise ValueError('invalid payroll fields')
    taxable = gross - allowances
    tax = min(taxable, 10000) // 10 + max(taxable - 10000, 0) // 5
    return {'employee_id': employee_id, 'taxable_income': taxable, 'tax': tax}

