def build_sensor_request(reading: dict, endpoint: str, config: dict | None=None) -> dict:
    if not isinstance(reading, dict):
        raise ValueError('reading must be a dictionary')
    required = ('sensor_id', 'temperature_c', 'ph', 'recorded_at')
    if any((key not in reading for key in required)):
        raise ValueError('reading is missing required fields')
    if not isinstance(reading['sensor_id'], str) or not reading['sensor_id']:
        raise ValueError('sensor_id must be a non-empty string')
    if not isinstance(reading['recorded_at'], str) or not reading['recorded_at']:
        raise ValueError('recorded_at must be a non-empty string')
    for key in ('temperature_c', 'ph'):
        if isinstance(reading[key], bool) or not isinstance(reading[key], (int, float)):
            raise ValueError(f'{key} must be numeric')
    if not isinstance(endpoint, str) or not endpoint.strip():
        raise ValueError('endpoint must be a non-empty string')
    token = config.get('api_token') if config is not None and 'api_token' in config else os.environ.get('AQUARIUM_API_TOKEN')
    if not token:
        raise ValueError('AQUARIUM_API_TOKEN is required')
    return {'endpoint': endpoint, 'headers': {'Content-Type': 'application/json', 'Authorization': f'Bearer {token}'}, 'body': json.dumps(reading, sort_keys=True, separators=(',', ':'), ensure_ascii=False)}

