    try:
        tree = ast.parse(rule, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError('invalid rule')
    allowed = {'min': min, 'max': max, 'round': round}
    allowed.update(variables)
    selected = []

    def get(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in allowed or (node.id not in variables and node.id in {'min', 'max', 'round'} is False):
                raise ValueError('unknown name')
            return allowed[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = get(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
            a, b = (get(node.left), get(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = get(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = get(part)
            return value
        if isinstance(node, ast.Compare):
            left = get(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = get(right_node)
                if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op), lambda a, b: (_ for _ in ()).throw(ValueError()))(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
            return allowed[node.func.id](*(get(a) for a in node.args))
        raise ValueError('unsupported rule')
    for record in records:
        scope = dict(variables)
        scope.update(record)
        allowed.update(scope)
        try:
            if get(tree):
                selected.append(record)
        except (NameError, TypeError, ZeroDivisionError):
            raise ValueError('invalid rule')
    speeds = [r['speed'] for r in selected]
    return {'ids': [r['id'] for r in selected], 'count': len(selected), 'total_volume': sum((r['volume'] for r in selected)), 'average_speed': round(sum(speeds) / len(speeds), 2) if speeds else None}

