import subprocess

def campaign_payouts(ledger_path: str, fee_bps: int, page: int=1, page_size: int=10) -> list[tuple[str, int]]:
    if not isinstance(fee_bps, int) or isinstance(fee_bps, bool) or (not 0 <= fee_bps <= 10000):
        raise ValueError('invalid fee')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    result = subprocess.run(['sort', '-t', '\t', '-k1,1', ledger_path], capture_output=True, text=True, check=True)
    totals = {}
    for line in result.stdout.splitlines():
        fields = line.split('\t')
        if len(fields) != 3:
            raise ValueError('malformed record')
        campaign, backer, amount_text = fields
        if not campaign or not backer or '\n' in campaign or ('\n' in backer):
            raise ValueError('invalid name')
        try:
            amount = int(amount_text)
        except ValueError as exc:
            raise ValueError('invalid amount') from exc
        if amount < 0:
            raise ValueError('invalid amount')
        totals[campaign] = totals.get(campaign, 0) + amount
    rows = []
    for campaign, gross in totals.items():
        payout = (gross * (10000 - fee_bps) + 5000) // 10000
        rows.append((campaign, payout))
    rows.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return rows[start:start + page_size]

