def parse_requests(data: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(data)))
    header = ['tenant', 'unit', 'priority', 'created', 'status', 'tags']
    if not rows or rows[0] != header:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 6:
            raise ValueError('invalid row')
        tenant, unit, priority, created, status, tags = row
        tenant, unit, status = (tenant.strip(), unit.strip(), status.strip())
        if not tenant or not unit or status not in {'open', 'closed'}:
            raise ValueError('invalid field')
        try:
            priority = int(priority.strip())
            created = int(created.strip())
        except ValueError:
            raise ValueError('invalid number')
        if not 1 <= priority <= 5 or created < 0:
            raise ValueError('invalid number')
        parsed_tags = []
        for tag in tags.split(';'):
            tag = tag.strip().lower()
            if tag and tag not in parsed_tags:
                parsed_tags.append(tag)
        result.append({'tenant': tenant, 'unit': unit, 'priority': priority, 'created': created, 'status': status, 'tags': parsed_tags})
    return result

def summarize_requests(data: str, as_of: int) -> list[dict]:
    if as_of < 0:
        raise ValueError('invalid date')
    groups = {}
    for item in parse_requests(data):
        if item['status'] != 'open' or item['created'] <= as_of - 30 or item['created'] > as_of:
            continue
        extra = sum(({'urgent': 3, 'water': 2, 'electrical': 2}.get(tag, 0) for tag in item['tags']))
        group = groups.setdefault(item['tenant'], {'tenant': item['tenant'], 'open_count': 0, 'score': 0, 'units': set()})
        group['open_count'] += 1
        group['score'] += item['priority'] + extra
        group['units'].add(item['unit'])
    result = []
    for group in groups.values():
        group['units'] = sorted(group['units'])
        result.append(group)
    return sorted(result, key=lambda item: (-item['score'], item['tenant']))

