import sqlite3
import math
import re

def list_rights(conn: sqlite3.Connection, county: str | None=None, status: str | None=None, sort_by: str='owner') -> list[dict]:
    columns = {'owner': 'p.owner', 'county': 'p.county', 'acres': 'p.acres', 'royalties': 'total_royalties', 'id': 'p.id'}
    if sort_by not in columns:
        raise ValueError('invalid sort field')
    conditions = []
    params = []
    if county is not None:
        conditions.append('p.county = ?')
        params.append(county)
    if status is not None:
        conditions.append('p.status = ?')
        params.append(status)
    where = ' WHERE ' + ' AND '.join(conditions) if conditions else ''
    sql = 'SELECT p.id, p.owner, p.county, p.acres, p.status, COALESCE(SUM(r.amount), 0.0) AS total_royalties, COUNT(DISTINCT r.month) AS royalty_months FROM parcels p LEFT JOIN royalties r ON r.parcel_id = p.id' + where + ' GROUP BY p.id, p.owner, p.county, p.acres, p.status ORDER BY ' + columns[sort_by] + ', p.id'
    rows = conn.execute(sql, params).fetchall()
    return [dict(id=r[0], owner=r[1], county=r[2], acres=float(r[3]), status=r[4], royalties=float(r[5]), royalty_months=r[6]) for r in rows]

def change_status(conn: sqlite3.Connection, parcel_ids: list[int], new_status: str) -> int:
    if not parcel_ids or new_status not in {'active', 'suspended', 'closed', 'pending'}:
        raise ValueError('invalid status or ids')
    ids = list(dict.fromkeys(parcel_ids))
    marks = ','.join(('?' for _ in ids))
    cur = conn.execute(f'UPDATE parcels SET status = ? WHERE id IN ({marks})', [new_status] + ids)
    conn.commit()
    return cur.rowcount

def parse_royalty_lines(text: str) -> list[tuple[int, str, float]]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        parts = [x.strip() for x in line.split('|')]
        if len(parts) != 3 or not parts[0].isdigit() or int(parts[0]) <= 0 or (not re.fullmatch('\\d{4}-\\d{2}', parts[1])) or (not 1 <= int(parts[1][5:]) <= 12):
            raise ValueError(f'invalid line {number}')
        try:
            amount = float(parts[2])
        except ValueError:
            raise ValueError(f'invalid line {number}')
        if not math.isfinite(amount) or amount < 0:
            raise ValueError(f'invalid line {number}')
        result.append((int(parts[0]), parts[1], amount))
    return result

