import hashlib
import hmac
import json
import os
from decimal import Decimal, ROUND_HALF_UP

def build_restock_manifest(parts: list[dict], page: int=1, page_size: int=50, config: dict | None=None) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    grouped = {}
    for record in parts:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        try:
            number = record['part_number']
            quantity = record['quantity']
            level = record['reorder_level']
            cost = record['unit_cost']
        except KeyError as exc:
            raise ValueError('invalid record') from exc
        if not isinstance(number, str) or not number or (not isinstance(quantity, int)) or isinstance(quantity, bool) or (quantity < 0) or (not isinstance(level, int)) or isinstance(level, bool) or (level < 0) or (not isinstance(cost, (int, float))) or isinstance(cost, bool) or (cost < 0):
            raise ValueError('invalid record')
        if number in grouped:
            old = grouped[number]
            if old['reorder_level'] != level or old['unit_cost'] != cost:
                raise ValueError('inconsistent duplicate record')
            old['quantity'] += quantity
        else:
            grouped[number] = {'quantity': quantity, 'reorder_level': level, 'unit_cost': cost}
    items = []
    for number, data in grouped.items():
        shortage = max(data['reorder_level'] - data['quantity'], 0)
        unit_cost = float(Decimal(str(data['unit_cost'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        value = float(Decimal(str(data['quantity'] * data['unit_cost'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        items.append({'part_number': number, 'quantity': data['quantity'], 'reorder_level': data['reorder_level'], 'unit_cost': unit_cost, 'inventory_value': value, 'shortage': shortage})
    items.sort(key=lambda item: (-item['shortage'], item['part_number']))
    total = len(items)
    start = (page - 1) * page_size
    selected = items[start:start + page_size]
    payload = {'page': page, 'page_size': page_size, 'total_items': total, 'items': selected}
    key = (config or {}).get('signing_key') if config is not None else None
    if key is None:
        key = os.environ.get('INVENTORY_SIGNING_KEY')
    if not key:
        raise ValueError('signing key is required')
    encoded = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

