def register_household(registry: dict, household_id: str, password: str, zone: str, pickup_days: list[str]) -> None:
    days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    if not isinstance(household_id, str) or not isinstance(zone, str) or (not isinstance(password, str)):
        raise ValueError('invalid value')
    key = household_id.strip()
    place = zone.strip()
    if not key or not place or len(password) < 4 or (not isinstance(pickup_days, list)) or (not pickup_days):
        raise ValueError('invalid value')
    chosen = set()
    for item in pickup_days:
        if not isinstance(item, str) or item.strip().title() not in days:
            raise ValueError('invalid day')
        chosen.add(item.strip().title())
    if key in registry:
        raise ValueError('duplicate')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    registry[key] = {'zone': place, 'pickup_days': [d for d in days if d in chosen], 'salt': salt, 'digest': digest}

def authenticate_household(registry: dict, household_id: str, password: str) -> bool:
    if not isinstance(password, str) or household_id not in registry:
        return False
    item = registry[household_id]
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), item['salt'], 100000)
    return hmac.compare_digest(digest, item['digest'])

def daily_collection_report(registry: dict, records: list[str], date: str) -> list[dict]:
    try:
        target = datetime.date.fromisoformat(date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    found = {}
    for line in records:
        try:
            fields = next(csv.reader([line]))
        except Exception:
            raise ValueError('invalid row')
        if len(fields) != 4:
            raise ValueError('invalid row')
        ident, stamp, weight_text, status = fields
        try:
            row_date = datetime.date.fromisoformat(stamp)
        except ValueError:
            raise ValueError('invalid date')
        if row_date != target:
            continue
        if ident not in registry:
            raise ValueError('unknown household')
        item = registry[ident]
        if target.strftime('%A') not in item['pickup_days']:
            continue
        try:
            weight = float(weight_text)
        except ValueError:
            raise ValueError('invalid weight')
        if not math.isfinite(weight) or weight < 0 or status not in ('collected', 'missed'):
            raise ValueError('invalid record')
        if ident in found:
            raise ValueError('duplicate')
        found[ident] = (item, weight, status)
    result = []
    for ident, (item, weight, status) in found.items():
        result.append({'household_id': ident, 'zone': item['zone'], 'collected_kg': round(weight if status == 'collected' else 0.0, 2), 'collected_count': int(status == 'collected'), 'missed_count': int(status == 'missed')})
    return sorted(result, key=lambda x: (x['zone'], -x['collected_kg'], x['household_id']))

