import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if pin == '':
        raise ValueError('pin must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored_hash, str)):
        return False
    try:
        iteration_text, salt_text, digest_text = stored_hash.split('$')
        iterations = int(iteration_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if iterations < 1 or not salt or (not expected):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def create_acknowledgment(donor_name: str, amount_cents: int, pin: str, stored_hash: str, donation_date: str) -> dict:
    if not isinstance(donor_name, str) or not isinstance(donation_date, str):
        raise TypeError('text fields must be strings')
    if donor_name == '' or donation_date == '':
        raise ValueError('text fields must not be empty')
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int):
        raise TypeError('amount_cents must be an integer')
    if amount_cents < 0:
        raise ValueError('amount_cents must not be negative')
    if not verify_pin(pin, stored_hash):
        raise ValueError('incorrect pin')
    dollars, cents = divmod(amount_cents, 100)
    message = f'Thank you, {donor_name}, for your donation of ${dollars}.{cents:02d} on {donation_date}.'
    return {'donor_name': donor_name, 'amount_cents': amount_cents, 'donation_date': donation_date, 'message': message}

