import csv
import math
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path

def write_bom_report(base_dir: str, relative_name: str, records: list[dict]) -> str:
    if not isinstance(relative_name, str) or not relative_name or (not relative_name.endswith('.csv')):
        raise ValueError('invalid filename')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid filename')
    if not isinstance(records, list):
        raise ValueError('invalid records')
    groups = {}
    for record in records:
        try:
            name = record['name']
            version = record['version']
            license_name = record['license']
            quantity = record['quantity']
            cost = record['unit_cost']
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(name, str) or not name or (not isinstance(version, str)) or (not version) or (not isinstance(license_name, str)) or (not license_name) or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity <= 0):
            raise ValueError('invalid record')
        try:
            cost_decimal = Decimal(str(cost))
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid record')
        if not cost_decimal.is_finite() or cost_decimal < 0:
            raise ValueError('invalid record')
        key = (name, version, license_name)
        if key not in groups:
            groups[key] = [0, Decimal('0')]
        groups[key][0] += quantity
        groups[key][1] += cost_decimal * quantity
    rows = []
    for (name, version, license_name), (quantity, total) in groups.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        rows.append((name, version, license_name, quantity, rounded))
    rows.sort(key=lambda row: (-row[4], row[0], row[1], row[2]))
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='', encoding='utf-8') as handle:
        writer = csv.writer(handle)
        writer.writerow(['name', 'version', 'license', 'quantity', 'total_cost'])
        for name, version, license_name, quantity, total in rows:
            writer.writerow([name, version, license_name, quantity, format(total, '.2f')])
    return str(target)

