import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    try:
        return _node(ast.parse(expression, mode='eval').body, variables)
    except NameError:
        raise
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def _node(n, v):
    if isinstance(n, ast.Constant) and type(n.value) in (int, float):
        return n.value
    if isinstance(n, ast.Name):
        if n.id not in v:
            raise NameError(n.id)
        return v[n.id]
    if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub, ast.Not)):
        x = _node(n.operand, v)
        return +x if isinstance(n.op, ast.UAdd) else -x if isinstance(n.op, ast.USub) else not x
    if isinstance(n, ast.BinOp) and type(n.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_node(n.left, v), _node(n.right, v))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](a, b)
    if isinstance(n, ast.BoolOp) and isinstance(n.op, (ast.And, ast.Or)):
        x = _node(n.values[0], v)
        for z in n.values[1:]:
            if isinstance(n.op, ast.And) and (not x):
                return x
            if isinstance(n.op, ast.Or) and x:
                return x
            x = _node(z, v)
        return x
    if isinstance(n, ast.Compare):
        x = _node(n.left, v)
        for op, z in zip(n.ops, n.comparators):
            y = _node(z, v)
            f = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
            if f is None or not f(x, y):
                return False
            x = y
        return True
    if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
        return {'min': min, 'max': max, 'round': round}[n.func.id](*[_node(x, v) for x in n.args])
    raise ValueError('invalid expression')

def intake_report(applications: list[dict], rule: str, limit: int, max_per_country: int) -> dict:
    if type(limit) is not int or limit <= 0 or type(max_per_country) is not int or (max_per_country <= 0):
        raise ValueError('invalid limits')
    seen, candidates = (set(), [])
    for a in applications:
        try:
            if set(a) != {'id', 'country', 'age', 'points', 'dependents', 'documents'} or type(a['id']) is not str or (not a['id']) or (type(a['country']) is not str) or (not a['country']) or (type(a['age']) is not int) or (type(a['points']) not in (int, float)) or (type(a['dependents']) is not int) or (a['dependents'] < 0) or (type(a['documents']) is not list) or (not all((type(x) is str for x in a['documents']))) or (a['id'] in seen):
                raise ValueError
            seen.add(a['id'])
            docs = len(a['documents'])
            r = evaluate_expression(rule, {'age': a['age'], 'points': a['points'], 'dependents': a['dependents'], 'docs': docs})
            if r is True:
                candidates.append((a['points'] + 5 * docs - 2 * a['dependents'], a['age'], a))
        except (KeyError, TypeError, NameError, ValueError):
            raise ValueError('invalid application')
    candidates.sort(key=lambda x: (-x[0], x[1], x[2]['id']))
    out, counts, ages = ([], {}, [])
    for score, age, a in candidates:
        if len(out) == limit:
            break
        if counts.get(a['country'], 0) >= max_per_country:
            continue
        out.append({'id': a['id'], 'country': a['country'], 'score': score})
        counts[a['country']] = counts.get(a['country'], 0) + 1
        ages.append(age)
    return {'accepted': out, 'by_country': counts, 'average_age': round(sum(ages) / len(ages), 2) if ages else 0.0}

