            try:
                moment = parse(reading['timestamp'])
                battery = float(reading['battery'])
                float(reading['latitude'])
                float(reading['longitude'])
            except PermissionError:
                raise
            except Exception as exc:
                raise ValueError() from exc
            if begin <= moment < finish:
                selected.append((moment, reading['timestamp'], battery))
