import hashlib
import os
import re
from datetime import date

def register_user(users: dict, username: str, password: str) -> None:
    if not isinstance(username, str) or not isinstance(password, str):
        raise ValueError('username and password must be strings')
    if not username or not password or (not re.fullmatch('[A-Za-z0-9 _-]+', username)):
        raise ValueError('invalid credentials')
    if username in users:
        raise ValueError('duplicate username')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    users[username] = (salt, digest)

def authenticate(users: dict, username: str, password: str) -> bool:
    if not isinstance(password, str) or username not in users:
        return False
    salt, expected = users[username]
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 120000)
    return actual == expected

def _fields(line):
    fields, current, escaped = ([], [], False)
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    return fields

def summarize_reports(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
    groups = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        trail, datestr, status, elevation, note = fields
        try:
