        except ValueError:
            raise ValueError('invalid date')
        if parsed.isoformat() != datestr or status not in ('open', 'closed', 'muddy') or (not re.fullmatch('\\d+', elevation)):
            raise ValueError('invalid report')
        value = int(elevation)
        item = groups.setdefault(trail, {'dates': [], 'elevations': [], 'counts': {'open': 0, 'closed': 0, 'muddy': 0}})
        item['dates'].append(datestr)
        item['elevations'].append(value)
        item['counts'][status] += 1
    result = []
