from solution import count_matching_alerts

import os
import tempfile


def make_file(contents):
    handle = tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", delete=False)
    handle.write(contents)
    handle.close()
    return handle.name


def test_counts_matching_lines_once_each():
    path = make_file("user=alice DLP\nDLP DLP\nuser=bob\n")
    try:
        assert count_matching_alerts(path, "DLP") == 2
    finally:
        os.unlink(path)


def test_returns_zero_when_no_lines_match():
    path = make_file("normal event\nanother event\n")
    try:
        assert count_matching_alerts(path, "DLP") == 0
    finally:
        os.unlink(path)


def test_matching_is_case_sensitive_and_literal():
    path = make_file("DLP\ndlp\nD.LP\n")
    try:
        assert count_matching_alerts(path, "DLP") == 1
        assert count_matching_alerts(path, "D.LP") == 1
    finally:
        os.unlink(path)


