import hashlib
import hmac
import json
import os

def parse_playlist(text: str) -> list[dict]:
    records = []
    for lineno, line in enumerate(text.splitlines(), 1):
        if not line.strip() or line.lstrip().startswith('#'):
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError(f'malformed record at line {lineno}: dangling escape')
        fields.append(''.join(current))
        if len(fields) != 3 or not fields[0] or (not fields[1]):
            raise ValueError(f'malformed record at line {lineno}')
        try:
            seconds = int(fields[2])
        except ValueError:
            raise ValueError(f'malformed record at line {lineno}: invalid duration')
        if seconds <= 0 or fields[2] != str(seconds):
            raise ValueError(f'malformed record at line {lineno}: invalid duration')
        records.append({'title': fields[0], 'artist': fields[1], 'seconds': seconds})
    return records

def compile_playlist(text: str, config: dict | None=None) -> dict:
    records = parse_playlist(text)
    combined = {}
    for record in records:
        key = (record['title'], record['artist'])
        if key not in combined:
            combined[key] = dict(record)
        else:
            combined[key]['seconds'] += record['seconds']
    tracks = list(combined.values())
    tracks.sort(key=lambda x: (x['artist'].casefold(), x['title'].casefold(), -x['seconds'], x['artist'], x['title']))
    total = sum((record['seconds'] for record in records))
    if config is not None and 'playlist_token' in config:
        key = config['playlist_token']
    else:
        key = os.environ.get('PLAYLIST_API_TOKEN')
    if key is None:
        raise RuntimeError('PLAYLIST_API_TOKEN is required')
    if isinstance(key, str):
        key = key.encode('utf-8')
    payload = json.dumps({'tracks': tracks, 'total_seconds': total}, separators=(',', ':'), sort_keys=True, ensure_ascii=False).encode('utf-8')
    signature = hmac.new(key, payload, hashlib.sha256).hexdigest()
    return {'tracks': tracks, 'total_seconds': total, 'signature': signature}

