def _key(config):
    value = config.get('signing_key') if config is not None else None
    if value is None:
        value = os.environ.get('PAYROLL_SIGNING_KEY')
    if not isinstance(value, str) or not value:
        raise ValueError('missing signing key')
    return value.encode()

def summarize_payroll(entries, month):
    if not isinstance(month, str) or not re.fullmatch('\\d{4}-\\d{2}', month):
        raise ValueError('invalid month')
    grouped = {}
    for row in entries:
        if row.get('month') != month:
            continue
        fields = ('employee_id', 'employee_name', 'department', 'month', 'gross_cents', 'deductions_cents', 'hours')
        if any((field not in row for field in fields)):
            raise ValueError('missing field')
        if not isinstance(row['gross_cents'], int) or not isinstance(row['deductions_cents'], int) or row['gross_cents'] < 0 or (row['deductions_cents'] < 0) or (row['hours'] < 0):
            raise ValueError('invalid payroll value')
        key = row['employee_id']
        if key not in grouped:
            grouped[key] = {'employee_id': key, 'employee_name': row['employee_name'], 'department': row['department'], 'gross_cents': 0, 'deductions_cents': 0, 'hours': 0}
        item = grouped[key]
        item['gross_cents'] += row['gross_cents']
        item['deductions_cents'] += row['deductions_cents']
        item['hours'] += row['hours']
    employees = []
    for item in grouped.values():
        item['net_cents'] = item['gross_cents'] - item['deductions_cents']
        item['overtime_hours'] = max(0, item['hours'] - 80)
        employees.append(item)
    employees.sort(key=lambda x: (x['department'], x['employee_name'], x['employee_id']))
    departments = {}
    for item in employees:
        d = departments.setdefault(item['department'], {'department': item['department'], 'gross_cents': 0, 'deductions_cents': 0, 'net_cents': 0, 'employee_count': 0})
        for field in ('gross_cents', 'deductions_cents', 'net_cents'):
            d[field] += item[field]
        d['employee_count'] += 1
    totals = {'gross_cents': sum((x['gross_cents'] for x in employees)), 'deductions_cents': sum((x['deductions_cents'] for x in employees)), 'net_cents': sum((x['net_cents'] for x in employees)), 'employee_count': len(employees)}
    return {'month': month, 'employees': employees, 'departments': [departments[x] for x in sorted(departments)], 'totals': totals}

