                if len(row) != 4:
                    raise ValueError
                employee, day, category, raw_amount = (x.strip() for x in row)
                if not employee or not category:
                    raise ValueError
                date.fromisoformat(day)
                amount = Decimal(raw_amount)
                if amount < 0 or -amount.as_tuple().exponent > 2:
                    raise ValueError
                amount = amount.quantize(Decimal('0.01'))
            except (ValueError, ArithmeticError, StopIteration) as exc:
                raise ValueError('malformed expense record') from exc
            records.append((employee, day, category, amount, path_index, line_index))
    records.sort(key=lambda x: (x[0], x[1], x[3], x[2], x[4], x[5]))
    return [(a, b, c, d) for a, b, c, d, _, _ in records]

def calculate_reimbursements(expenses: list[tuple[str, str, str, Decimal]], daily_cap: Decimal=Decimal('100.00'), category_limits: dict[str, Decimal] | None=None) -> dict[str, Decimal]:
    if daily_cap < 0 or (category_limits and any((v < 0 for v in category_limits.values()))):
        raise ValueError('invalid limit')
    grouped = {}
    order = []
    for employee, day, category, amount in expenses:
        try:
            date.fromisoformat(day)
            amount = Decimal(amount)
        except Exception as exc:
            raise ValueError('malformed expense') from exc
        if not employee or not category or amount < 0:
            raise ValueError('malformed expense')
        if employee not in grouped:
            grouped[employee] = {}
            order.append(employee)
        grouped[employee].setdefault(day, {})[category] = grouped[employee].setdefault(day, {}).get(category, Decimal('0')) + amount
    result = {}
    for employee in order:
        total = Decimal('0')
        for categories in grouped[employee].values():
            day_total = Decimal('0')
            for category, amount in categories.items():
                if category_limits and category in category_limits:
                    amount = min(amount, category_limits[category])
                day_total += amount
            total += min(day_total, daily_cap)
        result[employee] = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return result

