    try:
        root = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(root, dict) or not isinstance(root.get('tee_times'), list):
        raise ValueError('invalid payload')
    groups = {}
    for item in root['tee_times']:
        if not isinstance(item, dict):
            raise ValueError('invalid entry')
        keys = ('id', 'course', 'start', 'capacity', 'booked', 'price_cents', 'status')
        if any((k not in item for k in keys)) or not isinstance(item['id'], str) or (not isinstance(item['course'], str)) or (not isinstance(item['start'], str)) or (item['status'] not in ('active', 'cancelled')):
