import hmac
import json
import math

def process_identity_events(payload: str, signature: str, secret: bytes, offset: int=0, limit: int=50) -> list[dict]:
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise PermissionError('invalid signature')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).digest()
    if not hmac.compare_digest(expected, supplied):
        raise PermissionError('invalid signature')
    if offset < 0 or limit < 0:
        raise ValueError('invalid pagination')
    try:
        document = json.loads(payload)
    except (TypeError, json.JSONDecodeError):
        raise ValueError('invalid JSON')
    if not isinstance(document, dict) or not isinstance(document.get('checks'), list):
        raise ValueError('invalid document')
    groups = {}
    for item in document['checks']:
        if not isinstance(item, dict):
            raise ValueError('invalid check')
        if not isinstance(item.get('customer_id'), str) or not item['customer_id']:
            raise ValueError('invalid customer_id')
        if not isinstance(item.get('verified'), bool):
            raise ValueError('invalid verified value')
        score = item.get('score')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)) or (not 0 <= score <= 1):
            raise ValueError('invalid score')
        customer = item['customer_id']
        group = groups.setdefault(customer, [0, 0, 0.0])
        group[0] += 1
        group[1] += int(item['verified'])
        group[2] += score
    result = [{'customer_id': customer, 'checks': values[0], 'verified': values[1], 'average_score': round(values[2] / values[0], 2)} for customer, values in groups.items()]
    result.sort(key=lambda row: (-row['verified'], -row['average_score'], row['customer_id']))
    return result[offset:offset + limit]

