import hashlib
import hmac
import json
import math
import pytest


def make_payload(readings):
    return json.dumps({"readings": readings}, separators=(",", ":"))


def sign(payload, key=b"station-key"):
    return hmac.new(key, payload.encode("utf-8"), hashlib.sha256).hexdigest()


def test_empty_payload_returns_empty_list():
    payload = make_payload([])
    assert aggregate_sensor_payload(payload, sign(payload), b"station-key") == []


def test_groups_counts_averages_and_uses_latest_timestamp():
    readings = [
        {"sensor": "north", "timestamp": 10, "pm25": 10},
        {"sensor": "south", "timestamp": 30, "pm25": 7.25},
        {"sensor": "north", "timestamp": 40, "pm25": 20.555},
        {"sensor": "south", "timestamp": 20, "pm25": 12.75},
    ]
    payload = make_payload(readings)
    assert aggregate_sensor_payload(payload, sign(payload), b"station-key") == [
        {"sensor": "north", "count": 2, "average_pm25": 15.28, "latest_timestamp": 40},
        {"sensor": "south", "count": 2, "average_pm25": 10.0, "latest_timestamp": 30},
    ]


def test_ties_are_sorted_by_sensor_name():
    readings = [
        {"sensor": "zeta", "timestamp": 5, "pm25": 1},
        {"sensor": "alpha", "timestamp": 5, "pm25": 2},
        {"sensor": "mid", "timestamp": 8, "pm25": 3},
    ]
    payload = make_payload(readings)
    result = aggregate_sensor_payload(payload, sign(payload), b"station-key")
    assert [item["sensor"] for item in result] == ["mid", "alpha", "zeta"]


def test_boundary_pm25_and_timestamp_values_are_accepted():
    readings = [
        {"sensor": "edge", "timestamp": 0, "pm25": 0},
        {"sensor": "edge", "timestamp": 1, "pm25": 500},
    ]
    payload = make_payload(readings)
    assert aggregate_sensor_payload(payload, sign(payload), b"station-key") == [
        {"sensor": "edge", "count": 2, "average_pm25": 250.0, "latest_timestamp": 1}
    ]


def test_bad_signature_is_rejected_before_payload_processing():
    with pytest.raises(ValueError):
        aggregate_sensor_payload("not-json", "0" * 64, b"station-key")


def test_malformed_signature_is_rejected():
    payload = make_payload([])
    for signature in ["", "abc", "g" * 64, "0" * 62]:
        with pytest.raises(ValueError):
            aggregate_sensor_payload(payload, signature, b"station-key")


def test_malformed_json_and_wrong_top_level_raise_value_error():
    for payload in ["{", "[]", "{}", '{"readings": {}}']:
        with pytest.raises(ValueError):
            aggregate_sensor_payload(payload, sign(payload), b"station-key")


def test_invalid_readings_raise_value_error():
    invalid = [
        {"sensor": "", "timestamp": 1, "pm25": 2},
        {"sensor": "a", "timestamp": -1, "pm25": 2},
        {"sensor": "a", "timestamp": True, "pm25": 2},
        {"sensor": "a", "timestamp": 1, "pm25": 501},
        {"sensor": "a", "timestamp": 1, "pm25": float("nan")},
        {"sensor": "a", "timestamp": 1},
        "not-a-reading",
    ]
    for reading in invalid:
        payload = make_payload([reading])
        with pytest.raises(ValueError):
            aggregate_sensor_payload(payload, sign(payload), b"station-key")

