        raise TypeError('invalid arguments')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    total = 0
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('category'), str) or type(record.get('points')) is not int or (record['points'] < 0):
            raise TypeError('invalid record')
        category = record['category']
        if category not in groups:
            groups[category] = {'category': category, 'points': 0, 'count': 0}
        groups[category]['points'] += record['points']
        groups[category]['count'] += 1
        total += record['points']
    ordered = sorted(groups.values(), key=lambda x: (-x['points'], x['category']))
    start = (page - 1) * page_size
    return {'total': total, 'groups': ordered[start:start + page_size], 'page': page, 'page_size': page_size}

