import hashlib
import hmac
import os

def create_employee_record(employee_id: str, name: str, department: str, password: str) -> dict:
    values = (employee_id, name, department, password)
    if any((not isinstance(value, str) for value in values)):
        raise TypeError('employee fields must be strings')
    if any((value == '' for value in values)):
        raise ValueError('employee fields must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'employee_id': employee_id, 'name': name, 'department': department, 'password_hash': digest.hex(), 'salt': salt.hex()}

def authenticate_employee(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        stored = bytes.fromhex(record['password_hash'])
        salt = bytes.fromhex(record['salt'])
        candidate = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(candidate, stored)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_shifts(shifts: list[dict], department: str | None=None, page: int=1, page_size: int=2) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for shift in shifts:
        hours = shift['hours']
        if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
            raise ValueError('invalid hours')
        if department is not None and shift['department'] != department:
            continue
        item = groups.setdefault(shift['department'], [0, 0.0])
        item[0] += 1
        item[1] += hours
    result = [{'department': key, 'shift_count': value[0], 'total_hours': round(value[1], 2), 'average_hours': round(value[1] / value[0], 2)} for key, value in groups.items()]
    result.sort(key=lambda item: (-item['total_hours'], item['department']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

