    if not isinstance(text, str):
        raise TypeError('text must be a string')
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 5:
            raise ValueError('wrong field count')
        datestr, desk, currency, amount, status = fields
        if not desk or not currency or status not in {'pending', 'settled'}:
            raise ValueError('invalid field')
        try:
