import os, zipfile, re
from datetime import date

def _date(s):
    if not isinstance(s, str) or not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', s):
        raise ValueError('date')
    try:
        return date.fromisoformat(s)
    except ValueError as e:
        raise ValueError('date') from e

def _parts(s):
    out = []
    b = []
    esc = False
    for c in s:
        if esc:
            b.append('\\' + c)
            esc = False
        elif c == '\\':
            esc = True
        elif c == ';':
            out.append(''.join(b))
            b = []
        else:
            b.append(c)
    if esc:
        raise ValueError('escape')
    out.append(''.join(b))
    return out

def _un(s):
    out = []
    esc = False
    for c in s:
        if esc:
            out.append(c)
            esc = False
        elif c == '\\':
            esc = True
        else:
            out.append(c)
    if esc:
        raise ValueError('escape')
    return ''.join(out)

def parse_intake(text):
    if not isinstance(text, str) or not text.strip() or '\n' in text or ('\r' in text):
        raise ValueError('input')
    r = {}
    for f in _parts(text):
        q = []
        esc = False
        for i, c in enumerate(f):
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '=':
                q.append(i)
        if len(q) != 1:
            raise ValueError('field')
        k, v = (_un(f[:q[0]]).strip(), _un(f[q[0] + 1:]).strip())
        if not k or k in r:
            raise ValueError('key')
        r[k] = v
    if not {'case_id', 'client', 'priority'} <= r.keys():
        raise ValueError('missing')
    try:
        r['priority'] = int(r['priority'])
    except Exception as e:
        raise ValueError('priority') from e
    if not 1 <= r['priority'] <= 5:
        raise ValueError('priority')
    if 'next_hearing' in r:
        _date(r['next_hearing'])
    return r

def rank_cases(records, as_of):
    pivot = _date(as_of)
    a = []
    for r in records:
        try:
            cid, p, st, h, o = (r['case_id'], r['priority'], r['status'], r['next_hearing'], r['opened'])
            od = _date(o)
            hd = _date(h) if h else None
        except (KeyError, TypeError, ValueError) as e:
            raise ValueError('record') from e
        if type(p) is not int or st not in ('active', 'closed'):
            raise ValueError('record')
        if st == 'active':
            a.append((cid, p, hd, od, bool(hd and hd < pivot)))
    a.sort(key=lambda x: (-x[1], -int(x[4]), x[2] is None, x[2] or date.max, x[3], x[0]))
    return [x[0] for x in a]

def extract_case_bundle(archive_path, destination, case_id):
    if not case_id or '/' in case_id or '\\' in case_id:
        raise ValueError('case')
    try:
        with zipfile.ZipFile(archive_path) as z:
            infos = z.infolist()
            names = [i.filename for i in infos if not i.is_dir()]
            if len(names) != len(set(names)):
                raise ValueError('duplicate')
            root = os.path.realpath(os.path.join(destination, case_id))
            os.makedirs(root, exist_ok=True)
            for i in infos:
                if i.is_dir():
                    continue
                t = os.path.realpath(os.path.join(root, i.filename))
                if os.path.commonpath((root, t)) != root:
                    raise ValueError('path')
                os.makedirs(os.path.dirname(t), exist_ok=True)
                with z.open(i) as s, open(t, 'wb') as d:
                    d.write(s.read())
            return sorted(names)
    except ValueError:
        raise
    except (OSError, zipfile.BadZipFile, KeyError) as e:
        raise ValueError('archive') from e

