import hashlib
import hmac

def verify_report(payload: str, signature: str, secret: str | bytes) -> bool:
    if isinstance(secret, str):
        key = secret.encode()
    elif isinstance(secret, bytes):
        key = secret
    else:
        raise TypeError('secret must be str or bytes')
    if not isinstance(signature, str) or len(signature) != 64:
        return False
    try:
        bytes.fromhex(signature)
    except ValueError:
        return False
    expected = hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

def parse_event(line: str) -> tuple[int, str, int, int]:
    if not line:
        raise ValueError('empty line')
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('dangling escape')
    fields.append(''.join(current))
    if len(fields) != 4 or not fields[1]:
        raise ValueError('invalid fields')
    try:
        values = tuple((int(x) for x in (fields[0], fields[2], fields[3])))
    except ValueError:
        raise ValueError('invalid number')
    if any((x < 0 for x in values)):
        raise ValueError('negative number')
    return (values[0], fields[1], values[1], values[2])

def summarize_report(payload: str, signature: str, secret: str | bytes) -> dict:
    if not verify_report(payload, signature, secret):
        raise ValueError('invalid signature')
    station_data = {}
    windows = {}
    count = 0
    for line in payload.splitlines():
        if not line:
            continue
        timestamp, station, units, downtime = parse_event(line)
        count += 1
        data = station_data.setdefault(station, {'units': 0, 'downtime': 0, 'minutes': {}})
        data['units'] += units
        data['downtime'] += downtime
        minute = timestamp // 60
        data['minutes'][minute] = data['minutes'].get(minute, 0) + units
        windows[minute] = windows.get(minute, 0) + units
    stations = []
    for station in sorted(station_data):
        data = station_data[station]
        stations.append({'station': station, 'units': data['units'], 'downtime': data['downtime'], 'peak_minute_units': max(data['minutes'].values())})
    return {'events': count, 'stations': stations, 'window_totals': [{'minute': m, 'units': windows[m]} for m in sorted(windows)]}

