import json
import os
_STATES = ('IDLE', 'RUNNING', 'PAUSED', 'FAULT')

def _validate(record):
    if not isinstance(record, dict) or set(record) != {'robot', 'ts', 'state', 'battery'}:
        raise ValueError('invalid record')
    if not isinstance(record['robot'], str) or not record['robot']:
        raise ValueError('invalid record')
    if isinstance(record['ts'], bool) or not isinstance(record['ts'], int) or record['ts'] < 0:
        raise ValueError('invalid record')
    if record['state'] not in _STATES:
        raise ValueError('invalid record')
    if isinstance(record['battery'], bool) or not isinstance(record['battery'], (int, float)) or (not 0 <= record['battery'] <= 100):
        raise ValueError('invalid record')

def _path(base_dir, relative_name):
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath((base, candidate)) != base:
        raise ValueError('invalid path')
    return candidate

def load_status_log(base_dir: str, relative_name: str) -> list[dict]:
    records = []
    with open(_path(base_dir, relative_name), encoding='utf-8') as f:
        for line in f:
            if not line.strip():
                continue
            try:
                record = json.loads(line)
            except Exception as exc:
                raise ValueError('invalid JSON') from exc
            _validate(record)
            records.append(record)
    return records

def summarize_statuses(records: list[dict], start: int, end: int) -> list[dict]:
    if isinstance(start, bool) or isinstance(end, bool) or (not isinstance(start, int)) or (not isinstance(end, int)) or (start < 0) or (start >= end):
        raise ValueError('invalid range')
    groups = {}
    for record in records:
        _validate(record)
        if start <= record['ts'] < end:
            groups.setdefault(record['robot'], []).append(record)
    result = []
    for robot, items in groups.items():
        latest = max(enumerate(items), key=lambda x: (x[1]['ts'], x[0]))[1]
        counts = {state: 0 for state in _STATES}
        for item in items:
            counts[item['state']] += 1
        result.append({'robot': robot, 'samples': len(items), 'average_battery': round(sum((x['battery'] for x in items)) / len(items), 2), 'latest_state': latest['state'], 'latest_ts': latest['ts'], 'state_counts': counts})
    result.sort(key=lambda x: (-x['samples'], -x['latest_ts'], x['robot']))
    return result

def format_status_report(base_dir: str, relative_name: str, start: int, end: int) -> str:
    return json.dumps(summarize_statuses(load_status_log(base_dir, relative_name), start, end), indent=2, sort_keys=True) + '\n'

