from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
from lxml import etree

def generate_policy_report(xml_text: str, page: int, page_size: int) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if not isinstance(xml_text, str):
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'policies':
        raise ValueError('invalid root')
    records = []
    seen = set()
    totals = {'active': Decimal('0'), 'expired': Decimal('0'), 'pending': Decimal('0')}
    try:
        for node in root:
            if node.tag != 'policy':
                raise ValueError('invalid child')
            values = {key: node.attrib[key] for key in ('id', 'holder', 'status', 'premium', 'effective')}
            if values['id'] in seen or values['status'] not in totals:
                raise ValueError('invalid policy')
            premium = Decimal(values['premium'])
            if not premium.is_finite() or premium < 0:
                raise ValueError('invalid premium')
            date.fromisoformat(values['effective'])
            seen.add(values['id'])
            totals[values['status']] += premium
            records.append((values['effective'], values['id'], values, premium))
    except (KeyError, InvalidOperation, ValueError, TypeError) as exc:
        raise ValueError('invalid policy') from exc
    records.sort(key=lambda item: (item[0], item[1]), reverse=False)
    records.sort(key=lambda item: item[0], reverse=True)
    records.sort(key=lambda item: item[1] if item[0] == item[0] else item[1])
    records.sort(key=lambda item: (item[0], item[1]))
    records.sort(key=lambda item: item[0], reverse=True)
    pages = (len(records) + page_size - 1) // page_size
    selected = records[(page - 1) * page_size:page * page_size]
    quant = Decimal('0.01')
    items = []
    for _, _, values, premium in selected:
        items.append({**{key: values[key] for key in ('id', 'holder', 'status', 'effective')}, 'premium': str(premium.quantize(quant, rounding=ROUND_HALF_UP))})
    return {'total': len(records), 'page': page, 'page_size': page_size, 'pages': pages, 'items': items, 'totals_by_status': {key: str(totals[key].quantize(quant, rounding=ROUND_HALF_UP)) for key in ('active', 'expired', 'pending')}}

