import base64
import hashlib
import hmac
import os

def hash_inspector_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return base64.b64encode(salt).decode('ascii') + ':' + base64.b64encode(value).decode('ascii')

def verify_inspector_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored, str):
        raise TypeError('pin and stored must be strings')
    try:
        salt_text, value_text = stored.split(':')
        salt = base64.b64decode(salt_text.encode('ascii'), validate=True)
        expected = base64.b64decode(value_text.encode('ascii'), validate=True)
    except (ValueError, UnicodeEncodeError, TypeError):
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

