from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def reserve_inventory(requester: dict, lots: list[dict], item: str, quantity: int) -> dict:
    if not isinstance(item, str) or not item:
        raise ValueError('invalid item')
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
        raise ValueError('invalid quantity')
    required = {'id', 'item', 'quantity', 'unit_cost', 'expires_on', 'owner_id', 'tenant_id'}
    checked = []
    for lot in lots:
        if not isinstance(lot, dict) or not required.issubset(lot):
            raise ValueError('malformed lot')
        try:
            date.fromisoformat(lot['expires_on'])
            if isinstance(lot['quantity'], bool) or not isinstance(lot['quantity'], int) or lot['quantity'] < 0:
                raise ValueError
            cost = Decimal(str(lot['unit_cost']))
        except Exception as exc:
            raise ValueError('malformed lot') from exc
        if cost < 0:
            raise ValueError('malformed lot')
        checked.append((lot, cost))
    eligible = []
    roles = requester.get('roles', [])
    for lot, cost in checked:
        if lot['item'] == item and lot['tenant_id'] == requester.get('tenant_id') and (lot['quantity'] > 0):
            if lot['owner_id'] == requester.get('id') or 'inventory_manager' in roles:
                eligible.append((lot, cost))
    eligible.sort(key=lambda x: (x[0]['expires_on'], x[1], str(x[0]['id'])))
    if sum((lot['quantity'] for lot, _ in eligible)) < quantity:
        raise ValueError('insufficient stock')
    remaining = [dict(lot) for lot in lots]
    positions = {id(lot): i for i, lot in enumerate(lots)}
    allocations = []
    left = quantity
    total = Decimal('0')
    for lot, cost in eligible:
        if not left:
            break
        used = min(left, lot['quantity'])
        allocations.append({'lot_id': lot['id'], 'quantity': used, 'unit_cost': lot['unit_cost']})
        remaining[positions[id(lot)]]['quantity'] -= used
        total += cost * used
        left -= used
    rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    return {'item': item, 'quantity': quantity, 'total_cost': float(rounded), 'allocations': allocations, 'remaining_lots': remaining}

