import json

def _b64(data):
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def _date(value):
    try:
        return datetime.date.fromisoformat(value)
    except Exception as exc:
        raise ValueError('invalid date') from exc

