    if not isinstance(value, dict) or set(value) != {'records'} or (not isinstance(value['records'], list)):
        raise ValueError('invalid payload')
    out = []
    for record in value['records']:
        if not isinstance(record, dict) or set(record) != {'entity', 'obligation', 'due', 'status', 'amount_cents'}:
            raise ValueError('invalid record')
        if not all((isinstance(record[k], str) and record[k] for k in ('entity', 'obligation', 'due', 'status'))):
            raise ValueError('invalid record')
        _date(record['due'])
        if record['status'] not in {'met', 'overdue', 'waived'}:
            raise ValueError('invalid record')
        if isinstance(record['amount_cents'], bool) or not isinstance(record['amount_cents'], int) or record['amount_cents'] < 0:
            raise ValueError('invalid record')
        out.append(dict(record))
    return out

def make_envelope(records: list[dict], secret: bytes, timestamp: int) -> str:
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
    if isinstance(timestamp, bool) or not isinstance(timestamp, int) or (not 0 <= timestamp <= 4102444800):
        raise ValueError('invalid timestamp')
    records = _records({'records': records})
    payload = _b64(json.dumps({'records': records}, separators=(',', ':')).encode())
    head = f'v1.{timestamp}.{payload}'
    mac = hmac.new(secret, head.encode('ascii'), hashlib.sha256).digest()
    return head + '.' + _b64(mac)

def verify_and_summarize(envelope: str, secret: bytes, as_of: str) -> dict:
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
