        raise ValueError('invalid envelope')
    parts = envelope.split('.')
    if len(parts) != 4 or parts[0] != 'v1' or (not parts[1].isdigit()) or (len(parts[1]) > 1 and parts[1][0] == '0'):
        raise ValueError('invalid envelope')
    timestamp = int(parts[1])
    if timestamp > 4102444800:
        raise ValueError('invalid envelope')
    try:
        raw = base64.urlsafe_b64decode(parts[2] + '=' * (-len(parts[2]) % 4))
        supplied = base64.urlsafe_b64decode(parts[3] + '=' * (-len(parts[3]) % 4))
        payload = json.loads(raw.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid envelope') from exc
