import hmac
from datetime import date

def _field(value: str) -> str:
    return value.replace('\\', '\\\\').replace('|', '\\|').replace('\r', '\\r').replace('\n', '\\n')

def _check_record(record: dict) -> None:
    required = {'employee_id', 'name', 'department', 'salary_cents', 'effective_date'}
    if not isinstance(record, dict) or set(record) != required:
        raise ValueError('record must contain exactly the required fields')
    for key in ('employee_id', 'name', 'department'):
        if not isinstance(record[key], str) or not record[key]:
            raise ValueError(f'{key} must be a non-empty string')
    if isinstance(record['salary_cents'], bool) or not isinstance(record['salary_cents'], int) or record['salary_cents'] < 0:
        raise ValueError('salary_cents must be a non-negative integer')
    if not isinstance(record['effective_date'], str):
        raise ValueError('effective_date must be a date')
    try:
        date.fromisoformat(record['effective_date'])
    except ValueError as exc:
        raise ValueError('effective_date must be YYYY-MM-DD') from exc
    if len(record['effective_date']) != 10:
        raise ValueError('effective_date must be YYYY-MM-DD')

def canonicalize_records(records: list[dict]) -> str:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        _check_record(record)
    ids = [record['employee_id'] for record in records]
    if len(ids) != len(set(ids)):
        raise ValueError('employee_id values must be unique')
    ordered = sorted(records, key=lambda item: (item['effective_date'], item['employee_id']))
    lines = []
    for record in ordered:
        values = [record['employee_id'], record['name'], record['department'], str(record['salary_cents']), record['effective_date']]
        lines.append('|'.join((_field(value) for value in values)))
    return '\n'.join(lines) + ('\n' if lines else '')

def sign_records(records: list[dict], config: dict[str, str]) -> str:
    key = config['HR_SIGNING_KEY']
    if not isinstance(key, str):
        raise TypeError('HR_SIGNING_KEY must be a string')
    payload = canonicalize_records(records).encode('utf-8')
    return hmac.new(key.encode('utf-8'), payload, hashlib.sha256).hexdigest()

