import os
from collections import defaultdict
from datetime import datetime

def summarize_meter_file(base_dir: str, relative_name: str, meter_id: str) -> list[tuple[str, float, int]]:
    if not meter_id:
        raise ValueError('meter_id must not be empty')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if candidate != base and base not in os.path.commonpath([base, candidate]):
        raise ValueError('file is outside base directory')
    totals = defaultdict(float)
    counts = defaultdict(int)
    with open(candidate, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('missing header')
        if header != ['timestamp', 'meter_id', 'kwh']:
            raise ValueError('invalid header')
        for row in reader:
            if len(row) != 3:
                raise ValueError('invalid row')
            try:
                stamp = datetime.fromisoformat(row[0])
                value = float(row[2])
            except (TypeError, ValueError, OverflowError):
                raise ValueError('invalid data')
            if not math.isfinite(value) or value < 0:
                raise ValueError('invalid kwh')
            if row[1] == meter_id:
                day = stamp.date().isoformat()
                totals[day] += value
                counts[day] += 1
    return [(day, round(totals[day], 3), counts[day]) for day in sorted(totals)]

