import json
import pytest


def signed(payload, secret="survey-key"):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_empty_survey():
    payload = json.dumps({"responses": []}, separators=(",", ":"))
    assert process_survey(payload, signed(payload), "survey-key") == {
        "total_responses": 0,
        "averages": {},
        "page": 1,
        "page_size": 10,
        "respondents": [],
    }


def test_averages_and_sorted_pagination():
    data = {
        "responses": [
            {"respondent": "zoe", "answers": {"q2": 5, "q1": 2}},
            {"respondent": "amy", "answers": {"q1": 4}},
            {"respondent": "mike", "answers": {"q2": 1, "q1": 3}},
        ]
    }
    payload = json.dumps(data, separators=(",", ":"))
    assert process_survey(payload, signed(payload), "survey-key", 1, 2) == {
        "total_responses": 3,
        "averages": {"q1": 3.0, "q2": 3.0},
        "page": 1,
        "page_size": 2,
        "respondents": ["amy", "mike"],
    }
    assert process_survey(payload, signed(payload), "survey-key", 2, 2)["respondents"] == ["zoe"]


def test_rounding_and_missing_questions():
    data = {"responses": [
        {"respondent": "a", "answers": {"q": 1, "other": 5}},
        {"respondent": "b", "answers": {"q": 2}},
        {"respondent": "c", "answers": {"q": 4}},
    ]}
    payload = json.dumps(data, separators=(",", ":"))
    result = process_survey(payload, signed(payload), "survey-key")
    assert result["averages"] == {"other": 5.0, "q": 2.33}


def test_ties_and_duplicate_names_are_preserved():
    data = {"responses": [
        {"respondent": "sam", "answers": {"q": 1}},
        {"respondent": "sam", "answers": {"q": 5}},
        {"respondent": "ann", "answers": {"q": 3}},
    ]}
    payload = json.dumps(data, separators=(",", ":"))
    assert process_survey(payload, signed(payload), "survey-key", 1, 2)["respondents"] == ["ann", "sam"]
    assert process_survey(payload, signed(payload), "survey-key", 2, 2)["respondents"] == ["sam"]
    assert process_survey(payload, signed(payload), "survey-key")["averages"] == {"q": 3.0}


