from datetime import datetime

def _validate_records(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    seen = set()
    for item in records:
        if not isinstance(item, dict) or set(item) != {'id', 'vehicle', 'site', 'window_start', 'window_end', 'priority'}:
            raise ValueError('invalid record')
        if not all((isinstance(item[k], str) and item[k] for k in ('id', 'vehicle', 'site'))):
            raise ValueError('invalid text')
        if item['id'] in seen or not isinstance(item['priority'], int) or isinstance(item['priority'], bool):
            raise ValueError('invalid record')
        seen.add(item['id'])
        try:
            start = datetime.strptime(item['window_start'], '%Y-%m-%dT%H:%M:%SZ')
            end = datetime.strptime(item['window_end'], '%Y-%m-%dT%H:%M:%SZ')
        except Exception as exc:
            raise ValueError('invalid timestamp') from exc
        if start >= end or start.second or end.second:
            raise ValueError('invalid window')

def pack_launches(records: list[dict]) -> bytes:
    _validate_records(records)
    return json.dumps(records, separators=(',', ':')).encode('utf-8')

