    if not isinstance(blob, bytes) or not isinstance(minimum_duration_minutes, int) or isinstance(minimum_duration_minutes, bool) or (not isinstance(limit, int)) or isinstance(limit, bool) or (minimum_duration_minutes < 0) or (limit < 0):
        raise ValueError('invalid arguments')
    try:
        datetime.strptime(day, '%Y-%m-%d')
        records = json.loads(blob.decode('utf-8'))
        _validate_records(records)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError('invalid blob') from exc
    result = []
    for item in records:
        start = datetime.strptime(item['window_start'], '%Y-%m-%dT%H:%M:%SZ')
        end = datetime.strptime(item['window_end'], '%Y-%m-%dT%H:%M:%SZ')
        duration = int((end - start).total_seconds() // 60)
        if start.strftime('%Y-%m-%d') == day and end.strftime('%Y-%m-%d') == day and (duration >= minimum_duration_minutes):
            result.append({**item, 'duration_minutes': duration})
    result.sort(key=lambda x: (-x['priority'], x['window_start'], x['id']))
    return result[:limit]

