        if not isinstance(start, datetime):
            raise ValueError('invalid start')
        if start.date() == day:
            duration = item['duration']
            selected.append(item)
            totals[item['student']] = totals.get(item['student'], 0) + duration
    selected.sort(key=lambda x: (x['start'], -x['duration'], x['student']))
