        raise TypeError('requester and pass_record must be dictionaries')
    if not isinstance(origin, str) or not isinstance(destination, str):
        raise TypeError('locations must be strings')
    if not isinstance(fare_cents, int) or isinstance(fare_cents, bool):
        raise TypeError('fare_cents must be an integer')
    if not origin or not destination or origin == destination:
        raise ValueError('invalid route')
    if not isinstance(pass_record.get('active'), bool):
        raise TypeError('active must be boolean')
    if not pass_record['active'] or fare_cents <= 0:
        raise ValueError('invalid pass or fare')
    if pass_record['balance_cents'] < fare_cents:
        raise ValueError('insufficient balance')
    if requester.get('user_id') != pass_record.get('owner_id') and requester.get('role') != 'agent':
        raise PermissionError('requester cannot issue this ticket')
    pass_record['balance_cents'] -= fare_cents
    return {'ticket_id': f"{pass_record['pass_id']}:{origin}-{destination}", 'pass_id': pass_record['pass_id'], 'owner_id': pass_record['owner_id'], 'origin': origin, 'destination': destination, 'fare_cents': fare_cents}

