import os
import tempfile

def export_transcript(student_id: str, enrollments: list[dict], destination: str, page: int=1, page_size: int=50) -> dict:
    if not isinstance(student_id, str) or not student_id:
        raise ValueError('invalid student_id')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    values = {'A': 4.0, 'B': 3.0, 'C': 2.0, 'D': 1.0, 'F': 0.0, 'W': None}
    rows = []
    for item in enrollments:
        if not isinstance(item, dict) or not all((k in item for k in ('student_id', 'course', 'semester', 'credits', 'grade'))):
            raise ValueError('invalid enrollment')
        if not isinstance(item['student_id'], str) or not isinstance(item['course'], str) or (not item['course']) or (not isinstance(item['semester'], int)) or isinstance(item['semester'], bool) or (not isinstance(item['credits'], int)) or isinstance(item['credits'], bool) or (item['credits'] <= 0) or (item['grade'] not in values):
            raise ValueError('invalid enrollment')
        if item['student_id'] == student_id and item['grade'] != 'W':
            point = values[item['grade']]
            rows.append({'course': item['course'], 'semester': item['semester'], 'credits': item['credits'], 'grade': item['grade'], 'points': point * item['credits']})
    rows.sort(key=lambda x: (x['semester'], x['course']))
    total_credits = sum((x['credits'] for x in rows))
    total_points = sum((x['points'] for x in rows))
    result_rows = rows[(page - 1) * page_size:page * page_size]
    fd, temporary = tempfile.mkstemp(prefix='transcript_', suffix='.csv')
    os.close(fd)
    try:
        with open(temporary, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['course', 'semester', 'credits', 'grade', 'points'])
            for row in rows:
                writer.writerow([row['course'], row['semester'], row['credits'], row['grade'], f"{row['points']:.2f}"])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'student_id': student_id, 'total_courses': len(rows), 'total_credits': total_credits, 'gpa': round(total_points / total_credits, 2) if rows else None, 'rows': result_rows}

