import secrets

def summarize_loans(loans: list[dict], page: int, page_size: int) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    groups = {}
    total_records = 0
    total_value = 0
    required = {'object_id', 'institution', 'status', 'value', 'days'}
    for loan in loans:
        if not required.issubset(loan):
            raise ValueError('missing field')
        if not isinstance(loan['status'], str):
            raise ValueError('invalid status')
        if not isinstance(loan['value'], (int, float)) or isinstance(loan['value'], bool):
            raise ValueError('invalid value')
        if not isinstance(loan['days'], (int, float)) or isinstance(loan['days'], bool):
            raise ValueError('invalid days')
        if loan['status'] not in ('approved', 'pending'):
            continue
        name = loan['institution']
        group = groups.setdefault(name, {'count': 0, 'total_value': 0, 'days': 0})
        group['count'] += 1
        group['total_value'] += loan['value']
        group['days'] += loan['days']
        total_records += 1
        total_value += loan['value']
    output = [{'institution': name, 'count': data['count'], 'total_value': round(data['total_value'], 2), 'average_days': round(data['days'] / data['count'], 1)} for name, data in groups.items()]
    output.sort(key=lambda item: (-item['total_value'], item['institution']))
    total_pages = (len(output) + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'total_records': total_records, 'total_value': round(total_value, 2), 'groups': output[start:start + page_size], 'page': page, 'page_size': page_size, 'total_pages': total_pages}

def create_invite_code(loan_id: str, existing_codes: set[str] | list[str]) -> str:
    if not isinstance(loan_id, str) or not loan_id:
        raise ValueError('invalid loan id')
    if any((not isinstance(code, str) for code in existing_codes)):
        raise ValueError('invalid existing code')
    existing = set(existing_codes)
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    while True:
        code = 'MUS-' + ''.join((secrets.choice(alphabet) for _ in range(8)))
        if code not in existing:
            return code

