def select_trucks(records: list[dict], rule: str, limit: int=10, offset: int=0) -> list[dict]:
    if limit < 0 or offset < 0:
        raise ValueError('limit and offset must be nonnegative')
    try:
        tree = ast.parse(rule, mode='eval')
    except Exception as exc:
        raise ValueError('invalid rule') from exc
    names = {'id', 'axle_count', 'gross_kg', 'speed_kmh', 'route'}
    functions = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    comparisons = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def evaluate(node, values):
        if isinstance(node, ast.Expression):
            return evaluate(node.body, values)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, str, bool)):
            return node.value
        if isinstance(node, ast.Name) and node.id in names:
            return values[node.id]
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = evaluate(node.operand, values)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            return binary[type(node.op)](evaluate(node.left, values), evaluate(node.right, values))
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            result = evaluate(node.values[0], values)
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not result):
                    return result
                if isinstance(node.op, ast.Or) and result:
                    return result
                result = evaluate(item, values)
            return result
        if isinstance(node, ast.Compare):
            left = evaluate(node.left, values)
            for op, part in zip(node.ops, node.comparators):
                if type(op) not in comparisons:
                    raise ValueError('invalid rule')
                right = evaluate(part, values)
                if not comparisons[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in functions) and (not node.keywords):
            return functions[node.func.id](*(evaluate(arg, values) for arg in node.args))
        raise ValueError('invalid rule')
    selected = []
    for record in records:
        values = {name: record[name] for name in names}
        try:
            if evaluate(tree, values):
                selected.append(record)
        except Exception as exc:
            raise ValueError('invalid rule') from exc
    selected.sort(key=lambda item: (-item['gross_kg'], item['id']))
    return selected[offset:offset + limit]

