            raise ValueError('invalid amount')
        if not isinstance(text_date, str):
            raise ValueError('invalid date')
        try:
            date = datetime.date.fromisoformat(text_date)
        except ValueError:
            raise ValueError('invalid date')
        if date.isoformat() != text_date:
            raise ValueError('invalid date')
        campaign = item.get('campaign', 'General')
        if not isinstance(campaign, str) or not campaign.strip():
            raise ValueError('invalid campaign')
        if date.year != fiscal_year:
            continue
        if donor not in groups:
            groups[donor] = {'donor': donor, 'total_cents': 0, 'donation_count': 0, 'dates': [], 'campaigns': set()}
        group = groups[donor]
        group['total_cents'] += amount
        group['donation_count'] += 1
        group['dates'].append(text_date)
        group['campaigns'].add(campaign)
    result = []
    for group in groups.values():
        result.append({'donor': group['donor'], 'total_cents': group['total_cents'], 'donation_count': group['donation_count'], 'first_date': min(group['dates']), 'last_date': max(group['dates']), 'campaigns': sorted(group['campaigns'])})
    return sorted(result, key=lambda x: (-x['total_cents'], x['donor'].casefold(), x['donor']))

def write_acknowledgments(donations: list[dict], fiscal_year: int, destination: str) -> list[dict]:
    summaries = summarize_donations(donations, fiscal_year)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.ack-', suffix='.csv', dir=directory)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream)
            writer.writerow(['Donor', 'Total Cents', 'Donation Count', 'First Date', 'Last Date', 'Campaigns'])
            for row in summaries:
                writer.writerow([row['donor'], row['total_cents'], row['donation_count'], row['first_date'], row['last_date'], ';'.join(row['campaigns'])])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summaries

