import hashlib
import hmac
import os
from datetime import date

def create_reservation(plot_id: int, applicant: str, reservation_date: str, config: dict | None=None) -> dict:
    if not isinstance(plot_id, int) or isinstance(plot_id, bool) or plot_id <= 0:
        raise ValueError('plot_id must be a positive integer')
    normalized_applicant = applicant.strip()
    if not normalized_applicant:
        raise ValueError('applicant must not be empty')
    try:
        parsed_date = date.fromisoformat(reservation_date)
    except (TypeError, ValueError):
        raise ValueError('reservation_date must be a valid ISO date')
    if parsed_date.isoformat() != reservation_date:
        raise ValueError('reservation_date must be in YYYY-MM-DD form')
    if config is not None and 'reservation_signing_key' in config:
        key = config['reservation_signing_key']
    else:
        key = os.environ.get('CEMETERY_RESERVATION_KEY')
    if key is None:
        raise ValueError('reservation signing key is required')
    payload = f'{plot_id}|{reservation_date}|{normalized_applicant}'.encode('utf-8')
    signature = hmac.new(str(key).encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return {'plot_id': plot_id, 'applicant': normalized_applicant, 'reservation_date': reservation_date, 'signature': signature}

