import csv
import os
import tempfile

def read_rows(path):
    with open(path, 'r', encoding='utf-8', newline='') as handle:
        return list(csv.reader(handle))

def test_empty_input_writes_header():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'empty.csv')
        assert export_playlist_csv([], path) == 0
        assert read_rows(path) == [['genre', 'title', 'artist', 'duration_seconds', 'plays', 'rating']]

def test_ties_keep_input_order():
    tracks = [{'title': 'Same', 'artist': 'Artist', 'genre': 'Pop', 'duration_seconds': 1, 'plays': 1, 'rating': 3}, {'title': 'same', 'artist': 'artist', 'genre': 'pop', 'duration_seconds': 2, 'plays': 2, 'rating': 3}, {'title': 'Same', 'artist': 'Artist', 'genre': 'POP', 'duration_seconds': 3, 'plays': 3, 'rating': 3}]
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'ties.csv')
        export_playlist_csv(tracks, path)
        rows = read_rows(path)
        assert [row[3] for row in rows[1:]] == ['1', '2', '3']

def test_replaces_existing_file_and_handles_csv_text():
    track = {'title': 'A, B', 'artist': 'The "Band"', 'genre': 'Folk', 'duration_seconds': 65, 'plays': 0, 'rating': 5}
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'existing.csv')
        with open(path, 'w', encoding='utf-8') as handle:
            handle.write('old contents')
        assert export_playlist_csv([track], path) == 1
        assert read_rows(path)[1] == ['Folk', 'A, B', 'The "Band"', '65', '0', '5.0']

def test_invalid_track_raises_and_does_not_change_destination():
    with tempfile.TemporaryDirectory() as directory:
        path = os.path.join(directory, 'unchanged.csv')
        with open(path, 'w', encoding='utf-8') as handle:
            handle.write('keep this')
        bad = {'title': 'x', 'artist': 'y', 'genre': 'z', 'duration_seconds': 0, 'plays': 1, 'rating': 2}
        try:
            export_playlist_csv([bad], path)
            assert False
        except ValueError:
            pass
        with open(path, 'r', encoding='utf-8') as handle:
            assert handle.read() == 'keep this'

def test_invalid_rating_arguments_raise_value_error():
    with tempfile.TemporaryDirectory() as directory:
