def export_playlist_csv(tracks: list[dict], destination: str, min_rating: float=0.0) -> int:
    if isinstance(min_rating, bool) or not isinstance(min_rating, (int, float)) or (not 0.0 <= min_rating <= 5.0):
        raise ValueError('invalid minimum rating')
    prepared = []
    for track in tracks:
        if not isinstance(track, dict):
            raise ValueError('invalid track')
        for key in ('title', 'artist', 'genre', 'duration_seconds', 'plays', 'rating'):
