            raise ValueError('invalid track')
        if isinstance(track['plays'], bool) or not isinstance(track['plays'], int) or track['plays'] < 0:
            raise ValueError('invalid track')
        if isinstance(track['rating'], bool) or not isinstance(track['rating'], (int, float)) or (not 0.0 <= track['rating'] <= 5.0):
            raise ValueError('invalid track')
        if track['rating'] >= min_rating:
            prepared.append(track)
    prepared.sort(key=lambda t: (t['genre'].casefold(), t['title'].casefold(), t['artist'].casefold()))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='playlist-', suffix='.csv', dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['genre', 'title', 'artist', 'duration_seconds', 'plays', 'rating'])
