                writer.writerow([track['genre'], track['title'], track['artist'], track['duration_seconds'], track['plays'], f"{track['rating']:.1f}"])
        os.replace(temporary, destination)
        return len(prepared)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)

