from solution import summarize_event_files

import os
import subprocess
import tempfile


def make_file(directory, name, lines):
    path = os.path.join(directory, name)
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(lines))
        if lines:
            handle.write("\n")
    return path


def test_counts_files_and_preserves_paths():
    with tempfile.TemporaryDirectory() as directory:
        first = make_file(directory, "first.dat", ["a", "b", "c"])
        second = make_file(directory, "second.dat", ["x"])
        assert summarize_event_files([first, second]) == [(first, 3), (second, 1)]


def test_empty_file_and_threshold():
    with tempfile.TemporaryDirectory() as directory:
        empty = make_file(directory, "empty.dat", [])
        full = make_file(directory, "full.dat", ["a", "b"])
        assert summarize_event_files([empty, full], min_events=1) == [(full, 2)]
        assert summarize_event_files([empty, full], min_events=3) == []


def test_sorting_uses_path_for_ties():
    with tempfile.TemporaryDirectory() as directory:
        zed = make_file(directory, "z.dat", ["a", "b"])
        alpha = make_file(directory, "a.dat", ["a", "b"])
        one = make_file(directory, "m.dat", ["a"])
        assert summarize_event_files([zed, one, alpha]) == [
            (alpha, 2),
            (zed, 2),
            (one, 1),
        ]


def test_pagination_boundaries():
    with tempfile.TemporaryDirectory() as directory:
        paths = [make_file(directory, name, ["x"] * count) for name, count in [
            ("a.dat", 5), ("b.dat", 4), ("c.dat", 3), ("d.dat", 2), ("e.dat", 1)
        ]]
        assert summarize_event_files(paths, page=1, page_size=2) == [
            (paths[0], 5), (paths[1], 4)
        ]
        assert summarize_event_files(paths, page=2, page_size=2) == [
            (paths[2], 3), (paths[3], 2)
        ]
        assert summarize_event_files(paths, page=3, page_size=2) == [(paths[4], 1)]
        assert summarize_event_files(paths, page=4, page_size=2) == []


def test_empty_input_and_validation():
    assert summarize_event_files([]) == []
    assert summarize_event_files([], min_events=2, page=3, page_size=4) == []
    for args in [([], -1, 1, 10), ([], 0, 0, 10), ([], 0, 1, 0)]:
        try:
            summarize_event_files(*args)
        except ValueError:
            pass
        else:
            assert False


def test_type_validation():
    invalid_calls = [
        ("not-a-list", 0, 1, 10),
        (["ok"], "0", 1, 10),
        (["ok"], 0, "1", 10),
        (["ok"], 0, 1, "10"),
        ([1], 0, 1, 10),
    ]
    for args in invalid_calls:
        try:
            summarize_event_files(*args)
        except TypeError:
            pass
        else:
            assert False


def test_missing_file_error_propagates():
    with tempfile.TemporaryDirectory() as directory:
        missing = os.path.join(directory, "missing.dat")
        try:
            summarize_event_files([missing])
        except (subprocess.CalledProcessError, FileNotFoundError):
            pass
        else:
            assert False

