def summarize_event_files(paths: list[str], min_events: int=0, page: int=1, page_size: int=10) -> list[tuple[str, int]]:
    if not isinstance(paths, list) or any((not isinstance(path, str) for path in paths)):
        raise TypeError('paths must be a list of strings')
    if any((not isinstance(value, int) for value in (min_events, page, page_size))):
        raise TypeError('numeric arguments must be integers')
    if min_events < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid argument')
    results = []
    for path in paths:
        completed = subprocess.run(['wc', '-l', path], check=True, capture_output=True, text=True)
        count = int(completed.stdout.split()[0])
        if count >= min_events:
            results.append((path, count))
    results.sort(key=lambda item: (-item[1], item[0]))
    start = (page - 1) * page_size
    return results[start:start + page_size]

