import sqlite3
import time

def load_reading_report(conn: sqlite3.Connection, patient_id: str, start_ts: int, end_ts: int, order_by: str='timestamp') -> list[dict]:
    columns = {'timestamp': 'recorded_at', 'heart_rate': 'heart_rate', 'spo2': 'spo2'}
    if order_by not in columns:
        raise ValueError('invalid order')
    rows = conn.execute(f'SELECT id, recorded_at, heart_rate, spo2 FROM readings WHERE patient_id = ? AND recorded_at >= ? AND recorded_at < ? ORDER BY {columns[order_by]} ASC, id ASC', (patient_id, start_ts, end_ts)).fetchall()
    result = []
    for index, (ident, recorded, rate, oxygen) in enumerate(rows):
        window = rows[max(0, index - 2):index + 1]
        result.append({'id': ident, 'timestamp': recorded, 'heart_rate': float(rate), 'spo2': float(oxygen), 'heart_rate_avg': sum((float(row[2]) for row in window)) / len(window), 'spo2_avg': sum((float(row[3]) for row in window)) / len(window)})
    return result

def acknowledge_alert(conn: sqlite3.Connection, alert_id: int, actor: str, status: str='acknowledged') -> bool:
    if status not in {'acknowledged', 'resolved', 'dismissed'} or not actor:
        raise ValueError('invalid alert update')
    cursor = conn.execute('UPDATE alerts SET status = ?, acknowledged_by = ?, acknowledged_at = ? WHERE id = ?', (status, actor, int(time.time()), alert_id))
    conn.commit()
    return cursor.rowcount == 1

