from datetime import date
from lxml import etree

def parse_prescription(xml_text: str) -> dict:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
        if root.tag != 'prescription':
            raise ValueError()
        patient = root.get('patient')
        issued = root.get('issued')
        if not patient or not issued or date.fromisoformat(issued).isoformat() != issued:
            raise ValueError()
        eyes = {}
        for eye in root:
            if eye.tag != 'eye' or eye.get('side') not in ('R', 'L') or eye.get('side') in eyes:
                raise ValueError()
            side = eye.get('side')
            values = {}
            for item in eye:
                if item.tag not in ('sphere', 'cylinder', 'axis', 'add') or item.tag in values:
                    raise ValueError()
                text = (item.text or '').strip()
                if not text:
                    raise ValueError()
                try:
                    if item.tag == 'axis':
                        if any((c in text for c in '.eE')):
                            raise ValueError()
                        value = int(text)
                        if not 0 <= value <= 180:
                            raise ValueError()
                    else:
                        value = float(text)
                        if not -20.0 <= value <= 20.0:
                            raise ValueError()
                except (TypeError, ValueError, OverflowError):
                    raise ValueError()
                values[item.tag] = value
            if set(values) != {'sphere', 'cylinder', 'axis'} and set(values) != {'sphere', 'cylinder', 'axis', 'add'}:
                raise ValueError()
            values.setdefault('add', 0.0)
            eyes[side] = values
        if set(eyes) != {'R', 'L'}:
            raise ValueError()
        return {'patient': patient, 'issued': issued, 'eyes': {'R': eyes['R'], 'L': eyes['L']}}
    except (etree.XMLSyntaxError, ValueError, TypeError):
        raise ValueError()

def summarize_prescriptions(xml_documents: list[str]) -> list[dict]:
    latest = {}
    for index, document in enumerate(xml_documents):
        record = parse_prescription(document)
        key = record['patient']
        if key not in latest or record['issued'] >= latest[key][0]:
            latest[key] = (record['issued'], index, record)
    result = []
    for issued, index, record in latest.values():
        severity = max((abs(v['sphere'] + v['cylinder'] / 2) for v in record['eyes'].values()))
        result.append({'patient': record['patient'], 'issued': issued, 'severity': round(severity, 2)})
    result.sort(key=lambda x: (-x['severity'], x['issued']), reverse=False)
    result.sort(key=lambda x: (-x['severity'], x['issued'], x['patient']))
    return result

