import sqlite3

def find_cases(conn: sqlite3.Connection, status: str | None=None, assigned_to: int | None=None, search: str | None=None, sort_by: str='created_at', descending: bool=False) -> list[dict]:
    columns = {'id', 'client_name', 'status', 'assigned_to', 'created_at'}
    if sort_by not in columns:
        raise ValueError('unsupported sort column')
    clauses = []
    params = []
    if status is not None:
        clauses.append('status = ?')
        params.append(status)
    if assigned_to is not None:
        clauses.append('assigned_to = ?')
        params.append(assigned_to)
    if search is not None:
        clauses.append('summary LIKE ?')
        params.append(f'%{search}%')
    query = 'SELECT id, client_name, status, assigned_to, summary, created_at FROM cases'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    query += f" ORDER BY {sort_by} {('DESC' if descending else 'ASC')}, id ASC"
    rows = conn.execute(query, params).fetchall()
    keys = ['id', 'client_name', 'status', 'assigned_to', 'summary', 'created_at']
    return [dict(zip(keys, row)) for row in rows]

