import requests

def summarize_expiring_certificates(base_url: str, api_token: str, now: datetime, days: int) -> list[dict]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError('now must be timezone-aware')
    if isinstance(days, bool) or not isinstance(days, int) or days < 0:
        raise ValueError('days must be a non-negative integer')
    response = requests.get(base_url.rstrip('/') + '/api/v1/certificates', params={'limit': 1000}, headers={'Authorization': 'Bearer ' + api_token})
    if response.status_code != 200:
        raise RuntimeError('certificate API request failed')
    data = response.json()
    end = now + timedelta(days=days)
    groups = {}
    for certificate in data['certificates']:
        if certificate['status'] != 'active':
            continue
        value = certificate['expires_at']
        try:
            expires = datetime.fromisoformat(value[:-1] + '+00:00' if value.endswith('Z') else value)
        except (TypeError, ValueError):
            raise ValueError('invalid certificate timestamp')
        if expires.tzinfo is None or expires.utcoffset() is None:
            raise ValueError('certificate timestamp must be timezone-aware')
        if now <= expires <= end:
            issuer = certificate['issuer']
            groups.setdefault(issuer, []).append((expires, certificate['serial']))
    result = []
    for issuer in sorted(groups):
        entries = sorted(groups[issuer], key=lambda item: (item[0], item[1]))
        result.append({'issuer': issuer, 'count': len(entries), 'serials': [serial for _, serial in entries]})
    return result

