import re
import secrets

def generate_enrollment_invite(course_code: str, term: str, length: int=8) -> str:
    if not isinstance(course_code, str) or not isinstance(term, str):
        raise TypeError('course_code and term must be strings')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if length < 6 or length > 32:
        raise ValueError('length must be between 6 and 32')
    course_code = course_code.strip()
    term = term.strip()
    if not course_code or not term:
        raise ValueError('course_code and term must not be empty')
    if re.fullmatch('[A-Za-z0-9]+', course_code) is None:
        raise ValueError('invalid course_code')
    if re.fullmatch('[A-Za-z0-9-]+', term) is None:
        raise ValueError('invalid term')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'{course_code.upper()}-{term.upper()}-{code}'

