from lxml import etree

def parse_campaign_contributions(xml_text: str) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'report':
        raise ValueError('wrong root')
    result = []
    for child in root:
        if child.tag != 'contribution' or len(child):
            raise ValueError('invalid contribution')
        try:
            donor = child.attrib['donor'].strip()
            amount_text = child.attrib['amount_cents'].strip()
            date = child.attrib['date'].strip()
            committee = child.attrib.get('committee', '').strip()
            if not donor or not date or (not amount_text.isdigit()):
                raise ValueError('invalid fields')
            amount = int(amount_text)
        except (KeyError, ValueError) as exc:
            raise ValueError('invalid contribution') from exc
        result.append({'donor': donor, 'amount_cents': amount, 'date': date, 'committee': committee})
    return result

