def issue_invite(text: str, registry: set[str]) -> dict:
    case = parse_case(text)
    screened = screen_case(case)
    if not screened['benefits']:
        raise ValueError('no benefits')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
