def render_report(rows: list[dict], title: str) -> str:
    lines = ['<div class="air-quality-report">', f'<h1>{title}</h1>', '<table><thead><tr><th>Window</th><th>Station</th><th>Readings</th><th>Average PM2.5</th><th>Peak CO2</th></tr></thead><tbody>']
    for r in rows:
        try:
            start, station, count = (r['start'], r['station'], r['count'])
            avg, peak = (r['avg_pm25'], r['max_co2'])
        except KeyError as exc:
            raise ValueError('missing field') from exc
        lines.append(f'<tr><td>{start}</td><td>{station}</td><td>{count}</td><td>{float(avg):.2f}</td><td>{float(peak):.2f}</td></tr>')
    lines.extend(['</tbody></table>', '</div>'])
    return '\n'.join(lines)

