    query = 'SELECT id, title, start_time, end_time, status, volunteer_id, (julianday(end_time) - julianday(start_time)) * 24 AS duration_hours FROM shifts' + where + ' ORDER BY ' + sort_columns[sort_by] + ', id LIMIT ? OFFSET ?'
