import math
import requests
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def process_expenses(records: list[dict], config: dict, page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be positive')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    try:
        endpoint = config['endpoint']
        token = config['api_token']
    except (KeyError, TypeError):
        raise ValueError('endpoint and api token are required')
    grouped = {}
    for record in records:
        if not isinstance(record, dict) or not isinstance(record.get('employee'), str) or (not record['employee']) or (not isinstance(record.get('status'), str)):
            raise ValueError('invalid record')
        amount = record.get('amount')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)) or (amount < 0):
            raise ValueError('invalid amount')
        if record['status'] == 'approved':
            grouped.setdefault(record['employee'], [Decimal('0'), 0])
            grouped[record['employee']][0] += Decimal(str(amount))
            grouped[record['employee']][1] += 1
    entries = [{'employee': name, 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'count': count} for name, (total, count) in grouped.items()]
    entries.sort(key=lambda item: (-item['total'], item['employee']))
    total = sum((Decimal(str(item['total'])) for item in entries), Decimal('0'))
    pages = math.ceil(len(entries) / page_size) if entries else 0
    result = {'page': page, 'page_size': page_size, 'pages': pages, 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)), 'items': entries[(page - 1) * page_size:page * page_size]}
    response = requests.post(endpoint, headers={'Authorization': 'Bearer ' + str(token)}, json=result)
    response.raise_for_status()
    return result

