import hashlib
import hmac
import os

def make_volunteer(volunteer_id: str, name: str, skills: list[str], password: str, availability: list[tuple[int, int]], max_minutes: int) -> dict:
    if not isinstance(volunteer_id, str) or not volunteer_id.strip() or (not isinstance(name, str)) or (not name.strip()):
        raise ValueError()
    if not isinstance(password, str) or not password:
        raise ValueError()
    if not isinstance(skills, list) or any((not isinstance(x, str) or not x for x in skills)):
        raise ValueError()
    cleaned = list(dict.fromkeys(skills))
    if not isinstance(max_minutes, int) or isinstance(max_minutes, bool) or max_minutes <= 0:
        raise ValueError()
    av = []
    for x in availability:
        if not isinstance(x, (tuple, list)) or len(x) != 2 or (not all((isinstance(n, int) and (not isinstance(n, bool)) for n in x))) or (x[0] >= x[1]):
            raise ValueError()
        if av and av[-1][1] > x[0]:
            raise ValueError()
        av.append((x[0], x[1]))
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'id': volunteer_id, 'name': name, 'skills': cleaned, 'availability': av, 'max_minutes': max_minutes, 'password': salt.hex() + '$' + digest.hex()}

def check_password(volunteer: dict, password: str) -> bool:
    try:
        salt_text, digest_text = volunteer['password'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        if not isinstance(password, str):
            return False
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError):
        return False

def assign_shifts(volunteers: list[dict], shifts: list[dict]) -> list[dict]:
    seen = set()
    for v in volunteers:
        if not isinstance(v, dict) or not isinstance(v.get('id'), str) or (not isinstance(v.get('name'), str)) or (v['id'] in seen):
            raise ValueError()
        seen.add(v['id'])
    checked = []
    ids = set()
    for s in shifts:
        if not isinstance(s, dict) or not all((k in s for k in ('id', 'skill', 'start', 'end'))) or (not isinstance(s['id'], str)) or (not isinstance(s['skill'], str)) or (not isinstance(s['start'], int)) or (not isinstance(s['end'], int)) or (s['start'] >= s['end']) or (s['id'] in ids):
            raise ValueError()
        ids.add(s['id'])
        checked.append(s)
    totals = {v['id']: 0 for v in volunteers}
    out = []
    for s in sorted(checked, key=lambda x: (x['start'], x['end'], x['id'])):
        choices = []
        for v in volunteers:
            if s['skill'] not in v.get('skills', []) or totals[v['id']] + s['end'] - s['start'] > v.get('max_minutes', -1):
                continue
            if not any((a <= s['start'] and b >= s['end'] for a, b in v.get('availability', []))):
                continue
            choices.append(v)
        if choices:
            v = min(choices, key=lambda x: (totals[x['id']], x['name'], x['id']))
            totals[v['id']] += s['end'] - s['start']
            out.append({'shift_id': s['id'], 'volunteer_id': v['id']})
    return out

