from datetime import date
from pathlib import Path
import os

def _money(value: str) -> Decimal:
    try:
        result = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid amount')
    if not result.is_finite() or result.as_tuple().exponent < -2:
        raise ValueError('invalid amount')
    return result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def _fmt(value: Decimal, signed: bool=False) -> str:
    value = value.quantize(Decimal('0.01'))
    if signed and value > 0:
        return '+' + format(value, '.2f')
    return format(value, '.2f')

def generate_statement(account_id: str, opening_balance: str, transactions: list[dict[str, str]], month: str) -> str:
    try:
        year, mon = map(int, month.split('-'))
        date(year, mon, 1)
    except (ValueError, TypeError):
        raise ValueError('invalid month')
    balance = _money(opening_balance)
    records = []
    ids = set()
    for item in transactions:
        if set(item) != {'date', 'id', 'description', 'amount', 'type', 'category'}:
            raise ValueError('invalid transaction')
        try:
            when = date.fromisoformat(item['date'])
        except (ValueError, TypeError):
            raise ValueError('invalid date')
        if item['date'][:7] != month or when.strftime('%Y-%m') != month:
            raise ValueError('wrong month')
        if not item['id'] or item['id'] in ids or (not item['description']) or ('|' in item['description']) or ('\n' in item['description']):
            raise ValueError('invalid transaction')
        if item['type'] not in ('credit', 'debit') or not item['category']:
            raise ValueError('invalid transaction')
        amount = _money(item['amount'])
        if amount <= 0:
            raise ValueError('invalid amount')
        ids.add(item['id'])
        records.append((item, when, amount))
    records.sort(key=lambda x: (x[1], x[0]['id']))
    lines = [f'ACCOUNT: {account_id}', f'PERIOD: {month}', f'OPENING BALANCE: {_fmt(balance)}']
    totals = {}
    for item, _, amount in records:
        signed = amount if item['type'] == 'credit' else -amount
        balance += signed
        totals[item['category']] = totals.get(item['category'], Decimal('0')) + signed
        lines.append(f"{item['date']} | {item['id']} | {item['description']} | {_fmt(signed, True)} | {_fmt(balance)}")
    for category in sorted(totals):
        lines.append(f'CATEGORY {category}: {_fmt(totals[category], True)}')
    lines.append(f'CLOSING BALANCE: {_fmt(balance)}')
    return '\n'.join(lines)

def write_statement(base_dir: str, filename: str, account_id: str, opening_balance: str, transactions: list[dict[str, str]], month: str) -> str:
