def generate_artifact_code(build_id: int, artifact_name: str, length: int=16) -> str:
    if isinstance(build_id, bool) or not isinstance(build_id, int) or build_id < 0:
        raise ValueError('invalid build id')
    if not isinstance(artifact_name, str) or not artifact_name or (not re.fullmatch('[A-Za-z0-9._-]+', artifact_name)):
        raise ValueError('invalid artifact name')
    if isinstance(length, bool) or not isinstance(length, int) or (not 8 <= length <= 64):
        raise ValueError('invalid length')
    alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    suffix = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'b{build_id}-{artifact_name}-{suffix}'

def summarize_artifacts(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    checked = []
    for record in records:
        if not isinstance(record, dict) or not all((k in record for k in ('name', 'size', 'kind'))):
            raise ValueError('invalid record')
        name, size, kind = (record['name'], record['size'], record['kind'])
        if not isinstance(name, str) or not name or (not isinstance(kind, str)) or (not kind):
            raise ValueError('invalid record')
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise ValueError('invalid record')
        checked.append({'name': name, 'size': size, 'kind': kind})
    totals = {}
    for record in checked:
        totals[record['kind']] = totals.get(record['kind'], 0) + record['size']
    ordered = sorted(checked, key=lambda r: (-r['size'], r['name']))
