import json
import math
import os

def save_feature_vector(base_dir: str, relative_name: str, features: list[float]) -> str:
    if not relative_name:
        raise ValueError('relative_name must not be empty')
    if not isinstance(features, list):
        raise ValueError('features must be a list')
    if any((isinstance(value, bool) or not isinstance(value, (int, float)) or (not math.isfinite(value)) for value in features)):
        raise ValueError('features must contain only finite numbers')
    os.makedirs(base_dir, exist_ok=True)
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path is outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(json.dumps(features))
    return os.path.abspath(target)

