import hashlib
import hmac
import json
from datetime import datetime, timedelta, timezone

def case_digest(cases: list[dict], config: dict[str, str]) -> dict:
    if not isinstance(cases, list) or not cases:
        raise ValueError('cases must be a non-empty list')
    token = config.get('service_token') if isinstance(config, dict) else None
    if not token:
        raise ValueError('service_token is required')
    parsed = []
    ids = set()
    for case in cases:
        if not isinstance(case, dict) or not isinstance(case.get('case_id'), str) or (not case['case_id']):
            raise ValueError('invalid case')
        if case['case_id'] in ids or not isinstance(case.get('events'), list) or (not case['events']):
            raise ValueError('invalid case')
        ids.add(case['case_id'])
        events = []
        for event in case['events']:
            if not isinstance(event, dict) or not isinstance(event.get('status'), str) or (not event['status']):
                raise ValueError('invalid event')
            try:
                at = datetime.strptime(event['at'], '%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc)
            except (TypeError, ValueError, KeyError):
                raise ValueError('invalid timestamp')
            hours = event.get('hours')
            if isinstance(hours, bool) or not isinstance(hours, (int, float)) or hours < 0:
                raise ValueError('invalid hours')
            events.append((at, event['status'], hours))
        parsed.append((case['case_id'], events))
    reference = max((event[0] for _, events in parsed for event in events))
    start = reference - timedelta(days=7)
    summaries = []
    for case_id, events in parsed:
        selected = sorted((e for e in events if start <= e[0] <= reference), key=lambda e: e[0])
        counts = {}
        total = 0
        for _, status, hours in selected:
            counts[status] = counts.get(status, 0) + 1
            total += hours
        summaries.append({'case_id': case_id, 'total_hours': total, 'status_counts': dict(sorted(counts.items())), 'latest_status': selected[-1][1] if selected else None, 'event_count': len(selected)})
    summaries.sort(key=lambda x: (-x['total_hours'], x['case_id']))
    payload = json.dumps(summaries, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(token.encode(), payload, hashlib.sha256).hexdigest()
    return {'cases': summaries, 'signature': signature}

