import csv
import io
import subprocess

def build_timetable_report(path: str, station: str, page: int, page_size: int) -> list[dict[str, object]]:
    if not station or page < 1 or page_size < 1 or (page_size > 100):
        raise ValueError('invalid arguments')
    result = subprocess.run(['cat', path], check=True, capture_output=True, text=True)
    reader = csv.DictReader(io.StringIO(result.stdout), skipinitialspace=False)
    expected = ['train', 'station', 'departure', 'platform', 'destination']
    if reader.fieldnames != expected:
        raise ValueError('invalid header')
    rows = []
    for row in reader:
        if None in row or any((value is None for value in row.values())):
            raise ValueError('invalid row')
        values = {key: value.strip() for key, value in row.items()}
        if not values['train'] or not values['station'] or (not values['destination']):
            raise ValueError('invalid row')
        parts = values['departure'].split(':')
        if len(parts) != 2 or len(parts[0]) != 2 or len(parts[1]) != 2:
            raise ValueError('invalid time')
        try:
            hour, minute = (int(parts[0]), int(parts[1]))
            platform = int(values['platform'])
        except ValueError as exc:
            raise ValueError('invalid row') from exc
        if not 0 <= hour <= 23 or not 0 <= minute <= 59 or platform <= 0:
            raise ValueError('invalid row')
        if values['station'] == station:
            rows.append((hour * 60 + minute, platform, values['train'], {'train': values['train'], 'departure': values['departure'], 'platform': platform, 'destination': values['destination']}))
    rows.sort(key=lambda item: item[:3])
    start = (page - 1) * page_size
    return [item[3] for item in rows[start:start + page_size]]

