import hmac
import json
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Optional
_KEY = b'timber-permit-webhook-v1'

def summarize_harvest_webhook(payload: bytes, signature: str, page: int=1, page_size: int=10, year: Optional[int]=None) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    if year is not None and (not isinstance(year, int) or isinstance(year, bool) or (not 1900 <= year <= 2100)):
        raise ValueError('invalid year')
    if not isinstance(signature, str):
        raise PermissionError('invalid signature')
    expected = hmac.new(_KEY, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise PermissionError('invalid signature')
    try:
        root = json.loads(payload.decode('utf-8'))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(root, dict) or not isinstance(root.get('permits'), list):
        raise ValueError('invalid permits')
    totals = {}
    for item in root['permits']:
        if not isinstance(item, dict):
            raise ValueError('invalid permit')
        county = item.get('county')
        acres = item.get('acres')
        fee = item.get('fee_cents')
        status = item.get('status')
        record_year = item.get('year')
        if not isinstance(county, str) or not county.strip():
            raise ValueError('invalid county')
        if isinstance(acres, bool) or not isinstance(acres, (int, float)) or (not math.isfinite(acres)) or (acres <= 0):
            raise ValueError('invalid acres')
        if isinstance(fee, bool) or not isinstance(fee, int) or fee < 0:
            raise ValueError('invalid fee')
        if not isinstance(status, str):
            raise ValueError('invalid status')
        if isinstance(record_year, bool) or not isinstance(record_year, int) or (not 1900 <= record_year <= 2100):
            raise ValueError('invalid record year')
        if status == 'approved' and (year is None or record_year == year):
            name = county.strip()
            if name not in totals:
                totals[name] = [0, Decimal('0'), 0]
            totals[name][0] += 1
            try:
                totals[name][1] += Decimal(str(acres))
            except InvalidOperation as exc:
                raise ValueError('invalid acres') from exc
            totals[name][2] += fee
    groups = []
    for county, (count, acres, fee) in totals.items():
        rounded = acres.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        groups.append({'county': county, 'permit_count': count, 'total_acres': float(rounded), 'total_fee_cents': fee})
    groups.sort(key=lambda x: (-x['permit_count'], -x['total_acres'], x['county']))
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_groups': len(groups), 'groups': groups[start:start + page_size]}

