import re
import secrets
import string

def generate_transfer_code(record_id: str, length: int=12) -> str:
    if not isinstance(record_id, str):
        raise TypeError('record_id must be a string')
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError('length must be an integer')
    if length < 8 or length > 64:
        raise ValueError('length must be between 8 and 64')
    record_id = record_id.strip().upper()
    if not record_id or re.fullmatch('[A-Z0-9-]+', record_id) is None:
        raise ValueError('invalid record_id')
    alphabet = string.ascii_uppercase + string.digits
    token = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'ARCH-{record_id}-{token}'

