import pytest

def test_parses_multiple_shifts_in_document_order():
    xml = '\n        <schedule>\n          <shift driver="Ava" route="12" start="06:30" end="14:30"/>\n          <shift driver="Ben" route="7" start="14:00" end="22:00"/>\n        </schedule>\n    '
    assert parse_driver_schedule(xml) == [{'driver': 'Ava', 'route': '12', 'start': '06:30', 'end': '14:30'}, {'driver': 'Ben', 'route': '7', 'start': '14:00', 'end': '22:00'}]

def test_empty_schedule_returns_empty_list():
    assert parse_driver_schedule('<schedule></schedule>') == []

def test_rejects_non_string_input():
    with pytest.raises(TypeError):
        parse_driver_schedule(b'<schedule/>')

def test_rejects_malformed_xml():
    with pytest.raises(ValueError):
        parse_driver_schedule("<schedule><shift driver='A'></schedule>")

def test_rejects_wrong_root_element():
    with pytest.raises(ValueError):
        parse_driver_schedule("<routes><shift driver='A' route='1' start='06:00' end='14:00'/></routes>")

def test_rejects_non_shift_direct_child():
    with pytest.raises(ValueError):
        parse_driver_schedule('<schedule><break/></schedule>')

def test_rejects_shift_missing_required_attribute():
    with pytest.raises(ValueError):
        parse_driver_schedule("<schedule><shift driver='A' route='1' start='06:00'/></schedule>")

