from lxml import etree

def parse_driver_schedule(xml_text: str) -> list[dict[str, str]]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'schedule':
        raise ValueError('root must be schedule')
    required = ('driver', 'route', 'start', 'end')
    result = []
    for child in root:
        if not isinstance(child.tag, str) or child.tag != 'shift':
            raise ValueError('invalid schedule child')
        if any((name not in child.attrib for name in required)):
            raise ValueError('shift is missing an attribute')
        result.append({name: child.attrib[name] for name in required})
    return result

