import csv
import datetime
import tempfile

def export_cleaning_schedule(bookings: list[dict], start_date: str, end_date: str) -> str:

    def parse_date(value):
        try:
            result = datetime.date.fromisoformat(value)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if result.isoformat() != value:
            raise ValueError('invalid date')
        return result
    first = parse_date(start_date)
    last = parse_date(end_date)
    if first > last:
        raise ValueError('invalid date range')
    groups = {}
    required = {'reservation_id', 'property', 'checkout', 'guests', 'turnover_minutes'}
    for booking in bookings:
        if not isinstance(booking, dict) or not required.issubset(booking):
            raise ValueError('invalid booking')
        if not isinstance(booking['reservation_id'], str) or not booking['reservation_id']:
            raise ValueError('invalid booking')
        if not isinstance(booking['property'], str) or not booking['property']:
            raise ValueError('invalid booking')
        checkout = parse_date(booking['checkout'])
        for key in ('guests', 'turnover_minutes'):
            if isinstance(booking[key], bool) or not isinstance(booking[key], int) or booking[key] < 0:
                raise ValueError('invalid booking')
        if first <= checkout <= last:
            key = (checkout, booking['property'])
            row = groups.setdefault(key, [0, 0, 0])
            row[0] += 1
            row[1] += booking['guests']
            row[2] += booking['turnover_minutes']
    handle = tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', newline='', delete=False)
    try:
        writer = csv.writer(handle)
        writer.writerow(['checkout', 'property', 'bookings', 'guests', 'turnover_minutes'])
        for (checkout, property_name), values in sorted(groups.items()):
            writer.writerow([checkout.isoformat(), property_name, *values])
