            fetch_field_conditions("  \t", "key")
    get.assert_not_called()


def test_non_success_status_raises_runtime_error():
    response = make_response(503, {"message": "unavailable"})
    with patch("solution.requests.get", return_value=response):
        with pytest.raises(RuntimeError, match="503"):
            fetch_field_conditions("plot-4", "key")


