from datetime import date

class BoardMaterials:

    def __init__(self, password: str):
        if not isinstance(password, str) or not password:
            raise ValueError('invalid password')
        self._salt = os.urandom(16)
        self._digest = hashlib.pbkdf2_hmac('sha256', password.encode(), self._salt, 100000)
        self._materials = []
        self._active = False

    def add_material(self, line: str) -> None:
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError('invalid material')
        raw_date, title, raw_pages, raw_tags = fields
        try:
            parsed = date.fromisoformat(raw_date)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        if parsed.isoformat() != raw_date or not title:
            raise ValueError('invalid material')
        if not raw_pages.isdecimal() or int(raw_pages) <= 0:
            raise ValueError('invalid pages')
        tags = [x.strip() for x in raw_tags.split(',') if x.strip()]
        item = {'date': raw_date, 'title': title, 'pages': int(raw_pages), 'tags': tags}
        if any((x['date'] == raw_date and x['title'] == title for x in self._materials)):
            raise ValueError('duplicate material')
        self._materials.append(item)

    def authenticate(self, password: str) -> bool:
        if not isinstance(password, str):
            self._active = False
            return False
        value = hashlib.pbkdf2_hmac('sha256', password.encode(), self._salt, 100000)
        self._active = value == self._digest
        return self._active

    def report(self, start: str, end: str) -> dict:
        if not self._active:
            raise PermissionError('authentication required')
        try:
            first, last = (date.fromisoformat(start), date.fromisoformat(end))
        except ValueError:
            raise ValueError('invalid range')
        if first.isoformat() != start or last.isoformat() != end or first > last:
            raise ValueError('invalid range')
        selected = [x for x in self._materials if start <= x['date'] <= end]
        selected.sort(key=lambda x: (x['date'], x['title']))
        pages = sum((x['pages'] for x in selected))
        counts = {}
        for item in selected:
            for tag in item['tags']:
                counts[tag] = counts.get(tag, 0) + 1
        ordered = {key: counts[key] for key in sorted(counts)}
        return {'materials': selected, 'pages': pages, 'tags': ordered}

