import os
import subprocess
from decimal import Decimal, ROUND_HALF_UP

def analyze_backups(paths: list[str], min_size: int, page: int, page_size: int) -> dict:
    if min_size < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid pagination or size')
    groups = {}
    for path in paths:
        completed = subprocess.run(['wc', '-c', path], check=True, capture_output=True, text=True)
        size = int(completed.stdout.split()[0])
        if size < min_size:
            continue
        base = os.path.basename(path)
        if '.' not in base or base.endswith('.') or (base.startswith('.') and base.count('.') == 1):
            extension = ''
        else:
            extension = os.path.splitext(base)[1].lower()
        item = groups.setdefault(extension, [0, 0])
        item[0] += 1
        item[1] += size
    output = []
    for extension, (count, total) in groups.items():
        average = float(Decimal(total / count).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        output.append({'extension': extension, 'count': count, 'total_bytes': total, 'average_bytes': average})
    output.sort(key=lambda item: (-item['total_bytes'], item['extension']))
