import base64
import hashlib
import hmac
import json

def create_session_cookie(user: dict, session_id: str, issued_at: int, lifetime: int, key: str) -> str:
    if not isinstance(user, dict) or not isinstance(session_id, str) or (not session_id) or (not isinstance(issued_at, int)) or isinstance(issued_at, bool) or (not isinstance(lifetime, int)) or isinstance(lifetime, bool) or (lifetime <= 0) or (not isinstance(key, str)):
        raise ValueError('invalid arguments')
    if not isinstance(user.get('id'), str) or not user['id'] or (not isinstance(user.get('tenant'), str)) or (not user['tenant']):
        raise ValueError('invalid user')
    payload = {'sid': session_id, 'uid': user['id'], 'tenant': user['tenant'], 'iat': issued_at, 'exp': issued_at + lifetime}
    raw = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()
    body = base64.urlsafe_b64encode(raw).decode().rstrip('=')
    sig = hmac.new(key.encode(), body.encode(), hashlib.sha256).digest()
    return body + '.' + base64.urlsafe_b64encode(sig).decode().rstrip('=')

def read_session_cookie(cookie: str, key: str, now: int) -> dict:
    try:
        if not isinstance(cookie, str) or not isinstance(key, str) or (not isinstance(now, int)) or (cookie.count('.') != 1):
            raise ValueError
        body, encoded = cookie.split('.')
        given = base64.urlsafe_b64decode(encoded + '=' * (-len(encoded) % 4))
        expected = hmac.new(key.encode(), body.encode(), hashlib.sha256).digest()
        if not hmac.compare_digest(given, expected):
            raise ValueError
        data = json.loads(base64.urlsafe_b64decode(body + '=' * (-len(body) % 4)).decode())
        if set(data) != {'sid', 'uid', 'tenant', 'iat', 'exp'} or not isinstance(data['sid'], str) or (not data['sid']) or (not isinstance(data['uid'], str)) or (not data['uid']) or (not isinstance(data['tenant'], str)) or (not data['tenant']) or any((not isinstance(data[x], int) or isinstance(data[x], bool) for x in ('iat', 'exp'))) or (data['exp'] <= data['iat']) or (data['exp'] <= now):
            raise ValueError
        return {'session_id': data['sid'], 'user_id': data['uid'], 'tenant': data['tenant'], 'issued_at': data['iat'], 'expires_at': data['exp']}
    except (ValueError, TypeError, KeyError, json.JSONDecodeError, UnicodeError, base64.binascii.Error):
        raise ValueError('invalid cookie')

def revoke_sessions(requester: dict, sessions: list[dict], session_ids: list[str], now: int) -> list[dict]:
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant'), str)) or (not isinstance(requester.get('roles'), list)) or (not isinstance(sessions, list)) or (not isinstance(session_ids, list)) or (not isinstance(now, int)) or isinstance(now, bool) or (now < 0):
        raise ValueError('invalid arguments')
    for s in sessions:
        if not isinstance(s, dict) or not isinstance(s.get('id'), str) or (not isinstance(s.get('user_id'), str)) or (not isinstance(s.get('tenant'), str)) or (not isinstance(s.get('issued_at'), int)) or (not isinstance(s.get('expires_at'), int)) or (not isinstance(s.get('revoked'), bool)):
            raise ValueError('invalid session')
    lookup = {s['id']: s for s in sessions}
    result = []
    seen = set()
    for sid in session_ids:
        if not isinstance(sid, str) or sid in seen:
            continue
        seen.add(sid)
        s = lookup.get(sid)
        if not s or s['revoked'] or s['expires_at'] <= now:
            continue
        allowed = s['tenant'] == requester['tenant'] and (s['user_id'] == requester['id'] or 'sso_admin' in requester['roles'])
        if allowed:
            copy = dict(s)
            copy['revoked'] = True
            result.append(copy)
    return result

