def release_report(releases: list[dict], requester: dict, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    valid = {'queued', 'running', 'succeeded', 'failed'}
    if status is not None and status not in valid:
        raise ValueError('invalid status')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    if not isinstance(requester, dict) or not isinstance(requester.get('id'), str) or (not isinstance(requester.get('tenant_id'), str)) or (not isinstance(requester.get('roles'), list)):
        raise ValueError('invalid requester')
    selected = []
    for release in releases:
        try:
            required = {'id', 'app', 'version', 'status', 'created_at', 'duration_seconds', 'tenant_id', 'owner_id'}
            if not required.issubset(release) or any((not isinstance(release[x], str) for x in ('id', 'app', 'version', 'status', 'tenant_id', 'owner_id'))):
                raise ValueError
            if release['status'] not in valid or (status is not None and release['status'] != status):
                continue
            if isinstance(release['duration_seconds'], bool) or not isinstance(release['duration_seconds'], (int, float)) or release['duration_seconds'] < 0:
                raise ValueError
            timestamp = datetime.fromisoformat(release['created_at'].replace('Z', '+00:00'))
            if not (release['tenant_id'] == requester['tenant_id'] and (release['owner_id'] == requester['id'] or 'release_manager' in requester['roles'] or 'admin' in requester['roles'])):
                continue
            selected.append((timestamp, release))
        except (TypeError, KeyError, ValueError):
            raise ValueError('invalid release')
    selected.sort(key=lambda pair: (-pair[0].timestamp(), pair[1]['id']))
    start = (page - 1) * page_size
    items = [{'id': r['id'], 'app': r['app'], 'version': r['version'], 'status': r['status'], 'created_at': r['created_at'], 'duration_minutes': round(r['duration_seconds'] / 60, 2)} for _, r in selected[start:start + page_size]]
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'items': items}

