import csv
import heapq
import os
from pathlib import Path

def _minutes(value):
    if not isinstance(value, str) or len(value) != 5 or value[2] != ':':
        raise ValueError
    try:
        hour, minute = (int(value[:2]), int(value[3:]))
    except ValueError:
        raise ValueError
    if not 0 <= hour <= 23 or not 0 <= minute <= 59:
        raise ValueError
    return hour * 60 + minute

def allocate_gates(flights: list[dict], gate_count: int) -> list[dict]:
    if not isinstance(gate_count, int) or isinstance(gate_count, bool) or gate_count <= 0:
        raise ValueError
    seen = set()
    prepared = []
    for item in flights:
        if not isinstance(item, dict) or not isinstance(item.get('flight'), str):
            raise ValueError
        ident = item['flight']
        if ident in seen:
            raise ValueError
        seen.add(ident)
        arrival, departure = (_minutes(item.get('arrival')), _minutes(item.get('departure')))
        if departure <= arrival:
            raise ValueError
        priority = item.get('priority', 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise ValueError
        prepared.append((arrival, -priority, ident, departure, len(prepared)))
    prepared.sort(key=lambda x: x[:3])
    free = list(range(1, gate_count + 1))
    busy = []
    result = [None] * len(prepared)
    for arrival, _, ident, departure, original in prepared:
        while busy and busy[0][0] <= arrival:
            _, gate = heapq.heappop(busy)
            heapq.heappush(free, gate)
        if not free:
            raise ValueError
        gate = heapq.heappop(free)
        heapq.heappush(busy, (departure, gate))
        result[original] = {'flight': ident, 'gate': gate}
    return result

def write_allocation_report(base_dir: str, relative_name: str, assignments: list[dict]) -> str:
    base = Path(base_dir)
    if not base.is_dir() or not isinstance(relative_name, str) or (not relative_name):
        raise ValueError
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base.resolve())
    except ValueError:
        raise ValueError
    for item in assignments:
        if not isinstance(item, dict) or not isinstance(item.get('flight'), str) or (not isinstance(item.get('gate'), int)) or isinstance(item.get('gate'), bool) or (item['gate'] <= 0):
            raise ValueError
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['flight', 'gate'])
        for item in assignments:
            writer.writerow([item['flight'], item['gate']])
    return str(target)

