import json

import pytest

from solution import analyze_log


def make_payload(events):
    return json.dumps({"events": events}, separators=(",", ":"))


def signed(payload, secret=b"station-key"):
    return hmac.new(secret, payload.encode(), hashlib.sha256).hexdigest()


def test_empty_log_returns_empty_result():
    payload = make_payload([])
    assert analyze_log(payload, signed(payload), b"station-key", 0, 100) == {
        "total_events": 0,
        "detectors": [],
    }


def test_filters_inclusive_bounds_and_aggregates():
    events = [
        {"timestamp": 10, "detector": "D1", "counts": 5},
        {"timestamp": 20, "detector": "D1", "counts": 8},
        {"timestamp": 20, "detector": "D2", "counts": 20},
        {"timestamp": 21, "detector": "D2", "counts": 99},
    ]
    payload = make_payload(events)
    assert analyze_log(payload, signed(payload), b"station-key", 10, 20) == {
        "total_events": 3,
        "detectors": [
            {"detector": "D2", "events": 1, "counts": 20, "average": 20.0},
            {"detector": "D1", "events": 2, "counts": 13, "average": 6.5},
        ],
    }


def test_ties_are_sorted_by_detector_name():
    events = [
        {"timestamp": 1, "detector": "Z", "counts": 4},
        {"timestamp": 2, "detector": "A", "counts": 4},
        {"timestamp": 3, "detector": "M", "counts": 4},
    ]
    payload = make_payload(events)
    result = analyze_log(payload, signed(payload), b"station-key", 1, 3)
    assert [x["detector"] for x in result["detectors"]] == ["A", "M", "Z"]


def test_pagination_is_applied_after_sorting():
    events = [
        {"timestamp": i, "detector": name, "counts": count}
        for i, (name, count) in enumerate([("A", 1), ("B", 5), ("C", 3), ("D", 4)])
    ]
    payload = make_payload(events)
    result = analyze_log(payload, signed(payload), b"station-key", 0, 10, page=1, page_size=2)
    assert result["total_events"] == 4
    assert result["detectors"] == [
        {"detector": "C", "events": 1, "counts": 3, "average": 3.0},
        {"detector": "A", "events": 1, "counts": 1, "average": 1.0},
    ]


def test_signature_rejection_happens_for_bad_signature():
    payload = make_payload([])
    with pytest.raises(PermissionError):
        analyze_log(payload, "00", b"station-key", 0, 1)


def test_invalid_json_and_event_shape_raise_value_error():
    with pytest.raises(ValueError):
        analyze_log("{\"events\": []} trailing", signed('{"events": []} trailing'), b"station-key", 0, 1)
    payload = make_payload([{"timestamp": 1, "detector": "D1", "counts": -1}])
    with pytest.raises(ValueError):
        analyze_log(payload, signed(payload), b"station-key", 0, 1)


def test_invalid_ranges_pagination_and_missing_events_raise_value_error():
    payload = make_payload([])
    with pytest.raises(ValueError):
        analyze_log(payload, signed(payload), b"station-key", 3, 2)
    with pytest.raises(ValueError):
        analyze_log(payload, signed(payload), b"station-key", 0, 1, page=-1)
    with pytest.raises(ValueError):
        analyze_log(payload, signed(payload), b"station-key", 0, 1, page_size=0)
    missing = "{}"
    with pytest.raises(ValueError):
        analyze_log(missing, signed(missing), b"station-key", 0, 1)

