def eligible_claims(conn: sqlite3.Connection, passenger_id: str, minimum_delay: int=180, sort_by: str='delay') -> list[dict[str, object]]:
    if minimum_delay < 0:
        raise ValueError('minimum_delay must not be negative')
    order = {'delay': 'f.delay_minutes DESC, c.claim_id ASC', 'compensation': 'c.compensation DESC, c.claim_id ASC', 'flight_no': 'f.flight_no ASC, c.claim_id ASC'}
    if sort_by not in order:
        raise ValueError('unsupported sort')
    rows = conn.execute('SELECT c.claim_id, f.flight_no, f.delay_minutes, c.status, c.compensation FROM claims c JOIN flights f ON f.flight_id = c.flight_id WHERE f.passenger_id = ? AND f.delay_minutes >= ? ORDER BY ' + order[sort_by], (passenger_id, minimum_delay)).fetchall()
    return [dict(row) for row in rows]

