    rows = conn.execute('SELECT f.flight_id, f.delay_minutes, c.status, c.compensation FROM flights f JOIN claims c ON c.flight_id = f.flight_id WHERE f.origin = ? AND f.departure_date >= ? AND f.departure_date <= ?', (origin, start_date, end_date)).fetchall()
    statuses = {}
    for row in rows:
        statuses[row['status']] = statuses.get(row['status'], 0) + 1
    delays = [row['delay_minutes'] for row in rows]
    return {'flight_count': len({row['flight_id'] for row in rows}), 'claim_count': len(rows), 'total_compensation': sum((row['compensation'] for row in rows)), 'average_delay': sum(delays) / len(delays) if delays else None, 'statuses': {key: statuses[key] for key in sorted(statuses)}}

