import hashlib
import os
import hmac

def encode_pin(pin: str) -> str:
    if not isinstance(pin, str) or not pin.isascii() or (not pin.isdigit()) or (not 4 <= len(pin) <= 8):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_pin(pin: str, encoded: str) -> bool:
    if not isinstance(pin, str) or not pin.isascii() or (not pin.isdigit()) or (not 4 <= len(pin) <= 8) or (not isinstance(encoded, str)):
        return False
    try:
        salt_text, digest_text = encoded.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def generate_disclosure(items: list[dict], page: int, page_size: int) -> dict:
    sections = ['Loan Costs', 'Other Costs', 'Taxes and Other Government Charges']
    if not isinstance(items, list) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid arguments')
    cleaned = []
    for item in items:
        if not isinstance(item, dict) or set(item) != {'section', 'label', 'amount'}:
            raise ValueError('invalid item')
        section, label, amount = (item['section'], item['label'], item['amount'])
        if section not in sections or not isinstance(label, str) or (not label) or (not isinstance(amount, int)) or isinstance(amount, bool) or (amount < 0):
            raise ValueError('invalid item')
        cleaned.append((sections.index(section), section, label, amount))
    cleaned.sort(key=lambda x: (x[0], -x[3], x[2]))
    start = (page - 1) * page_size
    selected = cleaned[start:start + page_size]
    grouped = {name: [] for name in sections}
    for _, section, label, amount in selected:
        grouped[section].append({'label': label, 'amount': f'{amount / 100:.2f}'})
    output_sections = []
    for name in sections:
        entries = grouped[name]
        if entries:
            subtotal = sum((round(float(x['amount']) * 100) for x in entries))
            output_sections.append({'name': name, 'subtotal': f'{subtotal / 100:.2f}', 'items': entries})
    total = sum((x[3] for x in cleaned))
    return {'page': page, 'page_size': page_size, 'total_items': len(cleaned), 'total_amount': f'{total / 100:.2f}', 'sections': output_sections}

