from lxml import etree
from datetime import datetime

def parse_appointment(xml_text: str) -> dict:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'appointment':
        raise ValueError('invalid root')
    allowed = {'client_id', 'counselor', 'date', 'start_time', 'duration_minutes', 'location', 'notes'}
    values = {}
    for child in root:
        if child.tag not in allowed or child.tag in values:
            raise ValueError('invalid child element')
        values[child.tag] = (child.text or '').strip()
    required = ('client_id', 'counselor', 'date', 'start_time', 'duration_minutes', 'location')
    if any((not values.get(name) for name in required)):
        raise ValueError('missing value')
    try:
        datetime.strptime(values['date'], '%Y-%m-%d')
        datetime.strptime(values['start_time'], '%H:%M')
        duration = int(values['duration_minutes'])
    except (ValueError, TypeError) as exc:
        raise ValueError('invalid appointment value') from exc
    if str(duration) != values['duration_minutes'] or duration <= 0:
        raise ValueError('invalid duration')
    return {'client_id': values['client_id'], 'counselor': values['counselor'], 'date': values['date'], 'start_time': values['start_time'], 'duration_minutes': duration, 'location': values['location'], 'notes': values.get('notes', '')}

