from typing import Any

def publish_report(requester: dict[str, Any], report: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(requester, dict) or not isinstance(report, dict):
        raise TypeError('requester and report must be dictionaries')
    required_requester = ('id', 'tenant_id', 'roles')
    required_report = ('id', 'title', 'owner_id', 'tenant_id', 'status', 'values')
    if any((key not in requester for key in required_requester)) or any((key not in report for key in required_report)):
        raise ValueError('missing required field')
    if report['status'] != 'draft':
        raise ValueError('report is not a draft')
    if not isinstance(report['values'], list) or any((not isinstance(value, (int, float)) or isinstance(value, bool) for value in report['values'])):
        raise ValueError('values must be numeric')
    if requester['tenant_id'] != report['tenant_id'] or (requester['id'] != report['owner_id'] and (not set(requester['roles']) & {'statistician', 'admin'})):
        raise PermissionError('not permitted to publish report')
    result = report.copy()
    result['values'] = report['values'].copy()
    result['status'] = 'published'
    result['published_by'] = requester['id']
    return result

import os
from datetime import date, datetime, timedelta

def build_hearing_manifest(hearings: list[dict], hearing_date: str, court_code: str, config: dict[str, str] | None=None) -> dict:
    try:
        date.fromisoformat(hearing_date)
    except (TypeError, ValueError):
        raise ValueError('invalid hearing date')
    token = None
    if config is not None:
        token = config.get('COURT_SERVICE_TOKEN')
    if token is None:
        token = os.environ.get('COURT_SERVICE_TOKEN')
    if not token:
        raise ValueError('COURT_SERVICE_TOKEN is required')
    selected = []
    for hearing in hearings:
        try:
            status = hearing['status']
            if status not in {'scheduled', 'adjourned', 'cancelled'}:
                raise ValueError('invalid status')
            start = datetime.strptime(hearing['start'], '%H:%M')
            duration = hearing['duration_minutes']
            if type(duration) is not int or duration < 0:
                raise ValueError('invalid duration')
            if hearing['court'] != court_code or hearing['date'] != hearing_date or status == 'cancelled':
                continue
            end = (start + timedelta(minutes=duration)).strftime('%H:%M')
            selected.append((hearing['start'], hearing['room'], hearing['id'], {'id': hearing['id'], 'room': hearing['room'], 'start': hearing['start'], 'end': end, 'status': status}, duration))
        except KeyError:
            raise ValueError('invalid hearing')
        except ValueError:
            raise
    selected.sort(key=lambda item: item[:3])
    return {'court': court_code, 'date': hearing_date, 'authorization': 'Bearer ' + token, 'hearings': [item[3] for item in selected], 'total_minutes': sum((item[4] for item in selected))}

