            raise ValueError('invalid record')
        if not isinstance(item['measured'], (int, float)) or not isinstance(item['target'], (int, float)):
            raise ValueError('invalid record')
        if not math.isfinite(item['measured']) or not math.isfinite(item['target']):
            raise ValueError('invalid record')
        try:
            date.fromisoformat(item['inspected_on'])
        except (TypeError, ValueError):
            raise ValueError('invalid record')
