            variance = round(item['measured'] - item['target'], 2)
            included.append({'asset': item['asset'], 'system': item['system'], 'status': item['status'], 'measured': float(item['measured']), 'target': float(item['target']), 'variance': variance, 'inspected_on': item['inspected_on']})
