    total = len(included)
    pages = (total + page_size - 1) // page_size
    selected = included[(page - 1) * page_size:page * page_size]
    fields = ['asset', 'system', 'status', 'measured', 'target', 'variance', 'inspected_on']
    directory = os.path.dirname(os.path.abspath(output_path))
