def fetch_material_stats(api_url: str, materials: list[str], min_temperature: float, max_temperature: float, page_size: int=100) -> list[dict]:
    if not materials or len(set(materials)) != len(materials):
        raise ValueError('materials must be nonempty and unique')
    if min_temperature > max_temperature:
        raise ValueError('invalid temperature range')
    if page_size <= 0:
        raise ValueError('page_size must be positive')
    wanted = set(materials)
    groups = {}
    page = 1
    while True:
        response = requests.get(api_url, params={'page': page, 'page_size': page_size}, headers={'Accept': 'application/json'}, timeout=10)
