        if not isinstance(data, dict) or not isinstance(data.get('results'), list):
            raise ValueError('invalid response')
        for record in data['results']:
            if record['material'] in wanted and min_temperature <= record['temperature_c'] <= max_temperature and (record['passed'] is True):
                groups.setdefault(record['material'], []).append(record['strength_mpa'])
        if not data.get('next'):
            break
        page += 1
    result = []
    for material, strengths in groups.items():
        result.append({'material': material, 'count': len(strengths), 'average_strength_mpa': round(sum(strengths) / len(strengths), 2), 'maximum_strength_mpa': round(max(strengths), 2)})
    result.sort(key=lambda item: (-item['count'], -item['average_strength_mpa'], item['material']))
