from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def extract_bundle(archive_path: str, output_dir: str) -> list[str]:
    base = os.path.realpath(output_dir)
    os.makedirs(base, exist_ok=True)
    written = []
    with zipfile.ZipFile(archive_path, 'r') as archive:
        for member in archive.infolist():
            name = member.filename
            if name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(base, name))
            if target != base and (not target.startswith(base + os.sep)):
                raise ValueError('member outside output directory')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, 'wb') as handle:
                handle.write(archive.read(member))
            written.append(name)
    return sorted(written)

def _parts(line):
    result = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    result.append(''.join(current))
    return result

def _day(value):
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def summarize_maintenance_log(text: str, as_of: str) -> dict[str, dict[str, object]]:
    cutoff = _day(as_of)
    groups = {}
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _parts(raw)
        if len(fields) != 5:
            raise ValueError('invalid record')
        day = _day(fields[0].strip())
        system = fields[1].strip()
        if not system:
            raise ValueError('empty system')
        try:
            hours = Decimal(fields[2].strip())
        except InvalidOperation:
            raise ValueError('invalid hours')
        if not hours.is_finite() or hours < 0:
            raise ValueError('invalid hours')
        status = fields[3].strip()
        if status not in ('completed', 'open'):
            raise ValueError('invalid status')
        item = groups.setdefault(system, {'hours': Decimal('0'), 'completed': 0, 'open': 0, 'latest': day, 'overdue': 0})
        item['hours'] += hours
        item[status] += 1
        if day > item['latest']:
            item['latest'] = day
        if status == 'open' and day < cutoff:
            item['overdue'] += 1
    result = {}
    for system in sorted(groups):
        item = groups[system]
        total = item['hours'].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result[system] = {'hours': float(total), 'completed': item['completed'], 'open': item['open'], 'latest': item['latest'].isoformat(), 'overdue': item['overdue']}
    return result

