    try:
        tree = ast.parse(rule, mode='eval').body
    except Exception as exc:
        raise ValueError('invalid rule') from exc

    def ev(n, names):
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float, bool)):
            return n.value
        if isinstance(n, ast.Name) and n.id in names:
            return names[n.id]
        if isinstance(n, ast.UnaryOp) and type(n.op) in (ast.UAdd, ast.USub, ast.Not):
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(n.op)](ev(n.operand, names))
        if isinstance(n, ast.BinOp) and type(n.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(n.op)](ev(n.left, names), ev(n.right, names))
        if isinstance(n, ast.BoolOp) and type(n.op) in (ast.And, ast.Or):
            vals = [ev(x, names) for x in n.values]
            result = vals[0]
            for value in vals[1:]:
                result = value if (bool(result) if isinstance(n.op, ast.And) else not bool(result)) else result
            return result
        if isinstance(n, ast.Compare) and len(n.ops) == len(n.comparators):
            vals = [ev(n.left, names)] + [ev(x, names) for x in n.comparators]
            funcs = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
            return all((funcs[type(op)](a, b) for op, a, b in zip(n.ops, vals, vals[1:])))
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and (n.func.id in ('min', 'max', 'round')) and (not n.keywords):
            return {'min': min, 'max': max, 'round': round}[n.func.id](*(ev(x, names) for x in n.args))
        raise ValueError('unsupported rule')
    result = []
    for exhibit in exhibits:
        names = {'age': visitor_age, 'duration': exhibit['duration'], 'rating': exhibit['rating'], 'capacity': exhibit['capacity'], 'family_friendly': exhibit.get('family_friendly', False)}
