def extract_housekeeping_archive(archive_path: str, destination: str) -> list[tuple[str, int, int]]:
    base = Path(destination).resolve()
    base.mkdir(parents=True, exist_ok=True)
    totals: dict[str, list[int]] = {}
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if info.is_dir() or not name.startswith('reports/') or (not name.endswith('.csv')):
                continue
            target = (base / name).resolve()
            try:
                target.relative_to(base)
            except ValueError:
                raise ValueError('archive member is outside destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info, 'r') as source, target.open('wb') as output:
                output.write(source.read())
            with target.open('r', newline='') as handle:
                for row in csv.reader(handle):
                    if not row:
                        continue
                    if len(row) != 3:
                        raise ValueError('invalid report row')
                    room, status, minutes_text = row
                    if not room or status not in {'done', 'pending'}:
                        raise ValueError('invalid report row')
                    try:
                        minutes = int(minutes_text, 10)
                    except ValueError:
                        raise ValueError('invalid report row')
                    if minutes < 0:
                        raise ValueError('invalid report row')
                    entry = totals.setdefault(room, [0, 0])
                    entry[0] += status == 'done'
                    entry[1] += minutes
    return [(room, totals[room][0], totals[room][1]) for room in sorted(totals)]

