        except ValueError:
            raise ValueError('invalid minutes')
        if minutes < 0:
            raise ValueError('invalid minutes')
        usage[row[0]] = usage.get(row[0], 0) + minutes
    return {'license_id': rows[0][0], 'tenant_id': rows[0][1], 'owner_id': rows[0][2], 'seats': seats, 'expires_at': expires, 'usage': usage, 'activations': []}

