        if item['device_id'] == device_id:
            found = item
            break
    if found is None:
        if len(result['activations']) >= result['seats']:
            raise ValueError('no seats')
        result['activations'].append({'device_id': device_id, 'user_id': requester['id'], 'activated_at': at})
    else:
