            except (ValueError, InvalidOperation) as exc:
                raise ValueError('invalid payment') from exc
            if not amount.is_finite() or amount < 0:
                raise ValueError('invalid payment')
            paid += amount
            if last is None or when > last:
                last = when
        records.append({'plate': plate, 'vin': vin, 'owner': owner_node.text.strip(), 'due': due, 'currency': currency, 'fee': fee, 'paid': paid, 'balance': fee - paid, 'status': status, 'last_payment': last})
    return records

