def find_articles(conn: sqlite3.Connection, search: str='', category: str | None=None, sort_by: str='newest', page: int=1, page_size: int=20) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be a positive integer')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size out of range')
    ordering = {'newest': 'created_at DESC, id ASC', 'oldest': 'created_at ASC, id ASC', 'title': 'title ASC, id ASC', 'id': 'id ASC'}
    if sort_by not in ordering:
        raise ValueError('invalid sort_by')
    if not isinstance(search, str) or (category is not None and (not isinstance(category, str))):
        raise ValueError('invalid filter')
    term = search.strip()
    clauses = []
    args = []
    if term:
        clauses.append('(title LIKE ? COLLATE NOCASE OR body LIKE ? COLLATE NOCASE)')
        pattern = '%' + term + '%'
        args.extend([pattern, pattern])
    if category is not None:
        clauses.append('category = ?')
        args.append(category)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    total = conn.execute('SELECT COUNT(*) FROM articles' + where, args).fetchone()[0]
    offset = (page - 1) * page_size
    rows = conn.execute('SELECT id, title, body, category, created_at FROM articles' + where + ' ORDER BY ' + ordering[sort_by] + ' LIMIT ? OFFSET ?', args + [page_size, offset]).fetchall()
    return {'total': total, 'articles': [dict(row) for row in rows]}

