import requests

def get_cargo_document(container_id: str, api_key: str) -> dict:
    if not isinstance(container_id, str) or not container_id.strip():
        raise ValueError('container_id must not be blank')
    container_id = container_id.strip()
    response = requests.get(f'https://api.harbor.example/v1/cargo/documents/{container_id}', headers={'Authorization': f'Bearer {api_key}'}, params={'format': 'json'}, timeout=10)
    if response.status_code == 404:
        raise ValueError('cargo document not found')
    if not 200 <= response.status_code < 300:
        raise RuntimeError('cargo document request failed')
    document = response.json()['document']
    packages = document.get('packages', [])
    return {'document_id': document['id'], 'status': document['status'], 'updated_at': document['updated_at'], 'package_count': sum((package['count'] for package in packages))}

