from lxml import etree

def reconcile_inventory(xml_text: str) -> dict[str, int]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode('utf-8'), parser)
    except (etree.XMLSyntaxError, UnicodeEncodeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'inventory':
        raise ValueError('invalid root')
    result: dict[str, int] = {}
    for item in root:
        if item.tag != 'item':
            continue
        barcode = item.get('barcode')
        quantity_text = item.get('quantity')
        if barcode is None or quantity_text is None or (not barcode.strip()):
            raise ValueError('invalid item')
        try:
            quantity = int(quantity_text.strip())
        except ValueError as exc:
            raise ValueError('invalid quantity') from exc
        if quantity < 0:
            raise ValueError('invalid quantity')
        barcode = barcode.strip()
        result[barcode] = result.get(barcode, 0) + quantity
    return result

