import sqlite3

def list_images(conn: sqlite3.Connection, patient_id: str | None=None, modality: str | None=None, name_contains: str | None=None, min_file_size: int | None=None, sort_by: str='study_date', descending: bool=False, limit: int=50, offset: int=0) -> list[dict]:
    allowed = {'image_id', 'study_date', 'file_size', 'width', 'height'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    if not isinstance(limit, int) or not isinstance(offset, int) or limit < 0 or (offset < 0):
        raise ValueError('invalid pagination')
    clauses = []
    if patient_id is not None:
        clauses.append(f"patient_id = '{patient_id}'")
    if modality is not None:
        clauses.append(f"modality = '{modality}'")
    if name_contains is not None:
        clauses.append(f"lower(image_name) LIKE lower('%{name_contains}%')")
    if min_file_size is not None:
        clauses.append(f'file_size >= {min_file_size}')
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    query = 'SELECT image_id, patient_id, study_date, modality, image_name, width, height, file_size FROM images' + where + f' ORDER BY {sort_by} {direction}, image_id ASC LIMIT {limit} OFFSET {offset}'
    rows = conn.execute(query).fetchall()
    result = []
    for row in rows:
        item = dict(row)
        item['megapixels'] = round(item['width'] * item['height'] / 1000000, 2)
        result.append(item)
    return result

