import csv
import os
import zipfile

def extract_member(base_dir: str, archive_path: str, member_name: str) -> str:
    with zipfile.ZipFile(archive_path) as zf:
        try:
            info = zf.getinfo(member_name)
        except KeyError:
            raise
        if info.is_dir():
            raise ValueError('archive entry is not a regular file')
        base = os.path.realpath(base_dir)
        target = os.path.realpath(os.path.join(base, member_name))
        if os.path.commonpath([base, target]) != base:
            raise ValueError('member is outside base directory')
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with zf.open(info) as src, open(target, 'wb') as dst:
            while True:
                block = src.read(65536)
                if not block:
                    break
                dst.write(block)
        return target

def parse_claims_csv(path: str) -> list[dict[str, int]]:
    expected = ['accident_year', 'development_month', 'paid_loss']
    result = []
    with open(path, encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return []
        if header != expected:
            raise ValueError('invalid header')
        for row in reader:
            if not row or all((not value.strip() for value in row)):
                continue
            if len(row) != 3:
                raise ValueError('invalid row')
            try:
                values = [int(value) for value in row]
            except ValueError:
                raise ValueError('invalid integer')
            if values[0] < 1900 or values[1] < 0 or values[2] < 0:
                raise ValueError('value out of range')
            result.append(dict(zip(expected, values)))
    return result

def development_triangle(records: list[dict[str, int]]) -> list[dict[str, object]]:
    expected = {'accident_year', 'development_month', 'paid_loss'}
    grouped = {}
    maximum = -1
    for record in records:
        if set(record) != expected or any((type(record[k]) is not int for k in expected)):
            raise ValueError('invalid record')
        year = record['accident_year']
        month = record['development_month']
        loss = record['paid_loss']
        if year < 1900 or month < 0 or loss < 0:
            raise ValueError('value out of range')
        grouped.setdefault(year, {})[month] = grouped.setdefault(year, {}).get(month, 0) + loss
        maximum = max(maximum, month)
    output = []
    for year in sorted(grouped):
        running = 0
        cumulative = {}
        for month in range(maximum + 1):
            running += grouped[year].get(month, 0)
            cumulative[month] = running
        output.append({'accident_year': year, 'cumulative': cumulative})
    return output

