def summarize_beneficiary_changes(account_id: str, start_date: str, end_date: str) -> dict:
    if not isinstance(account_id, str) or not account_id:
        raise ValueError('invalid account_id')
    date_pattern = re.compile('^\\d{4}-\\d{2}-\\d{2}$')
    if not isinstance(start_date, str) or not date_pattern.fullmatch(start_date):
        raise ValueError('invalid start_date')
    if not isinstance(end_date, str) or not date_pattern.fullmatch(end_date):
        raise ValueError('invalid end_date')
    try:
        start = datetime.date.fromisoformat(start_date)
        end = datetime.date.fromisoformat(end_date)
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    if start > end:
        raise ValueError('invalid date range')
    url = f'https://benefits.example.com/v1/accounts/{account_id}/beneficiary-changes'
    response = requests.get(url, params={'start_date': start_date, 'end_date': end_date}, headers={'Accept': 'application/json'}, timeout=10)
    if response.status_code != 200:
        raise RuntimeError('request failed')
    records = response.json()
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    grouped = {}
    required = {'beneficiary', 'action', 'status', 'percentage', 'effective_date'}
    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError('malformed record')
        beneficiary = record['beneficiary']
        percentage = record['percentage']
        effective_date = record['effective_date']
        if not isinstance(beneficiary, str) or not beneficiary:
            raise ValueError('malformed record')
        if not isinstance(record['action'], str) or not isinstance(record['status'], str):
            raise ValueError('malformed record')
        if isinstance(percentage, bool) or not isinstance(percentage, (int, float)) or (not 0 <= percentage <= 100):
            raise ValueError('malformed record')
        if not isinstance(effective_date, str) or not date_pattern.fullmatch(effective_date):
            raise ValueError('malformed record')
        try:
            record_date = datetime.date.fromisoformat(effective_date)
        except ValueError as exc:
            raise ValueError('malformed record') from exc
        if record['action'] == 'changed' and record['status'] == 'approved' and (start <= record_date <= end):
            total, count = grouped.get(beneficiary, (0, 0))
            grouped[beneficiary] = (total + percentage, count + 1)
    beneficiaries = [{'beneficiary': name, 'total_percentage': round(total, 2), 'change_count': count} for name, (total, count) in grouped.items()]
    beneficiaries.sort(key=lambda item: (-item['total_percentage'], item['beneficiary']))
    return {'account_id': account_id, 'period': {'start_date': start_date, 'end_date': end_date}, 'beneficiaries': beneficiaries}

