from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from lxml import etree

def summarize_rentals(xml: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid pagination')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit <= 0):
        raise ValueError('invalid pagination')
    if not isinstance(xml, str):
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'rentals':
        raise ValueError('invalid root')
    groups = {}
    for node in root:
        if node.tag != 'rental':
            raise ValueError('invalid rental')
        try:
            category = node.attrib['category']
            days_text = node.attrib['days']
            rate_text = node.attrib['daily_rate']
            status = node.attrib['status']
            if not category:
                raise ValueError('invalid category')
            days = int(days_text)
            rate = Decimal(rate_text)
        except (KeyError, ValueError, InvalidOperation) as exc:
            raise ValueError('invalid rental') from exc
        if days <= 0 or rate < 0:
            raise ValueError('invalid rental')
        if status == 'returned':
            if category not in groups:
                groups[category] = [0, Decimal('0')]
            groups[category][0] += 1
            groups[category][1] += Decimal(days) * rate
    result = []
    for category, (count, total) in groups.items():
        rounded = total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'category': category, 'count': count, 'total': float(rounded)})
    result.sort(key=lambda item: (-item['total'], item['category']))
    end = None if limit is None else offset + limit
    return result[offset:end]

