import hashlib
import hmac
import re

def build_delivery_manifest(orders: list[dict], config: dict[str, str]) -> list[dict]:
    if not isinstance(orders, list):
        raise ValueError('orders must be a list')
    if not orders:
        return []
    if 'DELIVERY_SIGNING_KEY' not in config:
        raise ValueError('DELIVERY_SIGNING_KEY is required')
    groups = {}
    seen = set()
    p = re.compile('^(\\d{2}):(\\d{2})-(\\d{2}):(\\d{2})$')
    for o in orders:
        if not isinstance(o, dict) or not isinstance(o.get('id'), str) or (not o['id']):
            raise ValueError('invalid order')
        if o['id'] in seen:
            raise ValueError('duplicate order ID')
        seen.add(o['id'])
        w = o.get('weight_kg')
        if isinstance(w, bool) or not isinstance(w, (int, float)) or w <= 0:
            raise ValueError('invalid weight')
        m = p.fullmatch(o.get('slot', ''))
        if not m:
            raise ValueError('invalid slot')
        sh, sm, eh, em = map(int, m.groups())
        if sh > 23 or eh > 23 or sm > 59 or (em > 59) or ((sh, sm) >= (eh, em)):
            raise ValueError('invalid slot')
        q = o.get('priority', 0)
        if isinstance(q, bool) or not isinstance(q, int):
            raise ValueError('invalid priority')
        groups.setdefault(o['slot'], []).append((o['id'], float(w), q))
    out = []
    for slot, a in groups.items():
        total = sum((x[1] for x in a))
        if total > 100:
            raise ValueError('slot capacity exceeded')
        a.sort(key=lambda x: (-x[2], x[0]))
        ids = [x[0] for x in a]
        wt = round(total, 2)
        fee = round(12 + 1.5 * len(a) + 0.75 * wt, 2)
        text = f"{slot}|{','.join(ids)}|{wt:.2f}|{fee:.2f}"
        out.append({'slot': slot, 'order_ids': ids, 'total_weight_kg': wt, 'fee': fee, 'signature': hmac.new(config['DELIVERY_SIGNING_KEY'].encode(), text.encode(), hashlib.sha256).hexdigest()})
    out.sort(key=lambda x: tuple(map(int, re.findall('\\d+', x['slot']))))
    return out

