import datetime
import os

def write_schedule_report(appointments: list[dict], output_name: str, base_dir: str, page: int=1, page_size: int=10) -> str:
    if not isinstance(appointments, list):
        raise TypeError('appointments must be a list')
    if not isinstance(output_name, str):
        raise TypeError('output_name must be a string')
    if not output_name:
        raise ValueError('output_name cannot be empty')
    if not isinstance(page, int) or not isinstance(page_size, int):
        raise TypeError('pagination values must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    checked = []
    for item in appointments:
        if not isinstance(item, dict):
            raise TypeError('appointment must be a dictionary')
        for field in ('date', 'time', 'name', 'service', 'duration_minutes', 'guests'):
            if field not in item:
                raise ValueError('missing field')
        if not isinstance(item['date'], str) or not isinstance(item['time'], str) or (not isinstance(item['name'], str)) or (not isinstance(item['service'], str)):
            raise TypeError('invalid text field')
        try:
            datetime.date.fromisoformat(item['date'])
            datetime.datetime.strptime(item['time'], '%H:%M')
        except ValueError:
            raise ValueError('invalid date or time')
        if not item['name'] or not item['service']:
            raise ValueError('empty text field')
        if not isinstance(item['duration_minutes'], int) or not isinstance(item['guests'], int):
            raise TypeError('invalid numeric field')
        if item['duration_minutes'] <= 0 or item['guests'] < 0:
            raise ValueError('invalid numeric value')
        checked.append(item)
    checked.sort(key=lambda x: (x['date'], x['time'], x['name']))
    total_pages = max(1, (len(checked) + page_size - 1) // page_size)
    selected = checked[(page - 1) * page_size:page * page_size]
    lines = [f'Schedule report - page {page} of {total_pages}', 'Date | Time | Name | Service | Duration | Guests']
    lines.extend((f"{x['date']} | {x['time']} | {x['name']} | {x['service']} | {x['duration_minutes']} | {x['guests']}" for x in selected))
    lines.append(f"Summary: {len(checked)} appointments, {sum((x['duration_minutes'] for x in checked))} minutes, {sum((x['guests'] for x in checked))} guests")
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, output_name))
    try:
        inside = os.path.commonpath([base, target]) == base
    except ValueError:
        inside = False
    if not inside:
        raise ValueError('output path is outside base directory')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write('\n'.join(lines) + '\n')
    return target

