            pieces_value = int(pieces)
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not math.isfinite(weight_value) or weight_value <= 0 or pieces_value <= 0 or (str(pieces_value) != pieces):
            raise ValueError('invalid number')
        seen.add(awb)
        result.append({'awb': awb, 'destination': destination, 'weight': weight_value, 'pieces': pieces_value, 'priority': priority.lower()})
