        rows = list(csv.reader(StringIO(text), skipinitialspace=False))
    except csv.Error as e:
        raise ValueError('malformed csv') from e
    rows = [r for r in rows if any((x.strip() for x in r))]
    if not rows or rows[0] != ['route', 'stop', 'scheduled', 'actual', 'riders']:
