    for r in rows[1:]:
        if len(r) != 5:
            raise ValueError('invalid row')
        route = r[0].strip()
        try:
            stop, scheduled, actual, riders = (int(x.strip()) for x in r[1:])
        except Exception as e:
            raise ValueError('invalid number') from e
        if not route or stop <= 0 or (not 0 <= scheduled <= 1439) or (not 0 <= actual <= 1439) or (riders < 0):
            raise ValueError('invalid value')
        out.append({'route': route, 'stop': stop, 'scheduled': scheduled, 'actual': actual, 'riders': riders})
    return out

def summarize_routes(rows: list[dict[str, object]]) -> list[dict[str, object]]:
    groups = {}
    for row in rows:
        if any((k not in row for k in ('route', 'stop', 'scheduled', 'actual', 'riders'))):
            raise ValueError('missing key')
        if not isinstance(row['route'], str) or not isinstance(row['riders'], int) or (not isinstance(row['scheduled'], int)) or (not isinstance(row['actual'], int)):
            raise ValueError('invalid row')
        route = row['route']
        g = groups.setdefault(route, [0, 0, [], 0])
        delay = row['actual'] - row['scheduled']
        g[0] += 1
        g[1] += row['riders']
        g[2].append(delay)
        g[3] += delay > 0
    out = []
    for route, (count, riders, delays, late) in groups.items():
        avg = float((Decimal(sum(delays)) / Decimal(len(delays))).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        out.append({'route': route, 'stops': count, 'riders': riders, 'average_delay': avg, 'late_stops': late})
    return sorted(out, key=lambda x: (-x['riders'], -x['late_stops'], x['route']))

def write_report(summary: list[dict[str, object]], destination: str) -> int:
    fields = ['route', 'stops', 'riders', 'average_delay', 'late_stops']
    for row in summary:
        if any((k not in row for k in fields)):
            raise ValueError('missing key')
    fd, temp = tempfile.mkstemp(dir=os.path.dirname(os.path.abspath(destination)), prefix='.report-')
    try:
        with os.fdopen(fd, 'w', newline='') as f:
            w = csv.DictWriter(f, fieldnames=fields)
            w.writeheader()
            w.writerows(summary)
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return len(summary)

