import csv
import os
import tempfile

def export_currency_report(entries: list[dict], output_path: str, page: int=1, page_size: int=50) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('page_size must be a positive integer')
    totals = {}
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {'player', 'amount', 'kind'}:
            raise ValueError('invalid entry')
        player = entry['player']
        amount = entry['amount']
        kind = entry['kind']
        if not isinstance(player, str) or not player:
            raise ValueError('invalid player')
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError('invalid amount')
        if kind not in ('credit', 'debit'):
            raise ValueError('invalid kind')
        if player not in totals:
            totals[player] = {'credits': 0, 'debits': 0}
        totals[player]['credits' if kind == 'credit' else 'debits'] += amount
    rows = []
    for player, values in totals.items():
        rows.append({'player': player, 'credits': values['credits'], 'debits': values['debits'], 'balance': values['credits'] - values['debits']})
    rows.sort(key=lambda row: (-row['balance'], row['player']))
    total_players = len(rows)
    total_pages = (total_players + page_size - 1) // page_size if total_players else 0
    start = (page - 1) * page_size
    selected = rows[start:start + page_size] if page <= total_pages else []
    directory = os.path.dirname(os.path.abspath(output_path))
    fd, temporary_path = tempfile.mkstemp(dir=directory, prefix='.currency-')
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['player', 'credits', 'debits', 'balance'])
            for row in selected:
                writer.writerow([row['player'], row['credits'], row['debits'], row['balance']])
        os.replace(temporary_path, output_path)
    finally:
        if os.path.exists(temporary_path):
            os.unlink(temporary_path)
    return {'total_players': total_players, 'total_pages': total_pages, 'page': page, 'page_size': page_size, 'rows': selected}

