def create_schema(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE IF NOT EXISTS subscriptions (email TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL, tags TEXT NOT NULL, subscribed_at INTEGER NOT NULL)')
    conn.commit()

def _check_status(status: str) -> None:
    if status not in {'active', 'paused', 'unsubscribed'}:
        raise ValueError('invalid status')

def save_subscription(conn: sqlite3.Connection, email: str, name: str, status: str='active', tags: list[str] | tuple[str, ...]=(), subscribed_at: int=0) -> None:
    if not isinstance(email, str) or not email.strip() or (not isinstance(name, str)):
        raise ValueError('invalid identity')
    _check_status(status)
    if not isinstance(tags, (list, tuple)) or any((not isinstance(x, str) for x in tags)):
        raise ValueError('invalid tags')
    if isinstance(subscribed_at, bool) or not isinstance(subscribed_at, int):
        raise ValueError('invalid timestamp')
    conn.execute('INSERT INTO subscriptions(email,name,status,tags,subscribed_at) VALUES(?,?,?,?,?) ON CONFLICT(email) DO UPDATE SET name=excluded.name,status=excluded.status,tags=excluded.tags,subscribed_at=excluded.subscribed_at', (email, name, status, json.dumps(list(tags)), subscribed_at))
    conn.commit()

def find_subscriptions(conn: sqlite3.Connection, status: str | None=None, search: str='', sort_by: str='email', descending: bool=False) -> list[dict]:
    columns = {'email': 'email', 'name': 'name', 'status': 'status', 'subscribed_at': 'subscribed_at'}
    if sort_by not in columns:
        raise ValueError('invalid sort')
    clauses = []
    args = []
    if status is not None:
        clauses.append('status = ?')
        args.append(status)
    if search:
        clauses.append('(lower(email) LIKE lower(?) OR lower(name) LIKE lower(?))')
        args.extend([f'%{search}%', f'%{search}%'])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    direction = 'DESC' if descending else 'ASC'
    rows = conn.execute(f'SELECT email,name,status,tags,subscribed_at FROM subscriptions{where} ORDER BY {columns[sort_by]} {direction}, email ASC', args).fetchall()
    return [{'email': r[0], 'name': r[1], 'status': r[2], 'tags': json.loads(r[3]), 'subscribed_at': r[4]} for r in rows]

def change_status(conn: sqlite3.Connection, email: str, status: str) -> bool:
    _check_status(status)
    cur = conn.execute('UPDATE subscriptions SET status=? WHERE email=?', (status, email))
    conn.commit()
    return cur.rowcount > 0

