import hmac
import json
import math

def summarize_grant_webhook(body: str, signature: str, secret: str) -> dict:
    if not isinstance(body, str) or not isinstance(signature, str) or (not isinstance(secret, str)):
        raise TypeError('arguments must be strings')
    expected = hmac.new(secret.encode('utf-8'), body.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body)
        applications = data['applications']
        if not isinstance(data, dict) or not isinstance(applications, list):
            raise ValueError
        counts = {'approved': 0, 'pending': 0, 'rejected': 0}
        totals = {}
        ids = set()
        for app in applications:
            if not isinstance(app, dict):
                raise ValueError
            if not all((isinstance(app.get(k), str) for k in ('id', 'status', 'institution'))):
                raise ValueError
            ident = app['id']
            status = app['status']
            institution = app['institution']
            amount = app.get('amount')
            if ident in ids or status not in counts or isinstance(amount, bool) or (not isinstance(amount, (int, float))) or (not math.isfinite(amount)) or (amount < 0):
                raise ValueError
            ids.add(ident)
            counts[status] += 1
            if status == 'approved':
                if institution not in totals:
                    totals[institution] = [0.0, 0]
                totals[institution][0] += amount
                totals[institution][1] += 1
        institutions = [{'name': name, 'approved_amount': round(value[0], 2), 'count': value[1]} for name, value in totals.items()]
        institutions.sort(key=lambda item: (-item['approved_amount'], item['name']))
        return {'total': len(applications), 'counts': counts, 'approved_amount': round(sum((x[0] for x in totals.values())), 2), 'institutions': institutions}
    except (KeyError, TypeError, ValueError, json.JSONDecodeError):
        raise ValueError('invalid payload')

