def parse_proposal_manifest(raw: str) -> dict:
    try:
        value = json.loads(raw)
    except Exception as exc:
        raise ValueError('invalid manifest') from exc
    if not isinstance(value, dict) or not isinstance(value.get('project'), str) or (not value['project']) or (not isinstance(value.get('phases'), list)):
        raise ValueError('invalid manifest')
    phases = []
    for phase in value['phases']:
        if not isinstance(phase, dict) or set(phase) != {'name', 'days', 'fee'}:
            raise ValueError('invalid phase')
        if not isinstance(phase['name'], str) or not phase['name'] or isinstance(phase['days'], bool) or (not isinstance(phase['days'], int)) or (phase['days'] < 0) or isinstance(phase['fee'], bool) or (not isinstance(phase['fee'], int)) or (phase['fee'] < 0):
            raise ValueError('invalid phase')
        phases.append({'name': phase['name'], 'days': phase['days'], 'fee': phase['fee']})
    return {'project': value['project'], 'phases': phases}

def extract_proposal_bundle(zip_path: str, destination: str) -> dict:
    with zipfile.ZipFile(zip_path) as archive:
        infos = archive.infolist()
        manifest_info = next((i for i in infos if i.filename == 'manifest.json' and (not i.is_dir())), None)
        if manifest_info is None:
            raise ValueError('manifest missing')
        manifest = parse_proposal_manifest(archive.read(manifest_info).decode('utf-8'))
        base = os.path.realpath(destination)
        os.makedirs(base, exist_ok=True)
        files = []
        for info in infos:
            if info.is_dir():
                continue
            target = os.path.realpath(os.path.join(base, info.filename))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('file outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with open(target, 'wb') as handle:
                handle.write(archive.read(info))
            files.append(info.filename)
    return {'project': manifest['project'], 'total_days': sum((p['days'] for p in manifest['phases'])), 'total_fee': sum((p['fee'] for p in manifest['phases'])), 'phase_count': len(manifest['phases']), 'files': sorted(files)}

def rank_proposals(proposals: list[dict]) -> list[dict]:
    for item in proposals:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not item['id']) or isinstance(item.get('fee'), bool) or (not isinstance(item.get('fee'), int)) or (item['fee'] < 0) or isinstance(item.get('days'), bool) or (not isinstance(item.get('days'), int)) or (item['days'] <= 0) or isinstance(item.get('confidence'), bool) or (not isinstance(item.get('confidence'), (int, float))) or (not 0 <= item['confidence'] <= 1):
            raise ValueError('invalid proposal')
    return sorted(proposals, key=lambda p: (-(p['confidence'] - p['fee'] / 100000), p['days'], p['id'].casefold(), p['id']))

