import hmac
import os

def create_leak_alert(sensor_id: str, flow_liters: float, observed_at: str) -> dict:
    if not isinstance(sensor_id, str) or not sensor_id:
        raise ValueError('sensor_id must not be empty')
    if not isinstance(observed_at, str) or not observed_at:
        raise ValueError('observed_at must not be empty')
    if isinstance(flow_liters, bool) or not isinstance(flow_liters, (int, float)) or flow_liters <= 0:
        raise ValueError('flow_liters must be positive')
    token = os.environ.get('LEAK_ALERT_TOKEN')
    if not token:
        raise RuntimeError('LEAK_ALERT_TOKEN is not configured')
    payload = f'{sensor_id}|{flow_liters:.2f}|{observed_at}'
    signature = hmac.new(token.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return {'sensor_id': sensor_id, 'flow_liters': round(flow_liters, 2), 'observed_at': observed_at, 'signature': signature}

