import hashlib
import hmac
import os
from datetime import date

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${salt.hex()}${digest.hex()}'

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str) or not pin or (not isinstance(stored, str)):
        return False
    try:
        iterations_text, salt_text, digest_text = stored.split('$')
        iterations = int(iterations_text)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def inspection_report(inspections: list[dict], target_date: str, page: int=1, page_size: int=10) -> dict:
    try:
        date.fromisoformat(target_date)
    except (TypeError, ValueError):
        raise ValueError('invalid target date')
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    matches = [{k: item[k] for k in ('station', 'date', 'start', 'priority', 'minutes')} for item in inspections if item['status'] == 'scheduled' and item['date'] == target_date]
    matches.sort(key=lambda x: (x['start'], -x['priority'], x['station']))
    total = len(matches)
    total_minutes = sum((x['minutes'] for x in matches))
    average = round(total_minutes / total, 2) if total else 0.0
    begin = (page - 1) * page_size
    return {'total': total, 'total_minutes': total_minutes, 'average_minutes': average, 'items': matches[begin:begin + page_size]}

