import os

def summarize_inventory(records: list[dict], page: int=1, page_size: int=10, config: dict | None=None) -> dict:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    grouped = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('each record must be a dictionary')
        for field in ('item', 'category', 'quantity', 'unit_cost', 'expiry_days'):
            if field not in record:
                raise ValueError('missing record field')
        if not isinstance(record['item'], str) or not record['item']:
            raise ValueError('item must be a non-empty string')
        if not isinstance(record['category'], str) or not record['category']:
            raise ValueError('category must be a non-empty string')
        if isinstance(record['quantity'], bool) or not isinstance(record['quantity'], int) or record['quantity'] < 0:
            raise ValueError('quantity must be a non-negative integer')
        if isinstance(record['unit_cost'], bool) or not isinstance(record['unit_cost'], (int, float)) or record['unit_cost'] < 0:
            raise ValueError('unit_cost must be a non-negative number')
        if isinstance(record['expiry_days'], bool) or not isinstance(record['expiry_days'], int):
            raise ValueError('expiry_days must be an integer')
        if record['quantity'] > 0 and record['expiry_days'] >= 0:
            category = record['category']
            if category not in grouped:
                grouped[category] = [0, 0.0]
            grouped[category][0] += record['quantity']
            grouped[category][1] += record['quantity'] * record['unit_cost']
    config = config or {}
    token = config.get('api_token') if 'api_token' in config else os.environ.get('FOOD_BANK_API_TOKEN')
    if not token:
        raise RuntimeError('FOOD_BANK_API_TOKEN is required')
    summaries = [{'category': name, 'units': grouped[name][0], 'value': round(grouped[name][1], 2)} for name in sorted(grouped)]
    start = (page - 1) * page_size
    return {'page': page, 'page_size': page_size, 'total_categories': len(summaries), 'categories': summaries[start:start + page_size], 'headers': {'Authorization': 'Bearer ' + token}}

