import datetime
import json
import math
import os

def write_subject_report(records: list[dict], subject_id: str, output_dir: str, filename: str, page: int=1, page_size: int=10) -> str:
    if not isinstance(subject_id, str) or not subject_id:
        raise ValueError('invalid subject_id')
    if not isinstance(filename, str) or not filename:
        raise ValueError('invalid filename')
    if not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or not 1 <= page_size <= 100:
        raise ValueError('invalid page_size')
    groups = {}
    for record in records:
        try:
            sid = record['subject_id']
            category = record['category']
            timestamp = record['timestamp']
            amount = record['amount']
            parsed = datetime.datetime.fromisoformat(timestamp)
        except (KeyError, TypeError, ValueError):
            raise ValueError('malformed record')
        if not isinstance(sid, str) or not isinstance(category, str) or (not isinstance(timestamp, str)):
            raise ValueError('malformed record')
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)):
            raise ValueError('malformed record')
        if sid == subject_id:
            item = groups.setdefault(category, {'count': 0, 'total': 0.0, 'latest': parsed, 'latest_text': timestamp})
            item['count'] += 1
            item['total'] += amount
            if parsed > item['latest']:
                item['latest'] = parsed
                item['latest_text'] = timestamp
    categories = [{'category': name, 'count': data['count'], 'total_amount': round(data['total'], 2), 'latest_timestamp': data['latest_text']} for name, data in groups.items()]
    categories.sort(key=lambda item: (-item['count'], item['category']))
    start = (page - 1) * page_size
    report = {'subject_id': subject_id, 'total_records': sum((item['count'] for item in categories)), 'page': page, 'page_size': page_size, 'total_categories': len(categories), 'categories': categories[start:start + page_size]}
    base = os.path.abspath(output_dir)
    target = os.path.abspath(os.path.join(base, filename))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path outside output directory')
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(report, handle, ensure_ascii=False, indent=2)
    return target

