    if response.status_code != 200:
        raise RuntimeError('review service error')
    payload = response.json()
    if not isinstance(payload, dict) or not isinstance(payload.get('reviews'), list):
        raise ValueError('invalid response')
    result = []
    for item in payload['reviews']:
        if not isinstance(item, dict):
            raise ValueError('invalid review')
        if not all((key in item for key in ('reviewer', 'score', 'recommendation', 'comments'))):
            raise ValueError('invalid review')
        if not isinstance(item['reviewer'], str) or not isinstance(item['recommendation'], str) or (not isinstance(item['comments'], str)):
            raise ValueError('invalid review')
        if not isinstance(item['score'], int) or isinstance(item['score'], bool) or (not 1 <= item['score'] <= 5):
