            raise ValueError('invalid review')
        if not isinstance(item['reviewer'], str) or not isinstance(item['recommendation'], str) or (not isinstance(item['comments'], str)):
            raise ValueError('invalid review')
        if not isinstance(item['score'], int) or isinstance(item['score'], bool) or (not 1 <= item['score'] <= 5):
            raise ValueError('invalid review')
        score_counts[item['score']] += 1
        recommendation_counts[item['recommendation']] = recommendation_counts.get(item['recommendation'], 0) + 1
