import csv
import io
import math
import secrets

def parse_schedule(text: str) -> list[dict]:
    rows = list(csv.reader(io.StringIO(text)))
    rows = [r for r in rows if any((x.strip() for x in r))]
    header = ['stand_id', 'acres', 'species', 'priority', 'window']
    if not rows or [x.strip() for x in rows[0]] != header:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        sid, acres, species, priority, window = [x.strip() for x in row]
        try:
            a = float(acres)
            p = int(priority)
            w = int(window)
        except (TypeError, ValueError):
            raise ValueError('invalid value')
        if not sid or not species or (not math.isfinite(a)) or (a <= 0) or (not 1 <= p <= 5) or (not 1 <= w <= 12) or (sid in seen):
            raise ValueError('invalid value')
        seen.add(sid)
        result.append({'stand_id': sid, 'acres': a, 'species': species, 'priority': p, 'window': w})
    return result

def plan_harvest(stands: list[dict], capacity: float, window: int) -> dict:
    if not isinstance(window, int) or not 1 <= window <= 12 or (not isinstance(capacity, (int, float))) or (not math.isfinite(capacity)) or (capacity < 0):
        raise ValueError('invalid limits')
    required = {'stand_id', 'acres', 'species', 'priority', 'window'}
    seen = set()
    data = []
    for s in stands:
        if set(s) != required or not isinstance(s['stand_id'], str) or (not s['stand_id']) or (s['stand_id'] in seen) or (not isinstance(s['acres'], (int, float))) or (not math.isfinite(s['acres'])) or (s['acres'] <= 0) or (not isinstance(s['priority'], int)) or (not 1 <= s['priority'] <= 5) or (not isinstance(s['window'], int)) or (not 1 <= s['window'] <= 12):
            raise ValueError('invalid stand')
        seen.add(s['stand_id'])
        if s['window'] == window:
            data.append(s)
    data.sort(key=lambda s: (-s['priority'], s['acres'], s['stand_id']))
    selected, total = ([], 0.0)
    for s in data:
        if total + s['acres'] <= capacity + 1e-12:
            selected.append(s['stand_id'])
            total += s['acres']
    return {'selected': selected, 'total_acres': round(total, 2), 'remaining_capacity': round(capacity - total, 2)}
