def parse_findings(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text')
    result = []
    for line in text.splitlines():
        if not line.strip():
            continue
        fields, current, escaped = ([], [], False)
        for char in line:
            if escaped:
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('trailing escape')
        fields.append(''.join(current))
        if len(fields) != 4 or not fields[0] or fields[1] not in {'low', 'medium', 'high'} or (fields[2] not in {'open', 'closed'}):
            raise ValueError('invalid finding')
        result.append({'code': fields[0], 'severity': fields[1], 'status': fields[2], 'note': fields[3]})
    return result

def summarize_findings(findings: list[dict]) -> dict:
    counts = {'low': 0, 'medium': 0, 'high': 0}
    open_count = closed_count = 0
    for item in findings:
        if not isinstance(item, dict) or item.get('severity') not in counts or item.get('status') not in {'open', 'closed'}:
            raise ValueError('invalid finding')
        counts[item['severity']] += 1
        if item['status'] == 'open':
            open_count += 1
        else:
            closed_count += 1
    return {'total': open_count + closed_count, 'open': open_count, 'closed': closed_count, 'by_severity': counts}

def decide_audit(requester: dict, audits: dict[str, dict], audit_id: str, decision: str, note: str, event_time: str) -> dict:
    audit = audits[audit_id]
    if requester.get('tenant') != audit.get('tenant') and 'admin' not in requester.get('roles', []):
        raise PermissionError('access denied')
    if requester.get('id') != audit.get('owner_id') and (not {'certifier', 'admin'} & set(requester.get('roles', []))):
        raise PermissionError('access denied')
    if audit.get('status') != 'submitted' or not isinstance(audit.get('findings'), list):
        raise ValueError('audit is not submittable')
    if decision not in {'approve', 'reject'} or not isinstance(note, str):
        raise ValueError('invalid decision')
    if decision == 'approve' and any((x.get('status') != 'closed' for x in audit['findings'])):
        raise ValueError('open findings')
    result = audit.copy()
    result['findings'] = [x.copy() for x in audit['findings']]
    result['history'] = list(audit.get('history', []))
    result['status'] = 'certified' if decision == 'approve' else 'rejected'
    result['history'].append({'actor_id': requester.get('id'), 'decision': decision, 'note': note, 'time': event_time})
    return result

