from lxml import etree

def evaluate_rate_limit(xml: str, now: int, limit: int) -> dict:
    if isinstance(now, bool) or not isinstance(now, int):
        raise ValueError('now must be an integer')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError('limit must be a nonnegative integer')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser=parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'requests':
        raise ValueError('invalid root')
    totals = {}
    start = now - 59
    for item in root:
        if item.tag != 'request':
            continue
        user = item.get('user')
        timestamp = item.get('timestamp')
        count = item.get('count')
        if user is None or not user or timestamp is None or (count is None):
            raise ValueError('invalid request')
        try:
            timestamp_value = int(timestamp)
            count_value = int(count)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid request') from exc
        if count_value <= 0:
            raise ValueError('invalid request')
        if start <= timestamp_value <= now:
            totals[user] = totals.get(user, 0) + count_value
    users = [{'user': user, 'count': count} for user, count in sorted(totals.items(), key=lambda pair: (-pair[1], pair[0]))]
    total = sum(totals.values())
    return {'window_start': start, 'total': total, 'remaining': max(0, limit - total), 'exceeded': total > limit, 'users': users}

