from datetime import date, timedelta
from decimal import Decimal, InvalidOperation
import re

def _day(s):
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', s):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(s)
    except ValueError:
        raise ValueError('invalid date')

def load_referrals(path: str) -> list[dict]:
    try:
        with open(path, encoding='utf-8') as f:
            lines = f.read().splitlines()
    except (OSError, UnicodeError):
        raise ValueError('cannot read file')
    if not lines or lines[0] != 'referral_id\treferrer\treferred\tdate\tstatus\tamount':
        raise ValueError('invalid header')
    out = []
    seen = set()
    for line in lines[1:]:
        p = line.split('\t')
        if len(p) != 6 or any((not x for x in p[:3])):
            raise ValueError('invalid row')
        rid, ref, who, day, status, amt = p
        _day(day)
        if rid in seen or status not in {'approved', 'pending', 'rejected'}:
            raise ValueError('invalid row')
        if not re.fullmatch('\\d+(?:\\.\\d{1,2})?', amt):
            raise ValueError('invalid amount')
        try:
            cents = int(Decimal(amt) * 100)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount')
        seen.add(rid)
        out.append({'referral_id': rid, 'referrer': ref, 'referred': who, 'date': day, 'status': status, 'amount': cents})
    return sorted(out, key=lambda x: (x['date'], x['referral_id']))

def calculate_rewards(path: str, as_of: str) -> dict[str, dict[str, int]]:
    end = _day(as_of)
    start = end - timedelta(days=29)
    groups = {}
    for r in load_referrals(path):
        if r['status'] == 'approved' and start <= _day(r['date']) <= end:
            g = groups.setdefault(r['referrer'], {'referrals': 0, 'amount_cents': 0, 'reward_cents': 0})
            g['referrals'] += 1
            g['amount_cents'] += r['amount']
    for g in groups.values():
        n = g['referrals']
        g['reward_cents'] = min(n, 2) * 1000 + max(0, n - 2) * 1500 + (2500 if n >= 5 else 0)
    return {k: groups[k] for k in sorted(groups)}

