import ast
import operator

def _evaluate(expression, values):
    try:
        tree = ast.parse(expression, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name) and node.id in values:
                return values[node.id]
            if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
                value = visit(node.operand)
                if isinstance(node.op, ast.UAdd):
                    return +value
                if isinstance(node.op, ast.USub):
                    return -value
                return not value
            if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
                if isinstance(node.op, ast.And):
                    result = visit(node.values[0])
                    for item in node.values[1:]:
                        if not result:
                            return result
                        result = visit(item)
                    return result
                result = visit(node.values[0])
                for item in node.values[1:]:
                    if result:
                        return result
                    result = visit(item)
                return result
            if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def schedule_cast(actors: list[dict], expression: str, page: int=1, page_size: int=10) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid paging')
    matching = []
    for actor in actors:
        values = {key: actor[key] for key in ('score', 'experience', 'auditions', 'available')}
        if _evaluate(expression, values):
            matching.append(actor)
    matching.sort(key=lambda actor: (-actor['score'], actor['name']))
    total = len(matching)
    start = (page - 1) * page_size
    selected = matching[start:start + page_size]
    return {'total': total, 'pages': (total + page_size - 1) // page_size if total else 0, 'page': page, 'page_size': page_size, 'actors': [{'name': x['name'], 'score': x['score'], 'available': x['available']} for x in selected]}

