from datetime import date, timedelta
from pathlib import Path
import re
import subprocess

def scan_case_deadlines(directory: str, pattern: str, today: date, window: int=7) -> list[dict[str, object]]:
    root = Path(directory)
    if not root.is_dir() or not pattern or window < 0:
        raise ValueError('invalid arguments')
    try:
        re.compile(pattern)
    except re.error as exc:
        raise ValueError('invalid pattern') from exc
    files = sorted((p for p in root.iterdir() if p.is_file() and p.suffix == '.cases'))
    if not files:
        return []
    result = subprocess.run(['grep', '-h', '-E', pattern, '--', *[str(p) for p in files]], capture_output=True, text=True)
    if result.returncode not in (0, 1):
        raise ValueError('invalid pattern')
    alerts = []
    seen = set()
    last = today + timedelta(days=window)
    for line in result.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('|')
        if len(fields) != 4:
            raise ValueError('malformed record')
        case_id, due_text, priority, title = fields
        try:
            due = date.fromisoformat(due_text)
        except ValueError as exc:
            raise ValueError('invalid date') from exc
        if priority not in {'high', 'medium', 'low'}:
            raise ValueError('invalid priority')
        if case_id in seen:
            raise ValueError('duplicate case')
        seen.add(case_id)
        if today <= due <= last:
            alerts.append({'case_id': case_id, 'due_date': due_text, 'priority': priority, 'title': title, 'days_remaining': (due - today).days})
    order = {'high': 0, 'medium': 1, 'low': 2}
    alerts.sort(key=lambda x: (x['due_date'], order[x['priority']], x['case_id']))
    return alerts

