from datetime import datetime, timezone

def parse_event(line: str) -> dict:
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\n'):
        if escaped:
            if char not in '|\\':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    fields.append(''.join(current))
    if len(fields) != 5 or any((not x for x in fields)):
        raise ValueError('invalid event')
    stamp, batch, location, quantity, status = fields
    try:
        datetime.fromisoformat(stamp[:-1] + '+00:00')
        number = int(quantity)
    except Exception as exc:
        raise ValueError('invalid event') from exc
    if number < 0 or str(number) != quantity or status not in {'RECEIVE', 'MOVE', 'RELEASE', 'RECALL'}:
        raise ValueError('invalid event')
    return {'timestamp': stamp, 'batch': batch, 'location': location, 'quantity': number, 'status': status}

def build_trace_report(path: str, window_hours: int=24) -> list[dict]:
    if isinstance(window_hours, bool) or not isinstance(window_hours, int) or window_hours < 0:
        raise ValueError('invalid window')
    completed = subprocess.run(['sort', '-t', '|', '-k1,1', '-k2,2', '-k3,3', path], capture_output=True, text=True, check=True)
    groups = {}
    for line in completed.stdout.splitlines():
        event = parse_event(line)
        groups.setdefault(event['batch'], []).append(event)
    result = []
    for batch in sorted(groups):
        events = groups[batch]
        state = 0
        locations = []
        for event in events:
            status = event['status']
            if state == 0 and status == 'RECEIVE':
                state = 1
            elif state == 1 and status == 'MOVE':
                pass
            elif state == 1 and status in {'RELEASE', 'RECALL'}:
                state = 2
            else:
                raise ValueError('invalid progression')
            if event['location'] not in locations:
                locations.append(event['location'])
        first = datetime.fromisoformat(events[0]['timestamp'][:-1] + '+00:00')
        last = datetime.fromisoformat(events[-1]['timestamp'][:-1] + '+00:00')
        if (last - first).total_seconds() <= window_hours * 3600:
            result.append({'batch': batch, 'quantity': sum((x['quantity'] for x in events)), 'first': events[0]['timestamp'], 'last': events[-1]['timestamp'], 'locations': locations, 'status': events[-1]['status']})
    return result

