import ast
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body
        return _visit(tree, variables)
    except Exception as exc:
        raise ValueError('invalid expression') from exc

def _visit(node, names):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError('unknown name')
        return names[node.id]
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        value = _visit(node.operand, names)
        return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_visit(node.left, names), _visit(node.right, names))
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        values = [_visit(x, names) for x in node.values]
        result = values[0]
        for value in values[1:]:
            result = value if (bool(result) if isinstance(node.op, ast.And) else not bool(result)) else result
        return result
    if isinstance(node, ast.Compare):
        left = _visit(node.left, names)
        for op, right_node in zip(node.ops, node.comparators):
            right = _visit(right_node, names)
            fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
            if fn is None or not fn(left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        args = [_visit(x, names) for x in node.args]
        if node.func.id == 'round' and len(args) in (1, 2):
            return round(*args)
        if node.func.id in ('min', 'max') and len(args) >= 2:
            return min(args) if node.func.id == 'min' else max(args)
    raise ValueError('unsupported expression')

def rank_applications(applications: list[dict], rule: str, variables: dict[str, int | float]) -> list[dict]:
    fields = ('id', 'score', 'requested', 'category', 'submitted', 'status')
    chosen = []
    for app in applications:
        if app['status'] == 'submitted' and evaluate_expression(rule, {**variables, **app}):
            chosen.append({key: app[key] for key in fields})
    return sorted(chosen, key=lambda x: (-x['score'], x['requested'], x['submitted'], x['id']))

def summary_grants(applications: list[dict], selected_ids: list[str]) -> dict:
    wanted = set(selected_ids)
    seen = set()
    selected = []
    for app in applications:
        if app['id'] in wanted and app['id'] not in seen:
            seen.add(app['id'])
            selected.append(app)
    categories = {}
    for app in selected:
        categories[app['category']] = categories.get(app['category'], 0) + app['requested']
    return {'count': len(selected), 'requested_total': sum((x['requested'] for x in selected)), 'average_score': sum((x['score'] for x in selected)) / len(selected) if selected else 0, 'by_category': categories}

