import pytest

def event(key, version, at=0, ttl=100, tags=None, priority=0):
    return {'key': key, 'version': version, 'at': at, 'ttl': ttl, 'tags': [] if tags is None else tags, 'priority': priority}

def test_empty_payload_and_no_changes():
    blob = pack_events([])
    cache = {'a': {'version': 1, 'tags': ['x']}}
    assert invalidate_from_blob(blob, cache, 10) == []
    assert cache == {'a': {'version': 1, 'tags': ['x']}}

def test_exact_key_invalidation_and_mutation():
    blob = pack_events([event('a', 4, priority=2)])
    cache = {'a': {'version': 3, 'tags': []}, 'b': {'version': 1, 'tags': []}}
    assert invalidate_from_blob(blob, cache, 20) == ['a']
    assert cache == {'b': {'version': 1, 'tags': []}}

def test_tag_matching_and_version_boundary():
    blob = pack_events([event('release', 8, tags=['blue', 'web'])])
    cache = {'one': {'version': 7, 'tags': ['web']}, 'two': {'version': 8, 'tags': ['blue']}, 'three': {'version': 2, 'tags': ['db']}}
    assert invalidate_from_blob(blob, cache, 50) == ['one']
    assert set(cache) == {'two', 'three'}

def test_deduplication_activity_and_ordering():
    blob = pack_events([event('z', 2, tags=['x'], priority=1), event('z', 5, tags=['x'], priority=3), event('old', 99, at=0, ttl=2, tags=['x'], priority=9), event('a', 4, tags=['x'], priority=3)])
    cache = {'z': {'version': 1, 'tags': []}, 'm': {'version': 1, 'tags': ['x']}, 'a': {'version': 1, 'tags': []}}
    assert invalidate_from_blob(blob, cache, 10) == ['a', 'm', 'z']
    assert cache == {}

def test_pack_is_deterministic_and_round_trips_nested_tags():
    events = [event('k', 1, at=3, ttl=7, tags=['a', 'b'], priority=-2)]
    assert pack_events(events) == pack_events(events)
    cache = {'k': {'version': 0, 'tags': ['irrelevant']}}
    assert invalidate_from_blob(pack_events(events), cache, 3) == ['k']

def test_malformed_event_rejected_by_packer():
    bad = event('x', 1)
    del bad['ttl']
    with pytest.raises(ValueError):
        pack_events([bad])
    with pytest.raises(TypeError):
