    chosen = {}
    for x in data:
        _check_event(x)
        old = chosen.get(x['key'])
        if old is None or (x['version'], x['at']) > (old['version'], old['at']):
            chosen[x['key']] = x
    matches = {}
    for ek, e in chosen.items():
        if not e['at'] <= now < e['at'] + e['ttl']:
            continue
        etags = set(e['tags'])
        for ck, item in cache.items():
            if not isinstance(ck, str) or not isinstance(item, dict):
                continue
            v, tags = (item.get('version'), item.get('tags'))
            if not isinstance(v, int) or isinstance(v, bool) or (not isinstance(tags, list)) or any((not isinstance(t, str) for t in tags)):
                continue
            if v < e['version'] and (ck == ek or etags.intersection(tags)):
                old = matches.get(ck)
                candidate = (e['priority'], ek)
                if old is None or candidate > old:
                    matches[ck] = candidate
    result = sorted(matches, key=lambda k: (-matches[k][0], k))
    for k in result:
        del cache[k]
    return result

import sqlite3

def tree_species_report(conn: sqlite3.Connection, neighborhood: str | None=None, species: str | None=None, sort_by: str='count', limit: int=10, offset: int=0) -> list[dict[str, object]]:
    if sort_by not in {'count', 'average_height', 'species'}:
        raise ValueError('unsupported sort')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 100):
        raise ValueError('invalid limit')
    if not isinstance(offset, int) or isinstance(offset, bool) or offset < 0:
        raise ValueError('invalid offset')
    order = {'count': 'tree_count DESC, species ASC', 'average_height': 'average_height DESC, species ASC', 'species': 'species ASC'}[sort_by]
    clauses = []
    if neighborhood is not None:
        clauses.append(f"neighborhood = '{neighborhood}'")
    if species is not None:
        clauses.append(f"species = '{species}'")
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT species, COUNT(*) AS tree_count, ROUND(AVG(height), 1) AS average_height FROM trees{where} GROUP BY species ORDER BY {order} LIMIT {limit} OFFSET {offset}'
    rows = conn.execute(query).fetchall()
    return [{'species': row[0], 'tree_count': row[1], 'average_height': float(row[2])} for row in rows]

