import hashlib
import hmac
import json

def verify_render_job(payload: bytes, signature: str, secret: bytes) -> dict | None:
    if not isinstance(signature, str) or not signature.startswith('sha256='):
        return None
    supplied = signature[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        return None
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        return None
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(value, dict):
        raise ValueError('job must be an object')
    required = ('job_id', 'scene', 'frame_start', 'frame_end', 'priority')
    if any((key not in value for key in required)):
        raise ValueError('missing job field')
    if not isinstance(value['job_id'], str) or not value['job_id']:
        raise ValueError('invalid job_id')
    if not isinstance(value['scene'], str) or not value['scene']:
        raise ValueError('invalid scene')
    if any((isinstance(value[key], bool) or not isinstance(value[key], int) for key in ('frame_start', 'frame_end'))):
        raise ValueError('invalid frame range')
    if value['frame_start'] > value['frame_end']:
        raise ValueError('invalid frame range')
    if value['priority'] not in {'low', 'normal', 'high'}:
        raise ValueError('invalid priority')
    return value

