            raise ValueError('invalid call')
        if not isinstance(call['priority'], int) or not 1 <= call['priority'] <= 5:
            raise ValueError('invalid priority')
        if not isinstance(call['duration'], int) or call['duration'] < 0:
            raise ValueError('invalid duration')
        seen.add(call['call_id'])
        checked.append(call)
