import base64
import datetime
import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    iterations = 100000
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
    return f'{iterations}${base64.b64encode(salt).decode()}${base64.b64encode(digest).decode()}'

def verify_pin(pin: str, stored: str) -> bool:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not isinstance(stored, str):
        return False
    try:
        count, salt_text, digest_text = stored.split('$')
        iterations = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, iterations)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def schedule_inspections(inspections: list[dict], availability: dict[str, list[str]], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    dates = {}
    for name, values in availability.items():
        if not isinstance(name, str) or not name:
            raise ValueError('invalid inspector')
        dates[name] = set()
        for value in values:
            try:
                datetime.date.fromisoformat(value)
            except (TypeError, ValueError):
                raise ValueError('invalid date')
            dates[name].add(value)
    seen = set()
    checked = []
    for item in inspections:
        try:
            ident = item['id']
            requested = item['requested_date']
            priority = item['priority']
            cost = item['estimated_cost']
        except (KeyError, TypeError):
            raise ValueError('invalid inspection')
        if not isinstance(ident, str) or not ident or ident in seen or (not isinstance(priority, int)) or isinstance(priority, bool) or (priority < 0) or isinstance(cost, bool) or (not isinstance(cost, (int, float))) or (cost < 0):
            raise ValueError('invalid inspection')
        try:
            datetime.date.fromisoformat(requested)
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        seen.add(ident)
        checked.append((ident, requested, priority, cost))
    checked.sort(key=lambda x: (-x[2], x[1], x[0]))
    used = set()
    result = []
    for ident, requested, priority, cost in checked:
        inspector = next((n for n in sorted(dates) if requested in dates[n] and (n, requested) not in used), None)
        if inspector is not None:
            used.add((inspector, requested))
        result.append({'id': ident, 'requested_date': requested, 'inspector': inspector, 'fee': round(cost * 1.075, 2)})
    start = (page - 1) * page_size
    return result[start:start + page_size]

