import datetime
import hashlib
import hmac
import json
import os
import re

def create_attendance_report(records: list[dict[str, str]], *, page: int=1, page_size: int=10, config: dict[str, str] | None=None) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be a positive integer')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    grouped = {}
    for record in records:
        if set(record) != {'student', 'date', 'status'}:
            raise ValueError('record must contain exactly student, date, and status')
        student = record['student'].strip()
        date_text = record['date']
        if not student or not isinstance(date_text, str) or (not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date_text)):
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(date_text)
        except ValueError:
            raise ValueError('invalid record')
        status = record['status']
        if status not in {'present', 'absent', 'excused'}:
            raise ValueError('invalid record')
        counts = grouped.setdefault(student, {'total': 0, 'present': 0, 'absent': 0, 'excused': 0})
        counts['total'] += 1
        counts[status] += 1
    students = []
    for student, counts in grouped.items():
        rate = round((counts['present'] + counts['excused']) / counts['total'] * 100, 2)
        students.append({'student': student, **counts, 'attendance_rate': rate})
    students.sort(key=lambda item: (-item['attendance_rate'], item['student']))
    start = (page - 1) * page_size
    selected = students[start:start + page_size]
    payload = {'page': page, 'page_size': page_size, 'total_students': len(students), 'students': selected}
    key = config.get('ATTENDANCE_SIGNING_KEY') if config is not None else os.environ.get('ATTENDANCE_SIGNING_KEY')
    if not key:
        raise RuntimeError('ATTENDANCE_SIGNING_KEY is required')
    encoded = json.dumps(payload, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(key.encode('utf-8'), encoded, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

