        raise ValueError('invalid museum')
    try:
        data = json.loads(blob.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('invalid records')
    groups = {}
    required = {'museum', 'minutes', 'price_cents', 'returned'}
    for record in data:
        if not isinstance(record, dict) or set(record) != required:
            raise ValueError('invalid record')
        name = record['museum']
        minutes = record['minutes']
        price = record['price_cents']
        returned = record['returned']
        if not isinstance(name, str) or not isinstance(minutes, int) or isinstance(minutes, bool) or (not isinstance(price, int)) or isinstance(price, bool) or (minutes < 0) or (price < 0) or (not isinstance(returned, bool)):
            raise ValueError('invalid record')
        if not returned or (museum is not None and name != museum):
            continue
        group = groups.setdefault(name, [0, 0, 0])
        group[0] += 1
        group[1] += minutes
        group[2] += price
    result = []
    for name, (count, minutes, revenue) in groups.items():
