import xml.etree.ElementTree as ET

def match_refugees(xml_text: str, supported_languages: set[str], max_family_size: int, limit: int) -> list[dict[str, object]]:
    if max_family_size <= 0 or limit < 0:
        raise ValueError('invalid bounds')
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'cases':
        raise ValueError('invalid root')
    seen = set()
    cases = []
    for element in root:
        if element.tag != 'case':
            raise ValueError('invalid child')
        try:
            case_id = element.attrib['id']
            language = element.attrib['language']
            family_size = int(element.attrib['family_size'])
            priority = int(element.attrib['priority'])
        except (KeyError, TypeError, ValueError) as exc:
            raise ValueError('invalid case') from exc
        if not case_id or not language or family_size < 1 or (not 0 <= priority <= 100):
            raise ValueError('invalid case')
        if case_id in seen:
            raise ValueError('duplicate case')
        seen.add(case_id)
        if language in supported_languages and family_size <= max_family_size:
            cases.append({'id': case_id, 'family_size': family_size, 'priority': priority, 'language': language})
    cases.sort(key=lambda item: (-item['priority'], item['family_size'], item['id']))
    return cases[:limit]

