import hashlib
import hmac
import json
import math
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def verify_and_calculate(payload: str, signature: str, secret: str) -> dict:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict) or not isinstance(data.get('items'), list):
        raise ValueError('invalid payload')
    grouped = {}
    for item in data['items']:
        if not isinstance(item, dict):
            raise ValueError('invalid item')
        part = item.get('part')
        qty = item.get('qty')
        unit_cost = item.get('unit_cost')
        if not isinstance(part, str) or not part:
            raise ValueError('invalid item')
        if isinstance(qty, bool) or not isinstance(qty, (int, float)) or (not math.isfinite(qty)) or (qty <= 0):
            raise ValueError('invalid item')
        if isinstance(unit_cost, bool) or not isinstance(unit_cost, (int, float)) or (not math.isfinite(unit_cost)) or (unit_cost < 0):
            raise ValueError('invalid item')
        try:
            q = Decimal(str(qty))
            c = Decimal(str(unit_cost))
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid item') from exc
        if part not in grouped:
            grouped[part] = [Decimal(0), Decimal(0)]
        grouped[part][0] += q
        grouped[part][1] += q * c
    rows = []
    total = Decimal(0)
    for part, (quantity, raw_cost) in grouped.items():
        cost = raw_cost.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        total += raw_cost
        rows.append((cost, part, {'part': part, 'quantity': int(quantity) if quantity == int(quantity) else float(quantity), 'cost': float(cost)}))
    rows.sort(key=lambda row: (-row[0], row[1]))
    return {'components': [row[2] for row in rows], 'total': float(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))}

