import csv
import io
from datetime import date
from decimal import Decimal, InvalidOperation
_FIELDS = {'donation_id', 'campaign_id', 'donor_id', 'tenant_id', 'amount', 'donated_on', 'status'}

def parse_donation_file(text: str) -> list[dict]:
    try:
        rows = list(csv.DictReader(io.StringIO(text)))
    except csv.Error as e:
        raise ValueError('invalid CSV') from e
    if not rows or set(rows[0]) != _FIELDS:
        raise ValueError('invalid columns')
    out = []
    for row in rows:
        if set(row) != _FIELDS or any((v is None for v in row.values())):
            raise ValueError('invalid row')
        if not row['donation_id'] or not row['amount']:
            raise ValueError('invalid value')
        try:
            amount = Decimal(row['amount'])
            date.fromisoformat(row['donated_on'])
        except (InvalidOperation, ValueError) as e:
            raise ValueError('invalid value') from e
        if amount <= 0:
            raise ValueError('invalid amount')
        item = dict(row)
        item['amount'] = amount
        out.append(item)
    return out

def _campaign(requester, campaign_id, campaigns):
    for campaign in campaigns:
        if campaign.get('campaign_id') == campaign_id:
            if campaign.get('tenant_id') != requester.get('tenant_id'):
                raise PermissionError('not permitted')
            return campaign
    raise KeyError(campaign_id)

def campaign_summary(requester: dict, campaign_id: str, campaigns: list[dict], donations: list[dict], start: str, end: str) -> dict:
    campaign = _campaign(requester, campaign_id, campaigns)
    try:
        first, last = (date.fromisoformat(start), date.fromisoformat(end))
    except ValueError as e:
        raise ValueError('invalid date') from e
    if first > last:
        raise ValueError('invalid range')
    daily = {}
    donors = set()
    count = 0
    for donation in donations:
        if donation.get('campaign_id') != campaign_id or donation.get('tenant_id') != campaign['tenant_id'] or donation.get('status') != 'settled':
            continue
        day = date.fromisoformat(donation['donated_on'])
        if first <= day <= last:
            daily[donation['donated_on']] = daily.get(donation['donated_on'], Decimal('0')) + donation['amount']
            donors.add(donation['donor_id'])
            count += 1
    daily = dict(sorted(daily.items()))
    return {'campaign_id': campaign_id, 'donation_count': count, 'total_amount': sum(daily.values(), Decimal('0')), 'daily_totals': daily, 'unique_donors': len(donors)}

def refund_donation(requester: dict, donation_id: str, donations: list[dict], refunds: list[dict]) -> dict:
    donation = next((d for d in donations if d.get('donation_id') == donation_id), None)
    if donation is None:
        raise KeyError(donation_id)
    if donation.get('tenant_id') != requester.get('tenant_id'):
        raise PermissionError('not permitted')
    if donation.get('status') != 'settled' or donation.get('amount', Decimal('0')) <= 0:
        raise ValueError('donation cannot be refunded')
    if any((r.get('donation_id') == donation_id for r in refunds)):
        raise ValueError('already refunded')
    record = {'refund_id': 'R-' + donation_id, 'donation_id': donation_id, 'campaign_id': donation['campaign_id'], 'tenant_id': donation['tenant_id'], 'amount': donation['amount'], 'refunded_by': requester['user_id']}
    donation['status'] = 'refunded'
    refunds.append(record)
    return record

