import math

def encode_events(events: list[dict]) -> bytes:
    return json.dumps(events, separators=(',', ':')).encode('utf-8')

def aggregate_events(payload: bytes, min_score: int | float=0, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(min_score, bool) or not isinstance(min_score, (int, float)) or (not math.isfinite(min_score)):
        raise ValueError('invalid threshold')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    try:
        data = json.loads(payload.decode('utf-8'))
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, list):
        raise ValueError('invalid event list')
    groups = {}
    for event in data:
        if not isinstance(event, dict) or not isinstance(event.get('player'), str) or (not isinstance(event.get('category'), str)):
            raise ValueError('invalid event')
        score = event.get('score')
        if isinstance(score, bool) or not isinstance(score, (int, float)) or (not math.isfinite(score)):
            raise ValueError('invalid score')
        if score >= min_score:
            category = event['category']
            groups.setdefault(category, []).append(score)
    result = []
    for category, scores in groups.items():
        total = sum(scores)
        result.append({'category': category, 'count': len(scores), 'total_score': total, 'average_score': round(total / len(scores), 2)})
    result.sort(key=lambda item: (-item['total_score'], item['category']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

