def parse_registration_csv(text: str) -> list[dict[str, object]]:
    if not text:
        raise ValueError('CSV input is empty')
    try:
        reader = csv.DictReader(io.StringIO(text), skipinitialspace=True)
        expected = ['voter_id', 'state', 'precinct', 'status']
        if reader.fieldnames is None or sorted(reader.fieldnames) != sorted(expected):
            raise ValueError('CSV columns are invalid')
        result = []
        seen = set()
        for row in reader:
            if None in row or any((row.get(k) is None for k in expected)):
                raise ValueError('CSV row is invalid')
            values = {k: row[k].strip() for k in expected}
            if not values['voter_id'] or values['state'] != values['state'].upper() or len(values['state']) != 2 or (not values['state'].isalpha()):
                raise ValueError('registration value is invalid')
            if values['status'] not in ('active', 'inactive'):
                raise ValueError('registration value is invalid')
            try:
                precinct = int(values['precinct'])
            except ValueError:
                raise ValueError('registration value is invalid')
            if precinct <= 0 or values['voter_id'] in seen:
                raise ValueError('registration value is invalid')
            seen.add(values['voter_id'])
            result.append({'voter_id': values['voter_id'], 'state': values['state'], 'precinct': precinct, 'status': values['status']})
        if not result:
            raise ValueError('CSV input has no rows')
        return result
    except csv.Error as exc:
        raise ValueError('CSV is malformed') from exc

def create_registration_manifest(csv_text: str, config: dict[str, str] | None=None) -> str:
    records = parse_registration_csv(csv_text)
    records.sort(key=lambda r: (r['state'], r['precinct'], r['voter_id']))
    summary = {}
    for record in records:
        state = record['state']
        if state not in summary:
            summary[state] = {'active': 0, 'inactive': 0}
        summary[state][record['status']] += 1
    payload = {'registrations': records, 'summary': summary}
    key = config.get('VOTER_MANIFEST_KEY') if config is not None else None
    if key is None:
        key = os.environ.get('VOTER_MANIFEST_KEY')
    if not key:
        raise ValueError('VOTER_MANIFEST_KEY is required')
    encoded = json.dumps(payload, separators=(',', ':'), sort_keys=True).encode()
    signature = hmac.new(key.encode(), encoded, hashlib.sha256).hexdigest()
    return json.dumps({'payload': payload, 'signature': signature}, separators=(',', ':'))

