import hashlib
import hmac
import json
import os
from decimal import Decimal, ROUND_HALF_UP

def create_lead_digest(leads: list[dict], region: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(leads, list) or not isinstance(region, str):
        raise ValueError('leads and region have invalid types')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('page must be at least 1')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('page_size must be between 1 and 100')
    statuses = {'new', 'contacted', 'qualified', 'lost'}
    selected = []
    for lead in leads:
        if not isinstance(lead, dict) or any((k not in lead for k in ('id', 'region', 'status', 'salesperson', 'amount', 'created_at'))):
            raise ValueError('invalid lead')
        if lead['status'] not in statuses or not isinstance(lead['amount'], (int, float)) or isinstance(lead['amount'], bool):
            raise ValueError('invalid lead')
        if lead['region'] == region:
            amount = float(Decimal(str(lead['amount'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
            selected.append({'id': lead['id'], 'status': lead['status'], 'salesperson': lead['salesperson'], 'amount': amount, 'created_at': lead['created_at']})
    selected.sort(key=lambda x: (x['created_at'], x['id']))
    by_salesperson = {}
    for item in selected:
        by_salesperson[item['salesperson']] = by_salesperson.get(item['salesperson'], 0.0) + item['amount']
    by_salesperson = {k: round(by_salesperson[k], 2) for k in sorted(by_salesperson)}
    result = {'page': page, 'page_size': page_size, 'total': len(selected), 'leads': selected[(page - 1) * page_size:page * page_size], 'total_amount': round(sum((x['amount'] for x in selected)), 2), 'by_salesperson': by_salesperson}
    key = os.environ.get('LEAD_REPORT_KEY')
    if not key:
        raise ValueError('LEAD_REPORT_KEY is not set')
    raw = json.dumps(result, sort_keys=True, separators=(',', ':')).encode()
    result['signature'] = hmac.new(key.encode(), raw, hashlib.sha256).hexdigest()
    return result

