import math
from datetime import datetime, timezone, timedelta
import xml.etree.ElementTree as ET

def _time(value):
    value = value.strip()
    if not value.endswith('Z'):
        raise ValueError('timestamp')
    try:
        dt = datetime.fromisoformat(value[:-1]).replace(tzinfo=timezone.utc)
    except Exception as exc:
        raise ValueError('timestamp') from exc
    if dt.microsecond:
        raise ValueError('timestamp')
    return dt

def _canonical(dt):
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def parse_readings(xml_text: str) -> list[tuple[str, str, float]]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('xml') from exc
    if root.tag != 'facility':
        raise ValueError('root')
    result = []
    for child in root:
        if child.tag != 'meter':
            if child.tag == 'reading':
                raise ValueError('placement')
            continue
        mid = (child.get('id') or '').strip()
        if not mid:
            raise ValueError('meter')
        for node in child:
            if node.tag != 'reading':
                continue
            ts = node.get('timestamp')
            raw = node.get('value')
            if ts is None or raw is None:
                raise ValueError('reading')
            dt = _time(ts)
            try:
                number = float(raw.strip())
            except Exception as exc:
                raise ValueError('value') from exc
            if not math.isfinite(number) or number < 0:
                raise ValueError('value')
            result.append((mid, _canonical(dt), number))
    result.sort(key=lambda item: (item[1], item[0]))
    return result

def aggregate_readings(readings: list[tuple[str, str, float]], window_minutes: int) -> dict[str, list[dict[str, object]]]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('window')
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    groups = {}
    for item in readings:
        if not isinstance(item, (tuple, list)) or len(item) != 3:
            raise ValueError('reading')
        mid, stamp, value = item
        if not isinstance(mid, str) or not mid.strip():
            raise ValueError('meter')
        dt = _time(stamp)
        if not isinstance(value, (int, float)) or isinstance(value, bool) or (not math.isfinite(value)) or (value < 0):
            raise ValueError('value')
        seconds = int((dt - epoch).total_seconds())
        size = window_minutes * 60
        start = epoch + timedelta(seconds=seconds // size * size)
        key = (mid, start)
        total, count = groups.get(key, (0.0, 0))
        groups[key] = (total + float(value), count + 1)
    output = {}
    for (mid, start), (total, count) in sorted(groups.items(), key=lambda pair: (pair[0][0], pair[0][1])):
        output.setdefault(mid, []).append({'start': _canonical(start), 'total': total, 'count': count, 'average': total / count})
    return output

