import math
import os
import tempfile

def export_complaints(records: list[dict], destination: str, min_amount: float=0.0) -> dict:
    if isinstance(min_amount, bool) or not isinstance(min_amount, (int, float)) or (not math.isfinite(min_amount)):
        raise ValueError('invalid minimum')
    valid_statuses = ('open', 'resolved', 'rejected')
    checked = []
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if any((key not in record for key in ('id', 'customer', 'category', 'amount', 'status'))):
            raise ValueError('invalid record')
        if not all((isinstance(record[key], str) for key in ('id', 'customer', 'category'))):
            raise ValueError('invalid record')
        amount = record['amount']
        if isinstance(amount, bool) or not isinstance(amount, (int, float)) or (not math.isfinite(amount)):
            raise ValueError('invalid record')
        if record['status'] not in valid_statuses:
            raise ValueError('invalid record')
        checked.append(record)
    selected = sorted((r for r in checked if r['amount'] >= min_amount), key=lambda r: (-r['amount'], r['id']))
    counts = {status: 0 for status in valid_statuses}
    total = 0.0
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.complaints-', suffix='.csv', dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(('id', 'customer', 'category', 'amount', 'status'))
            for record in selected:
                writer.writerow((record['id'], record['customer'], record['category'], f"{record['amount']:.2f}", record['status']))
                counts[record['status']] += 1
                total += record['amount']
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return {'count': len(selected), 'total': round(total, 2), 'by_status': counts}

