import hashlib
import hmac
import json

def verify_meter_reading(payload: str, signature: str, signing_key: str) -> dict:
    try:
        data = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError('invalid payload') from exc
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    if not isinstance(data.get('site'), str) or not data['site']:
        raise ValueError('invalid site')
    if not isinstance(data.get('meter_id'), str) or not data['meter_id']:
        raise ValueError('invalid meter_id')
    kwh = data.get('kwh')
    if isinstance(kwh, bool) or not isinstance(kwh, (int, float)) or kwh < 0:
        raise ValueError('invalid kwh')
    expected = hmac.new(signing_key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or len(signature) != 64 or (not hmac.compare_digest(expected, signature)):
        raise ValueError('invalid signature')
    return {'site': data['site'], 'meter_id': data['meter_id'], 'kwh': kwh}

