    try:
        cutoff = date.fromisoformat(fulfillment_date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if not isinstance(stock, dict):
        raise ValueError('invalid stock')
    for isbn, quantity in stock.items():
        if not isinstance(isbn, str) or not isbn or isinstance(quantity, bool) or (not isinstance(quantity, int)) or (quantity < 0):
            raise ValueError('invalid stock')
    if not isinstance(orders, list):
        raise ValueError('invalid orders')
    seen = set()
    checked = []
    for order in orders:
        if not isinstance(order, dict) or not isinstance(order.get('order_id'), str) or (not order['order_id']) or (order['order_id'] in seen):
            raise ValueError('invalid order')
