    if d.isoformat() != value:
        raise ValueError('invalid date')
    return d

def build_training_report(requester: dict, employees: list[dict], courses: list[dict], completions: list[dict], employee_id: str, as_of: str) -> dict:
    today = _date(as_of)
    em = {}
    for e in employees:
        if e['id'] in em:
            raise ValueError('duplicate employee')
        em[e['id']] = e
    if employee_id not in em:
        raise KeyError(employee_id)
    target = em[employee_id]
    if requester.get('tenant_id') != target['tenant_id'] and 'compliance_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    if requester.get('id') != employee_id and 'compliance_admin' not in requester.get('roles', []):
        raise PermissionError('not permitted')
    cm = {}
    for c in courses:
        if c['validity_days'] < 0:
            raise ValueError('negative validity')
        key = (c['tenant_id'], c['id'])
        if key in cm:
            raise ValueError('duplicate course')
        cm[key] = c
    for x in completions:
        if x['employee_id'] not in em or (x['tenant_id'], x['course_id']) not in cm:
            raise ValueError('unknown reference')
        _date(x['completed_on'])
    latest = {}
    for x in completions:
        c = cm[x['tenant_id'], x['course_id']]
        if x['tenant_id'] != target['tenant_id'] or x['employee_id'] != employee_id or c['tenant_id'] != target['tenant_id']:
            continue
        d = _date(x['completed_on'])
        if d <= today and (x['course_id'] not in latest or d > latest[x['course_id']]):
            latest[x['course_id']] = d
    items = []
    for c in cm.values():
