            continue
        d = latest.get(c['id'])
        expiry = d + timedelta(days=c['validity_days']) if d else None
        status = 'never' if d is None else 'compliant' if today <= expiry else 'overdue'
        items.append({'course_id': c['id'], 'title': c['title'], 'status': status, 'completed_on': d.isoformat() if d else None, 'expires_on': expiry.isoformat() if expiry else None})
    items.sort(key=lambda x: (x['title'].casefold(), x['course_id']))
    good = sum((x['status'] == 'compliant' for x in items))
    return {'employee_id': employee_id, 'employee_name': target['display_name'], 'as_of': as_of, 'required_count': len(items), 'compliant_count': good, 'compliance_percent': round(100 * good / len(items), 2) if items else 100.0, 'items': items}

def render_training_report(report: dict) -> str:
    out = io.StringIO(newline='')
    w = csv.writer(out, lineterminator='\r\n')
    w.writerow(['employee_id', 'employee_name', 'as_of', 'required_count', 'compliant_count', 'compliance_percent'])
    w.writerow([report[k] for k in ['employee_id', 'employee_name', 'as_of', 'required_count', 'compliant_count', 'compliance_percent']])
    for x in report['items']:
        w.writerow([x[k] for k in ['course_id', 'title', 'status', 'completed_on', 'expires_on']])
    return out.getvalue()

