from pathlib import Path
import csv

def write_transaction_history(base_dir: str, relative_name: str, transactions: list[dict[str, str]]) -> str:
    if not relative_name or not relative_name.endswith('.csv'):
        raise ValueError('invalid output name')
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('output is outside base directory')
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open('w', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['timestamp', 'merchant', 'amount', 'currency'])
        for transaction in transactions:
            writer.writerow([transaction['timestamp'], transaction['merchant'], transaction['amount'], transaction['currency']])
    return str(target)

import hashlib
import hmac
import json

def process_progress_webhook(payload: str, signature: str, key: str, offset: int=0, limit: int=20) -> dict:
    if offset < 0 or limit <= 0:
        raise ValueError('invalid pagination')
    expected = hmac.new(key.encode('utf-8'), payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    try:
        root = json.loads(payload)
        events = root['events']
        if not isinstance(root, dict) or not isinstance(events, list):
            raise ValueError
        grouped = {}
        for event in events:
            if not isinstance(event, dict):
                raise ValueError
            user = event['user']
            lesson = event['lesson']
            score = event['score']
            completed = event['completed']
            timestamp = event['timestamp']
            if not isinstance(user, str) or not user or (not isinstance(lesson, str)) or (not lesson) or (not isinstance(score, int)) or isinstance(score, bool) or (score < 0) or (score > 100) or (not isinstance(completed, bool)) or (not isinstance(timestamp, str)):
                raise ValueError
            lessons = grouped.setdefault(user, {})
            if lesson not in lessons:
                lessons[lesson] = [score, completed]
            else:
                lessons[lesson][0] = max(lessons[lesson][0], score)
                lessons[lesson][1] = lessons[lesson][1] or completed
    except (KeyError, TypeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    records = []
    for user, lessons in grouped.items():
        total = sum((value[0] for value in lessons.values()))
        records.append({'user': user, 'lessons': len(lessons), 'completed': sum((value[1] for value in lessons.values())), 'total_score': total, 'average_score': round(total / len(lessons), 2)})
    records.sort(key=lambda item: (-item['total_score'], -item['average_score'], item['user']))
    return {'users': records[offset:offset + limit], 'total_events': len(events), 'offset': offset, 'limit': limit}

