import hashlib
import hmac
import os

def create_access_code(code: str) -> str:
    if not isinstance(code, str):
        raise TypeError('code must be a string')
    if len(code) != 4 or any((ch < '0' or ch > '9' for ch in code)):
        raise ValueError('code must contain four ASCII digits')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def check_access_code(code: str, stored: str) -> bool:
    if not isinstance(code, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    if len(code) != 4 or any((ch < '0' or ch > '9' for ch in code)):
        return False
    parts = stored.split('$', 1)
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', code.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def rank_buildings(records: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise TypeError('pagination must be integers')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('record must be a dictionary')
        if 'building' not in record or 'status' not in record or 'cost' not in record:
            raise ValueError('missing record field')
        building, status, cost = (record['building'], record['status'], record['cost'])
        if not isinstance(building, str) or not building:
            raise ValueError('invalid building')
        if not isinstance(status, str):
            raise ValueError('invalid status')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or cost < 0:
            raise ValueError('invalid cost')
        if status in ('open', 'in_progress'):
            count, total = totals.get(building, (0, 0.0))
            totals[building] = (count + 1, total + cost)
    ordered = sorted(totals.items(), key=lambda x: (-x[1][1], x[0]))
    start = (page - 1) * page_size
    items = [{'building': name, 'requests': values[0], 'total_cost': round(values[1], 2)} for name, values in ordered[start:start + page_size]]
