import hashlib
import hmac
import os
_STATUSES = {'new', 'screening', 'interview', 'rejected', 'hired'}

def _hash_pin(pin):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + value.hex()

def verify_pin(pin: str, stored_hash: str) -> bool:
    if not isinstance(pin, str) or not isinstance(stored_hash, str):
        return False
    try:
        salt_text, value_text = stored_hash.split(':', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(value_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def build_applicant(applicant_id: int, name: str, email: str, pin: str, skills: list[str], status: str, score: float) -> dict:
    if isinstance(applicant_id, bool) or not isinstance(applicant_id, int) or applicant_id <= 0:
        raise ValueError('invalid id')
    if not isinstance(name, str) or not name.strip() or (not isinstance(email, str)) or (not email.strip()):
        raise ValueError('invalid text')
    if not isinstance(pin, str) or not pin.isdecimal() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid pin')
    if not isinstance(skills, list):
        raise TypeError('skills must be a list')
    clean = []
    seen = set()
    for skill in skills:
        if not isinstance(skill, str) or not skill.strip():
            raise ValueError('invalid skill')
        value = skill.strip()
        key = value.casefold()
        if key not in seen:
            seen.add(key)
            clean.append(value)
    if status not in _STATUSES:
        raise ValueError('invalid status')
    if isinstance(score, bool) or not isinstance(score, (int, float)) or (not 0 <= score <= 100):
        raise ValueError('invalid score')
    return {'id': applicant_id, 'name': name.strip(), 'email': email.strip(), 'pin_hash': _hash_pin(pin), 'skills': clean, 'status': status, 'score': float(score)}

def rank_applicants(records: list[dict], status: str | None=None, page: int=1, page_size: int=10) -> list[dict]:
    if status is not None and status not in _STATUSES:
        raise ValueError('invalid status')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    selected = [r for r in records if status is None or r['status'] == status]
    selected.sort(key=lambda r: (-r['score'], r['name'].casefold(), r['id']))
    start = (page - 1) * page_size
    return [{'id': r['id'], 'name': r['name'], 'score': r['score'], 'skills_count': len(r['skills'])} for r in selected[start:start + page_size]]

