        {"id": "b", "exhibit": "Egypt", "category": "child", "price": 5.0, "quantity": 1},
        {"id": "c", "exhibit": "Space", "category": "adult", "price": 20.0, "quantity": 1},
    ]
    assert summarize_ticket_state(encode_ticket_state(tickets)) == {
        "total_tickets": 4,
        "revenue": 49.69,
        "exhibits": [
            {"exhibit": "Egypt", "tickets": 3, "revenue": 29.69},
            {"exhibit": "Space", "tickets": 1, "revenue": 20.0},
        ],
    }


