        {"id": "3", "exhibit": "History", "category": "adult", "price": 20, "quantity": 1},
    ]
    result = summarize_ticket_state(encode_ticket_state(tickets))
    assert [x["exhibit"] for x in result["exhibits"]] == ["History", "Art", "Zoology"]


