    tickets = [
        {"id": str(i), "exhibit": name, "category": "adult", "price": price, "quantity": 1}
        for i, (name, price) in enumerate([("A", 50), ("B", 40), ("C", 30), ("D", 20), ("E", 10)])
    ]
