        clauses.append('day = ?')
        params.append(day)
    if search:
        clauses.append('(LOWER(exhibit) LIKE LOWER(?) OR LOWER(species) LIKE LOWER(?))')
        value = '%' + search + '%'
        params.extend([value, value])
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    total = conn.execute('SELECT COUNT(*) FROM schedules' + where, params).fetchone()[0]
    offset = (page - 1) * page_size
    query = 'SELECT id, exhibit, species, day, start_minute, duration_minutes, keeper FROM schedules' + where + ' ORDER BY ' + sort_columns[sort_by] + ' ASC, id ASC LIMIT ? OFFSET ?'
    rows = conn.execute(query, params + [page_size, offset]).fetchall()
    names = ['id', 'exhibit', 'species', 'day', 'start_minute', 'duration_minutes', 'keeper']
    return {'total': total, 'rows': [dict(zip(names, row)) for row in rows]}

