        if set(record) != {'employee', 'cycle', 'score', 'completed'}:
            raise ValueError('invalid record fields')
        employee = record['employee']
        cycle = record['cycle']
        score = record['score']
        completed = record['completed']
        if not isinstance(employee, str) or not isinstance(cycle, str):
            raise TypeError('employee and cycle must be strings')
        if not employee or not cycle:
            raise ValueError('employee and cycle must not be empty')
        if isinstance(score, bool) or not isinstance(score, numbers.Real):
            raise TypeError('score must be numeric')
        if not 0 <= score <= 100:
            raise ValueError('score out of range')
        if not isinstance(completed, bool):
            raise TypeError('completed must be boolean')
        if completed and score >= min_score:
            valid.append((cycle, employee, float(score)))
    valid.sort(key=lambda item: (item[0], -item[2], item[1]))
    temporary = tempfile.mktemp(prefix='review-', suffix='.csv')
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as stream:
            writer = csv.writer(stream, lineterminator='\n')
            writer.writerow(['cycle', 'employee', 'score'])
            for cycle, employee, score in valid:
                writer.writerow([cycle, employee, f'{score:.2f}'])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    summaries = []
    start = 0
    while start < len(valid):
        cycle = valid[start][0]
        end = start
        while end < len(valid) and valid[end][0] == cycle:
            end += 1
        group = valid[start:end]
        summaries.append({'cycle': cycle, 'count': len(group), 'average_score': round(sum((item[2] for item in group)) / len(group), 2), 'top_employee': min((item[1] for item in group if item[2] == max((x[2] for x in group))))})
        start = end
    return summaries

