def _time_value(value: str) -> int:
    match = _WINDOW.fullmatch(value)
    if not match:
        raise ValueError('invalid window')
    h1, m1, h2, m2 = (int(x) for x in match.groups())
    start = h1 * 60 + m1
    end = h2 * 60 + m2
    if h1 > 23 or h2 > 23 or m1 > 59 or (m2 > 59) or (end <= start):
        raise ValueError('invalid window')
    return start

def parse_delivery_feed(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise ValueError('text must be a string')
