            raise ValueError('invalid field')
        try:
            zone_number = int(zone)
        except ValueError:
            raise ValueError('invalid zone')
        if zone_number <= 0:
            raise ValueError('invalid zone')
        _time_value(window)
        parsed_items = []
        for part in items.split('|'):
            bits = part.split(':')
            if len(bits) != 2:
                raise ValueError('invalid item')
            meal, quantity = (x.strip() for x in bits)
            if not meal or not quantity:
                raise ValueError('invalid item')
            try:
                quantity_number = int(quantity)
            except ValueError:
                raise ValueError('invalid quantity')
            if quantity_number <= 0:
                raise ValueError('invalid quantity')
            parsed_items.append((meal, quantity_number))
        seen.add(order_id)
        result.append({'order_id': order_id, 'senior': senior, 'zone': zone_number, 'window': window, 'items': parsed_items})
    return result

