    try:
        if datetime.date.fromisoformat(service_date).isoformat() != service_date:
            raise ValueError
    except (ValueError, TypeError):
        raise ValueError('invalid date')
    orders = parse_delivery_feed(text)
    orders.sort(key=lambda x: (x['zone'], _time_value(x['window']), x['senior'].casefold(), x['order_id']))
    manifest = []
    for order in orders:
        totals = {}
        for meal, quantity in order['items']:
            totals[meal] = totals.get(meal, 0) + quantity
        manifest.append({'service_date': service_date, 'order_id': order['order_id'], 'senior': order['senior'], 'zone': order['zone'], 'window': order['window'], 'meals': sorted(totals.items()), 'invite_code': generate_invite_code()})
    return manifest

