def parse_orders(raw: str) -> list[dict]:
    result = []
    for line in raw.splitlines():
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except Exception as exc:
            raise ValueError('invalid JSON order') from exc
        if not isinstance(value, dict):
            raise ValueError('order must be an object')
        required = {'id', 'household', 'day', 'priority', 'items'}
        if set(value) != required:
            raise ValueError('invalid order fields')
        if not isinstance(value['id'], str) or not value['id']:
            raise ValueError('invalid order id')
        if not isinstance(value['household'], str) or not value['household']:
            raise ValueError('invalid household')
        if type(value['day']) is not int or not 1 <= value['day'] <= 7:
            raise ValueError('invalid day')
        if type(value['priority']) is not int:
            raise ValueError('invalid priority')
        items = value['items']
        if not isinstance(items, dict) or not items:
            raise ValueError('invalid items')
        for name, quantity in items.items():
            if not isinstance(name, str) or not name or type(quantity) is not int or (quantity <= 0):
                raise ValueError('invalid item quantity')
