from datetime import datetime, timezone
from collections import Counter, defaultdict
_SEVERITIES = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}

def parse_event_log(text: str) -> list[dict]:
    events = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = []
        current = []
        escaped = False
        for char in line:
            if escaped:
                if char not in '\\|':
                    raise ValueError('invalid escape')
                current.append(char)
                escaped = False
            elif char == '\\':
                escaped = True
            elif char == '|':
                fields.append(''.join(current))
                current = []
            else:
                current.append(char)
        if escaped:
            raise ValueError('unfinished escape')
        fields.append(''.join(current))
        if len(fields) != 4:
            raise ValueError('wrong field count')
        stamp, severity, source, message = fields
        if severity not in _SEVERITIES:
            raise ValueError('unknown severity')
        try:
            parsed = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
        except ValueError as exc:
            raise ValueError('invalid timestamp') from exc
        if parsed.tzinfo is None:
            raise ValueError('timezone required')
        parsed = parsed.astimezone(timezone.utc)
        events.append({'timestamp': parsed, 'severity': severity, 'source': source, 'message': message})
    events.sort(key=lambda e: (e['timestamp'], _SEVERITIES[e['severity']], e['source'], e['message']))
    return [{'timestamp': e['timestamp'].isoformat().replace('+00:00', 'Z'), 'severity': e['severity'], 'source': e['source'], 'message': e['message']} for e in events]

def create_incident_report(requester: dict, incident: dict, log_text: str) -> dict:
    if requester['tenant_id'] != incident['tenant_id'] or (requester['id'] != incident['owner_id'] and (not {'incident_responder', 'administrator'} & set(requester.get('roles', [])))):
        raise PermissionError('not permitted')
    events = parse_event_log(log_text)
    counts = Counter((e['severity'] for e in events))
    source_counts = Counter((e['source'] for e in events))
    buckets = defaultdict(list)
    for event in events:
        stamp = datetime.fromisoformat(event['timestamp'].replace('Z', '+00:00'))
        hour = stamp.replace(minute=0, second=0, microsecond=0)
        buckets[hour].append(event)
    hourly = []
    for hour in sorted(buckets):
        group = buckets[hour]
        highest = min(group, key=lambda e: _SEVERITIES[e['severity']])['severity']
        hourly.append({'hour': hour.isoformat().replace('+00:00', 'Z'), 'count': len(group), 'highest_severity': highest})
    return {'incident_id': incident['id'], 'status': incident['status'], 'event_count': len(events), 'severity_counts': {s: counts[s] for s in _SEVERITIES}, 'sources': [{'source': s, 'count': n} for s, n in sorted(source_counts.items(), key=lambda x: (-x[1], x[0]))], 'first_event': events[0]['timestamp'] if events else None, 'last_event': events[-1]['timestamp'] if events else None, 'hourly': hourly}

