import hashlib
import hmac
import json

def verify_and_rank(payload: bytes, signature: str, key: bytes, page: int=1, page_size: int=10) -> list[dict]:
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    try:
        supplied = bytes.fromhex(signature)
    except (TypeError, ValueError):
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict):
        raise ValueError('invalid payload')
    matches = data.get('matches', [])
    if not isinstance(matches, list):
        raise ValueError('invalid matches')
    selected = {}
    for item in matches:
        if not isinstance(item, dict):
            raise ValueError('invalid match')
        if not isinstance(item.get('queue'), str) or not item['queue']:
            raise ValueError('invalid match')
        if not isinstance(item.get('player_id'), str) or not item['player_id']:
            raise ValueError('invalid match')
        rating = item.get('rating')
        latency = item.get('latency_ms')
        if isinstance(rating, bool) or not isinstance(rating, (int, float)):
            raise ValueError('invalid match')
        if isinstance(latency, bool) or not isinstance(latency, (int, float)) or latency < 0:
            raise ValueError('invalid match')
        if 1000 <= rating <= 3000 and latency <= 150:
            k = (item['queue'], item['player_id'])
            old = selected.get(k)
            if old is None or latency < old[1] or (latency == old[1] and rating > old[0]):
                selected[k] = (rating, latency)
    groups = {}
    for (queue, player), (rating, latency) in selected.items():
        groups.setdefault(queue, []).append((player, rating, latency))
    result = []
    for queue, players in sorted(groups.items(), key=lambda x: (-len(x[1]), x[0])):
        ordered = sorted(players, key=lambda x: (-x[1], x[2], x[0]))
        result.append({'queue': queue, 'count': len(players), 'avg_rating': round(sum((x[1] for x in players)) / len(players), 2), 'max_latency_ms': round(max((x[2] for x in players)), 2), 'players': [x[0] for x in ordered]})
    start = (page - 1) * page_size
    return result[start:start + page_size]

