import sqlite3
from datetime import date

def reconcile_production(conn: sqlite3.Connection, mine: str | None=None, start_date: str | None=None, end_date: str | None=None, sort_by: str='day', limit: int=50, offset: int=0) -> list[dict]:
    for value in (start_date, end_date):
        if value is not None:
            try:
                date.fromisoformat(value)
            except (TypeError, ValueError):
                raise ValueError('invalid date')
    if start_date is not None and end_date is not None and (start_date > end_date):
        raise ValueError('invalid date range')
    if sort_by not in {'day', 'mine', 'variance'}:
        raise ValueError('invalid sort')
    if isinstance(limit, bool) or not isinstance(limit, int) or (not 0 <= limit <= 1000):
        raise ValueError('invalid limit')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('invalid offset')
    ordering = {'day': 'production_date ASC, mine ASC', 'mine': 'mine ASC, production_date ASC', 'variance': 'variance DESC, mine ASC, production_date ASC'}[sort_by]
    clauses = []
    params = []
    if mine is not None:
        clauses.append('mine = ?')
        params.append(mine)
    if start_date is not None:
        clauses.append('production_date >= ?')
        params.append(start_date)
    if end_date is not None:
        clauses.append('production_date <= ?')
        params.append(end_date)
    where = ' WHERE ' + ' AND '.join(clauses) if clauses else ''
    query = f'SELECT mine, production_date, SUM(planned_tonnes) AS planned, SUM(actual_tonnes) AS actual, SUM(actual_tonnes) - SUM(planned_tonnes) AS variance FROM production{where} GROUP BY mine, production_date ORDER BY {ordering} LIMIT ? OFFSET ?'
    rows = conn.execute(query, params + [limit, offset]).fetchall()
    result = []
    for name, day, planned, actual, variance in rows:
        p = round(planned, 2)
        a = round(actual, 2)
        v = round(variance, 2)
        result.append({'mine': name, 'date': day, 'planned_tonnes': p, 'actual_tonnes': a, 'variance_tonnes': v, 'status': 'shortfall' if v < 0 else 'surplus' if v > 0 else 'balanced'})
    return result

