import csv
import io
from datetime import datetime, timezone
KINDS = ('submitted', 'document', 'interview', 'decision', 'note')
STATUSES = {'pending', 'review', 'approved', 'denied', 'closed'}

def _time(value):
    try:
        s = value[:-1] + '+00:00' if value.endswith('Z') else value
        d = datetime.fromisoformat(s)
        if d.tzinfo is None:
            raise ValueError
        d = d.astimezone(timezone.utc)
        return (d, d.strftime('%Y-%m-%dT%H:%M:%SZ'))
    except Exception as e:
        raise ValueError('invalid timestamp') from e

def _authorize(case, requester):
    if not isinstance(requester, dict) or requester.get('tenant') != case.get('tenant'):
        raise PermissionError('not permitted')
    roles = requester.get('roles', [])
    if requester.get('id') != case.get('owner_id') and (not {'case_manager', 'admin'} & set(roles)):
        raise PermissionError('not permitted')

def _check_case(case):
    if not all((k in case for k in ('id', 'owner_id', 'tenant', 'status', 'events'))) or case['status'] not in STATUSES:
        raise ValueError('invalid case')
    for e in case['events']:
        if e.get('kind') not in KINDS or not all((k in e for k in ('timestamp', 'kind', 'detail'))):
            raise ValueError('invalid event')
        _time(e['timestamp'])

def parse_event_feed(text: str) -> list[dict]:
    out = []
    for row in csv.reader(io.StringIO(text)):
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        _, stamp = _time(row[1])
        if row[2] not in KINDS:
            raise ValueError('invalid kind')
        out.append({'case_id': row[0], 'timestamp': stamp, 'kind': row[2], 'detail': row[3]})
    return out

def case_dashboard(cases: list[dict], requester: dict, since: str | None=None) -> list[dict]:
    cutoff = _time(since)[0] if since is not None else None
    seen = set()
    result = []
    for c in cases:
        _check_case(c)
        if c['id'] in seen:
            raise ValueError('duplicate case')
        seen.add(c['id'])
        _authorize(c, requester)
        selected = []
        for e in c['events']:
            d, stamp = _time(e['timestamp'])
            if cutoff is None or d >= cutoff:
                selected.append((d, stamp, e))
        counts = {k: 0 for k in KINDS}
        for _, _, e in selected:
            counts[e['kind']] += 1
        latest = max(selected, key=lambda x: x[0]) if selected else None
        first = min((_time(e['timestamp'])[0] for e in c['events']), default=None)
        days = (latest[0].date() - first.date()).days if latest and first else 0
        result.append({'id': c['id'], 'status': c['status'], 'event_count': len(selected), 'kinds': counts, 'latest': latest[1] if latest else None, 'days_open': days})
    return sorted(result, key=lambda x: (-x['event_count'], x['id']))

def record_case_event(cases: list[dict], requester: dict, case_id: str, event: dict) -> None:
    case = next((c for c in cases if c.get('id') == case_id), None)
    if case is None:
        raise KeyError(case_id)
    _authorize(case, requester)
    _check_case(case)
    if not all((k in event for k in ('timestamp', 'kind', 'detail'))) or event['kind'] not in KINDS:
        raise ValueError('invalid event')
    d, stamp = _time(event['timestamp'])
    if case['events'] and d < _time(case['events'][-1]['timestamp'])[0]:
        raise ValueError('out of order')
    if event['kind'] == 'decision' and event['detail'] not in ('approved', 'denied'):
        raise ValueError('invalid decision')
    event = dict(event)
    event['timestamp'] = stamp
    case['events'].append(event)
    if event['kind'] == 'decision':
        case['status'] = event['detail']

