def load_requests(request_file: str) -> list[dict]:
    result = subprocess.run(['sort', '-t', '|', '-k2,2nr', '-k3,3n', '-k1,1', request_file], check=True, capture_output=True, text=True)
    records = []
    for raw in result.stdout.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 6:
            raise ValueError('invalid request line')
        request_id, priority, arrival, beds, status, district = fields
        if not request_id or not district:
            raise ValueError('invalid request line')
        try:
            priority_value = int(priority)
            arrival_value = int(arrival)
            beds_value = int(beds)
        except ValueError as exc:
            raise ValueError('invalid request line') from exc
        if beds_value <= 0:
            raise ValueError('invalid request line')
        records.append({'request_id': request_id, 'priority': priority_value, 'arrival_order': arrival_value, 'bed_count': beds_value, 'status': status, 'district': district})
    return records

def allocate_beds(requests: list[dict], capacity: int) -> list[str]:
    if capacity < 0:
        raise ValueError('capacity must not be negative')
    required = {'request_id', 'priority', 'arrival_order', 'bed_count', 'status', 'district'}
    remaining = capacity
    allocated = []
    for request in requests:
        if not required.issubset(request):
            raise ValueError('invalid request')
        if not isinstance(request['bed_count'], int) or request['bed_count'] <= 0:
            raise ValueError('invalid request')
        if request['status'] == 'ACTIVE' and request['bed_count'] <= remaining:
            allocated.append(request['request_id'])
            remaining -= request['bed_count']
    return allocated

