import csv
import hashlib
import hmac
import io
import os
from decimal import Decimal, InvalidOperation

def _credential(pin):
    salt = os.urandom(16)
    value = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + '$' + value.hex()

def register_operator(name: str, pin: str, roles: list[str]) -> dict:
    if not isinstance(name, str) or not name.strip():
        raise ValueError('invalid name')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 32 or any((c.isspace() for c in pin)):
        raise ValueError('invalid pin')
    if not isinstance(roles, list):
        raise ValueError('invalid roles')
    clean = []
    for role in roles:
        if not isinstance(role, str) or not role:
            raise ValueError('invalid role')
        if role not in clean:
            clean.append(role)
    if not clean:
        raise ValueError('invalid roles')
    return {'name': name.strip(), 'roles': clean, 'credential': _credential(pin)}

def authorize_operator(record: dict, pin: str, role: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(pin, str):
            return False
        credential = record['credential']
        salt_hex, digest_hex = credential.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected) and role in record['roles']
    except (KeyError, TypeError, ValueError):
        return False

def inventory_snapshot(manifest: str, operators: dict[str, dict], at: int) -> list[dict]:
    rows = list(csv.reader(io.StringIO(manifest)))
    if not rows or all((not row for row in rows)):
        raise ValueError('empty manifest')
    totals = {}
    for row in rows:
        if not row:
            continue
        if len(row) != 6:
            raise ValueError('bad row')
        try:
            timestamp = int(row[0].strip())
            silo, grain = (row[1].strip(), row[2].strip())
            tons = Decimal(row[3].strip())
        except (ValueError, InvalidOperation):
            raise ValueError('bad row')
        operator, pin = (row[4], row[5])
        if not silo or not grain or tons <= 0:
            raise ValueError('bad row')
        if at - 3600 <= timestamp <= at:
            record = operators.get(operator)
            if isinstance(record, dict) and authorize_operator(record, pin, 'weigh'):
                key = (silo, grain)
                totals[key] = totals.get(key, Decimal('0')) + tons
    return [{'silo': s, 'grain': g, 'tons': round(float(t), 3)} for (s, g), t in sorted(totals.items())]

