import hashlib
import hmac
import os

def hash_subscriber_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_subscriber_password(password: str, stored: str) -> bool:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    if not isinstance(stored, str) or not stored:
        return False
    parts = stored.split(':')
    if len(parts) != 2:
        return False
    try:
        salt = bytes.fromhex(parts[0])
        expected = bytes.fromhex(parts[1])
    except ValueError:
        return False
    if len(salt) != 16 or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

