    with tempfile.TemporaryDirectory() as base:
        result = write_trace_record(base, "batch.json", {"z": 1, "farmer": "Málaga", "a": [2, 3]})
        expected = os.path.abspath(os.path.join(base, "batch.json"))
        assert result == expected
        with open(expected, "r", encoding="utf-8") as handle:
            assert handle.read() == '{"a": [2, 3], "farmer": "Málaga", "z": 1}\n'


def test_creates_nested_parent_directories():
    with tempfile.TemporaryDirectory() as base:
        result = write_trace_record(base, "2025/apples/batch-17.json", {"batch": 17})
        assert result == os.path.abspath(os.path.join(base, "2025", "apples", "batch-17.json"))
        assert os.path.isfile(result)
        with open(result, encoding="utf-8") as handle:
            assert json.load(handle) == {"batch": 17}


