    with tempfile.TemporaryDirectory() as base:
        name = "records/current.json"
        first = write_trace_record(base, name, {"status": "harvested"})
        second = write_trace_record(base, name, {"status": "sold", "quantity": 8})
        assert first == second
        with open(second, encoding="utf-8") as handle:
            assert json.load(handle) == {"quantity": 8, "status": "sold"}


def test_preserves_boolean_null_and_nested_values():
    with tempfile.TemporaryDirectory() as base:
