        with open(path, encoding="utf-8") as handle:
            assert json.load(handle) == {"organic": True, "note": None, "lots": [{"id": 4}]}


def test_rejects_parent_directory_name():
    with tempfile.TemporaryDirectory() as base:
        try:
            write_trace_record(base, "../outside.json", {"x": 1})
        except ValueError:
            pass
        else:
            assert False


def test_rejects_absolute_name():
    with tempfile.TemporaryDirectory() as base:
        outside = os.path.join(os.path.dirname(base), "absolute.json")
        try:
            write_trace_record(base, outside, {"x": 1})
        except ValueError:
            pass
        else:
