import csv
import os
import zipfile
from collections import defaultdict
from pathlib import Path

def summarize_observation_archive(archive_path: str, destination_dir: str, species: str | None=None) -> list[dict]:
    os.makedirs(destination_dir, exist_ok=True)
    base = Path(destination_dir).resolve()
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            target = (base / info.filename).resolve()
            if os.path.commonpath((str(base), str(target))) != str(base):
                raise ValueError('archive member is outside destination')
            target.parent.mkdir(parents=True, exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
    totals = defaultdict(lambda: [0, 0, 0.0])
    for path in base.rglob('*.csv'):
        with open(path, newline='', encoding='utf-8') as handle:
            reader = csv.DictReader(handle)
            required = {'species', 'count', 'latitude'}
            if reader.fieldnames is None or not required.issubset(reader.fieldnames):
                raise ValueError('missing required column')
            for row in reader:
                name = row['species'].strip()
                if not name:
                    raise ValueError('blank species')
                if species is not None and name != species:
                    continue
                try:
                    count = int(row['count'].strip())
                    latitude = float(row['latitude'].strip())
                except (ValueError, AttributeError):
                    raise ValueError('invalid observation')
                if count < 0:
                    raise ValueError('invalid observation')
                item = totals[name]
                item[0] += 1
                item[1] += count
                item[2] += latitude
    result = [{'species': name, 'observations': values[0], 'total_count': values[1], 'average_latitude': round(values[2] / values[0], 2)} for name, values in totals.items()]
    return sorted(result, key=lambda item: (-item['total_count'], item['species']))

