import ast
import datetime
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float]):
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc
    allowed = {'min': min, 'max': max, 'round': round}
    binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
    compare = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, complex)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            value = variables[node.id]
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError('invalid variable')
            return value
        if isinstance(node, ast.BinOp) and type(node.op) in binary:
            try:
                return binary[type(node.op)](visit(node.left), visit(node.right))
            except (ArithmeticError, TypeError) as exc:
                raise ValueError('invalid arithmetic') from exc
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = visit(node.values[0])
            for part in node.values[1:]:
                if isinstance(node.op, ast.And):
                    if not value:
                        return value
                elif value:
                    return value
                value = visit(part)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, part in zip(node.ops, node.comparators):
                if type(op) not in compare:
                    raise ValueError('invalid comparison')
                right = visit(part)
                if not compare[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in allowed) and (not node.keywords):
            try:
                return allowed[node.func.id](*[visit(x) for x in node.args])
            except (TypeError, ValueError, ArithmeticError) as exc:
                raise ValueError('invalid call') from exc
        raise ValueError('unsupported expression')
    result = visit(tree)
    if not isinstance(result, (int, float, bool)) or isinstance(result, complex):
        raise ValueError('non-numeric result')
