import ast
import operator

def _evaluate(node, values):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in values:
            raise NameError(node.id)
        return values[node.id]
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        value = _evaluate(node.operand, values)
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.USub):
            return -value
        return not value
    if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
        left = _evaluate(node.left, values)
        right = _evaluate(node.right, values)
        return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _evaluate(node.values[0], values)
        for item in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _evaluate(item, values)
        return result
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, values)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, values)
            if not {ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE}.__contains__(type(op)):
                raise ValueError('unsupported expression')
            if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, values) for x in node.args])
    raise ValueError('unsupported expression')

def rank_preorders(records: list[dict], expression: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    tree = ast.parse(expression, mode='eval').body
    selected = []
    for record in records:
        score = _evaluate(tree, {'price': record['price'], 'quantity': record['quantity'], 'days': record['days']})
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('expression must produce a number')
        if score > 0:
            selected.append((score, record))
    selected.sort(key=lambda pair: (-pair[0], pair[1]['id']))
    start = (page - 1) * page_size
    items = [{'id': r['id'], 'title': r['title'], 'score': score, 'subtotal': round(r['price'] * r['quantity'], 2)} for score, r in selected[start:start + page_size]]
    return {'total': len(selected), 'page': page, 'page_size': page_size, 'items': items}

