from datetime import datetime, timezone

def parse_sessions(xml_text: str) -> list[dict]:
    try:
        root = etree.fromstring(xml_text.encode(), etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as e:
        raise ValueError('invalid XML') from e
    if root.tag != 'report':
        raise ValueError('root')
    out = []
    ids = set()
    for n in root:
        if n.tag != 'session' or any((k not in ('id', 'scooter', 'start', 'end') for k in n.attrib)):
            raise ValueError('structure')
        a = n.attrib
        if any((not a.get(k) for k in ('id', 'scooter', 'start', 'end'))) or a['id'] in ids:
            raise ValueError('attribute')
        try:
            st = datetime.fromisoformat(a['start'].replace('Z', '+00:00'))
            en = datetime.fromisoformat(a['end'].replace('Z', '+00:00'))
            if not a['start'].endswith('Z') or not a['end'].endswith('Z') or st.tzinfo != timezone.utc or (en.tzinfo != timezone.utc) or (en <= st):
                raise ValueError()
        except Exception as e:
            raise ValueError('time') from e
        station = energy = tags = None
        for c in n:
            if c.tag == 'station' and station is None:
                station = (c.text or '').strip()
            elif c.tag == 'energy' and energy is None and (c.attrib == {'unit': 'Wh'}):
                energy = (c.text or '').strip()
            elif c.tag == 'tags' and tags is None:
                tags = c
            else:
                raise ValueError('child')
        if not station or energy is None:
            raise ValueError('missing')
        try:
            d = Decimal(energy)
            if d < 0 or d.as_tuple().exponent < -2:
                raise ValueError()
        except Exception as e:
            raise ValueError('energy') from e
        vals = []
        if tags is not None:
            for t in tags:
                v = (t.text or '').strip()
                if t.tag != 'tag' or not v:
                    raise ValueError('tag')
                if v not in vals:
                    vals.append(v)
        ids.add(a['id'])
        out.append({'id': a['id'], 'scooter': a['scooter'], 'start': a['start'], 'end': a['end'], 'station': station, 'energy_wh': float(d), 'tags': vals})
    return out

def charging_summary(xml_text: str, window_minutes: int=60) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or (not 1 <= window_minutes <= 1440) or 1440 % window_minutes:
        raise ValueError('window')
    g = {}
    for s in parse_sessions(xml_text):
        d = datetime.fromisoformat(s['start'].replace('Z', '+00:00'))
        m = (d.hour * 60 + d.minute) // window_minutes * window_minutes
        k = (s['station'], d.date().isoformat(), m)
        q = g.setdefault(k, [0, 0, set()])
        q[0] += s['energy_wh']
        q[1] += 1
        q[2].add(s['scooter'])
    return [{'station': k[0], 'date': k[1], 'window_start': f'{k[2] // 60:02d}:{k[2] % 60:02d}', 'total_wh': round(v[0], 2), 'session_count': v[1], 'scooters': sorted(v[2])} for k, v in sorted(g.items())]

