import csv
import io
import os
import zipfile

def extract_registry_archive(base_dir: str, archive_path: str, batch_name: str) -> list[str]:
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, batch_name))
    try:
        if os.path.commonpath([base, target]) != base:
            raise ValueError('batch is outside base directory')
    except ValueError:
        raise ValueError('batch is outside base directory')
    os.makedirs(target, exist_ok=True)
    result = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            if info.is_dir():
                continue
            destination = os.path.realpath(os.path.join(target, info.filename))
            try:
                inside = os.path.commonpath([target, destination]) == target
            except ValueError:
                inside = False
            if not inside:
                raise ValueError('archive member is outside batch directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            with archive.open(info) as source, open(destination, 'wb') as output:
                output.write(source.read())
            result.append(os.path.relpath(destination, target).replace(os.sep, '/'))
    return sorted(result)

def parse_registry_csv(text: str) -> list[dict[str, object]]:
    if not text:
        raise ValueError('empty input')
    rows = list(csv.reader(io.StringIO(text, newline='')))
    expected = ['donor_id', 'blood_type', 'age', 'available', 'region']
    if not rows or rows[0] != expected:
        raise ValueError('invalid header')
    blood = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        donor, kind, age_text, available, region = row
        if not donor or donor in seen or kind not in blood or (available not in {'yes', 'no'}):
            raise ValueError('invalid record')
        try:
            age = int(age_text)
        except ValueError:
            raise ValueError('invalid age')
        if age < 18 or age > 70:
            raise ValueError('invalid age')
        seen.add(donor)
        result.append({'donor_id': donor, 'blood_type': kind, 'age': age, 'available': available == 'yes', 'region': region})
    return result

def rank_donors(records: list[dict[str, object]], recipient_blood: str, region: str) -> list[str]:
    blood = {'O-', 'O+', 'A-', 'A+', 'B-', 'B+', 'AB-', 'AB+'}
    if recipient_blood not in blood:
        raise ValueError('invalid recipient blood type')
    recipient_base = recipient_blood.rstrip('+-')
    recipient_rh = recipient_blood[-1]
    allowed = {'O': {'O', 'A', 'B', 'AB'}, 'A': {'A', 'AB'}, 'B': {'B', 'AB'}, 'AB': {'AB'}}
    chosen = []
    for record in records:
        donor = str(record['blood_type'])
        donor_base, donor_rh = (donor.rstrip('+-'), donor[-1])
        compatible = donor_base in allowed and recipient_base in allowed[donor_base] and (donor_rh == '-' or recipient_rh == '+')
        if record['available'] and compatible:
            chosen.append((0 if record['region'] == region else 1, abs(int(record['age']) - 40), str(record['donor_id'])))
    chosen.sort()
    return [item[2] for item in chosen]

