import hashlib
import hmac
import json

def verify_and_analyze(payload: str, signature: str, secret: bytes) -> dict:
    if not isinstance(payload, str) or not isinstance(signature, str) or (not isinstance(secret, bytes)):
        raise ValueError('invalid request')
    if len(signature) != 67 or not signature.startswith('v1='):
        raise ValueError('invalid signature')
    value = signature[3:]
    if any((c not in '0123456789abcdef' for c in value)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(value, expected):
        raise ValueError('invalid signature')
    try:
        data = json.loads(payload)
    except (UnicodeError, json.JSONDecodeError):
        raise ValueError('invalid json')
    if not isinstance(data, dict) or set(data) != {'conversation_id', 'messages'}:
        raise ValueError('invalid conversation')
    cid = data['conversation_id']
    messages = data['messages']
    if not isinstance(cid, str) or not cid or (not isinstance(messages, list)):
        raise ValueError('invalid conversation')
    users = {}
    minutes = {}
    previous = None
    for item in messages:
        if not isinstance(item, dict) or set(item) != {'user', 'text', 'ts'}:
            raise ValueError('invalid message')
        user, text, ts = (item['user'], item['text'], item['ts'])
        if not isinstance(user, str) or not user or (not isinstance(text, str)) or isinstance(ts, bool) or (not isinstance(ts, int)) or (ts < 0):
            raise ValueError('invalid message')
        if previous is not None and ts < previous:
            raise ValueError('timestamps out of order')
        previous = ts
        if user not in users:
            users[user] = [0, 0, 0, None]
        row = users[user]
        row[0] += 1
        row[1] += len(text)
        if row[3] is None or ts - row[3] > 300:
            row[2] += 1
        row[3] = ts
        minute = ts // 60
        minutes[minute] = minutes.get(minute, 0) + 1
    timeline = [{'minute': m, 'count': minutes[m]} for m in sorted(minutes)]
    peak = min(minutes, key=lambda m: (-minutes[m], m)) if minutes else None
    result_users = [{'user': u, 'count': r[0], 'characters': r[1], 'windows': r[2]} for u, r in users.items()]
    result_users.sort(key=lambda r: (-r['count'], r['user']))
    duration = 0 if len(messages) < 2 else messages[-1]['ts'] - messages[0]['ts']
    return {'conversation_id': cid, 'message_count': len(messages), 'duration': duration, 'peak_minute': peak, 'timeline': timeline, 'users': result_users}

