import hashlib
import hmac
import os
from datetime import date, timedelta

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _hash_secret(secret):
    salt = os.urandom(16)
    result = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000)
    return salt.hex() + '$' + result.hex()

def _check_secret(stored, secret):
    if not isinstance(stored, str) or not isinstance(secret, str):
        return False
    try:
        salt_text, digest = stored.split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = hashlib.pbkdf2_hmac('sha256', secret.encode('utf-8'), salt, 100000).hex()
    except (ValueError, TypeError, UnicodeError):
        return False
    return hmac.compare_digest(expected, digest)

def create_customer(customer_id: str, name: str, secret: str, interactions: list[dict]) -> dict:
    if not isinstance(customer_id, str) or not customer_id:
        raise ValueError('invalid customer')
    if not isinstance(name, str) or not name:
        raise ValueError('invalid customer')
    if not isinstance(secret, str) or not secret:
        raise ValueError('invalid customer')
    copied = []
    for item in interactions:
        if not isinstance(item, dict) or set(item) != {'date', 'kind', 'value'}:
            raise ValueError('invalid interaction')
        parsed = _parse_date(item['date'])
        if item['kind'] not in {'call', 'email', 'meeting'}:
            raise ValueError('invalid interaction')
        if isinstance(item['value'], bool) or not isinstance(item['value'], int) or item['value'] < 0:
            raise ValueError('invalid interaction')
        copied.append({'date': parsed.isoformat(), 'kind': item['kind'], 'value': item['value']})
    return {'customer_id': customer_id, 'name': name, 'secret_hash': _hash_secret(secret), 'interactions': copied}

def authenticate_customer(customer: dict, secret: str) -> bool:
    if not isinstance(customer, dict):
        return False
    return _check_secret(customer.get('secret_hash'), secret)

def rank_customers(customers: list[dict], as_of: str) -> list[dict]:
    end = _parse_date(as_of)
    start = end - timedelta(days=29)
    weights = {'call': 3, 'email': 1, 'meeting': 5}
    result = []
    for customer in customers:
        score = 0
        count = 0
        for item in customer['interactions']:
            when = _parse_date(item['date'])
            if start <= when <= end:
                score += weights[item['kind']] * item['value']
                count += 1
        result.append({'customer_id': customer['customer_id'], 'name': customer['name'], 'score': score, 'interaction_count': count})
    result.sort(key=lambda item: (-item['score'], item['name'].casefold(), item['customer_id']))
    return result

