import subprocess

def scan_vulnerability_report(report_path: str, minimum_severity: str='LOW', page: int=1, page_size: int=20) -> list[dict]:
    levels = {'LOW': 0, 'MEDIUM': 1, 'HIGH': 2, 'CRITICAL': 3}
    if minimum_severity not in levels:
        raise ValueError('invalid severity')
    if page <= 0 or page_size <= 0 or page_size > 100:
        raise ValueError('invalid pagination')
    result = subprocess.run(['cat', report_path], capture_output=True, text=True, check=True)
    findings = []
    for line in result.stdout.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        fields = [field.strip() for field in stripped.split(',')]
        if len(fields) != 4 or not fields[0] or (not fields[1]) or (fields[2] not in levels):
            raise ValueError('malformed finding')
        findings.append({'package': fields[0], 'version': fields[1], 'severity': fields[2], 'fixed_version': None if fields[3] == '-' else fields[3], '_order': len(findings)})
    findings = [item for item in findings if levels[item['severity']] >= levels[minimum_severity]]
    findings.sort(key=lambda item: (-levels[item['severity']], item['package'], item['version'], item['_order']))
    start = (page - 1) * page_size
    selected = findings[start:start + page_size]
    return [{key: item[key] for key in ('package', 'version', 'severity', 'fixed_version')} for item in selected]

