from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math
import xml.etree.ElementTree as ET

def track_passport_renewals(xml_text: str, page: int=1, page_size: int=10, status: str | None=None) -> dict:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    valid_statuses = {'pending', 'approved', 'rejected'}
    if status is not None and status not in valid_statuses:
        raise ValueError('invalid status')
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'renewals':
        raise ValueError('invalid root')
    expected = {'id', 'applicant', 'submitted', 'status', 'fee'}
    records = []
    seen = set()
    try:
        for node in root:
            if node.tag != 'application' or set(node.attrib) != expected or node.attrib['id'] in seen:
                raise ValueError('invalid application')
            values = node.attrib
            if values['status'] not in valid_statuses or (status is not None and values['status'] != status):
                if values['status'] not in valid_statuses:
                    raise ValueError('invalid application status')
                continue
            parsed_date = date.fromisoformat(values['submitted'])
            if parsed_date.isoformat() != values['submitted']:
                raise ValueError('invalid date')
            fee = Decimal(values['fee'])
            if not fee.is_finite() or fee < 0:
                raise ValueError('invalid fee')
            fee = fee.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
            seen.add(values['id'])
            records.append((parsed_date, values['id'], {'id': values['id'], 'applicant': values['applicant'], 'submitted': values['submitted'], 'status': values['status'], 'fee': format(fee, '.2f')}, fee))
    except (ValueError, InvalidOperation, OverflowError) as exc:
        raise ValueError('invalid application') from exc
    records.sort(key=lambda item: (-item[0].toordinal(), item[1]))
    total = len(records)
    total_fee = sum((item[3] for item in records), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    pages = math.ceil(total / page_size) if total else 0
    start = (page - 1) * page_size
    return {'total': total, 'page': page, 'page_size': page_size, 'pages': pages, 'total_fee': format(total_fee, '.2f'), 'applications': [item[2] for item in records[start:start + page_size]]}

