import os
import subprocess

def count_preorders_by_status(file_path: str, status: str) -> int:
    if not os.path.isfile(file_path):
        raise FileNotFoundError(file_path)
    if not status or '\n' in status or '\r' in status:
        raise ValueError('invalid status')
    result = subprocess.run(['grep', '-F', '-x', '--', status, file_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=False)
    if result.returncode not in (0, 1):
        raise OSError(result.stderr.strip() or 'grep failed')
    return len(result.stdout.splitlines())

