import csv
import os
import tempfile
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
_HEADER = ['sku', 'store', 'date', 'forecast_units']

def _valid_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def forecast_and_export(records: list[dict], horizon: int, destination: str) -> list[dict]:
    if isinstance(horizon, bool) or not isinstance(horizon, int) or horizon < 0:
        raise ValueError('invalid horizon')
    totals = defaultdict(lambda: defaultdict(int))
    for record in records:
        if not isinstance(record, dict) or set(record) != {'date', 'sku', 'store', 'units'}:
            raise ValueError('invalid record')
        day = _valid_date(record['date'])
        if not isinstance(record['sku'], str) or not record['sku']:
            raise ValueError('invalid sku')
        if not isinstance(record['store'], str) or not record['store']:
            raise ValueError('invalid store')
        if isinstance(record['units'], bool) or not isinstance(record['units'], int) or record['units'] < 0:
            raise ValueError('invalid units')
        totals[record['sku'], record['store']][day] += record['units']
    rows = []
    for sku, store in sorted(totals):
        days = totals[sku, store]
        ordered = sorted(days)
        average = Decimal(sum((days[x] for x in ordered[-3:]))) / min(3, len(ordered))
        value = int(average.quantize(Decimal('1'), rounding=ROUND_HALF_UP))
        for offset in range(1, horizon + 1):
            rows.append({'sku': sku, 'store': store, 'date': (ordered[-1] + timedelta(days=offset)).isoformat(), 'forecast_units': value})
    fd, temporary = tempfile.mkstemp(prefix='.forecast-', dir=os.path.dirname(os.path.abspath(destination)))
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=_HEADER)
            writer.writeheader()
            writer.writerows(rows)
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return rows

def read_forecast_export(source: str) -> list[dict]:
    with open(source, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.reader(handle)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('empty file')
        if header != _HEADER:
            raise ValueError('invalid header')
        result = []
        for fields in reader:
            if len(fields) != 4 or not fields[0] or (not fields[1]):
                raise ValueError('invalid row')
            _valid_date(fields[2])
            if not fields[3].isdigit():
                raise ValueError('invalid units')
            result.append({'sku': fields[0], 'store': fields[1], 'date': fields[2], 'forecast_units': int(fields[3])})
        return result

