import csv
import datetime
import os
import tempfile

def parse_reports(text: str) -> list[dict]:
    fields = ['id', 'district', 'latitude', 'longitude', 'severity', 'status', 'date']
    try:
        rows = list(csv.reader(text.splitlines()))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    if not rows or rows[0] != fields:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if len(row) != len(fields) or any((x == '' for x in row)):
            raise ValueError('invalid row')
        try:
            ident, district = (row[0], row[1])
            lat, lon = (float(row[2]), float(row[3]))
            severity = int(row[4])
            status = row[5]
            parsed_date = datetime.datetime.strptime(row[6], '%Y-%m-%d').date()
            if parsed_date.isoformat() != row[6]:
                raise ValueError
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid value') from exc
        if ident in seen or not -90 <= lat <= 90 or (not -180 <= lon <= 180) or (not 1 <= severity <= 5) or (status not in ('open', 'closed')):
            raise ValueError('invalid value')
        seen.add(ident)
        result.append({'id': ident, 'district': district, 'latitude': lat, 'longitude': lon, 'severity': severity, 'status': status, 'date': parsed_date})
    return result

def aggregate_reports(reports: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('window_days must be positive')
    if not reports:
        return []
    latest = max((item['date'] for item in reports))
    first = latest - datetime.timedelta(days=window_days - 1)
    groups = {}
    for item in reports:
        if first <= item['date'] <= latest:
            group = groups.setdefault(item['district'], [])
            group.append(item)
    result = []
    for district, items in groups.items():
        result.append({'district': district, 'total': len(items), 'open': sum((x['status'] == 'open' for x in items)), 'avg_severity': round(sum((x['severity'] for x in items)) / len(items), 2), 'latest_date': max((x['date'] for x in items))})
    return sorted(result, key=lambda x: (-x['open'], -x['avg_severity'], x['district']))

def export_summary(reports: list[dict], path: str, window_days: int=7) -> int:
    summaries = aggregate_reports(reports, window_days)
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(dir=directory, prefix='.summary-')
    try:
        with os.fdopen(fd, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle)
            writer.writerow(['district', 'total', 'open', 'avg_severity', 'latest_date'])
            for item in summaries:
                writer.writerow([item['district'], item['total'], item['open'], f"{item['avg_severity']:.2f}", item['latest_date'].isoformat()])
        os.replace(temporary, path)
    except BaseException:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise
    return len(summaries)

