        if not isinstance(incident, dict) or set(incident) != fields:
            raise ValueError('invalid incident')
        if not isinstance(incident['id'], str) or not incident['id']:
            raise ValueError('invalid id')
        if not isinstance(incident['zone'], str) or not incident['zone']:
            raise ValueError('invalid zone')
        if isinstance(incident['severity'], bool) or not isinstance(incident['severity'], int) or (not 1 <= incident['severity'] <= 5):
            raise ValueError('invalid severity')
        eta = incident['eta_minutes']
        if isinstance(eta, bool) or not isinstance(eta, (int, float)) or (not math.isfinite(eta)) or (eta < 0):
            raise ValueError('invalid eta')
        if incident['status'] not in {'open', 'closed'}:
            raise ValueError('invalid status')
        if incident['status'] == 'open':
            valid.append(incident)
    valid.sort(key=lambda x: (-x['severity'], x['eta_minutes'], x['id']))
    start = (page - 1) * page_size
    selected = valid[start:start + page_size]
    average = round(sum((x['eta_minutes'] for x in valid)) / len(valid), 2) if valid else 0.0
    report = {'count': len(valid), 'average_eta': average, 'incidents': selected}
    base = Path(base_dir).resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base)
    except ValueError:
        raise ValueError('invalid report location')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    return str(target)

