import base64
import datetime
import hashlib
import hmac
import os
import re

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str) or not secret:
        raise ValueError('empty secret')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, rounds)
    return f'pbkdf2${rounds}${base64.urlsafe_b64encode(salt).decode()}${digest.hex()}'

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not secret or (not isinstance(stored, str)):
        return False
    try:
        kind, rounds, salt, expected = stored.split('$')
        if kind != 'pbkdf2':
            return False
        rounds = int(rounds)
        salt = base64.urlsafe_b64decode(salt.encode())
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, rounds).hex()
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError, UnicodeError):
        return False

def _date(value):
    try:
        parsed = datetime.date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def _cents(value):
    if not isinstance(value, str) or not re.fullmatch('(?:0|[1-9]\\d*)(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    whole, _, fraction = value.partition('.')
    return int(whole) * 100 + int((fraction + '00')[:2])

def parse_payments(text: str) -> list[tuple[str, int]]:
    if not isinstance(text, str):
        raise ValueError('invalid payments')
    totals = {}
    for line in text.splitlines():
        if not line.strip():
            continue
        parts = line.split(' ')
        if len(parts) != 2 or not parts[0] or (not parts[1]):
            raise ValueError('invalid payment line')
        day = _date(parts[0])
        amount = _cents(parts[1])
        totals[day.isoformat()] = totals.get(day.isoformat(), 0) + amount
    return sorted(totals.items())

def register_lease(tenant_id: str, password: str, start: str, end: str, monthly_rent: str, payments: str) -> dict:
    if not isinstance(tenant_id, str) or not tenant_id:
        raise ValueError('invalid tenant')
    first, last = (_date(start), _date(end))
    if first.day != 1 or last.day != 1 or first > last:
        raise ValueError('invalid lease range')
    rent = _cents(monthly_rent)
    if rent <= 0:
        raise ValueError('invalid rent')
    return {'tenant_id': tenant_id, 'password': hash_secret(password), 'start': start, 'end': end, 'rent_cents': rent, 'payments': parse_payments(payments)}

def lease_summary(lease: dict, as_of: str) -> dict:
    if not isinstance(lease, dict):
        raise ValueError('invalid lease')
    try:
        tenant, start, end, rent, payments = (lease[k] for k in ('tenant_id', 'start', 'end', 'rent_cents', 'payments'))
    except (KeyError, TypeError):
        raise ValueError('invalid lease')
    today, first, last = (_date(as_of), _date(start), _date(end))
    if first.day != 1 or last.day != 1 or first > last or (not isinstance(rent, int)) or (rent <= 0):
        raise ValueError('invalid lease')
    charges = []
    cursor = first
