import os

def create_worker_record(worker_id: str, pin: str) -> dict:
    if not isinstance(worker_id, str) or not worker_id.strip():
        raise ValueError('invalid worker id')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 12 or (not all(('0' <= c <= '9' for c in pin))):
        raise ValueError('invalid pin')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'worker_id': worker_id, 'pin_hash': salt.hex() + '$' + digest.hex()}

def verify_worker_pin(record: dict, pin: str) -> bool:
    if not isinstance(record, dict) or not isinstance(record.get('pin_hash'), str) or (not isinstance(pin, str)):
        return False
    try:
        salt_text, digest_text = record['pin_hash'].split('$', 1)
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

