_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def create_invite(patient_id: str, readings: list[dict], used_codes: set[str]) -> dict:
    if not isinstance(patient_id, str) or not patient_id:
        raise ValueError('invalid patient_id')
    if not isinstance(readings, list):
        raise ValueError('invalid readings')
    grouped = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        day = reading.get('date')
        heart_rate = reading.get('heart_rate')
        if not isinstance(day, str) or not isinstance(heart_rate, (int, float)) or isinstance(heart_rate, bool):
            raise ValueError('invalid reading')
        try:
            date.fromisoformat(day)
        except ValueError:
            raise ValueError('invalid reading')
        if not 30 <= heart_rate <= 220:
            raise ValueError('invalid reading')
        grouped.setdefault(day, []).append(heart_rate)
    while True:
        code = ''.join((secrets.choice(_CODE_ALPHABET) for _ in range(12)))
        if code not in used_codes:
            break
    days = []
    for day in sorted(grouped):
        values = grouped[day]
        days.append({'date': day, 'average_heart_rate': round(sum(values) / len(values), 1), 'maximum_heart_rate': max(values)})
