import hashlib
import hmac
import json
import pytest

from solution import generate_asset_report


def expected(records, key, offset=0, limit=50):
    active = [r for r in records if r["status"] == "active"]
    groups = {}
    for record in active:
        category = record["category"]
        item = groups.setdefault(category, {"category": category, "count": 0, "value": 0.0})
        item["count"] += 1
        item["value"] += record["value"]
    by_category = []
    for category in sorted(groups):
        item = groups[category]
        by_category.append({"category": category, "count": item["count"], "value": round(item["value"], 2)})
    ordered = sorted(active, key=lambda r: (-r["value"], r["asset_id"]))
    report = {
        "assets": [
            {"asset_id": r["asset_id"], "category": r["category"], "value": r["value"]}
            for r in ordered[offset:offset + limit]
        ],
        "by_category": by_category,
        "total_assets": len(active),
        "total_value": round(sum(r["value"] for r in active), 2),
    }
    encoded = json.dumps(report, sort_keys=True, separators=(",", ":"))
    signature = hmac.new(key.encode(), encoded.encode(), hashlib.sha256).hexdigest()
    return {"report": report, "signature": signature}


def test_empty_input_has_empty_aggregates():
    result = json.loads(generate_asset_report([], {"report_key": "alpha"}))
    assert result == expected([], "alpha")


def test_filters_groups_rounds_and_sorts_records():
    records = [
        {"asset_id": "b", "category": "z", "status": "active", "value": 10.125},
        {"asset_id": "a", "category": "z", "status": "active", "value": 10.125},
        {"asset_id": "c", "category": "a", "status": "retired", "value": 99},
        {"asset_id": "d", "category": "a", "status": "active", "value": 2.2},
    ]
    assert json.loads(generate_asset_report(records, {"report_key": "alpha"})) == expected(records, "alpha")


def test_ties_use_asset_id_as_second_sort_key():
    records = [
        {"asset_id": "z", "category": "x", "status": "active", "value": 4},
        {"asset_id": "a", "category": "x", "status": "active", "value": 4},
        {"asset_id": "m", "category": "x", "status": "active", "value": 8},
    ]
    result = json.loads(generate_asset_report(records, {"report_key": "k"}))
    assert [x["asset_id"] for x in result["report"]["assets"]] == ["m", "a", "z"]


def test_pagination_applies_after_sorting():
    records = [
        {"asset_id": str(i), "category": "c", "status": "active", "value": i}
        for i in range(6)
    ]
    result = json.loads(generate_asset_report(records, {"report_key": "k"}, 2, 3))
    assert [x["asset_id"] for x in result["report"]["assets"]] == ["3", "2", "1"]


