    assert set(result) == {"report", "signature"}


def test_invalid_pagination_raises_value_error():
    with pytest.raises(ValueError):
        generate_asset_report([], {"report_key": "k"}, -1, 2)
    with pytest.raises(ValueError):
        generate_asset_report([], {"report_key": "k"}, 0, 0)


