    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    groups = {}
    for reading in readings:
        if not isinstance(reading, dict):
            raise ValueError('invalid reading')
        sensor = reading.get('sensor')
        value = reading.get('value')
        timestamp = reading.get('timestamp')
        if not isinstance(sensor, str) or not sensor or isinstance(value, bool) or (not isinstance(value, (int, float))) or (not math.isfinite(value)) or isinstance(timestamp, bool) or (not isinstance(timestamp, int)) or (timestamp < 0):
            raise ValueError('invalid reading')
        groups.setdefault(sensor, []).append((value, timestamp))
    result = []
