        result.append({'sensor': sensor, 'average': round(sum((x[0] for x in items)) / len(items), 2), 'latest_timestamp': max((x[1] for x in items)), 'count': len(items)})
    result.sort(key=lambda item: (-item['average'], item['sensor']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

