import hashlib
import hmac

def verify_specimen_webhook(payload: bytes, signature: str, shared_key: bytes) -> bool:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(shared_key, bytes)):
        return False
    if not signature.startswith('sha256='):
        return False
    digest = signature[7:]
    if len(digest) != 64 or any((character not in '0123456789abcdef' for character in digest)):
        return False
    expected = hmac.new(shared_key, payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, digest)

