import ast
import operator

def _evaluate(node, names):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float, str, bool)) or node.value is None:
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id not in names:
            raise ValueError()
        return names[node.id]
    if isinstance(node, ast.BinOp):
        left = _evaluate(node.left, names)
        right = _evaluate(node.right, names)
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
        for kind, fn in ops.items():
            if isinstance(node.op, kind):
                return fn(left, right)
        raise ValueError()
    if isinstance(node, ast.UnaryOp):
        value = _evaluate(node.operand, names)
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return +value
        if isinstance(node.op, ast.Not):
            return not value
        raise ValueError()
    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = None
            for item in node.values:
                result = _evaluate(item, names)
                if not result:
                    return result
            return result
        if isinstance(node.op, ast.Or):
            result = None
            for item in node.values:
                result = _evaluate(item, names)
                if result:
                    return result
            return result
        raise ValueError()
    if isinstance(node, ast.Compare):
        left = _evaluate(node.left, names)
        for op, part in zip(node.ops, node.comparators):
            right = _evaluate(part, names)
            fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
            if fn is None:
                raise ValueError()
            if not fn(left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_evaluate(x, names) for x in node.args])
