        raise ValueError('invalid offset')
    clauses = ['status = ?', 'amount >= ?']
    parameters: list[object] = ['approved', min_amount]
    if region:
        clauses.append('region = ?')
        parameters.append(region)
    order = {'total_amount': 'total_amount DESC, region ASC', 'application_count': 'application_count DESC, region ASC', 'region': 'region ASC'}[sort_by]
    query = f"\n        SELECT region, COUNT(*) AS application_count,\n               ROUND(SUM(amount), 2) AS total_amount,\n               ROUND(AVG(amount), 2) AS average_amount\n        FROM applications\n        WHERE {' AND '.join(clauses)}\n        GROUP BY region\n        ORDER BY {order}\n        LIMIT ? OFFSET ?\n    "
    parameters.extend([limit, offset])
    rows = connection.execute(query, parameters).fetchall()
    return [{'region': row[0], 'application_count': row[1], 'total_amount': float(row[2]), 'average_amount': float(row[3])} for row in rows]

