import numbers
from pathlib import Path

def write_quality_report(records: list[dict], base_dir: str, name: str) -> str:
    if not isinstance(records, list):
        raise TypeError('records must be a list')
    if not isinstance(name, str) or not name or Path(name).is_absolute():
        raise ValueError('name must be a non-empty relative path')
    groups = {}
    required = {'batch_id', 'chemical', 'yield_pct', 'moisture_pct', 'status'}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        if not required.issubset(record):
            raise ValueError('missing record field')
        batch_id = record['batch_id']
        chemical = record['chemical']
        if not isinstance(batch_id, str) or not batch_id or (not isinstance(chemical, str)) or (not chemical):
            raise ValueError('text fields must be non-empty strings')
        values = (record['yield_pct'], record['moisture_pct'])
        if any((isinstance(value, bool) or not isinstance(value, numbers.Real) or (not math.isfinite(value)) for value in values)):
            raise ValueError('numeric fields must be finite real numbers')
        if record['status'] not in ('pass', 'fail'):
            raise ValueError('invalid status')
        group = groups.setdefault(chemical, [0, 0.0, 0.0, 0])
        group[0] += 1
        group[1] += values[0]
        group[2] += values[1]
        group[3] += record['status'] == 'pass'
    base = Path(base_dir).resolve()
    output = (base / name).resolve()
    try:
        output.relative_to(base)
    except ValueError:
        raise ValueError('output path is outside base directory')
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['chemical', 'batch_count', 'average_yield_pct', 'average_moisture_pct', 'pass_count', 'pass_rate_pct'])
        for chemical in sorted(groups):
            count, total_yield, total_moisture, passed = groups[chemical]
            writer.writerow([chemical, count, f'{total_yield / count:.2f}', f'{total_moisture / count:.2f}', passed, f'{passed * 100 / count:.2f}'])
    return str(output)

