        group[0] += 1
        group[1] += values[0]
        group[2] += values[1]
        group[3] += record['status'] == 'pass'
    base = Path(base_dir).resolve()
    output = base / name
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open('w', encoding='utf-8', newline='') as handle:
        writer = csv.writer(handle, lineterminator='\n')
        writer.writerow(['chemical', 'batch_count', 'average_yield_pct', 'average_moisture_pct', 'pass_count', 'pass_rate_pct'])
