def build_dispatch_plan(requester: dict, batteries: list[dict], requested_kw: float, duration_minutes: int) -> list[dict]:
    required = {'id', 'owner_id', 'tenant_id', 'capacity_kwh', 'soc_percent', 'max_discharge_kw', 'priority'}
    if not isinstance(requester, dict) or not {'id', 'tenant_id', 'roles'}.issubset(requester) or (not isinstance(requester['roles'], list)):
        raise ValueError('invalid requester')
    if not isinstance(batteries, list) or isinstance(requested_kw, bool) or (not isinstance(requested_kw, (int, float))) or (not math.isfinite(requested_kw)) or (requested_kw < 0) or isinstance(duration_minutes, bool) or (not isinstance(duration_minutes, int)) or (duration_minutes <= 0):
        raise ValueError('invalid request')
    seen = set()
    for b in batteries:
        if not isinstance(b, dict) or not required.issubset(b) or (not isinstance(b['id'], str)) or (b['id'] in seen):
            raise ValueError('invalid battery')
        seen.add(b['id'])
        for key in ('capacity_kwh', 'soc_percent', 'max_discharge_kw', 'priority'):
            if isinstance(b[key], bool) or not isinstance(b[key], (int, float)) or (not math.isfinite(b[key])):
                raise ValueError('invalid battery')
        if b['capacity_kwh'] < 0 or b['max_discharge_kw'] < 0 or (not 0 <= b['soc_percent'] <= 100):
            raise ValueError('invalid battery')
    ids = requester.get('battery_ids')
    if ids is not None and (not isinstance(ids, list) or any((not isinstance(x, str) for x in ids))):
        raise ValueError('invalid selection')
    selected = set(ids) if ids is not None else {b['id'] for b in batteries}
    allowed = []
    for b in batteries:
        if b['id'] not in selected:
            continue
        same_tenant = b['tenant_id'] == requester['tenant_id']
        if same_tenant and (b['owner_id'] == requester['id'] or 'dispatcher' in requester['roles']):
            allowed.append(b)
    hours = duration_minutes / 60
    remaining = float(requested_kw)
    result = []
    for b in sorted(allowed, key=lambda x: (-x['priority'], x['id'])):
        available = min(b['max_discharge_kw'], b['capacity_kwh'] * b['soc_percent'] / 100 / hours)
        power = min(available, remaining)
        if power > 0:
            result.append({'battery_id': b['id'], 'power_kw': round(power, 2), 'energy_kwh': round(power * hours, 2)})
            remaining -= power
    return result

