def prepare_translation_upload(project: str, locale: str, entries: list[dict], page: int=1, page_size: int=50) -> dict:
    if not isinstance(project, str) or not project:
        raise ValueError('project must be a non-empty string')
    if not isinstance(locale, str) or re.fullmatch('[a-z]{2}(?:-[A-Z]{2})?', locale) is None:
        raise ValueError('invalid locale')
    if not isinstance(entries, list):
        raise TypeError('entries must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page_size')
    statuses = ('draft', 'translated', 'reviewed')
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError('invalid entry')
        if any((not isinstance(entry.get(field), str) or not entry[field] for field in ('id', 'key', 'text'))):
            raise ValueError('invalid entry')
        if entry.get('status') not in statuses:
            raise ValueError('invalid entry')
        if not isinstance(entry.get('updated_at'), int) or isinstance(entry['updated_at'], bool) or entry['updated_at'] < 0:
            raise ValueError('invalid entry')
    token = os.environ.get('TRANSLATION_API_TOKEN')
    if not token:
        raise RuntimeError('TRANSLATION_API_TOKEN is not set')
    ordered = sorted(entries, key=lambda item: (-item['updated_at'], item['id']))
    start = (page - 1) * page_size
    records = ordered[start:start + page_size]
    counts = {status: 0 for status in statuses}
    for entry in entries:
        counts[entry['status']] += 1
    total = len(entries)
    return {'url': f'https://translations.example.test/projects/{project}/uploads', 'headers': {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}, 'params': {'locale': locale, 'page': page, 'page_size': page_size}, 'records': records, 'summary': {'total_entries': total, 'total_pages': (total + page_size - 1) // page_size if total else 0, 'total_words': sum((len(entry['text'].split()) for entry in entries)), 'status_counts': counts}}

