        normalized.append(float(value))
    secret = None
    if config is not None:
        secret = config.get('OCEAN_API_TOKEN')
    if secret is None:
        secret = os.environ.get('OCEAN_API_TOKEN')
    if not secret:
        raise ValueError('OCEAN_API_TOKEN is required')
    body = {'count': len(normalized), 'readings': normalized, 'sensor_id': normalized_id}
    message = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    auth = hmac.new(secret.encode(), message, hashlib.sha256).hexdigest()
    return {**body, 'auth': auth}

