import hashlib
import hmac

def verify_leaderboard_submission(payload: str, secret: bytes) -> tuple[str, int]:
    if not isinstance(payload, str):
        raise TypeError('payload must be a string')
    if not isinstance(secret, bytes):
        raise TypeError('secret must be bytes')
    if not secret:
        raise ValueError('secret must not be empty')
    parts = payload.split('|')
    if len(parts) != 3:
        raise ValueError('invalid payload')
    player, score_text, signature = parts
    if not 1 <= len(player) <= 20 or not player.isascii() or (not all((c.isalnum() or c == '_' for c in player))):
        raise ValueError('invalid player')
    if not score_text.isdecimal() or (len(score_text) > 1 and score_text[0] == '0'):
        raise ValueError('invalid score')
    score = int(score_text)
    if score > 1000000000:
        raise ValueError('invalid score')
    if len(signature) != 64 or any((c not in '0123456789abcdef' for c in signature)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, f'{player}|{score_text}'.encode(), hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    return (player, score)

