    seen = set()
    for row in rows[1:]:
        if not row or all((not x.strip() for x in row)):
            continue
        if len(row) != 4:
            raise ValueError('invalid row')
        owner, parcel, area_text, status = (x.strip() for x in row)
        if not owner or not parcel or parcel in seen or (status not in {'active', 'leased', 'abandoned'}):
            raise ValueError('invalid field')
        try:
            area = float(area_text)
        except ValueError as exc:
            raise ValueError('invalid area') from exc
        if not math.isfinite(area) or area <= 0:
            raise ValueError('invalid area')
        seen.add(parcel)
        result.append((owner, parcel, area, status))
    return result

def summarize_land(deeds: list[tuple[str, str, float, str]]) -> list[dict[str, object]]:
    groups = {}
    for owner, parcel, area, status in deeds:
        item = groups.setdefault(owner, {'owner': owner, 'parcels': 0, 'total_area': 0.0, 'active_area': 0.0, 'active_parcels': 0})
        item['parcels'] += 1
        item['total_area'] += area
        if status == 'active':
            item['active_area'] += area
            item['active_parcels'] += 1
    result = []
    for item in groups.values():
        item = dict(item)
        item['total_area'] = round(item['total_area'], 2)
        item['active_area'] = round(item['active_area'], 2)
        result.append(item)
    return sorted(result, key=lambda x: (-x['total_area'], x['owner']))

def export_land_report(deeds: list[tuple[str, str, float, str]], destination: str) -> list[dict[str, object]]:
    summary = summarize_land(deeds)
    parent = os.path.dirname(os.path.abspath(destination))
