import os

def parse_fiber_record(line: str) -> dict:
    if not isinstance(line, str) or not line:
        raise ValueError('invalid line')
    fields = []
    current = []
    escaped = False
    for char in line:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 5:
        raise ValueError('wrong field count')
    site, rack, port_text, status, loss_text = fields
    if not site or not rack or any((c.isspace() for c in rack)):
        raise ValueError('invalid location')
    if status not in {'active', 'down', 'maintenance'}:
        raise ValueError('invalid status')
    try:
        port = int(port_text)
        loss = float(loss_text)
    except (TypeError, ValueError):
        raise ValueError('invalid number')
    if port < 1 or port > 144 or loss != loss or (loss < 0) or (loss > 100):
        raise ValueError('number out of range')
    return {'site': site, 'rack': rack, 'port': port, 'status': status, 'loss': loss}

def register_technician(store: dict, username: str, password: str) -> None:
    if not isinstance(username, str) or not username or any((c.isspace() for c in username)):
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 8:
        raise ValueError('invalid password')
    if username in store:
        raise ValueError('duplicate username')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    store[username] = (salt, digest)

def authenticate_technician(store: dict, username: str, password: str) -> bool:
    if not isinstance(username, str) or not isinstance(password, str):
        return False
    entry = store.get(username)
    if entry is None:
        return False
    salt, expected = entry
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def summarize_active_loss(records: list[dict]) -> list[dict]:
    grouped = {}
    required = {'site', 'rack', 'port', 'status', 'loss'}
    for record in records:
        if not required.issubset(record):
            raise ValueError('incomplete record')
        if record['status'] not in {'active', 'down', 'maintenance'}:
            raise ValueError('invalid status')
        if not isinstance(record['port'], int) or not 1 <= record['port'] <= 144:
            raise ValueError('invalid port')
        loss = record['loss']
        if not isinstance(loss, (int, float)) or loss != loss or (not 0 <= loss <= 100):
            raise ValueError('invalid loss')
        if record['status'] == 'active':
            item = grouped.setdefault(record['site'], [0, 0.0])
            item[0] += 1
            item[1] += float(loss)
    result = [{'site': site, 'count': count, 'total_loss': round(total, 2), 'average_loss': round(total / count, 2)} for site, (count, total) in grouped.items()]
    return sorted(result, key=lambda x: (-x['total_loss'], x['site']))

