def build_run_report(requester: dict, run: dict, reads: list[dict], page: int=1, page_size: int=20) -> dict:
    if type(page) is not int or page <= 0 or type(page_size) is not int or (page_size <= 0):
        raise ValueError('invalid pagination')
    allowed = requester.get('tenant_id') == run.get('tenant_id') and (requester.get('id') == run.get('owner_id') or 'pipeline_manager' in requester.get('roles', []))
    if not allowed:
        raise PermissionError('not permitted')
    groups = {}
    for item in reads:
        if not isinstance(item, dict) or not all((k in item for k in ('run_id', 'sample_id', 'bases', 'q30', 'passed'))):
            raise ValueError('invalid read')
        if not isinstance(item['run_id'], str) or not isinstance(item['sample_id'], str):
            raise ValueError('invalid read')
        if type(item['bases']) is not int or item['bases'] < 0:
            raise ValueError('invalid read')
        if isinstance(item['q30'], bool) or not isinstance(item['q30'], (int, float)) or (not 0 <= item['q30'] <= 100):
            raise ValueError('invalid read')
        if type(item['passed']) is not bool:
            raise ValueError('invalid read')
        if item['run_id'] == run['id'] and item['passed']:
            g = groups.setdefault(item['sample_id'], [0, 0, 0.0])
            g[0] += 1
            g[1] += item['bases']
            g[2] += item['q30']
    samples = [{'sample_id': k, 'read_count': v[0], 'bases': v[1], 'mean_q30': round(v[2] / v[0], 2)} for k, v in groups.items()]
