import hashlib
import hmac
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if password == '':
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        return False
    try:
        salt_hex, digest_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
    except (ValueError, TypeError):
        return False
    if not salt or len(expected) != 32:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def extract_clauses(document: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if not isinstance(document, str):
        raise TypeError('document must be a string')
    if page < 1 or page_size < 1:
        raise ValueError('pagination values must be positive')
    clauses = []
    for line in document.splitlines():
        if not line.startswith('CLAUSE'):
            continue
        parts = line.split('::', 2)
