import hashlib
import hmac
import json

def verify_return_webhook(payload: bytes, signature: str, signing_key: str) -> dict | None:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(signing_key, str)):
        raise TypeError('invalid argument type')
    if not signing_key:
        raise ValueError('empty signing key')
    if not signature.startswith('sha256=') or len(signature) != 71:
        raise ValueError('invalid signature')
    digest = signature[7:]
    try:
        int(digest, 16)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(signing_key.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(digest, expected):
        return None
    try:
        value = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(value, dict) or set(value) != {'event_id', 'equipment_id', 'status'}:
        raise ValueError('invalid fields')
    if not all((isinstance(value[name], str) for name in value)):
        raise ValueError('invalid field type')
    if value['status'] not in {'returned', 'inspection_required'}:
        raise ValueError('invalid status')
    return value

