from solution import rank_elevators

def test_empty_input():
    assert rank_elevators([], 'load > 10', 'load * 2', 3) == []

def test_boundary_comparisons_and_boolean_precedence():
    readings = [{'id': 'e1', 'floor': 0, 'load': 10, 'temperature': 30, 'trips': 0, 'fault': False}, {'id': 'e2', 'floor': 3, 'load': 11, 'temperature': 20, 'trips': 2, 'fault': True}, {'id': 'e3', 'floor': 4, 'load': 12, 'temperature': 20, 'trips': 3, 'fault': False}]
    result = rank_elevators(readings, 'floor >= 3 and (not fault or load == 11)', 'min(load, 12) - max(trips, 1)', 10)
    assert [x['id'] for x in result] == ['e2', 'e3']
    assert [x['score'] for x in result] == [9, 9]

def test_limit_larger_than_matches_and_input_is_not_mutated():
    readings = [{'id': 'x', 'floor': 1, 'load': 20, 'temperature': 22, 'trips': 1, 'fault': False}]
    before = [dict(readings[0])]
    result = rank_elevators(readings, 'load > 0', 'load / 2', 9)
    assert result == [{'id': 'x', 'floor': 1, 'load': 20, 'temperature': 22, 'trips': 1, 'fault': False, 'score': 10.0}]
    assert readings == before
    assert result[0] is not readings[0]

def test_invalid_limit_and_unknown_name():
    reading = {'id': 'x', 'floor': 1, 'load': 20, 'temperature': 22, 'trips': 1, 'fault': False}
