def generate_invite_code(length: int=10) -> str:
    if isinstance(length, bool) or not isinstance(length, int) or length < 6 or (length > 32):
        raise ValueError('length must be between 6 and 32')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    return ''.join((secrets.choice(alphabet) for _ in range(length)))

def summarize_season_tickets(records: list[dict], page: int=1, page_size: int=20) -> dict:
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        if not all((key in record for key in ('section', 'row', 'seat', 'price', 'status'))):
            raise ValueError('invalid record')
        section = record['section']
        row = record['row']
        seat = record['seat']
        price = record['price']
        status = record['status']
        if not isinstance(section, str) or not section:
            raise ValueError('invalid section')
        if isinstance(row, bool) or not isinstance(row, int) or row < 1:
            raise ValueError('invalid row')
        if isinstance(seat, bool) or not isinstance(seat, int) or seat < 1:
            raise ValueError('invalid seat')
        if isinstance(price, bool) or not isinstance(price, (int, float)) or (not math.isfinite(price)) or (price < 0):
            raise ValueError('invalid price')
        if status not in ('paid', 'refunded', 'held'):
            raise ValueError('invalid status')
        if status == 'paid':
            item = groups.setdefault(section, [0, 0.0])
            item[0] += 1
            item[1] += price
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], item[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    return {'page': page, 'page_size': page_size, 'total_sections': len(ordered), 'sections': [{'section': name, 'tickets': values[0], 'revenue': round(values[1], 2)} for name, values in selected]}

