import hmac
import os

def _credential(pin):
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def create_agent(agent_id: str, pin: str) -> dict:
    if not isinstance(agent_id, str) or not agent_id.strip():
        raise ValueError('invalid id')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 32 or (not pin.isdigit()):
        raise ValueError('invalid pin')
    return {'id': agent_id, 'credential': _credential(pin)}

def authenticate(agent: dict, pin: str) -> bool:
    try:
        value = agent['credential']
        salt_text, digest_text = value.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError, AttributeError):
        return False

class CallQueue:

    def __init__(self, agents: list[dict]):
        self.agents = {}
        for agent in agents:
            ident = agent.get('id') if isinstance(agent, dict) else None
            if not isinstance(ident, str) or ident in self.agents:
                raise ValueError('duplicate agent')
            self.agents[ident] = agent
        self.calls = []

    def add_call(self, call_id: str, customer: str, priority: int, created_at: int, vip: bool=False) -> None:
        if not isinstance(call_id, str) or not call_id.strip() or (not isinstance(customer, str)) or (not customer.strip()):
            raise ValueError('invalid text')
        if not isinstance(priority, int) or isinstance(priority, bool) or (not 1 <= priority <= 5):
            raise ValueError('invalid priority')
        if not isinstance(created_at, int) or isinstance(created_at, bool) or created_at < 0 or (not isinstance(vip, bool)):
            raise ValueError('invalid call')
        if any((x['call_id'] == call_id for x in self.calls)):
            raise ValueError('duplicate call')
        self.calls.append({'call_id': call_id, 'customer': customer, 'priority': priority, 'created_at': created_at, 'vip': vip, 'status': 'waiting', 'assigned_to': None})

    def _auth(self, agent_id, pin):
        if agent_id not in self.agents or not authenticate(self.agents[agent_id], pin):
            raise PermissionError('authentication failed')

    def _free(self, agent_id):
        return not any((x['assigned_to'] == agent_id and x['status'] == 'assigned' for x in self.calls))

    def next_call(self, agent_id: str, pin: str, now: int) -> dict | None:
        self._auth(agent_id, pin)
        if not isinstance(now, int) or isinstance(now, bool) or now < 0:
            raise ValueError('invalid time')
        if not self._free(agent_id):
            return None
        waiting = [x for x in self.calls if x['status'] == 'waiting']
        if not waiting:
            return None

        def key(x):
            wait = max(0, (now - x['created_at']) // 60)
            return (not x['vip'], -x['priority'], -wait, x['created_at'], x['call_id'])
        chosen = min(waiting, key=key)
        chosen['status'] = 'assigned'
        chosen['assigned_to'] = agent_id
        return dict(chosen)

    def complete_call(self, agent_id: str, pin: str, call_id: str) -> bool:
        self._auth(agent_id, pin)
        for call in self.calls:
            if call['call_id'] == call_id and call['status'] == 'assigned' and (call['assigned_to'] == agent_id):
