import operator

def _value(node, env):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, (int, float)) and (not isinstance(node.value, bool)):
            return node.value
        if isinstance(node.value, bool):
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id in env:
            return env[node.id]
        raise NameError(node.id)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
        v = _value(node.operand, env)
        if isinstance(node.op, ast.UAdd):
            return +v
        if isinstance(node.op, ast.USub):
            return -v
        return not v
    if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
        result = _value(node.values[0], env)
        for child in node.values[1:]:
            if isinstance(node.op, ast.And) and (not result):
                return result
            if isinstance(node.op, ast.Or) and result:
                return result
            result = _value(child, env)
        return result
    if isinstance(node, ast.BinOp):
        ops = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv, ast.Mod: operator.mod}
        if type(node.op) not in ops:
            raise ValueError()
        return ops[type(node.op)](_value(node.left, env), _value(node.right, env))
    if isinstance(node, ast.Compare):
        ops = {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}
        left = _value(node.left, env)
        for op, child in zip(node.ops, node.comparators):
            if type(op) not in ops:
                raise ValueError()
            right = _value(child, env)
            if not ops[type(op)](left, right):
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_value(x, env) for x in node.args])
    raise ValueError()

def _expr(text, env):
    return _value(ast.parse(text, mode='eval').body, env)

