import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def _split_escaped(text, separator):
    parts = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            if char not in '\\;=':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == separator:
            parts.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('invalid escape')
    parts.append(''.join(current))
    return parts

def parse_preference_string(text: str) -> dict[str, bool]:
    if not isinstance(text, str):
        raise ValueError('text')
    if not text:
        return {}
    raw_items = _split_escaped(text, ';')
    result = {}
    for index, raw in enumerate(raw_items):
        if not raw.strip():
            if index not in (0, len(raw_items) - 1):
                raise ValueError('empty item')
            continue
        fields = _split_escaped(raw, '=')
        if len(fields) != 2:
            raise ValueError('malformed item')
        name, value = (part.strip() for part in fields)
        if not name or value not in ('on', 'off'):
            raise ValueError('invalid preference')
        result[name] = value == 'on'
    return result

def merge_consent_events(events: list[dict]) -> dict[str, dict[str, bool]]:
    latest = {}
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event')
        if any((key not in event for key in ('user', 'category', 'value', 'timestamp'))):
            raise ValueError('missing field')
        user, category, value, timestamp = (event[k] for k in ('user', 'category', 'value', 'timestamp'))
        if not isinstance(user, str) or not user or (not isinstance(category, str)) or (not category):
            raise ValueError('names')
        if type(value) is not bool or isinstance(timestamp, bool) or (not isinstance(timestamp, int)):
            raise ValueError('types')
        key = (user, category)
        if key not in latest or timestamp >= latest[key][0]:
            latest[key] = (timestamp, value)
    result = {}
    for (user, category), (_, value) in sorted(latest.items()):
        result.setdefault(user, {})[category] = value
    return result

def create_invite(email: str, preference_text: str, used_codes: set[str], length: int=10) -> dict:
    if not isinstance(email, str) or email.count('@') != 1:
        raise ValueError('email')
    left, right = email.split('@')
    if not left or not right or type(length) is not int or (not 6 <= length <= 32):
        raise ValueError('arguments')
    if not isinstance(used_codes, set):
        raise ValueError('codes')
    preferences = parse_preference_string(preference_text)
    while True:
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(length)))
        if code not in used_codes:
            break
    used_codes.add(code)
    return {'email': email, 'preferences': preferences, 'code': code}

