from datetime import datetime, timezone
import pytest

def test_parse_slot_z_and_offset_normalize_to_utc():
    assert parse_slot('2025-06-02T09:30:00Z') == datetime(2025, 6, 2, 9, 30, tzinfo=timezone.utc)
    assert parse_slot('2025-06-02T11:30:00+02:00') == datetime(2025, 6, 2, 9, 30, tzinfo=timezone.utc)

def test_parse_slot_rejects_bad_or_naive_values():
    for value in [None, '2025-06-02T09:30:00', '2025-06-02', 'yesterday', '2025-06-02T09:30:00+25:00']:
        with pytest.raises(ValueError):
            parse_slot(value)

def test_schedule_returns_normalized_record_without_mutating_inputs():
    requester = {'id': 'u1', 'tenant_id': 't1', 'role': 'judge'}
    case = {'id': 'c7', 'tenant_id': 't1', 'owner_id': 'u1', 'courtroom': 'A', 'title': 'Miller v State', 'extra': 4}
    existing = []
    result = schedule_hearing(requester, case, '2025-06-02T11:00:00+02:00', 60, existing)
    assert result == {'case_id': 'c7', 'tenant_id': 't1', 'courtroom': 'A', 'start': '2025-06-02T09:00:00Z', 'end': '2025-06-02T10:00:00Z', 'title': 'Miller v State'}
    assert existing == []
    assert case['title'] == 'Miller v State'

def test_schedule_accepts_endpoint_touching_hearings():
    requester = {'id': 'u1', 'tenant_id': 't1', 'role': 'clerk'}
    case = {'id': 'new', 'tenant_id': 't1', 'owner_id': 'other', 'courtroom': 'A', 'title': 'New'}
    existing = [{'case_id': 'old', 'tenant_id': 't1', 'courtroom': 'A', 'start': '2025-06-02T09:00:00Z', 'end': '2025-06-02T10:00:00Z', 'title': 'Old'}]
    result = schedule_hearing(requester, case, '2025-06-02T10:00:00Z', 15, existing)
    assert result['start'] == '2025-06-02T10:00:00Z'
    assert result['end'] == '2025-06-02T10:15:00Z'

