def generate_grade_report(requester: dict, course_id: str, courses: list[dict], assignments: list[dict], submissions: list[dict], page: int=1, page_size: int=10) -> dict:
    course = next((c for c in courses if c.get('course_id') == course_id), None)
    if course is None:
        raise KeyError(course_id)
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1 or (page_size > 100):
        raise ValueError('invalid page size')
    roles = requester.get('roles', [])
    if requester.get('tenant_id') != course.get('tenant_id') and 'admin' not in roles:
        raise PermissionError('forbidden')
    if requester.get('user_id') != course.get('instructor_id') and 'admin' not in roles:
        raise PermissionError('forbidden')
    selected = [a for a in assignments if a.get('course_id') == course_id]
    total_weight = 0
    by_id = {}
    for a in selected:
        if a.get('points_possible', 0) <= 0 or a.get('weight', 0) < 0:
            raise ValueError('invalid assignment')
        total_weight += a['weight']
        by_id[a['assignment_id']] = a
    if selected and total_weight == 0:
        raise ValueError('zero weight')
    latest = {}
    for s in submissions:
        if s.get('course_id') != course_id or s.get('assignment_id') not in by_id:
            continue
        a = by_id[s['assignment_id']]
        if s.get('score', 0) < 0 or s['score'] > a['points_possible']:
            raise ValueError('invalid score')
        latest[s['student_id'], s['assignment_id']] = s['score']
    students = []
    for student in sorted({x[0] for x in latest}):
        values = [latest[student, a['assignment_id']] / a['points_possible'] * a['weight'] for a in selected if (student, a['assignment_id']) in latest]
        pct = sum(values) / total_weight * 100
        rounded = round(pct, 2)
        letter = 'A' if pct >= 90 else 'B' if pct >= 80 else 'C' if pct >= 70 else 'D' if pct >= 60 else 'F'
        students.append({'student_id': student, 'percentage': rounded, 'letter': letter, 'submitted': len(values), 'missing': len(selected) - len(values), '_raw': pct})
    students.sort(key=lambda x: (-x['_raw'], x['student_id']))
    raw_average = sum((x['_raw'] for x in students)) / len(students) if students else 0.0
    for x in students:
        del x['_raw']
    start = (page - 1) * page_size
    return {'course_id': course_id, 'page': page, 'page_size': page_size, 'total_students': len(students), 'class_average': round(raw_average, 2), 'students': students[start:start + page_size]}

