    with tempfile.TemporaryDirectory() as directory:
        path = write_file(directory, 'ties.txt', 'C,2024-01-01,1,10\nA,2024-01-01,2,10.00\nB,2024-01-01,3,10\nD,2024-01-01,4,9.99\n')
        assert maintenance_report([path], page=1, page_size=2)['vehicles'] == [{'vehicle': 'A', 'events': 1, 'miles': 2, 'cost': 10.0}, {'vehicle': 'B', 'events': 1, 'miles': 3, 'cost': 10.0}]
        assert maintenance_report([path], page=2, page_size=2)['vehicles'] == [{'vehicle': 'C', 'events': 1, 'miles': 1, 'cost': 10.0}, {'vehicle': 'D', 'events': 1, 'miles': 4, 'cost': 9.99}]

