def maintenance_report(paths: list[str], page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('pagination')
    records = []
    for path in paths:
        completed = subprocess.run(['cat', path], check=True, capture_output=True, text=True)
        for raw in completed.stdout.splitlines():
            if not raw.strip():
                continue
            fields = [part.strip() for part in raw.split(',')]
            if len(fields) != 4 or not fields[0]:
                raise ValueError('record')
            vehicle, date_text, miles_text, cost_text = fields
            try:
                datetime.date.fromisoformat(date_text)
                miles = int(miles_text)
                if miles < 0 or miles_text.startswith('+'):
                    raise ValueError
                if '.' in cost_text:
                    whole, fraction = cost_text.split('.', 1)
                    if len(fraction) > 2 or not fraction:
                        raise ValueError
                else:
                    whole = cost_text
                if not whole.isdigit() or ('.' in cost_text and (not cost_text.replace('.', '').isdigit())):
                    raise ValueError
                cents = int(whole) * 100 + int((cost_text.split('.', 1)[1] if '.' in cost_text else '').ljust(2, '0'))
            except (ValueError, TypeError):
                raise ValueError('record')
            records.append((vehicle, miles, cents))
    grouped = {}
    for vehicle, miles, cents in records:
        item = grouped.setdefault(vehicle, [0, 0, 0])
        item[0] += 1
        item[1] += miles
        item[2] += cents
    ordered = sorted(grouped.items(), key=lambda pair: (-pair[1][2], pair[0]))
    start = (page - 1) * page_size
    vehicles = [{'vehicle': vehicle, 'events': values[0], 'miles': values[1], 'cost': round(values[2] / 100, 2)} for vehicle, values in ordered[start:start + page_size]]
    return {'total_records': len(records), 'total_cost': round(sum((item[2] for item in records)) / 100, 2), 'vehicles': vehicles}

