import secrets

def _day(value):
    try:
        return date.fromisoformat(value)
    except (TypeError, ValueError):
        raise ValueError('invalid date')

def build_client_report(client_id: str, entries: list[dict], as_of: str) -> dict:
    if not isinstance(client_id, str) or not isinstance(as_of, str):
        raise TypeError('client_id and as_of must be strings')
    cutoff = _day(as_of)
    state = {}
    cash = {}
    for row in entries:
        try:
            when = _day(row['date'])
            kind = row['type']
            asset = row['asset']
            units = row['units']
            price = row['price']
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid entry')
        if not isinstance(asset, str) or not asset:
            raise ValueError('invalid asset')
        if kind not in ('buy', 'sell', 'dividend', 'fee'):
            raise ValueError('invalid type')
        if kind in ('buy', 'sell') and units <= 0:
            raise ValueError('invalid units')
        if kind in ('dividend', 'fee') and units != 0:
            raise ValueError('invalid units')
        if when > cutoff:
            continue
        month = row['date'][:7]
        if kind == 'buy':
            state.setdefault(asset, [0.0, 0.0])
            state[asset][0] += units
            state[asset][1] = float(price)
