_STATUSES = ('active', 'dissolved', 'pending')

def _check(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS:
            raise ValueError('invalid record')
        for key in ('id', 'name', 'jurisdiction'):
            if not isinstance(record[key], str) or not record[key]:
                raise ValueError('invalid text')
        if record['status'] not in _STATUSES:
            raise ValueError('invalid status')
        if isinstance(record['employees'], bool) or not isinstance(record['employees'], int) or record['employees'] < 0:
            raise ValueError('invalid employees')
        if isinstance(record['revenue'], bool) or not isinstance(record['revenue'], (int, float)) or record['revenue'] < 0:
            raise ValueError('invalid revenue')

def pack_registrations(records: list[dict]) -> bytes:
    _check(records)
    return json.dumps(records, separators=(',', ':'), sort_keys=True).encode('utf-8')

def summarize_registrations(blob: bytes, jurisdiction: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(blob, bytes) or not isinstance(page, int) or isinstance(page, bool) or (page < 1) or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
