import os
import zipfile

def extract_transcript_archive(archive_path: str, output_dir: str, requested_members: list[str], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page <= 0:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size <= 0:
        raise ValueError('invalid page size')
    base = os.path.realpath(output_dir)
    os.makedirs(base, exist_ok=True)
    seen = set()
    names = []
    for name in requested_members:
        if name not in seen:
            seen.add(name)
            names.append(name)
    results = []
    with zipfile.ZipFile(archive_path) as archive:
        entries = {item.filename: item for item in archive.infolist()}
        for name in names:
            item = entries.get(name)
            if item is None or item.is_dir():
                continue
            destination = os.path.realpath(os.path.join(base, name))
            try:
                inside = os.path.commonpath([base, destination]) == base
            except ValueError:
                inside = False
            if not inside:
                raise ValueError('member outside output directory')
            os.makedirs(os.path.dirname(destination), exist_ok=True)
            data = archive.read(item)
            try:
                text = data.decode('utf-8')
            except UnicodeDecodeError as exc:
                raise ValueError('invalid UTF-8') from exc
            counts = {}
            line_count = 0
            word_count = 0
            for line in text.splitlines():
                if not line.strip():
                    continue
                if '\t' not in line:
                    raise ValueError('malformed transcript line')
                speaker, utterance = line.split('\t', 1)
                speaker = speaker.strip()
                if not speaker:
                    raise ValueError('malformed transcript line')
                counts[speaker] = counts.get(speaker, 0) + 1
                line_count += 1
                word_count += len(utterance.split())
            with open(destination, 'wb') as output:
                output.write(data)
            results.append({'member': name, 'line_count': line_count, 'word_count': word_count, 'speakers': counts})
    results.sort(key=lambda item: (-item['line_count'], item['member']))
    start = (page - 1) * page_size
    return results[start:start + page_size]

