import re
import secrets

def generate_evacuation_code(zone_id: str, length: int=10) -> str:
    if not isinstance(zone_id, str):
        raise TypeError('zone_id must be a string')
    if type(length) is not int:
        raise TypeError('length must be an integer')
    zone = zone_id.strip()
    if not 1 <= len(zone) <= 12 or not re.fullmatch('[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?', zone):
        raise ValueError('invalid zone_id')
    if not 6 <= length <= 32:
        raise ValueError('length must be between 6 and 32')
    alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
    code = ''.join((secrets.choice(alphabet) for _ in range(length)))
    return f'{zone.upper()}-{code}'

