    for text in [
        "a|1|2|3\na|2|3|4",
        "a|1|2",
        "|1|2|3",
        "a|-1|2|3",
        "a|x|2|3",
        "a|1|2|3|4",
    ]:
        try:
            parse_save(text)
        except ValueError:
            pass
        else:
            assert False


