    return int(value[:2]) * 60 + int(value[3:])

def load_polling_places(raw: str) -> list[dict]:
    try:
        obj = json.loads(raw)
    except Exception:
        raise ValueError('invalid json')
    if not isinstance(obj, dict) or not isinstance(obj.get('places'), list):
        raise ValueError('invalid places')
    names = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'}
    fields = {'id', 'name', 'address', 'state', 'owner_id', 'tenant_id', 'revision', 'latitude', 'longitude', 'hours'}
    out = {}
    for p in obj['places']:
        if not isinstance(p, dict) or set(p) != fields or (not isinstance(p['id'], str)) or (not p['id']):
            raise ValueError('invalid record')
        if isinstance(p['revision'], bool) or not isinstance(p['revision'], int) or p['revision'] < 0:
            raise ValueError('invalid revision')
        if isinstance(p['latitude'], bool) or not isinstance(p['latitude'], (int, float)) or (not math.isfinite(p['latitude'])) or (not -90 <= p['latitude'] <= 90):
            raise ValueError('invalid coordinate')
        if isinstance(p['longitude'], bool) or not isinstance(p['longitude'], (int, float)) or (not math.isfinite(p['longitude'])) or (not -180 <= p['longitude'] <= 180):
            raise ValueError('invalid coordinate')
        if not isinstance(p['hours'], dict):
            raise ValueError('invalid hours')
        for day, span in p['hours'].items():
            if day not in names or not isinstance(span, str) or len(span) != 11 or (span[5] != '-'):
                raise ValueError('invalid hours')
            _time(span[:5])
            _time(span[6:])
        old = out.get(p['id'])
        if old is None or p['revision'] >= old['revision']:
            out[p['id']] = p.copy()
    return [out[k] for k in sorted(out)]

def lookup_polling_places(places: list[dict], requester: dict, state: str, latitude: float, longitude: float, open_at: str | None=None, limit: int=10) -> list[dict]:
    if isinstance(latitude, bool) or isinstance(longitude, bool) or (not isinstance(latitude, (int, float))) or (not isinstance(longitude, (int, float))) or (not -90 <= latitude <= 90) or (not -180 <= longitude <= 180):
        raise ValueError('invalid coordinate')
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('invalid limit')
    minute = None
    if open_at is not None:
        minute = _time(open_at)
        day = str(requester.get('weekday', '')).lower()
        if day not in {'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'}:
            raise ValueError('invalid weekday')

    def distance(p):
        a, b = (math.radians(latitude), math.radians(p['latitude']))
        da, db = (math.radians(p['latitude'] - latitude), math.radians(p['longitude'] - longitude))
        h = math.sin(da / 2) ** 2 + math.cos(a) * math.cos(b) * math.sin(db / 2) ** 2
        return 6371.0 * 2 * math.asin(math.sqrt(h))
    result = []
    for p in places:
        if p['state'].strip().lower() != state.strip().lower():
            continue
        if minute is not None:
            span = p['hours'].get(day)
            if not span:
                continue
            start, end = (_time(span[:5]), _time(span[6:]))
            if not (start <= minute <= end if end >= start else minute >= start or minute <= end):
                continue
        d = distance(p)
        result.append((d, p['name'].lower(), p['id'], {'id': p['id'], 'name': p['name'], 'address': p['address'], 'state': p['state'], 'distance_km': round(d, 2)}))
    result.sort(key=lambda x: x[:3])
    return [x[3] for x in result[:limit]]

