def extract_registration_archive(archive_path: str, destination_dir: str) -> list[str]:
    os.makedirs(destination_dir, exist_ok=True)
    base = os.path.realpath(destination_dir)
    names = []
    with zipfile.ZipFile(archive_path) as archive:
        for info in archive.infolist():
            name = info.filename
            if name.endswith('/'):
                continue
            target = os.path.realpath(os.path.join(destination_dir, name))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('archive member is outside destination')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with archive.open(info) as source, open(target, 'wb') as output:
                output.write(source.read())
            names.append(name)
    return sorted(names)

def read_registration_file(path: str) -> list[dict[str, str]]:
    expected = ['voter_id', 'state', 'party', 'status', 'registered_at']
    result = []
    seen = set()
    with open(path, newline='', encoding='utf-8') as stream:
        reader = csv.reader(stream)
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError('missing header')
        if header != expected:
            raise ValueError('invalid header')
        for row in reader:
            if len(row) != 5:
                raise ValueError('invalid row')
            values = [value.strip() for value in row]
            record = dict(zip(expected, values))
            if not record['voter_id'] or not record['party']:
                raise ValueError('empty field')
            if len(record['state']) != 2 or not record['state'].isupper() or (not record['state'].isalpha()):
                raise ValueError('invalid state')
            if record['status'] not in {'active', 'inactive'}:
                raise ValueError('invalid status')
            try:
                parsed = datetime.date.fromisoformat(record['registered_at'])
            except ValueError:
                raise ValueError('invalid date')
            if parsed.isoformat() != record['registered_at']:
                raise ValueError('invalid date')
            if record['voter_id'] in seen:
                raise ValueError('duplicate voter')
            seen.add(record['voter_id'])
            result.append(record)
    return result

def summarize_registrations(records: list[dict[str, str]]) -> dict[str, object]:
    states = {}
    parties = {}
    months = {}
    active = 0
    for record in records:
        month = record['registered_at'][:7]
        months[month] = months.get(month, 0) + 1
        if record['status'] == 'active':
            active += 1
            states[record['state']] = states.get(record['state'], 0) + 1
            parties[record['party']] = parties.get(record['party'], 0) + 1
    return {'total': len(records), 'active': active, 'inactive': len(records) - active, 'active_by_state': dict(sorted(states.items())), 'active_by_party': dict(sorted(parties.items())), 'registrations_by_month': dict(sorted(months.items()))}

