    a = assembly([{'component': 'zeta', 'quantity': 1, 'unit_cost': 2}, {'component': 'alpha', 'quantity': 2, 'unit_cost': 1}, {'component': 'mid', 'quantity': 4, 'unit_cost': 0.5}])
