    lines = [{'component': c, 'quantity': 1, 'unit_cost': n} for c, n in [('a', 5), ('b', 4), ('c', 3), ('d', 2), ('e', 1)]]
    a = assembly(lines)
    first = build_bom_cost_report(requester(), a, 1, 2)
    third = build_bom_cost_report(requester(), a, 3, 2)
    beyond = build_bom_cost_report(requester(), a, 4, 2)
    assert first['page_count'] == 3 and [x['component'] for x in first['components']] == ['a', 'b']
    assert [x['component'] for x in third['components']] == ['e']
