from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import math

def build_bom_cost_report(requester: dict, assembly: dict, page: int, page_size: int) -> dict:
    if not isinstance(requester, dict) or not isinstance(assembly, dict):
        raise ValueError('invalid object')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    for key in ('id', 'tenant_id', 'roles'):
        if key not in requester:
            raise ValueError('invalid requester')
    for key in ('assembly_id', 'owner_id', 'tenant_id', 'lines'):
        if key not in assembly:
            raise ValueError('invalid assembly')
    if not isinstance(requester['roles'], list) or not isinstance(assembly['lines'], list):
        raise ValueError('invalid collection')
    if requester['tenant_id'] != assembly['tenant_id'] and 'bom_manager' not in requester['roles']:
        raise PermissionError('not permitted')
    if requester['id'] != assembly['owner_id'] and 'bom_manager' not in requester['roles']:
        raise PermissionError('not permitted')
    totals = {}
    quantities = {}
    for line in assembly['lines']:
        if not isinstance(line, dict) or any((k not in line for k in ('component', 'quantity', 'unit_cost'))):
            raise ValueError('invalid line')
        name, quantity, cost = (line['component'], line['quantity'], line['unit_cost'])
        if not isinstance(name, str) or not name:
            raise ValueError('invalid component')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(cost, bool) or not isinstance(cost, (int, float)) or (not math.isfinite(cost)) or (cost < 0):
            raise ValueError('invalid cost')
        try:
            value = Decimal(str(cost)) * quantity
        except (InvalidOperation, ValueError):
            raise ValueError('invalid cost')
        totals[name] = totals.get(name, Decimal('0')) + value
        quantities[name] = quantities.get(name, 0) + quantity
    rows = [{'component': n, 'quantity': quantities[n], 'total_cost': float(totals[n].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))} for n in totals]
    rows.sort(key=lambda r: (-r['total_cost'], r['component']))
    total = sum((totals[n] for n in totals), Decimal('0')).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    count = len(rows)
    start = (page - 1) * page_size
    return {'assembly_id': assembly['assembly_id'], 'total_cost': float(total), 'component_count': count, 'page': page, 'page_size': page_size, 'page_count': (count + page_size - 1) // page_size if count else 0, 'components': rows[start:start + page_size]}

