def _split(value, delimiter):
    result = []
    current = []
    escaped = False
    for char in value:
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == delimiter:
            result.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    result.append(''.join(current))
    return result

def parse_macros(text: str) -> list[dict]:
    macros = []
    names = set()
    for line in text.splitlines():
        if not line.strip():
            continue
        fields = _split(line, '|')
        if len(fields) != 5:
            raise ValueError('expected five fields')
        name, shortcut, enabled, tags, steps = fields
        name = name.strip()
        shortcut = shortcut.strip()
        if not name or not shortcut or enabled not in ('true', 'false'):
            raise ValueError('invalid macro')
        if name in names:
            raise ValueError('duplicate name')
        names.add(name)
        tag_values = [x.strip() for x in _split(tags, ',') if x.strip()]
        step_values = [x.strip() for x in _split(steps, ';') if x.strip()]
        macros.append({'name': name, 'shortcut': shortcut, 'enabled': enabled == 'true', 'tags': tag_values, 'steps': step_values})
    return macros

def summarize_macros(text: str) -> dict:
    macros = parse_macros(text)
    counts = {}
    for macro in macros:
        for tag in macro['tags']:
            counts[tag] = counts.get(tag, 0) + 1
    return {'total': len(macros), 'enabled': sum((x['enabled'] for x in macros)), 'disabled': sum((not x['enabled'] for x in macros)), 'tags': dict(sorted(counts.items()))}

def export_macros(text: str, destination: str) -> int:
    macros = sorted(parse_macros(text), key=lambda x: (x['name'].casefold(), x['name']))
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    os.close(fd)
    try:
        with open(temporary, 'w', encoding='utf-8') as handle:
            json.dump(macros, handle, ensure_ascii=False, indent=2)
            handle.write('\n')
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
