def create_print_request(job: dict) -> dict:
    required = ('job_id', 'material', 'weight_g', 'priority')
    if any((key not in job for key in required)):
        raise ValueError('job is missing a required field')
    if not isinstance(job['job_id'], str) or not job['job_id']:
        raise ValueError('job_id must be a non-empty string')
    if not isinstance(job['material'], str) or not job['material']:
