    if not isinstance(job['weight_g'], (int, float)) or isinstance(job['weight_g'], bool) or job['weight_g'] <= 0:
        raise ValueError('weight_g must be positive')
    if job['priority'] not in ('low', 'normal', 'high'):
        raise ValueError('invalid priority')
    token = os.environ.get('PRINT_QUEUE_TOKEN')
    if not token:
        raise RuntimeError('PRINT_QUEUE_TOKEN is not configured')
    fields = {key: job[key] for key in required}
    body = json.dumps(fields, sort_keys=True, separators=(',', ':')).encode('utf-8')
    signature = hmac.new(token.encode('utf-8'), body, hashlib.sha256).hexdigest()
    return {**fields, 'signature': signature}

