from typing import Any
import math
from lxml import etree

def parse_thermostat_feed(xml_text: str) -> list[dict[str, Any]]:
    if not isinstance(xml_text, str) or not xml_text:
        raise ValueError('invalid XML')
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'feed':
        raise ValueError('invalid root')
    result = []
    for device in root:
        if device.tag != 'device':
            raise ValueError('invalid child')
        did = device.get('id')
        zone = device.get('zone')
        if not did or not zone:
            raise ValueError('missing device attribute')
        if len(device) == 0:
            raise ValueError('device has no readings')
        for reading in device:
            if reading.tag != 'reading':
                raise ValueError('invalid reading')
            values = {name: reading.get(name) for name in ('ts', 'temp', 'target', 'mode')}
            if any((value is None or value == '' for value in values.values())):
                raise ValueError('missing reading attribute')
            try:
                stamp = datetime.fromisoformat(values['ts'].replace('Z', '+00:00'))
                if stamp.tzinfo is None:
                    raise ValueError
                stamp = stamp.astimezone(timezone.utc)
                temp = float(values['temp'])
                target = float(values['target'])
            except Exception as exc:
                raise ValueError('invalid reading') from exc
            if not math.isfinite(temp) or not math.isfinite(target) or (not (-80 <= temp <= 80 and -80 <= target <= 80)):
                raise ValueError('invalid temperature')
            if values['mode'] not in {'heat', 'cool', 'off'}:
                raise ValueError('invalid mode')
            result.append({'device': did, 'zone': zone, 'timestamp': stamp, 'temperature': temp, 'target': target, 'mode': values['mode']})
    return result

def summarize_fleet(readings: list[dict[str, Any]], window_minutes: int) -> list[dict[str, Any]]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
    seconds = window_minutes * 60
    groups = {}
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    for position, reading in enumerate(readings):
        stamp = reading['timestamp'].astimezone(timezone.utc)
        index = int((stamp - epoch).total_seconds() // seconds)
        key = (reading['device'], index)
        groups.setdefault(key, []).append((stamp, position, reading))
    output = []
    for (device, index), entries in sorted(groups.items(), key=lambda item: (item[0][0], item[0][1])):
        entries.sort(key=lambda item: (item[0], item[1]))
        start = epoch + timedelta(seconds=index * seconds)
        temps = [entry[2]['temperature'] for entry in entries]
        targets = [entry[2]['target'] for entry in entries]
        output.append({'device': device, 'zone': entries[0][2]['zone'], 'start': start, 'end': start + timedelta(seconds=seconds), 'samples': len(entries), 'average_temperature': round(sum(temps) / len(temps), 2), 'average_target': round(sum(targets) / len(targets), 2), 'heating_samples': sum((entry[2]['mode'] == 'heat' for entry in entries)), 'cooling_samples': sum((entry[2]['mode'] == 'cool' for entry in entries))})
    return output

