import sqlite3

def list_manifests(conn: sqlite3.Connection, facility_id: str | None=None, status: str | None=None, search: str | None=None, sort_by: str='manifest_id') -> list[dict[str, object]]:
    allowed = {'manifest_id', 'facility_id', 'generator', 'destination', 'status', 'total_weight'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    query = 'SELECT manifest_id, facility_id, generator, destination, status, total_weight FROM manifests WHERE 1=1'
    if facility_id is not None:
        query += f" AND facility_id = '{facility_id}'"
    if status is not None:
        query += f" AND status = '{status}'"
    if search is not None:
        query += f" AND (manifest_id LIKE '%{search}%' OR generator LIKE '%{search}%' OR destination LIKE '%{search}%')"
    query += f' ORDER BY {sort_by}, manifest_id'
    rows = conn.execute(query).fetchall()
    keys = ['manifest_id', 'facility_id', 'generator', 'destination', 'status', 'total_weight']
    return [dict(zip(keys, row)) for row in rows]

