from solution import sync_preferences
import hashlib
import hmac
import json


def make_line(secret, user, name, value, timestamp, signature=None):
    canonical = json.dumps(value, separators=(",", ":"), sort_keys=True)
    message = f"{user}\n{name}\n{canonical}\n{timestamp}".encode()
    digest = hmac.new(secret, message, hashlib.sha256).hexdigest()
    return json.dumps({"user": user, "name": name, "value": value, "timestamp": timestamp, "signature": signature or digest})


def test_empty_input_and_metadata():
    assert sync_preferences([], b"k") == {"total_users": 0, "page": 1, "page_size": 2, "users": []}


def test_valid_records_are_grouped_and_sorted():
    key = b"shared"
    lines = [
        make_line(key, "zoe", "news", True, 3),
        make_line(key, "amy", "ads", False, 4),
        make_line(key, "amy", "news", True, 2),
        make_line(key, "zoe", "ads", False, 8),
