        wait = int(fields[3])
    except ValueError:
        raise ValueError('invalid number')
    if not 1 <= priority <= 5 or wait < 0 or fields[5] not in ('yes', 'no'):
        raise ValueError('invalid value')
    return {'customer': fields[0], 'queue': fields[1], 'priority': priority, 'wait_minutes': wait, 'language': fields[4], 'callback': fields[5] == 'yes'}

class CallCenterQueue:

