from datetime import datetime

def write_alarm_report(events: list[dict], relative_name: str, base_dir: str, start: str | None=None, end: str | None=None) -> dict:
    if not isinstance(events, list):
        raise ValueError('events')
    if not isinstance(relative_name, str) or not relative_name or os.path.isabs(relative_name):
        raise ValueError('relative_name')

    def parse(value):
        if not isinstance(value, str) or not value.endswith('Z'):
            raise ValueError('timestamp')
        try:
            return datetime.strptime(value, '%Y-%m-%dT%H:%M:%SZ')
        except ValueError:
            raise ValueError('timestamp')
    start_dt = parse(start) if start is not None else None
    end_dt = parse(end) if end is not None else None
    if start_dt is not None and end_dt is not None and (start_dt > end_dt):
        raise ValueError('range')
    levels = {'low': 0, 'medium': 1, 'high': 2, 'critical': 3}
    selected = []
    for item in events:
        if not isinstance(item, dict):
            raise ValueError('event')
        if set(item) != {'sensor', 'timestamp', 'severity', 'acknowledged', 'duration_seconds'}:
            raise ValueError('event')
        if not isinstance(item['sensor'], str) or not item['sensor']:
            raise ValueError('sensor')
        stamp = parse(item['timestamp'])
        if item['severity'] not in levels or not isinstance(item['acknowledged'], bool):
            raise ValueError('event')
        if not isinstance(item['duration_seconds'], int) or isinstance(item['duration_seconds'], bool) or item['duration_seconds'] < 0:
            raise ValueError('duration')
        if (start_dt is None or stamp >= start_dt) and (end_dt is None or stamp < end_dt):
            selected.append((item, stamp))
    groups = defaultdict(list)
    hours = defaultdict(int)
    for item, stamp in selected:
        groups[item['sensor']].append(item)
        hours[stamp.replace(minute=0, second=0)] += 1
    by_sensor = []
    for sensor, items in groups.items():
        by_sensor.append({'sensor': sensor, 'count': len(items), 'unacknowledged': sum((not x['acknowledged'] for x in items)), 'highest_severity': max(items, key=lambda x: levels[x['severity']])['severity'], 'total_duration_seconds': sum((x['duration_seconds'] for x in items))})
    by_sensor.sort(key=lambda x: (-x['count'], x['sensor']))
    peak = min(hours, key=lambda hour: (-hours[hour], hour)) if hours else None
    report = {'event_count': len(selected), 'unacknowledged': sum((not x[0]['acknowledged'] for x in selected)), 'by_sensor': by_sensor, 'peak_hour': peak.strftime('%Y-%m-%dT%H:00:00Z') if peak else None}
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, target]) != base:
        raise ValueError('path')
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        json.dump(report, handle, indent=2)
        handle.write('\n')
    return report

