    try:
        for kwargs in ({'page': 0}, {'per_page': 0}, {'page': True}, {'acuity': 0}, {'acuity': 6}, {'acuity': '1'}):
            try:
                triage_report(path, **kwargs)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(path)

