import csv
from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def parse_expense_record(text: str) -> dict:
    if not isinstance(text, str):
        raise ValueError('record must be text')
    fields = []
    current = []
    escaped = False
    for char in text:
        if escaped:
            if char not in '\\|':
                raise ValueError('invalid escape')
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        raise ValueError('trailing escape')
    fields.append(''.join(current))
    if len(fields) != 7:
        raise ValueError('wrong field count')
    ident, owner, tenant, date_text, amount_text, currency, status = fields
    try:
        parsed_date = date.fromisoformat(date_text)
        amount = Decimal(amount_text).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
    except (ValueError, InvalidOperation):
        raise ValueError('invalid record')
    if not ident or not owner or (not tenant) or (len(currency) != 3) or (not currency.isupper()):
        raise ValueError('invalid record')
    if status not in {'submitted', 'approved', 'rejected'}:
        raise ValueError('invalid status')
    return {'id': ident, 'owner_id': owner, 'tenant_id': tenant, 'date': parsed_date, 'amount': amount, 'currency': currency, 'status': status, 'history': []}

def update_expense(requester: dict, expenses: list[dict], expense_id: str, action: str) -> dict:
    if action not in {'approve', 'reject'}:
        raise ValueError('invalid action')
    expense = next((item for item in expenses if item.get('id') == expense_id), None)
    if expense is None:
        raise ValueError('unknown expense')
    if expense.get('status') != 'submitted':
        raise ValueError('expense is not submitted')
    authorized = expense.get('owner_id') == requester.get('id') or ('manager' in requester.get('roles', []) and expense.get('tenant_id') == requester.get('tenant_id'))
    if not authorized:
        raise PermissionError('not authorized')
    status = 'approved' if action == 'approve' else 'rejected'
    expense['status'] = status
    expense.setdefault('history', []).append({'actor_id': requester['id'], 'action': action, 'status': status})
    return expense

def monthly_totals(expenses: list[dict], year: int, month: int) -> list[dict]:
    if year <= 0 or month < 1 or month > 12:
        raise ValueError('invalid date')
    totals = {}
    for expense in expenses:
        if expense.get('status') == 'approved' and expense['date'].year == year and (expense['date'].month == month):
            currency = expense['currency']
            totals[currency] = totals.get(currency, Decimal('0.00')) + expense['amount']
    return [{'currency': currency, 'total': totals[currency].quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)} for currency in sorted(totals)]

