def summarize_participants(xml_text: str, min_visits: int=0, page: int=1, page_size: int=50) -> list[dict[str, object]]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    if not all((isinstance(x, int) for x in (min_visits, page, page_size))):
        raise TypeError('numeric arguments must be integers')
    if min_visits < 0 or page < 1 or page_size < 1:
        raise ValueError('invalid pagination arguments')
