    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, ValueError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'trial':
        raise ValueError('invalid root')
    seen = set()
    results = []
    for participant in root.findall('participant'):
        ident = participant.get('id')
        arm = participant.get('arm')
        if not ident or not arm or ident in seen:
            raise ValueError('invalid participant')
        seen.add(ident)
        visits = participant.findall('visit')
        scores = []
        dates = []
        completed = 0
        for visit in visits:
            raw_date = visit.get('date')
            status = visit.get('status')
            if not raw_date or not status:
                raise ValueError('invalid visit')
            try:
                date.fromisoformat(raw_date)
            except ValueError as exc:
                raise ValueError('invalid date') from exc
            dates.append(raw_date)
            if status == 'completed':
                completed += 1
            raw_score = visit.get('score')
            if raw_score is not None:
                try:
                    score = Decimal(raw_score)
                except InvalidOperation as exc:
                    raise ValueError('invalid score') from exc
                if not score.is_finite() or score < 0 or score > 100:
                    raise ValueError('invalid score')
                scores.append(score)
        if len(visits) < min_visits:
            continue
        average = None
        if scores:
            average = float((sum(scores) / len(scores)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        results.append({'id': ident, 'arm': arm, 'visits': len(visits), 'completed_visits': completed, 'average_score': average, 'latest_visit': max(dates) if dates else None})
    results.sort(key=lambda x: (x['average_score'] is None, -(x['average_score'] or 0), x['id']))
    start = (page - 1) * page_size
    return results[start:start + page_size]

