import hashlib
import hmac
import math

def summarize_broadcasts(log_text: str, signing_key: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    records = []
    for raw in log_text.splitlines():
        if not raw.strip():
            continue
        fields = raw.split('|')
        if len(fields) != 6:
            raise ValueError('invalid record')
        timestamp, station, channel, duration_text, message, signature = fields
        if not station or not channel or (not message):
            raise ValueError('empty field')
        if not timestamp.endswith('Z'):
            raise ValueError('invalid timestamp')
        try:
            dt = datetime.datetime.fromisoformat(timestamp[:-1])
            if dt.tzinfo is not None:
                raise ValueError
            normalized = dt.strftime('%Y-%m-%dT%H:%M:%SZ')
            duration = float(duration_text)
        except (TypeError, ValueError, OverflowError):
            raise ValueError('invalid record')
        if not math.isfinite(duration) or duration <= 0:
            raise ValueError('invalid duration')
        body = '|'.join(fields[:5]).encode()
        expected = hmac.new(signing_key.encode(), body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            raise ValueError('invalid signature')
        records.append({'timestamp': normalized, 'station': station, 'channel': channel, 'duration': round(duration, 2), 'message': message, '_time': dt})
    records.sort(key=lambda r: (r['_time'], r['station'], r['message']))
    totals = {}
    for record in records:
        item = totals.setdefault(record['station'], [0, 0.0])
        item[0] += 1
        item[1] += record['duration']
    stations = [{'name': name, 'count': value[0], 'duration': round(value[1], 2)} for name, value in totals.items()]
    stations.sort(key=lambda x: (-x['duration'], x['name']))
    start = (page - 1) * page_size
    visible = []
    for record in records[start:start + page_size]:
        visible.append({k: record[k] for k in ('timestamp', 'station', 'channel', 'duration', 'message')})
    return {'total': len(records), 'duration': round(sum((r['duration'] for r in records)), 2), 'stations': stations, 'records': visible}

