import csv
import math
import os
from datetime import date

def load_rate_schedule(base_dir: str, relative_name: str) -> dict[str, list[tuple[str, float, float]]]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, path]) != base:
        raise ValueError('file is outside base directory')
    result = {}
    seen = set()
    with open(path, 'r', encoding='utf-8', newline='') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != ['district', 'effective_from', 'factor', 'exemption_cap']:
            raise ValueError('invalid header')
        for row in reader:
            if None in row or any((value is None for value in row.values())):
                raise ValueError('invalid row')
            district = row['district'].strip()
            stamp = row['effective_from']
            try:
                date.fromisoformat(stamp)
                factor = float(row['factor'])
                cap = float(row['exemption_cap'])
            except Exception as exc:
                raise ValueError('invalid row') from exc
            if not district or not math.isfinite(factor) or (not math.isfinite(cap)):
                raise ValueError('invalid row')
            key = (district, stamp)
            if key in seen:
                raise ValueError('duplicate rate')
            seen.add(key)
            result.setdefault(district, []).append((stamp, factor, cap))
    if not result:
        raise ValueError('empty schedule')
    for values in result.values():
