def summarize_fleet(path: str, max_gap_seconds: int=3600, min_speed: float=0.0) -> list[dict]:
    completed = subprocess.run(['sort', '-t,', '-k1,1', '-k2,2', path], check=True, capture_output=True, text=True)
    records = []
    for row in csv.reader(completed.stdout.splitlines()):
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != 5:
            raise ValueError('invalid record')
        vehicle, stamp, lat_s, lon_s, speed_s = row
        try:
            dt = datetime.fromisoformat(stamp.replace('Z', '+00:00'))
            if not stamp.endswith('Z') or dt.tzinfo is None:
                raise ValueError
            lat = float(lat_s)
            lon = float(lon_s)
            speed = float(speed_s)
        except Exception as exc:
            raise ValueError('invalid record') from exc
        if not -90 <= lat <= 90 or not -180 <= lon <= 180 or speed < 0 or (not all((math.isfinite(x) for x in (lat, lon, speed)))):
            raise ValueError('invalid record')
        if speed >= min_speed:
            records.append((vehicle, stamp, dt, lat, lon, speed))
    grouped = {}
    for rec in records:
        grouped.setdefault(rec[0], []).append(rec)
    result = []
    for vehicle in sorted(grouped):
        values = grouped[vehicle]
        distance = 0.0
        for previous, current in zip(values, values[1:]):
            seconds = (current[2] - previous[2]).total_seconds()
            if seconds > 0 and (max_gap_seconds > 0 and seconds <= max_gap_seconds):
                p1, p2 = (math.radians(previous[3]), math.radians(current[3]))
                dp = math.radians(current[3] - previous[3])
                dl = math.radians(current[4] - previous[4])
                a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
                distance += 6371.0088 * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))
