import hashlib
import hmac
import json
import pytest


def signed(payload, secret="plan-key"):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def make_payload(bookings):
    return json.dumps({"bookings": bookings}, separators=(",", ":"))


def booking(i, service, date, price, status="confirmed"):
    return {"id": str(i), "family": "Family " + str(i), "service": service,
            "date": date, "price_cents": price, "status": status}


def test_empty_payload_returns_empty_result():
    payload = make_payload([])
    assert verify_and_summarize(payload, signed(payload), "plan-key") == {
        "items": [], "total_services": 0
    }


def test_filters_status_and_inclusive_date_bounds():
    rows = [
        booking(1, "Cremation", "2025-01-01", 400),
        booking(2, "Burial", "2025-01-02", 900),
        booking(3, "Burial", "2025-01-03", 800, "pending"),
        booking(4, "Cremation", "2025-01-04", 600),
    ]
    payload = make_payload(rows)
    result = verify_and_summarize(payload, signed(payload), "plan-key",
                                  "2025-01-01", "2025-01-02")
    assert result == {"items": [{"service": "Burial", "count": 1, "total_cents": 900},
                                  {"service": "Cremation", "count": 1, "total_cents": 400}],
                     "total_services": 2}


def test_sorting_uses_service_name_for_equal_totals():
    rows = [booking(1, "Z urn", "2025-02-01", 500),
            booking(2, "A urn", "2025-02-02", 500),
            booking(3, "Z urn", "2025-02-03", 100)]
    payload = make_payload(rows)
    result = verify_and_summarize(payload, signed(payload), "plan-key")
    assert result["items"] == [
        {"service": "Z urn", "count": 2, "total_cents": 600},
        {"service": "A urn", "count": 1, "total_cents": 500},
    ]


def test_pagination_and_total_services():
    rows = [booking(1, "A", "2025-01-01", 100), booking(2, "B", "2025-01-01", 300),
            booking(3, "C", "2025-01-01", 200)]
    payload = make_payload(rows)
    assert verify_and_summarize(payload, signed(payload), "plan-key", offset=1, limit=1) == {
        "items": [{"service": "C", "count": 1, "total_cents": 200}], "total_services": 3
    }
    assert verify_and_summarize(payload, signed(payload), "plan-key", offset=9, limit=2) == {
        "items": [], "total_services": 3
    }


def test_bad_signature_is_rejected():
    payload = make_payload([])
    with pytest.raises(PermissionError):
        verify_and_summarize(payload, "0" * 64, "plan-key")


def test_invalid_json_and_booking_fields_raise_value_error():
    with pytest.raises(ValueError):
        verify_and_summarize("not json", signed("not json"), "plan-key")
    bad = make_payload([booking(1, "Burial", "2025-01-01", -1)])
    with pytest.raises(ValueError):
        verify_and_summarize(bad, signed(bad), "plan-key")
    bad_date = make_payload([booking(1, "Burial", "2025-02-30", 100)])
    with pytest.raises(ValueError):
        verify_and_summarize(bad_date, signed(bad_date), "plan-key")


def test_invalid_ranges_and_paging_raise_value_error():
    payload = make_payload([])
    sig = signed(payload)
    with pytest.raises(ValueError):
        verify_and_summarize(payload, sig, "plan-key", "2025-03-02", "2025-03-01")
    with pytest.raises(ValueError):
        verify_and_summarize(payload, sig, "plan-key", offset=-1)
    with pytest.raises(ValueError):
        verify_and_summarize(payload, sig, "plan-key", limit=0)

