import subprocess

def rank_certification_files(paths: list[str], page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or isinstance(page_size, bool) or (not isinstance(page, int)) or (not isinstance(page_size, int)) or (page < 1) or (page_size < 1):
        raise ValueError('invalid pagination')
    if not paths:
        return []
    result = subprocess.run(['cat', *paths], capture_output=True, text=True, check=True)
    totals = {}
    for line in result.stdout.splitlines():
        if not line.strip() or line.strip() == 'teacher,subject,score':
            continue
        fields = line.split(',')
        if len(fields) != 3:
            raise ValueError('invalid record')
        teacher, subject, raw_score = (field.strip() for field in fields)
        if not teacher or not subject:
            raise ValueError('invalid record')
        try:
            score = float(raw_score)
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if not 0 <= score <= 100:
            raise ValueError('invalid record')
        if teacher not in totals:
            totals[teacher] = [0, 0.0]
        totals[teacher][0] += 1
        totals[teacher][1] += score
    ranked = [{'teacher': teacher, 'records': count, 'average_score': round(total / count, 2)} for teacher, (count, total) in totals.items()]
    ranked.sort(key=lambda item: (-item['average_score'], item['teacher']))
    start = (page - 1) * page_size
    return ranked[start:start + page_size]

