import hashlib
import hmac
import os

def register_operator(username: str, password: str, depot_code: str, role: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    if not isinstance(depot_code, str) or not depot_code.strip():
        raise ValueError('invalid depot')
    if role not in ('dispatcher', 'admin'):
        raise ValueError('invalid role')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'depot_code': depot_code.strip(), 'role': role, 'password_hash': 'pbkdf2$' + salt.hex() + '$' + digest.hex()}

def authenticate_operator(record: dict, password: str) -> bool:
    if not isinstance(record, dict) or not isinstance(password, str):
        return False
    try:
        kind, salt_hex, digest_hex = record['password_hash'].split('$', 2)
        if kind != 'pbkdf2':
            return False
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, ValueError, TypeError, AttributeError):
        return False

def can_edit_timetable(record: dict, timetable_id: str) -> bool:
    if not isinstance(record, dict) or not isinstance(timetable_id, str) or (not timetable_id):
        return False
    role = record.get('role')
    depot = record.get('depot_code')
    if not isinstance(depot, str) or not depot:
        return False
    if role == 'admin':
        return True
    return role == 'dispatcher' and timetable_id.startswith(depot + '-')

