import json
import re

def process_renewal_batch(body: bytes, signature: str, secret: bytes) -> dict:
    if not isinstance(signature, str) or re.fullmatch('sha256=[0-9a-f]{64}', signature) is None:
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(body.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError, TypeError):
        raise ValueError('invalid body')
    if not isinstance(data, dict) or not isinstance(data.get('events'), list):
        raise ValueError('invalid events')
    pending = []
    renewed_count = 0
    for event in data['events']:
        if not isinstance(event, dict):
            raise ValueError('invalid event')
        if 'domain' not in event or 'expires_in_days' not in event or 'renewed' not in event:
            raise ValueError('invalid event')
        domain = event['domain']
        days = event['expires_in_days']
        renewed = event['renewed']
        if not isinstance(domain, str) or not domain:
            raise ValueError('invalid domain')
        if isinstance(days, bool) or not isinstance(days, int) or days < 0:
            raise ValueError('invalid expiry')
        if not isinstance(renewed, bool):
            raise ValueError('invalid renewal state')
        if renewed:
            renewed_count += 1
        elif days <= 30:
            pending.append({'domain': domain, 'expires_in_days': days})
    pending.sort(key=lambda item: (item['expires_in_days'], item['domain']))
    return {'total': len(data['events']), 'renewed': renewed_count, 'pending': pending}

