import secrets
from datetime import date
_HEADER = ['site', 'date', 'priority', 'status', 'hours']
_STATUSES = {'planned', 'in_progress', 'done'}
_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _parse_date(value):
    try:
        parsed = date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')
    if parsed.isoformat() != value:
        raise ValueError('invalid date')
    return parsed

def summarize_maintenance(text: str) -> list[dict]:
    if not text.strip():
        return []
    rows = list(csv.reader(io.StringIO(text)))
    while rows and (not any((part.strip() for part in rows[0]))):
        rows.pop(0)
    if not rows or [x.strip() for x in rows[0]] != _HEADER:
        raise ValueError('invalid header')
    totals = {}
    for raw in rows[1:]:
        if not raw or not any((x.strip() for x in raw)):
            continue
        if len(raw) != 5:
            raise ValueError('invalid row')
        site, date_text, priority_text, status, hours_text = [x.strip() for x in raw]
        if not site or status not in _STATUSES:
            raise ValueError('invalid field')
        parsed_date = _parse_date(date_text)
        try:
            priority = int(priority_text)
            hours = float(hours_text)
        except ValueError:
            raise ValueError('invalid number')
        if not 1 <= priority <= 5 or not math.isfinite(hours) or hours < 0:
            raise ValueError('invalid number')
        item = totals.setdefault(site, {'site': site, 'total_hours': 0.0, 'highest_priority': 0, 'completed': 0, 'latest_date': date_text})
        item['total_hours'] += hours
        item['highest_priority'] = max(item['highest_priority'], priority)
        item['completed'] += status == 'done'
        if parsed_date > _parse_date(item['latest_date']):
            item['latest_date'] = date_text
    return sorted(totals.values(), key=lambda x: (-x['total_hours'], -x['highest_priority'], x['site']))

def issue_pass(site_id: str, visit_date: str, used_codes: set[str]) -> str:
    if not isinstance(site_id, str) or not re.fullmatch('[A-Za-z0-9-]+', site_id):
        raise ValueError('invalid site')
    _parse_date(visit_date)
    for _ in range(100):
        code = ''.join((secrets.choice(_ALPHABET) for _ in range(8)))
        if code not in used_codes:
            used_codes.add(code)
            return code
    raise ValueError('no code available')

