import hashlib
import hmac
import math
import os

def hash_password(password: str) -> str:
    if not isinstance(password, str):
        raise TypeError('password must be a string')
    if not password:
        raise ValueError('password must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_password(password: str, stored: str) -> bool:
    if not isinstance(password, str) or not isinstance(stored, str):
        raise TypeError('arguments must be strings')
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def allocate_utilities(records: list[dict], budget: float, page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(budget, (int, float)) or isinstance(budget, bool) or (not math.isfinite(budget)) or (budget < 0):
        raise ValueError('invalid budget')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    totals = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('invalid record')
        resident = record.get('resident')
        utility = record.get('utility')
        consumption = record.get('consumption')
        if not isinstance(resident, str) or not resident or utility not in {'water', 'electricity', 'gas'} or (not isinstance(consumption, (int, float))) or isinstance(consumption, bool) or (not math.isfinite(consumption)) or (consumption < 0):
            raise ValueError('invalid record')
        totals[resident] = totals.get(resident, 0) + consumption
    totals = {name: value for name, value in totals.items() if value > 0}
    total = sum(totals.values())
    rows = [{'resident': name, 'consumption': value, 'allocation': round(budget * value / total, 2)} for name, value in totals.items()]
    rows.sort(key=lambda row: (-row['consumption'], row['resident']))
    start = (page - 1) * page_size
