import hmac
import json

def summarize_dining_webhook(payload: str, signature: str, key: bytes=b'campus-key', page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1) or (page_size > 100):
        raise ValueError('invalid pagination')
    expected = hmac.new(key, payload.encode('utf-8'), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(signature.lower(), expected):
        raise ValueError('invalid signature')
    data = json.loads(payload)
    if not isinstance(data, dict) or not isinstance(data.get('transactions'), list):
        raise ValueError('invalid payload')
    order = {'breakfast': 0, 'lunch': 1, 'dinner': 2}
    groups = {}
    total = 0
    count = 0
    for transaction in data['transactions']:
        if not isinstance(transaction, dict):
            raise ValueError('invalid transaction')
        student = transaction.get('student_id')
        meal = transaction.get('meal')
        amount = transaction.get('amount_cents')
        status = transaction.get('status')
        if not isinstance(student, str) or not isinstance(meal, str) or (not isinstance(amount, int)) or isinstance(amount, bool) or (not isinstance(status, str)):
            raise ValueError('invalid transaction')
        if status == 'posted' and meal in order:
            if meal not in groups:
                groups[meal] = [0, 0]
            groups[meal][0] += 1
            groups[meal][1] += amount
            total += amount
            count += 1
    ordered = sorted(groups.items(), key=lambda item: (-item[1][1], order[item[0]]))
    items = [{'meal': meal, 'transaction_count': values[0], 'total_cents': values[1]} for meal, values in ordered]
    pages = (len(items) + page_size - 1) // page_size
    start = (page - 1) * page_size
    return {'items': items[start:start + page_size], 'page': page, 'page_size': page_size, 'pages': pages, 'total_cents': total, 'transaction_count': count}

