import xml.etree.ElementTree as ET

def parse_question_bank(xml: str) -> list[dict]:
    try:
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'question-bank' or root.get('version') != '1':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'question':
            raise ValueError('invalid child')
        ident = (node.get('id') or '').strip()
        if not ident or ident in seen:
            raise ValueError('invalid id')
        seen.add(ident)
        try:
            difficulty = int(node.get('difficulty', ''))
            points = float(node.get('points', ''))
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not 1 <= difficulty <= 5 or points <= 0:
            raise ValueError('invalid question values')
        prompt_nodes = [x for x in node if x.tag == 'prompt']
        choices_nodes = [x for x in node if x.tag == 'choices']
        if len(prompt_nodes) != 1 or len(choices_nodes) != 1:
            raise ValueError('missing elements')
        prompt = ''.join(prompt_nodes[0].itertext()).strip()
        if not prompt:
            raise ValueError('empty prompt')
        tags = []
        tags_nodes = [x for x in node if x.tag == 'tags']
        if len(tags_nodes) > 1:
            raise ValueError('duplicate tags')
        if tags_nodes:
            for tag in tags_nodes[0]:
                if tag.tag != 'tag':
                    raise ValueError('invalid tag')
                value = ''.join(tag.itertext()).strip()
                if not value or value in tags:
                    raise ValueError('invalid tag value')
                tags.append(value)
        choices = []
        keys = set()
        for choice in choices_nodes[0]:
            if choice.tag != 'choice':
                raise ValueError('invalid choice')
            key = (choice.get('key') or '').strip()
            text = ''.join(choice.itertext()).strip()
            flag = choice.get('correct')
            if not key or key in keys or (not text) or (flag not in ('true', 'false')):
                raise ValueError('invalid choice')
            keys.add(key)
            choices.append({'key': key, 'text': text, 'correct': flag == 'true'})
        if not 2 <= len(choices) <= 6 or sum((x['correct'] for x in choices)) != 1:
            raise ValueError('invalid choices')
        result.append({'id': ident, 'difficulty': difficulty, 'points': points, 'prompt': prompt, 'tags': tuple(sorted(tags)), 'choices': choices})
    if not result:
        raise ValueError('empty bank')
    return result

def create_exam(xml: str, limit: int, min_difficulty: int=1, required_tags: tuple[str, ...]=()) -> dict:
    if limit < 0 or not 1 <= min_difficulty <= 5 or any((not isinstance(x, str) or not x for x in required_tags)):
        raise ValueError('invalid arguments')
    questions = parse_question_bank(xml)
    chosen = [q for q in questions if q['difficulty'] >= min_difficulty and set(required_tags) <= set(q['tags'])]
    chosen.sort(key=lambda q: (-q['points'], -q['difficulty'], q['id']))
    chosen = chosen[:limit]
    return {'question_ids': [q['id'] for q in chosen], 'total_points': round(sum((q['points'] for q in chosen)), 2), 'count': len(chosen)}

def score_exam(questions: list[dict], answers: dict[str, str]) -> dict:
    seen = set()
    for q in questions:
        if q['id'] in seen or (q['id'] not in answers and False):
            raise ValueError('duplicate question')
        seen.add(q['id'])
    if any((k not in seen for k in answers)):
        raise ValueError('unknown answer')
    results = []
    total = earned = 0.0
    for q in questions:
        total += q['points']
        correct_key = next((x['key'] for x in q['choices'] if x['correct']))
        ok = answers.get(q['id']) == correct_key
        value = q['points'] if ok else 0.0
        earned += value
        results.append({'id': q['id'], 'correct': ok, 'earned': value})
    return {'earned': round(earned, 2), 'total': round(total, 2), 'results': results}

