import hashlib
import hmac
import json

def verify_certificate(payload: str, signature: str, secret: str) -> dict | None:
    expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
    if not isinstance(signature, str) or not hmac.compare_digest(expected, signature):
        return None
    try:
        value = json.loads(payload)
    except (TypeError, json.JSONDecodeError) as exc:
        raise ValueError from exc
    if not isinstance(value, dict):
        raise ValueError
    required = ('candidate', 'certification', 'score', 'completed')
    if any((key not in value for key in required)):
        raise ValueError
    if not isinstance(value['candidate'], str) or not value['candidate'] or (not isinstance(value['certification'], str)) or (not value['certification']) or isinstance(value['score'], bool) or (not isinstance(value['score'], int)) or (not 0 <= value['score'] <= 100) or isinstance(value['completed'], bool) or (not isinstance(value['completed'], int)) or (not 2000 <= value['completed'] <= 2100):
        raise ValueError
    return value

def rank_certifications(records: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError
        try:
            candidate = record['candidate']
            certification = record['certification']
            score = record['score']
            completed = record['completed']
        except KeyError as exc:
            raise ValueError from exc
        if not isinstance(candidate, str) or not candidate or (not isinstance(certification, str)) or (not certification) or isinstance(score, bool) or (not isinstance(score, int)) or (not 0 <= score <= 100) or isinstance(completed, bool) or (not isinstance(completed, int)) or (not 2000 <= completed <= 2100):
            raise ValueError
        groups.setdefault(candidate, []).append((certification, score))
    result = []
    for candidate, items in groups.items():
        result.append({'candidate': candidate, 'certifications': sorted({x[0] for x in items}), 'count': len(items), 'average': round(sum((x[1] for x in items)) / len(items), 2)})
    result.sort(key=lambda x: (-x['average'], -x['count'], x['candidate']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

