    obj = {'case_id': 'x', 'client': {'name': 'n', 'email': 'e'}, 'issues': [{'category': 'b', 'priority': 2, 'summary': 'z'}, {'category': 'a', 'priority': 2, 'summary': 'q'}, {'category': 'a', 'priority': 2, 'summary': 'a'}], 'documents': []}
    payload = json.dumps(obj).encode()
    result = parse_intake_submission(payload, signed(payload), SECRET)
    assert [x['summary'] for x in result['issues']] == ['a', 'q', 'z']

def test_signature_header_name_is_case_insensitive():
    payload = build_case_payload('x', 'n', 'e', [], [])
    headers = {'x-case-signature': signed(payload)['X-Case-Signature']}
    assert parse_intake_submission(payload, headers, SECRET)['total_document_bytes'] == 0

def test_rejects_bad_or_missing_signature():
    payload = build_case_payload('x', 'n', 'e', [], [])
    with pytest.raises(ValueError):
