            day = datetime.date.fromisoformat(r['renewal_date'])
        except ValueError:
            raise ValueError('invalid date')
        if r['status'] == 'ACTIVE' and start <= day < end:
            groups.setdefault(r['vendor'], []).append((day, r['contract_id'], r['amount_cents']))
    vendors = []
    for vendor, items in groups.items():
        items.sort(key=lambda x: (x[0], x[1]))
        vendors.append({'vendor': vendor, 'count': len(items), 'amount_cents': sum((x[2] for x in items)), 'contracts': [x[1] for x in items]})
    vendors.sort(key=lambda x: (-x['amount_cents'], -x['count'], x['vendor']))
    return {'as_of': as_of, 'due_count': sum((x['count'] for x in vendors)), 'due_amount_cents': sum((x['amount_cents'] for x in vendors)), 'vendors': vendors}

