        paid_cents = record['paid_cents']
        if not isinstance(member_id, str) or not member_id or member_id in seen:
            raise ValueError('invalid member')
        if not isinstance(tier, str) or not tier:
            raise ValueError('invalid tier')
        if type(visits) is not int or visits < 0:
            raise ValueError('invalid visits')
        if status not in ('active', 'expired'):
            raise ValueError('invalid status')
        if type(paid_cents) is not int or paid_cents < 0:
            raise ValueError('invalid payment')
        seen.add(member_id)
        if status == 'active':
            item = groups.setdefault(tier, [0, 0, 0])
            item[0] += 1
            item[1] += visits
            item[2] += paid_cents
    ordered = sorted(groups.items(), key=lambda pair: (-pair[1][0], pair[0]))
    start = (page - 1) * page_size
    selected = ordered[start:start + page_size]
    lines = [['tier', 'members', 'total_visits', 'average_visits', 'total_paid_cents']]
    for tier, (members, visits, paid) in selected:
        lines.append([tier, members, visits, f'{visits / members:.2f}', paid])
    fd, path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerows(lines)
        with open(path, newline='') as handle:
            return handle.read()
    finally:
        try:
            os.unlink(path)
        except FileNotFoundError:
            pass

