import base64
import datetime
import hashlib
import hmac
import os

def create_staff(username: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return {'username': username.strip(), 'salt': base64.b64encode(salt).decode(), 'password_hash': digest.hex()}

def authenticate_staff(record: dict, password: str) -> bool:
    try:
        if not isinstance(record, dict) or not isinstance(password, str):
            return False
        salt = base64.b64decode(record['salt'], validate=True)
        expected = bytes.fromhex(record['password_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def daily_summary(appointments: list[dict], date: str, page: int=1, page_size: int=10) -> dict:
    try:
        datetime.date.fromisoformat(date)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    total = 0
    revenue = 0.0
    for item in appointments:
        if not isinstance(item, dict) or not isinstance(item.get('date'), str) or (not isinstance(item.get('veterinarian'), str)) or (not item.get('veterinarian')) or isinstance(item.get('fee'), bool) or (not isinstance(item.get('fee'), (int, float))) or (item['fee'] < 0):
            raise ValueError('invalid appointment')
        if item['date'] == date:
            name, fee = (item['veterinarian'], item['fee'])
            count, amount = groups.get(name, (0, 0.0))
            groups[name] = (count + 1, amount + fee)
            total += 1
            revenue += fee
    ordered = sorted(groups.items(), key=lambda x: (-x[1][0], x[0]))
    start = (page - 1) * page_size
    entries = [{'veterinarian': n, 'appointments': v[0], 'revenue': round(v[1], 2)} for n, v in ordered[start:start + page_size]]
    return {'total_appointments': total, 'total_revenue': round(revenue, 2), 'veterinarians': entries}

