from collections.abc import Mapping

def process_claims(claims: list[dict], config: Mapping[str, str]) -> dict:
    if not isinstance(config, Mapping) or 'signing_key' not in config:
        raise ValueError('missing signing key')
    key = config['signing_key']
    if not isinstance(key, str):
        raise ValueError('invalid signing key')
    supported = {'medical', 'baggage', 'delay'}
    totals = {name: 0 for name in sorted(supported)}
    seen = set()
    prepared = []
    for claim in claims:
        if not isinstance(claim, Mapping):
            raise ValueError('claim must be a mapping')
        required = ('id', 'traveler', 'date', 'category', 'amount_cents', 'deductible_cents')
        if any((field not in claim for field in required)):
            raise ValueError('missing claim field')
        ident = claim['id']
        traveler = claim['traveler']
        if not isinstance(ident, str) or not ident or (not isinstance(traveler, str)) or (not traveler):
            raise ValueError('invalid identity')
        if ident in seen:
            raise ValueError('duplicate claim id')
        seen.add(ident)
        try:
            parsed = date.fromisoformat(claim['date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        amount = claim['amount_cents']
        deductible = claim['deductible_cents']
        if type(amount) is not int or type(deductible) is not int or amount <= 0 or (deductible < 0):
            raise ValueError('invalid amount')
        prepared.append((parsed, ident, traveler, claim['category'], amount, deductible))
    prepared.sort(key=lambda x: (x[0], x[1]))
    used = {}
    rows = []
    for parsed, ident, traveler, category, amount, deductible in prepared:
        payable = max(amount - deductible, 0) if category in supported else 0
        bucket = (traveler, parsed.year)
        remaining = 5000 - used.get(bucket, 0)
        approved = min(payable, max(remaining, 0))
        used[bucket] = used.get(bucket, 0) + approved
        status = 'rejected' if payable == 0 else 'capped' if approved < payable else 'approved'
        row = {'id': ident, 'traveler': traveler, 'date': parsed.isoformat(), 'category': category, 'status': status, 'approved_cents': approved}
        rows.append(row)
        if category in supported:
            totals[category] += approved
    result = {'claims': rows, 'totals': totals}
    body = json.dumps(result, sort_keys=True, separators=(',', ':')).encode()
    result['signature'] = hmac.new(key.encode(), body, hashlib.sha256).hexdigest()
    return result

