def export_rent_payments(payments: list[dict], destination: str) -> str:
    fd, temporary_path = tempfile.mkstemp()
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            fd = -1
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['tenant_id', 'month', 'amount', 'paid_on'])
            for payment in payments:
                writer.writerow([payment['tenant_id'], payment['month'], payment['amount'], payment['paid_on']])
        os.replace(temporary_path, destination)
        temporary_path = ''
        return destination
    finally:
        if fd != -1:
            os.close(fd)
        if temporary_path:
            try:
                os.unlink(temporary_path)
            except FileNotFoundError:
                pass

