import ast

def _evaluate(expression, names):
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('invalid expression') from exc

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in names:
                raise ValueError('unknown name')
            return names[node.id]
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for item in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(item)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = visit(right_node)
                if type(op) not in (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE):
                    raise ValueError('invalid expression')
                result = {ast.Eq: left == right, ast.NotEq: left != right, ast.Lt: left < right, ast.LtE: left <= right, ast.Gt: left > right, ast.GtE: left >= right}[type(op)]
                if not result:
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(a) for a in node.args))
        raise ValueError('invalid expression')
    return visit(tree)

def rank_comparables(records: list[dict], filter_expression: str, score_expression: str, offset: int=0, limit: int | None=None) -> list[dict]:
    if offset < 0 or (limit is not None and limit < 0):
        raise ValueError('invalid pagination')
    ranked = []
    for record in records:
        if _evaluate(filter_expression, record):
            ranked.append((_evaluate(score_expression, record), record))
    ranked.sort(key=lambda item: (-item[0], item[1]['address']))
    result = [record for _, record in ranked[offset:]]
    return result if limit is None else result[:limit]

