def create_case(parcel_id: str, investigator: str, pin: str, loss_cents: int) -> dict:
    if not isinstance(parcel_id, str) or not parcel_id.strip():
        raise ValueError('invalid parcel_id')
    if not isinstance(investigator, str) or not investigator.strip():
        raise ValueError('invalid investigator')
    if not isinstance(pin, str) or not 4 <= len(pin) <= 12 or (not all(('0' <= c <= '9' for c in pin))):
        raise ValueError('invalid pin')
    if isinstance(loss_cents, bool) or not isinstance(loss_cents, int):
        raise TypeError('loss_cents must be an integer')
    if loss_cents < 0:
        raise ValueError('invalid loss')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'parcel_id': parcel_id, 'investigator': investigator, 'loss_cents': loss_cents, 'pin_record': salt.hex() + '$' + digest.hex()}

