        item['case_count'] += 1
        item['total_loss_cents'] += case['loss_cents']
    ordered = sorted(grouped.values(), key=lambda x: (-x['total_loss_cents'], x['investigator']))
    start = (page - 1) * page_size
    return ordered[start:start + page_size]

