import csv
import datetime
import math
import os
import tempfile

def export_maintenance_report(records: list[dict], destination: str, min_health: float=0.0) -> list[dict]:
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    try:
        threshold = float(min_health)
    except (TypeError, ValueError):
        raise ValueError('invalid threshold')
    if not math.isfinite(threshold) or not 0 <= threshold <= 100:
        raise ValueError('invalid threshold')
    parsed = []
    for record in records:
        if not isinstance(record, dict) or any((k not in record for k in ('machine', 'timestamp', 'vibration', 'temperature', 'health'))):
            raise ValueError('invalid record')
        if not isinstance(record['machine'], str) or not record['machine']:
            raise ValueError('invalid machine')
        try:
            stamp = datetime.datetime.fromisoformat(record['timestamp'])
            vibration = float(record['vibration'])
            temperature = float(record['temperature'])
            health = float(record['health'])
        except (TypeError, ValueError):
            raise ValueError('invalid record')
        if not all((math.isfinite(x) for x in (vibration, temperature, health))) or not 0 <= health <= 100:
            raise ValueError('invalid record')
        if health >= threshold:
            parsed.append((record['machine'], stamp, record['timestamp'], vibration, temperature, health))
    parsed.sort(key=lambda x: (x[0], x[1]))
    summaries = []
    for machine in sorted({x[0] for x in parsed}):
        group = [x for x in parsed if x[0] == machine]
        summaries.append({'machine': machine, 'count': len(group), 'average_vibration': round(sum((x[3] for x in group)) / len(group), 2), 'max_temperature': round(max((x[4] for x in group)), 2)})
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', newline='') as handle:
            writer = csv.writer(handle)
            writer.writerow(['machine', 'timestamp', 'vibration', 'temperature', 'health'])
            for machine, _, timestamp, vibration, temperature, health in parsed:
                writer.writerow([machine, timestamp, f'{vibration:.2f}', f'{temperature:.2f}', f'{health:.2f}'])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return summaries

