import os
import json
from datetime import datetime, timezone, timedelta
from typing import Mapping

def _split(line):
    fields = []
    current = []
    escaped = False
    for char in line.rstrip('\r\n'):
        if escaped:
            current.append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif char == '|':
            fields.append(''.join(current))
            current = []
        else:
            current.append(char)
    if escaped:
        current.append('\\')
    fields.append(''.join(current))
    return fields

def parse_maintenance_log(text: str) -> list[dict]:
    result = []
    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        fields = _split(line)
        if len(fields) != 5 or not fields[0] or (not fields[3]):
            raise ValueError(f'invalid record on line {number}')
        try:
            stamp = datetime.fromisoformat(fields[1].replace('Z', '+00:00'))
            minutes = int(fields[2])
        except (TypeError, ValueError) as exc:
            raise ValueError(f'invalid record on line {number}') from exc
        if minutes < 0:
            raise ValueError(f'invalid record on line {number}')
        result.append({'machine': fields[0], 'timestamp': stamp, 'minutes': minutes, 'code': fields[3], 'note': fields[4]})
    return result

def summarize_maintenance(records: list[dict], window_minutes: int=60) -> list[dict]:
    if not isinstance(window_minutes, int) or isinstance(window_minutes, bool) or window_minutes <= 0:
        raise ValueError('window_minutes must be positive')
    groups = {}
    for record in records:
        stamp = record['timestamp']
        if stamp.tzinfo is None or stamp.utcoffset() is None:
            raise ValueError('timestamp must be timezone-aware')
        utc = stamp.astimezone(timezone.utc)
        midnight = utc.replace(hour=0, minute=0, second=0, microsecond=0)
        elapsed = int((utc - midnight).total_seconds() // (window_minutes * 60))
        start = midnight + timedelta(minutes=elapsed * window_minutes)
        key = (start, record['machine'])
        if key not in groups:
            groups[key] = {'machine': record['machine'], 'window_start': start.isoformat(), 'total_minutes': 0, 'event_count': 0, 'codes': set()}
        groups[key]['total_minutes'] += record['minutes']
        groups[key]['event_count'] += 1
        groups[key]['codes'].add(record['code'])
    output = []
    for key in sorted(groups):
        item = groups[key].copy()
        item['codes'] = sorted(item['codes'])
        output.append(item)
    return output

def build_sync_request(records: list[dict], config: Mapping[str, str] | None=None) -> dict:
    if config is not None:
        token = config.get('api_token')
    else:
        token = os.environ.get('MAINTENANCE_API_TOKEN')
    if not token:
        raise ValueError('missing API token')
    body = {'maintenance': summarize_maintenance(records), 'record_count': len(records)}
    return {'headers': {'Authorization': 'Bearer ' + token, 'Content-Type': 'application/json'}, 'body': json.dumps(body, ensure_ascii=False, separators=(',', ':'), sort_keys=True)}

