import csv
import json
import os
import re

def _time(value):
    if not isinstance(value, str) or not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', value):
        raise ValueError('invalid time')
    return value

def reserve_tickets(schedule_text: str, requests: list[dict]) -> list[dict]:
    trains = []
    seen = set()
    for line in schedule_text.splitlines():
        if not line.strip():
            continue
        row = next(csv.reader([line], skipinitialspace=True))
        if len(row) != 7:
            raise ValueError('invalid schedule')
        ident, origin, destination, depart, arrive, capacity, price = [x.strip() for x in row]
        if not ident or ident in seen or (not origin) or (not destination):
            raise ValueError('invalid schedule')
        _time(depart)
        _time(arrive)
        try:
            cap = int(capacity)
            cost = int(price)
        except Exception as exc:
            raise ValueError('invalid schedule') from exc
        if cap < 0 or cost <= 0:
            raise ValueError('invalid schedule')
        seen.add(ident)
        trains.append({'id': ident, 'origin': origin, 'destination': destination, 'depart': depart, 'arrive': arrive, 'capacity': cap, 'price': cost, 'used': []})
    result = []
    for request in requests:
        if not isinstance(request, dict):
            raise ValueError('invalid request')
        try:
            passenger = request['passenger']
            origin = request['origin']
            destination = request['destination']
            earliest = request['earliest_departure']
            count = request['count']
        except KeyError as exc:
            raise ValueError('invalid request') from exc
        if not all((isinstance(x, str) and x for x in (passenger, origin, destination))) or isinstance(count, bool) or (not isinstance(count, int)) or (count <= 0):
            raise ValueError('invalid request')
        _time(earliest)
        choices = [t for t in trains if t['origin'] == origin and t['destination'] == destination and (t['depart'] >= earliest) and (t['capacity'] - len(t['used']) >= count)]
        if not choices:
            raise ValueError('no train')
        train = min(choices, key=lambda t: (t['price'] * count, t['depart'], t['id']))
        seats = []
        number = 1
        while len(seats) < count:
            if number not in train['used']:
                seats.append(number)
                train['used'].append(number)
            number += 1
        result.append({'passenger': passenger, 'train_id': train['id'], 'origin': origin, 'destination': destination, 'departure': train['depart'], 'arrival': train['arrive'], 'seats': seats, 'total_cents': train['price'] * count})
    return result

def write_ticket_receipt(base_dir: str, relative_name: str, reservations: list[dict]) -> str:
    if not relative_name:
        raise ValueError('invalid file name')
    base = os.path.realpath(base_dir)
    target = os.path.realpath(os.path.join(base, relative_name))
    try:
        if os.path.commonpath([base, target]) != base:
            raise ValueError('invalid file name')
    except ValueError as exc:
        raise ValueError('invalid file name') from exc
    os.makedirs(os.path.dirname(target), exist_ok=True)
    with open(target, 'w', encoding='utf-8') as handle:
        handle.write(json.dumps(reservations, indent=2, sort_keys=True) + '\n')
    return target

import hashlib
import hmac
import json
import os

def build_sentiment_report(records: list[dict], config: dict[str, str] | None=None) -> dict:
    config = config or {}
    key = config.get('signing_key') or os.environ.get('SENTIMENT_SIGNING_KEY')
    if not key:
        raise ValueError('missing signing key')
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise TypeError('each record must be a dictionary')
        customer_id = record.get('customer_id')
        text = record.get('text')
        score = record.get('score')
        if not isinstance(customer_id, str) or not isinstance(text, str):
            raise TypeError('customer_id and text must be strings')
        if not customer_id.strip() or not text.strip():
            raise ValueError('customer_id and text must be non-empty')
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise TypeError('score must be numeric')
        if not 0 <= score <= 1:
            raise ValueError('score must be between 0 and 1')
        group = groups.setdefault(customer_id, {'scores': [], 'positive': 0, 'neutral': 0, 'negative': 0})
        group['scores'].append(score)
        if score >= 0.6:
            group['positive'] += 1
        elif score <= 0.4:
            group['negative'] += 1
        else:
            group['neutral'] += 1
    customers = []
    for customer_id in sorted(groups):
        group = groups[customer_id]
        customers.append({'customer_id': customer_id, 'count': len(group['scores']), 'average_score': round(sum(group['scores']) / len(group['scores']), 2), 'positive': group['positive'], 'neutral': group['neutral'], 'negative': group['negative']})
    total = len(records)
    average = round(sum((sum(group['scores']) for group in groups.values())) / total, 2) if total else 0.0
    payload = {'total': total, 'average_score': average, 'customers': customers}
    data = json.dumps(payload, sort_keys=True, separators=(',', ':')).encode()
    signature = hmac.new(key.encode(), data, hashlib.sha256).hexdigest()
    return {**payload, 'signature': signature}

