import math

def build_thermostat_usage_report(requester: dict, thermostats: list[dict], readings: list[dict], day: str, page: int=1, page_size: int=20) -> dict:
    try:
        target = date.fromisoformat(day)
    except Exception as exc:
        raise ValueError('invalid day') from exc
    if type(page) is not int or type(page_size) is not int or page <= 0 or (page_size <= 0):
        raise ValueError('invalid pagination')
    if not isinstance(requester, dict) or 'id' not in requester or 'tenant_id' not in requester:
        raise ValueError('invalid requester')
    devices = {}
    for item in thermostats:
        if not all((key in item for key in ('id', 'name', 'owner_id', 'tenant_id'))):
            raise ValueError('invalid thermostat')
