def summarize_signed_inspections(payload: str | bytes, signature: str, shared_key: str) -> dict:
    if not isinstance(payload, (str, bytes)) or not isinstance(signature, str) or (not isinstance(shared_key, str)):
        raise ValueError('invalid signature')
    try:
        raw = payload.encode('utf-8') if isinstance(payload, str) else payload
        expected = hmac.new(shared_key.encode('utf-8'), raw, hashlib.sha256).hexdigest()
    except (UnicodeEncodeError, TypeError):
        raise ValueError('invalid signature')
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        data = json.loads(raw.decode('utf-8'))
        if not isinstance(data, dict) or not isinstance(data.get('inspections'), list):
            raise ValueError
        as_of = datetime.date.fromisoformat(data['as_of'])
        end = as_of + datetime.timedelta(days=14)
        selected = []
        for item in data['inspections']:
            if not isinstance(item, dict):
                raise ValueError
            fields = ('id', 'district', 'due_date', 'status', 'duration', 'risk')
            if any((field not in item for field in fields)):
                raise ValueError
            if not all((isinstance(item[field], str) for field in ('id', 'district', 'due_date', 'status'))):
                raise ValueError
            if type(item['duration']) is not int or type(item['risk']) is not int:
                raise ValueError
            due = datetime.date.fromisoformat(item['due_date'])
            if item['status'] == 'pending' and as_of <= due <= end:
                selected.append((due, item))
    except (ValueError, TypeError, UnicodeDecodeError, KeyError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    selected.sort(key=lambda pair: (pair[0], -pair[1]['risk'], pair[1]['id']))
    groups = {}
    for due, item in selected:
        groups.setdefault(item['district'], []).append(item)
    districts = []
    for district, items in groups.items():
        districts.append({'district': district, 'count': len(items), 'minutes': sum((item['duration'] for item in items)), 'average_risk': round(sum((item['risk'] for item in items)) / len(items), 2), '_first': min((item['due_date'] for item in items))})
    districts.sort(key=lambda item: (item['_first'], item['district']))
    for item in districts:
        del item['_first']
    return {'total': len(selected), 'by_district': districts, 'priority_ids': [item[1]['id'] for item in selected]}

