import hashlib
import hmac
import io
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def hash_api_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + '$' + digest.hex()

def verify_api_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        salt_hex, digest_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
        expected = bytes.fromhex(digest_hex)
        if len(salt) != 16 or len(expected) != 32:
            return False
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except (ValueError, UnicodeError):
        return False

def _money(value):
    try:
        number = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid monetary value')
    if not number.is_finite() or number < 0 or -number.as_tuple().exponent > 2:
        raise ValueError('invalid monetary value')
    return number.quantize(Decimal('0.01'))

def _formatted(value):
    return format(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP), '.2f')

def actuarial_summary(csv_text: str, secret: str, stored_secret: str) -> dict:
    if not verify_api_secret(secret, stored_secret):
        raise PermissionError('invalid secret')
    if not isinstance(csv_text, str):
        raise ValueError('CSV must be text')
    try:
        rows = list(csv.reader(io.StringIO(csv_text), strict=True))
    except csv.Error as exc:
        raise ValueError('malformed CSV') from exc
    header = ['policy', 'state', 'year', 'paid', 'incurred']
    if not rows or rows[0] != header:
        raise ValueError('incorrect header')
    states = {}
    years = {}
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('wrong field count')
        policy, state, year_text, paid_text, incurred_text = row
        if not policy or len(state) != 2 or (not state.isascii()) or (not state.isupper()) or (not state.isalpha()):
            raise ValueError('invalid row')
        try:
            year = int(year_text)
        except ValueError as exc:
            raise ValueError('invalid year') from exc
        if not 1900 <= year <= 2100 or str(year) != year_text:
            raise ValueError('invalid year')
        paid, incurred = (_money(paid_text), _money(incurred_text))
        if incurred < paid:
            raise ValueError('invalid amounts')
        item = states.setdefault(state, [0, Decimal(0), Decimal(0)])
        item[0] += 1
        item[1] += paid
        item[2] += incurred
        years[year] = years.get(year, Decimal(0)) + incurred
    output_states = {}
    for state in sorted(states):
        count, paid, incurred = states[state]
        ratio = Decimal(0) if paid == 0 else (incurred / paid).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
