    try:
        raw = blob.encode('utf-8') if isinstance(blob, str) else blob
        value = json.loads(raw.decode('utf-8'))
    except (AttributeError, TypeError, UnicodeDecodeError, ValueError) as exc:
        raise ValueError('invalid caseload payload') from exc
    if not isinstance(value, dict):
        raise ValueError('caseload payload must contain a dictionary')
    return value

