import base64
import hashlib
import hmac
import os

def create_account(username: str, department: str, password: str) -> dict:
    if not isinstance(username, str) or not username.strip():
        raise ValueError('invalid username')
    if not isinstance(department, str) or not department.strip():
        raise ValueError('invalid department')
    if not isinstance(password, str) or len(password) < 4:
        raise ValueError('invalid password')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    stored = base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()
    return {'username': username.strip(), 'department': department.strip(), 'password_hash': stored}

def authenticate(account: dict, password: str) -> bool:
    if not isinstance(account, dict) or not isinstance(password, str):
        return False
    value = account.get('password_hash')
    if not isinstance(value, str) or '$' not in value:
        return False
    try:
        salt_text, digest_text = value.split('$', 1)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
    except Exception:
        return False
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def list_directory(accounts: list[dict], department: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(accounts, list):
        raise ValueError('accounts must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError('invalid page')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size < 1:
        raise ValueError('invalid page size')
    selected = [a for a in accounts if department is None or a.get('department') == department]
    selected.sort(key=lambda a: (a.get('username', '').lower(), a.get('username', '')))
    total = len(selected)
    pages = (total + page_size - 1) // page_size
    start = (page - 1) * page_size
    items = [{'username': a['username'], 'department': a['department']} for a in selected[start:start + page_size]]
    return {'total': total, 'pages': pages, 'page': page, 'page_size': page_size, 'items': items}

