import subprocess

def parse_offer(line: str) -> dict:
    fields = line.rstrip('\n').split('\t')
    if len(fields) != 5:
        raise ValueError('invalid offer')
    product, seller, price_text, stock_text, rating_text = fields
    product = product.strip()
    seller = seller.strip()
    if not product or not seller:
        raise ValueError('invalid offer')
    try:
        price = float(price_text.strip())
        stock_float = float(stock_text.strip())
        rating = float(rating_text.strip())
    except ValueError as exc:
        raise ValueError('invalid offer') from exc
    if not price >= 0 or not stock_float.is_integer() or stock_float < 0 or (not 0 <= rating <= 5):
        raise ValueError('invalid offer')
    return {'product': product, 'seller': seller, 'price': price, 'stock': int(stock_float), 'rating': rating}

def compare_prices(paths: list[str], budget: float | None=None, limit: int | None=None) -> list[dict]:
    if budget is not None:
        try:
            budget = float(budget)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid budget') from exc
        if budget < 0:
            raise ValueError('invalid budget')
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('invalid limit')
    if not paths:
        return []
    result = subprocess.run(['cat', *paths], capture_output=True, text=True, check=True)
