def generate_reconciliation_token(length: int=20) -> str:
    if not isinstance(length, int) or isinstance(length, bool) or length < 8:
        raise ValueError('invalid token length')
    return ''.join((secrets.choice(_ALPHABET) for _ in range(length)))

def reconcile_cash(entries: list[dict], page: int=1, page_size: int=10) -> dict:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    totals = {}
    for entry in entries:
        if not isinstance(entry, dict) or set(entry) != {'branch', 'expected_cents', 'counted_cents'}:
            raise ValueError('invalid entry')
        branch = entry['branch']
        expected = entry['expected_cents']
        counted = entry['counted_cents']
        if not isinstance(branch, str) or not branch or (not isinstance(expected, int)) or isinstance(expected, bool) or (expected < 0) or (not isinstance(counted, int)) or isinstance(counted, bool) or (counted < 0):
            raise ValueError('invalid entry')
        if branch not in totals:
            totals[branch] = [0, 0]
        totals[branch][0] += expected
        totals[branch][1] += counted
    rows = []
    for branch in sorted(totals):
        expected, counted = totals[branch]
        difference = counted - expected
        status = 'balanced' if difference == 0 else 'over' if difference > 0 else 'short'
        rows.append({'branch': branch, 'expected_cents': expected, 'counted_cents': counted, 'difference_cents': difference, 'status': status})
