import base64
import hashlib
import hmac
import os

def hash_pin(pin: str) -> str:
    if not isinstance(pin, str):
        raise TypeError('pin must be a string')
    if not pin:
        raise ValueError('pin must not be empty')
    salt = os.urandom(16)
    rounds = 100000
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
    return 'pbkdf2$%d$%s$%s' % (rounds, base64.b64encode(salt).decode(), base64.b64encode(digest).decode())

def verify_pin(stored: str, pin: str) -> bool:
    if not isinstance(stored, str) or not isinstance(pin, str) or (not pin):
        return False
    try:
        kind, count, salt_text, digest_text = stored.split('$', 3)
        if kind != 'pbkdf2':
            return False
        rounds = int(count)
        salt = base64.b64decode(salt_text.encode(), validate=True)
        expected = base64.b64decode(digest_text.encode(), validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, rounds)
        return hmac.compare_digest(actual, expected)
    except (ValueError, TypeError):
        return False

def plan_restock(inventory, sales, as_of, window=7):
    if window < 1:
        raise ValueError('window')
    totals = {name: [0, -1] for name in inventory}
    for name, data in inventory.items():
        if any((key not in data for key in ('stock', 'reorder', 'priority'))):
            raise ValueError('inventory entry')
        if any((type(data[key]) is not int for key in ('stock', 'reorder', 'priority'))):
            raise ValueError('inventory value')
    start = as_of - window + 1
    for sale in sales:
        if not isinstance(sale, tuple) or len(sale) != 3:
            raise ValueError('sale')
        day, name, quantity = sale
        if type(day) is not int or not isinstance(name, str) or type(quantity) is not int:
            raise ValueError('sale value')
        if name in inventory and start <= day <= as_of and (quantity > 0):
            totals[name][0] += quantity
            totals[name][1] = max(totals[name][1], day)
    result = []
    for name, data in inventory.items():
        sold, last = totals[name]
        remaining = data['stock'] - sold
        if remaining <= data['reorder']:
            result.append({'item': name, 'remaining': remaining, 'sold': sold, 'priority': data['priority'], 'last_sale_day': last})
    return sorted(result, key=lambda x: (-x['priority'], x['remaining'], x['item']))

