import json
from datetime import date
_STATUSES = {'RECEIVED', 'IN_PROCESS', 'RELEASED', 'HOLD'}
_FIELDS = {'lot_id', 'product', 'weight_kg', 'status', 'received_date'}

def _validate(records):
    if not isinstance(records, list):
        raise ValueError('records must be a list')
    for record in records:
        if not isinstance(record, dict) or set(record) != _FIELDS:
            raise ValueError('invalid record')
        if not isinstance(record['lot_id'], str) or not record['lot_id']:
            raise ValueError('invalid lot id')
        if not isinstance(record['product'], str) or not record['product']:
            raise ValueError('invalid product')
        if isinstance(record['weight_kg'], bool) or not isinstance(record['weight_kg'], (int, float)) or record['weight_kg'] < 0:
            raise ValueError('invalid weight')
        if record['status'] not in _STATUSES:
            raise ValueError('invalid status')
        if not isinstance(record['received_date'], str):
            raise ValueError('invalid date')
        try:
            date.fromisoformat(record['received_date'])
        except Exception as exc:
            raise ValueError('invalid date') from exc

def encode_lots(records: list[dict]) -> bytes:
    _validate(records)
    try:
        return json.dumps(records, separators=(',', ':')).encode('utf-8')
    except Exception as exc:
        raise ValueError('cannot encode records') from exc

def lot_report(payload: bytes, product: str | None=None, status: str | None=None, page: int=1, page_size: int=10) -> dict:
    if not isinstance(product, (str, type(None))) or not isinstance(status, (str, type(None))):
        raise ValueError('invalid filter')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1 or (not isinstance(page_size, int)) or isinstance(page_size, bool) or (page_size < 1):
        raise ValueError('invalid pagination')
    try:
        records = json.loads(payload.decode('utf-8'))
        _validate(records)
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    chosen = [r for r in records if (product is None or r['product'] == product) and (status is None or r['status'] == status)]
    chosen.sort(key=lambda r: (-date.fromisoformat(r['received_date']).toordinal(), r['lot_id']))
    start = (page - 1) * page_size
    return {'count': len(chosen), 'total_weight_kg': round(sum((r['weight_kg'] for r in chosen)), 2), 'lots': chosen[start:start + page_size]}

