from datetime import datetime
from math import isfinite
from lxml import etree

def parse_manifest(xml_text: str) -> dict:
    if not isinstance(xml_text, str) or not xml_text.strip():
        raise ValueError('invalid XML')
    try:
        root = etree.fromstring(xml_text.encode(), parser=etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False))
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'manifest':
        raise ValueError('invalid root')
    vals = {}
    for key in ('shipment_id', 'facility', 'date'):
        value = root.get(key)
        if value is None or not value.strip():
            raise ValueError('missing manifest attribute')
        vals[key] = value.strip()
    try:
        datetime.strptime(vals['date'], '%Y-%m-%d')
    except ValueError as exc:
        raise ValueError('invalid date') from exc
    items = []
    for child in root:
        if child.tag != 'battery' or len(child):
            raise ValueError('invalid child')
        values = {}
        for key in ('sku', 'chemistry', 'weight_kg', 'count'):
            value = child.get(key)
            if value is None:
                raise ValueError('missing battery attribute')
            values[key] = value.strip()
        if not values['sku'] or not values['chemistry']:
            raise ValueError('empty battery attribute')
        try:
            weight = float(values['weight_kg'])
            count_float = float(values['count'])
            count = int(values['count'])
        except ValueError as exc:
            raise ValueError('invalid number') from exc
        if not isfinite(weight) or weight <= 0 or count_float != count or (count <= 0):
            raise ValueError('invalid number')
        items.append({'sku': values['sku'], 'chemistry': values['chemistry'], 'weight_kg': weight, 'count': count})
    if not items:
        raise ValueError('no batteries')
    vals['items'] = items
    return vals

def build_recycling_plan(xml_documents: list[str], capacity_kg: float) -> list[dict]:
    if not isfinite(capacity_kg) or capacity_kg <= 0:
        raise ValueError('invalid capacity')
    groups = {}
    for order, document in enumerate(xml_documents):
        manifest = parse_manifest(document)
        for item_order, item in enumerate(manifest['items']):
            total = item['weight_kg'] * item['count']
            if total > capacity_kg:
                raise ValueError('item exceeds capacity')
            key = (manifest['facility'], item['chemistry'])
            groups.setdefault(key, []).append((manifest['date'], manifest['shipment_id'], order, item_order, item, total))
    ranked = sorted(groups.items(), key=lambda pair: (-sum((x[5] for x in pair[1])), pair[0][0], pair[0][1]))
    result = []
    for (facility, chemistry), entries in ranked:
        entries.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        batches = []
        for entry in entries:
            if not batches or batches[-1]['weight'] + entry[5] > capacity_kg:
                batches.append({'weight': 0.0, 'count': 0, 'shipments': []})
            batch = batches[-1]
            batch['weight'] += entry[5]
            batch['count'] += entry[4]['count']
            if entry[1] not in batch['shipments']:
                batch['shipments'].append(entry[1])
        for number, batch in enumerate(batches, 1):
            result.append({'facility': facility, 'chemistry': chemistry, 'batch': number, 'weight_kg': round(batch['weight'], 6), 'count': batch['count'], 'shipments': batch['shipments']})
    return result

