from solution import import_fare_batch

import csv
import os
import tempfile
import zipfile


def make_archive(files):
    archive = tempfile.NamedTemporaryFile(suffix=".zip", delete=False)
    archive.close()
    with zipfile.ZipFile(archive.name, "w") as zf:
        for name, content in files.items():
            zf.writestr(name, content)
    return archive.name


def test_aggregates_multiple_files_and_sorts_results():
    archive = make_archive({
        "first.csv": "card_id,fare_cents\nA100,125\nB200,300\nA100,75\n",
        "nested/second.csv": "card_id,fare_cents\nC300,500\nB200,100\n",
        "readme.txt": "not fare data\n",
    })
    try:
        with tempfile.TemporaryDirectory() as output:
            result = import_fare_batch(archive, output)
            assert result == [("C300", 500), ("B200", 400), ("A100", 200)]
            assert os.path.isfile(os.path.join(output, "first.csv"))
            assert os.path.isfile(os.path.join(output, "nested", "second.csv"))
    finally:
        os.unlink(archive)


def test_prefix_filter_and_tie_ordering():
    archive = make_archive({
        "fares.csv": "card_id,fare_cents\nAB2,100\nAB1,100\nZZ9,900\nAB1,50\n"
    })
    try:
        with tempfile.TemporaryDirectory() as output:
            assert import_fare_batch(archive, output, "AB") == [("AB1", 150), ("AB2", 100)]
    finally:
        os.unlink(archive)


def test_empty_archive_and_archive_without_csv():
    archive = make_archive({"notes.txt": "hello", "folder/data.json": "{}"})
    try:
        with tempfile.TemporaryDirectory() as output:
            assert import_fare_batch(archive, output) == []
    finally:
        os.unlink(archive)


def test_zero_fares_and_existing_output_directory():
    archive = make_archive({"fares.csv": "card_id,fare_cents\nCARD,0\n"})
    try:
        with tempfile.TemporaryDirectory() as output:
            with open(os.path.join(output, "old.txt"), "w") as file:
                file.write("old")
            assert import_fare_batch(archive, output) == [("CARD", 0)]
            assert open(os.path.join(output, "old.txt")).read() == "old"
    finally:
        os.unlink(archive)


def test_missing_columns_raise_value_error():
    archive = make_archive({"bad.csv": "card_id,amount\nCARD,10\n"})
    try:
        with tempfile.TemporaryDirectory() as output:
            try:
                import_fare_batch(archive, output)
                assert False
            except ValueError:
                pass
    finally:
        os.unlink(archive)


def test_invalid_rows_raise_value_error():
    cases = [
        "card_id,fare_cents\n,10\n",
        "card_id,fare_cents\nCARD,-1\n",
        "card_id,fare_cents\nCARD,2.5\n",
        "card_id,fare_cents\nCARD,\n",
    ]
    for content in cases:
        archive = make_archive({"bad.csv": content})
        try:
            with tempfile.TemporaryDirectory() as output:
                try:
                    import_fare_batch(archive, output)
                    assert False
                except ValueError:
                    pass
        finally:
            os.unlink(archive)


def test_nested_benign_names_are_extracted_and_processed():
    archive = make_archive({
        "2025/january/card_fares.csv": "card_id,fare_cents\nCARD9,275\n"
    })
    try:
        with tempfile.TemporaryDirectory() as output:
