        raise ValueError('invalid state')
    if any((not isinstance(state[key], str) or not state[key] for key in ('title', 'filmmaker', 'screener_url'))):
        raise ValueError('invalid state')
    if isinstance(state['runtime_minutes'], bool) or not isinstance(state['runtime_minutes'], int) or state['runtime_minutes'] <= 0:
        raise ValueError('invalid state')
    if not isinstance(state['genres'], list) or any((not isinstance(item, str) for item in state['genres'])):
        raise ValueError('invalid state')

def encode_submission_state(state: dict) -> bytes:
    _validate(state)
    return json.dumps(state, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')

def decode_submission_state(blob: bytes) -> dict:
