import datetime
import operator

def evaluate_expression(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval').body
    except SyntaxError as exc:
        raise ValueError('unsupported syntax') from exc

    def walk(node):
        if isinstance(node, ast.Constant) and type(node.value) in (int, float, bool):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise NameError(node.id)
            return variables[node.id]
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub, ast.Not)):
            value = walk(node.operand)
            return +value if isinstance(node.op, ast.UAdd) else -value if isinstance(node.op, ast.USub) else not value
        if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a, b = (walk(node.left), walk(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.BoolOp) and isinstance(node.op, (ast.And, ast.Or)):
            value = walk(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                    return value
                value = walk(child)
            return value
        if isinstance(node, ast.Compare):
            left = walk(node.left)
            for op, right_node in zip(node.ops, node.comparators):
                right = walk(right_node)
                fn = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}.get(type(op))
                if fn is None:
                    raise ValueError('unsupported syntax')
                if not fn(left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [walk(arg) for arg in node.args]
            if node.func.id == 'round' and len(args) in (1, 2):
                return round(*args)
            if node.func.id == 'min' and len(args) >= 2:
                return min(*args)
            if node.func.id == 'max' and len(args) >= 2:
                return max(*args)
        raise ValueError('unsupported syntax')
    return walk(tree)

def schedule_campaign(messages: list[dict], rule: str, variables: dict[str, int | float | bool], daily_limit: int) -> list[dict]:
    if daily_limit < 1:
        raise ValueError('daily_limit')
    seen, selected = (set(), [])
    for message in messages:
        ident = message['id']
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        try:
            moment = datetime.datetime.fromisoformat(message['send_at'])
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid datetime') from exc
        context = dict(variables)
