import json

def _check(items):
    if not isinstance(items, list):
        raise ValueError('contacts must be a list')
    out = []
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str) or (not item['id']) or (not isinstance(item.get('name'), str)):
            raise ValueError('invalid contact')
        row = {'id': item['id'], 'name': item['name']}
        for key in ('email', 'phone', 'company'):
            value = item.get(key, '')
            if not isinstance(value, str):
                raise ValueError('invalid contact')
            row[key] = value
        out.append(row)
    return out

def encode_contacts(contacts: list[dict]) -> bytes:
    return json.dumps({'contacts': _check(contacts)}, separators=(',', ':'), ensure_ascii=False).encode()

def _read(blob):
    try:
        obj = json.loads(blob.decode())
        return _check(obj['contacts']) if isinstance(obj, dict) and set(obj) == {'contacts'} else (_ for _ in ()).throw(ValueError())
    except Exception as exc:
        raise ValueError('invalid state') from exc

def add_contacts(blob: bytes, contacts: list[dict]) -> bytes:
    return encode_contacts(_read(blob) + _check(contacts))

def deduplicate(blob: bytes) -> list[dict]:
    rows = _read(blob)
    parent = list(range(len(rows)))

    def root(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    keys = {}
    for i, row in enumerate(rows):
        values = [('e', row['email'].strip().casefold())] if row['email'].strip() else []
        digits = ''.join((c for c in row['phone'] if c.isdigit()))
        if len(digits) >= 7:
            values.append(('p', digits))
        for key in values:
            if key in keys:
                parent[root(i)] = root(keys[key])
            else:
                keys[key] = i
    groups = {}
    for i in range(len(rows)):
        groups.setdefault(root(i), []).append(rows[i])
    result = []
    for members in groups.values():
        members.sort(key=lambda x: x['id'])
        result.append({'ids': [x['id'] for x in members], 'name': next((x['name'] for x in members if x['name']), ''), 'email': next((x['email'] for x in members if x['email']), ''), 'phone': next((x['phone'] for x in members if x['phone']), ''), 'company': next((x['company'] for x in members if x['company']), ''), 'count': len(members)})
    return sorted(result, key=lambda x: (-x['count'], x['name'].casefold(), x['ids'][0]))

