    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'certificate':
        raise ValueError('invalid root')
    allowed = {'id', 'student', 'course', 'score', 'date', 'honors', 'modules'}
    if any((child.tag not in allowed for child in root)):
        raise ValueError('unexpected element')
    values = {}
    for name in ('id', 'student', 'course', 'score', 'date'):
        node = root.find(name)
        text = None if node is None or node.text is None else node.text.strip()
        if not text:
            raise ValueError('missing field')
        values[name] = text
    try:
        score = int(values['score'])
        if not 0 <= score <= 100:
            raise ValueError
        datetime.date.fromisoformat(values['date'])
    except Exception as exc:
        raise ValueError('invalid field') from exc
    honors_node = root.find('honors')
    honors = False
    if honors_node is not None:
        text = '' if honors_node.text is None else honors_node.text.strip().lower()
        if text not in {'true', 'yes', '1', 'false', 'no', '0'}:
            raise ValueError('invalid honors')
        honors = text in {'true', 'yes', '1'}
    modules_node = root.find('modules')
    modules = []
    seen = set()
    if modules_node is not None:
        if modules_node.attrib or (modules_node.text and modules_node.text.strip()):
            raise ValueError('invalid modules')
        for node in modules_node:
            if node.tag != 'module' or (node.text and node.text.strip()):
                raise ValueError('invalid module')
            code = node.attrib.get('code', '').strip()
            title = node.attrib.get('title', code).strip()
            raw_hours = node.attrib.get('hours', '').strip()
            if not code or not title or code in seen:
                raise ValueError('invalid module')
            try:
                hours = int(raw_hours)
                if hours <= 0:
                    raise ValueError
            except Exception as exc:
                raise ValueError('invalid hours') from exc
            seen.add(code)
            modules.append({'code': code, 'title': title, 'hours': hours})
    return {'id': values['id'], 'student': values['student'], 'course': values['course'], 'score': score, 'date': values['date'], 'honors': honors, 'modules': modules, 'total_hours': sum((x['hours'] for x in modules))}

def issue_certificates(xml_documents: list[str | bytes], passing_score: int=70) -> list[dict]:
    if isinstance(passing_score, bool) or not isinstance(passing_score, int) or (not 0 <= passing_score <= 100):
        raise ValueError('invalid passing score')
    parsed = []
    seen = set()
    for document in xml_documents:
        certificate = parse_certificate(document)
        if certificate['id'] in seen:
            raise ValueError('duplicate certificate')
        seen.add(certificate['id'])
        if certificate['score'] >= passing_score:
            parsed.append(certificate)
    parsed.sort(key=lambda x: (-x['score'], not x['honors'], x['date'], x['student'].casefold(), x['id']))
    return [{'rank': index, 'certificate': certificate} for index, certificate in enumerate(parsed, 1)]

