import pytest


def test_round_trip_empty_batch():
    records = []
    assert decode_search_batch(encode_search_batch(records)) == records


def test_round_trip_preserves_order_and_values():
    records = [
        {
            "id": "doc-2",
            "title": "Second",
            "content": "Résumé and 東京",
            "metadata": {"department": "finance", "lang": "fr"},
        },
        {
            "id": "doc-1",
            "title": "First",
            "content": "Body",
            "metadata": {},
        },
    ]
    assert decode_search_batch(encode_search_batch(records)) == records


def test_round_trip_allows_empty_strings():
    records = [{"id": "", "title": "", "content": "", "metadata": {"x": ""}}]
    assert decode_search_batch(encode_search_batch(records)) == records


def test_encoded_payload_is_bytes():
    records = [{"id": "a", "title": "b", "content": "c", "metadata": {}}]
    payload = encode_search_batch(records)
    assert isinstance(payload, bytes)
    assert decode_search_batch(payload) == records


def test_encode_rejects_invalid_records():
    invalid = [
        None,
        [{"id": "a"}],
        [{"id": 1, "title": "b", "content": "c", "metadata": {}}],
        [{"id": "a", "title": "b", "content": "c", "metadata": {"n": 3}}],
        [{"id": "a", "title": "b", "content": "c", "metadata": {}, "extra": "x"}],
    ]
    for value in invalid:
        with pytest.raises(ValueError):
            encode_search_batch(value)


def test_decode_rejects_malformed_payload():
    for payload in (b"", b"not a batch", b"[1, 2, 3]", b"{}"):
        with pytest.raises(ValueError):
            decode_search_batch(payload)


def test_decode_rejects_validly_encoded_wrong_shape():
    with pytest.raises(ValueError):
        decode_search_batch(encode_search_batch([]) + b"extra")


def test_decode_requires_bytes():
    with pytest.raises(ValueError):
        decode_search_batch("not bytes")

