        if not all((isinstance(record[key], str) for key in ('id', 'title', 'content'))):
            raise ValueError('invalid document')
        metadata = record['metadata']
        if not isinstance(metadata, dict) or not all((isinstance(k, str) and isinstance(v, str) for k, v in metadata.items())):
            raise ValueError('invalid metadata')

def encode_search_batch(records: list[dict[str, object]]) -> bytes:
    _validate(records)
    return pickle.dumps(records, protocol=4)

def decode_search_batch(payload: bytes) -> list[dict[str, object]]:
    if not isinstance(payload, bytes):
        raise ValueError('payload must be bytes')
    try:
        records = pickle.loads(payload)
        if pickle.dumps(records, protocol=4) != payload:
            raise ValueError('invalid payload')
    except Exception as exc:
        raise ValueError('invalid payload') from exc
    _validate(records)
    return records

