from lxml import etree

def load_requests(xml_text: str) -> list[dict]:
    parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
    try:
        root = etree.fromstring(xml_text.encode(), parser)
    except (etree.XMLSyntaxError, ValueError, TypeError) as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'office':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for child in root:
        if child.tag != 'employee':
            raise ValueError('invalid child')
        for name in ('id', 'team', 'priority', 'zone'):
            if name not in child.attrib:
                raise ValueError('missing attribute')
        ident = child.attrib['id'].strip()
        team = child.attrib['team'].strip()
        zone = child.attrib['zone'].strip()
        if not ident or not team or (not zone) or (ident in seen):
            raise ValueError('invalid employee')
        try:
            priority = int(child.attrib['priority'].strip(), 10)
        except (ValueError, AttributeError) as exc:
            raise ValueError('invalid priority') from exc
        requests = list(child)
        if any((node.tag != 'request' for node in requests)) or len(requests) > 1:
            raise ValueError('invalid request')
        requested = None
        if requests:
            if 'desk' not in requests[0].attrib:
                raise ValueError('missing desk')
            requested = requests[0].attrib['desk'].strip()
            if not requested:
                raise ValueError('invalid desk')
        seen.add(ident)
        result.append({'id': ident, 'team': team, 'priority': priority, 'zone': zone, 'requested_desk': requested})
    return result

def assign_seats(xml_text: str, available_desks: dict[str, str]) -> dict[str, str | None]:
    employees = load_requests(xml_text)
    ordered = sorted(employees, key=lambda x: (-x['priority'], x['team'], x['id']))
    free = set(available_desks)
    result = {}
    for employee in ordered:
        wanted = employee['requested_desk']
        if wanted in free and available_desks[wanted] == employee['zone']:
            chosen = wanted
        else:
            choices = sorted((desk for desk in free if available_desks[desk] == employee['zone']))
            chosen = choices[0] if choices else None
        result[employee['id']] = chosen
        if chosen is not None:
            free.remove(chosen)
    return result

def allocation_summary(assignments: dict[str, str | None], available_desks: dict[str, str]) -> dict[str, object]:
    counts = {zone: 0 for zone in sorted(set(available_desks.values()))}
    assigned = 0
    for desk in assignments.values():
        if desk is None:
            continue
        if not isinstance(desk, str) or desk not in available_desks:
            raise ValueError('unknown desk')
        assigned += 1
        counts[available_desks[desk]] += 1
    return {'assigned': assigned, 'unassigned': len(assignments) - assigned, 'by_zone': counts}

