import ast
import operator

def _evaluate(text, variables):
    tree = ast.parse(text, mode='eval').body

    def visit(node):
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            if node.id in ('min', 'max', 'round'):
                return node.id
            raise NameError(node.id)
        if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
            a, b = (visit(node.left), visit(node.right))
            return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](a, b)
        if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
            value = visit(node.operand)
            return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
        if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
            value = visit(node.values[0])
            for child in node.values[1:]:
                if isinstance(node.op, ast.And) and (not value):
                    return value
                if isinstance(node.op, ast.Or) and value:
                    return value
                value = visit(child)
            return value
        if isinstance(node, ast.Compare):
            left = visit(node.left)
            for op, child in zip(node.ops, node.comparators):
                right = visit(child)
                if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                    return False
                left = right
            return True
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
            args = [visit(x) for x in node.args]
            return {'min': min, 'max': max, 'round': round}[node.func.id](*args)
        raise ValueError('invalid expression')
    try:
        return visit(tree)
    except (SyntaxError, TypeError, ZeroDivisionError):
        raise ValueError('invalid expression')

def rank_snapshots(snapshots: list[dict], filter_expr: str, score_expr: str, window: int) -> list[dict]:
    if window < 1:
        raise ValueError('window')
    selected = []
    for snap in snapshots:
        if not isinstance(snap, dict) or set(snap) != {'id', 'timestamp', 'size', 'changed'} or (not isinstance(snap['id'], str)) or (not isinstance(snap['timestamp'], int)) or isinstance(snap['timestamp'], bool) or (not isinstance(snap['size'], int)) or isinstance(snap['size'], bool) or (snap['size'] < 0) or (not isinstance(snap['changed'], int)) or isinstance(snap['changed'], bool) or (snap['changed'] < 0):
            raise ValueError('snapshot')
        env = {k: snap[k] for k in ('id', 'timestamp', 'size', 'changed')}
        if _evaluate(filter_expr, env):
            score = _evaluate(score_expr, env)
            if isinstance(score, bool) or not isinstance(score, (int, float)):
                raise ValueError('score')
            selected.append((score, snap))
    selected.sort(key=lambda x: (-x[0], -x[1]['timestamp'], x[1]['id']))
    result = []
    for i, (score, snap) in enumerate(selected):
        total = sum((x[1]['changed'] for x in selected[max(0, i - window + 1):i + 1]))
        result.append({'id': snap['id'], 'timestamp': snap['timestamp'], 'size': snap['size'], 'changed': snap['changed'], 'score': score, 'window_changed': total})
    return result

