import ast
import operator

def _evaluate(text, variables):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and isinstance(node.value, (int, float, bool)):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in variables:
                    raise ValueError()
                return variables[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](visit(node.left), visit(node.right))
            if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](visit(node.operand))
            if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
                value = visit(node.values[0])
                for item in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                        return value
                    value = visit(item)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, part in zip(node.ops, node.comparators):
                    right = visit(part)
                    if type(op) not in (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE):
                        raise ValueError()
                    if not {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*[visit(arg) for arg in node.args])
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def rank_registrations(registrations: list[dict], rule: str, score_formula: str, page: int=1, page_size: int=10) -> list[dict]:
    if page < 1 or page_size < 1:
        raise ValueError()
    ranked = []
    for index, registration in enumerate(registrations):
        variables = {key: registration[key] for key in ('experience', 'sessions', 'remote', 'fee')}
        matched = _evaluate(rule, variables)
        if not isinstance(matched, bool):
            raise ValueError()
        if not matched:
            continue
        score = _evaluate(score_formula, variables)
        if isinstance(score, bool) or not isinstance(score, (int, float)):
            raise ValueError()
        ranked.append((score, registration['name'], index))
    ranked.sort(key=lambda item: (-item[0], item[1], item[2]))
    start = (page - 1) * page_size
    return [{'name': name, 'score': round(score, 2)} for score, name, _ in ranked[start:start + page_size]]

