                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max')) and (not node.keywords) and (len(node.args) >= 2):
                args = [visit(x) for x in node.args]
                return min(args) if node.func.id == 'min' else max(args)
            raise ValueError('invalid expression')
        return visit(tree)
    except (SyntaxError, NameError, KeyError, TypeError, ZeroDivisionError, ValueError, IndexError):
        raise ValueError('invalid expression')

def aggregate_events(events: list[dict], filter_expression: str, score_expression: str, limit: int=10, offset: int=0) -> list[dict]:
    if not isinstance(limit, int) or isinstance(limit, bool) or (not isinstance(offset, int)) or isinstance(offset, bool) or (limit < 0) or (offset < 0):
        raise ValueError('invalid pagination')
