import csv
import datetime
import os
import tempfile

def _check_int(value):
    return isinstance(value, int) and (not isinstance(value, bool)) and (value >= 0)

def compute_bills(members: list[dict], visits: list[dict], month: str) -> list[dict]:
    try:
        year, mon = map(int, month.split('-'))
        if len(month) != 7 or month[4] != '-' or (not 1 <= mon <= 12):
            raise ValueError
        datetime.date(year, mon, 1)
    except Exception:
        raise ValueError('invalid month')
    data = {}
    for m in members:
        if not isinstance(m.get('member_id'), str) or not m['member_id'] or m['member_id'] in data or (not isinstance(m.get('name'), str)):
            raise ValueError('invalid member')
        if any((not _check_int(m.get(k)) for k in ('plan_cents', 'included_visits', 'overage_cents'))):
            raise ValueError('invalid member')
        data[m['member_id']] = m
    counts = {key: 0 for key in data}
    for v in visits:
        if v.get('member_id') not in data or not _check_int(v.get('visits')) or (not isinstance(v.get('date'), str)):
            raise ValueError('invalid visit')
        try:
            day = datetime.date.fromisoformat(v['date'])
        except Exception:
            raise ValueError('invalid visit')
        if day.strftime('%Y-%m') == month:
            counts[v['member_id']] += v['visits']
    result = []
    for key, m in data.items():
        extra = max(0, counts[key] - m['included_visits'])
        charge = extra * m['overage_cents']
        result.append({'member_id': key, 'name': m['name'], 'base_cents': m['plan_cents'], 'overage_visits': extra, 'overage_cents': charge, 'total_cents': m['plan_cents'] + charge})
    return sorted(result, key=lambda x: (-x['total_cents'], x['member_id']))

def export_bills(members: list[dict], visits: list[dict], month: str, destination: str) -> int:
    bills = compute_bills(members, visits, month)
    parent = os.path.dirname(os.path.abspath(destination))
    fd, temp = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            writer = csv.DictWriter(f, fieldnames=['member_id', 'name', 'base_cents', 'overage_visits', 'overage_cents', 'total_cents'])
            writer.writeheader()
            writer.writerows(bills)
        os.replace(temp, destination)
    except Exception:
        try:
            os.unlink(temp)
        except OSError:
            pass
        raise
    return len(bills)

