        return eval(rule, {'__builtins__': {}}, {**values, 'min': min, 'max': max, 'round': round})
    except Exception as exc:
        raise ValueError('invalid rule') from exc

def dispatch_work_orders(work_orders: list[dict], rule: str, limit: int) -> list[dict]:
    if limit < 0:
        raise ValueError('negative limit')
    if limit == 0:
        return []
    selected = []
    for order in work_orders:
        values = {key: order[key] for key in ('id', 'priority', 'duration', 'due', 'station')}
        if _evaluate(rule, values):
            selected.append(order)
    selected.sort(key=lambda x: (x['due'], -x['priority'], x['duration'], x['id']))
    return selected[:limit]

