        raise ValueError('visitors must be a list')
    if isinstance(page, bool) or not isinstance(page, int) or isinstance(page_size, bool) or (not isinstance(page_size, int)):
        raise ValueError('invalid pagination')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    required = ('id', 'name', 'company', 'priority', 'checked_in')
    checked = []
    for visitor in visitors:
        if not isinstance(visitor, dict) or any((key not in visitor for key in required)):
