        if visitor['checked_in']:
            checked.append(visitor)
    checked.sort(key=lambda v: (v['company'].casefold(), -v['priority'], v['name'].casefold(), v['id']))
    start = (page - 1) * page_size
    selected = checked[start:start + page_size]
    if not selected:
        return []
    base = Path(base_dir).resolve()
    base.mkdir(parents=True, exist_ok=True)
    result = []
    for visitor in selected:
