import csv
import io
import os
import tempfile
from decimal import Decimal, InvalidOperation
_HEADER = ['id', 'farmer', 'region', 'crop', 'hectares', 'requested', 'status']
_STATUSES = {'approved', 'pending', 'rejected'}

def parse_applications(data: str) -> list[dict]:
    if not isinstance(data, str):
        raise ValueError('data must be text')
    rows = list(csv.reader(io.StringIO(data, newline='')))
    if not rows or rows[0] != _HEADER:
        raise ValueError('invalid header')
    result = []
    seen = set()
    for row in rows[1:]:
        if not row or all((x == '' for x in row)):
            continue
        if len(row) != len(_HEADER):
            raise ValueError('invalid row')
        ident, farmer, region, crop, hectares, requested, status = row
        status = status.strip()
        if not ident or not farmer or (not region) or (not crop) or (ident in seen):
            raise ValueError('invalid identity')
        try:
            h = Decimal(hectares.strip())
            amount = Decimal(requested.strip())
        except (InvalidOperation, ValueError):
            raise ValueError('invalid number')
        if not h.is_finite() or h <= 0 or (not amount.is_finite()) or (amount < 0):
            raise ValueError('invalid number')
        if -amount.as_tuple().exponent > 2:
            raise ValueError('too many decimals')
        if status not in _STATUSES:
            raise ValueError('invalid status')
        seen.add(ident)
        result.append({'id': ident, 'farmer': farmer, 'region': region, 'crop': crop, 'hectares': h, 'requested': amount, 'status': status})
    return result

def _decimal_text(value):
    return format(value.normalize(), 'f')

def build_report(applications: list[dict]) -> str:
    groups = {}
    for item in applications:
        key = (item['region'], item['crop'])
        if key not in groups:
            groups[key] = [0, Decimal('0'), Decimal('0')]
        group = groups[key]
        group[0] += 1
        group[1] += item['hectares']
        if item['status'] == 'approved':
            group[2] += item['requested']
    output = io.StringIO(newline='')
    writer = csv.writer(output, lineterminator='\n')
    writer.writerow(['region', 'crop', 'applications', 'hectares', 'approved_amount'])
    for (region, crop), (count, hectares, amount) in sorted(groups.items()):
        writer.writerow([region, crop, count, _decimal_text(hectares), format(amount, '.2f')])
    return output.getvalue()

def write_report(applications: list[dict], destination: str) -> str:
    content = build_report(applications)
    directory = os.path.dirname(os.path.abspath(destination))
    fd, temporary = tempfile.mkstemp(prefix='.subsidy-', dir=directory, text=True)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as handle:
            fd = None
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
        temporary = None
        return content
    finally:
        if fd is not None:
            os.close(fd)
        if temporary is not None:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass

