    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be a positive integer')
    active = []
    groups = {}
    for record in records:
        if not isinstance(record, dict):
            raise ValueError('record must be a dictionary')
        required = {'id', 'name', 'segment', 'revenue_cents', 'active'}
        if set(record) != required:
            raise ValueError('record has invalid fields')
        if isinstance(record['id'], bool) or not isinstance(record['id'], int) or record['id'] <= 0 or (not isinstance(record['name'], str)) or (not record['name']) or (not isinstance(record['segment'], str)) or (not record['segment']) or isinstance(record['revenue_cents'], bool) or (not isinstance(record['revenue_cents'], int)) or (record['revenue_cents'] < 0) or (not isinstance(record['active'], bool)):
