    by_segment.sort(key=lambda x: (-x['revenue_cents'], x['segment']))
    start = (page - 1) * page_size
    data = {'customers': active[start:start + page_size], 'total_count': len(active), 'total_revenue_cents': sum((item['revenue_cents'] for item in active)), 'by_segment': by_segment, 'page': page, 'page_size': page_size}
    key = os.environ.get('CRM_REPORT_SIGNING_KEY')
