            raise ValueError('negative quantity')
    for request in requests:
        if request['need'] < 0:
            raise ValueError('negative need')
    remaining = {offer['id']: offer['quantity'] for offer in offers}
    result = []
    ordered = sorted(requests, key=lambda r: (-r['priority'], r['distance'], r['id']))
    for request in ordered:
        need = request['need']
        matching = sorted((o for o in offers if o['item'] == request['item']), key=lambda o: (o['expires'], o['id']))
