def summarize_reservations(xml: str, as_of: str, page: int=1, page_size: int=10) -> list[dict[str, object]]:
    if page <= 0 or page_size <= 0:
        raise ValueError('page values must be positive')
    try:
        cutoff = date.fromisoformat(as_of)
        root = ET.fromstring(xml)
    except Exception as exc:
        raise ValueError('invalid input') from exc
    groups = {}
    for node in root.findall('reservation'):
        required = ('customer', 'check_in', 'check_out', 'status', 'price_per_day')
        if any((name not in node.attrib for name in required)):
            raise ValueError('missing attribute')
        try:
