    if isinstance(budget, bool) or not isinstance(budget, (int, float)) or budget < 0:
        raise ValueError('invalid budget')
    seen = set()
    checked = []
    required = ('id', 'gpa', 'income', 'need', 'submitted')
    for app in applications:
        if not isinstance(app, dict) or any((key not in app for key in required)):
            raise ValueError('invalid application')
        ident = app['id']
        if not isinstance(ident, str) or not ident or ident != ident.strip():
            raise ValueError('invalid id')
        if ident in seen:
            raise ValueError('duplicate id')
        seen.add(ident)
        if isinstance(app['submitted'], bool) is False:
            raise ValueError('invalid submitted value')
        for key in ('gpa', 'income', 'need'):
            value = app[key]
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError('invalid numeric value')
        if not 0 <= app['gpa'] <= 4 or app['income'] < 0 or app['need'] <= 0:
            raise ValueError('invalid application values')
        checked.append(app)
    eligible = []
    for app in checked:
        if app['submitted'] and app['gpa'] >= 2.5 and (app['income'] <= 120000):
            score = round(app['gpa'] * 25 + max(0, (100000 - app['income']) / 10000) * 5 + app['need'] / 1000, 6)
            eligible.append((score, app))
    eligible.sort(key=lambda pair: (-pair[0], pair[1]['id']))
    result = []
    remaining = budget
    for score, app in eligible:
        if remaining <= 0:
            break
        award = round(min(app['need'], remaining), 2)
        if award <= 0:
            break
        result.append({'id': app['id'], 'score': score, 'award': award, 'invite_code': generate_invite_code()})
        remaining -= award
    return result

