from datetime import date

def _amount(value):
    if not isinstance(value, str) or not re.fullmatch('(?:0|[1-9]\\d*)(?:\\.\\d{1,2})?', value):
        raise ValueError('invalid amount')
    whole, _, frac = value.partition('.')
    return int(whole) * 100 + int((frac + '00')[:2])

def verify_webhook(body: str, authorization: str, secrets: dict[str, bytes]) -> list[dict]:
    try:
        obj = json.loads(body)
    except Exception as exc:
        raise ValueError('invalid json') from exc
    if not isinstance(obj, dict) or obj.get('version') != 1 or (not isinstance(obj.get('events'), list)):
        raise ValueError('invalid document')
    if not isinstance(authorization, str) or authorization.count(':') != 1:
        raise ValueError('invalid authorization')
    kid, digest = authorization.split(':')
    if not kid or not re.fullmatch('[0-9a-fA-F]{64}', digest) or kid not in secrets:
        raise ValueError('invalid authorization')
    canonical = json.dumps(obj, sort_keys=True, separators=(',', ':')).encode()
    expected = hmac.new(secrets[kid], canonical, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, digest.lower()):
        raise ValueError('invalid digest')
    result = []
    for raw in obj['events']:
        if not isinstance(raw, dict) or not isinstance(raw.get('id'), str) or (not raw['id']) or (not isinstance(raw.get('supplier'), str)) or (not raw['supplier']):
            raise ValueError('invalid event')
        if not isinstance(raw.get('revision'), int) or isinstance(raw['revision'], bool) or raw['revision'] < 0:
            raise ValueError('invalid revision')
        if raw.get('currency') is None or not re.fullmatch('[A-Z]{3}', raw['currency']):
            raise ValueError('invalid currency')
        if raw.get('status') not in {'awarded', 'active', 'closed'}:
            raise ValueError('invalid status')
        try:
            date.fromisoformat(raw['effective_date'])
        except Exception as exc:
            raise ValueError('invalid date') from exc
        result.append({'id': raw['id'], 'revision': raw['revision'], 'supplier': raw['supplier'], 'amount_cents': _amount(raw.get('amount')), 'currency': raw['currency'], 'status': raw['status'], 'effective_date': raw['effective_date']})
    return result

def summarize_contracts(events: list[dict]) -> list[dict]:
    chosen = {}
    for event in events:
        if not isinstance(event, dict) or not all((k in event for k in ('id', 'revision', 'supplier', 'amount_cents', 'status'))):
            raise ValueError('invalid event')
        if not isinstance(event['amount_cents'], int) or event['amount_cents'] < 0 or event['status'] not in {'awarded', 'active', 'closed'}:
            raise ValueError('invalid event')
        old = chosen.get(event['id'])
        if old is None or event['revision'] >= old['revision']:
            chosen[event['id']] = event
    grouped = {}
    for event in chosen.values():
        row = grouped.setdefault(event['supplier'], {'supplier': event['supplier'], 'contract_count': 0, 'total_cents': 0, 'open_count': 0})
        row['contract_count'] += 1
        row['total_cents'] += event['amount_cents']
        row['open_count'] += event['status'] in {'awarded', 'active'}
    return sorted(grouped.values(), key=lambda x: (-x['total_cents'], x['supplier']))

