        w.writerow(['outlet', 'journalist', 'email', 'beats', 'priority'])
        for x in rows:
            w.writerow([x['outlet'], x['journalist'], x['email'], x['beats'], x['priority']])
    else:
        b.write(json.dumps([{k: x[k] for k in ('outlet', 'journalist', 'email', 'beats', 'priority')} for x in rows], indent=2) + '\n')
