    fd, t = tempfile.mkstemp(dir=parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8', newline='') as f:
            f.write(b.getvalue())
        os.replace(t, destination)
    finally:
        if os.path.exists(t):
            os.unlink(t)
    return len(rows)

