from solution import verify_and_process
import hashlib
import hmac
import json
import pytest


def signed(body, secret=b"recruiting-key"):
    return "sha256=" + hmac.new(secret, body, hashlib.sha256).hexdigest()


def make(events):
    return json.dumps({"events": events}, separators=(",", ":")).encode()


def event(eid, applicant, stage, score, when):
    return {"id": eid, "applicant": applicant, "stage": stage, "score": score, "occurred_at": when}


def test_accepts_signature_and_applies_sorted_events():
    body = make([
        event("b", "Zoe", "offer", 88, 20),
        event("a", "Zoe", "interview", 72, 10),
        event("c", "Mia", "interview", 88, 20),
    ])
    state = {"secret": b"recruiting-key", "seen": set(), "applicants": {}}
    result = verify_and_process(body, signed(body), state)
    assert result == [
        {"applicant": "Mia", "stage": "interview", "score": 88, "occurred_at": 20, "event_id": "c"},
        {"applicant": "Zoe", "stage": "offer", "score": 88, "occurred_at": 20, "event_id": "b"},
    ]
    assert state["seen"] == {"a", "b", "c"}
    assert state["applicants"]["Zoe"]["event_id"] == "b"


def test_duplicate_ids_are_ignored_across_calls():
    state = {"secret": "abc", "seen": set(), "applicants": {}}
    first = make([event("x", "Ana", "interview", 80, 4)])
    assert verify_and_process(first, signed(first, b"abc"), state)[0]["score"] == 80
    second = make([event("x", "Ana", "offer", 99, 9), event("y", "Bob", "offer", 70, 2)])
    assert verify_and_process(second, signed(second, b"abc"), state) == [
        {"applicant": "Ana", "stage": "interview", "score": 80, "occurred_at": 4, "event_id": "x"},
        {"applicant": "Bob", "stage": "offer", "score": 70, "occurred_at": 2, "event_id": "y"},
    ]


def test_later_and_tied_events_replace_records_correctly():
    state = {"secret": b"k", "seen": set(), "applicants": {}}
    body = make([
        event("z", "A", "offer", 75, 5),
        event("a", "A", "interview", 71, 5),
        event("q", "A", "rejected", 100, 4),
        event("b", "A", "interview", 72, 6),
    ])
    assert verify_and_process(body, signed(body, b"k"), state) == [{
        "applicant": "A", "stage": "interview", "score": 72, "occurred_at": 6, "event_id": "b"
    }]
    assert state["applicants"]["A"]["event_id"] == "b"


def test_rejected_and_low_score_records_are_excluded():
    body = make([
        event("1", "A", "rejected", 100, 1),
        event("2", "B", "interview", 69, 2),
        event("3", "C", "offer", 70, 3),
    ])
    state = {"secret": "s", "seen": set(), "applicants": {}}
    assert verify_and_process(body, signed(body, b"s"), state) == [{
        "applicant": "C", "stage": "offer", "score": 70, "occurred_at": 3, "event_id": "3"
    }]


def test_bad_signature_does_not_mutate_state():
    body = make([event("x", "A", "offer", 90, 1)])
    state = {"secret": b"right", "seen": set(), "applicants": {}}
    with pytest.raises(ValueError):
        verify_and_process(body, "sha256=" + "0" * 64, state)
    assert state == {"secret": b"right", "seen": set(), "applicants": {}}


def test_malformed_payload_and_events_are_rejected_without_mutation():
    state = {"secret": b"k", "seen": set(), "applicants": {}}
    bad_bodies = [
        b"not json",
        json.dumps({"events": {}}).encode(),
        make([event("x", "A", "unknown", 50, 1)]),
        make([event("x", "A", "offer", True, 1)]),
        make([event("x", "A", "offer", 50, -1)]),
        make([{"id": "x", "applicant": "A", "stage": "offer", "score": 50}]),
    ]
    for body in bad_bodies:
        with pytest.raises(ValueError):
            verify_and_process(body, signed(body, b"k"), state)
        assert state["seen"] == set()
        assert state["applicants"] == {}


def test_signature_format_and_secret_type_errors():
    body = make([])
    state = {"secret": b"k", "seen": set(), "applicants": {}}
    for sig in ["", "sha256=", "sha256=" + "A" * 64, "md5=" + "0" * 32]:
        with pytest.raises(ValueError):
            verify_and_process(body, sig, state)
    bad_state = {"secret": 12, "seen": set(), "applicants": {}}
    with pytest.raises(ValueError):
        verify_and_process(body, signed(body, b"k"), bad_state)

