import hashlib
import hmac
import json

def verify_and_process(body: bytes, signature: str, state: dict) -> list[dict]:
    try:
        secret = state['secret']
        seen = state['seen']
        applicants = state['applicants']
    except (KeyError, TypeError):
        raise ValueError('invalid state')
    if isinstance(secret, str):
        secret = secret.encode()
    elif not isinstance(secret, bytes):
        raise ValueError('invalid state')
    if not isinstance(signature, str) or len(signature) != 71 or (not signature.startswith('sha256=')):
        raise ValueError('invalid signature')
    expected = 'sha256=' + hmac.new(secret, body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        parsed = json.loads(body.decode('utf-8'))
        events = parsed['events']
    except (UnicodeDecodeError, json.JSONDecodeError, KeyError, TypeError):
        raise ValueError('invalid payload')
    if not isinstance(parsed, dict) or not isinstance(events, list):
        raise ValueError('invalid payload')
    checked = []
    for e in events:
        if not isinstance(e, dict):
            raise ValueError('invalid event')
        if any((not isinstance(e.get(k), str) or not e[k] for k in ('id', 'applicant', 'stage'))):
            raise ValueError('invalid event')
        if e['stage'] not in {'phone', 'interview', 'offer', 'rejected'}:
            raise ValueError('invalid event')
        if isinstance(e.get('score'), bool) or not isinstance(e.get('score'), int) or (not 0 <= e['score'] <= 100):
            raise ValueError('invalid event')
        if isinstance(e.get('occurred_at'), bool) or not isinstance(e.get('occurred_at'), int) or e['occurred_at'] < 0:
            raise ValueError('invalid event')
        checked.append(e)
    for e in sorted(checked, key=lambda x: (x['occurred_at'], x['id'])):
        if e['id'] in seen:
            continue
        seen.add(e['id'])
        old = applicants.get(e['applicant'])
        if old is None or (e['occurred_at'], e['id']) > (old['occurred_at'], old['event_id']):
            applicants[e['applicant']] = {'stage': e['stage'], 'score': e['score'], 'occurred_at': e['occurred_at'], 'event_id': e['id']}
    result = []
    for name, r in applicants.items():
        if r['stage'] in {'interview', 'offer'} and r['score'] >= 70:
            result.append({'applicant': name, **r})
    return sorted(result, key=lambda x: (-x['score'], x['applicant'], -x['occurred_at'], x['event_id']))

