import json
import os
from datetime import date

def _path(base_dir: str, relative_name: str) -> str:
    if not isinstance(relative_name, str) or not relative_name:
        raise ValueError('invalid path')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, candidate]) != base or os.path.isabs(relative_name):
        raise ValueError('invalid path')
    return candidate

def schedule_deliveries(deliveries: list[dict], daily_capacity: int) -> dict[str, list[dict]]:
    if isinstance(daily_capacity, bool) or not isinstance(daily_capacity, int) or daily_capacity <= 0:
        raise ValueError('invalid capacity')
    grouped = {}
    seen = set()
    for item in deliveries:
        if not isinstance(item, dict):
            raise ValueError('invalid delivery')
        required = ('household', 'zone', 'day', 'priority', 'boxes')
        if any((key not in item for key in required)):
            raise ValueError('invalid delivery')
        household, zone, day = (item['household'], item['zone'], item['day'])
        priority, boxes = (item['priority'], item['boxes'])
        if not isinstance(household, str) or not household or (not isinstance(zone, str)) or (not zone):
            raise ValueError('invalid delivery')
        if not isinstance(day, str):
            raise ValueError('invalid date')
        try:
            parsed = date.fromisoformat(day)
        except ValueError:
            raise ValueError('invalid date')
        if parsed.isoformat() != day:
            raise ValueError('invalid date')
        if isinstance(priority, bool) or not isinstance(priority, int) or (not 0 <= priority <= 9):
            raise ValueError('invalid priority')
        if isinstance(boxes, bool) or not isinstance(boxes, int) or boxes <= 0:
            raise ValueError('invalid boxes')
        key = (day, household)
        if key in seen:
            raise ValueError('duplicate household')
        seen.add(key)
        grouped.setdefault(day, []).append((household, zone, priority, boxes))
    result = {}
    for day in sorted(grouped):
        remaining = daily_capacity
        rows = []
        for household, zone, priority, boxes in sorted(grouped[day], key=lambda x: (-x[2], x[1], x[0])):
            allocated = min(boxes, remaining)
            remaining -= allocated
            status = 'scheduled' if allocated == boxes else 'partial' if allocated else 'waitlist'
            rows.append({'household': household, 'zone': zone, 'priority': priority, 'boxes': boxes, 'allocated': allocated, 'status': status})
        result[day] = rows
    return result

def save_schedule(base_dir: str, relative_name: str, schedule: dict[str, list[dict]]) -> None:
    path = _path(base_dir, relative_name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as handle:
        json.dump(schedule, handle, indent=2)
        handle.write('\n')

def load_schedule(base_dir: str, relative_name: str) -> dict[str, list[dict]]:
    path = _path(base_dir, relative_name)
    with open(path, encoding='utf-8') as handle:
        return json.load(handle)

