    if not events:
        return {}
    cid = events[0]['consent_id']
    identity = (events[0]['tenant'], events[0]['subject_id'])
    chosen = {}
    for event in events:
        if event['consent_id'] != cid or (event['tenant'], event['subject_id']) != identity:
            raise ValueError('inconsistent consent')
