    except ValueError:
        raise ValueError('invalid timestamp')
    if parsed.tzinfo != timezone.utc:
        raise ValueError('invalid timestamp')
    return parsed

def parse_incidents(report: str) -> list[dict[str, str]]:
    if not isinstance(report, str) or not report.strip():
        raise ValueError('empty report')
    try:
        records = list(csv.reader(report.splitlines(), strict=True))
    except csv.Error as exc:
        raise ValueError('invalid csv') from exc
    records = [row for row in records if any((field.strip() for field in row))]
    if not records or records[0] != ['timestamp', 'vessel', 'severity', 'category']:
        raise ValueError('invalid header')
    result = []
    allowed = {'low', 'medium', 'high', 'critical'}
    for row in records[1:]:
        if len(row) != 4:
            raise ValueError('invalid row')
        timestamp, vessel, severity, category = row
        _timestamp(timestamp)
        vessel = vessel.strip()
        category = category.strip()
        if not vessel or not category or severity not in allowed:
            raise ValueError('invalid field')
        result.append({'timestamp': timestamp, 'vessel': vessel, 'severity': severity, 'category': category})
    return result

