import subprocess
from datetime import date

def summarize_hives(paths: list[str], start_date: str, end_date: str) -> list[dict]:
    try:
        first = date.fromisoformat(start_date)
        last = date.fromisoformat(end_date)
    except ValueError as exc:
        raise ValueError('invalid query date') from exc
    if first > last:
        raise ValueError('reversed date range')
    records = []
    for path in paths:
        result = subprocess.run(['sort', '--', path], check=True, capture_output=True, text=True)
        for line in result.stdout.splitlines():
            if not line.strip():
                continue
            fields = line.split()
            if len(fields) != 4:
                raise ValueError('malformed record')
            day_text, hive, metric, value = fields
            try:
                day = date.fromisoformat(day_text)
            except ValueError as exc:
                raise ValueError('invalid record date') from exc
            if not hive or day < first or day > last:
                if not hive and first <= day <= last:
                    raise ValueError('empty hive')
                continue
            if metric == 'temperature':
                try:
                    parsed = float(value)
                except ValueError as exc:
                    raise ValueError('invalid temperature') from exc
            elif metric == 'bees':
                try:
                    parsed = int(value)
                except ValueError as exc:
                    raise ValueError('invalid bee count') from exc
                if parsed < 0:
                    raise ValueError('negative bee count')
            elif metric == 'queen':
                if value not in ('yes', 'no'):
                    raise ValueError('invalid queen value')
                parsed = value
            else:
                raise ValueError('unknown metric')
            records.append((day, hive, metric, parsed))
    grouped = {}
    for day, hive, metric, value in records:
        item = grouped.setdefault(hive, {'days': set(), 'temperatures': [], 'bees': [], 'queen': 0})
        item['days'].add(day)
        if metric == 'temperature':
            item['temperatures'].append(value)
        elif metric == 'bees':
            item['bees'].append(value)
        elif value == 'yes':
            item['queen'] += 1
    output = []
    for hive in sorted(grouped):
        item = grouped[hive]
        temps = item['temperatures']
        bees = item['bees']
        output.append({'hive': hive, 'days': len(item['days']), 'average_temperature': round(sum(temps) / len(temps), 2) if temps else None, 'peak_bees': max(bees) if bees else None, 'queen_sightings': item['queen']})
    return output

