    if isinstance(page, bool) or not isinstance(page, int) or page < 1:
        raise ValueError()
    if isinstance(page_size, bool) or not isinstance(page_size, int) or (not 1 <= page_size <= 100):
        raise ValueError()
    groups = {}
    for registration in registrations:
        if not isinstance(registration, dict):
            raise ValueError()
        required = {'attendee', 'congregation', 'status', 'fee_cents'}
        if not required.issubset(registration):
            raise ValueError()
        if not isinstance(registration['attendee'], str) or not isinstance(registration['congregation'], str):
            raise ValueError()
        if registration['status'] not in {'confirmed', 'cancelled', 'waitlist'}:
            raise ValueError()
        fee = registration['fee_cents']
        if isinstance(fee, bool) or not isinstance(fee, int) or fee < 0:
            raise ValueError()
        if registration['status'] == 'confirmed':
            congregation = registration['congregation']
            if congregation not in groups:
                groups[congregation] = [0, 0]
            groups[congregation][0] += 1
            groups[congregation][1] += fee
    ordered = sorted(groups.items(), key=lambda item: (-item[1][0], item[0]))
    total = sum((value[0] for value in groups.values()))
    revenue = sum((value[1] for value in groups.values()))
    page_count = max(1, (len(ordered) + page_size - 1) // page_size)
    selected = ordered[(page - 1) * page_size:page * page_size]
    rows = ''.join((f'<tr><td>{name}</td><td>{count}</td><td>${amount // 100}.{amount % 100:02d}</td></tr>' for name, (count, amount) in selected))
    return f'<section class="report">\n<h1>{event_title} - Registration Report</h1>\n<p class="summary">Confirmed: {total} | Revenue: ${revenue // 100}.{revenue % 100:02d} | Page: {page} of {page_count}</p>\n<table><thead><tr><th>Congregation</th><th>Registrations</th><th>Revenue</th></tr></thead><tbody>{rows}</tbody></table>\n</section>'

