from solution import sign_document, resolve_flags
import hashlib
import hmac
import json
import pytest


def make_payload(flags):
    return json.dumps({'flags': flags}, separators=(',', ':'), ensure_ascii=False)


def test_sign_and_resolve_defaults_and_order():
    payload = make_payload({
        'beta': {'default': False},
        'title': {'default': 'Welcome'},
        'count': {'default': 3}
    })
    document = sign_document(payload, b'key')
    assert document.startswith('sig:')
    assert resolve_flags(document, b'key', {}) == {
        'beta': False, 'title': 'Welcome', 'count': 3
    }


def test_rules_are_ordered_and_require_all_attributes():
    flags = {
        'mode': {
            'default': 'base',
            'rules': [
                {'when': {'plan': 'pro'}, 'value': 'pro'},
                {'when': {'plan': 'pro', 'region': 'eu'}, 'value': 'eu-pro'},
                {'when': {'region': 'us'}, 'value': 'us'}
            ]
        }
    }
    document = sign_document(make_payload(flags), b'secret')
    assert resolve_flags(document, b'secret', {'plan': 'pro', 'region': 'eu'}) == {'mode': 'pro'}
    assert resolve_flags(document, b'secret', {'region': 'us'}) == {'mode': 'us'}
    assert resolve_flags(document, b'secret', {'plan': 'free', 'region': 'eu'}) == {'mode': 'base'}


def test_rollout_is_deterministic_and_boundary_is_less_than():
    name = 'experiment'
    uid = 'alice'
    digest = hashlib.sha256((name + '|' + uid).encode()).digest()
    bucket = int.from_bytes(digest[:4], 'big') % 100
    flags = {
        name: {'default': 'off', 'rollout': bucket, 'rollout_value': 'on'},
        'all': {'default': 'no', 'rollout': 100, 'rollout_value': 'yes'},
        'none': {'default': 'no', 'rollout': 0, 'rollout_value': 'yes'}
    }
    document = sign_document(make_payload(flags), b'x')
    result = resolve_flags(document, b'x', {'user_id': uid})
    assert result[name] == 'off'
    assert result['all'] == 'yes'
    assert result['none'] == 'no'


def test_rollout_without_user_and_default_rollout_value():
    flags = {'f': {'default': 10, 'rollout': 100}}
    document = sign_document(make_payload(flags), b'x')
    assert resolve_flags(document, b'x', {}) == {'f': 10}
    assert resolve_flags(document, b'x', {'user_id': 4}) == {'f': 10}


def test_bad_signature_and_wrong_secret_are_rejected():
    payload = make_payload({'f': {'default': True}})
    document = sign_document(payload, b'right')
    with pytest.raises(ValueError):
        resolve_flags(document, b'wrong', {})
    altered = document[:-1] + ('0' if document[-1] != '0' else '1')
    with pytest.raises(ValueError):
        resolve_flags(altered, b'right', {})


def test_malformed_envelopes_and_payloads_raise_value_error():
    cases = [
        '', 'sig:00\n\n{}', 'sig:' + '0' * 64 + '\n{}',
        'sig:' + 'z' * 64 + '\n\n{}',
        'sig:' + '0' * 64 + '\n\n[]'
    ]
    for case in cases:
        with pytest.raises(ValueError):
            resolve_flags(case, b'x', {})
    with pytest.raises(ValueError):
        sign_document('a\nb', b'x')


def test_schema_errors_are_rejected():
    bad_payloads = [
        {'flags': []},
        {'flags': {'f': {}}},
        {'flags': {'f': {'default': 1, 'rules': {}}}},
        {'flags': {'f': {'default': 1, 'rollout': 101}}},
        {'flags': {'f': {'default': 1, 'rules': [{'when': [], 'value': 2}]}}}
    ]
    for obj in bad_payloads:
        document = sign_document(json.dumps(obj, separators=(',', ':')), b'x')
        with pytest.raises(ValueError):
            resolve_flags(document, b'x', {})

