import ast
from collections import deque

def evaluate_rule(expression: str, variables: dict[str, int | float | bool]) -> int | float | bool:
    try:
        tree = ast.parse(expression, mode='eval')
        allowed = (ast.Expression, ast.Constant, ast.Name, ast.UnaryOp, ast.UAdd, ast.USub, ast.Not, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.BoolOp, ast.And, ast.Or, ast.Compare, ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Call, ast.Load)
        for node in ast.walk(tree):
            if not isinstance(node, allowed):
                raise ValueError()
            if isinstance(node, ast.Constant) and (not isinstance(node.value, (int, float, bool))):
                raise ValueError()
            if isinstance(node, ast.Name) and node.id not in variables and (node.id not in {'min', 'max', 'round'}):
                raise ValueError()
            if isinstance(node, ast.Call) and (not isinstance(node.func, ast.Name) or node.func.id not in {'min', 'max', 'round'} or node.keywords):
                raise ValueError()
        return _walk(tree.body, variables)
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError() from exc

def _walk(n, v):
    if isinstance(n, ast.Constant):
        return n.value
    if isinstance(n, ast.Name):
        return v[n.id]
    if isinstance(n, ast.UnaryOp):
        x = _walk(n.operand, v)
        return +x if isinstance(n.op, ast.UAdd) else -x if isinstance(n.op, ast.USub) else not x
    if isinstance(n, ast.BinOp):
        a, b = (_walk(n.left, v), _walk(n.right, v))
        return a + b if isinstance(n.op, ast.Add) else a - b if isinstance(n.op, ast.Sub) else a * b if isinstance(n.op, ast.Mult) else a / b
    if isinstance(n, ast.BoolOp):
        if isinstance(n.op, ast.And):
            x = _walk(n.values[0], v)
            for q in n.values[1:]:
                if not x:
                    return x
                x = _walk(q, v)
            return x
        x = _walk(n.values[0], v)
        for q in n.values[1:]:
            if x:
                return x
            x = _walk(q, v)
        return x
    if isinstance(n, ast.Compare):
        a = _walk(n.left, v)
        for op, q in zip(n.ops, n.comparators):
            b = _walk(q, v)
            ok = a == b if isinstance(op, ast.Eq) else a != b if isinstance(op, ast.NotEq) else a < b if isinstance(op, ast.Lt) else a <= b if isinstance(op, ast.LtE) else a > b if isinstance(op, ast.Gt) else a >= b
            if not ok:
                return False
            a = b
        return True
    if isinstance(n, ast.Call):
        args = [_walk(x, v) for x in n.args]
        if n.func.id == 'round' and len(args) not in (1, 2):
            raise ValueError()
        if n.func.id != 'round' and (not args):
            raise ValueError()
        return {'min': min, 'max': max, 'round': round}[n.func.id](*args)

def summarize_occupancy(readings: list[dict], expression: str, window: int=3) -> dict[str, dict]:
    if not isinstance(window, int) or isinstance(window, bool) or window <= 0:
        raise ValueError()
    ordered = []
    for i, r in enumerate(readings):
        if set(r) != {'timestamp', 'zone', 'occupied', 'confidence'} or not isinstance(r['timestamp'], int) or (not isinstance(r['zone'], str)) or (not r['zone']) or (not isinstance(r['occupied'], bool)) or (not isinstance(r['confidence'], (int, float))) or isinstance(r['confidence'], bool) or (not 0 <= r['confidence'] <= 1):
