import sqlite3
from datetime import date
from decimal import Decimal, ROUND_HALF_UP

def fetch_inspections(conn: sqlite3.Connection, filters: dict[str, object] | None=None, sort_by: str='scheduled_date', descending: bool=False) -> list[dict[str, object]]:
    allowed = {'id', 'building_id', 'inspector', 'status', 'scheduled_date', 'score', 'notes'}
    filter_columns = {'building_id', 'status', 'inspector', 'minimum_score'}
    if sort_by not in allowed:
        raise ValueError('invalid sort column')
    filters = {} if filters is None else dict(filters)
    unknown = set(filters) - filter_columns
    if unknown:
        raise ValueError('invalid filter')
    clauses = []
    values = []
    for key in ('building_id', 'status', 'inspector'):
        if key in filters:
            clauses.append(f'{key} = ?')
            values.append(filters[key])
    if 'minimum_score' in filters:
        clauses.append('score >= ?')
        values.append(filters['minimum_score'])
    query = 'SELECT id, building_id, inspector, status, scheduled_date, score, notes FROM inspections'
    if clauses:
        query += ' WHERE ' + ' AND '.join(clauses)
    direction = 'DESC' if descending else 'ASC'
    query += f' ORDER BY {sort_by} {direction}, id ASC'
    result = conn.execute(query, values).fetchall()
    names = ['id', 'building_id', 'inspector', 'status', 'scheduled_date', 'score', 'notes']
    return [{name: row[name] for name in names} for row in result]

def build_compliance_report(inspections: list[dict[str, object]], as_of: str) -> list[dict[str, object]]:
    try:
        cutoff = date.fromisoformat(as_of)
    except (TypeError, ValueError):
        raise ValueError('invalid date')
    grouped = {}
    for row in inspections:
        try:
            scheduled = date.fromisoformat(row['scheduled_date'])
        except (TypeError, ValueError):
            raise ValueError('invalid date')
        building = row['building_id']
        state = grouped.setdefault(building, {'total': 0, 'completed': 0, 'scores': [], 'overdue': 0})
        state['total'] += 1
        if row['status'] == 'completed':
            state['completed'] += 1
        elif scheduled < cutoff:
            state['overdue'] += 1
        if row.get('score') is not None:
            state['scores'].append(Decimal(str(row['score'])))
    output = []
    for building in sorted(grouped):
        state = grouped[building]
        average = None
        if state['scores']:
            average = float((sum(state['scores']) / len(state['scores'])).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
        output.append({'building_id': building, 'total': state['total'], 'completed': state['completed'], 'average_score': average, 'overdue': state['overdue']})
    return output

