import hmac

def verify_transport_webhook(payload: bytes, signature: str, secret: str) -> bool:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(secret, str)):
        return False
    if not secret or signature.count('=') != 1:
        return False
    algorithm, supplied = signature.split('=', 1)
    if algorithm != 'sha256' or len(supplied) != 64:
        return False
    if any((char not in '0123456789abcdef' for char in supplied)):
        return False
    expected = hmac.new(secret.encode('utf-8'), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(supplied, expected)

