import base64
import datetime
import hashlib
import hmac
import os

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return 'p1$' + base64.b64encode(salt).decode() + '$' + base64.b64encode(digest).decode()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str) or not isinstance(stored, str):
        return False
    try:
        tag, salt_text, digest_text = stored.split('$')
        if tag != 'p1':
            return False
        salt = base64.b64decode(salt_text, validate=True)
        expected = base64.b64decode(digest_text, validate=True)
        actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
        return hmac.compare_digest(actual, expected)
    except Exception:
        return False

def lot_report(records: list[dict], page: int, page_size: int, operator_secret: str, stored_secret: str) -> list[dict]:
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or page_size < 1:
        raise ValueError('invalid page size')
    if not verify_secret(operator_secret, stored_secret):
        raise PermissionError('invalid operator')
    groups = {}
    seen = set()
    for r in records:
        try:
            lid, product, quantity, status, stamp = (r['lot_id'], r['product'], r['quantity_kg'], r['status'], r['timestamp'])
        except (KeyError, TypeError):
            raise ValueError('invalid record')
        if not isinstance(lid, str) or not lid or (not isinstance(product, str)) or (not product) or (lid in seen):
            raise ValueError('invalid record')
        if isinstance(quantity, bool) or not isinstance(quantity, (int, float)) or quantity <= 0:
            raise ValueError('invalid quantity')
        if status not in ('released', 'held', 'recalled') or not isinstance(stamp, str):
            raise ValueError('invalid record')
        try:
            datetime.datetime.strptime(stamp, '%Y-%m-%dT%H:%M:%S')
        except ValueError:
            raise ValueError('invalid timestamp')
        seen.add(lid)
        if product not in groups:
            groups[product] = [0.0, 0, None, {'released': 0, 'held': 0, 'recalled': 0}]
        g = groups[product]
        g[0] += quantity
        g[1] += 1
        if g[2] is None or stamp > g[2]:
            g[2] = stamp
        g[3][status] += 1
    result = []
    for product, (total, count, latest, statuses) in groups.items():
        result.append({'product': product, 'total_kg': round(total, 2), 'lot_count': count, 'latest_timestamp': latest, 'status_counts': statuses})
    result.sort(key=lambda x: (-x['total_kg'], x['product']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

