from solution import verify_trademark_notification
import json
import pytest


def make_body(**overrides):
    data = {
        "event": "trademark_watch",
        "mark": "Aurora",
        "jurisdiction": "US",
        "status": "active",
        "serial": "88991234",
        "timestamp": 1712345678,
    }
    data.update(overrides)
    return json.dumps(data)


def test_valid_notification_returns_only_required_fields():
    body = make_body(source="registry", priority=3)
    assert verify_trademark_notification(body, "watch-key", "watch-key") == {
        "event": "trademark_watch",
        "mark": "Aurora",
        "jurisdiction": "US",
        "status": "active",
        "serial": "88991234",
        "timestamp": 1712345678,
    }


def test_all_supported_statuses_are_accepted():
    for status in ("active", "expired", "opposed"):
        result = verify_trademark_notification(
            make_body(status=status), "abc123", "abc123"
        )
        assert result["status"] == status


def test_wrong_key_is_rejected():
    with pytest.raises(PermissionError, match="^invalid key$"):
        verify_trademark_notification(make_body(), "wrong", "watch-key")


def test_malformed_json_is_rejected():
    with pytest.raises(ValueError, match="^invalid JSON$"):
        verify_trademark_notification("{not json", "key", "key")


def test_non_object_json_is_rejected_as_invalid_json():
    with pytest.raises(ValueError, match="^invalid JSON$"):
        verify_trademark_notification("[1, 2, 3]", "key", "key")


def test_missing_or_invalid_fields_are_rejected():
    required = {"event", "mark", "jurisdiction", "status", "serial", "timestamp"}
    for field in required:
        data = json.loads(make_body())
        del data[field]
        with pytest.raises(ValueError, match="^invalid notification$"):
            verify_trademark_notification(json.dumps(data), "key", "key")

    for field, value in (
        ("event", "other_event"),
        ("mark", ""),
        ("jurisdiction", 7),
        ("status", "pending"),
        ("serial", ""),
        ("timestamp", True),
    ):
        with pytest.raises(ValueError, match="^invalid notification$"):
            verify_trademark_notification(make_body(**{field: value}), "key", "key")


def test_unicode_values_and_zero_timestamp_are_preserved():
    body = make_body(mark="Étoile™", jurisdiction="EU", timestamp=0)
    result = verify_trademark_notification(body, "clé", "clé")
    assert result["mark"] == "Étoile™"
    assert result["jurisdiction"] == "EU"
    assert result["timestamp"] == 0


def test_empty_keys_follow_normal_matching_rules():
    body = make_body()
    assert verify_trademark_notification(body, "", "")["serial"] == "88991234"

