import re
import sqlite3
from typing import Any

def parse_coupon(text: str) -> tuple[str, int]:
    if text == '':
        return ('none', 0)
    match = re.fullmatch('(PERCENT|FIXED):([0-9]+)', text)
    if match is None:
        raise ValueError('invalid coupon')
    value = int(match.group(2))
    if value > 10000:
        raise ValueError('invalid coupon')
    return ('percent' if match.group(1) == 'PERCENT' else 'fixed', value)

def cart_quote(conn: sqlite3.Connection, cart_id: int, search: str='', sort_by: str='position', descending: bool=False, coupon: str='') -> dict[str, Any]:
    if sort_by not in {'position', 'name', 'line_total'}:
        raise ValueError('invalid sort')
    kind, amount = parse_coupon(coupon)
    columns = {'position': 'ci.position', 'name': 'p.name', 'line_total': 'ci.quantity * p.unit_price_cents'}
    direction = 'DESC' if descending else 'ASC'
    sql = 'SELECT p.id, p.name, ci.quantity, p.unit_price_cents, p.tax_bps, ci.position FROM cart_items ci JOIN products p ON p.id = ci.product_id WHERE ci.cart_id = ? AND lower(p.name) LIKE lower(?) ORDER BY ' + columns[sort_by] + ' ' + direction + ', ci.position ASC, p.id ASC'
    rows = conn.execute(sql, (cart_id, '%' + search + '%')).fetchall()
    items = []
    subtotal = 0
    tax = 0
    for product_id, name, quantity, price, tax_bps, position in rows:
        line = quantity * price
        items.append({'product_id': product_id, 'name': name, 'quantity': quantity, 'unit_price_cents': price, 'tax_bps': tax_bps, 'line_total_cents': line})
        subtotal += line
        tax += line * tax_bps // 10000
    if kind == 'percent':
        discount = subtotal * amount // 100
    elif kind == 'fixed':
        discount = min(amount, subtotal)
    else:
        discount = 0
    return {'items': items, 'subtotal_cents': subtotal, 'tax_cents': tax, 'discount_cents': discount, 'total_cents': subtotal + tax - discount}

