import ast

def _eval(node, env):
    if isinstance(node, ast.Constant):
        if node.value is None or isinstance(node.value, (bool, int, float, str)):
            return node.value
        raise ValueError()
    if isinstance(node, ast.Name):
        if node.id not in env:
            raise ValueError()
        return env[node.id]
    if isinstance(node, ast.BinOp) and type(node.op) in (ast.Add, ast.Sub, ast.Mult, ast.Div):
        a, b = (_eval(node.left, env), _eval(node.right, env))
        return {ast.Add: lambda: a + b, ast.Sub: lambda: a - b, ast.Mult: lambda: a * b, ast.Div: lambda: a / b}[type(node.op)]()
    if isinstance(node, ast.UnaryOp) and type(node.op) in (ast.UAdd, ast.USub, ast.Not):
        v = _eval(node.operand, env)
        return +v if isinstance(node.op, ast.UAdd) else -v if isinstance(node.op, ast.USub) else not v
    if isinstance(node, ast.BoolOp) and type(node.op) in (ast.And, ast.Or):
        value = _eval(node.values[0], env)
        for n in node.values[1:]:
            if isinstance(node.op, ast.And) and (not value):
                return value
            if isinstance(node.op, ast.Or) and value:
                return value
            value = _eval(n, env)
        return value
    if isinstance(node, ast.Compare):
        left = _eval(node.left, env)
        for op, part in zip(node.ops, node.comparators):
            right = _eval(part, env)
            if type(op) not in (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE):
                raise ValueError()
            if not {ast.Eq: lambda: left == right, ast.NotEq: lambda: left != right, ast.Lt: lambda: left < right, ast.LtE: lambda: left <= right, ast.Gt: lambda: left > right, ast.GtE: lambda: left >= right}[type(op)]():
                return False
            left = right
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in ('min', 'max', 'round')) and (not node.keywords):
        return {'min': min, 'max': max, 'round': round}[node.func.id](*[_eval(x, env) for x in node.args])
    raise ValueError()

def evaluate_rule(expression: str, variables: dict[str, object]) -> object:
    try:
        tree = ast.parse(expression, mode='eval')
        return _eval(tree.body, variables)
    except Exception as exc:
        if isinstance(exc, ValueError):
            raise
        raise ValueError() from exc

def dispatch_alerts(alerts: list[dict[str, object]], subscriptions: list[dict[str, object]], now: int) -> dict[str, list[str]]:
    if isinstance(now, bool) or not isinstance(now, int):
        raise ValueError()
    ids = [a.get('id') for a in alerts]
    if any((not isinstance(x, str) for x in ids)) or len(set(ids)) != len(ids):
        raise ValueError()
    out = {}
    seen = set()
    for s in subscriptions:
        if not isinstance(s.get('id'), str) or s['id'] in seen or (not isinstance(s.get('regions'), list)) or (not isinstance(s.get('rule'), str)):
            raise ValueError()
        seen.add(s['id'])
        window, limit = (s.get('window'), s.get('limit', 3))
        if isinstance(window, bool) or not isinstance(window, int) or window < 0 or isinstance(limit, bool) or (not isinstance(limit, int)) or (limit < 0):
            raise ValueError()
        chosen = []
        for a in alerts:
            required = ('timestamp', 'region', 'severity', 'category')
            if any((k not in a for k in required)):
                raise ValueError()
            age = now - a['timestamp']
            if a['region'] in s['regions'] and a['timestamp'] <= now and (age <= window):
                try:
                    if evaluate_rule(s['rule'], {'severity': a['severity'], 'age': age, 'category': a['category'], 'region': a['region'], 'timestamp': a['timestamp']}):
                        chosen.append(a)
                except ValueError:
                    raise
        chosen.sort(key=lambda a: (-a['severity'], a['timestamp'], a['id']))
        out[s['id']] = [a['id'] for a in chosen[:limit]]
    return out

