def verify_record(line: str, keys: dict[str, str]) -> dict:
    try:
        obj = json.loads(line)
    except Exception as exc:
        raise ValueError('invalid record') from exc
    if not isinstance(obj, dict) or set(obj) != {'timestamp', 'sensor', 'key_id', 'readings', 'signature'}:
        raise ValueError('invalid record')
    if not isinstance(obj['timestamp'], int) or isinstance(obj['timestamp'], bool) or obj['timestamp'] < 0 or (not isinstance(obj['sensor'], str)) or (not obj['sensor']) or (not isinstance(obj['key_id'], str)) or (not obj['key_id']) or (not isinstance(obj['readings'], dict)) or (not obj['readings']) or (not isinstance(obj['signature'], str)):
        raise ValueError('invalid record')
    for name, value in obj['readings'].items():
        if not isinstance(name, str) or isinstance(value, bool) or (not isinstance(value, (int, float))) or (not math.isfinite(value)):
            raise ValueError('invalid readings')
    if obj['key_id'] not in keys:
        raise ValueError('unknown key')
    sig = obj['signature']
    if len(sig) != 64 or any((c not in '0123456789abcdef' for c in sig)):
        raise ValueError('invalid signature')
    body = {k: v for k, v in obj.items() if k != 'signature'}
    data = json.dumps(body, sort_keys=True, separators=(',', ':')).encode()
    expected = hmac.new(keys[obj['key_id']].encode(), data, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, sig):
        raise ValueError('invalid signature')
