        raise ValueError('invalid window')
    groups = {}
    for line in lines:
        record = verify_record(line, keys)
        start = record['timestamp'] // window * window
        bucket = groups.setdefault((start, record['sensor']), [])
        bucket.append(record)
    output = []
    for (start, sensor), records in sorted(groups.items()):
