            if not isinstance(h, dict) or h['id'] in seen_h or (not isinstance(h['id'], str)) or (not isinstance(h['tenant'], str)) or (not isinstance(h['priority'], int)) or (not isinstance(h['registered'], str)) or (not isinstance(h['size'], int)) or (h['size'] <= 0):
