import re
from decimal import Decimal, InvalidOperation
from lxml import etree

def read_stylist_schedule(xml: str, stylist: str, date: str, page: int=1, page_size: int=10) -> dict:
    if not isinstance(xml, str) or not isinstance(page, int) or isinstance(page, bool) or (not isinstance(page_size, int)) or isinstance(page_size, bool):
        raise ValueError('invalid arguments')
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'schedule':
        raise ValueError('invalid root')
    matches = []
    for node in root.iter('appointment'):
        if node.get('stylist') != stylist or node.get('date') != date or node.get('status') != 'booked':
            continue
        try:
            ident = node.attrib['id']
            start = node.attrib['start']
            duration = int(node.attrib['duration'])
            raw_price = node.attrib['price']
            if not re.fullmatch('(?:[01][0-9]|2[0-3]):[0-5][0-9]', start):
                raise ValueError
            if duration < 1 or duration > 720:
                raise ValueError
            price = Decimal(raw_price)
            if price < 0 or price.as_tuple().exponent < -2:
                raise ValueError
            cents = int(price * 100)
            if Decimal(cents) / 100 != price:
                raise ValueError
        except (KeyError, ValueError, InvalidOperation, OverflowError):
            raise ValueError('invalid appointment')
        matches.append((start, ident, {'id': ident, 'start': start, 'duration_minutes': duration, 'price_cents': cents}))
    matches.sort(key=lambda item: (item[0], item[1]))
    total_minutes = sum((item[2]['duration_minutes'] for item in matches))
    total_price = sum((item[2]['price_cents'] for item in matches))
    page_count = (len(matches) + page_size - 1) // page_size
    begin = (page - 1) * page_size
    selected = [item[2] for item in matches[begin:begin + page_size]]
    return {'appointments': selected, 'total_minutes': total_minutes, 'total_price_cents': total_price, 'page': page, 'page_count': page_count}

