import ast
import operator

def _evaluate(text, names):
    try:
        tree = ast.parse(text, mode='eval').body

        def visit(node):
            if isinstance(node, ast.Constant) and type(node.value) in (int, float):
                return node.value
            if isinstance(node, ast.Name):
                if node.id not in names:
                    raise ValueError()
                return names[node.id]
            if isinstance(node, ast.BinOp) and type(node.op) in {ast.Add, ast.Sub, ast.Mult, ast.Div}:
                left, right = (visit(node.left), visit(node.right))
                return {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}[type(node.op)](left, right)
            if isinstance(node, ast.UnaryOp) and type(node.op) in {ast.UAdd, ast.USub, ast.Not}:
                value = visit(node.operand)
                return {ast.UAdd: operator.pos, ast.USub: operator.neg, ast.Not: operator.not_}[type(node.op)](value)
            if isinstance(node, ast.BoolOp) and type(node.op) in {ast.And, ast.Or}:
                value = visit(node.values[0])
                for child in node.values[1:]:
                    if isinstance(node.op, ast.And) and (not value) or (isinstance(node.op, ast.Or) and value):
                        return value
                    value = visit(child)
                return value
            if isinstance(node, ast.Compare):
                left = visit(node.left)
                for op, child in zip(node.ops, node.comparators):
                    right = visit(child)
                    if type(op) not in {ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.Eq, ast.NotEq}:
                        raise ValueError()
                    if not {ast.Lt: operator.lt, ast.LtE: operator.le, ast.Gt: operator.gt, ast.GtE: operator.ge, ast.Eq: operator.eq, ast.NotEq: operator.ne}[type(op)](left, right):
                        return False
                    left = right
                return True
            if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and (node.func.id in {'min', 'max', 'round'}) and (not node.keywords):
                return {'min': min, 'max': max, 'round': round}[node.func.id](*(visit(x) for x in node.args))
            raise ValueError()
        return visit(tree)
    except Exception as exc:
        raise ValueError() from exc

def grade_report(records: list[dict], expression: str, page: int=1, page_size: int=10) -> dict:
    if type(page) is not int or type(page_size) is not int or page < 1 or (page_size < 1):
        raise ValueError()
    rows = []
    for record in records:
        score = float(round(_evaluate(expression, record['scores']), 2))
        rows.append({'student': record['student'], 'score': score})
    rows.sort(key=lambda row: (-row['score'], row['student']))
    for index, row in enumerate(rows):
        row['rank'] = index + 1 if index == 0 or row['score'] != rows[index - 1]['score'] else rows[index - 1]['rank']
    start = (page - 1) * page_size
    return {'total': len(rows), 'page': page, 'page_size': page_size, 'students': rows[start:start + page_size]}

