import hashlib
import hmac
import json
import pytest


def signed(payload, secret="warehouse-key"):
    return hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()


def test_empty_payload_and_empty_summary():
    payload = json.dumps({"records": []})
    assert process_equipment_webhook(payload, signed(payload), "warehouse-key") == {
        "total_hours": 0,
        "equipment": [],
    }


def test_groups_rounds_and_sorts_by_hours_then_id():
    payload = json.dumps({"records": [
        {"equipment_id": "drill-b", "employee": "a", "hours": 1.005, "status": "assigned", "date": "2024-02-29"},
        {"equipment_id": "drill-a", "employee": "b", "hours": 2, "status": "returned", "date": "2024-03-01"},
        {"equipment_id": "drill-b", "employee": "c", "hours": 1.005, "status": "returned", "date": "2024-03-02"},
        {"equipment_id": "drill-c", "employee": "d", "hours": 2.01, "status": "assigned", "date": "2024-03-03"},
    ]})
    assert process_equipment_webhook(payload, signed(payload), "warehouse-key") == {
        "total_hours": 6.02,
        "equipment": [
            {"equipment_id": "drill-b", "hours": 2.01, "records": 2},
            {"equipment_id": "drill-c", "hours": 2.01, "records": 1},
            {"equipment_id": "drill-a", "hours": 2, "records": 1},
        ],
    }


def test_status_does_not_filter_records():
    payload = json.dumps({"records": [
        {"equipment_id": "lift-7", "employee": "x", "hours": 3.5, "status": "returned", "date": "2024-01-15"},
    ]})
    result = process_equipment_webhook(payload, signed(payload), "warehouse-key")
    assert result["total_hours"] == 3.5
    assert result["equipment"] == [{"equipment_id": "lift-7", "hours": 3.5, "records": 1}]


def test_bad_signature_returns_none_before_json_parsing():
    assert process_equipment_webhook("not json", "0" * 64, "warehouse-key") is None
    payload = json.dumps({"records": []})
    assert process_equipment_webhook(payload, signed(payload, "other"), "warehouse-key") is None


