from datetime import date
import secrets
_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'

def _fields(line):
    out, cur, escaped = ([], [], False)
    for ch in line:
        if escaped:
            if ch not in '\\|':
                raise ValueError('invalid escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def parse_manifest(text: str) -> list[dict]:
    result = []
    for raw in text.splitlines():
        if not raw.strip():
            continue
        fields = _fields(raw)
        if len(fields) != 4 or any((not x for x in fields[:3])):
            raise ValueError('invalid row')
        try:
            when = date.fromisoformat(fields[3])
        except ValueError:
            raise ValueError('invalid date')
        if fields[1] == fields[2]:
            raise ValueError('same station')
        result.append({'passenger': fields[0], 'origin': fields[1], 'destination': fields[2], 'date': when})
    return result

def _zone(name):
    digits = ''
    for ch in reversed(name):
        if ch.isdigit():
            digits = ch + digits
        else:
            break
    return int(digits) if digits else 0

def _code():
    return ''.join((secrets.choice(_ALPHABET) for _ in range(12)))

def issue_passes(manifest: str, valid_from: str) -> list[dict]:
    try:
        start = date.fromisoformat(valid_from)
    except ValueError:
        raise ValueError('invalid date')
    groups = {}
    for row in parse_manifest(manifest):
        groups.setdefault(row['passenger'], []).append(row)
    result = []
    for passenger in sorted(groups):
        rows = sorted(groups[passenger], key=lambda r: (r['date'], r['origin'], r['destination']))
        journeys = [{'origin': r['origin'], 'destination': r['destination'], 'date': r['date'].isoformat()} for r in rows]
        fare = sum((100 + 250 * abs(_zone(r['origin']) - _zone(r['destination'])) for r in rows))
        end = max(start, rows[-1]['date'])
        result.append({'passenger': passenger, 'code': _code(), 'valid_from': start.isoformat(), 'valid_to': end.isoformat(), 'journeys': journeys, 'fare_cents': fare})
    return result

def summarize_passes(passes: list[dict]) -> dict:
    return {'pass_count': len(passes), 'journey_count': sum((len(p['journeys']) for p in passes)), 'fare_cents': sum((p['fare_cents'] for p in passes)), 'passengers': [p['passenger'] for p in passes]}

