def generate_enrollment_code(site_code: str, length: int=10) -> str:
    if isinstance(site_code, bool) or not isinstance(site_code, str):
        raise ValueError('invalid site code')
    if not 2 <= len(site_code) <= 6 or not site_code.isascii() or (not site_code.isalnum()):
        raise ValueError('invalid site code')
    if isinstance(length, bool) or not isinstance(length, int) or (not 6 <= length <= 32):
