        parcel_id = record['parcel_id']
        municipality = record['municipality']
        record_year = record['year']
        assessed = record['assessed_value']
        exemption = record['exemption']
        if not isinstance(parcel_id, str) or not parcel_id:
            raise ValueError('invalid parcel id')
        if not isinstance(municipality, str) or not municipality:
            raise ValueError('invalid municipality')
        if not isinstance(record_year, int) or isinstance(record_year, bool):
            raise ValueError('invalid year')
