import hashlib
import os
import hmac
from decimal import Decimal, ROUND_HALF_UP

def hash_secret(secret: str) -> str:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not secret:
        raise ValueError('secret must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return salt.hex() + ':' + digest.hex()

def verify_secret(secret: str, stored: str) -> bool:
    if not isinstance(secret, str):
        raise TypeError('secret must be a string')
    if not isinstance(stored, str):
        return False
    try:
        salt_text, digest_text = stored.split(':')
        salt = bytes.fromhex(salt_text)
        expected = bytes.fromhex(digest_text)
    except (ValueError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', secret.encode(), salt, 100000)
    return hmac.compare_digest(actual, expected)

def fulfillment_summary(orders: list[dict], page: int=1, page_size: int=10) -> list[dict]:
    if not isinstance(orders, list):
        raise TypeError('orders must be a list')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid page')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid page size')
    groups = {}
    for order in orders:
        if not isinstance(order, dict):
            raise ValueError('invalid order')
        customer = order.get('customer')
        status = order.get('status')
        quantity = order.get('quantity')
        unit_price = order.get('unit_price')
        if not isinstance(customer, str) or not customer:
            raise ValueError('invalid customer')
        if not isinstance(status, str):
            raise ValueError('invalid status')
        if not isinstance(quantity, int) or isinstance(quantity, bool) or quantity <= 0:
            raise ValueError('invalid quantity')
        if isinstance(unit_price, bool) or not isinstance(unit_price, (int, float)) or unit_price < 0:
            raise ValueError('invalid price')
        if status == 'ready':
            item = groups.setdefault(customer, [0, 0, Decimal('0')])
            item[0] += 1
            item[1] += quantity
            item[2] += Decimal(quantity) * Decimal(str(unit_price))
    result = []
    for customer, (count, units, value) in groups.items():
        result.append({'customer': customer, 'orders': count, 'units': units, 'value': float(value.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))})
    result.sort(key=lambda item: (-item['value'], item['customer']))
    start = (page - 1) * page_size
    return result[start:start + page_size]

