import hashlib
import hmac
import os

def hash_access_code(access_code: str) -> str:
    if not isinstance(access_code, str):
        raise TypeError('access_code must be a string')
    if access_code == '':
        raise ValueError('access_code must not be empty')
    salt = os.urandom(16)
    digest = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    return base64.urlsafe_b64encode(salt).decode('ascii') + ':' + base64.urlsafe_b64encode(digest).decode('ascii')

def verify_access_code(access_code: str, stored_value: str) -> bool:
    if not isinstance(access_code, str) or not access_code or (not isinstance(stored_value, str)):
        return False
    try:
        salt_text, digest_text = stored_value.split(':', 1)
        salt = base64.urlsafe_b64decode(salt_text.encode('ascii'))
        expected = base64.urlsafe_b64decode(digest_text.encode('ascii'))
    except (ValueError, UnicodeError, TypeError):
        return False
    actual = hashlib.pbkdf2_hmac('sha256', access_code.encode('utf-8'), salt, 100000)
    return hmac.compare_digest(actual, expected)

