import csv
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from datetime import date
_COLUMNS = ['date', 'artist', 'venue', 'gross', 'expenses', 'merchandise', 'tickets_sold', 'tickets_capacity']
_CENT = Decimal('0.01')

def _money(value):
    try:
        return Decimal(value).quantize(_CENT, rounding=ROUND_HALF_UP)
    except (InvalidOperation, TypeError):
        raise ValueError('invalid monetary value')

def read_settlement_report(base_dir: str, relative_name: str) -> list[dict]:
    base = os.path.realpath(base_dir)
    path = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, path]) != base:
        raise ValueError('file is outside base directory')
    try:
        with open(path, 'r', encoding='utf-8', newline='') as handle:
            reader = csv.DictReader(handle)
            if reader.fieldnames != _COLUMNS and set(reader.fieldnames or []) != set(_COLUMNS):
                raise ValueError('invalid columns')
            result = []
            for row in reader:
                if not any(((v or '').strip() for v in row.values())):
                    continue
                try:
                    date.fromisoformat(row['date'])
                    if not row['artist'] or not row['venue']:
                        raise ValueError
                    sold = int(row['tickets_sold'])
                    capacity = int(row['tickets_capacity'])
                    if sold < 0 or capacity < 0:
                        raise ValueError
                    result.append({'date': row['date'], 'artist': row['artist'], 'venue': row['venue'], 'gross': _money(row['gross']), 'expenses': _money(row['expenses']), 'merchandise': _money(row['merchandise']), 'tickets_sold': sold, 'tickets_capacity': capacity})
                except (KeyError, TypeError, ValueError):
                    raise ValueError('invalid row')
            return result
    except OSError as exc:
        raise ValueError('unable to read report') from exc

def calculate_artist_settlement(rows: list[dict], artist: str, share: str, tax_rate: str='0') -> dict:
    if not artist:
        raise ValueError('artist is required')
    try:
        fraction = Decimal(share)
        tax_fraction = Decimal(tax_rate)
    except (InvalidOperation, TypeError):
        raise ValueError('invalid rate')
    if not Decimal('0') <= fraction <= Decimal('1') or not Decimal('0') <= tax_fraction <= Decimal('1'):
        raise ValueError('invalid rate')
    selected = [(i, r) for i, r in enumerate(rows) if r.get('artist') == artist]
    selected.sort(key=lambda item: (item[1]['date'], item[1]['venue'], item[0]))
    shows = []
    totals = [Decimal('0.00'), Decimal('0.00'), Decimal('0.00'), Decimal('0.00')]
    sold = capacity = 0
    for _, row in selected:
        net = (row['gross'] + row['merchandise'] - row['expenses']).quantize(_CENT)
        pre = (net * fraction).quantize(_CENT)
        tax = (max(pre, Decimal('0.00')) * tax_fraction).quantize(_CENT)
        payout = (pre - tax).quantize(_CENT)
        shows.append({'date': row['date'], 'venue': row['venue'], 'net': net, 'pre_tax': pre, 'tax': tax, 'payout': payout, 'tickets_sold': row['tickets_sold'], 'tickets_capacity': row['tickets_capacity']})
        totals[0] += row['gross']
        totals[1] += row['expenses']
        totals[2] += row['merchandise']
        totals[3] += payout
        sold += row['tickets_sold']
        capacity += row['tickets_capacity']
    sell = (Decimal(sold) / Decimal(capacity)).quantize(Decimal('0.0001')) if capacity else Decimal('0.0000')
    return {'artist': artist, 'shows': shows, 'gross_total': totals[0].quantize(_CENT), 'expenses_total': totals[1].quantize(_CENT), 'merchandise_total': totals[2].quantize(_CENT), 'payout_total': totals[3].quantize(_CENT), 'tickets_sold': sold, 'tickets_capacity': capacity, 'sell_through': sell}

