        if not isinstance(record, dict) or not isinstance(record.get('vessel'), str) or (not record['vessel']):
            raise ValueError('invalid record')
        fuel = record.get('fuel_tons')
        distance = record.get('distance_nm')
        if isinstance(fuel, bool) or not isinstance(fuel, (int, float)) or (not math.isfinite(fuel)) or (fuel < 0):
            raise ValueError('invalid fuel')
        if isinstance(distance, bool) or not isinstance(distance, (int, float)) or (not math.isfinite(distance)) or (distance <= 0):
            raise ValueError('invalid distance')
