def summarize_harvests(blob: bytes, start_date: str | None=None, end_date: str | None=None, max_moisture: float=18.0, offset: int=0, limit: int=10) -> list[dict]:
    if offset < 0 or limit <= 0:
        raise ValueError('invalid pagination')
