            day = record['date']
            kg = record['kg']
            moisture = record['moisture']
            date.fromisoformat(day)
            if not isinstance(hive, str) or not isinstance(day, str) or isinstance(kg, bool) or (not isinstance(kg, (int, float))) or isinstance(moisture, bool) or (not isinstance(moisture, (int, float))):
