        if start_date is not None and day < start_date or (end_date is not None and day > end_date) or moisture > max_moisture:
            continue
        item = groups.setdefault(hive, [0.0, 0.0, 0])
        item[0] += kg
        item[1] += moisture
        item[2] += 1
    result = [{'hive': h, 'total_kg': round(v[0], 2), 'average_moisture': round(v[1] / v[2], 1), 'harvests': v[2]} for h, v in groups.items()]
