def parse_agenda(xml_text: str) -> list[dict[str, str]]:
    if not isinstance(xml_text, str):
        raise TypeError('xml_text must be a string')
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'agenda':
        raise ValueError('root must be agenda')
    result = []
    seen = set()
    for node in root:
        if node.tag != 'hearing':
            continue
        hearing_id = (node.get('id') or '').strip()
        if not hearing_id or hearing_id in seen:
            raise ValueError('invalid or duplicate hearing id')
        values = {}
        for name in ('date', 'title', 'location'):
            child = node.find(name)
            value = '' if child is None or child.text is None else child.text.strip()
            if not value:
