import subprocess

def rank_episodes(log_path: str, limit: int=10, offset: int=0) -> list[dict[str, object]]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit <= 0:
        raise ValueError('limit must be positive')
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError('offset must be non-negative')
    completed = subprocess.run(['sort', '-t', '\t', '-k1,1', log_path], check=True, capture_output=True, text=True)
    totals: dict[str, list[int]] = {}
    for line in completed.stdout.splitlines():
        if not line.strip():
            continue
        fields = line.split('\t')
        if len(fields) != 2:
            raise ValueError('malformed record')
        episode = fields[0].strip()
        if not episode:
            raise ValueError('empty episode')
        try:
            amount = int(fields[1].strip())
        except ValueError:
            raise ValueError('invalid byte count')
        if amount < 0:
            raise ValueError('invalid byte count')
        if episode not in totals:
            totals[episode] = [0, 0]
        totals[episode][0] += 1
        totals[episode][1] += amount
    ranked = sorted(((episode, values[0], values[1]) for episode, values in totals.items()), key=lambda item: (-item[1], -item[2], item[0]))
    page = ranked[offset:offset + limit]
    return [{'episode': episode, 'downloads': downloads, 'bytes': amount} for episode, downloads, amount in page]

