from datetime import date
from decimal import Decimal, ROUND_CEILING, ROUND_HALF_UP
import calendar

def _check(requester, loan):
    if requester['tenant_id'] != loan['tenant_id'] or (requester['id'] != loan['owner_id'] and 'loan_admin' not in requester['roles']):
        raise PermissionError('access denied')

def _date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    try:
        return date.fromisoformat(value)
    except ValueError:
        raise ValueError('invalid date')

def _month_after(d, n):
    m = d.month - 1 + n
    y, m = (d.year + m // 12, m % 12 + 1)
    return date(y, m, min(d.day, calendar.monthrange(y, m)[1]))

def build_repayment_schedule(requester: dict, loan: dict, extra_payment_cents: int=0) -> list[dict]:
    _check(requester, loan)
    principal = loan['principal_cents']
    rate_bps = loan['annual_rate_bps']
    term = loan['term_months']
    start = _date(loan['start_date'])
    if principal < 0 or rate_bps < 0 or term <= 0 or (not isinstance(extra_payment_cents, int)) or (extra_payment_cents < 0) or (extra_payment_cents > principal):
        raise ValueError('invalid loan')
    balance = principal - extra_payment_cents
    if balance == 0:
        return [{'due_date': _month_after(start, 1).isoformat(), 'payment_cents': extra_payment_cents, 'interest_cents': 0, 'principal_cents': principal}]
    r = Decimal(rate_bps) / Decimal(1200000)
    if r:
        regular = (Decimal(balance) * r / (Decimal(1) - (Decimal(1) + r) ** Decimal(-term))).to_integral_value(rounding=ROUND_CEILING)
    else:
        regular = (Decimal(balance) / Decimal(term)).to_integral_value(rounding=ROUND_CEILING)
    rows = []
    for i in range(term):
        interest = (Decimal(balance) * r).quantize(Decimal('1'), rounding=ROUND_HALF_UP)
        principal_part = min(balance, int(regular - interest))
        if i == 0:
            principal_part = min(balance, principal_part + extra_payment_cents)
        if i == term - 1 or principal_part >= balance:
            principal_part = balance
        payment = int(interest) + principal_part
        rows.append({'due_date': _month_after(start, i + 1).isoformat(), 'payment_cents': payment, 'interest_cents': int(interest), 'principal_cents': principal_part})
        balance -= principal_part
        if balance == 0:
            break
    return rows

def record_loan_payment(requester: dict, loan: dict, amount_cents: int, paid_on: str) -> dict:
    _check(requester, loan)
    _date(paid_on)
    if isinstance(amount_cents, bool) or not isinstance(amount_cents, int) or amount_cents <= 0:
        raise ValueError('invalid amount')
    loan['payments'].append({'amount_cents': amount_cents, 'paid_on': paid_on})
    return {'loan_id': loan['id'], 'payment_count': len(loan['payments']), 'total_paid_cents': sum((x['amount_cents'] for x in loan['payments']))}

def loan_summary(requester: dict, loan: dict) -> dict:
    _check(requester, loan)
    total = sum((x['amount_cents'] for x in loan['payments']))
    return {'loan_id': loan['id'], 'principal_cents': loan['principal_cents'], 'total_paid_cents': total, 'remaining_cents': max(loan['principal_cents'] - total, 0), 'payment_count': len(loan['payments'])}

