import csv
import os
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

def summarize_fuel_log(base_dir: str, relative_name: str, page: int=1, page_size: int=10, card_prefix: str | None=None) -> list[dict]:
    if page < 1 or page_size < 1 or page_size > 100:
        raise ValueError('invalid pagination')
    base = os.path.realpath(base_dir)
    candidate = os.path.realpath(os.path.join(base, relative_name))
    if os.path.commonpath([base, candidate]) != base:
        raise ValueError('invalid file name')
    try:
        with open(candidate, newline='', encoding='utf-8') as handle:
            reader = csv.DictReader(handle)
            required = {'card_id', 'gallons', 'price_per_gallon', 'station', 'timestamp'}
            if not reader.fieldnames or not required.issubset(reader.fieldnames):
                raise ValueError('missing columns')
            grouped = {}
            for row in reader:
                card = row.get('card_id', '')
                if not card or not row.get('gallons') or (not row.get('price_per_gallon')):
                    raise ValueError('invalid row')
                try:
                    gallons = Decimal(row['gallons'])
                    price = Decimal(row['price_per_gallon'])
                except (InvalidOperation, TypeError):
                    raise ValueError('invalid number')
                if gallons <= 0 or price <= 0:
                    raise ValueError('invalid number')
                if card_prefix is not None and (not card.startswith(card_prefix)):
                    continue
                item = grouped.setdefault(card, [0, Decimal('0'), Decimal('0')])
                item[0] += 1
                item[1] += gallons
                item[2] += gallons * price
    except (OSError, csv.Error):
        raise ValueError('invalid log')
    results = []
    for card, (count, gallons, cost) in grouped.items():
        quant = Decimal('0.01')
        results.append({'card_id': card, 'transaction_count': count, 'total_gallons': float(gallons.quantize(quant, rounding=ROUND_HALF_UP)), 'total_cost': float(cost.quantize(quant, rounding=ROUND_HALF_UP)), 'average_price': float((cost / gallons).quantize(quant, rounding=ROUND_HALF_UP))})
    results.sort(key=lambda x: (-x['total_cost'], x['card_id']))
    start = (page - 1) * page_size
    return results[start:start + page_size]

