def summarize_verified_bookings(payload: bytes, signature: str, key: bytes, page: int=1, page_size: int=10) -> dict:
    if not isinstance(signature, str) or re.fullmatch('[0-9a-f]{64}', signature) is None:
        raise ValueError('invalid signature')
    expected = hmac.new(key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(signature, expected):
        raise ValueError('invalid signature')
    if not isinstance(page, int) or isinstance(page, bool) or page < 1:
        raise ValueError('invalid pagination')
    if not isinstance(page_size, int) or isinstance(page_size, bool) or (not 1 <= page_size <= 100):
        raise ValueError('invalid pagination')
    try:
        data = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(data, dict) or not isinstance(data.get('bookings'), list):
        raise ValueError('invalid bookings')
    bookings = []
    for item in data['bookings']:
        if not isinstance(item, dict) or set(item) != {'member', 'machine', 'minutes', 'date'}:
            raise ValueError('invalid booking')
        member = item['member']
        machine = item['machine']
        minutes = item['minutes']
        date = item['date']
        if not isinstance(member, str) or not member or (not isinstance(machine, str)) or (not machine):
            raise ValueError('invalid booking')
        if not isinstance(minutes, int) or isinstance(minutes, bool) or minutes < 0:
            raise ValueError('invalid booking')
        if not isinstance(date, str) or re.fullmatch('\\d{4}-\\d{2}-\\d{2}', date) is None:
            raise ValueError('invalid booking')
        try:
            datetime.date.fromisoformat(date)
        except ValueError:
            raise ValueError('invalid booking')
        bookings.append({'member': member, 'machine': machine, 'minutes': minutes, 'date': date})
    bookings.sort(key=lambda x: (x['date'], x['machine'], x['member']))
    totals = {}
    for item in bookings:
        totals[item['machine']] = totals.get(item['machine'], 0) + item['minutes']
    start = (page - 1) * page_size
    pages = math.ceil(len(bookings) / page_size) if bookings else 0
    return {'total_minutes': sum((item['minutes'] for item in bookings)), 'machine_totals': [{'machine': name, 'minutes': totals[name]} for name in sorted(totals)], 'bookings': bookings[start:start + page_size], 'page': page, 'pages': pages}

