    except Exception:
        raise ValueError('invalid catalog')
    if not isinstance(x, dict) or not isinstance(x.get('tenant'), str) or (not x['tenant']) or (not isinstance(x.get('revision'), int)) or (not isinstance(x.get('shows'), list)):
