    directory = os.path.dirname(os.path.abspath(destination))
    temporary = tempfile.mktemp(dir=directory, prefix='.loan-report-')
    try:
        with open(temporary, 'w', newline='', encoding='utf-8') as handle:
            writer = csv.writer(handle, lineterminator='\n')
            writer.writerow(['library', 'requested', 'fulfilled', 'average_days', 'total_fee'])
            for library, values in selected:
                average = sum(values[2]) / values[1] if values[1] else 0
                writer.writerow([library, values[0], values[1], f'{average:.2f}', f'{values[3]:.2f}'])
        os.replace(temporary, destination)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return len(selected)

