import csv
import subprocess

def flight_report(path: str, event: str, window: int) -> dict:
    if not event or window <= 0:
        raise ValueError('invalid arguments')
    completed = subprocess.run(['grep', '-F', '--', event, path], capture_output=True, text=True, encoding='utf-8')
    if completed.returncode == 2:
        raise FileNotFoundError(path)
    if completed.returncode not in (0, 1):
        raise ValueError('grep failed')
    records = []
    for line in completed.stdout.splitlines():
        fields = next(csv.reader([line]))
        if len(fields) != 5:
            raise ValueError('invalid record')
        fields = [item.strip() for item in fields]
        if not fields[1] or not fields[4]:
            raise ValueError('invalid record')
        try:
            timestamp = int(fields[0])
            altitude = float(fields[2])
            speed = float(fields[3])
        except ValueError as exc:
            raise ValueError('invalid record') from exc
        if timestamp < 0 or fields[4] != event:
            continue
        records.append((timestamp, fields[1], altitude, speed))
    records.sort(key=lambda item: (item[0], item[1]))
    phases = {}
    buckets = {}
    for timestamp, phase, altitude, speed in records:
        phase_data = phases.setdefault(phase, [0, 0.0, float('-inf')])
        phase_data[0] += 1
        phase_data[1] += altitude
        phase_data[2] = max(phase_data[2], speed)
        start = timestamp // window * window
        bucket = buckets.setdefault(start, [0, 0.0])
        bucket[0] += 1
        bucket[1] += altitude
    by_phase = {}
    for phase in sorted(phases):
        count, total, maximum = phases[phase]
        by_phase[phase] = {'count': count, 'avg_altitude': round(total / count, 2), 'max_speed': maximum}
    windows = [{'start': start, 'count': values[0], 'avg_altitude': round(values[1] / values[0], 2)} for start, values in sorted(buckets.items())]
    return {'event': event, 'count': len(records), 'by_phase': by_phase, 'windows': windows}

