def summarize_reservoir(xml_text: str, page: int=1, page_size: int=10) -> dict:
    if page < 1 or page_size < 1:
        raise ValueError('invalid pagination')
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(xml_text.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'reservoir' or not root.get('name'):
        raise ValueError('invalid reservoir')
    groups = {}
    total = 0
    for node in root.findall('reading'):
        if node.get('status', 'active') == 'offline':
            continue
        station = node.get('station')
        timestamp = node.get('timestamp')
        level = node.get('level')
        flow = node.get('flow')
        if not station or timestamp is None or level is None or (flow is None):
            raise ValueError('invalid reading')
        try:
            level_value = float(level)
            flow_value = float(flow)
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid reading') from exc
        item = groups.setdefault(station, {'levels': [], 'flow': 0.0, 'latest': timestamp})
        item['levels'].append(level_value)
        item['flow'] += flow_value
        if timestamp > item['latest']:
            item['latest'] = timestamp
        total += 1
    stations = []
    for station, item in groups.items():
        stations.append({'station': station, 'readings': len(item['levels']), 'average_level': round(sum(item['levels']) / len(item['levels']), 2), 'total_flow': round(item['flow'], 2), 'latest': item['latest']})
    stations.sort(key=lambda x: (-1,))
    stations.sort(key=lambda x: x['station'])
    stations.sort(key=lambda x: x['latest'], reverse=True)
    start = (page - 1) * page_size
    return {'reservoir': root.get('name'), 'total_readings': total, 'total_stations': len(stations), 'stations': stations[start:start + page_size]}

