from lxml import etree
import re

def _parse_root(xml):
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        return etree.fromstring(xml.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid XML') from exc

def _required_text(node):
    if node is None or node.text is None:
        raise ValueError('missing text')
    value = node.text.strip()
    if not value:
        raise ValueError('empty text')
    return value

def parse_purchase_order(xml: str) -> dict:
    root = _parse_root(xml)
    if root.tag != 'purchase_order':
        raise ValueError('wrong root')
    order_id = root.get('id', '').strip()
    currency = root.get('currency', '')
    if not order_id or not re.fullmatch('[A-Z]{3}', currency):
        raise ValueError('invalid attributes')
    supplier = root.find('supplier')
    name = _required_text(supplier.find('name') if supplier is not None else None)
    lines_node = root.find('lines')
    if lines_node is None:
        raise ValueError('missing lines')
    lines = []
    seen = set()
    for node in lines_node.findall('line'):
        sku = node.get('sku', '').strip()
        qty_text = node.get('qty', '')
        price_text = node.get('unit_price', '')
        if not sku or sku in seen or (not re.fullmatch('[1-9][0-9]*', qty_text)):
            raise ValueError('invalid line')
        if not re.fullmatch('[0-9]+(?:\\.[0-9]{1,2})?', price_text):
            raise ValueError('invalid price')
        whole, _, frac = price_text.partition('.')
        cents = int(whole) * 100 + int((frac + '00')[:2])
        qty = int(qty_text)
        seen.add(sku)
        lines.append({'sku': sku, 'quantity': qty, 'unit_price_cents': cents, 'line_total_cents': qty * cents})
    if not lines:
        raise ValueError('empty lines')
    return {'order_id': order_id, 'supplier': name, 'currency': currency, 'lines': lines, 'total_cents': sum((x['line_total_cents'] for x in lines))}

def consolidate_orders(xml_documents: list[str]) -> list[dict]:
    groups = {}
    ids = set()
    for xml in xml_documents:
        root = _parse_root(xml)
        if root.tag != 'orders':
            raise ValueError('wrong root')
        for child in root:
            if child.tag != 'purchase_order':
                raise ValueError('invalid child')
            order = parse_purchase_order(etree.tostring(child, encoding='unicode'))
            if order['order_id'] in ids:
                raise ValueError('duplicate order')
            ids.add(order['order_id'])
            key = (order['supplier'], order['currency'])
            group = groups.setdefault(key, {'supplier': key[0], 'currency': key[1], 'order_count': 0, 'total_cents': 0, 'sku_quantities': {}})
            group['order_count'] += 1
            group['total_cents'] += order['total_cents']
            for line in order['lines']:
                group['sku_quantities'][line['sku']] = group['sku_quantities'].get(line['sku'], 0) + line['quantity']
    result = []
    for group in groups.values():
        group['sku_quantities'] = [{'sku': sku, 'quantity': qty} for sku, qty in sorted(group['sku_quantities'].items(), key=lambda x: (-x[1], x[0]))]
        result.append(group)
    return sorted(result, key=lambda x: (-x['total_cents'], x['supplier'], x['currency']))

