import subprocess
from datetime import date, time

def _fields(line):
    out = []
    cur = []
    escaped = False
    for ch in line:
        if escaped:
            if ch not in ('\\', '|'):
                raise ValueError('invalid escape')
            cur.append(ch)
            escaped = False
        elif ch == '\\':
            escaped = True
        elif ch == '|':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(ch)
    if escaped:
        raise ValueError('invalid escape')
    out.append(''.join(cur))
    return out

def parse_itinerary(text: str) -> list[dict]:
    if not isinstance(text, str):
        raise TypeError('text must be a string')
    result = []
    for raw in text.splitlines():
        if not raw:
            continue
        fields = _fields(raw)
        if len(fields) != 5 or not fields[2] or (not fields[3]):
            raise ValueError('invalid record')
        try:
            y, m, d = (int(x) for x in fields[0].split('-'))
            hh, mm = (int(x) for x in fields[1].split(':'))
            day = date(y, m, d)
            clock = time(hh, mm)
            minutes = int(fields[4])
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if minutes < 0:
            raise ValueError('invalid minutes')
        result.append({'date': day, 'time': clock, 'destination': fields[2], 'activity': fields[3], 'minutes': minutes})
    return result

def itinerary_report(path: str) -> str:
    try:
        completed = subprocess.run(['sort', '--', path], check=True, capture_output=True, text=True, encoding='utf-8', env={'LC_ALL': 'C'})
        records = parse_itinerary(completed.stdout)
    except (OSError, subprocess.CalledProcessError, UnicodeError, ValueError, TypeError):
        raise ValueError('unable to read itinerary')
    records.sort(key=lambda r: (r['date'], r['time']))
    groups = {}
    for record in records:
        group = groups.setdefault(record['date'], [0, 0, []])
        group[0] += record['minutes']
        group[1] += 1
        if record['destination'] not in group[2]:
            group[2].append(record['destination'])
    return '\n'.join((f"{day.isoformat()}: {v[0]} minutes, {v[1]} stops, destinations: {', '.join(v[2])}" for day, v in sorted(groups.items())))

