            cid = campaign['id']
            if cid in by_id:
                raise ValueError('duplicate campaign')
            by_id[cid] = campaign
        except (KeyError, TypeError):
            raise ValueError('invalid campaign')
    if not isinstance(requester, dict):
        raise ValueError('invalid requester')
    result = {}
    for event in events:
        try:
            cid = event['campaign_id']
            when = datetime.fromisoformat(event['occurred_at'])
            cents = event['revenue_cents']
            if type(cents) is not int or cents < 0:
                raise ValueError('invalid revenue')
        except (KeyError, TypeError, ValueError):
            raise ValueError('invalid event')
        campaign = by_id.get(cid)
        if campaign is None or not begin <= when < finish:
            continue
        allowed = campaign['tenant_id'] == requester.get('tenant_id') and (campaign['owner_id'] == requester.get('id') or 'analyst' in requester.get('roles', []))
