import math
import xml.etree.ElementTree as ET

def parse_observations(xml_text: str) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except Exception as exc:
        raise ValueError('invalid XML') from exc
    if root.tag != 'survey':
        raise ValueError('invalid root')
    result = []
    allowed = {'id', 'epoch', 'elevation', 'weight'}
    for child in root:
        if child.tag != 'observation' or list(child) or set(child.attrib) != allowed.intersection(child.attrib):
            raise ValueError('invalid observation')
        if set(child.attrib) - allowed or 'id' not in child.attrib or 'epoch' not in child.attrib or ('elevation' not in child.attrib):
            raise ValueError('missing attribute')
        try:
            epoch = int(child.attrib['epoch'], 10)
            elevation = float(child.attrib['elevation'])
            weight = float(child.attrib.get('weight', '1.0'))
        except Exception as exc:
            raise ValueError('invalid value') from exc
        if not math.isfinite(elevation) or not math.isfinite(weight) or weight <= 0:
            raise ValueError('invalid number')
        result.append({'id': child.attrib['id'], 'epoch': epoch, 'elevation': elevation, 'weight': weight})
    return result

def compute_settlement_report(xml_text: str, window: int=3) -> dict:
    if isinstance(window, bool) or not isinstance(window, int) or window < 1:
        raise ValueError('invalid window')
    observations = parse_observations(xml_text)
    if not observations:
        raise ValueError('empty survey')
    groups = {}
    for item in observations:
        groups.setdefault(item['id'], []).append(item)
    points = []
    for ident in sorted(groups):
        items = groups[ident]
        total = sum((x['weight'] for x in items))
        mean = sum((x['elevation'] * x['weight'] for x in items)) / total
        rms = math.sqrt(sum((x['weight'] * (x['elevation'] - mean) ** 2 for x in items)) / total)
        latest = max(enumerate(items), key=lambda z: (z[1]['epoch'], z[0]))[1]['elevation']
        points.append({'id': ident, 'count': len(items), 'mean': mean, 'rms': rms, 'latest': latest})
    ordered = sorted(enumerate(observations), key=lambda z: (z[1]['epoch'], z[0]))
    values = []
    for end in range(len(ordered)):
        batch = [x[1] for x in ordered[max(0, end + 1 - window):end + 1]]
        total = sum((x['weight'] for x in batch))
        values.append(sum((x['elevation'] * x['weight'] for x in batch)) / total)
    elevations = [x['elevation'] for x in observations]
    return {'points': points, 'window_means': values, 'range': [min(elevations), max(elevations)]}

