import hashlib
import secrets
from datetime import datetime

def issue_ticket(ticket_id: str, skier: str, pin: str, ride_events: list[dict]) -> dict:
    if not isinstance(ticket_id, str) or not ticket_id:
        raise ValueError('invalid ticket id')
    if not isinstance(skier, str) or not skier:
        raise ValueError('invalid skier')
    if not isinstance(pin, str) or not pin.isdigit() or (not 4 <= len(pin) <= 12):
        raise ValueError('invalid pin')
    if not isinstance(ride_events, list):
        raise ValueError('invalid rides')
    rides = []
    for event in ride_events:
        if not isinstance(event, dict) or set(event) != {'lift', 'at'}:
            raise ValueError('invalid ride')
        if not isinstance(event['lift'], str) or not event['lift']:
            raise ValueError('invalid lift')
        if not isinstance(event['at'], str):
            raise ValueError('invalid time')
        try:
            parsed = datetime.fromisoformat(event['at'])
        except (TypeError, ValueError):
            raise ValueError('invalid time')
        rides.append((parsed, {'lift': event['lift'], 'at': event['at']}))
    rides.sort(key=lambda x: x[0])
    salt = secrets.token_bytes(16)
    digest = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
    return {'ticket_id': ticket_id, 'skier': skier, 'rides': [x[1] for x in rides], 'salt': salt.hex(), 'pin_hash': digest.hex()}

def verify_ticket(ticket: dict, pin: str) -> bool:
    try:
        if not isinstance(ticket, dict) or not isinstance(pin, str):
            return False
        salt = bytes.fromhex(ticket['salt'])
        expected = bytes.fromhex(ticket['pin_hash'])
        actual = hashlib.pbkdf2_hmac('sha256', pin.encode(), salt, 100000)
        return secrets.compare_digest(actual, expected)
    except (KeyError, TypeError, ValueError):
        return False

def summarize_lifts(tickets: list[dict], day: str, rates: dict[str, int]) -> list[dict]:
    try:
        datetime.strptime(day, '%Y-%m-%d')
    except (TypeError, ValueError):
        raise ValueError('invalid day')
    totals = {}
    for ticket in tickets:
        if not isinstance(ticket, dict) or not isinstance(ticket.get('rides'), list):
            continue
        for ride in ticket['rides']:
            try:
                when = datetime.fromisoformat(ride['at'])
                lift = ride['lift']
                rate = rates[lift]
                if when.date().isoformat() == day:
                    count, revenue = totals.get(lift, (0, 0))
                    totals[lift] = (count + 1, revenue + rate)
            except (KeyError, TypeError, ValueError):
                continue
    return [{'lift': lift, 'rides': count, 'revenue': revenue} for lift, (count, revenue) in sorted(totals.items(), key=lambda x: (-x[1][1], -x[1][0], x[0]))]

