def verify_and_parse_report(payload: bytes, signature: str, signing_key: bytes) -> dict:
    if not isinstance(payload, bytes) or not isinstance(signature, str) or (not isinstance(signing_key, bytes)):
        raise ValueError('invalid input')
    if not signing_key or not signature or len(signature) != hashlib.sha256().digest_size * 2:
        raise ValueError('invalid signature')
    try:
        int(signature, 16)
    except ValueError:
        raise ValueError('invalid signature')
    expected = hmac.new(signing_key, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected, signature):
        raise ValueError('invalid signature')
    try:
        report = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid report')
    if not isinstance(report, dict) or set(report) != {'campaign_id', 'impressions', 'clicks', 'spend'}:
        raise ValueError('invalid report')
    if not isinstance(report['campaign_id'], str) or not report['campaign_id']:
        raise ValueError('invalid report')
    for field in ('impressions', 'clicks'):
        if isinstance(report[field], bool) or not isinstance(report[field], int) or report[field] < 0:
            raise ValueError('invalid report')
    spend = report['spend']
    if isinstance(spend, bool) or not isinstance(spend, (int, float)) or (not math.isfinite(spend)) or (spend < 0):
        raise ValueError('invalid report')
    return report

