import math
import subprocess

def summarize_observations(path: str, species: str | None=None, min_depth: float=0.0, page: int=1, page_size: int=10) -> list[dict]:
    if isinstance(page, bool) or not isinstance(page, int) or page <= 0:
        raise ValueError('page must be positive')
    if isinstance(page_size, bool) or not isinstance(page_size, int) or page_size <= 0:
        raise ValueError('page_size must be positive')
    if not isinstance(min_depth, (int, float)) or isinstance(min_depth, bool) or (not math.isfinite(min_depth)):
        raise ValueError('min_depth must be finite')
    result = subprocess.run(['sort', '-t,', '-k1,1', path], check=True, capture_output=True, text=True)
    groups = {}
    for row in csv.reader(result.stdout.splitlines()):
        if not row or all((not part.strip() for part in row)):
            continue
        if len(row) != 3:
            raise ValueError('malformed record')
        name = row[0]
        try:
            depth = float(row[1])
            count = int(row[2])
        except ValueError as exc:
            raise ValueError('malformed record') from exc
        if not name or depth < 0 or count < 0:
            raise ValueError('invalid record')
        if species is not None and name != species:
            continue
        if depth < min_depth:
            continue
        groups.setdefault(name, []).append((depth, count))
    records = []
    for name in sorted(groups):
        values = groups[name]
        records.append({'species': name, 'observations': len(values), 'total_count': sum((v[1] for v in values)), 'average_depth': round(sum((v[0] for v in values)) / len(values), 2)})
    start = (page - 1) * page_size
    return records[start:start + page_size]

