from solution import verify_and_parse, aggregate_analytics
import hashlib
import hmac
import json
import pytest

def make_payload(events):
    return json.dumps({'events': events}, separators=(',', ':')).encode()

def signed_headers(payload, secret):
    digest = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    return {'X-Podcast-Signature': 'sha256=' + digest}

def event(podcast, episode, listener, timestamp, seconds, completed):
    return {'podcast': podcast, 'episode': episode, 'listener': listener, 'timestamp': timestamp, 'seconds': seconds, 'completed': completed}

def test_verify_and_parse_accepts_signed_payload_and_preserves_order():
    events = [event('daily', 'ep2', 'u2', '2024-01-01T00:01:00Z', 30, False), event('news', 'ep1', 'u1', '2024-01-01T00:02:00Z', 60, True)]
    payload = make_payload(events)
    assert verify_and_parse(payload, signed_headers(payload, b'secret'), b'secret') == events

def test_verify_and_parse_rejects_missing_or_wrong_signature():
    payload = make_payload([])
    with pytest.raises(ValueError):
        verify_and_parse(payload, {}, b'secret')
    with pytest.raises(ValueError):
        verify_and_parse(payload, {'X-Podcast-Signature': 'sha256=' + '0' * 64}, b'secret')

def test_verify_and_parse_rejects_bad_header_and_bad_json():
    payload = make_payload([])
    for header in ['', 'sha1=abc', 'sha256=xyz', 'sha256=' + 'a' * 63]:
        with pytest.raises(ValueError):
            verify_and_parse(payload, {'X-Podcast-Signature': header}, b'secret')
    bad = b'not json'
    with pytest.raises(ValueError):
        verify_and_parse(bad, signed_headers(bad, b'secret'), b'secret')

def test_verify_and_parse_rejects_invalid_top_level_and_utf8():
    for value in [[], {'events': {}}, {'other': []}]:
        payload = json.dumps(value).encode()
        with pytest.raises(ValueError):
            verify_and_parse(payload, signed_headers(payload, b'x'), b'x')
    payload = b'\xff'
    with pytest.raises(ValueError):
        verify_and_parse(payload, signed_headers(payload, b'x'), b'x')

def test_aggregate_combines_events_and_counts_distinct_listeners():
    events = [event('show', 'a', 'alice', '2024-01-01T00:00:01Z', 40, True), event('show', 'b', 'alice', '2024-01-01T00:10:00Z', 20, False), event('show', 'a', 'bob', '2024-01-01T00:59:59Z', 10, True)]
    assert aggregate_analytics(events) == [{'podcast': 'show', 'window_start': '2024-01-01T00:00:00Z', 'downloads': 3, 'total_seconds': 70, 'unique_listeners': 2, 'completed_downloads': 2}]

def test_aggregate_sorting_uses_seconds_then_podcast_then_window():
    events = [event('zeta', 'e', 'u', '2024-01-01T00:00:00Z', 10, False), event('alpha', 'e', 'u', '2024-01-01T00:00:00Z', 10, False), event('alpha', 'e', 'u', '2024-01-01T02:00:00Z', 10, False)]
    result = aggregate_analytics(events)
    assert [(x['podcast'], x['window_start']) for x in result] == [('alpha', '2024-01-01T00:00:00Z'), ('alpha', '2024-01-01T02:00:00Z'), ('zeta', '2024-01-01T00:00:00Z')]

def test_aggregate_rejects_invalid_events_and_window():
    base = event('show', 'e', 'u', '2024-01-01T00:00:00Z', 2, False)
    for bad in [{**base, 'seconds': -1}, {**base, 'completed': 1}, {**base, 'podcast': ''}, {**base, 'timestamp': '2024-01-01T00:00:00'}, {k: v for k, v in base.items() if k != 'listener'}]:
        with pytest.raises(ValueError):
            aggregate_analytics([bad])
    for width in [0, -1, True, 1.5]:
        with pytest.raises(ValueError):
            aggregate_analytics([base], width)

