import hashlib
import hmac
import json
from datetime import datetime, timezone

def verify_and_parse(payload: bytes, headers: dict[str, str], secret: bytes) -> list[dict]:
    value = headers.get('X-Podcast-Signature')
    if not isinstance(value, str) or not value.startswith('sha256='):
        raise ValueError('invalid signature')
    supplied = value[7:]
    if len(supplied) != 64 or any((c not in '0123456789abcdef' for c in supplied)):
        raise ValueError('invalid signature')
    expected = hmac.new(secret, payload, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(supplied, expected):
        raise ValueError('invalid signature')
    try:
        document = json.loads(payload.decode('utf-8'))
    except (UnicodeDecodeError, json.JSONDecodeError):
        raise ValueError('invalid payload')
    if not isinstance(document, dict) or not isinstance(document.get('events'), list):
        raise ValueError('invalid payload')
    return document['events']

def aggregate_analytics(events: list[dict], window_seconds: int=3600) -> list[dict]:
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, int) or window_seconds <= 0:
        raise ValueError('invalid window')
    groups = {}
    for item in events:
        if not isinstance(item, dict):
            raise ValueError('invalid event')
        required = ('podcast', 'episode', 'listener', 'timestamp', 'seconds', 'completed')
        if any((k not in item for k in required)):
            raise ValueError('invalid event')
        if any((not isinstance(item[k], str) or not item[k] for k in ('podcast', 'episode', 'listener'))):
            raise ValueError('invalid event')
        if isinstance(item['seconds'], bool) or not isinstance(item['seconds'], int) or item['seconds'] < 0:
            raise ValueError('invalid event')
        if not isinstance(item['completed'], bool):
            raise ValueError('invalid event')
        try:
            stamp = item['timestamp']
            if not isinstance(stamp, str) or not stamp.endswith('Z'):
                raise ValueError
            dt = datetime.fromisoformat(stamp[:-1] + '+00:00')
            if dt.tzinfo is None or dt.utcoffset() != timezone.utc.utcoffset(dt):
                raise ValueError
            epoch = int(dt.timestamp())
        except (ValueError, TypeError, OverflowError):
            raise ValueError('invalid event')
        start = epoch - epoch % window_seconds
        key = (item['podcast'], start)
        if key not in groups:
            groups[key] = {'listeners': set(), 'downloads': 0, 'total_seconds': 0, 'completed_downloads': 0}
        group = groups[key]
        group['listeners'].add(item['listener'])
        group['downloads'] += 1
        group['total_seconds'] += item['seconds']
        group['completed_downloads'] += int(item['completed'])
    rows = []
    for (podcast, start), group in groups.items():
        rows.append({'podcast': podcast, 'window_start': datetime.fromtimestamp(start, timezone.utc).isoformat().replace('+00:00', 'Z'), 'downloads': group['downloads'], 'total_seconds': group['total_seconds'], 'unique_listeners': len(group['listeners']), 'completed_downloads': group['completed_downloads']})
    return sorted(rows, key=lambda row: (-row['total_seconds'], row['podcast'], row['window_start']))

