def parse_event(line: str) -> dict:
    fields = []
    key = []
    value = []
    in_value = False
    escaped = False
    for char in line + ';':
        if escaped:
            (value if in_value else key).append(char)
            escaped = False
        elif char == '\\':
            escaped = True
        elif not in_value and char == '=':
            in_value = True
        elif char == ';':
            if not in_value or not key:
                raise ValueError('malformed field')
            fields.append((''.join(key), ''.join(value)))
            key, value, in_value = ([], [], False)
        else:
            (value if in_value else key).append(char)
    if escaped or len(fields) != 5:
        raise ValueError('malformed record')
    data = dict(fields)
