            raise ValueError('invalid row')
        result.append({'permit_id': permit_id, 'owner_id': owner_id, 'tenant': tenant, 'area': area, 'risk': risk})
    if not result or len({x['permit_id'] for x in result}) != len(result):
        raise ValueError('invalid permits')
    return sorted(result, key=lambda x: x['permit_id'])

class PermitBook:

    def __init__(self, records: list[dict]):
        self.records = {}
        for item in records:
            r = copy.deepcopy(item)
            if any((k not in r for k in ('permit_id', 'owner_id', 'tenant', 'area', 'risk'))):
                raise ValueError('incomplete record')
            if r['permit_id'] in self.records or float(r['area']) <= 0:
                raise ValueError('invalid record')
            r['area'] = float(r['area'])
            r.setdefault('status', 'pending')
            r.setdefault('history', [])
            self.records[r['permit_id']] = r

