            raise PermissionError('not permitted')
        record['status'] = 'approved' if decision == 'approve' else 'denied'
        record['history'].append({'actor': requester['id'], 'decision': decision})
        return copy.deepcopy(record)

    def summary(self, tenant: str | None=None) -> list[dict]:
        groups = {}
        for r in self.records.values():
            if tenant is not None and r['tenant'] != tenant:
                continue
            g = groups.setdefault(r['tenant'], {'tenant': r['tenant'], 'total': 0, 'pending': 0, 'approved': 0, 'denied': 0, 'area': 0.0})
