    eligible.sort(key=lambda x: (-x[1]['score'], -x[1]['activity'], -x[2], x[1]['user']))
    granted, waitlisted = ([], [])
    for _, r, _ in eligible:
        if r['requested'] <= seats:
            granted.append(r['user'])
            seats -= r['requested']
        else:
            waitlisted.append(r['user'])
