from datetime import datetime, timezone
import requests

def _time(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)
    except (AttributeError, TypeError, ValueError):
        raise ValueError('invalid timestamp')

def fetch_robot_events(api_url: str, fleet_id: str, since: str, until: str, token: str) -> list[dict]:
    response = requests.get(api_url.rstrip('/') + '/fleets/' + fleet_id + '/events', params={'since': since, 'until': until}, headers={'Authorization': 'Bearer ' + token})
    if response.status_code != 200:
        raise RuntimeError('fleet request failed: ' + str(response.status_code))
    try:
        data = response.json()
        robots = data['robots']
        if not isinstance(data, dict) or not isinstance(robots, list):
            raise ValueError
        result = []
        for robot in robots:
            if not isinstance(robot, dict) or not isinstance(robot.get('events'), list) or 'robot_id' not in robot:
                raise ValueError
            for event in robot['events']:
                if not isinstance(event, dict) or not all((k in event for k in ('timestamp', 'status', 'battery'))):
                    raise ValueError
                item = event.copy()
                item['robot_id'] = robot['robot_id']
                result.append(item)
        result.sort(key=lambda x: (x['timestamp'], x['robot_id']))
        return result
    except (KeyError, TypeError, ValueError):
        raise ValueError('invalid response')

def summarize_robot_events(events: list[dict], window_minutes: int=15) -> list[dict]:
    if isinstance(window_minutes, bool) or not isinstance(window_minutes, int) or window_minutes <= 0:
        raise ValueError('invalid window')
    groups = {}
    span = window_minutes * 60
    for index, event in enumerate(events):
        if not isinstance(event, dict) or not all((k in event for k in ('robot_id', 'timestamp', 'status', 'battery'))):
            raise ValueError('invalid event')
        moment = _time(event['timestamp'])
        battery = event['battery']
        if isinstance(battery, bool) or not isinstance(battery, (int, float)):
            raise ValueError('invalid battery')
        epoch = int(moment.timestamp())
        start = datetime.fromtimestamp(epoch - epoch % span, timezone.utc)
        key = (event['robot_id'], start)
        groups.setdefault(key, []).append((moment, index, event))
    output = []
    for (robot, start), items in groups.items():
        counts = {}
        for _, _, event in items:
            counts[event['status']] = counts.get(event['status'], 0) + 1
        counts = dict(sorted(counts.items()))
        latest = max(items, key=lambda x: (x[0], x[1]))[2]['status']
        output.append({'robot_id': robot, 'window_start': start.strftime('%Y-%m-%dT%H:%M:%SZ'), 'event_count': len(items), 'statuses': counts, 'average_battery': round(sum((x[2]['battery'] for x in items)) / len(items), 2), 'latest_status': latest})
    output.sort(key=lambda x: (x['window_start'], x['robot_id']))
    return output

