from solution import verify_and_parse, reconcile_payments
import hashlib
import hmac
import json
import pytest

def make_payload(events):
    return json.dumps(events, separators=(',', ':')).encode()

def signed(payload, secret=b'provider-key'):
    return 'sha256=' + hmac.new(secret, payload, hashlib.sha256).hexdigest()

def event(i, provider, amount, currency, status, timestamp):
    return {'id': i, 'provider': provider, 'amount': amount, 'currency': currency, 'status': status, 'timestamp': timestamp}

def test_verify_and_parse_accepts_bytes_and_preserves_values():
    items = [event('a', 'stripe', 1250, 'USD', 'paid', '2025-01-02T09:10:11Z')]
    payload = make_payload(items)
    assert verify_and_parse(payload, signed(payload), b'provider-key') == items

def test_verify_and_parse_rejects_bad_signature_forms():
    payload = make_payload([])
    for signature in ['', 'sha256=', 'sha256=' + '0' * 63, 'md5=' + '0' * 32, 'sha256=' + 'G' * 64]:
        with pytest.raises(ValueError):
            verify_and_parse(payload, signature, b'provider-key')

def test_verify_and_parse_rejects_bad_json_utf8_and_top_level():
    for payload in [b'{', b'\xff', b'{}']:
        with pytest.raises(ValueError):
            verify_and_parse(payload, signed(payload), b'provider-key')

def test_reconcile_replacement_sorting_and_aggregation():
    events = [event('x', 'zeta', 900, 'USD', 'paid', '2025-01-02T12:00:00Z'), event('x', 'zeta', 700, 'USD', 'refunded', '2025-01-02T13:00:00Z'), event('b', 'beta', 250, 'EUR', 'paid', '2025-01-01T10:00:00Z'), event('a', 'alpha', 100, 'USD', 'paid', '2025-01-01T09:00:00Z'), event('f', 'alpha', 80, 'EUR', 'failed', '2025-01-02T08:00:00Z')]
    assert reconcile_payments(events, 1000) == {'balance': 650, 'by_currency': {'EUR': 250, 'USD': -600}, 'daily': {'2025-01-01': 350, '2025-01-02': -700}}

def test_equal_timestamp_later_input_wins():
    first = event('same', 'p', 10, 'USD', 'paid', '2025-04-01T01:00:00Z')
    second = event('same', 'p', 30, 'USD', 'refunded', '2025-04-01T01:00:00Z')
    assert reconcile_payments([first, second]) == {'balance': -30, 'by_currency': {'USD': -30}, 'daily': {'2025-04-01': -30}}

def test_reconcile_rejects_invalid_events_and_opening_balance():
    base = event('a', 'p', 1, 'USD', 'paid', '2025-01-01T00:00:00Z')
    bads = [{**base, 'amount': True}, {**base, 'currency': 'usd'}, {**base, 'status': 'pending'}, {**base, 'timestamp': '2025-01-01'}, {**base, 'id': ''}, {**base, 'amount': -1}]
