import csv
import io
import os
import zipfile
from datetime import datetime, timedelta

def parse_bookings(csv_text: str) -> list[dict]:
    lines = [x for x in csv_text.splitlines() if x.strip()]
    if not lines:
        return []
    reader = csv.reader(io.StringIO('\n'.join(lines)))
    rows = list(reader)
    if rows[0] != ['client', 'trainer', 'start', 'end', 'status']:
        raise ValueError('invalid header')
    result = []
    for row in rows[1:]:
        if len(row) != 5:
            raise ValueError('invalid row')
        client, trainer, start, end, status = [x.strip() for x in row]
        try:
            a, b = (datetime.fromisoformat(start), datetime.fromisoformat(end))
        except Exception as e:
            raise ValueError('invalid timestamp') from e
        if not client or not trainer or b <= a or (status not in ('confirmed', 'cancelled')):
            raise ValueError('invalid booking')
        result.append({'client': client, 'trainer': trainer, 'start': a.isoformat(), 'end': b.isoformat(), 'status': status})
    return result

def aggregate_bookings(bookings: list[dict], window_days: int=7) -> list[dict]:
    if not isinstance(window_days, int) or isinstance(window_days, bool) or window_days <= 0:
        raise ValueError('invalid window')
    if not bookings:
        return []
    checked = parse_bookings('client,trainer,start,end,status\n' + '\n'.join((','.join((r[k] for k in ('client', 'trainer', 'start', 'end', 'status'))) for r in bookings)))
    start = min((datetime.fromisoformat(r['start']) for r in checked))
    limit = start + timedelta(days=window_days)
    groups = {}
    for r in checked:
        a, b = (datetime.fromisoformat(r['start']), datetime.fromisoformat(r['end']))
        if not start <= a < limit:
            continue
        g = groups.setdefault(r['trainer'], {'trainer': r['trainer'], 'confirmed_hours': 0.0, 'confirmed_count': 0, 'days': {}})
        if r['status'] == 'confirmed':
            g['confirmed_count'] += 1
            g['confirmed_hours'] += (b - a).total_seconds() / 3600
            d = a.date()
            while d < b.date():
                nxt = datetime.combine(d + timedelta(days=1), datetime.min.time(), tzinfo=a.tzinfo)
                g['days'][d.isoformat()] = g['days'].get(d.isoformat(), 0) + (nxt - a).total_seconds() / 3600
                a, d = (nxt, d + timedelta(days=1))
            g['days'][d.isoformat()] = g['days'].get(d.isoformat(), 0) + (b - a).total_seconds() / 3600
    for g in groups.values():
        g['confirmed_hours'] = round(g['confirmed_hours'], 2)
        g['days'] = {k: round(g['days'][k], 2) for k in sorted(g['days'])}
    return sorted(groups.values(), key=lambda x: (-x['confirmed_hours'], x['trainer']))

def extract_booking_files(zip_path: str, destination: str) -> list[str]:
    os.makedirs(destination, exist_ok=True)
    base = os.path.realpath(destination)
    result = []
    seen = set()
    with zipfile.ZipFile(zip_path) as z:
        for info in z.infolist():
            name = info.filename.replace('\\', '/')
            if name.endswith('/'):
                target = os.path.realpath(os.path.join(base, name))
                if os.path.commonpath((base, target)) != base:
                    raise ValueError('invalid member')
                os.makedirs(target, exist_ok=True)
                continue
            target = os.path.realpath(os.path.join(base, name))
            if os.path.commonpath((base, target)) != base:
                raise ValueError('invalid member')
            rel = os.path.relpath(target, base).replace(os.sep, '/')
            if rel in seen:
                raise ValueError('duplicate member')
            seen.add(rel)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with z.open(info) as src, open(target, 'wb') as dst:
                dst.write(src.read())
            result.append(rel)
    return sorted(result)

