import zipfile
from decimal import Decimal, ROUND_HALF_UP
from datetime import datetime

def extract_energy_reports(archive_path: str, output_dir: str, members: list[str]) -> list[str]:
    if not members or len(members) != len(set(members)):
        raise ValueError('invalid members')
    base = os.path.realpath(output_dir)
    result = []
    with zipfile.ZipFile(archive_path) as zf:
        names = set(zf.namelist())
        for member in members:
            if member not in names or member.endswith('/'):
                raise ValueError('invalid member')
            target = os.path.realpath(os.path.join(base, member))
            if os.path.commonpath([base, target]) != base:
                raise ValueError('invalid member')
            os.makedirs(os.path.dirname(target), exist_ok=True)
            with zf.open(member) as src, open(target, 'wb') as dst:
                dst.write(src.read())
            result.append(target)
    return sorted(result)

def summarize_readings(paths: list[str]) -> list[dict[str, object]]:
    data = {}
    for path in paths:
        try:
            with open(path, encoding='utf-8', newline='') as f:
                reader = csv.reader(f)
                if next(reader, None) != ['timestamp', 'meter', 'kwh']:
                    raise ValueError('header')
                count = 0
                for row in reader:
                    if not row or all((not x for x in row)):
                        continue
                    if len(row) != 3 or not row[1]:
                        raise ValueError('row')
                    try:
                        stamp = datetime.fromisoformat(row[0].replace('Z', '+00:00'))
                        value = Decimal(row[2])
                    except Exception as exc:
                        raise ValueError('row') from exc
                    if value < 0:
                        raise ValueError('value')
                    data.setdefault(row[1], []).append((stamp, row[0], value))
                    count += 1
                if not count:
                    raise ValueError('empty')
        except OSError as exc:
            raise ValueError('file') from exc
    answer = []
    for meter in sorted(data):
        rows = data[meter]
        total = sum((x[2] for x in rows), Decimal('0'))
        peak = max(rows, key=lambda x: (x[2], -x[0].timestamp()))
        q = Decimal('0.001')
        answer.append({'meter': meter, 'total_kwh': float(total.quantize(q, rounding=ROUND_HALF_UP)), 'average_kwh': float((total / len(rows)).quantize(q, rounding=ROUND_HALF_UP)), 'peak_kwh': float(peak[2].quantize(q, rounding=ROUND_HALF_UP)), 'peak_timestamp': peak[1], 'readings': len(rows)})
    return answer

