import os
import re
import subprocess
from datetime import datetime

def collect_findings(path: str, pattern: str) -> list[dict]:
    if not os.path.isfile(path):
        raise FileNotFoundError(path)
    try:
        re.compile(pattern)
    except re.error as exc:
        raise ValueError(str(exc)) from exc
    result = subprocess.run(['grep', '-n', '-E', pattern, path], capture_output=True, text=True)
    if result.returncode == 1:
        return []
    if result.returncode != 0:
        raise ValueError(result.stderr.strip() or 'grep failed')
    output = []
    for row in result.stdout.splitlines():
        number, content = row.split(':', 1)
        parts = content.split('|', 3)
        if len(parts) != 4:
            continue
        date, control, severity, message = parts
        if severity not in {'LOW', 'MEDIUM', 'HIGH', 'CRITICAL'} or not control:
            continue
        try:
            datetime.strptime(date, '%Y-%m-%d')
        except ValueError:
            continue
        output.append({'line': int(number), 'date': date, 'control': control, 'severity': severity, 'message': message})
    return output

def summarize_findings(findings: list[dict], limit: int | None=None) -> list[dict]:
    if limit is not None and (not isinstance(limit, int) or isinstance(limit, bool) or limit < 0):
        raise ValueError('limit must be nonnegative or None')
    ranks = {'LOW': 0, 'MEDIUM': 1, 'HIGH': 2, 'CRITICAL': 3}
    groups = {}
    for item in findings:
        control = item['control']
        if control not in groups:
            groups[control] = {'items': [], 'messages': []}
        group = groups[control]
        group['items'].append(item)
        if item['message'] not in group['messages']:
            group['messages'].append(item['message'])
    result = []
    for control, group in groups.items():
        items = group['items']
        result.append({'control': control, 'count': len(items), 'max_severity': max((x['severity'] for x in items), key=ranks.get), 'first_line': min((x['line'] for x in items)), 'dates': sorted({x['date'] for x in items}), 'messages': group['messages']})
    result.sort(key=lambda x: (-x['count'], x['control']))
    return result if limit is None else result[:limit]

