import json
import subprocess

def load_flags(path: str) -> dict:
    try:
        with open(path, encoding='utf-8') as f:
            data = json.load(f)
        items = data['flags']
        if not isinstance(items, list):
            raise ValueError
        result = {}
        for item in items:
            if not isinstance(item, dict) or not isinstance(item.get('name'), str) or (not item['name']) or (not isinstance(item.get('enabled'), bool)):
                raise ValueError
            rollout = item.get('rollout', 100)
            allows = item.get('allow_users', [])
            denies = item.get('deny_users', [])
            if isinstance(rollout, bool) or not isinstance(rollout, int) or (not 0 <= rollout <= 100) or (not isinstance(allows, list)) or (not isinstance(denies, list)) or (not all((isinstance(x, str) for x in allows + denies))) or (item['name'] in result):
                raise ValueError
            result[item['name']] = {'enabled': item['enabled'], 'rollout': rollout, 'allow_users': list(allows), 'deny_users': list(denies)}
        return result
    except (OSError, ValueError, TypeError, KeyError, json.JSONDecodeError) as e:
        raise ValueError from e

def build_flag_report(flags_path: str, events_path: str, limit: int) -> list[dict]:
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:
        raise ValueError
    flags = load_flags(flags_path)
    try:
        count = int(subprocess.run(['wc', '-l', events_path], capture_output=True, text=True, check=True).stdout.split()[0])
        with open(events_path, encoding='utf-8') as f:
            counts = {k: [0, 0] for k in flags}
            for line in f:
                if not line.strip():
                    continue
                event = json.loads(line)
                if not isinstance(event, dict) or not isinstance(event.get('flag'), str) or (not isinstance(event.get('user'), str)) or (not isinstance(event.get('value'), bool)):
                    raise ValueError
                if event['flag'] in counts:
                    counts[event['flag']][0] += 1
                    counts[event['flag']][1] += int(event['value'])
    except (OSError, ValueError, TypeError, KeyError, json.JSONDecodeError, subprocess.SubprocessError, IndexError) as e:
        raise ValueError from e
    result = [{'flag': k, 'total': v[0], 'enabled': v[1], 'rate': round(v[1] / v[0], 4)} for k, v in counts.items() if v[0]]
    result.sort(key=lambda x: (-x['total'], x['flag']))
    return result[:limit]

