import re
import secrets

def issue_sample_codes(site: str, count: int) -> list[str]:
    if not isinstance(site, str) or re.fullmatch('[A-Za-z0-9]{2,12}', site) is None:
        raise ValueError('invalid site')
    if not isinstance(count, int) or isinstance(count, bool) or (not 0 <= count <= 100):
        raise ValueError('invalid count')
    alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    result = []
    while len(result) < count:
        token = ''.join((secrets.choice(alphabet) for _ in range(10)))
        code = f'FS-{site.upper()}-{token}'
        if code not in result:
            result.append(code)
    return result

def summarize_samples(records: list[dict], limit: int=3) -> dict:
    if not isinstance(records, list):
        raise ValueError('invalid records')
    if not isinstance(limit, int) or isinstance(limit, bool) or (not 1 <= limit <= 10):
        raise ValueError('invalid limit')
    seen = set()
    counts = {'passed': 0, 'failed': 0, 'pending': 0}
    high = []
    total_risk = 0
    for record in records:
        if not isinstance(record, dict) or set(record) != {'sample_id', 'status', 'risk_score'}:
            raise ValueError('invalid record')
        sample_id = record['sample_id']
        status = record['status']
        score = record['risk_score']
        if not isinstance(sample_id, str) or not sample_id or sample_id in seen:
            raise ValueError('invalid sample id')
        if status not in counts or isinstance(score, bool) or (not isinstance(score, (int, float))) or (not 0 <= score <= 100):
            raise ValueError('invalid record values')
        seen.add(sample_id)
        counts[status] += 1
        total_risk += score
        if score >= 70:
            high.append((score, sample_id))
    high.sort(key=lambda item: (-item[0], item[1]))
    return {'total': len(records), **counts, 'average_risk': round(total_risk / len(records), 2) if records else 0.0, 'high_risk_samples': [item[1] for item in high[:limit]]}

