import os
from pathlib import Path

def invalidate_cache(base_dir: str, relative_name: str) -> bool:
    if not relative_name or os.path.isabs(relative_name):
        raise ValueError('relative_name must be a non-empty relative path')
    base = Path(base_dir)
    if not base.exists():
        raise FileNotFoundError(base_dir)
    if not base.is_dir():
        raise NotADirectoryError(base_dir)
    base_resolved = base.resolve()
    target = (base / relative_name).resolve()
    try:
        target.relative_to(base_resolved)
    except ValueError:
        raise ValueError('path is outside the cache directory')
    if not target.exists():
        return False
    if target.is_dir():
        raise IsADirectoryError(str(target))
    target.unlink()
    return True

