def _date(value):
    try:
        return datetime.fromisoformat(value.replace('Z', '+00:00')).astimezone(timezone.utc)
    except Exception as exc:
        raise ValueError('invalid date') from exc

def parse_rotation_feed(document: str) -> list[dict]:
    try:
        parser = etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False)
        root = etree.fromstring(document.encode(), parser)
    except Exception as exc:
        raise ValueError('invalid xml') from exc
    if root.tag != 'rotation-feed':
        raise ValueError('invalid root')
    result = []
    seen = set()
    for secret in root:
        if secret.tag != 'secret':
            raise ValueError('invalid element')
        sid, owner = (secret.get('id'), secret.get('owner'))
        if not sid or not owner or sid in seen:
            raise ValueError('invalid secret')
        seen.add(sid)
        versions = []
        for version in secret:
            if version.tag != 'version':
                raise ValueError('invalid element')
            vid, created, state = (version.get('id'), version.get('created'), version.get('state'))
            checksum = (version.text or '').strip()
            if not vid or not created or state not in {'active', 'staged', 'retired'} or (not checksum):
                raise ValueError('invalid version')
            _date(created)
            if vid in versions:
                raise ValueError('duplicate version')
            versions.append(vid)
            result.append({'secret_id': sid, 'owner': owner, 'version_id': vid, 'created': created, 'state': state, 'checksum': checksum})
        if not versions:
            raise ValueError('missing versions')
    result.sort(key=lambda x: (x['secret_id'], _date(x['created']), x['version_id']))
    return result

