        if len(row) != 5 or row[0] != turbine or (not row[4]):
            if len(row) == 5 and row[0] != turbine:
                continue
            raise ValueError('invalid record')
        try:
            datetime.date.fromisoformat(row[1])
            hours = float(row[2])
            priority = int(row[3])
        except (ValueError, TypeError):
            raise ValueError('invalid record')
        if hours <= 0:
            raise ValueError('invalid record')
        result.append({'turbine': row[0], 'date': row[1], 'hours': hours, 'priority': priority, 'task': row[4]})
    result.sort(key=lambda x: (x['date'], -x['priority'], x['task']))
    return result

def build_schedule(path: str, turbines: list[str], start: str, end: str, max_hours: float=8.0) -> list[dict]:
    try:
        begin = datetime.date.fromisoformat(start)
        finish = datetime.date.fromisoformat(end)
    except ValueError:
        raise ValueError('invalid date')
    if begin > finish or max_hours <= 0:
        raise ValueError('invalid range')
    names = list(dict.fromkeys(turbines))
    records = {name: read_maintenance(path, name) for name in names}
    out = []
    current = begin
    while current <= finish:
        stamp = current.isoformat()
        for name in names:
            selected = [r for r in records[name] if r['date'] == stamp]
            if selected:
                total = round(sum((r['hours'] for r in selected)), 2)
                if total > max_hours:
                    raise ValueError('capacity exceeded')
                selected.sort(key=lambda r: (-r['priority'], r['task']))
                out.append({'date': stamp, 'turbine': name, 'hours': total, 'tasks': [r['task'] for r in selected]})
        current += datetime.timedelta(days=1)
    return out

def render_schedule(rows: list[dict]) -> str:
    text = 'DATE\tTURBINE\tHOURS\tTASKS\n'
    for row in rows:
        text += f"{row['date']}\t{row['turbine']}\t{row['hours']:.2f}\t{';'.join(row['tasks'])}\n"
    return text

